def _extract_request_keywords(ds):
    """Extract keyword set from a pydicom Dataset (excludes SQ elements)."""
    keywords = set()
    for elem in ds:
        if elem.VR != "SQ" and elem.keyword:
            keywords.add(elem.keyword)
    return keywords

def _iter_mwl_request_elements(ds):
    """Yield the C-FIND MWL identifier elements, top level and SPS item.

    A conformant MWL request carries its SPS matching and return keys INSIDE
    the single item of (0040,0100) Scheduled Procedure Step Sequence - that is
    where (0040,0001) ScheduledStationAETitle and (0040,0009) SPS ID live
    (PS3.4 Table K.6-1). A flat request that puts them at the top level is also
    accepted: older senders do it and the standard's sequence matching is
    satisfied either way.

    Top-level elements come first, so a value stated both ways resolves to the
    top-level one.
    """
    for elem in ds:
        if elem.VR != "SQ":
            yield elem
    for elem in ds:
        if elem.VR != "SQ" or elem.keyword != "ScheduledProcedureStepSequence":
            continue
        items = elem.value or []
        if not items:
            continue
        # Single Item only (Table K.6-1). A sender that breaks the rule gets
        # its first item read rather than an error: the response is one row per
        # SPS, and there is exactly one SPS to answer for.
        for item in items[:1]:
            for sub in item:
                if sub.VR != "SQ":
                    yield sub

def _extract_mwl_request_keywords(ds):
    """Request keywords for an MWL C-FIND: top level PLUS the (0040,0100) item.

    A modality asks for an Optional key by naming it in the identifier, and the
    SPS-level keys it may ask for live inside the sequence. Flat top-level
    keywords are kept too, so both request shapes work.
    """
    keywords = set()
    for elem in _iter_mwl_request_elements(ds):
        if elem.keyword:
            keywords.add(elem.keyword)
    return keywords

def _build_qido_params(ds):
    """Build QIDO-RS query parameters from a pydicom Dataset.

    Maps C-FIND keywords to QIDO query parameters.
    None and empty-after-strip values are skipped for ALL VRs (DICOMweb:
    absent parameter = match all). Field bug 31.08: an empty IS
    (SeriesNumber) decoded by pydicom to None was stringified to "None"
    and sent to the server, which answered 400.
    Non-empty values pass through as-is (server handles DICOM `*`/`?`
    wildcards).
    """
    params = {}
    for elem in ds:
        if elem.VR == "SQ":
            continue
        keyword = elem.keyword
        if keyword in C_FIND_TO_QIDO:
            if elem.value is None:
                continue
            # Multi-valued matching (a MultiValue) is a LIST of alternatives:
            # `str()` on one produces "['CT', 'MR']", which the server reads as
            # a single unmatched value and answers with zero matches. PS3.18
            # 10.6 defines the query syntax as comma-separated, so the
            # alternatives are joined that way.
            if isinstance(elem.value, (list, tuple, MultiValue)):
                val = ",".join(str(item).strip() for item in elem.value if item)
            else:
                val = str(elem.value).strip()
            # Skip empty values  -  DICOMweb convention: absent = match all
            if val:
                params[C_FIND_TO_QIDO[keyword]] = val
    return params

def _split_qido_params(ds):
    """Split a C-FIND identifier into (study_params, series_params).

    Server contract (qido_pure.rs foreign_keys, 31.08):
    - GET /studies rejects series-only keys with 400;
    - GET /studies/{study}/series accepts ONLY series keys + Modality
      (PatientName/PatientID/StudyInstanceUID are foreign there).
    Modality is legal at BOTH levels; it goes to the SERIES step only:
    the study-level Modality filter matches the study's first-series
    modality (documented server deviation) and could wrongly exclude a
    study whose later series carries the modality.
    """
    all_params = _build_qido_params(ds)
    study_params = {}
    series_params = {}
    for key, val in all_params.items():
        if key in _SERIES_ONLY_QIDO_PARAMS or key == "Modality":
            series_params[key] = val
        else:
            study_params[key] = val
    return study_params, series_params

def _split_instance_qido_params(ds):
    """Split an IMAGE-level C-FIND identifier into study/series/instance params.

    Returns `(study_params, series_params, instance_params)` for the three QIDO
    hops of an IMAGE-level query (PS3.4 C.4.1.3.1.1: match down the hierarchy
    from the top level to the level named by QueryRetrieveLevel).

    Three keys need care because the server scopes them to particular routes
    (qido_pure.rs `parse_and_validate`):

    - `Modality` is legal at the instance route but is a SERIES key in this
      query (a C-FIND IMAGE request states it to narrow the walk, and the
      series step applies it), so it stays on the series hop.
    - `SeriesInstanceUID` is a series key everywhere except the instance
      route, where it is foreign; it narrows the series hop and the instance
      rows are already scoped to that one series.
    - `SOPInstanceUID`, `SOPClassUID` and `InstanceNumber` are instance keys
      the series route rejects with 400, so they never travel with the series
      parameters.
    """
    all_params = _build_qido_params(ds)
    study_params = {}
    series_params = {}
    instance_params = {}
    for key, val in all_params.items():
        if key in _INSTANCE_ONLY_QIDO_PARAMS:
            instance_params[key] = val
        elif key in _SERIES_ONLY_QIDO_PARAMS or key == "Modality":
            series_params[key] = val
        else:
            study_params[key] = val
    return study_params, series_params, instance_params

# MWL (Modality Worklist) <-> UPS-RS workitem DICOMweb JSON keys.
#
# PS3.4 2026d Table K.6-1: the Modality Worklist Information Model is a FLAT,
# NON-OBJECT model - it has no SOP Common attributes, so SOP Instance UID
# (0008,0018) has no place in a response. The modality's identity for a
# Scheduled Procedure Step is (0040,0009) SPS ID plus (0040,1001) Requested
# Procedure ID, and the SPS attributes themselves live INSIDE the single item
# of (0040,0100) Scheduled Procedure Step Sequence:
#
#   "The Scheduled Procedure Step Sequence shall contain only a single Item."
#
# RETURN keys are emitted whenever the source has a value, whether the modality
# asked or not. OPTIONAL keys are emitted ONLY when the modality requested them
# (PS3.4 C.4.1.1.3.2), which is how a modality says "give me this key".
#
# Sources are the server's workitem render (handlers/ups/json.rs). The keys the
# server does not render simply produce nothing - an absent Return key, not a
# fabricated one. This is a documented VENDOR mapping: no normative DICOM or
# IHE mapping from UPS workitems to a DIMSE MWL response exists, so the derived
# identifiers below are the bridge's own, declared in
# dimse-bridge-conformance-statement.md.

# Top level. PatientName/PatientID are Return keys (Type 1) at identifier
# level; the rest are Optional and request-gated.
MWL_RETURN_TOP = {
    "00100010": (0x0010, 0x0010, "PN", "PatientName"),
    "00100020": (0x0010, 0x0020, "LO", "PatientID"),
}

MWL_OPTIONAL_TOP = {
    "00080050": (0x0008, 0x0050, "SH", "AccessionNumber"),
    "0020000D": (0x0020, 0x000D, "UI", "StudyInstanceUID"),
    "00321032": (0x0032, 0x1032, "PN", "RequestingPhysician"),
}

# The two Optional top-level keys whose UPS source moved into a sequence: the
# study and the accession are carried by (0040,A370) Referenced Request
# Sequence (PS3.4 Table CC.2.5-3). The bare top-level tag is a fallback for a
# server that still emits it (and the (0040,4021) Input Information Sequence
# names the study too), so a row is rendered whether the source is old or new.
MWL_OPTIONAL_TOP_SEQ = {
    "0020000D": ("0040A370", "0020000D"),
    "00080050": ("0040A370", "00080050"),
}

# The station source that moved into a sequence, resolved BEFORE the flat fill
# runs: UPS carries the station in (0040,4025) Scheduled Station Name Code
# Sequence, whose Code Value is the AE Title (PS3.4 Table CC.2.5-3; AIW-I
# 4.81.4.1.2.1 Table 4.81.4.1.2.1-3). The emitted MWL element stays
# (0040,0001) ScheduledStationAETitle, because that is the attribute Table
# K.6-1 defines for the DIMSE side - only the SOURCE changes.
MWL_STATION_SEQ = ("00404025", "00080100")

# Inside the single item of (0040,0100) Scheduled Procedure Step Sequence.
MWL_RETURN_SPS = {
    "00400001": (0x0040, 0x0001, "AE", "ScheduledStationAETitle"),
    "00400002": (0x0040, 0x0002, "DA", "ScheduledProcedureStepStartDate"),
    "00400003": (0x0040, 0x0003, "TM", "ScheduledProcedureStepStartTime"),
    # (0008,0060) Modality is a Return key Type 1 in MWL. UPS itself has no
    # Modality attribute (PS3.4 Table CC.2.5-3); the server renders the input
    # study's Modality as a documented vendor extension, and the bridge maps it
    # here. While a deployment's server does not render it, the key is simply
    # absent for every workitem - which is the same shape as any other absent
    # Return key, not a special case.
    "00080060": (0x0008, 0x0060, "CS", "Modality"),
}

MWL_OPTIONAL_SPS = {
    "00400010": (0x0040, 0x0010, "SH", "ScheduledStationName"),
}

# (0074,1200) ScheduledProcedureStepPriority is deliberately NOT here: it is an
# attribute of the UPS Scheduled Procedure Step Module (PS3.3 C.30.1) and has
# no row in Table K.6-1, so it must not appear in an MWL response.
#
# (0040,0006) ScheduledPerformingPhysicianName is a Return key Type 2 with no
# UPS source. Type 2 permits absence, so it is omitted rather than invented.

# SPS ID (0040,0009) / Requested Procedure ID (0040,1001) are derived, not
# mapped: see _mwl_sps_id / _mwl_rp_id.
MWL_SPS_ID_LEN = 16

# C-FIND MWL match keyword -> UPS-RS workitems query parameter.
# Only the keys the server's workitem search actually filters on (ups/types.rs
# parse_form_query / StoreFilter): station_aet, modality, patient_id,
# workitem_uid, workflow_state. Other MWL keys are NOT filterable server-side
# -> absent parameter = match all (DICOMweb convention).
MWL_TO_UPS_PARAM = {
    "ScheduledStationAETitle": "00404025.00080100",
    "Modality": "00080060",
    "PatientID": "00100020",
    "StudyInstanceUID": "0020000D",
    "ProcedureStepState": "00741000",
    "ScheduledProcedureStepStartDate": "00404005",
}

# PS3.4 Table K.6-1 (standard/ps3.4/mwl-k.6-1-matching-keys.json) makes
# Scheduled Procedure Step Start Time (0040,0003) a REQUIRED matching key of
# the SPS item, with the rule "Single Value or Range". Omitting it turned a
# 09:00-10:00 query into "match all": the bridge returned a 14:00 workitem
# alongside the 09:30 one. It has no separate UPS parameter - the origin filters
# on the combined workitem start instant (0040,4005) - so the time is folded
# into that value together with the date.
MWL_START_TIME_KEYWORD = "ScheduledProcedureStepStartTime"

# PS3.4 Table K.6-1 lists Scheduled Performing Physician's Name (0040,0006) as
# a matching key with the rule "Single Value or Wildcard". The UPS-RS workitem
# search exposes no parameter for it, so it cannot be pushed to the origin -
# but dropping it made the request match ALL workitems and a Jones procedure
# came back for a `Smith*` query. It is carried here and applied as a local
# wildcard filter over the response rows.
MWL_PHYSICIAN_KEYWORD = "ScheduledPerformingPhysicianName"

def _mwl_physician_matchers(ds):
    """The Scheduled Performing Physician patterns the request asked for.

    PS3.4 Table K.6-1 gives (0040,0006) the rule "Single Value or Wildcard",
    where the wildcard is `*` (PS3.4 C.2.2.2.4) and `?` matches one character.
    Each value is compiled once here, as a case-insensitive full match, and
    shared by every candidate row.

    Returns an empty tuple when the request states no physician, so the caller
    skips the filter entirely.
    """
    import re as _re

    patterns = []
    for elem in _iter_mwl_request_elements(ds):
        if elem.keyword != MWL_PHYSICIAN_KEYWORD:
            continue
        if elem.value is None:
            continue
        raw_values = (
            elem.value
            if isinstance(elem.value, (list, tuple, MultiValue))
            else [elem.value]
        )
        for raw in raw_values:
            pattern = str(raw or "").strip()
            if not pattern:
                continue
            # `*` is any run and `?` exactly one character (PS3.4 C.2.2.2.4).
            # Everything else is literal, so the value is quoted and only the
            # two wildcard characters are translated - a name containing a
            # regex metacharacter must not become a pattern.
            translated = "".join(
                ".*" if ch == "*" else "." if ch == "?" else _re.escape(ch)
                for ch in pattern
            )
            try:
                patterns.append(_re.compile(rf"\A{translated}\Z", _re.IGNORECASE))
            except _re.error:
                # An unparseable pattern cannot be honoured; keeping it would
                # reject every row for a request the origin already answered.
                continue
    return tuple(patterns)

def _mwl_physician_matches(stored, matchers):
    """Whether a stored physician name satisfies at least one request pattern.

    A row that carries no physician is KEPT: Type 2 permits an absent value,
    and absence is not proof that the name differs from the query. A request
    that states no physician (no matchers) keeps everything.
    """
    if not matchers:
        return True
    text = str(stored or "").strip()
    if not text:
        return True
    return any(m.match(text) for m in matchers)

def _mwl_start_datetime_bounds(ds):
    """The SPS start DATE+TIME window the request asks for, or None.

    PS3.4 Table K.6-1 defines (0040,0002) Start Date and (0040,0003) Start
    Time as separate matching keys, but they describe ONE interval: July 5-7
    at 10:00-18:00 includes a July 6 workitem at 22:00, because the time-of-day
    window applies inside the date range, not on top of it. Filtering each key
    independently dropped that workitem - the date query fetched it, then the
    time-of-day filter discarded it because 22:00 is outside 10:00-18:00.

    The combined window is expressed as an inclusive (low_dt, high_dt) pair of
    YYYYMMDDHHMMSS strings so a stored (0040,4005) instant compares by plain
    string ordering. A blank bound means unbounded on that side.

    Returns None when the request states no date/time window at all, so the
    caller skips local filtering entirely.
    """
    date_bounds = None
    time_bounds = None
    for elem in _iter_mwl_request_elements(ds):
        if elem.keyword == "ScheduledProcedureStepStartDate" and date_bounds is None:
            date_bounds = _mwl_date_bounds(elem.value)
        elif elem.keyword == MWL_START_TIME_KEYWORD and time_bounds is None:
            time_bounds = _mwl_time_bounds(elem.value)
    if date_bounds is None and time_bounds is None:
        return None

    d_lo, d_hi = date_bounds if date_bounds is not None else ("", "")
    t_lo, t_hi = time_bounds if time_bounds is not None else ("", "")

    if not d_lo and not d_hi:
        # TIME-ONLY request: the modality asked for a time of day on any
        # date, so only the HHMMSS component is comparable. Returning
        # date-prefixed bounds here would compare "2026..." against a bare
        # "090000" and reject every row.
        return ("T", t_lo, t_hi)

    # Each side is built from the SAME kind of bound: a single date with a
    # A date range with a time range is "EACH DAY in the range, WITHIN those
    # hours" - not one continuous span from the first evening to the last.
    # Concatenating the bounds (20260705210000..20260707230000) made a July 6
    # workitem at 10:00 match a 21:00-23:00 request, because 10:00 on July 6
    # lies between the two endpoints. The window is therefore carried as
    # three parts: the date span, and the time-of-day span applied inside it.
    if t_lo or t_hi:
        return ("DR", d_lo, d_hi, t_lo, t_hi)
    # Date only: the whole day, every day in the range.
    return ("D", d_lo, d_hi, "", "")

def _mwl_datetime_in_bounds(stored, bounds):
    """Whether a stored (0040,4005) instant lies inside a combined window.

    PS3.4 Table K.6-1 defines (0040,0002) Start Date and (0040,0003) Start
    Time as ONE interval: the date range selects the days, and the time range
    selects the hours WITHIN each of those days. July 5-7 at 21:00-23:00
    therefore includes a July 6 workitem at 22:00 and excludes one at 10:00,
    whereas comparing a single concatenated span accepted both.

    A TIME-ONLY request compares the HHMMSS component alone, because its
    bounds carry no date. A row without the attribute is kept: absence is not
    a proven mismatch.
    """
    if bounds is None:
        return True
    text = str(stored or "").strip()
    if len(text) < 8:
        return True
    # Pad the stored instant to the compared precision; a date-only stored
    # value compares as the start of that day.
    stamp = (text + "00000000000000")[:14]
    kind = bounds[0]
    if kind == "T":
        _, low, high = bounds
        hhmmss = stamp[8:14]
        if low and hhmmss < low:
            return False
        if high and hhmmss > high:
            return False
        return True
    _, d_lo, d_hi, t_lo, t_hi = bounds
    day = stamp[:8]
    # The DAY must be in the requested date range ...
    if d_lo and day < d_lo:
        return False
    if d_hi and day > d_hi:
        return False
    # ... and the TIME OF DAY inside that day must be in the time range.
    hhmmss = stamp[8:14]
    if t_lo and hhmmss < t_lo:
        return False
    if t_hi and hhmmss > t_hi:
        return False
    return True

def _mwl_time_bounds(value):
    """A (0040,0003) TM match value as an inclusive ``(low, high)`` HHMMSS pair.

    PS3.5 6.2 allows the short forms ``HH``, ``HHMM`` and ``HHMMSS``, and PS3.4
    Table K.6-1 gives this key the rule "Single Value or Range". Both are
    normalised to the six-digit form so a comparison against a stored time is
    plain string ordering:

      - ``0900``          -> ('090000', '090000')
      - ``090000-100000`` -> ('090000', '100000')
      - ``-100000``       -> ('', '100000')   (unbounded below)

    Returns None when the value cannot be read, so the caller can decide
    without guessing.
    """

    def _hm(part):
        part = part.strip()
        if not part:
            return None
        # PS3.5 6.2: TM is HH, HHMM or HHMMSS, each optionally followed by
        # `.FFFFFF` fractional seconds. The fraction was rejected outright,
        # so `093000.25-093000.75` - a legal range - yielded no bounds at all
        # and the request ran WITHOUT a time filter, returning a 14:00
        # workitem for a 09:30 request. The fraction is kept as its own
        # six-digit string so the comparison stays plain string ordering
        # against a stored instant that carries the same precision.
        #
        # The dot is split off FIRST: testing the whole component with
        # `isdigit()` rejected every fractional value before the split could
        # happen, which is the defect this branch exists to fix.
        whole, _, frac = part.partition(".")
        if not whole.isdigit() or len(whole) not in (2, 4, 6):
            return None
        if frac and not frac.isdigit():
            return None
        return (whole + "000000")[:6]

    text = str(value or "").strip()
    if not text:
        return None
    if "-" in text:
        low, _, high = text.partition("-")
        lo, hi = _hm(low), _hm(high)
        if lo is None and hi is None:
            return None
        return (lo or "", hi or "")
    single = _hm(text)
    if single is None:
        return None
    return (single, single)

def _mwl_date_bounds(value):
    """A (0040,0002) DA match value as an inclusive ``(low, high)`` YYYYMMDD pair.

    PS3.4 Table K.6-1 gives the key the rule "Single Value or Range", and
    PS3.5 6.2 allows the ``YYYY.MM.DD`` form. Both are normalised to the
    eight-digit dotted-free form so a comparison against a stored date is plain
    string ordering:

      - ``20260706``              -> ('20260706', '20260706')
      - ``20260705-20260707``     -> ('20260705', '20260707')
      - ``-20260707``             -> ('', '20260707')   (unbounded below)

    Returns None when the value cannot be read, so the caller decides without
    guessing.
    """

    def _day(part):
        part = part.strip().replace(".", "")
        if not part or not part.isdigit() or len(part) != 8:
            return None
        return part

    text = str(value or "").strip()
    if not text:
        return None
    if "-" in text:
        low, _, high = text.partition("-")
        lo, hi = _day(low), _day(high)
        if lo is None and hi is None:
            return None
        return (lo or "", hi or "")
    single = _day(text)
    if single is None:
        return None
    return (single, single)

def _mwl_time_in_bounds(stored, bounds):
    """Whether a stored (0040,4005) instant satisfies an SPS start-time range.

    The origin filters on the full instant; the modality expressed an interest
    in a TIME OF DAY. This applies that part of the matching locally, before
    the response limit, so a workitem outside the requested window never
    consumes a Pending response.
    """
    if bounds is None:
        return True
    low, high = bounds
    text = str(stored or "").strip()
    if len(text) < 8:
        return True
    # (0040,4005) DT: YYYYMMDDHHMMSS...; the time component starts at index 8.
    hhmmss = (text[8:14] + "000000")[:6]
    if low and hhmmss < low:
        return False
    if high and hhmmss > high:
        return False
    return True

def _mwl_date_to_ups_datetime(value):
    """Map a (0040,0002) DA match value onto the (0040,4005) DT grammar.

    MWL matches a DATE; UPS stores a DATETIME. The server compares the query
    value against the stored DT with string semantics inside an inclusive
    range (`<lo>-<hi>`), so:
      - `YYYYMMDD`        -> `YYYYMMDD000000-YYYYMMDD235959` (the whole day)
      - `YYYYMMDD-YYYYMMDD` -> `YYYYMMDD000000-YYYYMMDD235959`
      - a DT-shaped value is passed through untouched (some senders fill the
        DA key with the full instant).
    An unusable value is returned unchanged: a filter that cannot be built is
    not a reason to widen the search silently, and the server answers the
    unchanged form as it always has.
    """
    text = str(value or "").strip()
    if not text:
        return ""

    def _day(part):
        part = part.strip()
        return part if len(part) == 8 and part.isdigit() else None

    if "-" in text:
        low, _, high = text.partition("-")
        lo, hi = _day(low), _day(high)
        # Open-ended ranges keep their open end (the server treats an empty
        # bound as unbounded). The two bounds are built INDEPENDENTLY: emitting
        # the lower bound as a literal `000000` turned `-20261121` ("everything
        # up to that day") into `000000-20261121235959`, which silently
        # narrowed an unbounded window to one starting at midnight - the exact
        # opposite of what the modality asked.
        if lo is None and hi is None:
            return text
        lower = f"{lo}000000" if lo else ""
        # PS3.5 6.2: DT may carry fractional seconds. `{day}235959` is the
        # INSTANT 23:59:59, so a workitem scheduled at `{day}235959.500` sorts
        # AFTER it and a single-day query silently omitted the last 999 ms of
        # the day. The bound is the end of the final second, expressed with the
        # maximum fraction so every instant inside 23:59:59 compares below it.
        upper = f"{hi}235959.999999" if hi else ""
        return f"{lower}-{upper}"
    day = _day(text)
    if day is None:
        return text
    return f"{day}000000-{day}235959.999999"

def _mwl_start_time_bounds(ds):
    """The SPS start-time range the request asks for, or None.

    Read from the same two levels `_build_mwl_params` reads: the top level and
    the single item of (0040,0100). First statement wins, matching that
    function's rule so the two cannot disagree about which value applies.
    """
    for elem in _iter_mwl_request_elements(ds):
        if elem.keyword != MWL_START_TIME_KEYWORD:
            continue
        if elem.value is None:
            continue
        bounds = _mwl_time_bounds(elem.value)
        if bounds is not None:
            return bounds
        return None
    return None

def _build_mwl_params(ds):
    """Build UPS-RS workitems query params from a C-FIND MWL request Dataset.

    Reads the matching keys from BOTH the top level and the item of
    (0040,0100) Scheduled Procedure Step Sequence, because that is where a
    conformant MWL request puts them. A nested-only request used to yield an
    empty dict - i.e. match-all - so the modality's station filter silently
    returned every workitem on the server.

    Maps only the keys the server's workitem search filters on; empty values
    are skipped (absent = match all, the DICOMweb convention). Returns a dict
    (possibly empty).
    """
    params = {}
    for elem in _iter_mwl_request_elements(ds):
        keyword = elem.keyword
        if keyword not in MWL_TO_UPS_PARAM:
            continue
        param = MWL_TO_UPS_PARAM[keyword]
        if param in params:
            # Already stated at an earlier level (top level precedes the SPS
            # item). First statement wins, so the resolution does not depend on
            # element order inside the sequence.
            continue
        # PS3.18 10.6: the query syntax is comma-separated for a list of
        # alternatives, and `str()` on a MultiValue yields "['CT', 'MR']" -
        # which the server reads as one unmatched value. An element with no
        # value is skipped rather than sent as the text "None".
        if elem.value is None:
            continue
        if isinstance(elem.value, (list, tuple, MultiValue)):
            val = ",".join(str(item).strip() for item in elem.value if item)
        else:
            val = str(elem.value).strip()
        if val:
            if keyword == "ScheduledProcedureStepStartDate":
                val = _mwl_date_to_ups_datetime(val)
            params[param] = val
    return params

def _json_pn_to_dimse(raw):
    """A DICOMweb JSON Person Name back to its DIMSE `Alphabetic=Ideographic=Phonetic` form.

    PS3.18 F.2.2 gives each populated component group its OWN property. Reading
    only `Alphabetic` therefore dropped every non-alphabetic name: a PN whose
    answer carried only `Ideographic` became the empty string, so the modality
    received a nameless patient - and a PN with an ideographic part lost it.
    The three groups are rejoined with the `=` separator in the order the VR
    defines (PS3.5 6.2), preserving EMPTY leading groups so the modality can
    still tell which group a value belongs to.
    """
    if not isinstance(raw, dict):
        return str(raw)
    groups = [
        str(raw.get("Alphabetic", "") or ""),
        str(raw.get("Ideographic", "") or ""),
        str(raw.get("Phonetic", "") or ""),
    ]
    # Trailing empty groups are the default and carry no information, so only
    # the populated span up to the last non-empty group is emitted. An entirely
    # empty name stays an empty value rather than "==".
    while groups and not groups[-1]:
        groups.pop()
    return "=".join(groups)

def _safe_add_new(ds, group, elem, vr, val):
    """Add element to Dataset; fall back to direct assignment if tag exists (BR-014)."""
    try:
        ds.add_new((group, elem), vr, val)
    except ValueError:
        ds[(group, elem)] = DataElement((group, elem), vr, val)

def _json_add_vr(ds, group, elem, vr, raw_value):
    """Add one DICOMweb JSON value to `ds` under the element's VR (CMP-005).

    The single place a JSON value becomes a pydicom element, shared by the
    QIDO and MWL converters so the two cannot drift on VR handling. Returns
    True when the element was added.

    `raw_value` is the whole DICOMweb `Value` array (already checked non-empty
    by the caller). CS, UI and SH are value-multiplicity VRs (PS3.5 Table
    6.2-1): ModalitiesInStudy (0008,0061) legitimately carries several CS
    values, and taking `Value[0]` reported one modality for a study performed
    on three. Rendering the array with `str()` would be no better - the SCU
    would read "['CT', 'MR']" as a single value.

    A JSON `null` inside `Value` is an ABSENT value, not the text "None":
    `["CT", null]` stringified the null into five characters that then
    travelled to the SCU as a modality. Nulls are dropped before conversion;
    an array of nothing but nulls carries no value at all and is not added.
    """
    try:
        items = [v for v in raw_value if v is not None]
        if not items:
            return False
        if vr in ("CS", "UI", "SH") and len(items) > 1:
            val = [str(item) for item in items]
        else:
            raw_first = items[0]
            if vr == "PN":
                val = _json_pn_to_dimse(raw_first)
            elif vr == "IS":
                val = int(raw_first)
            elif vr == "TM":
                # Time: normalize the display "HH:MM:SS" form to the canonical
                # DICOM "HHMMSS.FFFFFF" (PS3.5 6.2). pydicom logs
                # "Invalid value for VR TM: '11:25:01'" when a colon form is
                # constructed (field noise on every C-FIND); stripping the
                # colons keeps the attribute valid and warning-free.
                val = str(raw_first).replace(":", "")
            else:
                # LO, DA - plain string.
                val = str(raw_first)
    except (TypeError, ValueError, IndexError):
        return False
    _safe_add_new(ds, group, elem, vr, val)
    return True

def _json_map_to_dataset(json_obj, keymap):
    """Convert a DICOMweb JSON object to a pydicom Dataset (shared core).

    Handles VR-aware parsing for PN/IS/CS/UI/LO/SH/DA/TM (CMP-005).

    The C-FIND response re-emits the 16 mapped attributes on every row;
    PS3.4 C.4.1.1.3.2 says the response shall not contain attributes that
    were not in the request or specified in that section - this is a
    deliberate, viewer-tolerated deviation (documented in the DIMSE bridge
    conformance statement).
    """
    ds = Dataset()
    # PS3.5 6.1.2: SpecificCharacterSet MUST be the first element.
    # ISO_IR 192 (UTF-8) is ALWAYS set, deliberately (documented in the DIMSE
    # bridge conformance statement): without it pydicom defaults to iso8859 /
    # Latin-1 and replaces Cyrillic PN/LO with '????' in RadiAnt/MicroDICOM.
    # The charset covers Cyrillic and all other scripts in the bridge rows.
    ds.SpecificCharacterSet = "ISO_IR 192"

    for json_key, value in json_obj.items():
        if json_key not in keymap:
            continue
        group, elem, vr, dicom_keyword = keymap[json_key]
        raw_value = value.get("Value", []) if isinstance(value, dict) else []
        if not raw_value:
            # Zero-length delta (documented in the DIMSE bridge conformance
            # statement): an attribute that is present but EMPTY is dropped,
            # i.e. the attribute is ABSENT from the row, NOT emitted as a
            # zero-length value. PS3.4 C.4.1.1.3.2 note 2 would require a
            # zero-length attribute; we deliberately do not do that (keeps
            # the rows minimal and is tolerated by all viewers).
            continue
        _json_add_vr(ds, group, elem, vr, raw_value)
    return ds

def _json_to_dataset(json_obj, request_keywords):
    """QIDO-RS study JSON -> pydicom Dataset (13/13 QIDO attributes)."""
    return _json_map_to_dataset(json_obj, QIDO_KEY_TO_TAG)

# PS3.4 C.6.1.1.2 Table C.6-1 (standard/ps3.4/patient-root-levels-C.6-1.json)
# fixes exactly these attributes at the Patient level of the Patient Root
# model. PatientName is the level's Type R key; the rest are optional, and
# QIDO_KEY_TO_TAG already maps all four, so no new tag knowledge is needed -
# the table only decides WHICH of the study row's attributes survive the fold.
PATIENT_LEVEL_KEYS = ("00100010", "00100020", "00100030", "00100040")

def _json_to_dataset_patient(json_obj):
    """QIDO-RS study JSON -> a Patient-level Dataset (PS3.4 Table C.6-1).

    Patient level is served from the study query: the origin's study row
    carries the patient attributes, so the fold is a projection, not a
    separate lookup. Keys outside Table C.6-1 are dropped - a Patient-level
    row that also carried StudyDate or StudyInstanceUID would tell the SCU
    the level is actually a study level with a relabelled (0008,0052).
    """
    return _json_map_to_dataset(
        json_obj, {k: QIDO_KEY_TO_TAG[k] for k in PATIENT_LEVEL_KEYS}
    )

def _json_first_value(json_obj, key):
    """First DICOMweb JSON Value entry for `key` ('' when absent).

    PN values arrive as {"Alphabetic": ...} objects; everything else as
    plain strings/numbers.

    A JSON null (or an empty list) means the attribute carries NO value, and
    returns None rather than the string "None": `str(None)` is a plausible
    looking token that then travels as a UID.
    """
    attr = json_obj.get(key) or {}
    values = attr.get("Value") or []
    if not values:
        return ""
    first = values[0]
    if first is None:
        return None
    if isinstance(first, dict):
        return str(first.get("Alphabetic", ""))
    return str(first)

def _json_seq_first_value(json_obj, seq_key, item_key):
    """First value of `item_key` inside the FIRST item of sequence `seq_key`.

    The UPS workitem render carries the study and the accession through
    (0040,A370) Referenced Request Sequence (PS3.4 Table CC.2.5-3), so a
    consumer that wants the input study reads it there. '' when the sequence,
    the item or the tag is absent.
    """
    seq = json_obj.get(seq_key) or {}
    items = seq.get("Value") or []
    if not items or not isinstance(items[0], dict):
        return ""
    return _json_first_value(items[0], item_key)

def _json_workitem_study_uid(json_obj):
    """The input study UID of a UPS workitem JSON, from either carriage.

    (0040,A370) Referenced Request Sequence is the standard carriage and is
    read first; the bare top-level (0020,000D) is the fallback for a server
    (or a stored row) that still emits it, and the (0040,4021) Input
    Information Sequence is the last resort. The three name one fact.
    """
    study = _json_seq_first_value(json_obj, "0040A370", "0020000D")
    if study:
        return study
    study = _json_first_value(json_obj, "0020000D")
    if study:
        return study
    return _json_seq_first_value(json_obj, "00404021", "0020000D")

def _json_to_dataset_series(json_obj, request_keywords, study_json=None):
    """QIDO-RS series JSON -> pydicom Dataset (31.08 series-level C-FIND).

    The series C-FIND dataset MUST carry series attributes (0020,000E,
    0020,0011, 0008,0060, ...) - viewers drop rows without them. The
    server's series render omits PatientName/PatientID/StudyInstanceUID
    (confirmed live 31.08), so when the owning study row (`study_json`)
    is given, those three are injected from it.
    """
    ds = _json_map_to_dataset(json_obj, QIDO_SERIES_KEY_TO_TAG)
    if study_json:
        study_ds = _json_map_to_dataset(study_json, QIDO_KEY_TO_TAG)
        for group, elem in _STUDY_IDENTITY_ATTRS.values():
            ident_elem = study_ds.get((group, elem))
            if ident_elem is not None:
                _safe_add_new(ds, group, elem, ident_elem.VR, ident_elem.value)
    return ds

def _json_to_dataset_instance(
    json_obj,
    request_keywords,
    study_uid,
    series_uid,
    study_json=None,
    series_json=None,
):
    """QIDO-RS instance JSON -> an IMAGE-level pydicom Dataset.

    PS3.4 Table C.6-4 / C.4.1.3.1.1 (standard/ps3.4/image-level-C.6-4.json):
    every response Identifier carries all Unique Keys of the levels above, so
    StudyInstanceUID and SeriesInstanceUID are injected from the walk's
    context, and PatientName/PatientID plus the series context (Modality,
    SeriesNumber, SeriesDescription) from the rows the walk already fetched.
    The server's instance render carries none of those.

    A row with NO SOPInstanceUID is not an IMAGE-level answer at all - it is
    the relabelled study/series row the old fall-through produced, which the
    SCU cannot use. The caller drops such a row before it is yielded; this
    converter cannot invent the UID.
    """
    ds = _json_map_to_dataset(json_obj, QIDO_INSTANCE_KEY_TO_TAG)
    # A missing UID on either axis would write a zero-length Unique Key, which
    # a SCU reads as a real (empty) UID: absent is the honest form.
    if study_uid:
        _safe_add_new(ds, 0x0020, 0x000D, "UI", study_uid)
    if series_uid:
        _safe_add_new(ds, 0x0020, 0x000E, "UI", series_uid)
    if study_json:
        study_ds = _json_map_to_dataset(
            study_json, {k: QIDO_KEY_TO_TAG[k] for k in PATIENT_LEVEL_KEYS}
        )
        for group, elem in _STUDY_IDENTITY_ATTRS.values():
            src = study_ds.get((group, elem))
            if src is not None:
                _safe_add_new(ds, group, elem, src.VR, src.value)
    if series_json:
        series_ds = _json_map_to_dataset(series_json, QIDO_SERIES_KEY_TO_TAG)
        for json_key in _INSTANCE_SERIES_CONTEXT:
            group, elem, _vr, _kw = QIDO_SERIES_KEY_TO_TAG[json_key]
            src = series_ds.get((group, elem))
            if src is not None:
                _safe_add_new(ds, group, elem, src.VR, src.value)
    return ds

def _mwl_tail(value):
    """An identifier that fits MWL_SPS_ID_LEN characters, or '' when absent.

    Both identifiers below live in VR SH (16 characters). A UPS workitem UID is
    `2.25.<decimal u128>` (up to 43 characters), so it cannot be carried
    verbatim and its tail is used instead. This is a DERIVATION into an
    identifier's own scoped namespace, not a truncation of a value the modality
    must round-trip: a modality only needs a stable handle to couple MPPS to
    the step, and SPS ID is scoped by the Requested Procedure (PS3.3 C.4.10).

    A value that ALREADY fits is returned unchanged. Returning '' for it made
    a short workitem UID yield no (0040,0009) at all - a Type 1 MWL key - even
    though the only reason to shorten anything is the VR's 16 characters.
    """
    text = str(value or "").strip()
    if len(text) <= MWL_SPS_ID_LEN:
        return text
    return text[-MWL_SPS_ID_LEN:]

def _mwl_sps_id(workitem_uid):
    """(0040,0009) Scheduled Procedure Step ID, derived from the workitem UID.

    The MWL model has no SOP Instance UID (PS3.4 Table K.6-1), so the workitem
    UID has no legal home; its tail is the honest, deterministic stand-in.
    """
    return _mwl_tail(workitem_uid)

def _mwl_rp_id(study_instance_uid):
    """(0040,1001) Requested Procedure ID, derived from the study UID.

    Empty when the workitem names no study: there is no Requested Procedure
    without one, so nothing is emitted.
    """
    return _mwl_tail(study_instance_uid)

def _mwl_fill_start_datetime(sps, json_obj):
    """Fill (0040,0002)/(0040,0003) from (0040,4005) when the pair is missing.

    Both are Return keys Type 1 in MWL, but the UPS workitem carries the single
    DT attribute (0040,4005) ScheduledProcedureStepStartDateTime instead. Split
    it: the first 8 characters are the date, the next 6 the time. Only fields
    that are still absent are filled, so an explicit DA/TM pair wins.
    """
    if (
        "ScheduledProcedureStepStartDate" in sps
        and "ScheduledProcedureStepStartTime" in sps
    ):
        return
    dt = _json_first_value(json_obj, "00404005")
    if not dt:
        return
    digits = str(dt).strip()
    if len(digits) < 8:
        return
    date_part = digits[:8]
    time_part = digits[8:14]
    if "ScheduledProcedureStepStartDate" not in sps and date_part.isdigit():
        _safe_add_new(sps, 0x0040, 0x0002, "DA", date_part)
    if (
        "ScheduledProcedureStepStartTime" not in sps
        and len(time_part) == 6
        and time_part.isdigit()
    ):
        _safe_add_new(sps, 0x0040, 0x0003, "TM", time_part)

def _json_to_dataset_mwl(json_obj, request_keywords):
    """UPS-RS workitem JSON -> pydicom MWL Dataset, in the standard's shape.

    PS3.4 Table K.6-1: one row per Scheduled Procedure Step, with
    PatientName/PatientID at identifier level and the SPS attributes inside the
    single item of (0040,0100) Scheduled Procedure Step Sequence.

    Emission rules:
      - Return keys (MWL_RETURN_TOP, MWL_RETURN_SPS) whenever the source has a
        value, whether the modality asked or not.
      - Optional keys (MWL_OPTIONAL_TOP, MWL_OPTIONAL_SPS) ONLY when the
        modality named them in the identifier (PS3.4 C.4.1.1.3.2).

    The two derived identifiers have no source to map from:
      - (0040,0009) SPS ID       <- the workitem UID's tail
      - (0040,1001) RP ID        <- the input study UID's tail
    See _mwl_sps_id / _mwl_rp_id for why the tail and not the whole value.
    """
    ds = Dataset()
    # PS3.5 6.1.2: SpecificCharacterSet MUST be the first element.
    # ISO_IR 192 (UTF-8) is ALWAYS set, deliberately (documented in the DIMSE
    # bridge conformance statement): without it pydicom defaults to iso8859 /
    # Latin-1 and replaces Cyrillic PN/LO with '????' in RadiAnt/MicroDICOM.
    ds.SpecificCharacterSet = "ISO_IR 192"

    sps = Dataset()

    def fill(target, keymap, source, always):
        """Copy mapped values from `source` into `target` under `keymap`."""
        for json_key, (group, elem, vr, keyword) in keymap.items():
            if not always and keyword not in request_keywords:
                continue
            value = source.get(json_key)
            if not isinstance(value, dict):
                continue
            raw_value = value.get("Value") or []
            if not raw_value:
                # Present but EMPTY is dropped, not emitted zero-length: an
                # attribute with no value is absent from the row (documented
                # deviation, PS3.4 C.4.1.1.3.2 note 2 would allow zero-length).
                continue
            _json_add_vr(target, group, elem, vr, raw_value)

    # Identifier level: the two Return keys, then the request-gated Optional
    # ones. The study and the accession live in the Referenced Request
    # Sequence on a current server, so their values are resolved through that
    # (with the bare tag and the Input Information Sequence as fallbacks)
    # before the flat fill runs.
    fill(ds, MWL_RETURN_TOP, json_obj, always=True)
    optional_source = dict(json_obj)
    for flat_key, (seq_key, item_key) in MWL_OPTIONAL_TOP_SEQ.items():
        # `0020000D` is resolved even when the flat tag is present: the bare
        # tag and the Referenced Request Sequence must name the SAME study as
        # the derived RP ID, and `_json_workitem_study_uid` is the one place
        # that decides which value wins. Skipping the resolution when the bare
        # tag exists let the two disagree - and an empty bare tag silently
        # dropped StudyInstanceUID while leaving the RP ID derived from it.
        if flat_key == "0020000D":
            value = _json_workitem_study_uid(json_obj)
        elif flat_key == "00080050":
            # AccessionNumber (0008,0050) is Type 2: a present-but-EMPTY flat
            # tag is the valid "not recorded" marker, not a value. The
            # accession's standard carriage is (0040,A370) Referenced Request
            # Sequence (PS3.4 Table CC.2.5-3), so it is resolved FIRST, with
            # the bare tag only as a fallback. The old guard skipped the
            # resolution on the bare tag's mere presence, so an empty flat tag
            # shadowed a sequence value and fill() dropped the attribute.
            value = _json_seq_first_value(
                json_obj, seq_key, item_key
            ) or _json_first_value(json_obj, flat_key)
        else:
            if flat_key in optional_source:
                continue
            value = _json_seq_first_value(
                json_obj, seq_key, item_key
            ) or _json_first_value(json_obj, flat_key)
        if value:
            optional_source[flat_key] = {"vr": "UI", "Value": [value]}
    fill(ds, MWL_OPTIONAL_TOP, optional_source, always=False)

    # SPS level: the Return keys, then the request-gated Optional ones. The
    # station is resolved through its sequence first, so the flat fill below
    # reads a value that came from (0040,4025) Code Value without the return
    # key map having to know about sequences.
    sps_source = dict(json_obj)
    station = _json_seq_first_value(json_obj, *MWL_STATION_SEQ)
    if station:
        sps_source["00400001"] = {"vr": "AE", "Value": [station]}
    fill(sps, MWL_RETURN_SPS, sps_source, always=True)
    fill(sps, MWL_OPTIONAL_SPS, json_obj, always=False)

    # (0040,0002)/(0040,0003) Start Date/Time are Return keys Type 1. A
    # workitem created by the 2709 UPS Update path carries only (0040,4005)
    # ScheduledProcedureStepStartDateTime (VR DT); split it into the DA/TM
    # pair rather than leaving two Return keys empty. With neither source, the
    # pair is honestly absent - a step with no start time cannot produce one.
    _mwl_fill_start_datetime(sps, json_obj)

    # (0040,0009) SPS ID: the handle the modality couples MPPS to.
    sps_id = _mwl_sps_id(_json_first_value(json_obj, "00080018"))
    if sps_id:
        _safe_add_new(sps, 0x0040, 0x0009, "SH", sps_id)

    # (0040,0007) SPS Description is Optional: the modality must ask for it.
    # Source is (0074,1204) Procedure Step Label, the human-readable label.
    if "ScheduledProcedureStepDescription" in request_keywords:
        label = _json_first_value(json_obj, "00741204")
        if label:
            _safe_add_new(sps, 0x0040, 0x0007, "LO", label)

    if len(sps) > 0:
        ds.ScheduledProcedureStepSequence = Sequence([sps])

    # (0040,1001) Requested Procedure ID is Optional, and derived from the
    # input study. No study -> no Requested Procedure, so nothing is emitted.
    # The study is read from the Referenced Request Sequence first (the
    # standard carriage), with the bare tag and the Input Information
    # Sequence as fallbacks.
    if "RequestedProcedureID" in request_keywords:
        rp_id = _mwl_rp_id(_json_workitem_study_uid(json_obj))
        if rp_id:
            _safe_add_new(ds, 0x0040, 0x1001, "SH", rp_id)

    return ds

# ---------------------------------------------------------------------------
# N-ACTION protocol helpers
# ---------------------------------------------------------------------------
def _parse_n_action_rq(event):
    """Parse N-ACTION-RQ dataset.

    Returns (transaction_uid, [(sop_class_uid, sop_instance_uid), ...]).
    Raises ValueError if TransactionUID (0008,1195) is missing.
    """
    # An N-ACTION-RQ carries its payload as the Action Information parameter
    # (PS3.7 9.3.2), which is `event.action_information`. `event.dataset` reads
    # the C-STORE Data Set parameter instead and RAISES for an N-ACTION, so it
    # is only a fallback for test doubles that populate it.
    ds = None
    try:
        ds = event.action_information
    except AttributeError:
        pass
    if ds is None:
        try:
            ds = event.dataset
        except AttributeError:
            ds = Dataset()
    tx_uid = getattr(ds, "TransactionUID", None)
    if not tx_uid or str(tx_uid).strip() == "":
        raise ValueError("N-ACTION-RQ: missing TransactionUID (0008,1195)")
    tx_uid = str(tx_uid)

    sop_list = []
    ref_seq = getattr(ds, "ReferencedSOPSequence", None)
    if ref_seq:
        for number, item in enumerate(ref_seq, start=1):
            sop_class = str(getattr(item, "ReferencedSOPClassUID", ""))
            sop_uid = str(getattr(item, "ReferencedSOPInstanceUID", ""))
            # PS3.4 J.3.2 makes both UIDs Type 1 in every item: an item that
            # lacks either one does not identify an instance, so there is
            # nothing the origin could be asked to commit.
            #
            # Silently skipping the item was the worst of the three options:
            # with only that item present the parser returned an empty list and
            # `handle_n_action` answered SUCCESS without registering any report,
            # and in a mixed request the malformed item vanished while the SCU
            # was told the whole set was accepted. Raising here sends the
            # request down the existing refusal path, which is honest about a
            # request the bridge cannot represent.
            if not sop_class.strip():
                raise ValueError(
                    "N-ACTION-RQ: Referenced SOP Sequence item "
                    f"{number} has no ReferencedSOPClassUID (0008,1150)"
                )
            if not sop_uid.strip():
                raise ValueError(
                    "N-ACTION-RQ: Referenced SOP Sequence item "
                    f"{number} has no ReferencedSOPInstanceUID (0008,1155)"
                )
            sop_list.append((sop_class, sop_uid))

    return tx_uid, sop_list

def _build_n_action_rsp(tx_uid, verified_sops, failed_sops):
    """Build N-ACTION-RSP pydicom Dataset.

    verified_sops: list of (sop_class_uid, sop_instance_uid)
    failed_sops:   list of (sop_class_uid, sop_instance_uid, failure_reason)
    """
    rsp = Dataset()
    rsp.TransactionUID = tx_uid

    if verified_sops:
        success_seq = []
        for sop_class, sop_uid in verified_sops:
            item = Dataset()
            item.ReferencedSOPClassUID = sop_class
            item.ReferencedSOPInstanceUID = sop_uid
            success_seq.append(item)
        rsp.ReferencedSOPSequence = success_seq

    if failed_sops:
        failed_seq = []
        for sop_class, sop_uid, reason in failed_sops:
            item = Dataset()
            item.ReferencedSOPClassUID = sop_class
            item.ReferencedSOPInstanceUID = sop_uid
            item.FailureReason = reason
            failed_seq.append(item)
        rsp.FailedSOPSequence = failed_seq

    return rsp

# ---------------------------------------------------------------------------
# Bridge: registry
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  SOP Class and Printer registries.

YAML-driven SOP class acceptance. 13 built-in fallback classes.
Printer registry for C-PRINT (P22c).
"""

import logging

class RegistryConfigError(RuntimeError):
    """A custom registry file exists but yields nothing usable.

    Distinct from "no file at all": a missing file is a supported deployment
    (the built-ins are the documented fallback), while a file the operator
    wrote and the loader could not use is a configuration error. Startup fails
    on the latter rather than silently re-enabling what the file disables.
    """

def _strip_inline_comment(text):
    """Remove a trailing `#` comment, honouring quoted scalars.

    `name: "Film #2" # lobby` keeps its `#2`: the octothorpe inside a quoted
    value is data, not the start of a comment. A blind `split("#", 1)` cut it
    off, so the printer was registered as `Film`.

    An unclosed quote is treated as ordinary text: a malformed line must not
    swallow the rest of the file.
    """
    out = []
    quote = ""
    escaped = False
    for ch in text:
        if escaped:
            out.append(ch)
            escaped = False
            continue
        if ch == "\\" and quote:
            out.append(ch)
            escaped = True
            continue
        if quote:
            out.append(ch)
            if ch == quote:
                quote = ""
            continue
        if ch in ('"', "'"):
            quote = ch
            out.append(ch)
            continue
        if ch == "#":
            break
        out.append(ch)
    return "".join(out).rstrip()

# ---------------------------------------------------------------------------
# _parse_simple_yaml  -  minimal YAML subset parser (0 dependencies)
# ---------------------------------------------------------------------------
def _parse_simple_yaml(path):
    """Parse a minimal YAML subset: top-level key with nested dicts of name/accept.

    Only handles the exact format used by sop_classes.yaml and printers.yaml.
    No dependencies. Replaces PyYAML (~500 KB).
    """
    result = {}
    current_section = None
    current_uid = None
    current_entry = {}

    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            # Skip empty lines and comments
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue

            # Count leading spaces for indentation
            indent = len(line) - len(line.lstrip())

            if indent == 0:
                # Top-level section: "sop_classes:" or "printers:".
                #
                # The comment is stripped BEFORE the `endswith(":")` test, for
                # the same reason as an entry header: `sop_classes: # local
                # policy` ends on the comment, so the header was skipped and
                # every entry below it was dropped on the floor. The loader
                # then found no registry at all and fell back to the built-ins,
                # re-enabling a class the operator had switched off.
                header = _strip_inline_comment(stripped)
                if header.endswith(":"):
                    current_section = header[:-1].strip()
                    result[current_section] = {}
                    current_uid = None
                    current_entry = {}
                else:
                    # Not a section this parser understands (e.g. `MR: &policy`
                    # - a key with an anchor, not a section header). Treating
                    # it as noise and carrying on left the PREVIOUS section and
                    # entry active, so every field indented below it was written
                    # onto the previous class: one unsupported line silently
                    # rewrote its neighbour's `accept`.
                    current_section = None
                    current_uid = None
                    current_entry = {}
            elif indent == 2:
                # UID/name key: "  1.2.840...:". An inline comment after the
                # colon ("  1.2.840...:  # MR") is documentation, not part of
                # the key: strip it BEFORE the `endswith(":")` test, otherwise
                # the line ends on the comment, the header is skipped and the
                # NEXT `accept:` line lands on the PREVIOUS UID - re-enabling
                # a class the operator switched off.
                header = _strip_inline_comment(stripped)
                if not header.endswith(":"):
                    continue
                current_uid = header[:-1].strip().strip("\"'")
                current_entry = {}
                if current_section:
                    result[current_section][current_uid] = current_entry
            elif indent == 4 and ":" in stripped:
                # Key: value: "    name: CT Image Storage"
                key, _, value = stripped.partition(":")
                key = key.strip()
                if current_uid is None or not current_section:
                    # Between a skipped header and the next valid one there is
                    # no owning entry, so this field belongs to nobody. Writing
                    # it anyway would mutate the last dictionary created - the
                    # previous class - which is the corruption this parser must
                    # not commit.
                    continue
                # An inline comment is documentation, not part of the value:
                # `accept: false  # retired vendor` must stay a boolean, and a
                # quoted value must compare without its quotes. The comment is
                # stripped OUTSIDE quotes only, so `name: "Film #2" # lobby`
                # keeps its `#2`.
                value = _strip_inline_comment(value.strip()).strip().strip("\"'")
                if value.lower() == "true":
                    current_entry[key] = True
                elif value.lower() == "false":
                    current_entry[key] = False
                else:
                    current_entry[key] = value

    return result

# ---------------------------------------------------------------------------
# Bridge: SOP Class Registry  -  YAML-driven, no code changes needed
# ---------------------------------------------------------------------------
def _load_sop_registry(yaml_path="sop_classes.yaml"):
    """Load SOP class registry from YAML file (BR-009: no PyYAML dependency).

    Returns dict[uid -> dict] with keys: name, accept.
    A MISSING file falls back to the built-ins. Any other failure - unreadable,
    undecodable, a parse error - raises `RegistryConfigError`: those are cases
    where a file exists and was meant to be honoured, and silently installing
    the built-ins would re-enable a class that file switches off.
    """
    try:
        data = _parse_simple_yaml(yaml_path)
        registry = data.get("sop_classes", {}) if data else {}
    except FileNotFoundError:
        logging.info("[SOP-REG] Using built-in SOP defaults (no custom %s)", yaml_path)
        return _BUILTIN_SOP_CLASSES()
    except Exception as e:
        # Not a missing file: the operator wrote a registry and the bridge
        # could not read or understand it. Falling back to the built-ins is a
        # silent change of ADMISSION policy - a class the file disables comes
        # back enabled - so startup stops and names the fault instead.
        raise RegistryConfigError(
            f"{yaml_path}: custom SOP class registry cannot be read ({e}) - "
            "refusing to fall back to the built-ins, which would re-enable a "
            "class this file may disable"
        ) from e

    if registry:
        # A file that parses but yields an entry without `accept` means the
        # parser desynchronised for THAT entry. Accepting it as-is silently
        # turns an unreadable class into an accepted one, so the entry is
        # dropped and reported. Replacing the WHOLE registry with the built-ins
        # (the old behaviour) threw away every correct line as well - an
        # operator's `accept: false` was replaced by a built-in `accept: true`,
        # so a class they switched off came back on.
        broken = sorted(uid for uid, entry in registry.items() if "accept" not in entry)
        if broken:
            logging.error(
                "[SOP-REG] %s: %d SOP class entr%s without `accept` (%s) - "
                "those entries are ignored, the rest of the file is used",
                yaml_path,
                len(broken),
                "y" if len(broken) == 1 else "ies",
                ", ".join(broken[:3]) + (", ..." if len(broken) > 3 else ""),
            )
            for uid in broken:
                registry.pop(uid, None)
        # `accept` must be a real boolean. `_parse_simple_yaml` already turns
        # the two literals into bools, so anything else got here as a STRING
        # (`accept: yes`, `accept: 1`, `accept: on`) and `bool("no")` is True.
        # Coercing it would accept a class the operator wrote as refused, which
        # is the same silent-wrong-answer failure as a missing key, so such an
        # entry is dropped rather than corrected - never the whole file.
        mistyped = sorted(
            uid
            for uid, entry in registry.items()
            if not isinstance(entry["accept"], bool)
        )
        if mistyped:
            for uid in mistyped:
                logging.error(
                    "[SOP-REG] %s: SOP class %s has non-boolean accept=%r - "
                    "expected true or false; entry ignored",
                    yaml_path,
                    uid,
                    registry[uid]["accept"],
                )
            logging.error(
                "[SOP-REG] %d SOP class entr%s with a non-boolean `accept` - "
                "ignored; the other %d entr%s of the file are still used",
                len(mistyped),
                "y" if len(mistyped) == 1 else "ies",
                len(registry) - len(mistyped),
                "y" if len(registry) - len(mistyped) == 1 else "ies",
            )
            for uid in mistyped:
                registry.pop(uid, None)
        if not registry:
            # The file EXISTS and parsed, but nothing in it survived. Falling
            # back to the built-ins here is the same silent-wrong-answer the
            # per-entry rules above exist to prevent: an operator who wrote
            # `accept: false` for the only class they described would get that
            # class back, accepted, from the built-in table.
            #
            # A MISSING file still falls back (the historical, documented
            # behaviour for a deployment with no custom registry); a present
            # file that yields nothing is a configuration error, and startup
            # says so instead of guessing.
            raise RegistryConfigError(
                f"{yaml_path}: a custom SOP class registry was found but no "
                "entry in it is usable (missing or non-boolean `accept`) - "
                "refusing to fall back to the built-ins, which would re-enable "
                "a class this file disables"
            )
        logging.info(
            "[SOP-REG] Loaded %d SOP classes from %s", len(registry), yaml_path
        )
        return registry

    # A file that parses to zero entries is also a recognized-but-empty
    # registry: the operator wrote a file and got nothing applied.
    raise RegistryConfigError(
        f"{yaml_path}: a custom SOP class registry was found but describes no "
        "SOP class - refusing to fall back to the built-in defaults"
    )

def _BUILTIN_SOP_CLASSES():
    """Return 13 built-in SOP classes  -  always available, no dependencies (CMP-006).

    Both the current and the Retired UID are listed for the two classes whose
    UID was re-issued, because the fallback runs precisely when no
    sop_classes.yaml exists and the installed base is unknown: a cine loop
    arrives as 1.2.840.10008.5.1.4.1.1.3.1 on current equipment and as
    1.2.840.10008.5.1.4.1.1.3 on pre-2006 equipment.

    Retired classes kept for pre-2006 equipment still in active use:
    - MG For Processing (Retired): 1.2.840.10008.5.1.4.1.1.1.2.1
    - US Multi-frame (Retired): 1.2.840.10008.5.1.4.1.1.3, superseded by ...3.1
    - NM (Retired): 1.2.840.10008.5.1.4.1.1.5, superseded by ...20
    """
    return {
        "1.2.840.10008.1.1": {"name": "Verification", "accept": True},
        "1.2.840.10008.5.1.4.1.1.2": {"name": "CT Image Storage", "accept": True},
        "1.2.840.10008.5.1.4.1.1.4": {"name": "MR Image Storage", "accept": True},
        "1.2.840.10008.5.1.4.1.1.1": {
            "name": "Computed Radiography Image Storage",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.1.1": {
            "name": "Digital X-Ray Image Storage - For Presentation",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.1.2": {
            "name": "Digital Mammography X-Ray Image Storage - For Presentation",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.7": {
            "name": "Secondary Capture Image Storage",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.6.1": {
            "name": "Ultrasound Image Storage",
            "accept": True,
        },
        # Legacy Retired (pre-2006 equipment still in active use)
        "1.2.840.10008.5.1.4.1.1.1.2.1": {
            "name": "Digital Mammography X-Ray - For Processing (Retired)",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.3": {
            "name": "Ultrasound Multi-frame Image Storage (Retired)",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.5": {
            "name": "Nuclear Medicine Image Storage (Retired)",
            "accept": True,
        },
        # Current UIDs of the same two classes (PS3.6 Table A-1).
        "1.2.840.10008.5.1.4.1.1.3.1": {
            "name": "Ultrasound Multi-frame Image Storage",
            "accept": True,
        },
        "1.2.840.10008.5.1.4.1.1.20": {
            "name": "Nuclear Medicine Image Storage",
            "accept": True,
        },
    }

def _is_sop_accepted(sop_registry, context_uid):
    """Check if a SOP class UID is accepted by the Bridge.

    Args:
        sop_registry: dict from _load_sop_registry()
        context_uid: pynetdicom UID string (e.g. '1.2.840.10008.5.1.4.1.1.2')

    Returns:
        True if the SOP class is in registry and accept=True.
    """
    info = sop_registry.get(context_uid)
    if info and info.get("accept", False):
        return True
    return False

def _get_sop_registry_uids(sop_registry):
    """Return list of accepted SOP class UID strings from registry."""
    return [uid for uid, info in sop_registry.items() if info.get("accept", False)]

# ---------------------------------------------------------------------------
# Bridge: C-PRINT printer registry loader
# ---------------------------------------------------------------------------
def _load_printer_registry(yaml_path="printers.yaml"):
    """Load printer registry from YAML file (BR-009: no PyYAML dependency).

    Returns dict[str -> dict] with keys: name, host, port, aet, driver.
    Falls back to empty dict if YAML is missing.
    """
    try:
        data = _parse_simple_yaml(yaml_path)
        registry = data.get("printers", {}) if data else {}
        if registry:
            logging.info(
                "[PRINT-REG] Loaded %d printers from %s", len(registry), yaml_path
            )
            return registry
    except FileNotFoundError:
        logging.debug("[PRINT-REG] No custom printers.yaml - C-PRINT disabled")
    except Exception as e:
        logging.info("[PRINT-REG] Printers config parse error - %s: %s", yaml_path, e)

    return {}

# ---------------------------------------------------------------------------
# Bridge: streaming
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  streaming multipart parser (P10: Content-Length-based framing).

Contains _stream_multipart_instances (yields DICOM parts from streaming
multipart/related response). Parts within the spill threshold stay fully in
memory; larger parts spill the excess into a system temp file (W3, 0209).

P10: replaced boundary-searching state machine with Content-Length-based
framing. Boundary is used ONLY for verification, not for finding part
boundaries. This eliminates false boundary matches in binary pixel data.
"""

import os
import tempfile
from collections import namedtuple

# Defence in depth: prevent unbounded buffer growth on malformed multipart
MAX_BUFFER_SIZE = 100 * 1024 * 1024  # 100 MB

# Parts above this size are yielded as SpilledPart - the first
# SPILL_THRESHOLD body bytes stay in memory, the excess streams into a temp
# file. Injectable per call via the spill_threshold parameter (tests), never
# monkeypatched.
SPILL_THRESHOLD = 16 * 1024 * 1024  # 16 MB

# Yield element for an oversized part. `head` carries the first
# spill_threshold body bytes (kept in memory), `path` points at a temp file
# holding the rest. Namedtuple over (is_path, payload) tuples: attribute
# access beats indexed nested tuples at the two call sites (parser + loop).
SpilledPart = namedtuple("SpilledPart", "head path")

# DICOM magic bytes at offset 128 (PS3.10 sec.7.1)
DICM_MAGIC = b"DICM"
DICM_OFFSET = 128
DICM_MIN_SIZE = 132  # 128 + 4 magic bytes

class MultipartFramingError(ValueError):
    """The multipart stream ended before its closing delimiter (PS3.18 8.7.2).

    A ValueError subclass so the existing `except ValueError` around the read
    path still catches it; a distinct type so the resume driver can tell
    "the rest never arrived" from "one part was unusable".
    """

class InvalidDicomPartError(ValueError):
    """One part of a multipart/related DICOM response is not a DICOM file.

    The response labelled the part `application/dicom` (PS3.18 8.7.2
    Table 8.7.4-1), so a body without the PS3.10 7.1 DICM prefix is a defect
    of the answer, not a part the client may silently skip: dropping it made
    a partial transfer report as a complete one.
    """

# ---------------------------------------------------------------------------
# P10 B2: DICOM magic bytes verification (defence in depth)
# ---------------------------------------------------------------------------
def _is_valid_dicom(data: bytes) -> bool:
    """Check DICOM magic bytes ('DICM' at offset 128). PS3.10 sec.7.1."""
    if len(data) < DICM_MIN_SIZE:
        return False
    return data[DICM_OFFSET : DICM_OFFSET + 4] == DICM_MAGIC

# ---------------------------------------------------------------------------
# P10 B1: Content-Length extraction from MIME part headers
# ---------------------------------------------------------------------------
def _parse_content_length(headers_bytes: bytes) -> int | None:
    """Extract Content-Length from MIME part headers.

    Returns int or None if header is missing or malformed.

    Only an UNSIGNED DECIMAL is accepted. `int()` would have taken a leading
    sign, and a negative length is not merely wrong - it inverts the slicing
    arithmetic below: with `body_start + content_length == -1` the buffer-length
    check passes and `buffer[a:-1]` returns everything up to the penultimate
    byte, so a truncated part whose first 132 bytes happen to carry the DICM
    prefix was handed to the sender as a valid instance. Digits only, no sign,
    no whitespace inside.
    """
    for line in headers_bytes.split(b"\r\n"):
        if line.lower().startswith(b"content-length:"):
            raw = line.split(b":", 1)[1].strip() if b":" in line else b""
            if not raw or not raw.isdigit():
                return None
            try:
                return int(raw)
            except (ValueError, IndexError):
                return None
    return None

def _parse_part_transfer_syntax(headers_bytes: bytes) -> str | None:
    """Extract the `transfer-syntax=` parameter from the part's
    Content-Type header (3008 stored-first: the server names the ACTUAL
    syntax of the part bytes). Handles quoted and unquoted values and
    other parameters before/after. Returns None when absent.
    """
    for line in headers_bytes.split(b"\r\n"):
        if not line.lower().startswith(b"content-type:"):
            continue
        for part in line.split(b";")[1:]:
            kv = part.strip()
            if not kv.lower().startswith(b"transfer-syntax="):
                continue
            value = kv.split(b"=", 1)[1].strip().strip(b'"')
            value = value.decode("ascii", "replace").strip()
            return value or None
        return None
    return None

# ---------------------------------------------------------------------------
# P10 B1: Content-Length-based streaming multipart parser
# ---------------------------------------------------------------------------
def _normalise_content_length(buffer, body_start, declared, boundary_bytes):
    """Body length with a separator CRLF excluded, when the origin counted it.

    PS3.18 8.7.2 puts the transport separator OUTSIDE the part body, but a MIME
    implementation that counts the CRLF into Content-Length is common. Both
    forms are legal to receive; only one is legal to decode.

    The decision is made from the framing, not from a config knob: a body-only
    length leaves `\\r\\n--BOUNDARY` at the declared end, while a
    separator-inclusive length leaves `\\r\\n--BOUNDARY` one CRLF EARLIER and
    the two separator bytes at the declared end. Nothing is guessed beyond
    which of those two byte patterns is actually present, and a buffer that
    holds neither is left exactly as declared so the delimiter phase reports
    the framing error itself.
    """
    end = body_start + declared
    if end <= len(buffer):
        if buffer.startswith(b"\r\n" + boundary_bytes, end):
            return declared  # body-only (the normal convention)
        if declared >= 2 and buffer.startswith(b"\r\n" + boundary_bytes, end - 2):
            # The declared length counted the separator CRLF. Excluding it
            # keeps the delimiter at the buffer head after the body slice,
            # which is what every later phase expects.
            return declared - 2
    return declared

def _stream_multipart_instances(
    response, chunk_size=65536, spill_threshold=SPILL_THRESHOLD
):
    """Generator: yield (part, part_index, part_ts) from streaming multipart response.

    part_ts is the `transfer-syntax=` parameter of the part's Content-Type
    header (None when the server did not emit it - old server builds). The
    bridge reads it first in the actual_ts resolution chain, so the send
    loop never trusts a DICOM parser for the stored syntax.

    P10: Content-Length-based framing. Boundary is used ONLY for verification.
    Each MIME part MUST include Content-Length header (fail closed if missing).

    Protocol on the wire (from Clarus Server S1):
        --BOUNDARY\\r\\n
        Content-Type: application/dicom\\r\\n
        Content-Length: N\\r\\n
        \\r\\n
        <N bytes DICOM>
        \\r\\n--BOUNDARY\\r\\n
        ... next part ...
        \\r\\n--BOUNDARY--\\r\\n

    Args:
        response: requests.Response with stream=True
        chunk_size: read buffer size (default 64KB)
        spill_threshold: body bytes kept in memory per part (default 16 MB)

    Yields:
        (part, part_index, part_ts)  -  part is the raw DICOM body as bytes
        (the whole part fit in memory) or SpilledPart(head, path) when the
        part exceeded spill_threshold. The head carries the first
        spill_threshold bytes - enough for the DICM magic check and the
        whole file meta group the send loop reads.

    Raises:
        ValueError: if buffer exceeds MAX_BUFFER_SIZE, boundary missing,
                    or Content-Length missing (fail closed)
    """
    # Extract boundary from Content-Type header
    content_type = response.headers.get("Content-Type", "")
    boundary = None
    for param in content_type.split(";"):
        param = param.strip()
        if param.startswith("boundary="):
            boundary = param.split("=", 1)[1].strip().strip('"')
            break
    if not boundary:
        raise ValueError("Multipart: no boundary in Content-Type header")

    # Wire-format delimiters (as sent by Clarus Server S1/S2)
    boundary_bytes = ("--" + boundary).encode("ascii")
    first_delimiter = boundary_bytes + b"\r\n"  # --BOUNDARY\r\n
    # PS3.18 sec.8.7.2: each part body is followed by CRLF, then the next boundary.
    # Content-Length may or may not include this trailing CRLF. Handle both:
    #   Case A (CRLF in Content-Length): <body>\r\n--BOUNDARY\r\n
    #   Case B (CRLF outside):          <body>\r\n\r\n--BOUNDARY\r\n
    next_delimiter = b"\r\n" + boundary_bytes + b"\r\n"  # \r\n--BOUNDARY\r\n
    next_delimiter_alt = (
        b"\r\n\r\n" + boundary_bytes + b"\r\n"
    )  # \r\n\r\n--BOUNDARY\r\n
    final_delimiter = b"\r\n" + boundary_bytes + b"--"  # \r\n--BOUNDARY--
    final_delimiter_alt = b"\r\n\r\n" + boundary_bytes + b"--"  # \r\n\r\n--BOUNDARY--
    # Bare forms: after a body whose declared length INCLUDED the separator
    # CRLF, `_normalise_content_length` excludes it, so the boundary line sits
    # at the head of the buffer with no leading CRLF at all. Without these the
    # delimiter phase would report a framing error on a perfectly well-formed
    # separator-inclusive stream.
    next_delimiter_bare = boundary_bytes + b"\r\n"
    final_delimiter_bare = boundary_bytes + b"--"
    len_next_delimiter = len(next_delimiter)
    len_next_delimiter_alt = len(next_delimiter_alt)

    def _delimiter_status(buf):
        """Classify the buffer head: 'next', 'final', 'partial', or 'invalid'.

        A part body is followed by the boundary line and NOTHING else before
        the next part's headers (PS3.18 8.7.2). Treating an unrecognised tail
        as "more header lines" was the old behaviour: any bytes between two
        parts that happened to contain a `Content-Length:` line let the parser
        resume as if it had seen a delimiter, so a corrupted delimiter between
        A and B produced BOTH parts and a normal return - the framing defect
        was invisible.

        'partial' means the buffer may still be a prefix of a delimiter and
        more data is needed; every other unrecognised byte is 'invalid'.

        The CLOSING delimiter is validated to the end of its line: PS3.18
        8.7.2 delimits with `--BOUNDARY--` followed by optional transport
        padding and CRLF (or end of stream). The old prefix test accepted
        `--BOUNDARY--garbage\r\n` as a clean finish, so a stream whose closing
        line was corrupted still reported a complete transfer.
        """
        for marker, is_final in (
            (final_delimiter, True),
            (final_delimiter_alt, True),
            (final_delimiter_bare, True),
            (next_delimiter, False),
            (next_delimiter_alt, False),
            (next_delimiter_bare, False),
        ):
            if not buf.startswith(marker):
                continue
            if not is_final:
                return "next"
            rest = buf[len(marker) :]
            # Padding (MIME epilogue whitespace) then CRLF, or nothing at EOF.
            stripped = rest.lstrip(b" \t")
            if stripped.startswith(b"\r\n") or stripped.startswith(b"\n"):
                return "final"
            # Still arriving: the line is not terminated yet. A bare `\r` is
            # the FIRST half of the CRLF terminator, not trailing garbage -
            # treating it as invalid made a delimiter split between its two
            # CRLF bytes a fatal framing error on a perfectly valid response.
            if stripped in (b"", b"\r"):
                return "partial"
            return "invalid"
        # Nothing matched. An EMPTY buffer is not a framing error: the body has
        # just been consumed and the delimiter has not arrived yet. Reporting
        # "invalid" here made every chunk boundary that fell exactly after a
        # body a fatal framing error, so a valid response failed whenever the
        # delimiter happened to start the next chunk.
        if not buf:
            return "partial"
        # Is the buffer still a viable prefix of any marker?
        for marker in (
            final_delimiter,
            final_delimiter_alt,
            final_delimiter_bare,
            next_delimiter,
            next_delimiter_alt,
            next_delimiter_bare,
        ):
            probe = buf[: len(marker)]
            if probe and marker.startswith(probe):
                return "partial"
        return "invalid"

    buffer = b""
    part_index = 0
    preamble_skipped = False
    # PS3.18 8.7.2: every part body is followed by the boundary, and the
    # LAST one by the closing delimiter (--BOUNDARY--). Only that delimiter
    # proves the origin said it was done; an origin that stops mid-stream
    # otherwise looks exactly like a complete short answer.
    closed = False
    # Explicit DELIMITER phase. After a body is consumed the parser is not
    # reading headers until it has seen and verified the boundary line that
    # separates the parts - but the inner loop restarted at Phase 1 on every
    # chunk, so a delimiter split across chunks (`\r\n--b` then `--\r\n`) was
    # consumed as header text and then raised on a COMPLETE response. This flag
    # keeps the parser in the delimiter phase until the line is fully
    # classified.
    awaiting_delimiter = False
    # W3 (0209) spill state for the oversized part currently being received.
    spill_file = None  # open temp file, None when no spill is active
    spill_path = None  # spill_file.name while active
    spill_written = 0  # body bytes already written to the file
    spill_total = 0  # Content-Length of the spilled part
    spill_body_start = 0  # buffer offset where the part body begins

    try:
        for chunk in response.iter_content(chunk_size=chunk_size):
            if not chunk:
                continue
            if spill_file is None:
                buffer += chunk
            else:
                # W3: cap the in-memory head at spill_threshold, stream the
                # body overflow to the temp file and keep only the framing
                # bytes (trailing CRLF + next delimiter) in the buffer - it
                # stays bounded no matter how large the part is.
                avail = len(buffer) - spill_body_start
                missing = spill_total - spill_written - avail
                to_head = min(spill_threshold - avail, len(chunk))
                buffer += chunk[:to_head]
                to_file = min(len(chunk) - to_head, missing - to_head)
                if to_file > 0:
                    spill_file.write(chunk[to_head : to_head + to_file])
                    spill_written += to_file
                buffer += chunk[to_head + to_file :]

            # Defence in depth: prevent unbounded growth. W3 note: with a
            # spill active the in-memory buffer is capped at spill_threshold
            # bytes, so this check is inert for the head of an oversized
            # part; it remains the guard for malformed streams (broken
            # framing never completes a part, nothing is ever consumed).
            if len(buffer) > MAX_BUFFER_SIZE:
                raise ValueError(
                    f"Multipart buffer exceeded {MAX_BUFFER_SIZE} bytes "
                    "- possible malformed response"
                )

            while True:
                # -- Delimiter phase: a body was just consumed ------------
                # Stay here until the boundary line is fully classified. This
                # is a PHASE, not a fall-through: restarting at header parsing
                # treated a partially received delimiter as header text and
                # then reported a complete response as truncated.
                if awaiting_delimiter:
                    verdict = _delimiter_status(buffer)
                    if verdict == "final":
                        closed = True
                        return  # Clean finish
                    if verdict == "next":
                        advance = 0
                        for marker, advance in (
                            (next_delimiter, len_next_delimiter),
                            (next_delimiter_alt, len_next_delimiter_alt),
                            (next_delimiter_bare, len(next_delimiter_bare)),
                        ):
                            if buffer.startswith(marker):
                                break
                        buffer = buffer[advance:]
                        awaiting_delimiter = False
                        continue  # Next part's headers
                    if verdict == "partial":
                        break  # Wait for the rest of the delimiter line
                    raise MultipartFramingError(
                        "[STREAM] part "
                        f"{part_index - 1} was not followed by a boundary "
                        f"delimiter (PS3.18 8.7.2); next bytes {buffer[:32]!r}"
                    )

                # -- Phase 0: skip preamble, find first boundary ---------
                if not preamble_skipped:
                    idx = buffer.find(first_delimiter)
                    if idx == -1:
                        break  # Wait for more data
                    buffer = buffer[idx + len(first_delimiter) :]
                    preamble_skipped = True
                    # Continue to Phase 1 (don't break  -  headers follow immediately)

                # -- Phase 1: parse part headers -------------------------
                header_end = buffer.find(b"\r\n\r\n")
                if header_end == -1:
                    break  # Wait for complete headers

                # Defence: empty headers (header_end == 0) means the \r\n\r\n
                # at buffer start is a trailing CRLF from previous part body,
                # NOT the start of a new part. Classify it as a delimiter; an
                # unrecognised head is a framing error, not header text.
                if header_end == 0:
                    verdict = _delimiter_status(buffer)
                    if verdict == "final":
                        closed = True
                        return  # Clean finish (trailing CRLF + closing delimiter)
                    if verdict == "next":
                        advance = 0
                        for marker, advance in (
                            (next_delimiter, len_next_delimiter),
                            (next_delimiter_alt, len_next_delimiter_alt),
                            (next_delimiter_bare, len(next_delimiter_bare)),
                        ):
                            if buffer.startswith(marker):
                                break
                        buffer = buffer[advance:]
                        continue  # Next part (trailing CRLF + next delimiter)
                    if verdict == "partial":
                        break  # Wait for the rest of the delimiter line
                    raise MultipartFramingError(
                        "[STREAM] expected a boundary delimiter after part "
                        f"{part_index - 1} (PS3.18 8.7.2); got {buffer[:32]!r}"
                    )

                headers_bytes = buffer[:header_end]
                body_start = header_end + 4  # Skip \r\n\r\n

                # P10: Content-Length is MANDATORY (S1  -  server provides it)
                content_length = _parse_content_length(headers_bytes)
                if content_length is None:
                    raise ValueError(
                        f"[STREAM] Part {part_index}: missing Content-Length "
                        "- server must provide Content-Length per MIME part (P10 S1). "
                        "Boundary-based framing is unsafe for binary DICOM data."
                    )
                # 3008 stored-first: per-part transfer-syntax parameter.
                part_ts = _parse_part_transfer_syntax(headers_bytes)

                # PS3.18 8.7.2 leaves the transport separator outside the
                # part body, but a MIME implementation that counts the CRLF
                # into Content-Length is common enough that the framing must
                # survive it: consuming the separator as body bytes left the
                # buffer starting at `--BOUNDARY--` with no leading CRLF, which
                # matched neither closing pattern, and the instance was handed
                # to the sender with two trailing bytes attached before the
                # stream was reported truncated.
                #
                # Detected from the framing itself, at the DECLARED offset: if
                # the bytes at `body_start + content_length` are the boundary
                # line, the length was body-only; if they are the boundary
                # line shifted by one CRLF, the length counted the separator.
                content_length = _normalise_content_length(
                    buffer, body_start, content_length, boundary_bytes
                )

                # W3: parts above the threshold spill to a temp file.
                if spill_file is None and content_length > spill_threshold:
                    spill_file = tempfile.NamedTemporaryFile(
                        prefix="clbridge_spill_",
                        suffix=".part",
                        delete=False,
                    )
                    spill_path = spill_file.name
                    spill_written = 0
                    spill_total = content_length
                    spill_body_start = body_start
                    # The current chunk may already carry body bytes past
                    # the threshold - drain exactly the body overflow to the
                    # file; framing bytes (trailing CRLF + delimiter) stay
                    # in the buffer for Phase 4.
                    body_end = body_start + content_length
                    overflow = buffer[body_start + spill_threshold : body_end]
                    if overflow:
                        spill_file.write(overflow)
                        spill_written += len(overflow)
                    buffer = buffer[: body_start + spill_threshold] + buffer[body_end:]

                # -- Phase 2: extract DICOM body by length ---------------
                body_end = body_start + content_length
                if spill_file is None:
                    if len(buffer) < body_end:
                        break  # Wait for complete body
                    part = buffer[body_start:body_end]
                    buffer = buffer[body_end:]
                    check = part
                else:
                    # Head capped in memory, the excess already on disk.
                    if (len(buffer) - body_start) + spill_written < content_length:
                        break  # Wait for complete body
                    part = SpilledPart(
                        buffer[body_start : body_start + spill_threshold],
                        spill_path,
                    )
                    buffer = buffer[body_start + spill_threshold :]
                    spill_file.close()
                    spill_file = None
                    spill_path = None
                    spill_written = 0
                    check = part.head

                # -- Phase 3: yield DICOM body (Content-Length is authoritative) -
                body_valid = _is_valid_dicom(check)
                if body_valid:
                    yield (part, part_index, part_ts)
                    part_index += 1
                else:
                    if isinstance(part, SpilledPart):
                        # No consumer will ever see this part - drop the file.
                        try:
                            os.unlink(part.path)
                        except OSError:
                            pass
                    # Conformance rule for what the origin promised: the
                    # enclosing response declared this part `Content-Type:
                    # application/dicom` (PS3.18 8.7.2 Table 8.7.4-1), and
                    # PS3.10 7.1 requires the DICM prefix. An undecodable
                    # part must not be indistinguishable from "there were
                    # fewer parts": silence here reported Success for A while
                    # B, which the origin claimed to have sent, went nowhere.
                    raise InvalidDicomPartError(
                        f"[STREAM] Part {part_index}: response declared "
                        f"application/dicom but the body has no DICM magic "
                        f"(PS3.10 7.1) - {len(check)} bytes checked"
                    )

                # The body is out. The next bytes MUST be a boundary line, and
                # the delimiter phase above enforces that - nothing here is
                # inferred, and the parser cannot fall back to header parsing
                # while the line is still arriving.
                awaiting_delimiter = True
                continue

        # -- Flush: stream ended without final delimiter ----------------
        # W3: with a spill still active the oversized part never completed -
        # never yield a truncated head, let the finally drop the file.
        if preamble_skipped and len(buffer) > 0 and spill_file is None:
            # Try to extract one last part from remaining buffer
            header_end = buffer.find(b"\r\n\r\n")
            if header_end != -1:
                headers_bytes = buffer[:header_end]
                body_start = header_end + 4
                content_length = _parse_content_length(headers_bytes)
                part_ts = _parse_part_transfer_syntax(headers_bytes)
                if (
                    content_length is not None
                    and len(buffer) >= body_start + content_length
                ):
                    dicom_body = buffer[body_start : body_start + content_length]
                    if _is_valid_dicom(dicom_body):
                        yield (dicom_body, part_index, part_ts)
                    else:
                        raise InvalidDicomPartError(
                            f"[STREAM] Part {part_index}: response declared "
                            f"application/dicom but the body has no DICM "
                            f"magic (PS3.10 7.1)"
                        )
                elif content_length is None:
                    # Fallback: use whatever is left as body (no Content-Length header).
                    # Some non-standard DICOMweb implementations omit Content-Length.
                    body = buffer[body_start:].rstrip(b"\r\n")
                    if body and _is_valid_dicom(body):
                        yield (body, part_index, part_ts)

        # PS3.18 8.7.2: the multipart body is terminated by the closing
        # delimiter. Reaching EOF without it means the origin stopped early -
        # half of part B never arrived. Returning normally here let the caller
        # report Success for the parts that did arrive, so a truncated retrieve
        # looked like a complete one (PS3.4 C.4.2: the C-MOVE-RSP status
        # describes the WHOLE request). Raising hands the parts already
        # delivered to the caller while it retries the remainder.
        if not closed:
            raise MultipartFramingError(
                "[STREAM] multipart body ended before the closing delimiter "
                f"(PS3.18 8.7.2); {part_index} part(s) received, stream truncated"
            )
    finally:
        # W3: never leak a spill file - a truncated stream, a fatal parse
        # error or an early consumer exit all land here. A completed part
        # resets spill_file before it is yielded, so only the part that was
        # still being received is cleaned up here.
        if spill_file is not None:
            try:
                spill_file.close()
            except OSError:
                pass
            try:
                os.unlink(spill_path)
            except OSError:
                pass

# ---------------------------------------------------------------------------
# Bridge: utils
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  core utilities: shutdown signal, logging, dataset measurement.

Contains graceful shutdown event, signal handler, logging setup with rotation,
and C-STORE dataset size measurement.
"""

import contextlib
import hashlib
import hmac
import io
import ipaddress
import logging
import os
import sys
import tempfile
import threading
import time
from logging.handlers import RotatingFileHandler

from pydicom import dcmwrite
from pydicom.uid import ImplicitVRLittleEndian

# ---------------------------------------------------------------------------
# Bridge: graceful shutdown event  -  checked by all handlers
# ---------------------------------------------------------------------------
_shutdown_requested = threading.Event()

# : PID file path for duplicate instance detection cleanup
_pid_path = None  # Set by main.py after successful startup checks

def set_pid_path(path: str) -> None:
    """Set PID file path (called by main.py after startup checks)."""
    global _pid_path
    _pid_path = path

# Set by the signal handler and read by the shutdown monitor, which emits the
# log line. A signal handler may not log: every logging handler serialises its
# I/O behind a lock, so if a worker thread is blocked writing to a redirected
# stderr the handler would wait for that lock here - BEFORE setting the event -
# and the monitor would never observe SIGTERM. The handler therefore records
# only the signal it saw.
_signal_seen = []

def _signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT/SIGBREAK  -  initiate graceful shutdown (BR-007).

    nginx-way: signal handler does ONE thing  -  sets the shutdown flag.
    The ShutdownMonitor thread (started in main.py) bridges this flag
    to pynetdicom's event loop by calling ae.shutdown() from a regular
    thread context, which is safe (not async-signal-restricted).

    Deliberately NO logging and NO `signal.Signals(signum).name` lookup that
    could raise: `_shutdown_requested.set()` must run on every path, because a
    handler that raises before it leaves the bridge ignoring the signal. The
    monitor reports the signal once it observes the event.
    """
    try:
        _signal_seen.append(signum)
    except Exception:
        pass
    _shutdown_requested.set()
    # That's it. Nothing else. No timers, no os._exit, no file I/O.
    # ShutdownMonitor thread handles the rest.

def take_signal_seen():
    """The signal number observed by the handler, or None (consumed once).

    The monitor calls this after it sees `_shutdown_requested`, so the log line
    is emitted from a normal thread context where blocking on a handler lock is
    harmless.
    """
    try:
        return _signal_seen.pop() if _signal_seen else None
    except Exception:
        return None

# ---------------------------------------------------------------------------
# Bridge: configure logging with optional rotation
# ---------------------------------------------------------------------------
def _setup_logging(log_level="INFO", log_file=None):
    """Configure root logger with console handler and optional file handler.

    Log rotation: 10 MB x 3 backups (always on when log_file is set).
    """
    level = getattr(logging, log_level.upper(), logging.INFO)
    fmt = logging.Formatter(
        "%(asctime)s [%(levelname)s] %(message)s",
        datefmt="%Y-%m-%dT%H:%M:%S",
    )

    root_logger = logging.getLogger()
    root_logger.setLevel(level)
    root_logger.handlers.clear()

    # -- Suppress library noise  -  : libraries keep quiet --
    # urllib3/requests log every HTTP request at INFO (432 lines of "201 Created"
    # for a 432-slice upload). pynetdicom/pydicom dump tracebacks.
    # Below WARNING, library output is noise  -  admin doesn't need it.
    for lib in ("urllib3", "requests", "httpx", "httpcore", "pydicom", "pynetdicom"):
        logging.getLogger(lib).setLevel(logging.WARNING)

    # -- Console: UTF-8 with error replacement  -  never crash on non-cp1251 chars --
    # Chinese patient names, Norwegian AE titles, DICOM UIDs with special chars  -
    # Windows console may be cp1251, but log messages come in UTF-8.
    # reconfigure() makes stderr replace unencodable chars with '?' instead of crashing.
    console_stream = sys.stderr
    try:
        console_stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass  # Python < 3.7 or non-TTY  -  fall through to raw stderr
    console = logging.StreamHandler(console_stream)
    console.setFormatter(fmt)
    root_logger.addHandler(console)

    if log_file:
        # Auto-create the parent directory (e.g. logs/) so a fresh host does not
        # fail on a missing path.
        log_dir = os.path.dirname(os.path.abspath(log_file))
        os.makedirs(log_dir, exist_ok=True)
        max_bytes = 10 * 1024 * 1024  # 10 MB
        file_handler = RotatingFileHandler(
            log_file,
            maxBytes=max_bytes,
            backupCount=3,
            encoding="utf-8",
        )
        file_handler.setFormatter(fmt)
        root_logger.addHandler(file_handler)
        logging.info("Logging to file: %s (10 MB x 3 rotations)", log_file)

# ---------------------------------------------------------------------------
# Bridge: C-STORE size limit measurement
# ---------------------------------------------------------------------------
def _measure_dataset_bytes(dataset, event=None):
    """Return dataset size in bytes.

    Prefers pynetdicom's raw DataSet if available (no extra serialization).
    Falls back to dcmwrite() into BytesIO buffer.

    pynetdicom hands large payloads over as a stream (BytesIO) rather than
    bytes, and a stream has no len(); the size of such a payload is its
    remaining length, so seek to the end and restore the position. Without
    this the size of every large C-STORE would be reported as unmeasurable.
    """
    # Bridge: try raw request data first (fast path, BR-001)
    if event is not None:
        raw = getattr(event.request, "DataSet", None)
        if raw is not None:
            try:
                return len(raw)
            except TypeError:
                # A stream: measure by seeking, then restore the read
                # position so the caller can still consume the payload.
                pos = raw.tell()
                size = raw.seek(0, io.SEEK_END)
                raw.seek(pos)
                return size
    # Bridge: fallback  -  serialize to measure (slow path, BR-001)
    buf = io.BytesIO()
    # Ensure bare Datasets (e.g. from tests) have encoding context
    if not hasattr(dataset, "is_implicit_VR") or dataset.is_implicit_VR is None:
        dataset.is_implicit_VR = True
        dataset.is_little_endian = True
    # Populate minimal file_meta to satisfy pydicom validator
    if not hasattr(dataset, "file_meta") or not dataset.file_meta:
        from pydicom import Dataset as DcmDs

        dataset.file_meta = DcmDs()
    fm = dataset.file_meta
    if not getattr(fm, "MediaStorageSOPClassUID", None):
        fm.MediaStorageSOPClassUID = (
            getattr(dataset, "SOPClassUID", "1.2.840.10008.5.1.4.1.1.7")
            or "1.2.840.10008.5.1.4.1.1.7"
        )
    if not getattr(fm, "MediaStorageSOPInstanceUID", None):
        fm.MediaStorageSOPInstanceUID = (
            getattr(dataset, "SOPInstanceUID", "1.2.826.0.1.3680043.8.498.1")
            or "1.2.826.0.1.3680043.8.498.1"
        )
    if not getattr(fm, "TransferSyntaxUID", None):
        fm.TransferSyntaxUID = ImplicitVRLittleEndian
    dcmwrite(buf, dataset, enforce_file_format=True)
    return len(buf.getvalue())

# ---------------------------------------------------------------------------
# Bridge: PatientName masking - no PHI in logs.
# ---------------------------------------------------------------------------
def replace_with_retry(src, dst, attempts=50):
    """Publish `src` over `dst` atomically, retrying a transient refusal.

    `os.replace` is atomic but NOT free of contention on Windows: it is built
    on ReplaceFile, which fails with a sharing violation (WinError 5/32) when
    the destination is momentarily held open by another handle - a concurrent
    writer, a reader mid-parse, or the OS itself. Measured on this code base:
    8 threads publishing the same destination lost ~10% of the renames, and a
    single thread in isolation never does.

    Retrying is the whole fix: the window is a single syscall wide, so a short
    escalating sleep converges almost immediately (measured: 265 failures
    without a retry, zero with one, ~0.9 extra attempts per publish). The
    attempt budget bounds the cost when the destination is genuinely locked
    forever, and the last error is re-raised unchanged so callers keep their
    existing error handling.
    """
    for attempt in range(attempts):
        try:
            os.replace(src, dst)
            return
        except PermissionError:
            if attempt == attempts - 1:
                raise
            time.sleep(0.001 * (attempt + 1))

# Fixed-size lock striping. A dict keyed by SOP Instance UID (or by index-file
# path) grows one entry per distinct key and nothing ever removes them, so a
# 24/7 service leaks a lock object per instance received - monotonic RSS growth
# with no upper bound. Stripes bound the registry at construction time.
#
# 256 stripes: two writers for the SAME key must still serialise, and they do
# because equal keys hash to the same stripe. Distinct keys sharing a stripe
# merely wait for each other, which costs concurrency but never correctness,
# and 256 is far more than the handful of concurrent publishers this bridge
# runs - the collision rate only matters if that count approaches the stripe
# count.
_STRIPE_COUNT = 256

class LockStripes:
    """A bounded replacement for a per-key dict of threading.Lock."""

    __slots__ = ("_stripes",)

    def __init__(self, count=_STRIPE_COUNT):
        self._stripes = [threading.Lock() for _ in range(count)]

    def for_key(self, key):
        """Return the lock guarding `key`.

        `hash()` is used rather than a digest because a single CPython process
        keeps string hashes stable for its lifetime, and these keys never leave
        the process. `zlib.crc32(key.encode())` would be the portable choice if
        this ever had to agree across interpreters; it does not.
        """
        stripes = self._stripes
        return stripes[hash(key) % len(stripes)]

# ---------------------------------------------------------------------------
# Peer address normalisation
# ---------------------------------------------------------------------------
def normalize_host(host):
    """Canonical form of a peer address for EQUALITY comparison.

    A `peers.conf` host may be `localhost`, an upper-case alias, a bracketed
    IPv6 literal or this machine's FQDN, while a request's calling address is
    the raw A-ASSOCIATE socket address (`127.0.0.1`, `::1`). String inequality
    is not address inequality, so both sides go through this once before being
    compared.

    What it actually does, in order:
      1. strips brackets and whitespace and lower-cases (a NAME is returned
         lower-cased and otherwise untouched - no DNS lookup, no expansion);
      2. the wildcard binds (`0.0.0.0`, `::`) and the literal `localhost`
         become `127.0.0.1`;
      3. anything the IPv4/IPv6 parser accepts is canonicalised by
         `str(ip_address(...))`, and every address in the loopback BLOCK
         (`127.0.0.0/8`, `::1`, and IPv4-mapped forms such as
         `::ffff:127.0.0.1`) is collapsed to `127.0.0.1`.

    It does NOT resolve names, does NOT expand a non-loopback alias to the
    address the kernel would pick, and does NOT treat two different
    non-loopback addresses as equal.
    """
    h = str(host or "").strip().lower().strip("[]")
    if not h:
        return ""
    # Zero-compression-vs-explicit and IPv4-mapped forms are the same endpoint.
    if h in ("0.0.0.0", "::"):
        return "127.0.0.1"
    if h == "localhost":
        return "127.0.0.1"
    try:
        addr = ipaddress.ip_address(h)
    except ValueError:
        return h
    # An IPv4-mapped IPv6 address IS the IPv4 address: a dual-stack listener
    # reports an IPv4 peer as `::ffff:10.0.0.5` while peers.conf says
    # `10.0.0.5`, and comparing the two as written never matches. Unwrap
    # first so the rest of the canonicalisation sees one address family.
    mapped = getattr(addr, "ipv4_mapped", None)
    if mapped is not None:
        addr = mapped
    # An unspecified address is the wildcard bind in ANY spelling. The literal
    # test above only catches the compressed `0.0.0.0` and `::`; the expanded
    # IPv6 form `0:0:0:0:0:0:0:0` reaches here unchanged and would compare
    # unequal to the `::` that a peers.conf entry normally writes, so a
    # configured wildcard peer failed to match a loopback caller.
    if addr.is_unspecified:
        return "127.0.0.1"
    # The whole loopback block is one machine: `::1`, `[::1]` and `127.0.0.1`
    # must compare equal or a peers.conf entry saying `localhost` disagrees
    # with an A-ASSOCIATE from `::1`.
    if addr.is_loopback:
        return "127.0.0.1"
    return str(addr)

def mask_patient_name(name: str) -> str:
    """Mask PatientName for 152-FZ: Ivanov -> I....v, Smith -> S...h."""
    if not name:
        return "***"
    n = len(name)
    if n <= 1:
        return "***"
    if n == 2:
        return name[0] + "."
    return name[0] + "." * min(n - 2, 4) + name[-1]

def mask_patient_id(patient_id: str) -> str:
    """Mask PatientID for the logs with a keyed HMAC token (152-FZ).

    A national/MRN identifier has no safe first/last mask (its prefix is
    site-coded), so the log carries a stable 12-hex token instead of the raw
    value. The study UID logged next to it remains the correlation key.

    The token is HMAC-SHA256 under a per-install secret, not a bare digest.
    Patient IDs are low entropy by design - a few digits, often with a
    site prefix - so an unkeyed SHA-256 of one is reversible by enumeration:
    anyone holding a log line hashes candidates until one matches, in
    seconds, and the log stops being anonymised. The secret is what makes
    that search impossible without the key file.

    Correlating two lines needs the same secret, so the key persists next to
    the outbox and is created once on first use. Deleting it yields a NEW
    key, and every token written afterwards differs from the ones already in
    the log: old lines keep their own tokens and no longer join to new ones.
    That affects log correlation ONLY - forwarding is unaffected, because the
    outbox carries the raw PatientID, not this token.
    """
    if not patient_id:
        return "***"
    key = _mask_key()
    return hmac.new(key, patient_id.encode("utf-8"), hashlib.sha256).hexdigest()[:12]

#: Per-install masking key, read once. `None` = not yet loaded.
_mask_key_cache = None

def _outbox_root() -> str:
    """The configured outbox directory, resolved the same way main.py resolves
    it (relative paths are relative to the config file). Falls back to the
    default so a unit-test import does not depend on startup order."""
    configured = os.environ.get("CLBRIDGE_OUTBOX_DIR")
    if configured:
        return configured
    return os.path.join(os.getcwd(), "clbridge", "outbox")

def set_mask_key_dir(path: str) -> None:
    """Point the masking key at `path` (called by main.py once the outbox
    directory is resolved). Clears the cache so the next call reloads."""
    global _mask_key_cache, _mask_key_dir_override
    _mask_key_dir_override = path
    _mask_key_cache = None

#: Explicit override set by main.py; empty means "derive from the outbox".
_mask_key_dir_override = ""

#: Serialises the load-or-create sequence between THREADS of this process.
#: The `O_EXCL` create already arbitrates between processes; two threads in
#: one process would otherwise both miss the cache and both run the repair
#: branch over the same file. `RLock` because the recursion is not expected:
#: a plain `Lock` would be enough today, and a nested call in the future must
#: not deadlock the whole process over a log line.
_mask_key_lock = threading.RLock()

#: A published key is 32 random bytes (256 bits); anything shorter is a
#: truncated file or a half-written one, never a key. The length is the
#: contract the winner writes and the loser accepts, so both sides agree.
_MASK_KEY_BYTES = 32

#: How many times a loser re-reads a file it found too short before giving
#: up. The winner's window is one `os.replace` - microseconds - so three
#: attempts with a 10 ms backoff cover an arbitrarily slow scheduler without
#: turning a broken file into an infinite wait.
_MASK_KEY_READ_ATTEMPTS = 3
_MASK_KEY_READ_PAUSE_S = 0.01

@contextlib.contextmanager
def _mask_key_file_lock(root: str):
    """Hold an INTERPROCESS exclusive lock over the mask-key directory.

    `_mask_key_lock` only serialises threads of one process. Two bridge
    processes sharing an outbox (a rolling restart, a supervisor that starts
    the replacement before the old one exits) could each see a missing key,
    each publish its own, and each cache a DIFFERENT one - so the same
    PatientID masked to two different tokens and log correlation broke across
    the restart. That is exactly when an operator is reading both logs.

    The lock file is a sibling of the key, created on demand and left in
    place: an unlink would race the next opener. Blocking, unlike the startup
    lock - a producer here holds it for one `os.replace`, so waiting is
    cheaper than the wrong answer.

    A lock that cannot be taken is not fatal: the in-process lock still holds
    and the file-level protocol below still picks a single winner. Losing
    cross-process serialisation degrades to the old behaviour rather than
    refusing to log.
    """
    lock_path = os.path.join(root, ".patient_id_mask.key.lock")
    handle = None
    try:
        os.makedirs(root, exist_ok=True)
        handle = open(lock_path, "a+b")
        if os.name == "nt":
            import msvcrt

            handle.seek(0)
            # LK_LOCK retries for ~10 s internally before raising; the file is
            # one byte and the holder releases in microseconds.
            msvcrt.locking(handle.fileno(), msvcrt.LK_LOCK, 1)
        else:
            import fcntl

            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
    except OSError as exc:
        logging.debug("[MASK] cross-process key lock unavailable (%s)", exc)
        if handle is not None:
            try:
                handle.close()
            except OSError:
                pass
            handle = None
    except Exception as exc:  # pragma: no cover - platform oddity
        logging.debug("[MASK] cross-process key lock unusable (%s)", exc)
        if handle is not None:
            try:
                handle.close()
            except OSError:
                pass
            handle = None

    try:
        yield
    finally:
        if handle is not None:
            try:
                if os.name == "nt":
                    import msvcrt

                    handle.seek(0)
                    msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
                else:
                    import fcntl

                    fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
            except OSError:
                pass
            try:
                handle.close()
            except OSError:
                pass

def _publish_key(path: str, key: bytes) -> None:
    """Write `key` to `path` so no reader can ever observe a partial file.

    A create-then-write publishes the NAME before the BYTES: a concurrent
    reader sees an empty file, and an empty HMAC key is as good as no key at
    all - the token becomes an unkeyed digest of a low-entropy patient id,
    reversible by enumeration. Writing to a temporary sibling and `os.replace`
    onto the final name makes the publication atomic on POSIX and on Windows,
    so a reader opens either the old file or the complete new one.
    """
    fd, tmp_path = tempfile.mkstemp(
        prefix=".patient_id_mask.", dir=os.path.dirname(path)
    )
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(key)
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

def _read_key(path: str) -> bytes:
    """Read a published key, retrying while it is still too short."""
    for attempt in range(_MASK_KEY_READ_ATTEMPTS):
        try:
            with open(path, "rb") as handle:
                key = handle.read()
        except FileNotFoundError:
            key = b""
        if len(key) >= _MASK_KEY_BYTES:
            return key
        if attempt + 1 < _MASK_KEY_READ_ATTEMPTS:
            time.sleep(_MASK_KEY_READ_PAUSE_S)
    return key

def _mask_key() -> bytes:
    """Load the per-install masking key, creating or repairing it as needed.

    Three cases, and they are genuinely different:

    * ABSENT - create it exclusively (`O_EXCL`). Two processes starting at the
      same moment must not both write a key with one silently winning: the
      loser re-reads what the winner wrote, so both end up with the same key.
    * PRESENT and long enough - use it. This is the normal path.
    * PRESENT but too short - the file is truncated or was never a key. It has
      to be REPLACED, which the exclusive-create path cannot do: `O_EXCL`
      fails on an existing file, and re-reading it would hand back the same
      unusable bytes while the log claimed otherwise. The replacement is
      therefore an in-place truncating write.

    A missing key is created rather than treated as an error: the first log
    line of a fresh install must already be masked, and refusing to log it
    would trade a privacy leak for an outage. An UNREADABLE key (permissions,
    a directory in its place) is logged and not fatal - tokens then stop being
    stable across restarts, which is visible and recoverable, whereas a crash
    at startup is not.
    """
    global _mask_key_cache
    if _mask_key_cache is not None:
        return _mask_key_cache
    with _mask_key_lock:
        if _mask_key_cache is not None:
            return _mask_key_cache
        key = _load_or_create_key()
        _mask_key_cache = key
        return key

def _load_or_create_key() -> bytes:
    """The load-or-repair sequence behind `_mask_key`, run under the lock.

    The whole sequence - read, validate, replace - runs under the interprocess
    file lock, so only one process at a time can decide the key. Reading
    before taking it was the race: a creator that paused between the
    exclusive create and its rename let a second process time out on the
    short file, publish its own key, and then have the first overwrite it,
    leaving two live processes with different keys.
    """
    root = _mask_key_dir_override or _outbox_root()
    path = os.path.join(root, ".patient_id_mask.key")

    with _mask_key_file_lock(root):
        return _load_or_create_key_locked(root, path)

def _load_or_create_key_locked(root: str, path: str) -> bytes:
    """Body of `_load_or_create_key`; the caller holds the file lock."""
    try:
        with open(path, "rb") as handle:
            existing = handle.read()
    except FileNotFoundError:
        existing = None
    except OSError as exc:
        logging.error(
            "[MASK] cannot read the patient-id key at %s (%s); "
            "log tokens are not stable across restarts",
            path,
            exc,
        )
        return os.urandom(_MASK_KEY_BYTES)

    if existing is not None and len(existing) >= _MASK_KEY_BYTES:
        return existing

    key = os.urandom(_MASK_KEY_BYTES)
    try:
        os.makedirs(root, exist_ok=True)
        if existing is None:
            # Absent. The exclusive create decides a race between processes,
            # and its only role is to name one winner: the bytes are then
            # published by rename, so no reader ever sees the empty file the
            # create leaves behind.
            try:
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            except FileExistsError:
                # Another process won. Its file is authoritative; it is read
                # back with a length check, because the winner's rename makes a
                # short read impossible and a half-written file must never be
                # adopted as a key.
                adopted = _read_key(path)
                if len(adopted) >= _MASK_KEY_BYTES:
                    return adopted
                # The winner is mid-publication or gone; publishing ours is
                # still the best repair, and it is atomic for every reader.
                _publish_key(path, key)
                return key
            os.close(fd)
        else:
            # Present but unusable: it cannot be trusted and `O_EXCL` would
            # refuse to fix it, so it is replaced.
            #
            # R11: re-read first. A SHORT file is also what a process sees
            # while ANOTHER process is mid-publish, and replacing it there
            # made two live processes hold DIFFERENT keys - the same PatientID
            # then masked to different tokens, which breaks log correlation.
            # `_read_key` retries with its own bounded pause, so a publication
            # in flight gets to finish; ours is published only if the file is
            # still unusable afterwards.
            adopted = _read_key(path)
            if len(adopted) >= _MASK_KEY_BYTES:
                return adopted
            # The length is reported because a short key is a symptom worth
            # seeing; after the retries it really is truncated, not in flight.
            logging.warning(
                "[MASK] key file %s is short (%d bytes); replacing it",
                path,
                len(adopted),
            )
        _publish_key(path, key)
    except OSError as exc:
        logging.error(
            "[MASK] cannot persist the patient-id key at %s (%s); "
            "log tokens are not stable across restarts",
            path,
            exc,
        )
    return key

# ---------------------------------------------------------------------------
# Bridge: validation
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  DICOM tag validation and coercion (FR-001).

Bridge sanitizes empty DICOM Type 2 fields (PatientID, PatientName)
BEFORE sending to the server. Records all modifications in
Original Attributes Sequence (0400,0561)  -  the bridge's audit trail.

Server also validates independently  -  two levels of protection.
"""

import hashlib
import secrets
import time

from pydicom.dataset import Dataset
from pydicom.sequence import Sequence

def generate_patient_id(prefix="AUTOPAT_"):
    """Generate unique PatientID: AUTOPAT_YYYYMMDD_HHMMSS_RRRRR.

    Fallback for when StudyInstanceUID is unavailable.
    Prefer generate_patient_id_from_study() for deterministic grouping.
    Uses timestamp + secrets for uniqueness across concurrent C-STORE calls.
    """
    ts = time.strftime("%Y%m%d_%H%M%S")
    rnd = secrets.token_hex(4)  # 8 hex chars  -  sufficient entropy for fallback
    return f"{prefix}{ts}_{rnd}"

def generate_patient_id_from_study(study_uid, prefix="AUTOPAT_"):
    """Generate deterministic PatientID from StudyInstanceUID.

    # All SOPs in one study must map to the same PatientID, otherwise the
    # DICOMweb hierarchy would split a single study across patients.
    SHA-256 truncated to 12 hex chars -> collision probability < 2^-48.
    Deterministic -> same StudyUID always produces same PatientID.
    """
    h = hashlib.sha256(study_uid.encode()).hexdigest()[:12].upper()
    return f"{prefix}{h}"

def generate_patient_name(prefix="Anonymous^"):
    """Generate DICOM PatientName in PN format: Anonymous^Generated.

    Fallback when StudyInstanceUID is unavailable.
    """
    return f"{prefix}Generated"

def generate_patient_name_from_study(study_uid, prefix="Anonymous^"):
    """Generate deterministic PatientName from StudyInstanceUID.

    Format: Anonymous^A1B2C3  -  unique per study, minimal.
    """
    h = hashlib.sha256(study_uid.encode()).hexdigest()[:6].upper()
    return f"{prefix}{h}"

def record_modification(
    ds,
    tag,
    old_value,
    reason="COERCE",
    modifying_operator=None,
    modifying_system=None,
):
    """Write modification to Original Attributes Sequence (0400,0561).

    DICOM PS3.3 C.12.1: Original Attributes Sequence records what was changed,
    by whom, when, and why. Bridge is the single point of audit  -  server does
    NOT write this tag.

    Structure:
      OriginalAttributesSequence (0400,0561)
        Item:
          AttributeModificationDateTime (0400,0562)
          ModifyingSystem (0400,0563)
          SourceOfPreviousValues (0400,0564)  -  Type 2, may be empty
          ReasonForModification (0400,0565)
          ModifiedAttributesSequence (0400,0550)
            Item: the actual changed tag with its OLD value

    Args:
        ds: pydicom Dataset (modified in-place)
        tag: DICOM tag tuple, e.g. (0x0010, 0x0020)
        old_value: original value before modification
        reason: DICOM CID 7050 code (COERCE, CORRECT, etc.)
        modifying_operator: who made the change (DIMSE AE Title for C-STORE, else "DIMSE")
        modifying_system: (0400,0563) system that applied the change - the
            bridge's configured AE title. PS3.3 C.12.1 wants the system
            identified, so the caller supplies it; a literal here would
            disagree with the AE title the bridge actually associates under.
    """
    from datetime import datetime

    from pydicom.dataelem import DataElement

    if not modifying_system:
        # (0400,0563) is Type 1 (PS3.3 C.12.1). An empty value would be a
        # malformed audit entry, and a silent default would hide the miswiring
        # that caused it - refuse the write instead.
        raise ValueError("modifying_system is required for ModifyingSystem (0400,0563)")

    # -- Original Attributes Sequence item (who/when/why) --
    # DICOM PS3.3 Table C.12.1.1.9-1: Original Attributes Macro
    attr_item = Dataset()
    attr_item.SourceOfPreviousValues = ""  # (0400,0564) Type 2  -  may be empty
    attr_item.AttributeModificationDateTime = datetime.now().strftime(
        "%Y%m%d%H%M%S"
    )  # (0400,0562) Type 1
    attr_item.ModifyingSystem = modifying_system  # (0400,0563) Type 1
    attr_item.ReasonForTheAttributeModification = (
        reason  # (0400,0565) Type 1  -  CID 7050: COERCE
    )
    # (0400,0566) ModifyingOperator is NOT a standard attribute: the Attribute
    # Modification macro's "who" is (0400,0562) DateTime, (0400,0563) Modifying
    # System and (0400,0564) Source of Previous Values (PS3.3 C.12.1.1.9.1),
    # and (0400,0566) is absent from the PS3.6 registry (verified against the
    # installed pydicom 3.0.2 dictionary). Group 0400 is even, so it cannot
    # carry a private element either (PS3.5 7.8.1). Writing it produced a tag
    # no reader can resolve, so the operator travels in ModifyingSystem above.

    # -- ModifiedAttributesSequence (0400,0550)  -  WHAT was changed --
    # Type 1. Single Item containing the modified tag with its OLD value.
    # Preserve VR from original element, fallback to LO (Long String).
    vr = ds[tag].VR if tag in ds else "LO"
    mod_attr = Dataset()
    # PS3.3 C.12.1.1.9.1: the item holds the PREVIOUS value. `old_value or ""`
    # replaced every falsy previous value - 0, 0.0, False - with an empty
    # string, so an audit entry for a changed numeric attribute recorded "no
    # previous value" instead of the zero it really held. Only None (no value
    # at all) becomes empty.
    mod_attr[tag] = DataElement(tag, vr, "" if old_value is None else old_value)
    mod_seq = Sequence()
    mod_seq.append(mod_attr)
    attr_item.ModifiedAttributesSequence = mod_seq

    # Add to main dataset
    if (0x0400, 0x0561) not in ds:
        ds.OriginalAttributesSequence = Sequence()
    ds.OriginalAttributesSequence.append(attr_item)

def sanitize_dataset(
    ds,
    fix_patient_id=True,
    fix_patient_name=True,
    id_prefix="AUTOPAT_",
    name_prefix="Anonymous^",
    write_audit=True,
    study_uid=None,
    modifying_system=None,
):
    """Sanitize empty DICOM Type 2 fields. Returns list of modifications.

    Args:
        ds: pydicom Dataset (modified in-place)
        fix_patient_id: generate PatientID if empty
        fix_patient_name: generate PatientName if empty
        id_prefix: prefix for generated PatientID
        name_prefix: prefix for generated PatientName
        write_audit: if True, record modification in (0400,0561) now.
                     If False, skip  -  caller must apply record_modification later
                     (used to defer audit trail writing off C-STORE hot-path).
        study_uid: if provided, generates deterministic PatientID/Name from
                   StudyInstanceUID. All SOPs in the same study get the same
                   PatientID  -  preserving the DICOM patient-study relationship
                   and preventing SQLite performance degradation.
        modifying_system: (0400,0563) value for the audit entry - the bridge's
                   configured AE title, threaded to record_modification().

    Returns:
        list of (tag, old_value, new_value) tuples for logging
    """
    if write_audit and not modifying_system:
        # Validated BEFORE any field is overwritten: mutating first and failing
        # inside record_modification would leave the dataset changed with no
        # audit entry carrying the original empty value, so a caller retrying
        # with a valid title would record a false "old" value.
        raise ValueError("modifying_system is required for ModifyingSystem (0400,0563)")

    modifications = []

    # PatientID (0010,0020)  -  Type 2
    pid = ds.get((0x0010, 0x0020))
    if not pid or not pid.value:
        # Two consumers with different jobs: the audit entry records what the
        # attribute ACTUALLY held - the empty string for an absent or empty
        # Type 2 field (PS3.3 C.2.2) - so the tuple carries `old`, never a
        # placeholder. The "(empty)" substitution belongs to the LOG line in
        # cstore.py, which needs a readable placeholder the audit must not
        # record. Recording "(empty)" in the Modified Attributes Sequence
        # would state a value the attribute never had.
        old = str(pid.value) if (pid and pid.value) else ""
        if fix_patient_id:
            if study_uid:
                new_id = generate_patient_id_from_study(study_uid, id_prefix)
            else:
                new_id = generate_patient_id(id_prefix)
            ds.PatientID = new_id
            if write_audit:
                record_modification(
                    ds, (0x0010, 0x0020), old, modifying_system=modifying_system
                )
            modifications.append(((0x0010, 0x0020), old, new_id))
        else:
            raise ValueError("PatientID is empty and fix_patient_id is disabled")

    # PatientName (0010,0010)  -  Type 2
    pname = ds.get((0x0010, 0x0010))
    if not pname or not pname.value:
        old = str(pname.value) if (pname and pname.value) else ""
        if fix_patient_name:
            if study_uid:
                new_name = generate_patient_name_from_study(study_uid, name_prefix)
            else:
                new_name = generate_patient_name(name_prefix)
            ds.PatientName = new_name
            if write_audit:
                record_modification(
                    ds, (0x0010, 0x0010), old, modifying_system=modifying_system
                )
            modifications.append(((0x0010, 0x0010), old, new_name))
        else:
            raise ValueError("PatientName is empty and fix_patient_name is disabled")

    return modifications

