"""DIMSE Association Tracker  -  nginx-way.

Tracks active DICOM associations: AE title, IP, studies received, instance counts.
Used by C-STORE handler and association event handlers to provide
administrator-visible INFO logs without per-SOP spam.

Thread-safe via threading.Lock. Cleanup on association release.
"""

import logging
import threading

# -- Association info ----------------------------------------------------

class AssocInfo:
    """Per-association tracking state."""

    __slots__ = ("address", "ae_title", "instance_count", "studies")

    def __init__(self, ae_title: str, address: str):
        self.ae_title = ae_title
        self.address = address
        # studies: dict[study_uid -> {'modality': str, 'count': int}]
        # No PatientID here: the summary this feeds only prints modality and
        # counts, so a raw identifier would be PHI held in memory for nothing.
        self.studies: dict[str, dict] = {}
        self.instance_count = 0

# Global registry: association_id -> AssocInfo
_assoc_registry: dict[int, AssocInfo] = {}
_assoc_lock = threading.Lock()

# -- Public API ----------------------------------------------------------

def register_assoc_accepted(assoc_id: int, ae_title: str, address: str) -> None:
    """Register a new DICOM association. Logs INFO on first connection.

    Called from evt.EVT_ACCEPTED handler.
    """
    with _assoc_lock:
        if assoc_id in _assoc_registry:
            return  # Already registered (should not happen)
        _assoc_registry[assoc_id] = AssocInfo(ae_title, address)

    # Counter is bumped outside the lock: prometheus_client objects are
    # already thread-safe and this is not on the C-STORE hot path.
    try:
        associations_total.labels(role="from", ae=ae_label(ae_title)).inc()
    except Exception:
        pass

    # : log outside lock to avoid holding it during I/O.
    # Mask AE title if it looks like a hostname (long, noisy).
    ae_display = ae_title if len(ae_title) <= 16 else ae_title[:16]
    logging.info(
        "[DIMSE] Association accepted: AE=%s from %s",
        ae_display,
        address,
    )

def register_assoc_released(assoc_id: int) -> None:
    """Release association and log summary.

    Called from evt.EVT_RELEASED or evt.EVT_ABORTED handler.
    """
    with _assoc_lock:
        info = _assoc_registry.pop(assoc_id, None)

    if info is None:
        return

    studies_count = len(info.studies)
    instances = info.instance_count
    ae = info.ae_title[:16] if len(info.ae_title) > 16 else info.ae_title

    if studies_count == 0:
        # NOTE: fires for EVERY association, including C-MOVE/C-FIND ones
        # that never carry C-STORE. "(no instances received)" is accurate
        # for all operation types (field: "no C-STORE received" read like
        # the bridge expected a C-STORE on a C-MOVE association).
        logging.info(
            "[DIMSE] Association released: AE=%s (no instances received)",
            ae,
        )
        return

    # Build study summary: "CTx432, SRx2" (ASCII only  -  cp1251-safe)
    study_parts = []
    for study_uid, sinfo in info.studies.items():
        mod = sinfo.get("modality", "??")
        cnt = sinfo.get("count", 0)
        study_parts.append(f"{mod}x{cnt}")

    logging.info(
        "[DIMSE] Association released: AE=%s studies=%d instances=%d [%s]",
        ae,
        studies_count,
        instances,
        ", ".join(study_parts),
    )

def record_cstore(assoc_id: int, study_uid: str, modality: str) -> bool:
    """Record a C-STORE instance in the association tracker.

    Returns True if this is the FIRST instance for this study_uid
    (caller should log INFO about new study).
    """
    with _assoc_lock:
        info = _assoc_registry.get(assoc_id)
        if info is None:
            return False  # Association not tracked (should not happen)

        # Count the instance even when the dataset names no study. A C-STORE
        # always carries a SOP Instance UID, but the Study Instance UID is a
        # separate element a nonconforming sender can omit; returning early
        # left `instance_count` at zero, so the release log reported "no
        # instances received" for an association that had stored several.
        info.instance_count += 1

        # The study UID only decides whether a study bucket is updated. An
        # unnamed study is counted but never bucketed: keying a bucket on ""
        # would merge every anonymous instance into one phantom study.
        if not study_uid:
            return False

        if study_uid not in info.studies:
            info.studies[study_uid] = {
                "modality": modality or "??",
                "count": 1,
            }
            return True  # First instance of this study
        else:
            info.studies[study_uid]["count"] += 1
            return False  # Already tracking this study

# ---------------------------------------------------------------------------
# Bridge: commit_tracker
# ---------------------------------------------------------------------------

"""CommitTracker - async Storage Commitment resolution (N-EVENT-REPORT, Stage 2).

nginx-way: N-ACTION is fire-and-forget. A background worker resolves each
commitment batch once ALL referenced SOPs are stored OR the hard deadline
(default 300s) passes; unconfirmed SOPs at deadline are reported as failures
(EventTypeID=2) so the modality keeps its local copy.

Backpressure is structural (single worker, fire-and-forget dispatch inside the
DIMSE reactor) - no cap / 0xA700 is introduced.

Decoupled via three injected callables so this module is unit-testable without
  a live DICOM/HTTP environment:
  verify(sop_class, sop_uid) -> bool    stored/confirmed?
  report(host, port, ae, tx_uid, event_type, ok, failed)
  resolve(job) -> None                  how the batch becomes a verdict

The third is what the 2409 migration adds. It defaults to the local
heuristic this module has always used (unconfirmed SOPs -> 0x0110), so the
default is byte-for-byte today's behaviour; true-mode supplies a callable
that asks the ORIGIN once and reports the origin's own verdict verbatim.
"""

import json
import logging
import threading
import time

DEFAULT_DEADLINE_SEC = 300.0
DEFAULT_RESOLVE_INTERVAL = 5.0

# Wall-clock budget for ONE batch's verification walk inside a single tick.
# `verify()` may be a round trip to the origin, and the tracker has exactly one
# worker: an unbounded walk over a large batch delayed every other peer past
# its own deadline. 30 s is well inside the default 300 s batch deadline, so a
# healthy origin never hits it, while a sick one costs at most this much before
# the remaining SOPs are reported as unconfirmed.
DEFAULT_VERIFY_BUDGET_SEC = 30.0

# Delivery attempts per batch before the verdict is abandoned. One attempt is
# not enough (the peer may be restarting) and an unbounded retry is a DoS: the
# tracker's single worker ticks every `interval`, and each N-EVENT-REPORT burns
# acse + network + dimse timeouts before it fails, so one dead peer starves
# every other batch FOREVER. 5 attempts at the default 5 s interval covers
# roughly half a minute of a restarting peer; PS3.4 J.3.3.1 makes the report
# the result, so a batch that cannot be reported is abandoned loudly rather
# than retried into the heat death of the universe.
MAX_REPORT_ATTEMPTS = 5

# Failure Reason (0008,1197) for an SOP never confirmed by the deadline:
# 0110H Processing Failure (PS3.3 C.14.1.1). 0111H is not an enumerated
# Failure Reason - it exists only as an N-CREATE status in PS3.7.
REASON_UNCONFIRMED = 0x0110

# R10: how long an ABANDONED row is kept for inspection before it is deleted.
# An abandoned verdict has already cost MAX_REPORT_ATTEMPTS associations and
# can never be delivered, so keeping it forever only grows the table and the
# inspection list with every dead peer. A day is long enough to read the
# ERROR line that came with it; `abandoned_at` is what the sweep measures
# against, so the retention is independent of the job's own deadline.
ABANDONED_RETENTION_SEC = 24 * 3600.0

def _pair(item):
    """One `(sop_class, sop_uid)` tuple from a persisted JSON pair.

    A tuple, not a list: `pending` is a SET of these, so the elements have to
    be hashable, and the comparison against `job.sops` (built from tuples)
    would otherwise never match.
    """
    sop_class, sop_uid = item
    return (sop_class, sop_uid)

def _verdict_to_json(verdict):
    """Serialise a frozen verdict for the row, or None.

    Lists, not tuples: JSON has no tuple, and the shapes are rebuilt by
    `_verdict_from_json`.
    """
    if verdict is None:
        return None
    ok, failed, event_type = verdict
    return [[list(item) for item in ok], [list(item) for item in failed], event_type]

def _verdict_from_json(raw):
    """Rebuild a frozen verdict from its row form (None when unset/unreadable)."""
    if not raw:
        return None
    try:
        data = json.loads(raw)
        ok = [_pair(item) for item in data[0]]
        # A failed entry is (class, uid, reason) - the reason is an int.
        failed = [(item[0], item[1], item[2]) for item in data[1]]
        return (ok, failed, int(data[2]))
    except (ValueError, TypeError, IndexError, KeyError):
        return None

class CommitJob:
    """One N-ACTION Storage Commitment batch awaiting resolution."""

    __slots__ = (
        "abandon_pending",
        "abandoned",
        "abandoned_at",
        "calling_ae",
        "cleanup_pending",
        "deadline",
        "frozen_verdict",
        "host",
        "pending",
        "pending_persisted",
        "port",
        "report_attempts",
        "sops",
        "tx_uid",
        "verdict_persisted",
        "verify_cursor",
    )

    def __init__(self, tx_uid, calling_ae, host, port, sops, deadline):
        self.tx_uid = tx_uid
        self.calling_ae = calling_ae
        self.host = host
        self.port = port
        self.sops = list(sops)  # [(sop_class, sop_uid), ...]
        self.pending = set(sops)  # not-yet-confirmed (cls, uid)
        self.deadline = deadline
        # Size of `pending` as last written to the store. Starts equal to the
        # live set so a freshly registered batch is not rewritten on the first
        # tick for no reason.
        self.pending_persisted = len(self.pending)
        # N-EVENT-REPORT delivery attempts so far (see MAX_REPORT_ATTEMPTS).
        self.report_attempts = 0
        # CC3: the verdict decided on the FIRST delivery attempt, as
        # `(ok, failed, event_type)`. Once set it is what every retry reports:
        # the outcome may not change between attempts.
        self.frozen_verdict = None
        # Whether the row on disk actually carries `frozen_verdict`. A tuple
        # cannot be "not None and unsaved", so the flag is what makes a FAILED
        # verdict write retryable: without it the next tick skipped the write
        # because the verdict was already set, and a restart rebuilt a
        # different verdict from the old `pending` set.
        self.verdict_persisted = False
        # R8: set when the report budget is exhausted and the verdict can never
        # leave this process. Persisted, because a reload that treats an
        # abandoned row as active grants the dead peer another full round of
        # delivery attempts at EVERY restart, on the single commit worker.
        self.abandoned = False
        # R10: when the row became abandoned (retention reference point).
        self.abandoned_at = 0.0
        # Where the verification walk resumes. `pending` is a SET, so `list()`
        # over it is not a stable order: a batch whose head never confirms
        # re-probed the same SOPs every tick and the tail never got a turn.
        # The cursor is the uid the next tick starts AT; it wraps to the head
        # once the sorted order is exhausted, so an unconfirmed SOP is retried
        # after every pending entry has had one.
        self.verify_cursor = None
        # The ABANDONED state has not reached the row yet (the write raised).
        # The job is out of the working set but must not be eligible for
        # retention: a restart would reload the row as ACTIVE and send the
        # verdict the bridge already gave up on.
        self.abandon_pending = False
        # The verdict WAS delivered and the row delete failed. Kept out of the
        # working set (it must never be reported again) and retried from the
        # cleanup list, so a restart does not re-send a verdict the modality
        # already received.
        self.cleanup_pending = False

class CommitTracker:
    """Tracks commitment batches; resolves and reports them asynchronously.

    Persistence (M7): a batch registered by an N-ACTION is a promise to the
    modality that an N-EVENT-REPORT will follow, and PS3.4 J.3.3.1 makes that
    report the result. Holding the promise only in `_jobs` meant a restart
    lost every outstanding batch: the transaction UID stayed active on the
    modality's side forever and the commitment never resolved. The jobs are
    therefore mirrored into a SQLite table, the same store the C-MOVE state
    machine already uses (`move_jobs.db`, via `SharedDb.locked()`), and a
    tracker constructed with a `db` reloads the pending rows before its loop
    starts.

    The dict stays the working set: it is what `_tick` iterates and what the
    tests inspect, and a row only exists to survive a process restart.
    """

    def __init__(
        self,
        verify,
        report,
        resolve=None,
        interval=DEFAULT_RESOLVE_INTERVAL,
        deadline_sec=DEFAULT_DEADLINE_SEC,
        shutdown=None,
        now=time.time,
        db=None,
        verify_budget_sec=DEFAULT_VERIFY_BUDGET_SEC,
    ):
        self._verify = verify  # verify(sop_class, sop_uid) -> bool
        self._report = report  # report(...)
        # resolve(job) -> None; None keeps the local heuristic below. The
        # callable owns sending the N-EVENT-REPORT for its batch.
        self._resolve_fn = resolve
        self._interval = interval
        self._deadline_sec = deadline_sec
        # CC2: wall-clock budget for ONE job's verification walk in a tick.
        # Each `_verify` can be a network round trip to the origin; without a
        # budget a large batch held the single commit worker past every other
        # peer's deadline.
        self._verify_budget_sec = verify_budget_sec
        self._jobs = {}
        # R10: abandoned batches, kept OUT of the working set. They are never
        # ticked and never counted as pending - only inspected - so keeping
        # them in `_jobs` made `pending_count()` grow for every dead peer.
        # Bounded by `purge_abandoned`.
        self._abandoned = {}
        # Delivered batches whose row delete failed, and batches whose
        # abandonment write failed. Kept out of `_jobs` because they must never
        # be reported again - only their ROW needs another attempt.
        self._cleanup = {}
        self._abandon_pending = {}
        self._lock = threading.Lock()
        self._stop = shutdown if shutdown is not None else threading.Event()
        self._now = now  # injectable clock for tests
        self._db = db
        if db is not None:
            self._create_schema()
            self._reload()

    # ---- persistence -----------------------------------------------------

    def _create_schema(self):
        """Create the batch table.

        `pending` is stored as JSON rather than as a second table: the column
        is read and written whole, never queried by SOP, and a normalised
        table would add a join and a row-set to keep consistent for no
        question anyone asks. `sops` is stored whole too - the report needs
        the COMPLETE referenced set (J.3.3.1.2), so a batch is never resolved
        from a partial list.
        """
        with self._db.locked() as conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS commit_jobs ("
                "  tx_uid TEXT PRIMARY KEY,"
                "  calling_ae TEXT NOT NULL,"
                "  host TEXT NOT NULL,"
                "  port INTEGER NOT NULL,"
                "  sops TEXT NOT NULL,"  # JSON [[cls, uid], ...]
                "  pending TEXT NOT NULL,"  # JSON [[cls, uid], ...]
                "  deadline REAL NOT NULL,"
                "  frozen TEXT,"  # JSON [ok, failed, event_type] or NULL
                "  abandoned INTEGER NOT NULL DEFAULT 0,"
                "  abandoned_at REAL NOT NULL DEFAULT 0,"
                "  report_attempts INTEGER NOT NULL DEFAULT 0,"
                "  cleanup_pending INTEGER NOT NULL DEFAULT 0"
                ")"
            )
            conn.commit()
        # A table created before these columns existed gains them in place.
        # Without `frozen` a restart rebuilt a possibly different verdict and
        # reported it as if it were the one already sent; without `abandoned`
        # every reload treated a dead peer's parked batch as active and gave
        # it five more delivery rounds on the single worker at every restart.
        for column, ddl in (
            ("frozen", "TEXT"),
            ("abandoned", "INTEGER NOT NULL DEFAULT 0"),
            ("abandoned_at", "REAL NOT NULL DEFAULT 0"),
            # Without the attempt count a restart handed a dead peer a fresh
            # MAX_REPORT_ATTEMPTS budget, on the single commit worker.
            ("report_attempts", "INTEGER NOT NULL DEFAULT 0"),
            # A delivered verdict whose row delete failed has to stay
            # findable, or a restart re-sends a report the modality already
            # received.
            ("cleanup_pending", "INTEGER NOT NULL DEFAULT 0"),
        ):
            try:
                with self._db.locked() as conn:
                    conn.execute(f"ALTER TABLE commit_jobs ADD COLUMN {column} {ddl}")
                    conn.commit()
            except Exception:
                # The column already exists (the normal case after the first
                # upgrade). Any other failure surfaces on the first read/write.
                pass

    def _reload(self):
        """Restore the pending batches left by a previous process.

        Rows are restored verbatim, INCLUDING their original deadline: a
        batch whose deadline passed while the bridge was down is resolved on
        the first tick, which is the correct answer - the modality is still
        waiting, and "everything unconfirmed by then" is what the deadline
        means. Rewriting the deadline on reload would extend a promise the
        SCP already made.
        """
        restored = 0
        abandoned = 0
        cleaned = 0
        with self._db.locked() as conn:
            rows = conn.execute(
                "SELECT tx_uid, calling_ae, host, port, sops, pending, deadline,"
                " frozen, abandoned, abandoned_at, report_attempts, cleanup_pending"
                " FROM commit_jobs"
            ).fetchall()
        for (
            tx_uid,
            calling_ae,
            host,
            port,
            sops,
            pending,
            deadline,
            frozen,
            abandoned_flag,
            abandoned_at,
            report_attempts,
            cleanup_flag,
        ) in rows:
            try:
                sop_pairs = [_pair(item) for item in json.loads(sops)]
                pending_pairs = {_pair(item) for item in json.loads(pending)}
                job = CommitJob(
                    tx_uid,
                    calling_ae,
                    host,
                    int(port),
                    sop_pairs,
                    float(deadline),
                )
                job.pending = pending_pairs
                job.pending_persisted = len(pending_pairs)
                # R10: the verdict already decided travels with the row, so a
                # restart re-sends the SAME result instead of computing a new
                # one that may contradict what the SCM was told.
                job.frozen_verdict = _verdict_from_json(frozen)
                job.verdict_persisted = job.frozen_verdict is not None
                if cleanup_flag:
                    # The verdict was DELIVERED and only the row delete failed.
                    # Reloading it as active re-sent a report the modality
                    # already acknowledged; the row is a cleanup chore, not a
                    # commitment, so it goes straight to the retry list.
                    job.cleanup_pending = True
                    self._cleanup[job.tx_uid] = job
                    cleaned += 1
                    continue
                if abandoned_flag:
                    # R10: an abandoned row stays abandoned. Reloading it as
                    # active would grant the dead peer another MAX_REPORT_ATTEMPTS
                    # rounds on the single commit worker at every restart; it
                    # would also be counted as pending forever.
                    job.abandoned = True
                    job.report_attempts = MAX_REPORT_ATTEMPTS
                    # R10: the retention clock travels with the row; without
                    # it a reloaded batch read as age 0 and was never purged.
                    job.abandoned_at = float(abandoned_at or 0.0)
                    job.report_attempts = max(
                        int(report_attempts or 0), MAX_REPORT_ATTEMPTS
                    )
                    self._abandoned[tx_uid] = job
                    abandoned += 1
                    continue
            except (ValueError, TypeError) as e:
                # A row that cannot be read is not a reason to refuse the
                # whole reload: the other batches are still deliverable, and
                # this one is named in the log rather than silently dropped.
                logging.error(
                    "[COMMIT] tx=%s: unreadable persisted batch (%s) - skipped",
                    tx_uid,
                    e,
                )
                continue
            self._jobs[tx_uid] = job
            # The attempt count survives the restart. Restoring it as zero gave
            # an unavailable peer a fresh MAX_REPORT_ATTEMPTS budget at every
            # restart of an otherwise healthy bridge.
            job.report_attempts = max(0, int(report_attempts or 0))
            restored += 1
        if restored:
            logging.warning(
                "[COMMIT] recovered %d outstanding batch(es) from the previous "
                "session; the modality is still waiting for their verdicts",
                restored,
            )
        if abandoned:
            logging.error(
                "[COMMIT] %d recovered batch(es) were already abandoned - their "
                "verdicts can no longer be delivered and are kept for inspection",
                abandoned,
            )
        if cleaned:
            logging.warning(
                "[COMMIT] %d recovered batch(es) were delivered but their row "
                "delete failed - retrying the delete, NOT the report",
                cleaned,
            )

    def purge_abandoned(self, max_age_sec=ABANDONED_RETENTION_SEC, now=None):
        """Delete abandoned rows older than `max_age_sec`; return the count.

        R10: nothing removed an abandoned row, so the table and the inspection
        list grew with every dead peer. The row's own deadline is NOT the
        reference point - it may be days old when a long pause finally exhausts
        the report budget - so the age is measured from `abandoned_at`, which
        `_park_undelivered` stamps.
        """
        if self._db is None:
            return 0
        cutoff = (self._now() if now is None else now) - max_age_sec
        removed = 0
        with self._lock:
            # A job whose abandonment write never landed is NOT in `_abandoned`
            # and its row still says active. If it were swept by age here the
            # verdict's only remaining trace would be gone while a restart
            # could still re-deliver it, so it is excluded by construction:
            # only `_abandoned` entries are candidates, and `_retry_settled_rows`
            # moves a job there once the write succeeds.
            stale = [
                tx
                for tx, job in self._abandoned.items()
                if getattr(job, "abandoned_at", 0.0) <= cutoff
            ]
        for tx in stale:
            try:
                with self._db.locked() as conn:
                    cur = conn.execute(
                        "DELETE FROM commit_jobs" " WHERE tx_uid = ? AND abandoned = 1",
                        (tx,),
                    )
                    conn.commit()
                    removed += cur.rowcount or 0
                # Drop the in-memory entry only AFTER the row is gone. The
                # old order deleted it first, so a failed DELETE left the row
                # on disk with nobody to find it on the next sweep.
                with self._lock:
                    self._abandoned.pop(tx, None)
            except Exception as e:
                # A failed delete leaves the row AND the in-memory entry for
                # the next sweep; it must not abort the retention pass for
                # the other batches.
                logging.error(
                    "[COMMIT] tx=%s: abandoned row could not be purged (%s)",
                    tx,
                    e,
                )
        if removed:
            logging.info(
                "[COMMIT] purged %d abandoned batch(es) older than %.0fs",
                removed,
                max_age_sec,
            )
        return removed

    def _persist(self, job):
        if self._db is None:
            return
        with self._db.locked() as conn:
            conn.execute(
                "INSERT OR REPLACE INTO commit_jobs"
                " (tx_uid, calling_ae, host, port, sops, pending, deadline,"
                "  frozen, abandoned, abandoned_at, report_attempts,"
                "  cleanup_pending)"
                " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    job.tx_uid,
                    job.calling_ae,
                    job.host,
                    int(job.port),
                    json.dumps([list(item) for item in job.sops]),
                    json.dumps(sorted(list(item) for item in job.pending)),
                    float(job.deadline),
                    # R10: the verdict travels with the row. A restart after a
                    # report was sent but its response was lost must re-send
                    # the SAME result, not a freshly computed one that may
                    # differ for the same transaction.
                    (
                        json.dumps(_verdict_to_json(job.frozen_verdict))
                        if job.frozen_verdict is not None
                        else None
                    ),
                    1 if job.abandoned else 0,
                    float(getattr(job, "abandoned_at", 0.0)),
                    int(job.report_attempts),
                    1 if job.cleanup_pending else 0,
                ),
            )
            conn.commit()

    def _forget(self, tx_uid):
        if self._db is None:
            return
        with self._db.locked() as conn:
            conn.execute("DELETE FROM commit_jobs WHERE tx_uid = ?", (tx_uid,))
            conn.commit()

    def register(self, tx_uid, calling_ae, host, port, sops):
        """Register an N-ACTION batch for async resolution. Fire-and-forget.

        `_persist` can raise (disk full, locked or corrupt database). Persist
        BEFORE the in-memory registration: a failed persist then leaves BOTH
        the on-disk row and the in-memory `_jobs` entry from an EARLIER
        registration for the same tx_uid untouched. The old order overwrote
        `_jobs[tx_uid]` first, so a failed persist and the following rollback
        `pop` removed the EARLIER job from the working set while its row
        survived - `_tick` then never resolved that commitment until a
        restart. Persisting first also means `_tick` can never observe a job
        whose persist failed and push an N-EVENT-REPORT for a request the
        caller is about to answer 0x0110. The caller's `except Exception`
        turns the failure into a clean 0x0110.

        `_forget()` is deliberately NOT used here: it runs a DELETE, and after
        a failed INSERT there may be a row from an earlier registration for the
        same tx_uid that must survive - deleting it would lose a commitment the
        SCU was already told about.

        CC1: the ROW and its in-memory owner move together. `_persist` runs
        under the same lock that publishes the job, so a concurrent `_tick`
        never sees the row of one registration paired with the object of
        another, and a crash cannot leave a row whose owner nobody knows. The
        lock is a plain `threading.Lock` held across an SQLite write - the
        store has its own lock and no path takes the two in the other order.
        """
        deadline = self._now() + self._deadline_sec
        job = CommitJob(tx_uid, calling_ae, host, port, sops, deadline)
        with self._lock:
            # R6: a Transaction UID names ONE transaction (PS3.4 J.3.2). A
            # second N-ACTION carrying it is a protocol error, not a retry: the
            # SCU reused an identifier the SCP has already acknowledged, and
            # accepting it would replace the first batch's row and in-memory
            # job - the first N-EVENT-REPORT would never be sent, silently.
            # The check and the registration are one locked step so two
            # concurrent requests cannot both pass it.
            if tx_uid in self._jobs:
                raise ValueError(
                    f"Transaction UID {tx_uid} is already active - the SCU "
                    "must use a new UID for a new request"
                )
            # A settled batch's row write is still PENDING (its DELETE or its
            # abandonment UPDATE failed and is retried by `_retry_settled_rows`).
            # Accepting a registration now would let that retry land on top of
            # the new row: the abandonment would overwrite an accepted
            # transaction, or the cleanup DELETE would erase it, and a restart
            # then lost the commitment the SCU had been told about. The UID is
            # still owned by the old batch until its row write succeeds.
            if tx_uid in self._abandon_pending or tx_uid in self._cleanup:
                raise ValueError(
                    f"Transaction UID {tx_uid} is still owned by a settled "
                    "batch whose row write has not completed - retry later"
                )
            self._persist(job)
            self._jobs[tx_uid] = job

    # ---- resolution ------------------------------------------------------

    def _build_verdict(self, job):
        """Decide the batch's verdict ONCE: `(ok, failed, event_type)`.

        Called on the first delivery attempt and stored on the job, so every
        retry reports the SAME outcome. Recomputing per attempt meant a SOP
        confirmed (or a report that failed and was retried) between attempts
        could change what the modality had already been told - and for the
        success/failure split that is a contradiction, not a retry.
        """
        ok = []
        failed = []
        for sop_class, sop_uid in job.sops:
            if (sop_class, sop_uid) in job.pending:
                failed.append((sop_class, sop_uid, REASON_UNCONFIRMED))
            else:
                ok.append((sop_class, sop_uid))
        event_type = 1 if not failed else 2  # success / complete-with-failures
        return (ok, failed, event_type)

    def _park_undelivered(self, job):
        """Keep an undelivered verdict durable (CC4).

        The job leaves the working set so it stops blocking the single commit
        worker, but its ROW is kept: it is the record that these SOPs were
        never confirmed and that no N-EVENT-REPORT ever reached the modality.
        Deleting it erased the only trace of the outcome.

        R10: `abandoned_at` is stamped here, because this is the instant the
        row becomes eligible for retention - the job's own deadline may be days
        older than the moment the report budget finally ran out.

        Returns True when the row now says "abandoned". A False return means an
        ACTIVE row survived the give-up, which a restart would reload as a
        commitment still to deliver - so the caller must keep the job in the
        write-retry list rather than treat it as parked.
        """
        job.abandoned_at = self._now()
        try:
            self._persist(job)
        except Exception as e:
            logging.error(
                "[COMMIT] tx=%s: undelivered verdict could not be recorded "
                "(%s) - the row stays active and the write is retried without "
                "another report",
                job.tx_uid,
                e,
            )
            return False
        return True

    def _resolve(self, job):
        """Send one N-EVENT-REPORT for the batch.

        The mode branch is here, at the single point where a batch becomes a
        verdict: a supplied `resolve` callable owns the whole resolution
        (true-mode asks the origin and reports its answer), and the default
        is the local heuristic that has always run.

        Returns True when the verdict was delivered. A failed delivery must NOT
        retire the job: the modality was never told the outcome, so discarding
        it lost the commitment silently (PS3.4 J.3.3.1 - the N-EVENT-REPORT IS
        the result).
        """
        if self._resolve_fn is not None:
            try:
                self._resolve_fn(job)
                return True
            except Exception as e:
                logging.error("[COMMIT] resolve for tx=%s failed: %s", job.tx_uid, e)
                return False

        # CC3: report the FROZEN verdict when there is one.
        if job.frozen_verdict is not None:
            ok, failed, event_type = job.frozen_verdict
        else:
            ok, failed, event_type = self._build_verdict(job)
        try:
            delivered = self._report(
                job.host, job.port, job.calling_ae, job.tx_uid, event_type, ok, failed
            )
        except Exception as e:
            logging.error("[COMMIT] report for tx=%s failed: %s", job.tx_uid, e)
            return False
        if delivered is False:
            return False
        # The verdict counters belong here, not in the handler: this is where
        # a SOP actually acquires a verdict. The handler answers 0x0000
        # without checking anything (PS3.4 J.3.2), so counting there would
        # report a verdict the bridge had no evidence for at that instant.
        # Counting BEFORE the report made an undelivered verdict bump the
        # counters on every retry of the same batch, so the metric described
        # attempts rather than outcomes.
        try:
            if ok:
                naction_total.labels(verdict="success").inc(len(ok))
            if failed:
                naction_total.labels(verdict="failed").inc(len(failed))
        except Exception:
            pass
        return True

    def _verify_walk(self, job, verify_deadline):
        """Probe `job.pending` from the resume cursor, within the budget.

        PS3.4 J.3.3.1 makes the report the result, so a SOP the walk never
        reached is reported as unconfirmed - "not stored" - which is a claim
        the bridge has no evidence for. `pending` is a SET, so `list()` over it
        is not a stable order and re-walking it from the start each tick
        examined the same head forever whenever those SOPs did not confirm.

        The walk therefore resumes at the cursor and wraps once: every pending
        SOP gets a turn before any of them gets a second one.
        """
        ordered = sorted(job.pending)
        if not ordered:
            return
        start = 0
        if job.verify_cursor is not None:
            # The next tick resumes AFTER the cursor, not at it: re-probing the
            # boundary SOP costs one round trip per tick for nothing.
            #
            # The cursor is the FULL `(sop_class, sop_uid)` pair, i.e. the same
            # key this list is sorted by. Resuming by UID alone lost every row
            # the UID ordering disagreed with: with the budget consumed by
            # (A, 9), no UID greater than "9" was found, the walk restarted at
            # (A, 9) on every tick, and (B, 1) and (B, 2) were never probed
            # before the deadline - so they were reported "not stored" without
            # the bridge ever having asked.
            for index, item in enumerate(ordered):
                if item > job.verify_cursor:
                    start = index
                    break
            else:
                # Past the tail: wrap to the head, which is what retries the
                # SOPs examined on earlier ticks.
                start = 0
        for offset in range(len(ordered)):
            sop_item = ordered[(start + offset) % len(ordered)]
            if self._now() >= verify_deadline:
                logging.info(
                    "[COMMIT] tx=%s: verification budget reached (%d left "
                    "unverified) - resolving with what is known",
                    job.tx_uid,
                    len(job.pending),
                )
                break
            # The cursor advances BEFORE the probe, so a probe that fails at
            # the tail does not make the next tick start there again.
            job.verify_cursor = sop_item
            sop_class, sop_uid = sop_item
            try:
                confirmed = self._verify(sop_class, sop_uid)
            except Exception as e:
                logging.warning("[COMMIT] verify %s error: %s", sop_uid, e)
                continue
            if not confirmed:
                continue
            # A probe can start inside the window and observe the instance only
            # AFTER it. Counting that as a confirmation tells the modality a
            # SOP is committed when the batch's own deadline said otherwise -
            # so the result is only applied if it arrived in time.
            if self._now() > job.deadline and job.deadline <= verify_deadline:
                logging.info(
                    "[COMMIT] tx=%s: confirmation of %s arrived after the "
                    "deadline - not counted",
                    job.tx_uid,
                    sop_uid,
                )
                continue
            job.pending.discard(sop_item)
        # A cursor past the last uid wraps on the next tick by the `for/else`
        # above; clearing it here would restart mid-set instead.
        if not job.pending:
            job.verify_cursor = None

    def _retry_settled_rows(self):
        """Retry only the ROW writes for batches whose verdict is settled.

        `_park_undelivered` and `_forget` both run after the job left `_jobs`,
        and both can fail. Losing either left an ACTIVE row behind, which a
        restart reloaded as a commitment still to deliver - so the modality was
        sent the same verdict again, or one the bridge had already given up on.
        """
        with self._lock:
            pending_abandon = list(self._abandon_pending.items())
            pending_cleanup = list(self._cleanup.items())
        for tx_uid, job in pending_abandon:
            # The ownership test and the write are ONE locked step. Testing
            # ownership outside the lock let `register()` accept the same UID
            # between the two, and the retry's `_persist(job)` then replaced the
            # NEW row with the old batch's abandoned one - the freshly accepted
            # transaction was silently turned into an abandonment, and the SCU
            # never received the verdict for the request it had just sent.
            # `register()` refuses a UID that is still in `_abandon_pending`, so
            # holding the lock across both is sufficient.
            with self._lock:
                try:
                    # The report is NOT re-sent: only the row write is retried.
                    self._persist(job)
                except Exception as e:
                    logging.error(
                        "[COMMIT] tx=%s: abandonment still not recorded (%s) - "
                        "the row stays active for now",
                        tx_uid,
                        e,
                    )
                    continue
                self._abandon_pending.pop(tx_uid, None)
                self._abandoned[tx_uid] = job
            logging.error("[COMMIT] tx=%s: abandonment recorded on a retry", tx_uid)
        for tx_uid, job in pending_cleanup:
            # Ownership and the DELETE are ONE locked step. Checking the owner
            # and releasing the lock let a `register()` for the same UID
            # persist a NEW row in between, and the retry then deleted it - a
            # restart lost an accepted transaction the SCU had already been
            # told about. `register()` refuses a UID that is still in
            # `_cleanup`, so holding the lock across both is sufficient.
            with self._lock:
                if tx_uid in self._jobs:
                    self._cleanup.pop(tx_uid, None)
                    logging.info(
                        "[COMMIT] tx=%s was re-registered - dropping the "
                        "pending row delete",
                        tx_uid,
                    )
                    continue
                try:
                    self._forget(tx_uid)
                except Exception as e:
                    logging.error(
                        "[COMMIT] tx=%s: row still not deleted (%s) - retried "
                        "next tick, verdict NOT re-sent",
                        tx_uid,
                        e,
                    )
                    continue
            with self._lock:
                self._cleanup.pop(tx_uid, None)

    def _tick(self):
        # Rows whose verdict is already settled: a delivered report whose row
        # delete failed, and an abandonment that never reached the store. Both
        # are OUT of `_jobs` (they must never be reported again), so they need
        # this separate pass or nothing retries their write.
        self._retry_settled_rows()
        with self._lock:
            jobs = list(self._jobs.values())
        for job in jobs:
            # Verification is bounded: each `_verify` may be a network round
            # trip to the origin, and an unbounded walk over a large batch held
            # the single commit worker past the job's own deadline - delaying
            # every other peer's verdict. The deadline is the job's, because
            # that is the instant its answer stops improving: past it the
            # remaining SOPs are reported as unconfirmed regardless.
            #
            # A FROZEN verdict is never re-examined: the outcome was decided
            # (and, once persisted, is on disk), so the remaining ticks only
            # retry the REPORT. Walking `pending` anyway burned up to
            # `verify_budget_sec` of origin round trips per tick on the single
            # commit worker, for an answer nothing may use any more.
            verify_deadline = min(job.deadline, self._now() + self._verify_budget_sec)
            if job.frozen_verdict is None:
                self._verify_walk(job, verify_deadline)
            # The deadline test reads a FRESH clock. `now` captured at the top
            # of the tick predates every report this tick sent, so a batch due
            # while an earlier (slow) report was in flight looked expired here
            # and was resolved as "everything unconfirmed" without a probe.
            if not job.pending or self._now() >= job.deadline:
                # CC3: the verdict is FROZEN on the first attempt. The report
                # must describe the batch as it stood when the outcome was
                # decided: recomputing it per attempt let a later successful
                # verify (or a late confirmation) change what had already been
                # reported, so the retry could contradict the first try.
                if job.frozen_verdict is None:
                    job.frozen_verdict = self._build_verdict(job)
                # R10: the verdict is durable BEFORE the first report goes
                # out. Memory-only, a crash after the N-EVENT-REPORT left the
                # response lost and the restart rebuilt a verdict from a later
                # `pending` set - so the SAME transaction could be reported
                # twice with different outcomes.
                #
                # The write is keyed on `verdict_persisted`, not on the verdict
                # being absent, and it runs on EVERY attempt until it lands: a
                # single failed write left the verdict in memory, so a guard on
                # `frozen_verdict is None` skipped every later attempt and the
                # row kept arguing from the OLD `pending` set at every restart.
                # With a database the operator asked for durability, so a
                # failed persist WITHHOLDS the report: sending first and
                # crashing before `_forget` left a restart to rebuild a
                # DIFFERENT verdict from a later `pending` set - the same
                # transaction reported twice with different outcomes (PS3.4
                # J.3.3.1: the report IS the result). The job stays in the
                # working set so the next tick retries the persist.
                if self._db is not None and not job.verdict_persisted:
                    try:
                        self._persist(job)
                        job.verdict_persisted = True
                        job.pending_persisted = len(job.pending)
                    except Exception as e:
                        logging.critical(
                            "[COMMIT] tx=%s: frozen verdict still not persisted "
                            "(%s) - report withheld until it is",
                            job.tx_uid,
                            e,
                        )
                        continue
                # Retire the job only once its verdict was actually delivered:
                # dropping it after a failed N-EVENT-REPORT lost the outcome
                # the modality was waiting for.
                #
                # The attempt limit is enforced BEFORE `_resolve`, not after.
                # `_reload()` can restore an active row whose persisted
                # `report_attempts` already reached the limit - the process may
                # have stopped between persisting attempt five and persisting
                # the abandonment - and `_tick` used to send one more report
                # before noticing. A row that has already spent its budget goes
                # straight to the abandonment transition instead.
                if job.report_attempts >= MAX_REPORT_ATTEMPTS:
                    with self._lock:
                        still_ours = self._jobs.get(job.tx_uid) is job
                        if still_ours:
                            del self._jobs[job.tx_uid]
                            self._abandon_pending[job.tx_uid] = job
                    logging.error(
                        "[COMMIT] tx=%s: report attempt limit (%d) already "
                        "spent - abandoning without another report",
                        job.tx_uid,
                        MAX_REPORT_ATTEMPTS,
                    )
                    continue
                if self._resolve(job):
                    # R7/R9: the ownership test, the in-memory removal and the
                    # row delete are ONE locked transition. Releasing the lock
                    # between them let a `register` for the same tx_uid persist
                    # a NEW row that this `_forget` then deleted - the new job
                    # survived in memory but its row did not, so a restart lost
                    # a commitment the SCU had just been told to expect.
                    with self._lock:
                        still_ours = self._jobs.get(job.tx_uid) is job
                        if still_ours:
                            del self._jobs[job.tx_uid]
                            # A failed delete must NOT escape: the verdict is
                            # already delivered, and aborting the tick leaves
                            # the row behind, so the next restart reloads the
                            # batch and sends a SECOND report for a verdict
                            # the modality already received. The delete is
                            # therefore retried from `_cleanup`, which carries
                            # a flag on the row so a restart resumes it too.
                            try:
                                self._forget(job.tx_uid)
                            except Exception as e:
                                job.cleanup_pending = True
                                self._cleanup[job.tx_uid] = job
                                logging.error(
                                    "[COMMIT] tx=%s: verdict delivered but the "
                                    "row could not be deleted (%s) - the delete "
                                    "is retried, the report is NOT re-sent",
                                    job.tx_uid,
                                    e,
                                )
                                try:
                                    self._persist(job)
                                except Exception as pe:
                                    logging.error(
                                        "[COMMIT] tx=%s: cleanup state not "
                                        "recorded (%s) - a restart may re-send "
                                        "the report once",
                                        job.tx_uid,
                                        pe,
                                    )
                    if not still_ours:
                        # Re-registered while the report was in flight: the
                        # NEW job and its row belong to the new request.
                        # Retiring them here would lose a commitment the SCU
                        # was just told to expect.
                        logging.info(
                            "[COMMIT] tx=%s was re-registered during resolution "
                            "- keeping the new job",
                            job.tx_uid,
                        )
                        continue
                else:
                    job.report_attempts += 1
                    # The count is durable as it grows. Without it a restart
                    # restored zero and handed an unavailable peer a FRESH
                    # MAX_REPORT_ATTEMPTS budget at every restart.
                    if self._db is not None:
                        try:
                            self._persist(job)
                        except Exception as e:
                            logging.error(
                                "[COMMIT] tx=%s: attempt count not persisted "
                                "(%s) - a restart resets the budget",
                                job.tx_uid,
                                e,
                            )
                    if job.report_attempts >= MAX_REPORT_ATTEMPTS:
                        # The modality will never hear this verdict: retire
                        # the batch and say so at ERROR level. Keeping it
                        # would re-block the single commit worker on every
                        # tick, delaying every other peer's verdict.
                        logging.error(
                            "[COMMIT] tx=%s: giving up after %d failed "
                            "N-EVENT-REPORT attempts - the verdict was never "
                            "delivered",
                            job.tx_uid,
                            job.report_attempts,
                        )
                        # CC4: an UNDELIVERED verdict is the record of what
                        # happened, not a transient state. The job leaves the
                        # working set (it would otherwise re-block this single
                        # worker on every tick) but its ROW STAYS, so the
                        # outcome survives a restart and can be re-reported or
                        # inspected. Deleting it would erase the only trace
                        # that these SOPs were never confirmed.
                        #
                        # Ownership test, in-memory removal and the ABANDONED
                        # row are ONE locked transition, the same rule `_forget`
                        # follows below. Writing the row after releasing the
                        # lock let a `register` of the same Transaction UID land
                        # in between, and the parked row then overwrote the NEW
                        # request's acknowledged commitment.
                        with self._lock:
                            still_ours = self._jobs.get(job.tx_uid) is job
                            if still_ours:
                                job.abandoned = True
                                del self._jobs[job.tx_uid]
                                # The write can fail (disk full, locked store).
                                # The job is already out of the working set, so
                                # a failed write used to leave an ACTIVE row
                                # that a restart re-delivered and that
                                # `purge_abandoned` would never collect. It is
                                # parked for a WRITE-ONLY retry instead.
                                if not self._park_undelivered(job):
                                    job.abandon_pending = True
                                    self._abandon_pending[job.tx_uid] = job
                                else:
                                    self._abandoned[job.tx_uid] = job
                        if not still_ours:
                            # Re-registered while the verdict was being
                            # abandoned: the NEW job and its row belong to the
                            # new request.
                            logging.info(
                                "[COMMIT] tx=%s was re-registered during "
                                "abandonment - keeping the new job",
                                job.tx_uid,
                            )
                            continue
            elif self._db is not None:
                # Confirmations shrink `job.pending` and that set is what a
                # restart reads back. Rewriting the row on EVERY tick would put
                # a commit on the tracker's own timer for a batch that may sit
                # for the full deadline; the row is written when the set
                # actually shrank, which is the only state change here that a
                # restart can observe.
                #
                # The write only belongs to a job that STILL OWNS its row. A
                # re-registration for the same tx_uid replaces `_jobs[tx_uid]`
                # with a fresh CommitJob and its own row; this tick is then
                # holding a snapshot of the OLD object, and writing it would
                # REPLACE the new job's row with stale SOPs and an old
                # deadline. Drawing on one's own row is exactly what "tie the
                # write to the job object" means here.
                if len(job.pending) != job.pending_persisted:
                    with self._lock:
                        still_ours = self._jobs.get(job.tx_uid) is job
                    if still_ours:
                        # CM1: advance the watermark only once the write has
                        # SUCCEEDED. Setting it first meant a failed persist
                        # was never retried - the batch then looked persisted
                        # for the rest of its life, so a restart brought back
                        # the OLD pending set and re-verified (or re-reported)
                        # SOPs that had already been confirmed.
                        #
                        # One batch's store failure must not abort this tick:
                        # the remaining batches would wait an extra interval
                        # for a reason that has nothing to do with them.
                        try:
                            self._persist(job)
                            job.pending_persisted = len(job.pending)
                        except Exception as e:
                            logging.error(
                                "[COMMIT] tx=%s: pending state not persisted (%s)",
                                job.tx_uid,
                                e,
                            )
                    else:
                        logging.debug(
                            "[COMMIT] tx=%s: re-registered - stale pending "
                            "state not written back",
                            job.tx_uid,
                        )

    # ---- lifecycle -------------------------------------------------------

    def run(self):
        """Background loop; resolve batches on an interval. Blocks until close."""
        while not self._stop.is_set():
            try:
                self._tick()
            except Exception as e:
                logging.error("[COMMIT] tick error: %s", e)
            self._stop.wait(self._interval)

    def pending_count(self):
        with self._lock:
            return len(self._jobs)

    def abandoned_count(self):
        """Undelivered batches kept for inspection (R10). Never ticked."""
        with self._lock:
            return len(self._abandoned)

    def settled_write_count(self):
        """Settled batches whose ROW write is still outstanding.

        A delivered-but-undeleted row and an abandonment that never reached the
        store. Both are retried without another N-EVENT-REPORT.
        """
        with self._lock:
            return len(self._cleanup) + len(self._abandon_pending)

    def close(self):
        self._stop.set()

# ---------------------------------------------------------------------------
# Bridge: http_helpers
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  HTTP helpers: retry, QIDO/WADO/STOW requests (BR-005).

Contains _http_retry (exponential backoff + jitter),
_qido_request, _wado_metadata_request, stow_single_instance, and
_http_status_to_dimse (BR-011).

Auth is handled by nginx reverse proxy  -  no Basic Auth in application code.
"""

import io
import json
import logging
import time
import uuid
from urllib.parse import quote, urlencode, urlsplit, urlunsplit

import httpx
from pydicom import dcmwrite
from pydicom.uid import ExplicitVRLittleEndian

# ---------------------------------------------------------------------------
# 2908: single source of the DICOMweb base URL (clarus_url refactor)
# ---------------------------------------------------------------------------
RETRY_AFTER_MIN_SEC = 5
RETRY_AFTER_MAX_SEC = 300
RETRY_AFTER_DEFAULT_SEC = 30

def dicomweb_base(clarus_url):
    """Return the normalized DICOMweb base URL (no trailing slash).

    Single source for EVERY DICOMweb URL the bridge builds. Config
    validation (clean_code.config.validate_clarus_url) already rejects
    bad schemes and strips the trailing slash; this re-strips for
    defense in depth.
    """
    return clarus_url.rstrip("/")

def dicomweb_origin(clarus_url):
    """Return scheme://netloc of clarus_url (health probe lives at root)."""
    parts = urlsplit(clarus_url)
    return urlunsplit((parts.scheme, parts.netloc, "", "", ""))

def service_base_url(clarus_url, qa_url, qa_view):
    """Pick the DICOMweb base URL for this request.

    `qa_view` is true for associations accepted by the QA AE. AIRA 57.2.1
    defines the expose mechanism as "a webservice endpoint specifically
    configured to provide access to hidden instances", i.e. a separate base
    URL the deployment chooses - NOT a query parameter. Selecting the base URL
    keeps the bridge usable against any DICOMweb server: a server that
    publishes a QA endpoint works, and one that would need a vendor-specific
    parameter is simply pointed at its own endpoint instead.

    Falls back to `clarus_url` when no QA endpoint is configured, so a bridge
    with `expose_port` set but no `qa_url` never silently queries an empty
    base - the caller has already refused to start the QA AE in that case.
    """
    if qa_view and qa_url:
        return dicomweb_base(qa_url)
    return dicomweb_base(clarus_url)

def retry_after_seconds(headers, default=RETRY_AFTER_DEFAULT_SEC):
    """Parse the Retry-After header (seconds or HTTP-date), clamp to [5, 300].

    Garbage / absent header -> fixed 30 s default. HTTP-date values are
    treated conservatively as the default (no clock math in the bridge).
    """
    try:
        value = int(str(headers.get("Retry-After", "")).strip())
    except (ValueError, TypeError, AttributeError):
        return default
    return max(RETRY_AFTER_MIN_SEC, min(RETRY_AFTER_MAX_SEC, value))

# ---------------------------------------------------------------------------
# Bridge: simple retry with fixed backoff (like Orthanc)
# ---------------------------------------------------------------------------
def _http_retry(request_func, max_retries=3, delay=2.0, on_retry=None, deadline=None):
    """Execute HTTP request with fixed backoff  -  3 attempts, 2s delay.

    Retry on: 429, 5xx, timeouts, connection errors.
    No retry on: 4xx except 429 (client errors are permanent).

    `on_retry` is called once per retried attempt. The shared helper serves
    QIDO, WADO, Storage Commitment AND STOW, so it must not own the STOW
    metric: incrementing `stow_retries` here counted a QIDO 503 followed by a
    successful retry as a STOW retry even when no STOW POST ever happened, and
    a QIDO-only deployment then reported STOW retry traffic it never generated.
    Only the two STOW callers pass a counter.

    `deadline` is an absolute `time.monotonic()` instant after which no FURTHER
    attempt may start. httpx's `Timeout(total=...)` bounds each individual
    connect/read/write/pool operation, not the elapsed time of the request, so
    an origin that keeps trickling response bytes within the read timeout holds
    a single POST alive far past the configured budget and the retry loop
    cannot begin another attempt. Checking the deadline here bounds the NUMBER
    of attempts in wall-clock terms; each caller additionally passes a
    shrinking per-attempt timeout built from the same instant.

    Returns httpx.Response, including the final 5xx; raises the last
    transport exception (timeout / connection error).
    """
    last_exception = None

    def _note_retry():
        if on_retry is None:
            return
        try:
            on_retry()
        except Exception:
            pass

    for attempt in range(max_retries + 1):
        if deadline is not None and time.monotonic() >= deadline:
            logging.warning(
                "[RETRY] elapsed-time budget spent before attempt %d/%d",
                attempt + 1,
                max_retries + 1,
            )
            break
        try:
            resp = request_func()
            if resp.status_code == 429:
                if attempt < max_retries:
                    _note_retry()
                    time.sleep(delay)
                    continue
                return resp
            if resp.status_code == 507:
                # 507 Insufficient Storage: NO retry inside _http_retry.
                # Return immediately; the outbox worker applies Retry-After
                # backpressure (clamped 5..300 s) and keeps files pending.
                return resp
            if 400 <= resp.status_code < 500:
                return resp
            if resp.status_code < 500:
                return resp
            logging.warning(
                "[RETRY] HTTP %d on attempt %d/%d",
                resp.status_code,
                attempt + 1,
                max_retries + 1,
            )
            # Final 5xx: return the response so the caller's
            # raise_for_status() / _http_status_to_dimse maps it (5xx ->
            # 0xA700 transient), not a bare Exception that escapes C-FIND
            # generators and mis-maps to fatal.
            if attempt == max_retries:
                return resp
        except (httpx.TimeoutException, httpx.ConnectError) as e:
            logging.warning(
                "[RETRY] %s on attempt %d/%d: %s",
                type(e).__name__,
                attempt + 1,
                max_retries + 1,
                e,
            )
            last_exception = e
        except httpx.TransportError as e:
            # Every other transport failure - a reset mid-response, a read
            # timeout, a truncated body - is equally transient and equally
            # retryable. Letting those escape aborted the batch on the first
            # hiccup while the two named subclasses were retried.
            logging.warning(
                "[RETRY] transport %s on attempt %d/%d: %s",
                type(e).__name__,
                attempt + 1,
                max_retries + 1,
                e,
            )
            last_exception = e

        if attempt < max_retries:
            _note_retry()
            time.sleep(delay)

    raise last_exception or Exception("Max retries exceeded")

# ---------------------------------------------------------------------------
# Bridge: QIDO-RS with retry
# ---------------------------------------------------------------------------
class QidoMalformedBodyError(ValueError):
    """A 2xx QIDO-RS answer whose body is not a DICOM JSON array.

    Separate from an empty result: `[]` means the query ran and matched
    nothing, whereas this means the answer could not be read at all.
    """

# Text marker on a STOW verdict whose outcome is UNKNOWN rather than refused:
# the origin answered 2xx and the bridge could not read its per-SOP verdict.
# The outbox worker must retry such an item without counting an attempt - the
# origin may hold it - instead of burning a retry on a guess.
STOW_UNVERIFIED = "stow-verdict-unreadable"

class QidoPage:
    """One QIDO-RS answer: its rows plus whether the origin left more behind.

    PS3.18 10.6.1.4: an origin may answer FEWER rows than the requested limit
    and still warn that the search did not complete, so `len(rows)` alone can
    never prove an answer exhaustive. The evidence is in the response HEADER,
    which a bare list cannot carry - a C-FIND handler built on the list alone
    reported Success (0x0000, "no further matches exist", PS3.4
    Table C.4.1-1) for searches the origin had explicitly left unfinished.
    """

    __slots__ = ("rows", "more")

    def __init__(self, rows, more):
        self.rows = rows
        self.more = more

    def __iter__(self):
        # Keeps `for row in answer` working where only the rows are wanted.
        return iter(self.rows)

    def __len__(self):
        return len(self.rows)

    def __getitem__(self, index):
        return self.rows[index]

    def __eq__(self, other):
        # `answer == []` is how a caller states "no matches"; the continuation
        # flag is metadata about the answer, not part of what it contains.
        if isinstance(other, QidoPage):
            return self.rows == other.rows
        return self.rows == other

    def __repr__(self):
        return f"QidoPage({self.rows!r}, more={self.more!r})"

def _qido_request(url, params, http_timeout=30, limit=None, offset=0, tls=None):
    """QIDO-RS GET with retry wrapper. Auth by nginx.

    Args:
        limit: if set, adds ?limit=N&offset=M to request (server-side pagination).
        offset: pagination offset, only used when limit is set.
        tls: optional (cert_path, key_path) tuple for mTLS. verify always on.

    The QA view is chosen by the CALLER through the base URL (see
    `qa_base_url`), not by a query parameter: the bridge is a universal
    DICOMweb client, so it must not depend on any one server's private
    parameter for this.

    Returns a `QidoPage`: the row list plus whether the origin reported more
    matches than it returned. A plain list would lose that (PS3.18 10.6.1.4),
    and a module-level "last page" flag would leak between concurrent C-FIND
    generators, which outlive the call that set it.
    """
    if limit is not None:
        params = dict(params)
        params["limit"] = str(limit)
        params["offset"] = str(offset)

    def _do_qido():
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            # PS3.18 8.3.1: space travels as %20, '+' is a literal qp-special.
            qs = urlencode(params, quote_via=quote, safe="")
            return client.get(
                url + "?" + qs,
                headers={"Accept": "application/dicom+json"},
            )
        finally:
            client.close()

    resp = _http_retry(_do_qido)
    resp.raise_for_status()
    # PS3.18 10.6: a search with no matches may answer 204 No Content, which
    # carries no body at all. `json()` on it raises ValueError, and the C-FIND
    # callers only catch httpx errors - a no-match search would surface as a
    # tooling failure instead of an empty result set. The same applies to an
    # intermediary that answers 200 with an empty or non-JSON body.
    # PS3.18 10.6.1: 204 is the explicit "nothing to return" answer and stays
    # an empty result. A 200 with no body is NOT that: the server claimed to
    # answer a query and delivered nothing readable, which is the same failure
    # class as an HTML error page and must not read as "matched nothing".
    if resp.status_code == 204:
        return QidoPage([], False)
    if not resp.content:
        raise QidoMalformedBodyError(f"{url} answered 200 with an empty body")
    try:
        body = resp.json()
    except ValueError:
        # PS3.18 10.6.1: a successful QIDO-RS response is a JSON array. A 200
        # carrying HTML/plain text is a proxy or an error page, not an empty
        # answer - and returning `[]` made it indistinguishable from "the
        # study has no matches", so a caller that counted on a real result got
        # a silent, confidently wrong zero. Signal it as a failure instead.
        raise QidoMalformedBodyError(
            f"{url} answered 200 with a body that is not JSON ({len(resp.content)} bytes)"
        )
    if not isinstance(body, list):
        # A DICOM JSON object where the array belongs is the same class of
        # breakage: it states nothing about matches.
        raise QidoMalformedBodyError(
            f"{url} answered 200 with a JSON {type(body).__name__}, expected an array"
        )
    # PS3.18 10.6.1.4 / Annex F: each match is a DICOM JSON MODEL object. A
    # `null` (or a string, or an array) is not a match, and letting it through
    # moved the failure downstream - the row converters call `.items()` on it
    # outside every C-FIND error handler. `[]` and 204 stay valid empty
    # results; a WRONG row is an unreadable answer.
    for position, row in enumerate(body):
        if not isinstance(row, dict):
            raise QidoMalformedBodyError(
                f"{url} answered 200 with a {type(row).__name__} at row "
                f"{position}, expected a JSON object"
            )
    return QidoPage(body, _qido_continuation(resp, body, limit))

def _qido_continuation(resp, body, limit):
    """Whether the origin says more matches exist beyond this page.

    PS3.18 10.6.1.4: a QIDO-RS origin signals an incomplete answer either by
    a Warning header carrying 299 ("The search did not fully complete") or by
    returning exactly the number of matches that were asked for, which the
    spec defines as possibly containing more. Both are treated the same way:
    the answer is not known to be exhaustive.

    A page SHORTER than the requested limit is exhaustive - the origin had the
    room to send more and did not. With no limit there is no page size to
    compare against, so only the Warning can say anything.
    """
    try:
        warning = str(resp.headers.get("Warning", "") or "")
    except (AttributeError, TypeError):
        warning = ""
    # The 299 warn-code is the first token of a Warning value, e.g.
    # `299 origin "The search did not fully complete"`. Parse the CODE instead
    # of searching the text: a substring test would also match 299 inside a
    # message body or a longer warn-code such as 2990.
    for field_value in warning.split(","):
        token = field_value.strip().split(" ", 1)[0]
        if token == "299":
            return True
    if limit is None:
        return False
    return len(body) >= int(limit)

# ---------------------------------------------------------------------------
# Bridge: WADO-RS metadata lookup with retry
# ---------------------------------------------------------------------------
def _wado_metadata_request(url, http_timeout=30, tls=None):
    """WADO-RS metadata GET with retry wrapper. Auth by nginx."""

    def _do_wado():
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            return client.get(
                url,
                headers={"Accept": "application/dicom+json"},
            )
        finally:
            client.close()

    return _http_retry(_do_wado)

# ---------------------------------------------------------------------------
# 2409: Storage Commitment (PS3.18 13.4/13.5) - POST commit, GET check
# ---------------------------------------------------------------------------
# DICOM JSON keys (Annex J.2), the same ones the server's commitment_pure
# module defines. Only the INSTANCE form of the Referenced SOP Sequence is
# used here: the bridge always has SOP Instance UIDs to commit.
_STC_REFERENCED_SOP_SEQUENCE = "00081199"
_STC_FAILED_SOP_SEQUENCE = "00081198"
_STC_FAILURE_REASON = "00081197"
_STC_REFERENCED_SOP_CLASS_UID = "00081150"
_STC_REFERENCED_SOP_INSTANCE_UID = "00081155"

# The only FailureReason values PS3.3 C.14.1.1 enumerates for the attribute.
# The server emits a subset of these; the table is total so a future server-
# side addition can never push a non-enumerated code onto the DIMSE wire.
_STC_NO_SUCH_SOP = 0x0112
_STC_PROCESSING_FAILURE = 0x0110
_STC_RESOURCE_LIMITATION = 0x0213

_STC_REASON_MAP = {
    "0110": _STC_PROCESSING_FAILURE,
    "0112": _STC_NO_SUCH_SOP,
    "0213": _STC_RESOURCE_LIMITATION,
}

# The full value set PS3.3 C.14.1.1 defines for Failure Reason (0008,1197).
# A code outside it is a defect of the origin and is answered as 0x0110.
_STC_ENUMERATED_REASONS = frozenset(
    {
        _STC_PROCESSING_FAILURE,
        _STC_NO_SUCH_SOP,
        _STC_RESOURCE_LIMITATION,
        0x0122,  # Referenced SOP Class not supported
        0x0119,  # Class / Instance conflict
        0x0131,  # Duplicate SOP Instance
    }
)

# Sentinel on the return value for "the origin has no Commit resource".
# The caller logs the misconfiguration WARN; there is deliberately NO
# fallback to the local path (a silent fallback would mask the wrong knob
# forever).
STC_NO_RESOURCE = "no_commit_resource"

# Sentinel meaning "the origin accepted the request and has not decided yet".
# PS3.18 13.4.3 defines 202 for exactly this: processed (accepted), not
# completed. Reporting it as a verdict - in either direction - is a claim the
# origin never made, so it is carried out as its own signal and the caller
# retries the Check instead of answering the modality.
STC_PENDING = "commit_pending"

def _stc_commit_request(clarus_url, tx_uid, sop_list, http_timeout=30, tls=None):
    """POST one Storage Commitment request and map the verdict.

    Returns ``(committed, failed, sentinel)``:

      committed: [(sop_class, sop_uid)]            - the origin committed these
      failed:    [(sop_class, sop_uid, reason_int)] - enumerated C.14.1.1 codes
      sentinel:  None, or STC_NO_RESOURCE when the origin answered 404/405

    409 (duplicate Transaction UID) replays the stored verdict through ONE
    GET of the same path. Every other non-200 outcome maps to "all failed
    0x0110" - the bridge reports what it knows, it never guesses.

    ``sop_list`` is [(sop_class_uid, sop_instance_uid), ...]; the body is the
    INSTANCE form of the Referenced SOP Sequence (commitment_pure.py).
    """
    base = dicomweb_base(clarus_url)
    url = f"{base}/commitment-requests/{tx_uid}"

    items = []
    for sop_class, sop_uid in sop_list:
        items.append(
            {
                _STC_REFERENCED_SOP_CLASS_UID: {"vr": "UI", "Value": [sop_class]},
                _STC_REFERENCED_SOP_INSTANCE_UID: {"vr": "UI", "Value": [sop_uid]},
            }
        )
    body = {_STC_REFERENCED_SOP_SEQUENCE: {"vr": "SQ", "Value": items}}

    def _do_commit():
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            return client.post(
                url,
                json=body,
                headers={
                    "Accept": "application/dicom+json",
                    "Content-Type": "application/dicom+json",
                },
            )
        finally:
            client.close()

    try:
        resp = _http_retry(_do_commit)
    except Exception as e:
        # Retry budget spent on a transport failure or a 5xx.
        logging.warning("[STC] commit tx=%s failed: %s", tx_uid, e)
        return [], _all_failed(sop_list), None

    status = resp.status_code

    if status in (404, 405):
        logging.warning(
            "[STC] origin answers %d on commitment-requests; set "
            "storage_commitment_presence=false for this origin",
            status,
        )
        return [], _all_failed(sop_list), STC_NO_RESOURCE

    if status == 409:
        # The Transaction UID was already committed: the verdict is stored,
        # not re-derived. ONE GET, and an idempotent answer is reported.
        return _stc_check_request(clarus_url, tx_uid, sop_list, http_timeout, tls=tls)

    if status == 202:
        # PS3.18 13.4.3: 202 Accepted means the origin TOOK the request and is
        # still processing it - it is not a verdict, and it says nothing about
        # any individual SOP. Mapping it to "all failed 0x0110" told the
        # modality its instances were not committed while the origin was still
        # deciding; the caller must keep the transaction pending and re-Check.
        logging.info(
            "[STC] commit tx=%s: HTTP 202 - origin still processing, "
            "transaction stays pending",
            tx_uid,
        )
        return [], [], STC_PENDING

    if status != 200:
        logging.warning(
            "[STC] commit tx=%s: HTTP %d -> all failed 0x0110 (%s)",
            tx_uid,
            status,
            resp.text[:200],
        )
        return [], _all_failed(sop_list), None

    try:
        payload = resp.json()
    except Exception as e:
        logging.warning("[STC] commit tx=%s: unparsable body (%s)", tx_uid, e)
        return [], _all_failed(sop_list), None

    return _stc_map_verdict(payload, sop_list, tx_uid)

def _stc_check_request(clarus_url, tx_uid, sop_list, http_timeout=30, tls=None):
    """GET the stored verdict for a Transaction UID (PS3.18 13.5).

    Used for the 409 replay path: the origin already has a verdict for this
    Transaction UID and re-committing must not change it. A 404 (the result
    was swept by retention) is every SOP failed 0x0110.
    """
    base = dicomweb_base(clarus_url)
    url = f"{base}/commitment-requests/{tx_uid}"

    def _do_check():
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            return client.get(url, headers={"Accept": "application/dicom+json"})
        finally:
            client.close()

    try:
        resp = _http_retry(_do_check)
    except Exception as e:
        logging.warning("[STC] check tx=%s failed: %s", tx_uid, e)
        return [], _all_failed(sop_list), None

    if resp.status_code in (404, 405):
        logging.warning(
            "[STC] check tx=%s: HTTP %d (result not stored) -> all failed 0x0110",
            tx_uid,
            resp.status_code,
        )
        return [], _all_failed(sop_list), None

    if resp.status_code == 202:
        # Same rule as the Commit path: the origin has not finished processing
        # this Transaction UID. Keeping the transaction pending is what makes
        # the bounded re-Check happen; answering 0x0110 here reported a
        # failure the origin never gave.
        logging.info(
            "[STC] check tx=%s: HTTP 202 - still processing, transaction stays "
            "pending",
            tx_uid,
        )
        return [], [], STC_PENDING

    if resp.status_code != 200:
        logging.warning(
            "[STC] check tx=%s: HTTP %d -> all failed 0x0110",
            tx_uid,
            resp.status_code,
        )
        return [], _all_failed(sop_list), None

    try:
        payload = resp.json()
    except Exception as e:
        logging.warning("[STC] check tx=%s: unparsable body (%s)", tx_uid, e)
        return [], _all_failed(sop_list), None

    return _stc_map_verdict(payload, sop_list, tx_uid)

def _all_failed(sop_list):
    """Every SOP failed with the general processing failure code."""
    return [
        (sop_class, sop_uid, _STC_PROCESSING_FAILURE) for sop_class, sop_uid in sop_list
    ]

def _stc_map_verdict(payload, sop_list, tx_uid):
    """Map a Commit/Check 200 body onto (committed, failed, None).

    Committed SOPs come from ReferencedSOPSequence (0008,1199); failed ones
    from FailedSOPSequence (0008,1198) with FailureReason (0008,1197). PS3.18
    F.2.3 maps US to a JSON Number, so the reason arrives as an integer and
    `_stc_reason` resolves it to a DIMSE code.

    The answer is projected onto the REQUEST. A Transaction UID identifies one
    transaction (PS3.4 J.3.2), so the response may only speak about the SOPs
    that were asked about: an origin that answers with a SOP the bridge never
    submitted, or with a SOP that carries no verdict, was previously mapped
    verbatim - SOP B committed and A failed for a request that named only A, or
    BOTH verdicts recorded for A when the origin listed it in both sequences.
    Each requested SOP therefore gets exactly ONE verdict, taken from the
    response where it is unambiguous; anything else falls back to the
    processing-failure code, which reports what is known instead of guessing.
    """
    requested = [(str(sop_class), str(sop_uid)) for sop_class, sop_uid in sop_list]
    wanted = set(requested)

    committed_pairs = []
    failed_pairs = []
    for item in _stc_sequence_items(payload, _STC_REFERENCED_SOP_SEQUENCE):
        pair = _stc_pair(item)
        if pair is None:
            continue
        committed_pairs.append(pair)
    for item in _stc_sequence_items(payload, _STC_FAILED_SOP_SEQUENCE):
        pair = _stc_pair(item)
        if pair is None:
            continue
        failed_pairs.append((pair[0], pair[1], _stc_reason(item)))

    committed_keys = {_stc_key(p) for p in committed_pairs}
    failed_by_key = {}
    for sop_class, sop_uid, reason in failed_pairs:
        failed_by_key.setdefault(_stc_key((sop_class, sop_uid)), reason)

    # A response entry about a SOP that was never requested is not a verdict
    # for this transaction; it is evidence the origin answered for a different
    # one, and adopting it would report on an instance the modality did not ask
    # about in this request.
    for key in sorted(committed_keys | set(failed_by_key)):
        if key not in wanted:
            logging.warning(
                "[STC] tx=%s: response names SOP %s which was not requested - "
                "ignored",
                tx_uid,
                key[1],
            )

    committed = []
    failed = []
    for pair in requested:
        key = _stc_key(pair)
        in_committed = key in committed_keys
        in_failed = key in failed_by_key
        if in_committed and in_failed:
            # Contradictory: the same SOP cannot be both stored and refused.
            # The safe reading is the failure - reporting "committed" for an
            # instance the origin also listed as failed would tell the modality
            # its data is safe on the strength of an ambiguous answer.
            logging.warning(
                "[STC] tx=%s: SOP %s appears in BOTH sequences - reporting "
                "the failure verdict",
                tx_uid,
                pair[1],
            )
            failed.append((pair[0], pair[1], failed_by_key[key]))
        elif in_committed:
            committed.append(pair)
        elif in_failed:
            failed.append((pair[0], pair[1], failed_by_key[key]))
        else:
            logging.warning(
                "[STC] tx=%s: SOP %s is in neither response sequence -> 0x0110",
                tx_uid,
                pair[1],
            )
            failed.append((pair[0], pair[1], _STC_PROCESSING_FAILURE))

    return committed, failed, None

def _stc_sequence_items(payload, tag):
    """The Value items of one sequence tag, or [] when absent/malformed."""
    if not isinstance(payload, dict):
        return []
    seq = payload.get(tag)
    if not isinstance(seq, dict):
        return []
    items = seq.get("Value")
    if not isinstance(items, list):
        return []
    return [item for item in items if isinstance(item, dict)]

def _stc_pair(item):
    """(sop_class, sop_uid) from one sequence item, or None when incomplete."""
    sop_class = _stc_single(item, _STC_REFERENCED_SOP_CLASS_UID)
    sop_uid = _stc_single(item, _STC_REFERENCED_SOP_INSTANCE_UID)
    if sop_class is None or sop_uid is None:
        return None
    return (sop_class, sop_uid)

def _stc_single(item, tag):
    """One string out of a DICOM JSON element's Value list."""
    element = item.get(tag)
    if not isinstance(element, dict):
        return None
    values = element.get("Value")
    if not isinstance(values, list) or not values:
        return None
    return str(values[0])

def _stc_key(pair):
    return (str(pair[0]), str(pair[1]))

def _stc_reason(item):
    """Failure Reason (0008,1197) as a DIMSE code; unenumerated -> 0x0110.

    PS3.18 F.2.3 Table F.2.3-1 maps US to the JSON Data Type "Number", so a
    conformant origin writes 0x0112 as the bare number 274. `_stc_single`
    stringifies it, so the DECIMAL text has to be resolved to the same code as
    the hex text - a map lookup keyed only on "0112" reported every numeric
    verdict as 0x0110. A JSON String is still accepted (lenient input): that
    form is non-conformant for US but harmless to read.
    """
    raw = _stc_single(item, _STC_FAILURE_REASON)
    if raw is None:
        return _STC_PROCESSING_FAILURE
    text = str(raw).strip()
    if text in _STC_REASON_MAP:
        return _STC_REASON_MAP[text]
    try:
        # Decimal form of the same code (274 == 0x0112).
        code = int(text, 10)
    except (TypeError, ValueError):
        return _STC_PROCESSING_FAILURE
    # PS3.3 C.14.1.1 enumerates the Failure Reason values; everything else is
    # reported as the general processing failure. A bare range check here let
    # a code the standard does not define (65535) travel to the modality as a
    # DIMSE reason the bridge promised to normalise.
    if code in _STC_ENUMERATED_REASONS:
        return code
    return _STC_PROCESSING_FAILURE

# ---------------------------------------------------------------------------
# Bridge: HTTP status -> DIMSE status mapping
# ---------------------------------------------------------------------------
def _http_status_to_dimse(http_status):
    """Map HTTP status code to DIMSE (status, description) tuple (BR-011).

    Transient errors (0xA700)  -  bridge should retry with backoff.
    Fatal errors (0xC000)  -  bridge should NOT retry.
    Success (0x0000)  -  delivered.
    """
    # -- Transient errors (retryable) --
    TRANSIENT = {
        429: "Too Many Requests - rate limited, retry after delay",
        500: "Internal Server Error - server malfunction",
        502: "Bad Gateway - storage backend error",
        503: "Service Unavailable - server busy or down",
        504: "Gateway Timeout - database operation timed out",
        507: "Insufficient Storage - disk full on server",
    }
    if http_status in TRANSIENT:
        return (0xA700, http_status, TRANSIENT[http_status])

    # -- Fatal errors (do NOT retry) --
    FATAL = {
        400: "Bad Request - invalid DICOM data",
        401: "Unauthorized - check Clarus credentials",
        403: "Forbidden - insufficient permissions",
        404: "Not Found - study/series/instance missing",
        405: "Method Not Allowed - wrong HTTP method",
        406: "Not Acceptable - unsupported Transfer Syntax",
        409: "Conflict - SOP Instance UID conflict",  # Note: 409 succeeds for idempotent delivery
        413: "Payload Too Large - dataset exceeds server limit",
        415: "Unsupported Media Type - wrong Content-Type",
        416: "Range Not Satisfiable - invalid byte range",
        422: "Unprocessable Content - DICOM validation failed",
    }
    if http_status in FATAL:
        return (0xC000, http_status, FATAL[http_status])

    # -- Success codes --
    if 200 <= http_status < 300:
        return (0x0000, http_status, "OK")

    # -- Unknown  -  conservative: treat as transient for safety --
    if 500 <= http_status < 600:
        return (0xA700, http_status, f"Unknown server error HTTP {http_status}")
    return (0xC000, http_status, f"Unexpected HTTP {http_status}")

# ---------------------------------------------------------------------------
# Bridge: STOW-RS response parser  -  detect per-SOP failures
# ---------------------------------------------------------------------------
class StowBodyNotJsonObject(ValueError):
    """A STOW-RS response body parsed to something that is not a JSON object.

    PS3.18 10.5.2 makes the STOW response a DICOM JSON OBJECT (an array or a
    bare scalar is not one). Rejecting it here turns what used to be an
    AttributeError escaping the handler into a structured 4xx the caller can
    act on.
    """

def _stow_body_dict(response_text):
    """Parse a STOW-RS body and return the JSON object it must contain.

    Returns None only for an EMPTY body, which PS3.18 10.5.2 permits (the
    response may be delivered with no content to report). Anything else that
    is not a JSON object raises `StowBodyNotJsonObject`: a 2xx whose verdict
    cannot be read states nothing about the instances, and answering "no
    failures" for it acknowledged a result nobody reported.
    """
    if response_text is None or not str(response_text).strip():
        return None
    try:
        body = json.loads(response_text)
    except (json.JSONDecodeError, TypeError, ValueError):
        raise StowBodyNotJsonObject(
            f"STOW-RS body is not JSON ({len(str(response_text))} bytes)"
        )
    if not isinstance(body, dict):
        raise StowBodyNotJsonObject(
            f"STOW-RS body is {type(body).__name__}, not a JSON object"
        )
    return body

def _stow_seq_value(tag, seq_item):
    """The `Value` list of one DICOM JSON tag element, type-checked (PS3.18 J.2).

    A tag element is an object with an optional `Value` array. Anything else -
    a bare string, a list where the element should be, a `Value` that is not a
    list - used to reach `.get`/`[0]` and raise AttributeError, which the wide
    `except Exception` in the callers mapped to 0xC000: a PERMANENT refusal
    for a body that is merely malformed. Corruption is transient, so it raises
    `StowBodyNotJsonObject` and the caller answers 0xA700 (retryable) instead.
    """
    if not isinstance(seq_item, dict):
        raise StowBodyNotJsonObject(
            f"failed-SOP item({tag}) is {type(seq_item).__name__}, not an object"
        )
    values = seq_item.get("Value", [])
    if values is None:
        values = []
    if not isinstance(values, list):
        raise StowBodyNotJsonObject(
            f"failed-SOP item({tag}) Value is {type(values).__name__}, not a list"
        )
    return values

def _stow_referenced_uids(response_text):
    """SOP Instance UIDs the origin explicitly ACCOUNTED FOR in a STOW answer.

    Reads the Referenced SOP Sequence (0008,1199) - the instances the origin
    reports having stored - so a 202 can be reconciled against the batch
    instead of being read as "no failures, therefore everything is stored"
    (PS3.18 10.5.3). A body the bridge cannot read yields an empty set, which
    makes every SOP unaccounted: an unreadable verdict is not a delivered one.
    """
    try:
        body = _stow_body_dict(response_text)
    except StowBodyNotJsonObject:
        return set()
    if body is None:
        return set()
    seq = body.get("00081199")
    if not isinstance(seq, dict):
        return set()
    items = seq.get("Value")
    if not isinstance(items, list):
        return set()
    uids = set()
    for item in items:
        if not isinstance(item, dict):
            continue
        try:
            values = _stow_seq_value("00081155", item.get("00081155", {}))
        except StowBodyNotJsonObject:
            continue
        if values and isinstance(values[0], str) and values[0].strip():
            uids.add(values[0].strip())
    return uids

def _parse_stow_failures_all(response_text):
    """Parse STOW-RS JSON for ALL failed SOPs (0008,1198 Failed SOP Sequence).

    Server returns HTTP 202 even when individual SOPs in a batch fail.
    Returns a list of {"sop_uid": str, "reason": str}; empty when none failed.
    Raises `StowBodyNotJsonObject` when the body is JSON but not an object, or
    when a failed-SOP item does not follow the DICOM JSON shape.
    """
    body = _stow_body_dict(response_text)
    if body is None:
        return []

    failed_seq = body.get("00081198")
    if not isinstance(failed_seq, dict):
        return []

    items = failed_seq.get("Value", [])
    if items is None:
        return []
    if not isinstance(items, list):
        raise StowBodyNotJsonObject(
            f"00081198 Value is {type(items).__name__}, not a list"
        )
    if not items:
        return []

    failures = []
    seq_items = []
    for item in items:
        if not isinstance(item, dict):
            raise StowBodyNotJsonObject(
                f"00081198 item is {type(item).__name__}, not an object"
            )
        seq_items.append(item)

    for item in seq_items:
        # 00081197 = Failure Reason (US, numeric code)
        codes = _stow_seq_value("00081197", item.get("00081197", {}))
        failure_code = codes[0] if codes else "?"

        # 00000902 = Error Comment (LO, human-readable)
        comments = _stow_seq_value("00000902", item.get("00000902", {}))
        error_comment = comments[0] if comments else "Unknown reason"

        # 00081155 = Referenced SOP Instance UID (PS3.18 sec.10.5.2.1)
        ref_sops = _stow_seq_value("00081155", item.get("00081155", {}))
        ref_sop = ref_sops[0] if ref_sops else "?"
        # The UID must be a non-empty STRING before it becomes an identity.
        # A `Value` holding an object or an array was returned as-is, and the
        # batch dictionary keyed by SOP UID then raised TypeError on the
        # unhashable value - which the caller's generic handler mapped to a
        # permanent 0xC000 for EVERY live SOP, including ones the origin had
        # already stored. An unreadable verdict is not a refusal, so it takes
        # the retryable path (`StowBodyNotJsonObject` -> 0xA700 / UNVERIFIED).
        if not isinstance(ref_sop, str) or not ref_sop.strip():
            raise StowBodyNotJsonObject(
                "00081155 Value[0] is "
                f"{type(ref_sop).__name__}, not a non-empty SOP Instance UID"
            )
        ref_sop = ref_sop.strip()

        failures.append(
            {
                "sop_uid": ref_sop,
                "reason": f"[code={failure_code}] {error_comment}",
            }
        )
    return failures

def _parse_stow_failures(response_text, sop_instance_uid):
    """Parse STOW-RS JSON response for the FIRST Failed SOP (batch-compatible).

    Server returns HTTP 202 even when individual SOPs fail.
    Returns dict {"sop_uid", "reason"} if rejected, None if accepted.
    """
    failures = _parse_stow_failures_all(response_text)
    if not failures:
        return None
    return failures[0]

def _ensure_stow_ts(dataset):
    """Ensure dataset has file_meta.TransferSyntaxUID for dcmwrite.

    pynetdicom may strip file_meta from network-received datasets (BR-020).
    Only needed when re-serializing (modified instances). Raw pass-through
    (raw_bytes != None) keeps the original bytes and never reaches here.
    Note: pydicom Dataset.__getattr__ raises AttributeError, not returns None.
    """
    try:
        _ = dataset.file_meta.TransferSyntaxUID
    except AttributeError:
        from pydicom.dataset import FileMetaDataset

        dataset.file_meta = FileMetaDataset()
        dataset.file_meta.TransferSyntaxUID = ExplicitVRLittleEndian

def stow_single_instance(
    dataset, clarus_url, http_timeout=30, raw_bytes=None, client=None, tls=None
):
    """STOW-RS single instance with retry (BR-002). Auth by nginx.

    Args:
        clarus_url: DICOMweb base URL (single knob, 2908). Trailing slash
            is stripped by dicomweb_base().
        raw_bytes: if provided, use these EXACT bytes as DICOM payload.
            Bypasses dcmwrite  -  preserves byte-identical content for CAS dedup.
            When None, dataset is re-serialized via dcmwrite (modified instance).
        client: optional pre-created httpx.Client for connection reuse.
            When None, creates and closes a new Client per call.
            P30: use a persistent Client for Keep-Alive (x2 throughput).
        tls: optional (cert_path, key_path) tuple for mTLS. verify is
            ALWAYS on (httpx default)  -  no knob to disable it.

    Returns: (dimse_status, http_status, msg).
    """
    # ensure file_meta TransferSyntaxUID before any dcmwrite re-serialization.
    if raw_bytes is None:
        _ensure_stow_ts(dataset)

    # P8: raw pass-through  -  use exact bytes when no modifications were applied.
    # This preserves byte-identical content for CAS dedup (avoids dcmwrite
    # re-serialization which changes File Meta Information, tag ordering, padding).
    if raw_bytes is not None:
        dicom_bytes = raw_bytes
    else:
        # R4: an instance that cannot be re-serialized (an invalid value for
        # its VR) is a verdict about THIS instance, not a crash. Letting
        # dcmwrite raise here escaped before the function returned its
        # promised three-tuple, and the caller's broad handler then answered
        # for the whole request.
        try:
            buf = io.BytesIO()
            dcmwrite(buf, dataset, enforce_file_format=True)
            dicom_bytes = buf.getvalue()
        except Exception as e:
            logging.error("[STOW-RS] could not serialize the instance: %s", e)
            return (0xC000, None, f"Serialize error: {e}")

    boundary = f"BOUNDARY_{uuid.uuid4().hex[:16]}"
    body = (
        (f"--{boundary}\r\nContent-Type: application/dicom\r\n\r\n").encode("ascii")
        + dicom_bytes
        + (f"\r\n--{boundary}--\r\n").encode("ascii")
    )

    # P8: httpx with total timeout  -  prevents indefinite hangs on TCP accept.
    # requests(timeout=30) only covers connect+read, not total elapsed time.
    # httpx.Timeout(N) covers the entire request lifecycle.
    total_timeout = http_timeout + 10
    # Absolute budget for the whole STOW attempt sequence. `httpx.Timeout()`
    # bounds each operation, so a slow origin that keeps sending response data
    # inside the read timeout can hold one POST open well past the budget; the
    # deadline is what bounds the attempt in wall-clock terms.
    deadline = time.monotonic() + total_timeout
    base = dicomweb_base(clarus_url)
    stow_url = f"{base}/studies"

    def _attempt_timeout():
        """Per-attempt httpx timeout, shrunk to whatever budget is left.

        A fixed per-operation timeout on every attempt let a sequence of
        near-timeout attempts total far more than the configured budget. Each
        attempt is bounded by the REMAINING time, so the sequence cannot.
        """
        remaining = max(1.0, deadline - time.monotonic())
        return httpx.Timeout(remaining)

    # P30: Keep-Alive  -  reuse client for connection persistence (x2 throughput).
    # Without Keep-Alive: TCP-handshake (~30-100ms) on every slice.
    # With Keep-Alive: one handshake for the entire queue drain.
    def _do_stow():
        if client is not None:
            # Persistent client  -  connection reuse via Keep-Alive
            return client.post(
                stow_url,
                content=body,
                headers={
                    "Content-Type": (
                        f'multipart/related; type="application/dicom"; '
                        f"boundary={boundary}"
                    ),
                    "Accept": "application/dicom+json",
                },
            )
        # Fallback: create+close client per request (backward compat)
        _c = httpx.Client(timeout=_attempt_timeout(), cert=tls)
        try:
            return _c.post(
                stow_url,
                content=body,
                headers={
                    "Content-Type": (
                        f'multipart/related; type="application/dicom"; '
                        f"boundary={boundary}"
                    ),
                    "Accept": "application/dicom+json",
                },
            )
        finally:
            _c.close()

    try:
        resp = _http_retry(_do_stow, on_retry=stow_retries.inc, deadline=deadline)
        # Bridge: STOW requests counter by HTTP status
        stow_requests.labels(status=str(resp.status_code)).inc()
        sop_uid = str(getattr(dataset, "SOPInstanceUID", "?"))

        if resp.status_code in (200, 201, 202):
            # Bridge: parse STOW-RS JSON for per-SOP failures. A body that is
            # not a DICOM JSON object is the server answering the wrong thing:
            # report it as a rejected instance rather than letting the parse
            # exception escape the C-STORE handler.
            try:
                rejection = _parse_stow_failures(resp.text, sop_uid)
            except StowBodyNotJsonObject as e:
                # PS3.18 10.5.2: a 2xx states that the request was processed,
                # not that the instance was stored. An unreadable verdict means
                # the outcome is UNKNOWN, and the marker tells the outbox worker
                # so - retrying costs one re-send, while a guessed failure marks
                # an instance undelivered that the origin may already hold.
                logging.error("[STOW-RS] malformed response body: %s", e)
                return (0xA700, resp.status_code, f"{STOW_UNVERIFIED}: {e}")
            if rejection:
                logging.error(
                    "[STOW-RS] Server rejected SOP %s: %s - check clarus-server logs",
                    rejection["sop_uid"],
                    rejection["reason"],
                )
                return (0xA700, resp.status_code, rejection["reason"])

            # PS3.18 10.5.3: a 202 says the request was ACCEPTED, and its
            # per-SOP verdict is what states what became of the instance. An
            # empty failure list is not that verdict - a bodiless 202 leaves
            # the outcome unknown. Reporting 0x0000 there claimed the instance
            # was stored on the strength of a status that never said so.
            if resp.status_code == 202 and sop_uid not in _stow_referenced_uids(
                resp.text
            ):
                logging.error(
                    "[STOW-RS] HTTP 202 without a per-SOP verdict for %s - "
                    "reporting it unverified, not stored",
                    sop_uid,
                )
                return (
                    0xA700,
                    resp.status_code,
                    f"{STOW_UNVERIFIED}: no per-SOP verdict on 202",
                )

            logging.debug("-> STOW-RS: %d OK (SOP: %s)", resp.status_code, sop_uid)
            return (0x0000, resp.status_code, "OK")

        # Disk full
        if resp.status_code == 507:
            backoff = retry_after_seconds(resp.headers)
            logging.error(
                "-> STOW-RS: 507 DISK FULL (retry after %ss)",
                backoff,
            )
            return (0xA700, 507, f"Disk full - retry after {backoff}s")

        # use _http_status_to_dimse for all non-2xx responses
        return _http_status_to_dimse(resp.status_code)
    except httpx.ConnectError:
        logging.warning("-> STOW-RS: CONNECTION REFUSED")
        stow_requests.labels(status="error").inc()
        return (0xA700, None, "Connection refused")
    except httpx.TimeoutException:
        logging.warning("-> STOW-RS: TOTAL TIMEOUT after %.0fs", total_timeout)
        stow_requests.labels(status="error").inc()
        return (0xA700, None, "Total timeout")
    except httpx.TransportError as e:
        # ReadError / WriteError / RemoteProtocolError: the TCP link broke
        # mid-request. This is TRANSIENT (retryable), not a permanent verdict:
        # answering 0xC000 told the modality the instance was refused and must
        # never be re-sent, so a single blip lost data. 0xA700 (Out of
        # Resources) is the retryable refusal.
        logging.warning("-> STOW-RS: TRANSPORT ERROR (%s)", e)
        stow_requests.labels(status="error").inc()
        return (0xA700, None, str(e))
    except Exception as e:
        logging.warning("-> STOW-RS: ERROR (%s)", e)
        logging.debug("-> STOW-RS: Full traceback follows:", exc_info=True)
        stow_requests.labels(status="error").inc()
        return (0xC000, None, str(e))

def stow_batch_instances(payloads, clarus_url, http_timeout=30, client=None, tls=None):
    """STOW-RS batch  -  N instances in ONE multipart/related request.

    One POST per study-batch (fieldtest: 1063 POSTs -> ~20). P8 raw
    pass-through per part: byte-identical content for CAS dedup, no
    dcmwrite re-serialization unless the instance was modified.

    Args:
        payloads: list of (sop_uid, ds, raw_bytes).
            raw_bytes: exact bytes (None -> re-serialize modified ds).
        clarus_url: DICOMweb base URL (single knob, 2908).
        client: optional pre-created httpx.Client (Keep-Alive, P30).
        tls: optional (cert_path, key_path) tuple for mTLS.

    Returns: (results, retry_after) tuple.
        results: per-SOP list, in payload order:
            [(sop_uid, dimse_status, http_status, msg), ...]
            dimse_status mirrors stow_single_instance (0x0000 / 0xA700 / 0xC000).
        retry_after: seconds to pause on HTTP 507 (clamped 5..300), or None.
    """
    if not payloads:
        return [], None

    boundary = f"BOUNDARY_{uuid.uuid4().hex[:16]}"
    total_timeout = http_timeout + 10
    # Same elapsed-time budget as the single-instance path: `httpx.Timeout()`
    # bounds each operation, not the request, so the deadline is what stops a
    # trickling origin from holding one POST open past the budget.
    deadline = time.monotonic() + total_timeout
    base = dicomweb_base(clarus_url)
    stow_url = f"{base}/studies"

    def _attempt_timeout():
        remaining = max(1.0, deadline - time.monotonic())
        return httpx.Timeout(remaining)

    body = bytearray()
    # R4: re-serialization is per-SOP work and can raise on ONE bad instance
    # (an invalid value for its VR). Outside this guard that exception escaped
    # before the function returned the `(results, retry_after)` tuple it
    # promises, so the whole batch had no outcome and the retry re-sent every
    # other SOP with it. A failed part is reported as 0xC000 (this instance is
    # unwritable) and the rest of the batch still goes.
    #
    # Verdicts live in a list INDEXED BY INPUT POSITION, not a pre-failed list
    # plus a live list: emitting the failures first and the delivered ones
    # after it returned the batch out of order (`[B failure, A success]` for
    # `[A, B]`), which this function promises never to do.
    verdicts = [None] * len(payloads)
    live_indexes = []
    for position, (sop_uid, ds, raw_bytes) in enumerate(payloads):
        if raw_bytes is None:
            try:
                _ensure_stow_ts(ds)
                buf = io.BytesIO()
                dcmwrite(buf, ds, enforce_file_format=True)
                dicom_bytes = buf.getvalue()
            except Exception as e:
                logging.error(
                    "[STOW-RS] could not serialize SOP %s for the batch: %s",
                    sop_uid,
                    e,
                )
                verdicts[position] = (sop_uid, 0xC000, None, f"Serialize error: {e}")
                continue
        else:
            dicom_bytes = raw_bytes
        body += b"--" + boundary.encode("ascii") + b"\r\n"
        body += b"Content-Type: application/dicom\r\n\r\n"
        body += dicom_bytes
        body += b"\r\n"
        live_indexes.append(position)
    body += b"--" + boundary.encode("ascii") + b"--\r\n"

    def _emit(default_status, http_status, msg_by_uid=None):
        """Fill the remaining verdict slots, in payload order."""
        for position in live_indexes:
            uid = payloads[position][0]
            msg = (msg_by_uid or {}).get(uid, default_status[1])
            verdicts[position] = (uid, default_status[0], http_status, msg)
        return verdicts

    if not live_indexes:
        # Every part was unwritable: nothing to POST, and the caller still gets
        # the promised tuple with the per-SOP verdicts.
        return verdicts, None

    headers = {
        "Content-Type": (
            f'multipart/related; type="application/dicom"; ' f"boundary={boundary}"
        ),
        "Accept": "application/dicom+json",
    }

    def _do_stow():
        if client is not None:
            return client.post(
                stow_url,
                content=bytes(body),
                headers=headers,
            )
        _c = httpx.Client(timeout=_attempt_timeout(), cert=tls)
        try:
            return _c.post(
                stow_url,
                content=bytes(body),
                headers=headers,
            )
        finally:
            _c.close()

    try:
        resp = _http_retry(_do_stow, on_retry=stow_retries.inc, deadline=deadline)
        stow_requests.labels(status=str(resp.status_code)).inc()

        if resp.status_code in (200, 201, 202):
            # PS3.18 10.5.2: a 2xx says the request was PROCESSED, not that
            # every instance in it was STORED. The per-SOP verdict lives in
            # the Failed SOP Sequence, so an answer the bridge cannot read is
            # an UNKNOWN outcome - the origin may have kept SOP A and refused
            # SOP B (10.5.1.1.1) - and must be retried, never acknowledged.
            try:
                failed = _parse_stow_failures_all(resp.text)
            except StowBodyNotJsonObject as e:
                # A list or scalar body states nothing about the batch. It is
                # returned in the SAME `(results, retryafter)` shape as every
                # other outcome, or the caller unpacks two values from a
                # three-tuple and dies with ValueError.
                logging.error("[STOW-RS] malformed batch response body: %s", e)
                return (
                    _emit((0xA700, f"{STOW_UNVERIFIED}: {e}"), resp.status_code),
                    None,
                )
            failed_by_uid = {f["sop_uid"]: f["reason"] for f in failed}
            sent = {payloads[p][0] for p in live_indexes}
            # PS3.18 10.5: a rejection the server reported for a SOP the client
            # did not send means the two sides disagree about the batch. Marking
            # every sent SOP as delivered would claim a success nobody stated,
            # so the whole batch is retried.
            unmatched = [f for f in failed if f["sop_uid"] not in sent]
            if unmatched:
                logging.error(
                    "[STOW-RS] Server rejected %d SOP(s) not in this batch - "
                    "whole batch retried",
                    len(unmatched),
                )
                return (
                    _emit((0xA700, "Unmatched failure response"), resp.status_code),
                    None,
                )
            for position in live_indexes:
                sop_uid = payloads[position][0]
                if sop_uid in failed_by_uid:
                    verdicts[position] = (
                        sop_uid,
                        0xA700,
                        resp.status_code,
                        failed_by_uid[sop_uid],
                    )
                else:
                    verdicts[position] = (sop_uid, 0x0000, resp.status_code, "OK")
            if failed:
                logging.error(
                    "[STOW-RS] Batch: %d/%d SOPs rejected by server - "
                    "will re-send individually on retry",
                    len(failed),
                    len(live_indexes),
                )
            # PS3.18 10.5.3: on a 202 the origin reports what it did WITH A
            # PER-SOP VERDICT. An empty failure list is not that proof - a 202
            # with no body, or one naming only some of the batch, leaves the
            # rest in an UNKNOWN state. Acknowledging them as stored claimed a
            # success the origin never stated, so anything the response did not
            # explicitly account for is reported UNVERIFIED (retryable) rather
            # than delivered. The 200 compatibility path is unchanged: there
            # the origin has completed the request and "no failures" is its
            # complete answer.
            if resp.status_code == 202:
                referenced = _stow_referenced_uids(resp.text)
                unaccounted = [
                    payloads[p][0]
                    for p in live_indexes
                    if payloads[p][0] not in failed_by_uid
                    and payloads[p][0] not in referenced
                ]
                if unaccounted:
                    logging.error(
                        "[STOW-RS] HTTP 202 without a per-SOP verdict for "
                        "%d/%d SOP(s) - reporting them unverified, not "
                        "stored",
                        len(unaccounted),
                        len(live_indexes),
                    )
                    for position in live_indexes:
                        sop_uid = payloads[position][0]
                        if sop_uid in unaccounted:
                            verdicts[position] = (
                                sop_uid,
                                0xA700,
                                resp.status_code,
                                f"{STOW_UNVERIFIED}: no per-SOP verdict on 202",
                            )
            return verdicts, None

        # / Disk full  -  whole batch retryable.
        # 2908: _http_retry does NOT retry 507; backoff comes from the
        # Retry-After header (clamped 5..300 s, default 30 s). The outbox
        # worker pauses and keeps the files pending.
        if resp.status_code == 507:
            backoff = retry_after_seconds(resp.headers)
            logging.error(
                "-> STOW-RS: 507 DISK FULL (retry after %ss)",
                backoff,
            )
            msg = f"Disk full - retry after {backoff}s"
            return _emit((0xA700, msg), 507), backoff

        # non-2xx  -  whole batch shares one outcome.
        dimse_status, _, msg = _http_status_to_dimse(resp.status_code)
        return _emit((dimse_status, msg), resp.status_code), None
    except httpx.ConnectError:
        logging.warning("-> STOW-RS: CONNECTION REFUSED")
        stow_requests.labels(status="error").inc()
        return _emit((0xA700, "Connection refused"), None), None
    except httpx.TimeoutException:
        logging.warning("-> STOW-RS: TOTAL TIMEOUT after %.0fs", total_timeout)
        stow_requests.labels(status="error").inc()
        return _emit((0xA700, "Total timeout"), None), None
    except httpx.TransportError as e:
        # Transient mid-request transport break (Read/Write/RemoteProtocol):
        # retryable, so 0xA700 per SOP, not the permanent 0xC000.
        logging.warning("-> STOW-RS: TRANSPORT ERROR (%s)", e)
        stow_requests.labels(status="error").inc()
        return _emit((0xA700, str(e)), None), None
    except Exception as e:
        logging.warning("-> STOW-RS: ERROR (%s)", e)
        logging.debug("-> STOW-RS: Full traceback follows:", exc_info=True)
        stow_requests.labels(status="error").inc()
        return _emit((0xC000, str(e)), None), None

# ---------------------------------------------------------------------------
# Bridge: http_server
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  HTTP handler for /print, /metrics, /health, /version.

BridgeHTTPHandler: POST /print (C-PRINT), GET /metrics (Prometheus), GET /health,
GET /version (build identification).
Includes JSON->DICOM Dataset converter and factory for dependency injection (MAJ-003).
"""

import base64
import json
import logging
import socket
import time
from http.server import BaseHTTPRequestHandler

from prometheus_client import generate_latest
from pydicom import Dataset
from pydicom.datadict import dictionary_VR, keyword_dict

# Short git revision of the commit the bundle was generated from. bundle.py
# rewrites this line when it assembles clbridge.py; in the source tree the
# value is the placeholder, which is also the honest answer for a bundle cut
# outside a repository.
BUNDLE_STAMP = "351976c7"

# Per-socket-operation deadline for a request. A print job is a JSON body with
# base64 images on a LAN, so 30 s is far beyond any legitimate transfer while
# still bounding a stalled peer: without it one silent body holds the
# connection (and the worker) open indefinitely. A peer that keeps sending a
# byte just inside every window is not a stall, so the TOTAL body read is
# bounded separately by BODY_TOTAL_TIMEOUT_SEC.
HTTP_SOCKET_TIMEOUT_SEC = 30

# Wall-clock budget for reading ONE request body. The largest legitimate body
# is a 100 MB base64 print job (the size ceiling in do_POST); on the LAN and
# even on a 10 Mbit link that is well under a minute, so 120 s leaves room for
# a slow printer driver while still bounding a peer that would otherwise hold
# the worker for as long as it cares to trickle.
BODY_TOTAL_TIMEOUT_SEC = 120

# Bytes per read in the body loop. The deadline bounds the total, so the chunk
# only has to be large enough that a normal body costs a handful of reads.
_BODY_CHUNK = 64 * 1024

# Wall-clock budget for the request line PLUS headers. `self.timeout` bounds
# one socket operation, so a peer sending a header byte every 29 s is never
# a stall and keeps the single-threaded listener busy for as long as it
# likes - while /health, the liveness probe, waits behind it. 30 s is far
# beyond any legitimate request head (nginx's default client_header_timeout
# is 60 s for a full request; a head is a fraction of that).
HEAD_TOTAL_TIMEOUT_SEC = 30

class _BodyDeadlineExceeded(Exception):
    """The peer is too slow: the wall-clock body budget ran out."""

class _BodyTruncated(Exception):
    """The peer sent fewer bytes than its Content-Length announced."""

class _HeadDeadlineExceeded(Exception):
    """The peer took too long over the request line and headers."""

class _HeadBudgetReader:
    """Re-arms the raw socket's timeout to the remaining head budget per BYTE.

    `parse_request` reads the headers through `self.rfile`, and `readline()`
    on a buffered reader loops internally: one call issues as many `recv`s as
    it needs, each of which would get its own fresh socket window. Re-arming
    once per `readline` call therefore still let a peer trickle a byte inside
    every window and hold the head read forever.

    `readline` is implemented HERE as a byte-at-a-time loop over `read(1)`, so
    the deadline is checked between every byte. The head is a few hundred
    bytes, so the extra Python-level looping costs nothing measurable, and the
    boundedness is what the head read exists for.
    """

    def __init__(self, inner, deadline, sock):
        self._inner = inner
        self._deadline = deadline
        self._sock = sock

    def _arm(self):
        remaining = self._deadline - time.monotonic()
        if remaining <= 0:
            raise _HeadDeadlineExceeded()
        if self._sock is not None:
            try:
                self._sock.settimeout(max(0.1, remaining))
            except OSError:
                pass

    def readline(self, limit=-1):
        """One line, assembled byte by byte under the remaining budget."""
        line = bytearray()
        while True:
            self._arm()
            char = self._inner.read(1)
            if not char:
                # EOF: the caller sees a short/empty line and answers
                # accordingly (empty request line = peer closed).
                return bytes(line)
            line += char
            if char == b"\n":
                return bytes(line)
            if 0 < limit <= len(line):
                # Same truncation contract as the buffered reader: a line
                # longer than `limit` is returned without its terminator and
                # the caller reports 414.
                return bytes(line)

    def read(self, n=-1):
        self._arm()
        return self._inner.read(n)

    def __getattr__(self, name):
        return getattr(self._inner, name)

# ---------------------------------------------------------------------------
# Bridge: JSON -> DICOM Dataset converter for C-PRINT
# ---------------------------------------------------------------------------
class _UnknownPrintAttribute(ValueError):
    """A print job names an attribute the DICOM dictionary does not know.

    Raised instead of skipping the key: a typo in a film-session keyword used
    to drop the attribute silently, and the print job then differed from what
    the caller asked for with no error anywhere.
    """

# PS3.5 Table 6.2-1: the VRs whose value is a number on the wire. A JSON
# number for one of these is passed through as a number; a JSON STRING is
# still accepted (a caller may format IS/DS itself) and reaches pydicom as it
# was written.
_NUMERIC_VRS = frozenset({"US", "SS", "UL", "SL", "UV", "SV", "IS", "DS", "FL", "FD"})

# The BINARY numeric VRs: their value is packed as an integer/float, so
# pydicom's writer requires a NUMBER and rejects a string outright. The string
# VRs (IS, DS) are decimal text on the wire and must stay strings.
_BINARY_NUMERIC_VRS = frozenset({"US", "SS", "UL", "SL", "UV", "SV"})

# PS3.5 Table 6.2-1: the inclusive range of each binary integer VR. US/UL/UV
# are unsigned, SS/SL/SV signed. A value outside its VR's range cannot be
# encoded at all, so it is refused here rather than failing inside pydicom
# with an exception the caller cannot act on.
_BINARY_NUMERIC_RANGES = {
    "US": (0, 2**16 - 1),
    "UL": (0, 2**32 - 1),
    "UV": (0, 2**64 - 1),
    "SS": (-(2**15), 2**15 - 1),
    "SL": (-(2**31), 2**31 - 1),
    "SV": (-(2**63), 2**63 - 1),
}

def _print_attr_value(vr, value):
    """One attribute value, typed for the VR the dictionary gave the tag.

    JSON can only carry strings, numbers, booleans and nulls, so a caller can
    legitimately send `{"ImageBoxPosition": 1}` or `"1"` for a US attribute.
    `str()`ing every scalar made the VALUE a string regardless - pydicom then
    warns ("a value of type 'str' cannot be assigned to a tag with VR US") and
    a strict SCP reads the element with the wrong value type. Numbers pass
    through untouched and pydicom's own converter applies the VR's rules;
    everything else keeps the historical string form.

    A numeric STRING for a BINARY numeric VR is converted and range-checked:
    the documented `"1"` form is valid input, but the binary writer packs an
    integer and cannot encode text, so passing the string through produced an
    element pydicom refused to write. IS/DS keep their string form - they are
    decimal text on the wire and pydicom encodes them as such.
    """
    if vr in _BINARY_NUMERIC_VRS and isinstance(value, str):
        text = value.strip()
        try:
            # `int(text, 0)` would accept "0x10"; DICOM values are decimal.
            parsed = int(text, 10)
        except (TypeError, ValueError):
            raise ValueError(f"{vr} value {value!r} is not an integer")
        lo, hi = _BINARY_NUMERIC_RANGES[vr]
        if not (lo <= parsed <= hi):
            raise ValueError(
                f"{vr} value {parsed} is outside the encodable range {lo}..{hi}"
            )
        return parsed
    if (
        vr in _NUMERIC_VRS
        and isinstance(value, (int, float))
        and not isinstance(value, bool)
    ):
        return value
    return str(value)

def _json_print_to_dataset(json_dict):
    """Convert JSON dict of DICOM tags to pydicom Dataset.

    Keys can be:
        - DICOM tag hex string (e.g. "00100010" -> PatientName)
        - DICOM keyword (e.g. "PatientName")

    The VR comes from the DICOM data dictionary (PS3.6; pydicom mirrors it in
    `pydicom.datadict.dictionary_VR`), never from the Python type of the JSON
    value. A hardcoded "SH" for every scalar wrote IS/CS/LO/DS/US attributes
    under the wrong VR, and "OB" for a list turned a multi-valued CS (such as
    a Film Box attribute) into a byte string the print SCP cannot interpret.

    An unknown keyword raises `_UnknownPrintAttribute` rather than being
    skipped: the caller answers 400 and the operator sees the typo.
    """
    ds = Dataset()
    for key, value in json_dict.items():
        # Try hex tag
        if len(key) == 8 and all(c in "0123456789ABCDEFabcdef" for c in key):
            group = int(key[0:4], 16)
            elem = int(key[4:8], 16)
        else:
            # Try keyword lookup
            tag_int = keyword_dict.get(key)
            if tag_int is None:
                raise _UnknownPrintAttribute(f"unknown print attribute: {key}")
            # keyword_dict values are ints like 0x00100010
            group = tag_int >> 16
            elem = tag_int & 0xFFFF

        tag = (group, elem)
        # PS3.6: the dictionary is the authority for the VR. It RAISES
        # KeyError for a tag it does not know (private or simply absent), so
        # the lookup is guarded rather than post-checked - `dictionary_VR`
        # never returns an empty string on an unknown tag.
        try:
            vr = dictionary_VR(tag)
        except KeyError:
            raise _UnknownPrintAttribute(
                f"unknown print attribute: {key} ({group:04X},{elem:04X})"
            ) from None
        if not vr:
            raise _UnknownPrintAttribute(
                f"unknown print attribute: {key} ({group:04X},{elem:04X})"
            )

        if vr == "SQ":
            # A sequence carries items, not scalars: a dict is one item.
            if isinstance(value, dict):
                items = [_json_print_to_dataset(value)]
            elif isinstance(value, list):
                items = [
                    _json_print_to_dataset(v) if isinstance(v, dict) else v
                    for v in value
                ]
            else:
                raise _UnknownPrintAttribute(
                    f"{key} is SQ but the value is not a sequence"
                )
            ds.add_new(tag, vr, items)
        elif isinstance(value, list):
            # Multi-valued attribute keeps the TAG's VR (PS3.5 6.4 VM>1).
            ds.add_new(tag, vr, [_print_attr_value(vr, v) for v in value])
        else:
            ds.add_new(tag, vr, _print_attr_value(vr, value))
    return ds

# ---------------------------------------------------------------------------
# Bridge: HTTP Bridge Handler  -  /print + /metrics, /health
# ---------------------------------------------------------------------------
class BridgeHTTPHandler(BaseHTTPRequestHandler):
    """HTTP handler for POST /print, GET /metrics, GET /health, GET /version.

    POST /print  -  receives print jobs from ClarityX.
        Request body: JSON with keys:
            printer_name (str): key in printers.yaml
            film_session (dict): DICOM Film Session attributes as JSON
            images (list[str]): base64-encoded DICOM Part 10 files
            calling_aet (str, optional): override AE Title
        Response: JSON PrintResult

    GET /metrics  -  Prometheus text format metrics.
    GET /health  -  liveness probe (200 OK), pure and fast.
    GET /version  -  build identification (version + generated-from revision).
    """

    # `socketserver` copies this onto the connection in BaseHTTPRequestHandler
    # .setup(), so it bounds EVERY socket operation on the handler - including
    # the body read below. It stops a peer that STALLS; a peer that trickles
    # keeps every recv inside the window, and that is what the total deadline
    # in `_read_body_with_deadline` bounds.
    timeout = HTTP_SOCKET_TIMEOUT_SEC

    # Dependencies injected via make_bridge_handler() factory  -  NO lazy imports in do_GET!
    driver_registry = {}
    printer_registry = {}
    bridge_ae_title = "CLBRIDGE"  # BR-P31: cached references to avoid per-request imports (P2.10 bottleneck fix)
    _outbox_ref = None  # OutboxQueue  -  reliable persistence queue
    _health_checker_ref = None  # HealthChecker  -  real server health status
    _commit_tracker_ref = None  # CommitTracker  -  Storage Commitment batches
    _move_jobs_ref = None  # MoveJobManager  -  C-MOVE job table

    def _read_body_with_deadline(self, content_length):
        """Read exactly `content_length` bytes, bounded by a wall-clock budget.

        `self.timeout` bounds one socket operation, so a peer that sends a
        byte just inside every timeout window holds this thread for as long as
        it likes while never tripping the socket timeout. The deadline makes
        the TOTAL bounded, which is the property the class comment claims.

        Checking the deadline BETWEEN reads is not enough on its own: a read
        can block for the whole socket timeout (30 s), so a peer trickling one
        byte per 29 s overran a 120 s budget by up to two windows. Each read is
        therefore bounded by what is LEFT of the budget, and a read that
        returns nothing before its own budget means the deadline passed inside
        it - reported as the same `_BodyDeadlineExceeded` a between-read check
        would raise.

        `rfile.read(n)` cannot be used here: it is a BUFFERED reader whose
        internal loop keeps issuing `recv`s until it has `n` bytes, so one call
        can outlive the budget however the socket timeout is set (the timeout
        applies per `recv`, not per call). The bytes are read from the RAW
        socket instead - one `recv` per iteration, each preceded by a
        budget-derived timeout - and any bytes the reader already buffered are
        consumed from it first so the two sources cannot interleave.
        """
        deadline = time.monotonic() + BODY_TOTAL_TIMEOUT_SEC
        sock = getattr(self, "connection", None)
        prev_timeout = None
        if sock is not None:
            try:
                prev_timeout = sock.gettimeout()
            except OSError:
                sock = None
        chunks = []
        remaining = content_length
        try:
            # Anything the buffered reader already pulled off the socket must
            # be consumed first, or the raw reads below would start past it.
            #
            # `peek(0)` on an EMPTY body still enters the buffered reader and
            # can block until the socket timeout (30 s) for a client that sent
            # `Content-Length: 0` and is waiting for the response - the request
            # then times out with nothing to read.
            if sock is not None and remaining > 0:
                try:
                    buffered = self.rfile.peek(0)
                except Exception:
                    buffered = b""
                if buffered:
                    take = min(len(buffered), remaining)
                    chunks.append(self.rfile.read(take))
                    remaining -= take
            while remaining > 0:
                budget = deadline - time.monotonic()
                if budget <= 0:
                    raise _BodyDeadlineExceeded()
                want = min(_BODY_CHUNK, remaining)
                if sock is None:
                    # No raw socket (an in-process caller): fall back to the
                    # reader, still bounded between iterations.
                    chunk = self.rfile.read(want)
                else:
                    # Never wait longer than the remaining budget: the socket
                    # timeout is the only thing that bounds a blocking recv.
                    try:
                        sock.settimeout(min(budget, self.timeout or budget))
                    except OSError:
                        sock = None
                        continue
                    try:
                        chunk = sock.recv(want)
                    except socket.timeout:
                        # Whose timeout fired decides the answer: ours means the
                        # wall-clock budget ran out (408, retryable), the peer's
                        # own stall is equally a 408 for the caller.
                        if time.monotonic() >= deadline:
                            raise _BodyDeadlineExceeded() from None
                        raise
                if not chunk:
                    raise _BodyTruncated()
                chunks.append(chunk)
                remaining -= len(chunk)
            return b"".join(chunks)
        finally:
            if sock is not None and prev_timeout is not None:
                try:
                    sock.settimeout(prev_timeout)
                except OSError:
                    pass

    def _read_head_with_deadline(self):
        """Parse the request line and headers under one wall-clock budget.

        `self.timeout` bounds ONE socket operation, and every received byte
        resets it, so a peer that sends a header line every 29 s is never a
        "stall" and holds this thread for as long as it likes. The listener
        is single-threaded, so that also blocks /health.

        The deadline is read ONCE here and travels with the reader: every
        read of the request line and of each header re-arms the raw socket to
        whatever is LEFT of the total, so a trickling peer exhausts the budget
        even though every individual recv succeeds. The body has its own
        budget (`_read_body_with_deadline`), which this one deliberately does
        not touch.
        """
        deadline = time.monotonic() + HEAD_TOTAL_TIMEOUT_SEC
        sock = getattr(self, "connection", None)
        prev_timeout = None
        if sock is not None:
            try:
                prev_timeout = sock.gettimeout()
            except OSError:
                sock = None
        rfile = self.rfile
        try:
            self.rfile = _HeadBudgetReader(rfile, deadline, sock)
            # Reset the parsed-request fields BEFORE reading: a head timeout
            # escapes before `parse_request` ever runs, and `send_error` logs
            # and quotes `self.requestline` - which `setup()` creates only
            # when the previous request completed. A peer that stalled on the
            # very first byte raised AttributeError out of the 408 path
            # instead of answering it.
            self.command = None
            self.request_version = self.default_request_version
            self.requestline = ""
            self.raw_requestline = self.rfile.readline(65537)
            if len(self.raw_requestline) > 65536:
                self.requestline = ""
                self.request_version = ""
                self.command = ""
                self.send_error(414)  # HTTPStatus.REQUEST_URI_TOO_LONG
                return False
            if not self.raw_requestline:
                # The peer closed before sending anything: not an error.
                self.close_connection = True
                return False
            if not self.parse_request():
                # parse_request already sent the error (400/505) or answered
                # an Expect: 100-continue rejection.
                return False
            return True
        finally:
            self.rfile = rfile
            if sock is not None and prev_timeout is not None:
                try:
                    sock.settimeout(prev_timeout)
                except OSError:
                    pass

    def handle_one_request(self):
        """Read one request under the head budget, then dispatch it.

        Reimplemented only to route the request line and headers through
        `_read_head_with_deadline`: the stdlib loop calls `readline` and
        `parse_request` directly, and each of those resets the per-operation
        socket timeout on every byte received. The body budget is applied
        later, inside the handler, and is unaffected.
        """
        try:
            self.raw_requestline = b""
            self.command = None
            self.request_version = self.default_request_version
            self.requestline = ""
            self.headers = None
            if not self._read_head_with_deadline():
                return
            method = getattr(self, "do_" + str(self.command), None)
            if method is None:
                self.send_error(
                    501, "Unsupported method (%r)" % self.command
                )  # HTTPStatus.NOT_IMPLEMENTED
                return
            method()
            self.wfile.flush()
        except (socket.timeout, TimeoutError, _HeadDeadlineExceeded):
            # The head budget ran out. 408 says what happened; dropping the
            # connection silently leaves the peer with no answer at all.
            self.close_connection = True
            # `BaseHTTPRequestHandler.send_error` writes the status line and
            # headers ONLY when `request_version` looks like HTTP/1.x. A head
            # timeout escapes before `parse_request` sets that field, so it is
            # still the stdlib's HTTP/0.9 default here and the peer received a
            # bare body with no status line - i.e. not a 408 at all. The
            # request version is genuinely unknown at this point, so answer as
            # HTTP/1.0: no keep-alive to honour, no chunking to negotiate.
            try:
                if str(self.request_version) not in ("HTTP/1.0", "HTTP/1.1"):
                    self.request_version = "HTTP/1.0"
                self.send_error(408, "Request header timed out")
            except OSError:
                pass
        except ConnectionError:
            self.close_connection = True

    def do_GET(self):
        """Handle GET /metrics, GET /health and GET /version (P22d, P2.10).

        P2.10: /health is a PURE liveness probe  -  no imports, no queue checks,
        no health checker calls. Those are enforced at C-STORE level (handle_c_store).
        /health MUST return in <1ms to avoid serialization bottleneck in
        the single-threaded HTTP server (or thread pool starvation in
        ThreadingHTTPServer).
        """
        if self.path == "/metrics":
            # RSS comes straight from the OS and involves no handle to hold
            # open, so there is nothing to cache between scrapes. A failure
            # leaves the gauge at 0 rather than breaking the scrape.
            memory_usage.set(get_process_rss_bytes())

            # update Outbox queue metrics  -  use cached refs, NO imports
            try:
                _outbox = type(self)._outbox_ref
                if _outbox is not None:
                    outbox_pending.set(_outbox.pending_count())
            except Exception:
                pass

            # update queue-depth gauges  -  cached refs, no imports.
            # Every access is guarded: a broken tracker must not break a scrape.
            try:
                _ct = type(self)._commit_tracker_ref
                if _ct is not None:
                    _n = _ct.pending_count()
                    commit_batches_pending.set(_n)
                    naction_batches_pending.set(_n)
            except Exception:
                pass

            try:
                _mj = type(self)._move_jobs_ref
                if _mj is not None:
                    cmove_jobs_pending.set(_mj.count_pending())
            except Exception:
                pass

            # server_health from real HealthChecker, NOT outbox pending
            try:
                _hc = type(self)._health_checker_ref
                if _hc is not None:
                    server_health.set(1 if _hc.is_healthy() else 0)
            except Exception as e:
                # A checker that raises must not keep reporting the last good
                # value: a stale 1 tells the dashboards the server is alive
                # while the very check that reports it is broken.
                server_health.set(0)
                logging.error("[METRICS] server_health update failed: %s", e)

            metrics_data = generate_latest()  # pyright: ignore[reportOptionalCall]
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; version=0.0.3; charset=utf-8")
            self.send_header("Content-Length", str(len(metrics_data)))
            self.end_headers()
            self.wfile.write(metrics_data)
        elif self.path == "/health":
            # P2.10: /health is a PURE liveness probe. No imports, no queue checks,
            # no health checker  -  just "is the HTTP server alive?".
            # Backpressure (queue%, server health) is enforced at C-STORE level.
            # This MUST be the fastest handler in the system.
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.end_headers()
            self.wfile.write(b"OK")
        elif self.path == "/version":
            # Which bundle is running? Same weight as /health: a constant join,
            # no imports beyond the module constant.
            body = f"clbridge {VERSION} ({BUNDLE_STAMP})".encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()

    def do_POST(self):
        if self.path != "/print":
            self.send_error(404, "Not Found")
            return

        # Validate Content-Type. Compare the media-type ESSENCE, never a
        # substring: `"application/json" in "text/plain; x=application/json"`
        # is True, and text/plain is CORS-safelisted, so a cross-origin page
        # could post a print job with no preflight at all (PS3.18 aside, this
        # is the request boundary). Parameters (charset) are allowed.
        content_type = self.headers.get("Content-Type", "")
        media_type = content_type.split(";", 1)[0].strip().lower()
        if media_type != "application/json":
            self.send_error(400, "Expected application/json")
            return

        # Read body. A non-numeric or negative length is a malformed request,
        # not a reason to drop the connection without an answer: `int()` would
        # raise out of the handler, and a negative length passes the size
        # ceiling below while `read(-1)` blocks the worker on a body that never
        # ends.
        try:
            content_length = int(self.headers.get("Content-Length", 0))
        except (TypeError, ValueError):
            self._json_error(400, "Invalid Content-Length")
            return
        if content_length < 0:
            self._json_error(400, "Invalid Content-Length")
            return
        if content_length > 100 * 1024 * 1024:  # 100 MB limit
            self.send_error(413, "Payload too large")
            return
        # Two failure modes, two answers: too slow is a 408 (the peer can
        # retry with less data), an early EOF is a 400 (the peer lied about
        # the length). Neither may escape do_POST - an uncaught exception here
        # drops the connection with no status at all.
        try:
            body = self._read_body_with_deadline(content_length)
        except _BodyDeadlineExceeded:
            self.send_error(408, "Request body timed out")
            return
        except _BodyTruncated:
            self.send_error(400, "Request body truncated")
            return
        except socket.timeout:
            # The peer STALLED mid-body: the socket read hit the per-connection
            # timeout instead of the wall-clock budget. Same meaning as the
            # deadline case - the request was never answered, so 408, not the
            # dropped connection an uncaught OSError leaves behind.
            self.send_error(408, "Request body read timed out")
            return

        try:
            request_data = json.loads(body)
        except ValueError as e:
            # json.loads(bytes) decodes to str first: non-UTF-8 bytes raise
            # UnicodeDecodeError (a ValueError), not JSONDecodeError. Both are
            # malformed input and must yield a 400, never a dropped connection.
            self._json_error(400, f"Invalid JSON: {e}")
            return
        # A syntactically valid array or scalar is still not a print request,
        # and `request_data.get` would raise AttributeError out of the handler.
        if not isinstance(request_data, dict):
            self._json_error(400, "Expected a JSON object")
            return

        printer_name = request_data.get("printer_name")
        if printer_name is None or printer_name == "":
            self._json_error(400, "Missing printer_name")
            return
        # A list or object here reaches `printer_registry.get(...)` and raises
        # TypeError (unhashable) out of the handler, dropping the connection
        # without the JSON error the caller can act on.
        if not isinstance(printer_name, str):
            self._json_error(400, "printer_name must be a string")
            return
        # `images: null` iterates over None (TypeError), and a string or an
        # object iterates character-by-character / key-by-key: both must be a
        # JSON 400, not a dropped connection or a garbage print job. Checked
        # with the rest of the request shape, before the registry lookup.
        raw_images = request_data.get("images", [])
        if not isinstance(raw_images, list):
            self._json_error(400, "images must be a list")
            return

        printer_cfg = self.printer_registry.get(printer_name)
        if not printer_cfg:
            self._json_error(404, f"Printer '{printer_name}' not found in registry")
            return

        # Decode film_session from JSON -> pydicom Dataset
        try:
            film_session = _json_print_to_dataset(request_data.get("film_session", {}))
        except Exception as e:
            self._json_error(400, f"Invalid film_session: {e}")
            return

        # Decode images from base64 (validated as a list above).
        images = []
        for img_b64 in raw_images:
            try:
                # validate=True: without it b64decode DISCARDS every character
                # outside the alphabet, so a truncated or corrupted image body
                # decoded to some shorter byte string and failed deep inside
                # the print driver instead of here, where the request shape is
                # still known and a 400 is the honest answer.
                if isinstance(img_b64, str):
                    img_b64 = img_b64.encode("ascii")
                images.append(base64.b64decode(img_b64, validate=True))
            except Exception as e:
                self._json_error(400, f"Invalid image base64: {e}")
                return

        # Get calling AE title
        calling_aet = request_data.get("calling_aet", self.bridge_ae_title)

        # Select driver
        driver_name = printer_cfg.get("driver", "generic_dicom")
        driver = self.driver_registry.get(driver_name)
        if not driver:
            self._json_error(500, f"Driver '{driver_name}' not registered")
            return

        # Execute print
        try:
            result = driver.print(
                film_session=film_session,
                images=images,
                printer_host=printer_cfg["host"],
                printer_port=printer_cfg["port"],
                calling_aet=calling_aet,
                # PS3.8 9.3.2.1: the Called AE Title is the PRINT SCP's, not
                # ours. `printer_cfg["aet"]` is what the registry documents as
                # the printer's identity; addressing it with the bridge's own
                # title only works against a peer that accepts anything.
                called_aet=printer_cfg.get("aet") or None,
            )
            self._json_response(200 if result.is_success else 502, result)
        except Exception as e:
            logging.error("[C-PRINT] Print job failed: %s", e)
            logging.debug("[C-PRINT] Full traceback follows:", exc_info=True)
            self._json_error(500, f"Print failed: {e}")

    def _json_response(self, status_code, result):
        """Send JSON PrintResult."""
        body = json.dumps(
            {
                "job_id": result.job_id,
                "status": f"0x{result.status:04X}",
                "film_boxes_printed": result.film_boxes_printed,
                "failed_images": result.failed_images,
                "printer_message": result.printer_message,
            }
        ).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _json_error(self, status_code, message):
        """Send JSON error."""
        body = json.dumps({"error": message}).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, format, *args):
        """Redirect HTTP server logs to Python logging.

        The arguments are passed through, NOT pre-formatted: `format % args`
        raises TypeError as soon as a caller's message does not match the
        format string, and `send_error` passes through text that reached it
        from the request. A logging call must never raise out of the handler.
        """
        logging.debug("[HTTP-BRIDGE] " + format, *args)

# ---------------------------------------------------------------------------
# Bridge: factory for BridgeHTTPHandler with injected dependencies
# ---------------------------------------------------------------------------
def make_bridge_handler(
    driver_registry,
    printer_registry,
    bridge_ae_title,
    health_checker=None,
    outbox=None,
    commit_tracker=None,
    move_jobs=None,
):
    """Create BridgeHTTPHandler subclass with injected dependencies.

    P2.10: Injects bridge runtime dependencies (outbox, etc.)
    as class-level attributes so do_GET() never does lazy imports. This eliminates
    the per-request import lock contention that was serializing /health behind
    /metrics in the single-threaded HTTPServer.

    PH-007: health_checker is stored for real server_health gauge.
    """

    class _Handler(BridgeHTTPHandler):
        pass

    _Handler.driver_registry = driver_registry
    _Handler.printer_registry = printer_registry
    _Handler.bridge_ae_title = bridge_ae_title
    _Handler._outbox_ref = outbox
    _Handler._health_checker_ref = health_checker
    _Handler._commit_tracker_ref = commit_tracker
    _Handler._move_jobs_ref = move_jobs
    return _Handler

# ---------------------------------------------------------------------------
# Bridge: prefetch
# ---------------------------------------------------------------------------

"""Bounded FIFO prefetch for the C-MOVE read path (B1, 2508).

A reader thread pulls `(dicom_bytes, idx)` from a source generator and fills a
bounded queue; the sender drains it. Structural backpressure is the bounded
queue itself: the reader blocks when it is full, the sender when it is empty,
so memory is bounded by `max_parts` and the Clarus server leg stays busy while
the sender is blocked on C-STORE network I/O - raising end-to-end C-MOVE
toward the server ceiling (the serial pipeline left the server idle during
each C-STORE).
"""

import logging
import os
import queue
import threading

# Default queue depth: 4 parts (~20 MB for typical CT slices), FIFO.
# A module-level constant so production and tests observe the same value.
DEFAULT_PREFETCH_PARTS = 4

# Sentinel: the reader has finished (EOF) or hit a fatal error to surface.
_EOF = object()

class PartPrefetcher:
    """Bounded FIFO prefetch bridging a reader thread and the sender loop.

    Usage:
        pref = PartPrefetcher(_stream_multipart_instances(resp)).start()
        for part, idx, part_ts in pref:
            ... send ...
        # On early exit (cancel / shutdown / fatal error):
        pref.stop()

    The source yields the three fields `_stream_multipart_instances` produces;
    unpacking two raised ValueError on the very first part.
    """

    def __init__(self, source, max_parts=DEFAULT_PREFETCH_PARTS, on_stop=None):
        self._q = queue.Queue(maxsize=max_parts)
        self._source = source
        self._error = None
        self._stop = threading.Event()
        # Guards the once-only claim of `_on_stop`. `stop()` is idempotent and
        # can be called from both the sender and the shutdown path, so two
        # calls used to start two close threads against the SAME response - a
        # second `close()` re-entering urllib3 while the first is still waiting
        # on the socket read.
        self._on_stop_lock = threading.Lock()
        self._on_stop_claimed = False
        # Called ONCE by `stop()` BEFORE the join. The reader may be blocked
        # inside the source (an `iter_content` on a slow or half-open HTTP
        # response), where no queue drain can reach it; closing the response
        # makes that read return, so the join does not sit out its whole
        # timeout on every early exit.
        self._on_stop = on_stop
        self._thread = threading.Thread(
            target=self._fill, name="cmove-prefetch", daemon=True
        )

    def _fill(self):
        try:
            for item in self._source:
                if self._stop.is_set():
                    # The item is already pulled from the source and will
                    # never be consumed - release a spilled part here, since
                    # the queue cannot show it to the drain.
                    self._discard(item)
                    break
                # `put_nowait` in a bounded wait loop rather than a bare
                # `put`: a bare put parks the reader until a slot frees, and
                # `stop()` only frees one slot per drain pass. A reader that
                # parked AFTER the stop check could therefore publish its part
                # after the final drain had run, leaving a spill file that no
                # one would ever unlink. Here the stop flag is re-checked every
                # 50 ms, so the reader always gets out on its own, and the item
                # it was holding is discarded rather than queued.
                while True:
                    try:
                        self._q.put(item, timeout=0.05)
                        break
                    except queue.Full:
                        if self._stop.is_set():
                            self._discard(item)
                            return
        except Exception as e:  # surface a reader failure to the sender
            self._error = e
        finally:
            # The EOF sentinel must NEVER be dropped. It is the only thing that
            # ends the sender's `get()`, so a sentinel lost to a full queue
            # blocks the drain forever - the reader has finished, nothing more
            # will ever arrive, and the C-MOVE hangs instead of ending.
            #
            # Waits on the queue rather than on a bounded timeout, but the wait
            # is always finite: either a sender drains a slot, or `stop()`
            # clears the flag and the loop gives up. On give-up the drain is
            # already gone, which is exactly what the abandoned sentinel means.
            while True:
                try:
                    self._q.put(_EOF, timeout=0.05)
                    break
                except queue.Full:
                    if self._stop.is_set():
                        break
                except Exception:
                    break

    def start(self):
        """Start the reader thread. Returns self."""
        self._thread.start()
        return self

    def __iter__(self):
        """Yield `(part, idx, part_ts)` as the reader produces them, in order."""
        while True:
            item = self._q.get()
            if item is _EOF:
                if self._error is not None:
                    raise self._error
                return
            yield item

    def _drain(self):
        """Discard queued items, unlinking any spilled part they carry."""
        while True:
            try:
                item = self._q.get_nowait()
            except queue.Empty:
                return
            self._discard(item)

    @staticmethod
    def _discard(item):
        """Unlink the temp file of a discarded, never-consumed part."""
        part = item[0] if isinstance(item, tuple) and item else None
        if isinstance(part, SpilledPart):
            try:
                os.unlink(part.path)
            except OSError:
                pass

    def stop(self):
        """Force the reader to finish and wait for it (non-fatal, idempotent).

        Called when the sender exits early (cancel / shutdown / fatal error).
        The reader may be blocked on `put` while the queue is full; draining
        the queue frees a slot so it can observe the stop flag and exit.
        A drained part that was spilled to disk is unlinked here: nothing
        downstream will ever consume it, so the temp file would otherwise
        stay behind (the parser drops only malformed parts, and the sender
        loop unlinks only the part it has already taken).

        Drained TWICE: the first pass frees the slot the reader is blocked on,
        and the reader then parks the part it was holding, so a pass that
        finished before that wake-up would miss it and leave its spill file
        behind. The second pass after the join catches exactly that item.

        `on_stop` runs BEFORE the join: the drain only frees a reader blocked
        in `put`, while a reader blocked inside the source (iterating a slow
        or half-open response) is only reachable by closing what it reads.
        Without the callback every early exit waited out the whole 5 s join.

        The callback itself runs on its OWN daemon thread. Closing an HTTP
        response can wait for the read that is in flight to return, which is
        exactly the stall this method exists to escape: run inline, a blocked
        `resp.close()` sat outside the join bound and held `stop()` (and the
        resume path behind it) until the socket read ended. On a helper thread
        the join bound is the only bound, and the close finishes whenever the
        read does.
        """
        self._stop.set()
        if self._claim_on_stop():
            closer = threading.Thread(
                target=self._run_on_stop, name="cmove-prefetch-close", daemon=True
            )
            closer.start()
        self._drain()
        if self._thread.is_alive():
            self._thread.join(timeout=5.0)
            if self._thread.is_alive():
                logging.warning("[B1-prefetch] reader thread did not exit in 5s")
        self._drain()

    def _claim_on_stop(self):
        """True exactly once, for the first caller that has an `on_stop`.

        The claim is taken under a lock rather than by testing a flag, because
        `stop()` legitimately runs on more than one thread: the sender's early
        exit and the shutdown path can both call it, and both would otherwise
        start their own close thread.
        """
        if self._on_stop is None:
            return False
        with self._on_stop_lock:
            if self._on_stop_claimed:
                return False
            self._on_stop_claimed = True
            return True

    def _run_on_stop(self):
        """Run the close callback; its failure must not kill the helper."""
        try:
            self._on_stop()
        except Exception:
            pass

# ---------------------------------------------------------------------------
# Bridge: move_jobs
# ---------------------------------------------------------------------------

"""Clarus Bridge - C-MOVE job queue and SCP target registry (BR-007).

MoveJobManager: SQLite-backed C-MOVE job queue with SCP target auto-registration.
Thread-safe via SharedDb: one connection, one lock.
Survives bridge restarts.

Known limitations:
- C-MOVE-CANCEL not supported. Client can close association;
  Bridge finishes the current job (data won't be lost).
- No duplicate SOP check before re-send after restart.
- Double I/O: temp-file -> read -> send (streaming future).
"""

import ipaddress
import logging
import sqlite3
import threading
import time

# ---------------------------------------------------------------------------
# DB Migration helpers (subnet support, composite keys)
# ---------------------------------------------------------------------------
def _migrate_move_jobs(conn):
    """Add target_host/target_port columns if missing (pre-existing DBs)."""
    cols = {r[1] for r in conn.execute("PRAGMA table_info('move_jobs')").fetchall()}
    if "target_host" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN target_host TEXT NOT NULL DEFAULT ''"
        )
    if "target_port" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN target_port INTEGER NOT NULL DEFAULT 0"
        )
    # (0008,0058) Failed SOP Instance UID List - newline-joined UIDs of
    # the slices that failed transfer in this job (PS3.4 C.4.2.1.4.2). The
    # C-MOVE reactor reads it to put the list on the final Failed/Cancel/
    # Warning C-MOVE-RSP Identifier.
    if "failed_sops" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN failed_sops TEXT NOT NULL DEFAULT ''"
        )
    # Per-association expose flag: 1 when this job was requested over the
    # Expose Rejected Instances AE. Carried on the job because the C-MOVE
    # worker threads are long-lived and outlive the association that queued
    # the work, so it cannot be read from the event when the job runs.
    if "expose_rejected" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN expose_rejected INTEGER NOT NULL DEFAULT 0"
        )
    # PS3.4 C.4.2.1.2: the C-MOVE-RQ names the SCOPE (STUDY/SERIES/IMAGE) and
    # the UIDs that scope it. The level and UIDs live on the job because the
    # worker thread outlives the association that queued the work. An empty
    # level means STUDY (the historical behaviour), so an existing row keeps
    # the meaning it had.
    if "request_level" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN request_level TEXT NOT NULL DEFAULT ''"
        )
    if "request_series_uid" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN request_series_uid TEXT"
            " NOT NULL DEFAULT ''"
        )
    if "request_sop_uid" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN request_sop_uid TEXT NOT NULL DEFAULT ''"
        )
    # The peers.conf KEY the destination was matched under. For a CIDR entry
    # that is the subnet ("192.168.1.0/24"), not the client IP the association
    # actually goes to: `scp_targets` is keyed by that configured host, so
    # recording success/failure against the client IP updated no row and a
    # subnet-backed peer never accumulated (or cleared) its failure streak.
    if "registry_host" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN registry_host TEXT NOT NULL DEFAULT ''"
        )
    # SOP instance UIDs this job has DELIVERED, newline-joined, written as the
    # peer acknowledges each one. The pass's returned list is the other carrier
    # and a raising pass never produces it, so without this column a mid-stream
    # exception wiped the resume skip set and the resumed pass re-sent instances
    # the destination already held.
    if "delivered_sops" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN delivered_sops TEXT NOT NULL DEFAULT ''"
        )

    # Instances the destination ACCEPTED with a C-STORE Warning (PS3.4 B.2.3.1)
    # across every pass. They are delivered, so they are not in failed_sops -
    # but Table C.4-2 gives "sub-operations completed with warnings" its own
    # status (0xB000), and the reactor builds that response, not the worker.
    if "warning_count" not in cols:
        conn.execute(
            "ALTER TABLE move_jobs ADD COLUMN warning_count INTEGER NOT NULL DEFAULT 0"
        )

    # One row per DELIVERED SOP. The `delivered_sops` TEXT column above holds
    # the same information as a newline-joined blob, and each acknowledgement
    # read it, split it, appended and wrote the WHOLE value back under the
    # shared DB lock: a 5000-instance study did 12.5 M string copies while
    # blocking every progress poll and every other worker's claim. A child
    # table makes one acknowledgement one INSERT, and the primary key makes a
    # duplicate acknowledgement idempotent without a read-modify-write.
    conn.execute(
        "CREATE TABLE IF NOT EXISTS move_job_delivered ("
        "  job_id INTEGER NOT NULL,"
        "  sop_uid TEXT NOT NULL,"
        "  sop_class TEXT NOT NULL DEFAULT '',"
        "  PRIMARY KEY (job_id, sop_uid)"
        ")"
    )

def _migrate_scp_targets(conn):
    """Migrate scp_targets from single PK (ae_title) to composite (ae_title, host).

    Preserves existing data. Idempotent  -  safe to run multiple times.
    """
    # Check if old schema (ae_title as sole PK) exists
    cols = {r[1] for r in conn.execute("PRAGMA table_info('scp_targets')").fetchall()}
    if not cols:
        # Table doesn't exist yet  -  create with v2 schema
        conn.execute(
            "CREATE TABLE IF NOT EXISTS scp_targets ("
            "  ae_title TEXT NOT NULL,"
            "  host TEXT NOT NULL,"
            "  port INTEGER NOT NULL DEFAULT 104,"
            "  last_seen INTEGER NOT NULL,"
            "  consecutive_failures INTEGER DEFAULT 0,"
            "  PRIMARY KEY (ae_title, host)"
            ")"
        )
        return

    # Check if already migrated: composite PK present.
    # SQLite PRAGMA table_info doesn't directly show composite PK.
    # Check by trying to insert a duplicate (ae, host)  -  if UNIQUE constraint
    # fails on (ae_title) alone, we're on old schema.
    # Simpler: check if 'host' is part of PK by looking at the CREATE TABLE sql
    create_sql = conn.execute(
        "SELECT sql FROM sqlite_master WHERE type='table' AND name='scp_targets'"
    ).fetchone()
    if create_sql and "PRIMARY KEY (ae_title, host)" in create_sql[0]:
        return  # Already v2

    # Migrate: create v2, copy data, drop v1, rename.
    #
    # Crash-safe (each step is idempotent on its own):
    #   * `scp_targets_v2` may already exist from a crashed run - IF NOT EXISTS
    #     turns the leftover into a no-op instead of "table already exists";
    #   * the copy is INSERT OR IGNORE, so re-running after a partial copy adds
    #     only the rows that are still missing;
    #   * DROP + RENAME happen together, so a crash between them leaves either
    #     the old table intact (safe: the migration runs again) or v2 already
    #     named `scp_targets` (safe: the PK check above returns early);
    #   * a leftover `scp_targets_v2` from a crash AFTER the rename cannot
    #     exist, because RENAME removes it.
    # Before this, a crash after the CREATE left `scp_targets_v2` behind, and
    # the next start died on "table scp_targets_v2 already exists" - a bridge
    # that could not open its own database.
    conn.execute(
        "CREATE TABLE IF NOT EXISTS scp_targets_v2 ("
        "  ae_title TEXT NOT NULL,"
        "  host TEXT NOT NULL,"
        "  port INTEGER NOT NULL DEFAULT 104,"
        "  last_seen INTEGER NOT NULL,"
        "  consecutive_failures INTEGER DEFAULT 0,"
        "  PRIMARY KEY (ae_title, host)"
        ")"
    )
    # The v1 table may be gone already (a crash between DROP and RENAME): the
    # copy then has nothing to read, which is not an error.
    try:
        conn.execute(
            "INSERT OR IGNORE INTO scp_targets_v2"
            " SELECT ae_title, host, port, last_seen, consecutive_failures"
            " FROM scp_targets"
        )
    except sqlite3.OperationalError:
        logging.debug("[MOVE-JOBS] scp_targets_v1 already migrated away")
    conn.execute("DROP TABLE IF EXISTS scp_targets")
    conn.execute("ALTER TABLE scp_targets_v2 RENAME TO scp_targets")

# ---------------------------------------------------------------------------
# Bridge: C-MOVE job queue and SCP target registry
# ---------------------------------------------------------------------------
class MoveJobManager:
    """SQLite-backed C-MOVE job queue with SCP target auto-registration.

    Thread-safe via SharedDb  -  "one connection, one lock".
    Survives bridge restarts.

    Known limitations:
    - C-MOVE-CANCEL not supported. Client can close association;
      Bridge finishes the current job (data won't be lost).
    - No duplicate SOP check before re-send after restart.
    - Double I/O: temp-file -> read -> send (streaming future).
    """

    def __init__(self, shared_db, max_workers=2, scp_remove_failures=3):
        """shared_db: SharedDb instance (NOT raw sqlite3.Connection).

        Uses SharedDb.locked() for ALL DB operations - no own lock.
        One connection, one lock: a single serialized writer avoids both lock
        ordering bugs and SQLite busy-handler tuning.

        scp_remove_failures: consecutive-failure threshold for the auto-remove
        of an auto-registered SCP peer (CM-006). Fixed constant 3 (fed from
        `_SCP_FAILURES_BEFORE_REMOVE` in main.py); there is no config knob.
        """
        self._db = shared_db  # SharedDb, NOT sqlite3.Connection
        self._cond = (
            threading.Condition()
        )  # notify workers (own cond, not on SharedDb lock)
        self.max_workers = max_workers
        self.scp_remove_failures = max(1, int(scp_remove_failures or 3))
        self._cancel_callbacks = {}  # job_id -> callable
        self._last_peers_reload = 0.0  # timestamp of last peers reload
        self.lazyload_peers_interval = (
            30  # seconds between peers.conf reloads (0 = every call)
        )

        with self._db.locked() as conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS move_jobs ("
                "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
                "  study_uid TEXT NOT NULL,"
                "  move_dest_ae TEXT NOT NULL,"
                "  target_host TEXT NOT NULL DEFAULT '',"
                "  target_port INTEGER NOT NULL DEFAULT 0,"
                "  status TEXT NOT NULL DEFAULT 'pending',"
                "  total_instances INTEGER DEFAULT 0,"
                "  completed_instances INTEGER DEFAULT 0,"
                "  failed_instances INTEGER DEFAULT 0,"
                "  error_message TEXT,"
                "  failed_sops TEXT NOT NULL DEFAULT '',"
                "  warning_count INTEGER NOT NULL DEFAULT 0,"
                "  created_at INTEGER NOT NULL,"
                "  updated_at INTEGER NOT NULL,"
                "  attempts INTEGER DEFAULT 0,"
                "  expose_rejected INTEGER NOT NULL DEFAULT 0"
                ")"
            )
            # Migration: add target_host/target_port columns if missing (pre-existing DBs)
            _migrate_move_jobs(conn)
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_move_jobs_status ON move_jobs(status)"
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_move_jobs_created ON move_jobs(created_at)"
            )
            # scp_targets v2: composite primary key (ae_title, host) for subnet support
            _migrate_scp_targets(conn)
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_scp_targets_ae ON scp_targets(ae_title)"
            )
            conn.commit()

    # --- move_jobs CRUD ---

    def create_job(
        self,
        study_uid,
        move_dest_ae,
        target_host="",
        target_port=0,
        expose_rejected=False,
        request_level="",
        request_series_uid="",
        request_sop_uid="",
        registry_host="",
        claimable=True,
    ):
        """Create a new pending C-MOVE job. Returns job id.

        target_host/target_port: resolved Move Destination address.
        Stored so worker doesn't need to re-resolve (subnet support).
        expose_rejected: the job was queued over the QA AE; the worker queries
        the configured `[dicomweb] qa_url` endpoint instead of `clarus_url`.
        Stored because the worker outlives the association.
        request_level/request_series_uid/request_sop_uid: the Query/Retrieve
        scope of the request (PS3.4 C.4.2.1.2), stored for the same reason -
        a SERIES-level C-MOVE must not retrieve the whole study.
        registry_host: the peers.conf key the destination matched under. For a
        CIDR entry this is the SUBNET while `target_host` is the client IP the
        association goes to; SCP health is recorded against the key.
        claimable: when False the row is inserted as 'held', which no worker
        picks. A multi-scope request publishes all of its jobs this way and
        then calls `release_held_jobs()`, so no worker can start the first
        scope while the handler is still submitting the rest (a second insert
        that then failed left a job already sending while the SCU got an
        error, and the worker could observe `is_job_cancelled()` as False
        before the cancel callback was installed).
        """
        now = int(time.time())
        initial_status = "pending" if claimable else "held"
        with self._db.locked() as conn:
            cur = conn.execute(
                "INSERT INTO move_jobs"
                " (study_uid, move_dest_ae, target_host, target_port,"
                "  status, created_at, updated_at, expose_rejected,"
                "  request_level, request_series_uid, request_sop_uid,"
                "  registry_host)"
                " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    study_uid,
                    move_dest_ae,
                    target_host,
                    target_port,
                    initial_status,
                    now,
                    now,
                    1 if expose_rejected else 0,
                    str(request_level or ""),
                    str(request_series_uid or ""),
                    str(request_sop_uid or ""),
                    str(registry_host or target_host or ""),
                ),
            )
            conn.commit()
            job_id = cur.lastrowid
        # NOTIFY AFTER the db lock is released. `pick_pending_job` takes
        # `_cond` and then `_db` (it must, to make its empty-check and wait
        # atomic against this notify); notifying while still holding `_db`
        # made this path `_db -> _cond`, the exact opposite order. A worker
        # holding `_cond` waiting for `_db` and a reactor holding `_db`
        # waiting for `_cond` deadlock the whole C-MOVE subsystem, including
        # the metrics scrape. The wakeup is only a hint, so releasing first
        # costs nothing: a worker that cannot see the new row yet simply
        # re-selects under `_cond`.
        with self._cond:
            self._cond.notify()
        return job_id

    def count_pending(self):
        """Number of jobs in the 'pending' state (drain gauge).

        Read-only and cheap (one indexed COUNT); never raises, so a metrics
        scrape cannot be broken by a busy/locked database - returns 0 instead.
        """
        try:
            with self._db.locked() as conn:
                row = conn.execute(
                    "SELECT COUNT(*) FROM move_jobs WHERE status = 'pending'"
                ).fetchone()
            return int(row[0]) if row else 0
        except Exception:
            return 0

    def release_held_jobs(self, job_ids):
        """Make `held` rows claimable. Returns how many were released.

        The publication step of a multi-scope C-MOVE request: every scope is
        inserted as 'held' (see `create_job`), the request's cancellation
        state is installed, and only then are all of them made pending
        together. A single UPDATE is the barrier - no worker can observe a
        partial set, and no scope can start before the request is ready.
        """
        ids = [int(i) for i in job_ids if i is not None]
        if not ids:
            return 0
        placeholders = ",".join("?" for _ in ids)
        with self._db.locked() as conn:
            cur = conn.execute(
                f"UPDATE move_jobs SET status = 'pending'"
                f" WHERE status = 'held' AND id IN ({placeholders})",
                ids,
            )
            conn.commit()
            released = cur.rowcount or 0
        if released:
            with self._cond:
                self._cond.notify_all()
        return released

    def _select_pending(self):
        """The pending-row SELECT used by `pick_pending_job`.

        Split out so the caller can run it while holding `self._cond`, which
        is what makes the empty-check/wait pair atomic against `insert`'s
        notify.
        """
        with self._db.locked() as conn:
            return conn.execute(
                "SELECT id, study_uid, move_dest_ae, attempts,"
                " target_host, target_port"
                " FROM move_jobs WHERE status = 'pending'"
                " ORDER BY created_at ASC"
            ).fetchall()

    def pick_pending_job(self, timeout=5.0, skip=None, reserve=None, release=None):
        """Atomically pick one pending job, optionally RESERVING its peer.

        `reserve(host, port, ae) -> bool` is a non-blocking claim of the peer
        (a per-peer gate in the worker). It runs while the pick is still a
        candidate, BEFORE the row is claimed: a peer that cannot be reserved is
        skipped, so the caller never holds a claimed job it cannot start. That
        is what keeps two workers from claiming two jobs for the same peer and
        leaving a job for a DIFFERENT peer unserved behind a blocking wait.

        A candidate that is claimed but then found gone (another worker won the
        race) releases its reservation through `release`, so the gate is not
        leaked by the losing thread.

        `skip(host, port, ae) -> bool` remains as an advisory filter.

        Returns dict or None.
        """
        while True:
            # The empty-check and the wait must be ONE atomic step against the
            # notifier. `insert` wakes a waiter under `self._cond`; taking the
            # same lock around the SELECT closes the lost-wakeup window where a
            # row was inserted after an empty SELECT and before the wait, which
            # left the worker asleep with pending work on disk until the
            # timeout expired.
            with self._cond:
                rows = self._select_pending()
                if skip is not None:
                    rows = [
                        r for r in rows if not skip(r[4] or "", r[5] or 0, r[2] or "")
                    ]
                if not rows:
                    if not self._cond.wait(timeout=timeout):
                        return None
                    continue

            claimed = None
            for row in rows:
                if reserve is not None and not reserve(
                    row[4] or "", row[5] or 0, row[2] or ""
                ):
                    # Another worker holds this peer: leave the row pending and
                    # look at the next one, so a job for a different peer is
                    # still served by THIS worker.
                    continue
                # The claim can RAISE - a SQLite error while the row is being
                # updated - and an exception escaping here skipped `release`,
                # leaking the peer reservation for the life of the process. The
                # leaked gate then made every other worker skip that peer, and
                # because the raise also escaped the worker loop's SELECT the
                # worker itself died. Every unsuccessful claim therefore
                # releases, and a claim error is retried against the next
                # candidate instead of killing the worker.
                try:
                    claimed = self._claim_row(row[0])
                except Exception as claim_err:
                    logging.error(
                        "[MOVE-JOBS] claim of job %s failed (%s) - releasing "
                        "the peer reservation and trying the next candidate",
                        row[0],
                        claim_err,
                    )
                    claimed = None
                    if release is not None:
                        try:
                            release(row[4] or "", row[5] or 0, row[2] or "")
                        except Exception:
                            pass
                    continue
                if claimed is not None:
                    return claimed
                # Lost the claim race: hand the reservation back.
                if release is not None:
                    release(row[4] or "", row[5] or 0, row[2] or "")
            # Every candidate was either busy or lost: wait like an empty queue.
            with self._cond:
                if not self._cond.wait(timeout=timeout):
                    return None

    def job_has_live_worker(self, job_id):
        """True when `job_id` may still be read by a worker.

        That is 'in_progress' (a worker owns it now) AND 'pending' (no worker
        has claimed it yet, but one can, and it must observe a cancel that was
        latched before it started). Only a TERMINAL job has nobody left to
        read the latch: installing one there leaves a callback in the registry
        that no worker would ever clear.
        """
        try:
            with self._db.locked() as conn:
                row = conn.execute(
                    "SELECT status FROM move_jobs WHERE id = ?", (job_id,)
                ).fetchone()
            return bool(row) and row[0] in ("pending", "in_progress")
        except Exception:
            return False

    def _claim_row(self, job_id):
        """Claim `job_id` for this worker, or None when another worker won it."""
        now = int(time.time())
        with self._db.locked() as conn:
            row2 = conn.execute(
                "SELECT id, study_uid, move_dest_ae, attempts,"
                " target_host, target_port, expose_rejected,"
                " request_level, request_series_uid, request_sop_uid,"
                " registry_host"
                " FROM move_jobs WHERE status = 'pending' AND id = ?",
                (job_id,),
            ).fetchone()
            if not row2:
                return None  # Another worker claimed it

            conn.execute(
                "UPDATE move_jobs SET status = 'in_progress',"
                " updated_at = ?, attempts = attempts + 1"
                " WHERE id = ? AND status = 'pending'",
                (now, job_id),
            )
            conn.commit()
            return {
                "id": job_id,
                "study_uid": row2[1],
                "move_dest_ae": row2[2],
                "attempts": row2[3],
                "target_host": row2[4],
                "target_port": row2[5],
                # The worker outlives the association that queued the job,
                # so which base URL to stream from has to come from the
                # row. Omitting it here silently sent every QA job to
                # clarus_url, i.e. the sequester was never lifted.
                "expose_rejected": int(row2[6] or 0),
                # PS3.4 C.4.2.1.2: the scope travels with the job for the
                # same reason - the worker no longer has the event.
                "request_level": str(row2[7] or ""),
                "request_series_uid": str(row2[8] or ""),
                "request_sop_uid": str(row2[9] or ""),
                # The peers.conf key, NOT the connection address: for a
                # CIDR peer the two differ and SCP health is keyed by the
                # former.
                "registry_host": str(row2[10] or row2[4] or ""),
            }

    def requeue_job_without_retry(self, job_id):
        """Return a claimed job to pending without charging it an attempt (R9).

        The worker claims a job and THEN takes the per-peer gate, so with more
        than one worker a job could be claimed for a peer another worker was
        already streaming to. It was then invisible in `in_progress/` for the
        whole of that transfer. This hands it back so other workers can see it;
        `attempts` is decremented because the claim already incremented it and
        nothing was attempted - otherwise a busy peer would burn the job's
        retry budget without a single C-STORE.

        Only a job still in `in_progress` for this claim is released: a job the
        reaper or a cancel already moved is not ours to rewrite.
        """
        now = int(time.time())
        with self._db.locked() as conn:
            cur = conn.execute(
                "UPDATE move_jobs SET status = 'pending', attempts = "
                "CASE WHEN attempts > 0 THEN attempts - 1 ELSE 0 END,"
                " updated_at = ? WHERE id = ? AND status = 'in_progress'",
                (now, job_id),
            )
            conn.commit()
            changed = cur.rowcount or 0
        if changed:
            with self._cond:
                self._cond.notify()
        return bool(changed)

    def update_job_progress(self, job_id, completed, failed, total):
        """Update job progress counters (CM-005)."""
        now = int(time.time())
        with self._db.locked() as conn:
            conn.execute(
                "UPDATE move_jobs SET completed_instances = ?,"
                " failed_instances = ?, total_instances = ?,"
                " updated_at = ? WHERE id = ?",
                (completed, failed, total, now, job_id),
            )
            conn.commit()

    def get_job_progress(self, job_id):
        """Return (completed, total, status) for a job. Used by C-MOVE generator for 0xFF00 polling."""
        with self._db.locked() as conn:
            row = conn.execute(
                "SELECT completed_instances, total_instances, status"
                " FROM move_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if row is None:
                return (0, 0, "unknown")
            return (row[0], row[1], row[2])

    def add_job_delivered_sop(self, job_id, sop_uid, sop_class=""):
        """Record one DELIVERED SOP instance (and its class) for the job.

        Written as the peer acknowledges each instance, not at the end of the
        pass: the pass's own list is lost when it raises, and the resume uses
        this record to skip what has already arrived.

        ONE INSERT into the child table. `INSERT OR IGNORE` keyed on
        (job_id, sop_uid) makes a duplicate acknowledgement idempotent without
        reading the previous value, so an acknowledgement costs the same
        whether the study holds ten instances or ten thousand.
        """
        if not sop_uid:
            return
        with self._db.locked() as conn:
            row = conn.execute(
                "SELECT id FROM move_jobs WHERE id = ?", (job_id,)
            ).fetchone()
            if row is None:
                # The job row was already retired; recording a delivery for a
                # row that no longer exists would resurrect nothing.
                return
            conn.execute(
                "INSERT OR IGNORE INTO move_job_delivered"
                " (job_id, sop_uid, sop_class) VALUES (?, ?, ?)",
                (job_id, str(sop_uid), str(sop_class or "")),
            )
            conn.commit()

    def get_job_delivered_sops(self, job_id):
        """`[(sop_class, sop_uid), ...]` recorded as delivered for this job."""
        with self._db.locked() as conn:
            rows = conn.execute(
                "SELECT sop_class, sop_uid FROM move_job_delivered"
                " WHERE job_id = ? ORDER BY rowid",
                (job_id,),
            ).fetchall()
        return [(str(r[0] or ""), str(r[1])) for r in rows]

    def set_job_failed_sops(self, job_id, uids):
        """Store the (0008,0058) Failed SOP Instance UID List for a job.

        newline-joined UIDs of the slices that were attempted but not
        delivered. Read back by the C-MOVE generator so the final
        Failed/Cancel/Warning C-MOVE-RSP Identifier carries the list
        (PS3.4 C.4.2.1.4.2). Call once at job end.
        """
        text = "\n".join(u for u in (uids or []) if u)
        now = int(time.time())
        with self._db.locked() as conn:
            conn.execute(
                "UPDATE move_jobs SET failed_sops = ?, updated_at = ? WHERE id = ?",
                (text, now, job_id),
            )
            conn.commit()

    def set_job_warning_count(self, job_id, count):
        """Record how many instances the destination accepted WITH a warning.

        PS3.4 B.2.3.1: a C-STORE Warning means the SCP stored the instance, so
        those UIDs are delivered and never belong in the failed tail. They are
        still not plain successes: PS3.4 Table C.4-2 reserves 0xB000 for
        "sub-operations completed with warnings", so the tally has to survive
        the worker that computed it - the reactor builds the final response.
        """
        try:
            value = max(0, int(count or 0))
        except (TypeError, ValueError):
            value = 0
        now = int(time.time())
        with self._db.locked() as conn:
            conn.execute(
                "UPDATE move_jobs SET warning_count = ?, updated_at = ? WHERE id = ?",
                (value, now, job_id),
            )
            conn.commit()

    def get_job_warning_count(self, job_id):
        """The warning tally recorded by `set_job_warning_count`. 0 if unset."""
        try:
            with self._db.locked() as conn:
                row = conn.execute(
                    "SELECT warning_count FROM move_jobs WHERE id = ?", (job_id,)
                ).fetchone()
            return int(row[0]) if row and row[0] else 0
        except Exception:
            return 0

    def get_job_failed_sops(self, job_id):
        """Return the (0008,0058) Failed SOP Instance UID list for a job."""
        with self._db.locked() as conn:
            row = conn.execute(
                "SELECT failed_sops FROM move_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
        if not row or not row[0]:
            return []
        return [u for u in str(row[0]).split("\n") if u]

    def finish_job(self, job_id, success=True, error_message=None):
        """Mark job as success or failed. A terminal row is never rewritten.

        Two wakers can finish the same job - the poll reactor on timeout and
        the worker when it reaches the end of the instance list - and the last
        writer would otherwise decide the outcome. A row that already says
        `failed` must not turn into `success` (or the reverse), because the
        viewer was already told the first verdict and the counter was already
        incremented for it.

        Returns True when THIS call moved the row to a terminal status, False
        when another waker had already finished it. The caller must use that
        answer before counting the outcome: a second waker that counts its own
        call double-counts a job that only finished once.
        """
        status = "success" if success else "failed"
        now = int(time.time())
        with self._db.locked() as conn:
            cur = conn.execute(
                "UPDATE move_jobs SET status = ?, error_message = ?,"
                " updated_at = ? WHERE id = ?"
                " AND status NOT IN ('success', 'failed')",
                (status, error_message or "", now, job_id),
            )
            conn.commit()
            return cur.rowcount > 0

    def reset_job_to_pending(self, job_id, reason=""):
        """Reset an in_progress job back to pending (viewer busy, retry later)."""
        now = int(time.time())
        with self._db.locked() as conn:
            conn.execute(
                "UPDATE move_jobs SET status = 'pending', error_message = ?,"
                " updated_at = ? WHERE id = ?",
                (reason, now, job_id),
            )
            conn.commit()
        with self._cond:
            self._cond.notify()  # Wake a worker to process the reset job (after fail_timeout)

    def recover_in_progress_jobs(self):
        """On startup: reset all in_progress jobs to pending (CM-007)."""
        now = int(time.time())
        with self._db.locked() as conn:
            cur = conn.execute(
                "UPDATE move_jobs SET status = 'pending', updated_at = ?"
                " WHERE status = 'in_progress'",
                (now,),
            )
            conn.commit()
            return cur.rowcount

    def cleanup_old_jobs(self, max_age_seconds=86400):
        """Remove success/failed jobs older than max_age_seconds (default 24h) (CM-008)."""
        with self._db.locked() as conn:
            cutoff = int(time.time()) - max_age_seconds
            conn.execute(
                "DELETE FROM move_jobs WHERE status IN ('success', 'failed')"
                " AND updated_at < ?",
                (cutoff,),
            )
            conn.commit()

    # --- scp_targets CRUD ---

    def register_peer(self, ae_title, host, port=104):
        """Register or update a manually configured peer from peers.conf.

        Composite key (ae_title, host)  -  supports multiple entries per AE
        (exact IP + CIDR subnet, or multiple subnets).
        Non-CIDR (exact IP) entries: only ONE per AE title  -  re-registration
        with a different host replaces the old one. CIDR entries coexist.
        """
        now = int(time.time())
        with self._db.locked() as conn:
            # Non-CIDR host: delete any existing non-CIDR entry for this AE
            # so re-registration with a different IP replaces the old one.
            if "/" not in host:
                conn.execute(
                    "DELETE FROM scp_targets"
                    " WHERE ae_title = ? AND host NOT LIKE '%/%'",
                    (ae_title,),
                )
            conn.execute(
                "INSERT OR REPLACE INTO scp_targets"
                " (ae_title, host, port, last_seen, consecutive_failures)"
                " VALUES (?, ?, ?, ?, 0)",
                (ae_title, host, port, now),
            )
            conn.commit()
        logging.info(
            "[PEER] Registered %s at %s:%d",
            ae_title,
            host,
            port,
        )

    def _lookup_target(self, ae_title, host):
        """(host, port) stored for the exact (ae_title, host) key, or None.

        Read in its own lock: `reload_peers_from_file` calls this BEFORE
        delegating the upsert to `register_peer`, which acquires the same
        lock, so the existing row cannot be read while the upsert lock is held.
        """
        with self._db.locked() as conn:
            row = conn.execute(
                "SELECT host, port FROM scp_targets WHERE ae_title = ? AND host = ?",
                (ae_title, host),
            ).fetchone()
        return (row[0], row[1]) if row else None

    # --- SCP peer lookup with subnet support --------------------

    def lookup_scp(self, ae_title, client_ip=None):
        """Look up SCP peer by AE Title, with optional IP subnet matching.

        Args:
            ae_title: Move Destination AE Title.
            client_ip: IP address of the requesting SCU (for subnet matching).
                If None, returns first exact-match (non-CIDR) entry.

        Returns:
            (host, port) tuple or None.

        Subnet matching (CIDR):
            peers.conf supports: WEASIS_AE  192.168.1.0/24  11113
            When client_ip falls within the subnet, returns the CIDR host
            (e.g. "192.168.1.0/24") and port. Caller uses the PORT for
            association; the HOST is informational (routed via client_ip).
        """
        with self._db.locked() as conn:
            rows = conn.execute(
                "SELECT host, port FROM scp_targets WHERE ae_title = ?",
                (ae_title,),
            ).fetchall()

        if not rows:
            return None

        if client_ip is None:
            # No IP  -  return first exact (non-CIDR) match, else first entry
            for host, port in rows:
                if "/" not in host:
                    return (host, port)
            return (rows[0][0], rows[0][1])

        # IP provided  -  match against subnets
        try:
            client = ipaddress.ip_address(client_ip)
        except ValueError:
            # Invalid IP string  -  fall back to exact match
            for host, port in rows:
                if "/" not in host:
                    return (host, port)
            return None

        # Priority 1: exact address match (non-CIDR). Both sides are
        # normalised so `VIEWER localhost 11112` matches a request from
        # 127.0.0.1, and `::1` matches `[::1]`; a raw string compare made the
        # operator see "Unknown Move Destination" (A801) instead of a match.
        # CIDR entries are untouched here and only treated as networks below,
        # so normalisation cannot promote a subnet to an exact hit.
        want = normalize_host(client_ip)
        for host, port in rows:
            if "/" not in host and normalize_host(host) == want:
                return (host, port)

        # Priority 2: CIDR subnet match
        for host, port in rows:
            if "/" in host:
                try:
                    network = ipaddress.ip_network(host, strict=False)
                    if client in network:
                        return (host, port)
                except ValueError:
                    continue

        return None

    def reload_peers_from_file(self, peers_file):
        """Reload peers from peers.conf into scp_targets table.

        Respects lazyload_peers_interval. Composite key (ae_title, host)
         -  multiple entries per AE (CIDR + exact) are preserved.

        Per-entry upsert delegates to `register_peer`, the single INSERT path:
        the reload used to run its own INSERT OR REPLACE here, so the two
        write paths drifted (register_peer's "one exact entry per AE"
        semantics were not applied by the file path). The file-sync half
        (removing peers the file no longer names) stays here.
        """
        if self.lazyload_peers_interval > 0:
            elapsed = time.time() - self._last_peers_reload
            if elapsed < self.lazyload_peers_interval:
                return 0

        self._last_peers_reload = time.time()
        parsed = list(parse_peers_conf(peers_file))
        if not parsed:
            # An EMPTY parse result must not delete anything: a file mid-save,
            # a truncated write or a crash leaves a config that parses to zero
            # peers, and treating that as "every peer was removed" silently
            # unregistered the whole peer table.
            logging.warning(
                "[PEER] %s parsed to no peers - keeping the existing table "
                "(a truncated or empty file must not wipe routing)",
                peers_file,
            )
            return 0

        seen = set()
        new_count = 0
        for ae_title, host, port in parsed:
            seen.add((ae_title, host))
            existing = self._lookup_target(ae_title, host)
            if existing == (host, port):
                # Unchanged entry: leave the row ALONE. `register_peer` writes
                # `consecutive_failures = 0`, so re-registering an identical
                # peer wiped its failure streak - a peer that had failed twice
                # (one short of the eviction threshold) started again from
                # zero at every reload, so the configured threshold was never
                # reached and a dead destination kept receiving jobs.
                continue
            new_count += 1
            self.register_peer(ae_title, host, port)

        # A peer removed from peers.conf is gone from the operator's view,
        # so routing to the stale row was a destination the config no
        # longer names. Deleting by (ae_title, host) keeps a peer that is
        # still listed under a different port.
        with self._db.locked() as conn:
            stale = [
                (ae, host)
                for ae, host in conn.execute("SELECT ae_title, host FROM scp_targets")
                if (ae, host) not in seen
            ]
            for ae, host in stale:
                conn.execute(
                    "DELETE FROM scp_targets WHERE ae_title = ? AND host = ?",
                    (ae, host),
                )
            if stale:
                logging.info(
                    "[PEER] Removed %d peer(s) no longer in %s",
                    len(stale),
                    peers_file,
                )
            conn.commit()
        if new_count:
            logging.info(
                "[PEER] Reloaded %d new/updated peer(s) from %s", new_count, peers_file
            )
        return new_count

    # --- scp failure tracking ---

    def record_scp_failure(self, ae_title, host=None):
        """Record a failure to reach SCP.

        Auto-remove after 3 consecutive failures (CM-006).
        If host is provided, only updates that specific entry (subnet-safe).
        """
        with self._db.locked() as conn:
            if host:
                conn.execute(
                    "UPDATE scp_targets SET consecutive_failures ="
                    " consecutive_failures + 1"
                    " WHERE ae_title = ? AND host = ?",
                    (ae_title, host),
                )
                row = conn.execute(
                    "SELECT consecutive_failures FROM scp_targets"
                    " WHERE ae_title = ? AND host = ?",
                    (ae_title, host),
                ).fetchone()
                if row and row[0] >= self.scp_remove_failures:
                    conn.execute(
                        "DELETE FROM scp_targets" " WHERE ae_title = ? AND host = ?",
                        (ae_title, host),
                    )
                    logging.warning(
                        "[SCP] Removed %s@%s after %d consecutive failures",
                        ae_title,
                        host,
                        self.scp_remove_failures,
                    )
            else:
                # Backward compat: update all entries for this AE
                conn.execute(
                    "UPDATE scp_targets SET consecutive_failures ="
                    " consecutive_failures + 1 WHERE ae_title = ?",
                    (ae_title,),
                )
                # Check and auto-remove entries with >= N failures
                conn.execute(
                    "DELETE FROM scp_targets"
                    " WHERE ae_title = ? AND consecutive_failures >= ?",
                    (ae_title, self.scp_remove_failures),
                )
            conn.commit()

    def record_scp_success(self, ae_title, host=None):
        """Reset failure counter on successful connection (CM-006).
        If host is provided, only resets that specific entry (subnet-safe).
        """
        with self._db.locked() as conn:
            if host:
                conn.execute(
                    "UPDATE scp_targets SET consecutive_failures = 0"
                    " WHERE ae_title = ? AND host = ?",
                    (ae_title, host),
                )
            else:
                conn.execute(
                    "UPDATE scp_targets SET consecutive_failures = 0"
                    " WHERE ae_title = ?",
                    (ae_title,),
                )
            conn.commit()

    def close(self):
        """no-op  -  SharedDb owns the connection, closed in main()."""

    # --- C-MOVE-CANCEL support ---

    def set_job_cancel_callback(self, job_id, callback):
        """Store cancel callback for a job (BR-012)."""
        self._cancel_callbacks[job_id] = callback

    def is_job_cancelled(self, job_id):
        """Check if job was cancelled by SCU (BR-012)."""
        cb = self._cancel_callbacks.get(job_id)
        if cb:
            try:
                return cb()
            except Exception:
                return False
        return False

    def clear_job_callback(self, job_id):
        """Remove cancel callback after job completes (BR-012)."""
        self._cancel_callbacks.pop(job_id, None)

# ---------------------------------------------------------------------------
# Bridge: outbox
# ---------------------------------------------------------------------------

"""Outbox Queue  -  filesystem-backed reliable DICOM persistence + delivery.

nginx-way: directories = queue state. os.rename = state transition; enqueue
publishes with os.replace (retried - see replace_with_retry).
No SQLite. No WAL. No busy_timeout. No _write_lock.

Layout:
    outbox/
      pending/       <- items waiting for first attempt or retry
        {uid}.dcm    <- DICOM blob (atomic write: .tmp -> os.replace)
        {uid}.meta   <- {"created_at": ..., "retry_count": 0, "next_retry_at": ..., "last_error": "..."}
        {uid}.mods   <- audit trail sidecar (FR-001), optional
      in_progress/   <- atomic claim: os.rename from pending/
      done/          <- only when cleanup=False (retain for audit)
      undelivered/   <- max retries exhausted (manual intervention)

Guarantees:
  - Atomic claim: os.rename(pending/x.*, in_progress/x.*)  -  only ONE worker succeeds
  - Restart-safe, NOT power-loss-safe: recover_stuck() moves in_progress/*
    back to pending/ on startup, so a crash or restart loses nothing that
    reached the filesystem. Writes are flushed to the OS page cache, not
    fsynced: an unclean power loss can lose an item already answered 0x0000.
    That window is closed by the HOST (UPS / battery-backed write cache), not
    by this process - fsync per instance would cost a disk round-trip per
    C-STORE and still not survive a failing disk.
  - Idempotent: enqueue checks if {uid}.dcm already exists in any dir -> skip
  - No duplicate delivery: exactly one in_progress/ at a time

Thread safety:
  - enqueue(): concurrent-safe via atomic os.replace (no shared state)
  - dequeue(): os.rename is atomic on same filesystem  -  collision -> skip, try next
  - Single worker (KISS)  -  no multi-worker contention in practice
"""

import json
import logging
import os
import shutil
import threading
import time

from pydicom import dcmread, dcmwrite
from pydicom.dataset import FileMetaDataset
from pydicom.uid import ExplicitVRLittleEndian

# How often the worker checks for stuck items (crashed during delivery).
STUCK_ITEM_CHECK_INTERVAL = 60.0  # seconds

# Items stuck in in_progress/ longer than this -> recovered.
STUCK_ITEM_TIMEOUT = 300.0  # 5 minutes

# A pending/ blob without its .meta is adopted as an orphan (crash between the
# blob write and the ready-marker) only after this long. enqueue writes .dcm
# first and .meta LAST, and the sweep runs on a 60 s timer while enqueue() is
# in flight, so anything younger than one sweep interval may still be being
# written. 60 s covers a large instance on slow storage and keeps the timer
# and the grace period aligned.
ENQUEUE_PUBLISH_GRACE_SEC = 60.0

def _ensure_file_meta(dataset):
    """Ensure dataset has a valid FileMetaDataset with TransferSyntaxUID.

    ALWAYS moves stray (0002,eeee) group elements out of the DIMSE dataset
    body into file_meta - pydicom rejects a write that leaves (0002,eeee)
    inline ("must be in a FileMetaDataset instance", Weasis C-STORE 0xA700).
    A tag already present in file_meta is NOT overwritten, so the negotiated
    TransferSyntaxUID from event.file_meta (C-STORE path sets ds.file_meta)
    always wins. Preserves upstream TS when present (cltranscode inserts
    (0002,0010) into DIMSE datasets). Falls back to ExplicitVRLittleEndian.
    """
    if (
        hasattr(dataset, "file_meta")
        and isinstance(dataset.file_meta, FileMetaDataset)
        and dataset.file_meta
    ):
        file_meta = dataset.file_meta
    else:
        file_meta = FileMetaDataset()
        dataset.file_meta = file_meta

    group_0002_tags = [tag for tag in dataset._dict if (tag >> 16) == 0x0002]
    for tag in group_0002_tags:
        elem = dataset[tag]
        if tag not in file_meta:
            file_meta.add(elem)
        del dataset[tag]

    if hasattr(file_meta, "TransferSyntaxUID") and file_meta.TransferSyntaxUID:
        return
    # A dataset without TS info is suspicious -
    # say it loud instead of silently corrupting compressed pixel data.
    logging.warning(
        "[OUTBOX] SOP %s has no TransferSyntaxUID - defaulting to "
        "ExplicitVRLittleEndian (compressed instances MUST pass the "
        "negotiated TS via event.file_meta)",
        str(getattr(dataset, "SOPInstanceUID", "?")),
    )
    file_meta.TransferSyntaxUID = ExplicitVRLittleEndian

class OutboxQueue:
    """Filesystem-backed outbox  -  directories + atomic rename = queue."""

    def __init__(
        self,
        outbox_dir,
        max_queue=20000,
        max_retries=10,
        cleanup=True,
        retry_interval=0,
        pending_gauge=None,
        undelivered_total=None,
        max_queue_bytes=0,
    ):
        self._dir = outbox_dir
        self.max_queue = max_queue
        # R7: byte budget for the pending/ blobs, 0 = no byte limit. The slot
        # count alone let a dead server plus store_forward pile up 20000 items
        # of 0.5-50 MB (up to 10 GB) against a configured 500 MB: the memory
        # budget was a documented knob the enqueue path never consulted.
        self.max_queue_bytes = max_queue_bytes
        self.MAX_RETRIES = max_retries
        self.cleanup = cleanup
        self.retry_interval = retry_interval

        # 0409 forwarder: this OutboxQueue backs BOTH the primary STOW drain
        # and (as a second instance) the best-effort forward channel. The
        # pending gauge tells the metric layer WHICH queue is reporting, so the
        # two never clobber each other. Default None = primary (outbox_pending).
        self._pending_gauge = (
            pending_gauge if pending_gauge is not None else outbox_pending
        )
        self._undelivered_total = undelivered_total

        # Subdirectories
        self._pending = os.path.join(self._dir, "pending")
        self._in_progress = os.path.join(self._dir, "in_progress")
        self._done = os.path.join(self._dir, "done")
        self._undelivered = os.path.join(self._dir, "undelivered")

        for d in [self._pending, self._in_progress, self._done, self._undelivered]:
            os.makedirs(d, exist_ok=True)

        # In-memory pending counter (avoids os.listdir on hot C-STORE path).
        self._pending_count = 0
        self._pending_lock = threading.Lock()
        # One guard per SOP Instance UID: two reactor threads receiving the
        # same instance publish to the same `<uid>.dcm`. Unique temp names stop
        # the writers from sharing a file; this serialises them so they do not
        # all contend for the destination rename at once (the rename itself is
        # retried inside `replace_with_retry`). Striped rather than one lock
        # per UID: a per-UID dict grows for every instance the bridge ever
        # receives and is never pruned.
        self._publish_guards = LockStripes()
        # `dequeue` sorts the pending/ .meta listing by mtime; the sorted list
        # is reused until something claims the queue empty or publishes a new
        # item (see dequeue's comment). None = must re-read the directory.
        self._pending_meta_cache = None
        # Admission reservations (hard byte budget): bytes and file names that
        # a publisher has been ALLOWED to write but has not finished publishing
        # yet. Without them the check is check-then-act across producers - two
        # enqueues of two large instances each see the same headroom and both
        # are admitted.
        self._reserved_bytes = 0
        self._reserved_names = set()
        # Bytes reserved per file name. Kept so a failed publish returns the
        # EXACT amount it reserved; recomputing it from the dataset later would
        # charge a different number, and the difference accumulates.
        self._reserved_amounts = {}
        self._pending_bytes_cache = None
        # EXACT byte ledger for pending/ (see `_pending_bytes_total`). Kept in
        # step with every transition that publishes, claims, moves or deletes a
        # blob, so admission never has to walk the directory: the walk cost one
        # `getsize` per pending blob on EVERY admitted C-STORE, twice, while
        # holding the lock - quadratic filesystem work on a large backlog.
        # `None` means "not yet measured"; the first admission or startup
        # reconciles it with a walk.
        self._pending_bytes = None
        # Sync from what's already on disk (survives restart).
        self._sync_pending_count()

    def _publish_guard_for(self, sop_uid):
        """The guard serialising publishers of `sop_uid`."""
        return self._publish_guards.for_key(sop_uid)

    @staticmethod
    def _filename_for(path):
        """The bare file name a reservation is keyed by."""
        return os.path.basename(path)

    @staticmethod
    def _incoming_bytes(dataset):
        """Upper-bound size estimate for admission, from the dataset itself.

        Measured from the sum of the element lengths rather than a serialised
        copy: pydicom 3.0.1's `Dataset` has NO `to_bytes()`, so the previous
        implementation raised and returned 0 for EVERY input - the admission
        check then reserved nothing and only the post-write check applied, which
        is exactly the check-then-act the budget exists to prevent.

        The estimate only has to be non-negative and roughly right; the hard
        limit still runs against the bytes that actually land.
        """
        try:
            total = 0
            for elem in dataset:
                # `elem.length` is 0 until the element has been encoded, so
                # every value in a freshly built dataset would count as
                # nothing. Measure the VALUE, which is what the write does.
                try:
                    size = len(elem.value)
                except TypeError:
                    size = 0
                total += size
            # Per-element headers: tag, VR and length. 8 bytes is the Explicit
            # VR short form (PS3.5 7.1.2), the smallest a value header can be.
            return total + 8 * max(1, len(dataset))
        except Exception:
            return 0

    def _release_reservation(self, dcm_path, reserved):
        """Give back an admission reservation that never became an item.

        Releases BOTH halves: the file name and the byte charge it was
        admitted with. Releasing only the name left the bytes counted, so
        repeated failures of a large instance exhausted the budget even after
        every failed blob had been removed.
        """
        if not reserved:
            return
        name = self._filename_for(dcm_path)
        with self._pending_lock:
            if name in self._reserved_names:
                self._reserved_names.discard(name)
                # The charge is recorded per name so the exact amount comes
                # back, never an estimate recomputed from a mutated dataset.
                self._reserved_bytes = max(
                    0, self._reserved_bytes - self._reserved_amounts.pop(name, 0)
                )

    def _pending_bytes_total(self):
        """Pending bytes including in-flight reservations.

        Callers hold `_pending_lock`, so this must not re-enter it. The value
        comes from the ledger, never from a directory walk: the walk used to
        run twice per admitted C-STORE (once here, once in the log line) and
        cost one `getsize` per pending blob, which is quadratic filesystem work
        when the backlog is large - exactly when admission matters.
        """
        if self._pending_bytes is None:
            # First use after construction, or after recovery invalidated it.
            # This is the ONLY walk on the admission path, and it happens once.
            self._pending_bytes = self._pending_bytes_walk()
        return self._pending_bytes + self._reserved_bytes

    def _ledger_add(self, delta):
        """Add `delta` to the pending-byte ledger. Callers hold the lock.

        A delta against an unmeasured ledger leaves it unmeasured, so the next
        admission measures reality instead of trusting a partial sum.
        """
        if self._pending_bytes is None:
            return
        self._pending_bytes = max(0, self._pending_bytes + delta)
        self._pending_bytes_cache = None

    def _set_pending_gauge(self):
        """Push the in-memory pending count to this queue's Prometheus gauge.

        0409: routed through self._pending_gauge so the primary STOW queue and
        the forward queue each report to their own metric (isolation).
        """
        try:
            self._pending_gauge.set(self._pending_count)
        except Exception:
            pass

    # -- path helpers --------------------------------------------------

    def _safe_uid(self, sop_uid):
        """File-name form of a SOP Instance UID, injective over its input.

        A UID is digits and dots, so nothing needs escaping in the normal case.
        The three bytes that cannot appear in a path (`\\x00`, `/`, `\\`) are
        percent-escaped rather than replaced with `_`: collapsing them all to
        one character made two different UIDs name one file, and the second
        instance then published over the first. `%` itself is escaped first so
        the mapping cannot be spoofed into producing an escape sequence.
        """
        return (
            sop_uid.replace("%", "%25")
            .replace("\x00", "%00")
            .replace("/", "%2F")
            .replace("\\", "%5C")
        )

    @staticmethod
    def _unsafe_uid(name):
        """Inverse of `_safe_uid`, applied ONLY to a UID read back from a
        filename (never to a UID already held in memory).

        `dequeue` and `recover_stuck` derive the UID from `name[:-4]` /
        `name[:-5]`, which is the ESCAPED form; passing it back through
        `_safe_uid` escaped it a second time (`%2F` -> `%252F`) and the item
        was skipped forever. Unescape in the REVERSE order of `_safe_uid`,
        so `%25` is decoded LAST (a literal `%` in the UID must not turn the
        two characters `%25` into a `%` before the other escapes run).
        """
        return (
            name.replace("%5C", "\\")
            .replace("%2F", "/")
            .replace("%00", "\x00")
            .replace("%25", "%")
        )

    def _dcm_path(self, dir_, sop_uid):
        return os.path.join(dir_, f"{self._safe_uid(sop_uid)}.dcm")

    def _meta_path(self, dir_, sop_uid):
        return os.path.join(dir_, f"{self._safe_uid(sop_uid)}.meta")

    def _mods_path(self, dir_, sop_uid):
        return os.path.join(dir_, f"{self._safe_uid(sop_uid)}.mods")

    def _audit_path(self, dir_, sop_uid):
        """Marker saying this item's blob REQUIRES its `.mods` sidecar.

        Written before the blob and before `.meta`, and only ever for a
        modified instance. Recovery uses it to prove that the audit trail it is
        about to publish alongside a blob is really there: without the marker,
        a crash between the `.dcm` rename and the `.mods` write was
        indistinguishable from an instance that simply had no modifications,
        so the sweep adopted it and `dequeue()` delivered it as raw bytes -
        the destination then stored the NEW patient fields with no Modified
        Attributes Sequence, i.e. a different record from the one this bridge
        documents.
        """
        return os.path.join(dir_, f"{self._safe_uid(sop_uid)}.audit")

    def _is_published(self, dir_, sop_uid):
        """True when `dir_` holds a COMPLETE publication of this SOP.

        "Complete" means the `.meta` ready-marker is present, not merely that
        a `.dcm` is. The `.meta` is written LAST on every publish path, so its
        presence is the only durable proof that the blob and its audit sidecar
        were both finished. A bare `.dcm` is an interrupted publication whose
        bytes may be truncated and whose `.mods` may never be written; treating
        it as "the instance is in the queue" is what let a re-C-STORE be
        acknowledged as a duplicate while the queue held nothing deliverable,
        and what let a half-written blob be claimed as soon as the sweep gave
        it a `.meta` of its own.
        """
        return os.path.isfile(self._meta_path(dir_, sop_uid))

    def _audit_required(self, dir_, sop_uid):
        """True when the marker says this blob needs its `.mods` sidecar."""
        return os.path.isfile(self._audit_path(dir_, sop_uid))

    def _is_undelivered(self, sop_uid):
        """True when the SOP is already parked in undelivered/.

        `move_to_undelivered` is not idempotent from the caller's point of
        view: it moves whatever it finds and counts it. A failure path that
        reaches it after `mark_failed` has already parked the same item would
        move nothing but still bump `undelivered_total`, so callers check here
        first.
        """
        return os.path.isfile(self._dcm_path(self._undelivered, sop_uid))

    # -- atomic file write ---------------------------------------------

    @staticmethod
    def _tmp_path(path):
        """A temporary path that only THIS write operation can own.

        The whole queue is keyed by SOP Instance UID, so two reactor threads
        receiving the same instance write the SAME final path. A shared
        `<path>.tmp` made them interleave into one file and both `os.replace`
        it; the dedup `isfile` check above is check-then-act and cannot
        serialise them. PID plus thread id is unique among the writers that
        can race here without leaving a lock or a file handle behind.
        """
        return f"{path}.{os.getpid()}.{threading.get_ident()}.tmp"

    @staticmethod
    def _atomic_write(path, data, binary=False):
        """Write data atomically: tmp -> flush -> os.replace."""
        tmp = OutboxQueue._tmp_path(path)
        mode = "wb" if binary else "w"
        encoding = None if binary else "utf-8"
        try:
            with open(tmp, mode, encoding=encoding) as f:
                f.write(data)
                f.flush()
            replace_with_retry(tmp, path)
        except Exception:
            # A failed write must not leave its temp file behind: the next
            # attempt would pile another one next to it.
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise

    # -- modifications sidecar -----------------------------------------

    def _write_mods_sidecar(self, sop_uid, modifications):
        """Write the FR-001 audit sidecar. Returns True when it is on disk.

        Publication is a DECISION, not a best-effort side effect: `.meta` is
        what makes an item ready, and `dequeue()` uses the presence of `.mods`
        to decide whether to apply the audit trail at all. A missing `.mods`
        therefore turned a modified instance into a raw-bytes passthrough
        carrying the NEW patient fields with no Modified Attributes Sequence -
        the destination stored a different record from the one the bridge
        documents. The caller must roll back rather than publish it.
        """
        try:
            mods_json = []
            for tag, old_val, new_val in modifications:
                mods_json.append(
                    {
                        "tag": [tag[0], tag[1]],
                        "old": old_val,
                        "new": new_val,
                    }
                )
            self._atomic_write(
                self._mods_path(self._pending, sop_uid),
                json.dumps(mods_json),
            )
            return True
        except Exception as e:
            logging.error("[OUTBOX] Failed to write .mods for %s: %s", sop_uid, e)
            return False

    @staticmethod
    def read_mods_sidecar(blob_path):
        """Read modifications sidecar for a blob file. Returns None if absent."""
        if not blob_path.endswith(".dcm"):
            return None
        mods_path = blob_path[:-4] + ".mods"
        if not os.path.isfile(mods_path):
            return None
        try:
            with open(mods_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None

    @staticmethod
    def delete_mods_sidecar(blob_path):
        """Delete a modifications sidecar (best-effort)."""
        if not blob_path.endswith(".dcm"):
            return
        mods_path = blob_path[:-4] + ".mods"
        try:
            os.unlink(mods_path)
        except OSError:
            pass

    # -- core operations -----------------------------------------------

    def enqueue(self, dataset, modifications=None):
        """Persist DICOM instance to outbox. Thread-safe, atomic writes.

        Order: .dcm -> .mods -> .meta (LAST). Orphan .dcm without .meta =
        safe to ignore on startup (recover_stuck skips them).

        Returns True (inserted), False (error), or "duplicate" (already in queue).
        """
        t0 = time.time()
        sop_uid = str(getattr(dataset, "SOPInstanceUID", ""))
        if not sop_uid:
            logging.error("[OUTBOX] Dataset has no SOPInstanceUID - cannot enqueue")
            return False

        dcm_path = self._dcm_path(self._pending, sop_uid)

        # Dedup and publish are one critical section per SOP Instance UID:
        # the scan is check-then-act, so it is only a decision when nothing
        # else can create the file between the scan and the write.
        #
        # The test is COMPLETED publication (`_is_published` = the `.meta`
        # ready-marker), not the presence of a `.dcm`. A bare blob is an
        # interrupted publish: its bytes may be truncated and its audit `.mods`
        # may never have been written, so answering "duplicate, 0x0000" told
        # the modality the instance was safely queued while the queue held
        # nothing it could deliver. The stale parts are cleared here so this
        # publish can proceed.
        guard = self._publish_guard_for(sop_uid)
        reserved = False
        with guard:
            for d in [self._pending, self._in_progress, self._done]:
                if self._is_published(d, sop_uid):
                    logging.info(
                        "[OUTBOX] SOP %s already in queue - duplicate, 0x0000",
                        sop_uid,
                    )
                    return "duplicate"

            # No committed publication anywhere: whatever is left under this
            # UID is debris from a failed or interrupted attempt and MUST NOT
            # survive into the new one. A stale `.audit` marker, in
            # particular, would mark THIS publish as audit-required and make
            # its own `.mods` mandatory even for an unmodified re-send.
            for d in [self._pending, self._in_progress]:
                for stale in (
                    self._dcm_path(d, sop_uid),
                    self._mods_path(d, sop_uid),
                    self._audit_path(d, sop_uid),
                    self._meta_path(d, sop_uid),
                ):
                    try:
                        os.unlink(stale)
                    except OSError:
                        pass

            # Step 0: admission. The queue slot and the byte budget are both
            # reserved HERE, before a byte is written, and released on every
            # failure path below. Without the byte check the enqueue path
            # published whatever the instance size limit allowed: with 400 MiB
            # pending against a 500 MiB budget, a 150 MiB instance brought the
            # queue to 550 MiB and the C-STORE still answered 0x0000. The
            # reservation makes check-then-publish atomic across producers,
            # which is what a limit has to be.
            incoming = self._incoming_bytes(dataset)
            with self._pending_lock:
                # In-flight slots count against the queue cap. Checking only
                # `_pending_count` let two producers both see the last free
                # slot before either incremented it, so a `max_queue` of one
                # accepted two instances.
                if self.max_queue and (
                    self._pending_count + len(self._reserved_names) >= self.max_queue
                ):
                    logging.warning(
                        "[OUTBOX] Queue full (%d) - refusing %s",
                        self.max_queue,
                        sop_uid,
                    )
                    return False
                if self.max_queue_bytes and (
                    self._pending_bytes_total() + incoming > self.max_queue_bytes
                ):
                    logging.warning(
                        "[OUTBOX] Byte budget %d exceeded (pending %d + %d) - "
                        "refusing %s",
                        self.max_queue_bytes,
                        self._pending_bytes_total(),
                        incoming,
                        sop_uid,
                    )
                    return False
                self._reserved_bytes += incoming
                self._reserved_names.add(self._filename_for(dcm_path))
                self._reserved_amounts[self._filename_for(dcm_path)] = incoming
                reserved = True

            # Step 1: Write DICOM blob (atomic).
            _ensure_file_meta(dataset)
            tmp = self._tmp_path(dcm_path)
            try:
                dcmwrite(tmp, dataset, enforce_file_format=True)
                replace_with_retry(tmp, dcm_path)
            except Exception as e:
                logging.error("[OUTBOX] Failed to write blob for %s: %s", sop_uid, e)
                try:
                    os.unlink(tmp)
                except OSError:
                    pass
                self._release_reservation(dcm_path, reserved)
                return False

            # The reservation used an ESTIMATE; this is the hard limit on the
            # bytes that actually landed. A dataset that could not be measured
            # up front therefore still cannot overrun the budget.
            if self.max_queue_bytes:
                try:
                    real_size = os.path.getsize(dcm_path)
                except OSError:
                    real_size = 0
                with self._pending_lock:
                    # The reservation is this item's charge; replacing it with
                    # the real size keeps every other item and every other
                    # in-flight reservation exactly as it was.
                    over = (
                        self._pending_bytes_total() - max(0, incoming) + real_size
                        > self.max_queue_bytes
                    )
                if over:
                    logging.warning(
                        "[OUTBOX] Byte budget %d exceeded by the real blob "
                        "(%d) - refusing %s",
                        self.max_queue_bytes,
                        real_size,
                        sop_uid,
                    )
                    try:
                        os.unlink(dcm_path)
                    except OSError:
                        pass
                    self._release_reservation(dcm_path, reserved)
                    return False

            # Step 2: audit sidecar - REQUIRED when the instance was modified
            # (FR-001), written BEFORE .meta. Optional otherwise.
            #
            # The MARKER goes down before the sidecar, so a crash between the
            # two leaves evidence that this blob needs audit data. Recovery
            # reads it and refuses to adopt the blob; without it the blob is
            # indistinguishable from an unmodified one.
            if modifications:
                try:
                    self._atomic_write(
                        self._audit_path(self._pending, sop_uid),
                        json.dumps({"required": True}),
                    )
                except Exception as e:
                    logging.error(
                        "[OUTBOX] Cannot record the audit requirement for %s: %s "
                        "- refusing the instance rather than publishing it "
                        "without provable audit data",
                        sop_uid,
                        e,
                    )
                    for orphan in (
                        dcm_path,
                        self._mods_path(self._pending, sop_uid),
                        self._audit_path(self._pending, sop_uid),
                    ):
                        try:
                            os.unlink(orphan)
                        except OSError:
                            pass
                    self._release_reservation(dcm_path, reserved)
                    return False
            if modifications and not self._write_mods_sidecar(sop_uid, modifications):
                # Publishing now would produce an instance whose audit trail
                # does not exist: `dequeue()` sees no `.mods`, delivers the
                # blob as raw bytes, and the destination receives the new
                # patient fields with no record of the change.
                logging.error(
                    "[OUTBOX] .mods failed for %s - rolling back the unready "
                    "blob so the sender retries",
                    sop_uid,
                )
                for orphan in (
                    dcm_path,
                    self._mods_path(self._pending, sop_uid),
                    self._audit_path(self._pending, sop_uid),
                ):
                    try:
                        os.unlink(orphan)
                    except OSError:
                        pass
                self._release_reservation(dcm_path, reserved)
                return False

            # Step 3: Write metadata (LAST  -  signals "this item is ready").
            now = time.time()
            meta = {
                "created_at": now,
                "retry_count": 0,
                "next_retry_at": now,
                "last_error": None,
            }
            meta_path = self._meta_path(self._pending, sop_uid)
            try:
                self._atomic_write(meta_path, json.dumps(meta))
                # A published item must be visible to the very next dequeue.
                self._pending_meta_cache = None
            except Exception as e:
                # `.meta` is what makes an item VISIBLE to the queue (the
                # pending walk trusts "no .meta = interrupted earlier, clean
                # up"). Leaving the blob behind on a failed write produced an
                # orphan that the next sweep would delete out from under a
                # caller that had already been told the enqueue failed. Undo
                # the blob so enqueue either succeeds whole or leaves nothing.
                logging.error(
                    "[OUTBOX] Failed to write .meta for %s: %s - removing the "
                    "orphan blob",
                    sop_uid,
                    e,
                )
                for orphan in (
                    dcm_path,
                    self._mods_path(self._pending, sop_uid),
                    self._audit_path(self._pending, sop_uid),
                ):
                    try:
                        os.unlink(orphan)
                    except OSError:
                        pass
                self._release_reservation(dcm_path, reserved)
                return False

        with self._pending_lock:
            self._pending_count += 1
            # The item is on disk and counted: the reservation becomes the
            # real pending byte, so the two never double-count it. The charge
            # that lands in the ledger is the REAL blob size, not the estimate:
            # the estimate exists only to make the pre-write check possible.
            self._reserved_bytes = max(0, self._reserved_bytes - incoming)
            self._reserved_names.discard(self._filename_for(dcm_path))
            self._reserved_amounts.pop(self._filename_for(dcm_path), None)
            try:
                published = os.path.getsize(dcm_path)
            except OSError:
                published = max(0, incoming)
            self._ledger_add(published)
        self._set_pending_gauge()

        logging.debug("[OUTBOX] Enqueued SOP %s", sop_uid)

        elapsed = time.time() - t0
        try:
            outbox_enqueue_latency_seconds.observe(elapsed)
        except Exception:
            pass

        return True

    # -- forward channel (0409) ----------------------------------------

    @staticmethod
    def _inc_forward_dropped():
        """Increment the forward DROP counter (0409 best-effort mirror)."""
        try:

            forward_dropped_total.inc()
        except Exception:
            pass

    def _link_or_copy(self, src, dst):
        """Place src bytes at dst with ZERO extra disk usage when possible.

        0409 forwarder: the blob is already atomically written in the PRIMARY
        outbox. Rather than duplicating its bytes, try a hard link
        first (same filesystem -> no extra bytes). If that fails (cross-device
        EXDEV, archived fs, no hardlink support) fall back to a byte copy via
        tmp + os.replace (still atomic, still crash-safe).

        Returns True on success, False on failure.
        """
        try:
            os.link(src, dst)
            return True
        except OSError:
            pass
        try:
            tmp = self._tmp_path(dst)
            shutil.copyfile(src, tmp)
            replace_with_retry(tmp, dst)
            return True
        except OSError:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            return False

    def enqueue_from_blob(self, blob_path, sop_uid, modifications=None):
        """Mirror an ALREADY-persisted primary blob into the forward queue.

        The forward channel is best-effort: it must NEVER change the C-STORE
        status the modality already received from the primary enqueue. Called
        from handle_c_store AFTER the primary enqueue returns True.

        Contract (identical ready-marker semantics to enqueue(), outbox.py):
          forward/<dir>/{uid}.dcm  <- hardlinked/copied primary pending blob
          forward/<dir>/{uid}.mods <- audit sidecar (optional)
          forward/<dir>/{uid}.meta <- written LAST = "this item is ready"

        Returns:
          True       -> blob placed in forward/pending
          "duplicate"-> already mirrored (idempotent re-C-STORE)
          "full"     -> forward queue at max_queue (dropped + counter)
          False      -> placement failed (dropped + counter)

        The caller ignores return for the modality status, but logs/drops.
        """
        if not sop_uid or not blob_path or not os.path.isfile(blob_path):
            self._inc_forward_dropped()
            return False

        # Dedup: already mirrored in forward/pending or in_progress -> nothing
        # to do (re-C-STORE of the same SOP, or a leftover from a crash).
        for d in [self._pending, self._in_progress]:
            if os.path.isfile(self._dcm_path(d, sop_uid)):
                logging.debug(
                    "[OUTBOX] SOP %s already in forward queue - duplicate",
                    sop_uid,
                )
                return "duplicate"

        # Queue-full: drop-newest (best-effort, never backpressure primary).
        # Checked and RESERVED under the count lock: reading the count here and
        # incrementing it further down let two producers both see one free slot
        # and both publish, so the forward queue exceeded its cap.
        with self._pending_lock:
            if self.max_queue and self._pending_count >= self.max_queue:
                logging.warning(
                    "[OUTBOX] Forward queue full (%d) - dropping %s "
                    "(primary 0x0000 unchanged)",
                    self.max_queue,
                    sop_uid,
                )
                self._inc_forward_dropped()
                return "full"
            self._pending_count += 1

        dcm_path = self._dcm_path(self._pending, sop_uid)

        def _unreserve():
            with self._pending_lock:
                self._pending_count = max(0, self._pending_count - 1)
            self._set_pending_gauge()

        # Step 1: hardlink/copy the primary blob into forward/pending.
        #
        # The primary worker can claim and remove this blob at any moment: the
        # primary enqueue that produced it returns before the worker runs, so
        # the `isfile` check above races the delivery. One retry covers the
        # window where the file is present but briefly unavailable; a second
        # failure means the item really is gone, which the primary channel has
        # already accounted for.
        if not self._link_or_copy(blob_path, dcm_path):
            if os.path.isfile(blob_path) and self._link_or_copy(blob_path, dcm_path):
                pass
            else:
                logging.error(
                    "[OUTBOX] Forward enqueue failed to place blob for %s "
                    "(primary 0x0000 unchanged)",
                    sop_uid,
                )
                self._inc_forward_dropped()
                _unreserve()
                return False

        # Step 2: audit sidecar (BEFORE .meta).
        #
        # REQUIRED when the instance carries modifications, exactly as in the
        # primary path: publishing without it makes `dequeue()` apply no audit
        # trail and forward the modified dataset as raw bytes, so the second
        # archive stores a different record from the one this bridge keeps.
        # The mirror is dropped rather than published incomplete; the PRIMARY
        # C-STORE result and its blob are untouched.
        if modifications and not self._write_mods_sidecar(sop_uid, modifications):
            logging.error(
                "[OUTBOX] Forward .mods failed for %s - dropping the mirror "
                "rather than forwarding it without its audit trail "
                "(primary 0x0000 unchanged)",
                sop_uid,
            )
            for orphan in (
                dcm_path,
                self._mods_path(self._pending, sop_uid),
                self._audit_path(self._pending, sop_uid),
            ):
                try:
                    os.unlink(orphan)
                except OSError:
                    pass
            self._inc_forward_dropped()
            _unreserve()
            return False

        # Step 3: metadata LAST  -  signals "this item is ready" to the worker.
        now = time.time()
        meta = {
            "created_at": now,
            "retry_count": 0,
            "next_retry_at": now,
            "last_error": None,
        }
        meta_path = self._meta_path(self._pending, sop_uid)
        try:
            self._atomic_write(meta_path, json.dumps(meta))
        except Exception as e:
            # A blob with no `.meta` is not an item: it makes a later mirror
            # attempt read as a duplicate (so the SOP is never forwarded) or
            # lets recovery adopt it as a new one. Roll the mirror back, as the
            # primary enqueue does. The PRIMARY blob and its acknowledgement
            # are untouched - this queue owns only the copy it just made.
            logging.error(
                "[OUTBOX] Forward .meta failed for %s: %s - removing the "
                "unready mirror",
                sop_uid,
                e,
            )
            for orphan in (
                dcm_path,
                self._mods_path(self._pending, sop_uid),
                self._audit_path(self._pending, sop_uid),
            ):
                try:
                    os.unlink(orphan)
                except OSError:
                    pass
            self._inc_forward_dropped()
            _unreserve()
            return False
        # A published item must be visible to the very next dequeue.
        self._pending_meta_cache = None
        self._set_pending_gauge()

        logging.debug("[OUTBOX] Forward-enqueued SOP %s", sop_uid)
        return True

    def _list_pending_names(self):
        """`os.listdir` of pending/, or [] when the directory is unreadable."""
        try:
            return os.listdir(self._pending)
        except OSError:
            return []

    def _scan_pending_metas(self, names):
        """`[(mtime, name)]` for every `.meta` in `names`, oldest first."""
        # Only the .meta NAMES are sorted here, so a busy queue costs one stat
        # per item instead of a full JSON re-read.
        metas = []
        for name in names:
            if not name.endswith(".meta"):
                continue
            meta_path = os.path.join(self._pending, name)
            try:
                metas.append((os.path.getmtime(meta_path), name))
            except OSError:
                continue
        metas.sort()
        return metas

    def dequeue(self):
        """Atomically claim the oldest ready SOP.

        Scans pending/*.meta for items with next_retry_at <= now.
        os.rename from pending/ to in_progress/  -  atomic claim.
        On collision -> skip, try next.

        Returns (sop_uid, ds, blob_path, raw_bytes) 4-tuple,
        or (None, None, None, None) if queue is empty.
        """
        now = time.time()
        sop_uid = None

        # OLDEST FIRST. `os.listdir` returns directory order, which is neither
        # creation order nor stable across filesystems, so the queue could
        # deliver a newer instance before an older one waiting on the same
        # study - and a backlog drained in arrival order is the whole point of
        # a queue. The sort key is the mtime of the .meta, which `enqueue`
        # writes LAST and nothing rewrites: it is the publish time, exactly the
        # ordering the queue means.
        #
        # The listing is CACHED and only re-read when nothing in it was
        # claimable. Dequeue runs once per delivered item, and re-listing a
        # backlog of `max_queue` (20000) entries with a stat per entry turned
        # a drain into O(n^2) filesystem calls - hours of stat traffic on
        # NTFS after a crash. The cache is dropped wholesale on every enqueue
        # (an item must become visible at once) and whenever the cached rows
        # yield nothing, so a newly ready retry is still found on the next
        # call.
        metas = self._pending_meta_cache
        from_cache = metas is not None
        if metas is None:
            metas = self._scan_pending_metas(self._list_pending_names())
            self._pending_meta_cache = metas

        # Find the first READY item in age order. Rows walked past are RETIRED
        # from the cache (see below): without that, every dequeue restarted at
        # the head of the same list and re-opened the metadata of every
        # already-claimed item, turning a drain of n into n^2/2 failed opens.
        #
        # `retired` counts rows that are GONE (claimed, unreadable, or holding
        # a dangling ready-marker), and only those may leave the cache. Rows
        # that are merely NOT YET DUE end the walk but stay: they are still
        # queue members, they become claimable on their own clock, and this
        # listing is the only record of when. Dropping them lost every pending
        # retry in the backlog to a single walk, so the queue drained and then
        # stayed empty for as long as the retry backoff.
        retired = 0
        for _mtime, name in metas:
            # `name` is the ESCAPED form on disk; unescape before any path
            # helper re-escapes it, or `1.2%2F3.meta` would be looked up as
            # `1.2%252F3.meta` and skipped on every pass.
            uid = self._unsafe_uid(name[:-5])  # strip .meta
            meta_path = self._meta_path(self._pending, uid)

            try:
                with open(meta_path, "r", encoding="utf-8") as f:
                    meta = json.load(f)
            except (json.JSONDecodeError, OSError):
                retired += 1
                continue

            next_retry = meta.get("next_retry_at", 0)
            retry_count = meta.get("retry_count", 0)
            if retry_count >= self.MAX_RETRIES:
                # Exhausted: this row will never be claimable again, so it must
                # not stop the scan for the healthy rows behind it. It is left
                # in place for `recover_stuck`, which parks it.
                retired += 1
                continue
            if next_retry > now:
                # Not due yet: stop here and keep this row and every row after
                # it in the cache. They are queue members on their own clock,
                # and this listing is the only record of when they come due.
                break

            # A `.meta` promises a COMPLETE publication: the blob finished
            # writing and, when the marker is present, its `.mods` sidecar was
            # written too. Claiming on the metadata alone delivered whatever
            # bytes happened to be on disk - a truncated blob from an
            # interrupted publish, or a modified instance whose audit trail
            # was never written. Both are settled as a delivery failure so the
            # retry path owns them, rather than being handed to the drain.
            dcm_ready = self._dcm_path(self._pending, uid)
            if not os.path.isfile(dcm_ready):
                retired += 1
                continue
            if self._audit_required(self._pending, uid) and not os.path.isfile(
                self._mods_path(self._pending, uid)
            ):
                logging.error(
                    "[OUTBOX] SOP %s is marked audit-required but its .mods "
                    "is missing - not delivering it without the audit trail",
                    uid,
                )
                retired += 1
                continue

            # Atomic claim: move ALL files for this UID to in_progress/.
            dcm = dcm_ready
            mods = self._mods_path(self._pending, uid)
            audit = self._audit_path(self._pending, uid)

            try:
                os.rename(dcm, self._dcm_path(self._in_progress, uid))
                if os.path.isfile(mods):
                    os.rename(mods, self._mods_path(self._in_progress, uid))
                # The marker travels with the item: recovery reads it there to
                # prove the audit trail it publishes is the one required.
                if os.path.isfile(audit):
                    os.rename(audit, self._audit_path(self._in_progress, uid))
                os.rename(meta_path, self._meta_path(self._in_progress, uid))
                # `rename` preserves the mtime the blob got when it was
                # ENQUEUED, but `recover_stuck` reads that mtime as "how long
                # has this been in progress". An item that waited in pending/
                # longer than STUCK_ITEM_TIMEOUT (a backlog after an incident,
                # parking, a 507 pause) therefore reads as stuck the instant it
                # is claimed, the sweep puts it back, and the same instance is
                # delivered twice while `_pending_count` drops by two.
                claimed = self._dcm_path(self._in_progress, uid)
                try:
                    os.utime(claimed, None)
                except OSError:
                    pass
                sop_uid = uid
                break
            except OSError:
                # Another worker claimed it (or file removed)  -  skip.
                retired += 1
                continue

        # Retire the rows this call walked past, so the next dequeue does not
        # re-open metadata for items it has already proven unclaimable. Only a
        # listing that came FROM the cache is retired: mutating a freshly
        # scanned list could drop the only ready row of a single-item queue.
        #
        # The slice stops BEFORE the first DEFERRED row. A deferred item is not
        # retired from the queue, only from this pass: everything before it is
        # provably gone (claimed, unreadable, dangling), everything from it
        # onward must be looked at again, because one of those rows is the
        # retry that is about to become due. Removing the tail here is what
        # `:839` was about - the old slice started at `retired + 1`, which is
        # one row PAST the item the walk actually stopped on, and every
        # not-yet-due retry behind it went with the cache.
        if from_cache and retired:
            self._pending_meta_cache = metas[retired:]

        if sop_uid is None:
            # Nothing was claimable. Keep the surviving tail: it is the only
            # record of which retries exist and when they come due. Discarding
            # it re-walked the whole backlog on every idle poll (one stat per
            # item, forever) AND, when the tail was dropped, forgot the retries
            # entirely. Only a listing with nothing left in it is dropped, so
            # the next call re-reads the directory.
            if not self._pending_meta_cache:
                self._pending_meta_cache = None
            return (None, None, None, None)

        # Read DICOM from claimed file.
        blob_path = self._dcm_path(self._in_progress, sop_uid)
        try:
            # Lazy parse (OPT-1): a full Dataset (incl. pixels) is needed ONLY
            # when the blob carries a .mods audit sidecar - the drain then
            # re-serializes it (stow re-write must keep PixelData). The
            # unmodified majority is delivered as raw_bytes passthrough; the
            # header-only parse (stop_before_pixels) still yields every field
            # the drain needs for study bucketing, stats and logging without
            # walking the bulky pixel element.
            modified = os.path.isfile(self._mods_path(self._in_progress, sop_uid))
            if modified:
                ds = dcmread(blob_path)
            else:
                ds = dcmread(blob_path, stop_before_pixels=True)
            with open(blob_path, "rb") as f:
                raw_bytes = f.read()
            return (sop_uid, ds, blob_path, raw_bytes)
        except Exception as e:
            logging.error("[OUTBOX] Failed to read blob %s: %s", blob_path, e)
            self.mark_failed(sop_uid, f"Blob read error: {e}")
            retries = self._get_retry_count(sop_uid)
            # mark_failed ALREADY parks the item once it hits MAX_RETRIES
            # (outbox.py mark_failed -> move_to_undelivered). Calling it again
            # here moved an item that was no longer in pending/ or
            # in_progress/ and, worse, could move a SECOND time on a
            # concurrent path, producing two undelivered entries and a double
            # `undelivered_total` bump for one failure. Only act when the
            # failed item is still present somewhere movable.
            if retries >= self.MAX_RETRIES and not self._is_undelivered(sop_uid):
                self.move_to_undelivered(sop_uid)
            return (None, None, None, None)

    # -- delivery status -----------------------------------------------

    def mark_delivered(self, sop_uid):
        """Mark SOP as successfully delivered.

        The terminal transition runs under the same per-UID publication guard
        `delivered()` reads under. Without it the reader could observe the
        blob already out of `in_progress/` and its `.meta` still there (or the
        reverse), so a concurrent Storage Commitment query judged a delivered
        instance undelivered, or an undelivered one finished.
        """
        with self._publish_guard_for(sop_uid):
            self._mark_delivered_locked(sop_uid)

    def _mark_delivered_locked(self, sop_uid):
        """Body of `mark_delivered`; the caller holds the publication guard."""
        # A previous delivery attempt may have exhausted its retries and left
        # undelivered/{uid}.dcm behind. If a LATER attempt of the SAME SOP
        # succeeds, that stale marker must go: delivered() checks undelivered/
        # FIRST, so the saved instance would otherwise keep reading as a
        # Storage Commitment failure forever. The marker and its companions go
        # together, or `delivered()` finds the `.meta` of the failed attempt.
        for stale in (
            self._dcm_path(self._undelivered, sop_uid),
            self._meta_path(self._undelivered, sop_uid),
            self._audit_path(self._undelivered, sop_uid),
            self._mods_path(self._undelivered, sop_uid),
        ):
            try:
                os.unlink(stale)
            except OSError:
                pass

        # Find which dir the SOP is in (normally in_progress/, but allow pending/ for test flexibility).
        dir_ = self._in_progress
        if not os.path.isfile(self._dcm_path(dir_, sop_uid)):
            dir_ = self._pending
        dcm = self._dcm_path(dir_, sop_uid)
        meta = self._meta_path(dir_, sop_uid)
        mods = self._mods_path(dir_, sop_uid)

        # Measure BEFORE the files move: after a cleanup unlink the size is
        # gone, and after a rename it belongs to done/ rather than pending/.
        try:
            released = os.path.getsize(dcm)
        except OSError:
            released = 0

        if self.cleanup:
            for p in [dcm, meta, mods]:
                try:
                    os.unlink(p)
                except OSError:
                    pass
        else:
            for p in [dcm, meta]:
                dst = p.replace(dir_, self._done)
                try:
                    os.rename(p, dst)
                except OSError:
                    pass
            if os.path.isfile(mods):
                try:
                    os.rename(mods, self._mods_path(self._done, sop_uid))
                except OSError:
                    pass
            # The audit marker travels with the item into done/. Leaving it in
            # the source directory let the NEXT publish of this UID read as
            # audit-required even though it carried no modifications.
            if os.path.isfile(self._audit_path(dir_, sop_uid)):
                try:
                    os.rename(
                        self._audit_path(dir_, sop_uid),
                        self._audit_path(self._done, sop_uid),
                    )
                except OSError:
                    pass

        with self._pending_lock:
            self._pending_count = max(0, self._pending_count - 1)
            # The blob left pending/ for good (deleted, or moved to done/),
            # so its bytes leave the admission ledger with it.
            self._ledger_add(-released)
        self._set_pending_gauge()
        logging.debug("[OUTBOX] Delivered SOP %s", sop_uid)

    def delivered(self, sop_uid):
        """True when this SOP is no longer waiting for delivery anywhere.

        The bridge's own delivery state is the durable fact and the ONLY
        readiness signal: the server ACKs a STOW-RS only after durable
        persist, so "not in this queue any more" means the origin has it.
        A C-STORE that was never enqueued (a modality re-request, a restart
        with cleanup on) also reads as delivered, which is correct: the
        bridge is not holding it, so nothing local stands between the SOP
        and the origin's verdict.

        Read-side only - the worker is the single writer of this state.
        Checks undelivered/ and the live directories under the SAME per-UID
        guard the worker transitions hold: two separate reads let a SOP parked
        BETWEEN them read as absent from both, so a failed instance reported
        itself delivered and Storage Commitment told the modality a SOP was
        saved that the archive had rejected.

        The guard also makes the answer a genuine transition point. `park_blob`
        moves only the `.dcm`, so "the blob is not in a live directory" is not
        enough: an item in the middle of a requeue has its blob in `done/` and
        its `.meta` still in `pending/`. Any part of a publication under the
        live directories - blob, ready-marker, audit marker or sidecar - means
        the queue still holds this SOP.
        """
        with self._publish_guard_for(sop_uid):
            for d in (self._undelivered, self._pending, self._in_progress):
                for p in (
                    self._dcm_path(d, sop_uid),
                    self._meta_path(d, sop_uid),
                    self._audit_path(d, sop_uid),
                    self._mods_path(d, sop_uid),
                ):
                    if os.path.isfile(p):
                        return False
            return True

    def mark_failed(self, sop_uid, error):
        """Mark delivery as failed. Retry with backoff.

        Works on items in pending/ or in_progress/. Updates .meta
        with retry_count and next_retry_at. If already in pending/,
        just updates .meta in place (no rename needed).
        Only calls move_to_undelivered when retry_count >= MAX_RETRIES.
        """
        # Find which dir the SOP is in.
        dir_ = self._in_progress
        if not os.path.isfile(self._dcm_path(dir_, sop_uid)):
            dir_ = self._pending
        meta_path = self._meta_path(dir_, sop_uid)

        retry_count = self._get_retry_count(sop_uid) + 1
        if self.retry_interval == 0:
            delay = min(2**retry_count, 120)
        else:
            delay = self.retry_interval
        next_retry = time.time() + delay

        meta = {
            "created_at": time.time(),
            "retry_count": retry_count,
            "next_retry_at": next_retry,
            "last_error": str(error)[:200],
        }

        # Atomic update of .meta.
        tmp = self._tmp_path(meta_path)
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(meta, f)
            f.flush()
        replace_with_retry(tmp, meta_path)

        # If in in_progress/, move back to pending/.
        if dir_ == self._in_progress:
            dcm = self._dcm_path(self._in_progress, sop_uid)
            mods = self._mods_path(self._in_progress, sop_uid)
            try:
                os.rename(dcm, self._dcm_path(self._pending, sop_uid))
                if os.path.isfile(mods):
                    os.rename(mods, self._mods_path(self._pending, sop_uid))
                os.rename(meta_path, self._meta_path(self._pending, sop_uid))
            except OSError as e:
                logging.error(
                    "[OUTBOX] Failed to move %s back to pending: %s", sop_uid, e
                )

        if retry_count >= self.MAX_RETRIES:
            logging.error(
                "[OUTBOX] SOP %s: max retries (%d) exceeded - needs manual intervention",
                sop_uid,
                self.MAX_RETRIES,
            )
            self.move_to_undelivered(sop_uid)
        else:
            logging.warning(
                "[OUTBOX] SOP %s: delivery failed (retry %d/%d): %s",
                sop_uid,
                retry_count,
                self.MAX_RETRIES,
                error,
            )

    def requeue(self, sop_uid, reason):
        """Move a claimed item back to pending/ WITHOUT bumping retry count.

        2908: used for 507 Insufficient Storage backpressure. The item is
        NOT a failed delivery - it stays pending (retry_count unchanged),
        only last_error is recorded for diagnostics.
        """
        dcm = self._dcm_path(self._in_progress, sop_uid)
        if not os.path.isfile(dcm):
            return
        mods = self._mods_path(self._in_progress, sop_uid)
        meta_path = self._meta_path(self._in_progress, sop_uid)
        try:
            os.rename(dcm, self._dcm_path(self._pending, sop_uid))
            if os.path.isfile(mods):
                os.rename(mods, self._mods_path(self._pending, sop_uid))
            os.rename(meta_path, self._meta_path(self._pending, sop_uid))
        except OSError as e:
            logging.error(
                "[OUTBOX] Failed to requeue %s back to pending: %s",
                sop_uid,
                e,
            )
            return

        # Update last_error only - retry_count stays (507 is not a failure).
        try:
            meta_target = self._meta_path(self._pending, sop_uid)
            with open(meta_target, "r", encoding="utf-8") as f:
                meta = json.load(f)
            meta["last_error"] = str(reason)[:200]
            self._atomic_write(meta_target, json.dumps(meta))
        except (OSError, json.JSONDecodeError):
            pass
        logging.warning(
            "[OUTBOX] SOP %s requeued to pending (no retry bump): %s",
            sop_uid,
            reason,
        )

    def move_to_undelivered(self, sop_uid):
        """Move exhausted-retry SOP to undelivered/  -  manual intervention needed."""

        # 0409: forward queue increments its own counter, not the primary's.
        undelivered_counter = (
            self._undelivered_total
            if self._undelivered_total is not None
            else outbox_undelivered_total
        )

        dcm = self._dcm_path(self._pending, sop_uid)
        # Also check in_progress (edge case: max retries hit during in-flight failure).
        if not os.path.isfile(dcm):
            dcm = self._dcm_path(self._in_progress, sop_uid)
        dst = self._dcm_path(self._undelivered, sop_uid)

        # The terminal move decides the ACCOUNTING. Moving the sidecars and
        # decrementing the counters after a FAILED blob move left the original
        # blob in pending/ with no `.meta` beside it - recovery then adopted it
        # as a fresh orphan with zero retries and no audit trail, and the
        # undelivered counter had been bumped for an item that never reached
        # the terminal state.
        if not os.path.isfile(dcm):
            # The blob already left the queue by another path: there is nothing
            # to park, but the counter must follow reality or the queue reports
            # an item it does not own and never recovers on its own.
            logging.critical(
                "[OUTBOX] Nothing to move to undelivered for %s - dropping its "
                "pending accounting",
                sop_uid,
            )
            with self._pending_lock:
                self._pending_count = max(0, self._pending_count - 1)
            self._set_pending_gauge()
            return False
        try:
            shutil.move(dcm, dst)
            logging.critical("[OUTBOX] SOP %s moved to UNDELIVERED: %s", sop_uid, dst)
        except OSError as e:
            # Leave the sidecars and the counters ALONE: the item is still a
            # live entry and the next sweep must retry the move WITH its
            # `.meta`.
            logging.critical(
                "[OUTBOX] Failed to move %s to undelivered: %s - keeping its "
                "retry state and accounting for a later attempt",
                sop_uid,
                e,
            )
            return False

        # Carry the audit sidecars WITH the blob. `.mods` is the record of what
        # the bridge changed (Modified Attributes Sequence material) and `.meta`
        # is why the item gave up - deleting them on the way to `undelivered/`
        # destroyed the trail exactly where an operator needs it to decide what
        # to do with a saved instance. The forward path already carries both.
        moved_sidecars = set()
        for dir_ in [self._pending, self._in_progress]:
            for src_sidecar, dst_sidecar in (
                (
                    self._meta_path(dir_, sop_uid),
                    self._meta_path(self._undelivered, sop_uid),
                ),
                (
                    self._mods_path(dir_, sop_uid),
                    self._mods_path(self._undelivered, sop_uid),
                ),
            ):
                if dst_sidecar in moved_sidecars:
                    continue
                if not os.path.isfile(src_sidecar):
                    continue
                try:
                    shutil.move(src_sidecar, dst_sidecar)
                    moved_sidecars.add(dst_sidecar)
                except OSError as e:
                    logging.warning(
                        "[OUTBOX] Could not carry sidecar %s to undelivered: %s",
                        src_sidecar,
                        e,
                    )

        with self._pending_lock:
            self._pending_count = max(0, self._pending_count - 1)
        self._set_pending_gauge()
        try:
            undelivered_counter.inc()
        except Exception:
            pass
        return True

    # -- recovery ------------------------------------------------------

    def recover_stuck(self, force=False):
        """Move stuck in_progress/ items back to pending/. Called at startup and periodically.

        Two categories:
          1. in_progress/ files with mtime older than STUCK_ITEM_TIMEOUT -> back to pending/
          2. pending/ items with retry_count >= MAX_RETRIES -> move to undelivered/

        `force=True` is the startup sweep: a crash + fast restart leaves the
        dead worker's in_progress/ items with a FRESH mtime, so the normal
        cutoff would hide them from `_sync_pending_count` and `delivered()`
        until the next periodic sweep (up to 300 s later) - long enough for a
        commitment tracker to answer "not committed" for a delivered SOP.
        Force treats every in_progress item as stuck (cutoff = now).
        """
        now = time.time()
        cutoff = now if force else now - STUCK_ITEM_TIMEOUT
        recovered = 0
        undelivered_count = 0
        # Orphans whose audit marker has no sidecar: counted, never adopted.
        quarantined = 0

        # Category 1: stuck in_progress -> pending.
        try:
            for name in os.listdir(self._in_progress):
                if not name.endswith(".dcm"):
                    continue
                # `name` is the ESCAPED form; unescape so the rename paths
                # below (re-escaped by _safe_uid) name the same file.
                uid = self._unsafe_uid(name[:-4])
                safe_uid = self._safe_uid(uid)
                dcm_path = os.path.join(self._in_progress, name)
                try:
                    if os.path.getmtime(dcm_path) < cutoff:
                        # The `.audit` marker travels with the item: dropping it
                        # on the way back to pending/ erased the proof that the
                        # blob needs its `.mods`, and the next claim then
                        # delivered a modified instance as raw bytes.
                        for ext in [".dcm", ".meta", ".mods", ".audit"]:
                            src = os.path.join(self._in_progress, safe_uid + ext)
                            dst = os.path.join(self._pending, safe_uid + ext)
                            if os.path.isfile(src):
                                os.rename(src, dst)
                        recovered += 1
                except OSError:
                    pass
        except OSError:
            pass

        # Category 1b: orphan .dcm files in pending/ without .meta (crashed before metadata write).
        # Create a .meta so dequeue() can find them.
        #
        # A blob whose .meta is missing is only an orphan once it has stopped
        # being written. The sweep also runs on a timer while enqueue() is in
        # flight, and enqueue writes .dcm first and .meta LAST - adopting a
        # blob that is still being written publishes a half-written instance as
        # ready. Earlier than ENQUEUE_PUBLISH_GRACE_SEC, it is not ours to adopt.
        orphan_cutoff = now - ENQUEUE_PUBLISH_GRACE_SEC
        try:
            for name in os.listdir(self._pending):
                if not name.endswith(".dcm"):
                    continue
                # `name` is the ESCAPED form; unescape before `_meta_path`
                # re-escapes it - the same double-escape as dequeue. A UID
                # with % or / would otherwise adopt a .meta under a name no
                # read path can ever match.
                uid = self._unsafe_uid(name[:-4])
                meta_path = self._meta_path(self._pending, uid)
                if not os.path.isfile(meta_path):
                    dcm_path = os.path.join(self._pending, name)
                    try:
                        if os.path.getmtime(dcm_path) > orphan_cutoff:
                            continue
                    except OSError:
                        continue
                    # A blob that declares it needs audit data must HAVE it.
                    # Adopting it otherwise publishes an instance whose
                    # Modified Attributes Sequence never existed, and
                    # `dequeue()` would deliver the modified dataset as raw
                    # bytes - a different record from the one this bridge
                    # documents. Quarantine instead of adopting.
                    if os.path.isfile(self._audit_path(self._pending, uid)) and not (
                        os.path.isfile(self._mods_path(self._pending, uid))
                    ):
                        quarantined += 1
                        logging.error(
                            "[OUTBOX] Orphan %s requires audit data but its "
                            ".mods is missing - NOT adopting it; left in "
                            "pending/ for an operator",
                            uid,
                        )
                        continue
                    now_ts = time.time()
                    meta = {
                        "created_at": now_ts,
                        "retry_count": 0,
                        "next_retry_at": now_ts,
                        "last_error": None,
                    }
                    self._atomic_write(meta_path, json.dumps(meta))
                    recovered += 1
                    logging.info("[OUTBOX] Created .meta for orphan %s", uid)
        except OSError:
            pass

        if recovered > 0:
            logging.warning(
                "[OUTBOX] Recovered %d stuck in_progress item(s)", recovered
            )

        # Category 2: max-retry items -> undelivered.
        try:
            for name in os.listdir(self._pending):
                if not name.endswith(".meta"):
                    continue
                # `name` is the ESCAPED form; unescape before `_dcm_path`
                # re-escapes it (the same double-escape as `dequeue`).
                uid = self._unsafe_uid(name[:-5])
                meta_path = os.path.join(self._pending, name)
                try:
                    with open(meta_path, "r", encoding="utf-8") as f:
                        meta = json.load(f)
                except (json.JSONDecodeError, OSError):
                    continue
                if meta.get("retry_count", 0) >= self.MAX_RETRIES:
                    dcm = self._dcm_path(self._pending, uid)
                    if os.path.isfile(dcm):
                        # Count only an item that actually moved. A False
                        # return means the blob is still live and will be
                        # tried again, so reporting it as moved overstates
                        # both the log line and the recovered tuple.
                        if self.move_to_undelivered(uid):
                            undelivered_count += 1
        except OSError:
            pass

        if undelivered_count > 0:
            logging.warning(
                "[OUTBOX] Moved %d max-retry item(s) to undelivered", undelivered_count
            )

        # Sync in-memory counter from FS.
        self._sync_pending_count()

        return (recovered, undelivered_count)

    # -- query helpers -------------------------------------------------

    def pending_count(self):
        """Return approximate pending count (in-memory, O(1))."""
        with self._pending_lock:
            return self._pending_count

    def pending_bytes(self):
        """Bytes currently held in pending/ (O(n) walk, size of each blob).

        R7: a walk, not a counter. `enqueue` runs once per instance, not in a
        loop, and the blob count it walks is bounded by `max_queue`, so the
        scan is cheap; a byte counter would have to be kept in step with
        every path that writes, moves or deletes a blob (deliver, requeue,
        undelivered, recovery), which is where drift comes from.

        R7b: the walk runs on EVERY admitted C-STORE (the admission gate
        calls it per instance), and each blob in it costs a `getsize` stat.
        With a dead server and store_forward the pending/ directory holds up
        to `max_queue` blobs, so thousands of stats per C-STORE, multiplied
        by the concurrent handlers, collapse throughput exactly when the
        backlog is worst. A 1 s TTL cache keeps the same walk but not per
        instance: the backpressure ratio only needs to move on the order of
        a second, not per blob.
        """
        now = time.monotonic()
        cached = getattr(self, "_pending_bytes_cache", None)
        if cached is not None and now - cached[0] < 1.0:
            return cached[1]
        total = self._pending_bytes_walk()
        self._pending_bytes_cache = (now, total)
        return total

    def _pending_bytes_walk(self):
        """Uncached size of pending/, lock-free (see `pending_bytes`).

        The admission gate adds in-flight reservations on top of this, under
        the pending lock, so a producer that has been admitted but has not
        finished writing still occupies its budget.
        """
        total = 0
        try:
            names = os.listdir(self._pending)
        except OSError:
            return 0
        for name in names:
            if not name.endswith(".dcm"):
                continue
            try:
                total += os.path.getsize(os.path.join(self._pending, name))
            except OSError:
                continue
        return total

    def _over_byte_budget(self, incoming_bytes):
        """True when accepting `incoming_bytes` would exceed the byte budget.

        Checked BEFORE the blob is published: refusing afterwards would mean
        writing the bytes that caused the overflow and then deleting them.
        """
        if not self.max_queue_bytes:
            return False
        return self.pending_bytes() + max(0, incoming_bytes) > self.max_queue_bytes

    def _sync_pending_count(self):
        """Recalculate the pending count from the filesystem (startup / recovery).

        The invariant is `_pending_count` = blobs the queue still OWNS, i.e.
        pending/ plus in_progress/. Recovery runs outside the workers, so the
        snapshot and the assignment happen under the same lock `enqueue`
        increments under: taking the count outside the lock and assigning it
        inside erased any publication that landed in between, and the queue
        then under-reported permanently. In-progress blobs are counted because
        `mark_delivered` is what subtracts them.
        """
        # The directory was just swept: the cached listing is stale.
        self._pending_meta_cache = None
        self._pending_bytes_cache = None
        try:
            names = os.listdir(self._pending)
        except OSError:
            names = []
        count = sum(1 for n in names if n.endswith(".dcm"))
        try:
            claimed = sum(
                1 for n in os.listdir(self._in_progress) if n.endswith(".dcm")
            )
        except OSError:
            claimed = 0
        # Recovery is where the ledger is TRUSTED again: every path that moves
        # a blob without going through `enqueue`/`mark_delivered` (recovery
        # adopting an orphan, a manual `cleanup`, an operator moving files)
        # lands here, so the walk below is the authority.
        #
        # The snapshot is reconciled against every publication that is still
        # IN FLIGHT, under the lock: the listing above is a read of the
        # filesystem taken without one, so an enqueue that reserved its slot
        # and is still writing has no `.dcm` yet and would be erased by the
        # assignment - the queue then under-reported for the rest of the
        # process life. The reservations are the only place those publications
        # are visible, so they are ADDED to the measured count rather than
        # assumed to be included in it.
        measured = self._pending_bytes_walk()
        with self._pending_lock:
            self._pending_count = count + claimed + len(self._reserved_names)
            self._pending_bytes = measured + self._reserved_bytes
            self._pending_bytes_cache = None
        self._set_pending_gauge()
        return self._pending_count

    def next_retry_wait_sec(self):
        """Return seconds until the next SOP is ready for retry, or 5.0 if empty.

        Scans pending/*.meta to find min next_retry_at. O(n) on <=1000 files  -  fine.
        """
        now = time.time()
        earliest = None
        try:
            for name in os.listdir(self._pending):
                if not name.endswith(".meta"):
                    continue
                meta_path = os.path.join(self._pending, name)
                try:
                    with open(meta_path, "r", encoding="utf-8") as f:
                        meta = json.load(f)
                except (json.JSONDecodeError, OSError):
                    continue
                retry_count = meta.get("retry_count", 0)
                next_retry = meta.get("next_retry_at", 0)
                if retry_count < self.MAX_RETRIES and next_retry > now:
                    if earliest is None or next_retry < earliest:
                        earliest = next_retry
        except OSError:
            pass

        if earliest is not None:
            wait = earliest - now
            return max(0.1, min(wait, 5.0))
        return 5.0

    def _get_retry_count(self, sop_uid):
        """Return current retry count for a SOP."""
        for dir_ in [self._pending, self._in_progress]:
            meta_path = self._meta_path(dir_, sop_uid)
            if os.path.isfile(meta_path):
                try:
                    with open(meta_path, "r", encoding="utf-8") as f:
                        return json.load(f).get("retry_count", 0)
                except (json.JSONDecodeError, OSError):
                    pass
        return 0

    def close(self):
        """No-op on filesystem."""

# ---------------------------------------------------------------------------
# Bridge: sop_index
# ---------------------------------------------------------------------------

"""SOP Instance UID index  -  filesystem-backed key-value store.

nginx-way: one JSON file per SOP UID. Directory = index.
No SQLite. No locks. No busy_timeout.
"""

import json
import logging
import os
import threading
import time

class SopIndexManager:
    """Filesystem-backed index: SOPInstanceUID -> (StudyInstanceUID, SeriesInstanceUID).

    Layout:
        sop_index/{sop_uid}.json -> {"study_uid": "...", "series_uid": "...",
                                     "ts": ..., "is_verified": false}

    Populated at C-STORE time after successful STOW-RS (HTTP 200/201/202).
    Looked up at N-ACTION time to verify Storage Commitment.
    """

    def __init__(self, index_dir):
        """index_dir: path to sop_index directory (created if absent)."""
        self._dir = index_dir
        os.makedirs(self._dir, exist_ok=True)
        # One guard per index file. A unique temp name stops two writers from
        # sharing a file, but they still rename onto the SAME destination, and
        # on Windows the second `os.replace` fails with a sharing violation
        # while the first destination handle is open - which loses the entry.
        # The guard covers readers too: `lookup_sop` holds the destination open
        # while it parses it, and that open handle blocks the rename just as
        # surely as a competing writer would. Striped rather than one lock per
        # path: cleanup() deletes index files but cannot reclaim their locks,
        # so a per-path dict grows for the life of the process.
        self._publish_guards = LockStripes()

    def _guard_for(self, path):
        """The guard serialising access to one index file."""
        return self._publish_guards.for_key(path)

    def _path(self, sop_uid):
        # Percent-escape rather than substitute: collapsing `\x00`, `/` and `\`
        # all to `_` made two distinct UIDs share one index file, so one SOP
        # silently overwrote the other's entry. See OutboxQueue._safe_uid.
        safe = (
            sop_uid.replace("%", "%25")
            .replace("\x00", "%00")
            .replace("/", "%2F")
            .replace("\\", "%5C")
        )
        return os.path.join(self._dir, f"{safe}.json")

    def _write_unlocked(self, path, data):
        """Write `data` to `path` atomically. The caller holds the guard.

        The index is keyed by SOP UID, so two reactor threads handling the same
        instance write the SAME path. A shared `<path>.tmp` made them interleave
        into one file and both `os.replace` it, which loses an entry outright (a
        stored SOP then reads as unconfirmed) and leaves stray `.json.tmp` files
        behind when a write fails.
        """
        tmp = f"{path}.{os.getpid()}.{threading.get_ident()}.tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(data, f)
                f.flush()
            replace_with_retry(tmp, path)
        except Exception:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise

    def _write(self, path, data):
        """Write `data` to `path` atomically, as one publish operation."""
        with self._guard_for(path):
            self._write_unlocked(path, data)

    def insert_sop(self, sop_uid, study_uid, series_uid):
        """Insert or replace a SOP entry. Idempotent."""
        data = {
            "study_uid": study_uid,
            "series_uid": series_uid,
            "ts": int(time.time()),
            "is_verified": False,
        }
        path = self._path(sop_uid)
        self._write(path, data)

    def _read_unlocked(self, path):
        """Read one index file. The caller holds the guard."""
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)

    def lookup_sop(self, sop_uid):
        """Look up a SOP UID. Returns dict or None."""
        path = self._path(sop_uid)
        if not os.path.isfile(path):
            return None
        try:
            # Under the per-file guard: on Windows this open handle would
            # otherwise block a concurrent writer's `os.replace` with a
            # sharing violation, which loses the entry it was writing.
            with self._guard_for(path):
                return self._read_unlocked(path)
        except (json.JSONDecodeError, OSError) as e:
            logging.warning("[SOP-INDEX] Corrupt %s: %s", path, e)
            return None

    def mark_verified(self, sop_uid):
        """Mark a SOP as verified after successful N-ACTION check.

        The read, the update and the write are ONE locked step. Reading with
        the guard released (`lookup_sop` then `_write`) let an `insert_sop`
        publish a fresh replacement in between, which this path then
        overwrote with the stale scope it had read and marked verified.
        """
        path = self._path(sop_uid)
        with self._guard_for(path):
            if not os.path.isfile(path):
                return
            try:
                entry = self._read_unlocked(path)
            except (json.JSONDecodeError, OSError) as e:
                logging.warning("[SOP-INDEX] Corrupt %s: %s", path, e)
                return
            entry["is_verified"] = True
            self._write_unlocked(path, entry)

    def cleanup(self, max_age_seconds=86400):
        """Remove entries older than max_age_seconds (default: 24h)."""
        cutoff = time.time() - max_age_seconds
        removed = 0
        try:
            for name in os.listdir(self._dir):
                if not name.endswith(".json"):
                    continue
                path = os.path.join(self._dir, name)
                try:
                    # The guard spans the mtime check AND the unlink: an
                    # `insert_sop` between them publishes a fresh replacement
                    # that the unlink would then delete (TOCTOU). Holding it
                    # serialises the sweep against a publisher of this file.
                    with self._guard_for(path):
                        if os.path.getmtime(path) < cutoff:
                            os.unlink(path)
                            removed += 1
                except OSError:
                    pass
        except OSError:
            pass
        if removed > 0:
            logging.info("[SOP-INDEX] Cleaned %d entries", removed)

    def count(self):
        """Return total number of entries."""
        try:
            return sum(1 for n in os.listdir(self._dir) if n.endswith(".json"))
        except OSError:
            return 0

    def close(self):
        """No-op on filesystem."""

# ---------------------------------------------------------------------------
# Bridge: health_checker
# ---------------------------------------------------------------------------

"""Clarus Bridge - DICOMweb Server Health Checker.

Background poller + pre-flight gate. Polls GET /health every N seconds
and updates a threading.Event. C-STORE handler reads the Event -
zero HTTP overhead on the hot path, proactive degradation.

Modes (from clbridge.conf [dicomweb] health_check_mode):
  "probe"  - background poll. On HTTP 404: server has no /health endpoint
             - disable checks until bridge restart (max compatibility).
  "always" - background poll every `interval` seconds. If server unhealthy,
             C-STORE immediately returns 0xA700 - no buffering, no waste.
             For Clarus: always use this mode.
  "never"  - skip health check entirely (max DICOMweb compatibility).

/health is NOT in PS3.18 - it's a Kubernetes liveness/readiness de-facto
standard. Non-K8s DICOMweb servers (Orthanc, dcm4che) don't have it.
"""

import logging
import threading
import time

import requests

class HealthChecker:
    """Background health-check of DICOMweb server + pre-flight gate.

    Background thread polls GET /health every `interval` seconds.
    Updates `_server_healthy` threading.Event proactively.
    C-STORE handler reads the Event via check_before_stow() -
    no HTTP on the hot path, bridge degrades before buffering.

    Thread-safe: check_before_stow() is lock-free (reads Event).
    Only the background poller writes state.
    """

    def __init__(
        self,
        clarus_url: str,
        mode: str = "probe",
        interval: float = 5.0,  # background poll interval (probe + always)
        http_timeout: float = 5.0,
        tls=None,
    ):
        if mode not in ("probe", "always", "never"):
            raise ValueError(
                f"health_check_mode must be 'probe'|'always'|'never', got '{mode}'"
            )
        self._clarus_url = clarus_url
        # /health lives at the server ROOT, not under /dicomweb (2908).
        self._health_url = f"{dicomweb_origin(clarus_url)}/health"
        self._tls = tls
        self._mode = mode
        self._interval = interval
        self._http_timeout = http_timeout

        # Proactive state (updated by background poller)
        self._server_healthy = threading.Event()
        self._server_healthy.set()  # Start optimistic - assume alive
        self._last_ok_time = time.monotonic()
        self._consecutive_failures = 0
        self._disabled_until_restart = False  # set on 404 in "probe" mode
        self._last_reason = ""
        # R11: set when /health answers 4xx. That is the server being reachable
        # but refusing the probe (bad auth, wrong verb, throttling), which says
        # nothing about whether it can store. The gate is restored while this
        # is set, so a transient probe rejection cannot pin every C-STORE to
        # 0xA700 for the life of the process.
        self._probe_rejected = False

        # Background thread
        self._thread = None

    # --- Public API ---

    def is_healthy(self) -> bool:
        """Return True if server is currently considered healthy.

        Non-blocking snapshot - reads Event, no HTTP.
        """
        if self._mode == "never":
            return True
        if self._disabled_until_restart:
            return True  # Server has no /health - assume OK
        return self._server_healthy.is_set()

    def check_before_stow(self) -> tuple:
        """Pre-flight health gate. Call before each STOW-RS.

        Both "probe" and "always" use the background poller's Event.
        Lock-free: zero HTTP overhead on the C-STORE hot path.

        "never" mode: always OK.
        "probe" mode:  if 404 was detected, checks disabled (always OK).
        "always" mode: Event reflects server state; 0xA700 if unhealthy.

        Returns:
            (True, 0x0000, "")         - server healthy, proceed
            (False, 0xA700, reason)    - server unhealthy, reject with 0xA700
            (True, 0x0000, "disabled") - health check disabled (probe got 404)
        """
        if self._mode == "never":
            return (True, 0x0000, "")

        if self._disabled_until_restart:
            return (True, 0x0000, "disabled")

        # Lock-free Event read - updated by background poller.
        # Zero HTTP on the hot path, proactive degradation.
        if self._server_healthy.is_set():
            return (True, 0x0000, "")

        return (False, 0xA700, self._last_reason or "server unhealthy")

    def dead_seconds(self) -> float:
        """Return seconds since last successful health check (0 if healthy).

        Uses the same predicate as `is_healthy()`: a disabled checker is not
        reporting an outage, so it must not report outage TIME either. In
        `probe` mode a 503 followed by a 404 exits the poller and reopens
        STOW admission, but the healthy Event is left as the 503 left it -
        reading the Event alone reported an "outage" that grew for the life of
        the process, long after the bridge had decided the server was fine.
        """
        if self._disabled_until_restart:
            return 0.0
        if self._server_healthy.is_set():
            return 0.0
        return time.monotonic() - self._last_ok_time

    # --- Lifecycle ---

    def start(self):
        """Start background health-check thread.

        "always" mode: poller runs forever, never disables.
        "probe" mode:  poller runs until first 404, then disables.
        "never" mode:  no poller, no checks.
        """
        if self._mode == "never":
            logging.info("[HEALTH] Health check disabled (mode=never).")
            return

        # Both "probe" and "always" use background polling.
        # Probe auto-disables on 404 (non-Clarus servers without /health).
        # Always mode: stays enabled permanently (Clarus, Kubernetes -
        # /health endpoint is guaranteed to exist).
        self._thread = threading.Thread(
            target=self._run,
            name="health-checker",
            daemon=True,
        )
        self._thread.start()
        logging.info(
            "[HEALTH] Background poller started: GET %s "
            "every %.0fs, timeout=%.0fs, mode=%s",
            self._health_url,
            self._interval,
            self._http_timeout,
            self._mode,
        )

    def stop(self):
        """Stop background thread (no-op - daemon thread exits with process)."""
        # Daemon thread, no explicit stop needed

    # - Background Poller -

    def _run(self):
        """Background loop: poll /health, update Event."""

        was_dead = False
        while not _shutdown_requested.is_set():
            was_dead = self._poll_once(was_dead)
            if self._disabled_until_restart:
                return  # Probe mode found no /health - nothing to poll
            time.sleep(self._interval)

    def _poll_once(self, was_dead):
        """One /health fetch; update the healthy Event. Returns the new
        `was_dead` flag.

        Split out of the loop so each verdict is reachable without a thread:
        the 4xx/5xx distinction is the whole point of the branch and could not
        be exercised while it lived inside an infinite loop.
        """
        url = self._health_url
        try:
            resp = requests.get(url, timeout=self._http_timeout, cert=self._tls)
            if resp.status_code == 200:
                self._on_healthy()
                return False
            if resp.status_code == 404 and self._mode == "probe":
                # Server has no /health - disable checks permanently
                self._disabled_until_restart = True
                logging.warning(
                    "[HEALTH] Server returned 404 on /health - "
                    "health check disabled until bridge restart "
                    "(mode=probe). Server: %s",
                    self._clarus_url,
                )
                return was_dead
            if 400 <= resp.status_code < 500:
                # A 4xx is the SERVER ANSWERING: it is alive and refusing this
                # particular request. 401/403 mean the probe is unauthenticated
                # or the config is wrong, 405 that the verb is wrong, 429 that
                # the probe is being throttled. Reporting "down" for them
                # cleared the health Event and made every C-STORE answer
                # 0xA700 - a bridge that stores nothing because its own probe
                # is unauthorised is worse than one that stores and lets the
                # real request fail on its own merits.
                #
                # The probe's own "not found" is the 404 case above. Any other
                # 4xx therefore means the endpoint exists but this request
                # cannot use it: keep the last verdict, and say so once so the
                # operator can fix the probe.
                reason = f"probe rejected HTTP {resp.status_code}"
                if not self._probe_rejected:
                    logging.warning(
                        "[HEALTH] /health answered HTTP %d - server is "
                        "reachable but the probe is not accepted; keeping "
                        "C-STORE enabled (check auth/config)",
                        resp.status_code,
                    )
                self._probe_rejected = True
                self._last_reason = reason
                # The server ANSWERED, so it is up for our purposes: restore
                # the gate. Leaving it cleared because the probe is unauthorised
                # made the bridge refuse every instance after a single 401.
                self._server_healthy.set()
                self._consecutive_failures = 0
                self._last_ok_time = time.monotonic()
                # The gate is open again, so the outage it was recording is
                # over. Returning `was_dead` left the flag set, and the NEXT
                # 503 then took the "already down" path - no new-outage
                # warning, so an operator saw one outage where the log
                # recorded two (503 then 401 then 503), with the second one
                # unannounced.
                return False
            self._on_unhealthy(f"Server returned HTTP {resp.status_code}", was_dead)
            return True
        except requests.exceptions.Timeout:
            self._on_unhealthy(f"/health timeout after {self._http_timeout}s", was_dead)
            return True
        except requests.exceptions.ConnectionError as e:
            self._on_unhealthy(f"Connection refused: {e}", was_dead)
            return True
        except Exception as e:
            self._on_unhealthy(f"/health error: {e}", was_dead)
            return True

    def _on_healthy(self):
        """Called when /health returns 200."""
        if not self._server_healthy.is_set():
            downtime = time.monotonic() - self._last_ok_time
            logging.warning(
                "[HEALTH] Server recovered after %.0fs downtime",
                downtime,
            )
        self._server_healthy.set()
        self._consecutive_failures = 0
        self._last_ok_time = time.monotonic()
        self._last_reason = ""
        self._probe_rejected = False

    def _on_unhealthy(self, reason: str, was_dead: bool):
        """Called when /health fails."""
        self._server_healthy.clear()
        self._consecutive_failures += 1
        self._last_reason = reason
        if not was_dead:
            logging.warning(
                "[HEALTH] Check #%d failed: %s - bridge degraded, "
                "C-STORE will return 0xA700",
                self._consecutive_failures,
                reason,
            )
        elif self._consecutive_failures % 12 == 0:
            # Periodic reminder every ~60s (12 * 5s interval)
            dead_for = time.monotonic() - self._last_ok_time
            logging.error(
                "[HEALTH] Server still dead after %.0fs " "(check #%d): %s",
                dead_for,
                self._consecutive_failures,
                reason,
            )

# ---------------------------------------------------------------------------
# Bridge: handlers/cfind
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  C-FIND handler: dispatches to Patient/Study Root or MWL.

CRIT-002: extracted common _handle_qido_search() to eliminate ~60 lines of duplication.
"""

import logging
from collections import Counter
from urllib.parse import quote

import httpx

# ---------------------------------------------------------------------------
# Bridge: C-FIND handler with response limit + timeout
# ---------------------------------------------------------------------------
def _stamp_cfind_response(event, row_ds):
    """Echo (0008,0052) QueryRetrieveLevel and add (0008,0054)
    RetrieveAETitle on every C-FIND response row (01.09 Orthanc-control
    finding: MicroDicom's series panel keys rows by the RESPONSE
    QueryRetrieveLevel; Orthanc puts both on every row and the panel
    renders there). Spec-legal: PS3.4 C.4.1 - the response identifier
    shall contain the attributes of the request identifier; the SCP's
    AE title is a standard C-FIND response attribute.
    """
    level = (
        str(getattr(event.identifier, "QueryRetrieveLevel", "") or "").strip().upper()
        or "STUDY"
    )
    if "QueryRetrieveLevel" not in row_ds:
        row_ds.QueryRetrieveLevel = level
    bridge_ae = (
        getattr(
            getattr(getattr(event, "assoc", None), "acceptor", None), "ae_title", ""
        )
        or ""
    )
    if bridge_ae and "RetrieveAETitle" not in row_ds:
        row_ds.RetrieveAETitle = bridge_ae

def _cfind_shape(ds):
    """Privacy-safe C-FIND query shape for diagnostics (31.08 field
    debugging): attribute NAMES with a '*' marker when the value contains
    a wildcard star, plus QueryRetrieveLevel and SpecificCharacterSet.
    NO attribute values are logged (PHI discipline, access-journal rule).
    """
    keys = []
    for elem in ds:
        if elem.VR == "SQ" or not elem.keyword:
            continue
        val = elem.value
        if val is None or str(val).strip() == "":
            continue
        keys.append(elem.keyword + ("*" if "*" in str(val) else ""))
    level = str(getattr(ds, "QueryRetrieveLevel", "") or "")
    charset = str(getattr(ds, "SpecificCharacterSet", "") or "")
    return (
        f"level={level or '-'} keys={','.join(keys) or '-'} "
        f"charset={charset or '-'}"
    )

def handle_c_find(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """Dispatch C-FIND to Patient Root, Study Root, or MWL models.

    `expose_rejected` is a property of the AE that accepted this association,
    not of the message: the QA AE sets it, every other AE leaves it False. It
    selects `qa_url` (the backend QA webservice endpoint) as the DICOMweb base
    instead of `clarus_url`; no query parameter is added, so the bridge works
    against any server that publishes such an endpoint.
    """
    # Bridge: reject new requests during shutdown
    if _shutdown_requested.is_set():
        yield 0xC000, None
        return

    model_uid = event.context.abstract_syntax
    calling_ae = event.assoc.requestor.ae_title
    logging.info("[DIMSE] C-FIND from %s -> model: %s", calling_ae, model_uid)
    logging.info("[C-FIND-DEBUG] AE=%s %s", calling_ae, _cfind_shape(event.identifier))

    if model_uid == PATIENT_ROOT_UID:
        yield from _handle_patient_root(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
    elif model_uid == STUDY_ROOT_UID:
        yield from _handle_study_root(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
    elif model_uid == MWL_UID:
        # MWL is a worklist: rejected instances are stored studies, never
        # scheduled procedures, so the QA AE has nothing to change here.
        yield from _handle_mwl(
            event, clarus_url, verbose, max_responses, http_timeout, tls
        )
    else:
        yield 0xA900, None

# ---------------------------------------------------------------------------
# CRIT-002: Common QIDO-RS search handler (eliminates ~60 lines of duplication)
# ---------------------------------------------------------------------------
# 31.08 honest error logging: HTTP status errors log the actual status and
# URL (with PHI values masked, like the access journal);
# "connection failed" is reserved for TRANSPORT errors. 4xx is never
# retried (_http_retry) - a 400 here means the bridge sent a bad query.
#
# PS3.18 Table 6.7.1-1: every query key here can carry patient data, not just
# PatientName - PatientID, the accession number and the description fields all
# identify a person. Masking one key left the rest in the journal.
_MASKED_LOG_KEYS = frozenset(
    key.lower()
    for key in (
        "PatientName",
        "PatientID",
        "OtherPatientIDs",
        "PatientBirthDate",
        "PatientSex",
        "PatientAddress",
        "PatientTelephoneNumbers",
        "AccessionNumber",
        "StudyDescription",
        "SeriesDescription",
        "InstitutionName",
        "ReferringPhysicianName",
        "PerformingPhysicianName",
        "NameOfPhysiciansReadingStudy",
        "RequestingPhysician",
        "AdmittingDiagnosesDescription",
        "StudyID",
    )
)
# The same keys by tag, for a caller that passed numeric tags. Normalised to
# lower case because `_masked_query` lower-cases the key before the lookup:
# a tag whose element component contains a hex letter (0008,103E, 0008,1060,
# 0008,1080) is stored with that letter in upper case by convention, and an
# exact comparison against the canonical spelling let the whole tag - and the
# PHI it carries - through unmasked.
_MASKED_LOG_TAGS = frozenset(
    tag.lower()
    for tag in (
        "00100010",
        "00100020",
        "00100022",
        "00100030",
        "00100040",
        "00101040",
        "00102154",
        "00080050",
        "00081030",
        "0008103E",
        "00080080",
        "00080090",
        "00081050",
        "00081060",
        "00081080",
        "00200010",
    )
)

def _masked_query(params):
    """Render QIDO params for logging with every PHI value masked as ***.

    The key is URL-decoded and lower-cased before the lookup: a query string
    may spell `patientname` or percent-encode the tag, and an exact-match
    comparison against the canonical spelling would let those through.
    """
    from urllib.parse import unquote

    parts = []
    # The error path calls this with whatever `params` holds, and a caller may
    # pass `default_param=None` (no default search key). Masking must never be
    # the reason a status is not sent, so a missing map logs as empty.
    for key in sorted(params or {}):
        bare = unquote(str(key)).strip().lower().replace(",", "")
        if bare in _MASKED_LOG_KEYS or bare in _MASKED_LOG_TAGS:
            parts.append(f"{key}=***")
        else:
            parts.append(f"{key}={params[key]}")
    return "&".join(parts)

def _handle_qido_search(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout,
    default_param,
    log_label,
    url_path="studies",
    json_to_ds=_json_to_dataset,
    tls=None,
    expose_rejected=False,
    qa_url="",
    row_filter=None,
):
    """Common C-FIND handler: QIDO-RS search -> DIMSE Pending responses.

    Args:
        default_param: default search value if no params extracted
            (e.g. {"PatientName": "*"} for Patient Root,
             {"StudyDescription": "*"} for Study Root)
        log_label: label for find_responses metric ('study' or 'mwl')
        url_path: DICOMweb resource path ("studies" or "workitems")
        json_to_ds: DICOMweb JSON -> Dataset converter (QIDO-study for
            "studies", MWL/UPS for "workitems")
    """
    ds = event.identifier
    # MWL requests carry their SPS-level keys inside (0040,0100), so the MWL
    # path needs keywords from the sequence item too. QIDO keeps the flat
    # extraction: its identifier carries no SPS sequence, and recursing would
    # only add noise to its keyword set.
    if url_path == "workitems":
        request_keywords = _extract_mwl_request_keywords(ds)
    else:
        request_keywords = _extract_request_keywords(ds)
    # Diagnostics ( 23.08): the bridge used to drop unmapped keywords
    # silently, which hid the modality-filter field bug behind "show all".
    logging.info(
        "[C-FIND] %s keywords: %s",
        log_label,
        ", ".join(sorted(request_keywords)) if request_keywords else "(none)",
    )
    if url_path == "workitems":
        # MWL: params already formed by caller, skip _build_qido_params
        params = default_param
    else:
        params = _build_qido_params(ds)
        if not params:
            params = default_param
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    url = f"{base}/{url_path}"
    # One row beyond the limit keeps the local truncation guard reachable: a
    # server told exactly max_responses cannot prove there was more
    # (PS3.4 Table C.4.1-1: B001 means further matches exist).
    qido_limit = max_responses + 1 if max_responses else None
    try:
        results = _qido_request(
            url,
            params,
            http_timeout,
            limit=qido_limit,
            tls=tls,
        )
        if not isinstance(results, (list, QidoPage)):
            results = []
    except httpx.HTTPStatusError as exc:
        # Status class decides the refusal: 4xx is the BRIDGE's own bad
        # query (e.g. series keys on the study level), 5xx is the server or
        # a proxy failing for a reason unrelated to this query. The response
        # body is not logged (may echo the query).
        #
        # R14: 429 is NOT a bad query - it is the upstream rate-limiting us,
        # and it is TRANSIENT. `_http_status_to_dimse` already classifies it
        # (and 5xx) as 0xA700; a bare `>= 500` check turned rate-limiting into
        # 0xC000, which told the SCU to give up on a query that would succeed
        # a moment later.
        logging.warning(
            "[C-FIND] QIDO HTTP %d: %s?%s",
            exc.response.status_code,
            url,
            _masked_query(params),
        )
        dimse, _code, _desc = _http_status_to_dimse(exc.response.status_code)
        yield dimse, None
        return
    except QidoMalformedBodyError as exc:
        # R16: a 2xx whose body is not a DICOM JSON array is an unreadable
        # ANSWER, not an empty result (batch-2 raised it instead of returning
        # []). It is a ValueError, so without this clause it escaped the
        # generator: no warning was logged, `find_responses` was never
        # incremented, and the SCU got whatever pynettyic picked. Treat it as
        # the transient upstream failure it is.
        logging.warning("[C-FIND] QIDO malformed response: %s", exc)
        yield 0xA700, None
        return
    except httpx.HTTPError:
        # Transport errors only: ReadError / ConnectError / Timeout. A broken
        # TCP link is TRANSIENT - answering 0xC000 told the SCU the query was
        # permanently refused, so it would never retry. 0xA700 (Refused: Out
        # of Resources) is the retryable refusal. HTTPStatusError above maps
        # by status class: 4xx -> 0xC000 (this bridge's bad query), 5xx ->
        # 0xA700 (transient upstream outage).
        logging.warning("[C-FIND] QIDO error: connection failed")
        yield 0xA700, None
        return

    count = 0
    truncated = False
    # PS3.18 10.6.1.4: the origin can answer fewer rows than the page size and
    # still report the search incomplete. 0x0000 states that no further
    # matches exist (PS3.4 Table C.4.1-1), so an answer the origin left
    # unfinished must be reported as 0xB001 instead. Only a `QidoPage` carries
    # that flag; a plain list (a caller that built its own pages) says nothing.
    incomplete = isinstance(results, QidoPage) and results.more
    for result in results:
        # PS3.7 9.3.2: a C-CANCEL can arrive at ANY time, and the SCU expects
        # the next response to be 0xFE00. Checking only at the top of a study
        # meant a multi-row answer kept sending Pending responses after the
        # SCU had already cancelled - each one a write the SCU no longer
        # reads. The rows already sent are retained in the metric.
        if getattr(event, "is_cancelled", False):
            find_responses.labels(type=log_label).inc(count)
            yield 0xFE00, None
            return
        if _shutdown_requested.is_set():
            find_responses.labels(type=log_label).inc(count)
            yield 0xC000, None
            return
        # A matching key the origin cannot filter on is applied here, BEFORE
        # the response limit, so a non-matching row never consumes a Pending
        # response (PS3.4 Table K.6-1 matching rule).
        if row_filter is not None and not row_filter(result):
            continue
        # Bridge: C-FIND response limit guard
        if max_responses and count >= max_responses:
            truncated = True
            logging.warning(
                "[C-FIND] Response limit reached (%d). "
                "Results truncated. Total available: %d.",
                max_responses,
                len(results),
            )
            break
        # Bridge: all responses sent with Pending status
        row_ds = json_to_ds(result, request_keywords)
        if url_path != "workitems":
            _stamp_cfind_response(event, row_ds)
        yield 0xFF00, row_ds
        count += 1

    # Bridge: final status when truncated.
    #
    # 0xB001 ("matching terminated due to number of matches encountered") is
    # NOT defined for Query/Retrieve by PS3.4 Table C.4.1-1 nor for MWL by
    # Table K.4-1, so it is not a status this SCP may choose to send. A search
    # the bridge could not finish is a refusal, not a success and not a
    # warning: 0xA700 (Refused: Out of Resources) is the defined status for
    # "the SCP could not complete this request", and it also tells the SCU
    # that retrying - with a narrower query - is meaningful.
    #
    # PS3.7 9.3.2: a C-CANCEL received during the HTTP request is only
    # observable AFTER it, so the cancel check has to sit between the request
    # and this terminal status; otherwise the SCU is told "success" for a
    # search it already abandoned.
    find_responses.labels(type=log_label).inc(count)
    if getattr(event, "is_cancelled", False):
        yield 0xFE00, None
        return
    if truncated or incomplete:
        yield 0xA700, None
    else:
        yield 0x0000, None

def _patient_group_key(study_row):
    """Grouping key of a study row in the patient fold.

    A study with a PatientID groups by that ID. A study without one
    (anonymous) cannot be asserted to belong to any other (PS3.4 C.6.1.1.2
    note: Patient ID is the grouping key), so it is its own group. The
    ("", id(study_row)) key keeps anonymous rows apart while staying distinct
    from a real PatientID; the id is stable because the pre-fold pass and the
    fold walk the same row list.
    """
    patient_id = _json_first_value(study_row, "00100020") or ""
    return patient_id if patient_id else ("", id(study_row))

def _int_or_zero(value):
    """DICOMweb JSON integer-string -> int; 0 when absent or unparsable.

    NumberOfStudyRelatedSeries/Instances arrive as IS strings, and the server
    may omit the key entirely. 0 is the neutral term of the fold: a study
    with no count adds nothing to the patient total.
    """
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0

def _handle_patient_level(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """C-FIND Patient Root at PATIENT level: study QIDO, folded per patient.

    PS3.4 C.6.1.1.2 Table C.6-1: PATIENT is the ROOT level of the model this
    SCP announces, and Patient's Name (0010,0010) is the one Type R attribute
    there. The bridge has no patient index of its own, so the level is served
    from the same study QIDO the STUDY level uses (PS3.18 10.6: a study
    result carries the patient attributes), folded onto one row per
    PatientID.

    Folding rules, in the order they matter:
      - Matching keys still go to the server: the study query is built by
        `_handle_qido_search`'s own parameter mapping, so a PatientName or
        PatientID filter narrows the study set exactly as at STUDY level.
      - A row keeps only the attributes Table C.6-1 defines at this level.
        PatientName is required; the optional ones are returned when the
        origin supplied a value (the shared converter already drops
        empty values, so an absent tag means the origin had nothing).
      - One row per PatientID, first-seen order: the study rows arrive
        ordered by the origin, and re-sorting would make the response
        unstable across servers.
      - A study with NO PatientID cannot be identified as belonging to any
        other, so each such study is its own row. Collapsing them would
        assert that every anonymous study is one patient (PS3.4 C.6.1.1.2
        note: Patient ID is the grouping key; without it there is no group).

    max_responses caps the PATIENT rows (not the study rows that produced
    them): the caller asked for patients, and 0xB001 must mean "more
    patients exist". A study set big enough to be ambiguous is therefore
    fetched whole - the patient count is only known after the fold, so a
    study-level limit could hide patients behind a silent early cut.
    """
    ds = event.identifier
    request_keywords = _extract_request_keywords(ds)
    logging.info(
        "[C-FIND] patient keywords: %s",
        ", ".join(sorted(request_keywords)) if request_keywords else "(none)",
    )
    params = _build_qido_params(ds) or {}
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    try:
        study_rows = _qido_request(
            f"{base}/studies",
            params,
            http_timeout,
            limit=None,
            tls=tls,
        )
        if not isinstance(study_rows, (list, QidoPage)):
            study_rows = []
    except httpx.HTTPStatusError as exc:
        # Same classifier as the other handlers: 4xx is this query's fault,
        # 5xx and 429 are upstream conditions the SCU should retry.
        logging.warning(
            "[C-FIND] QIDO HTTP %d: %s?%s",
            exc.response.status_code,
            f"{base}/studies",
            _masked_query(params),
        )
        dimse, _code, _desc = _http_status_to_dimse(exc.response.status_code)
        yield dimse, None
        return
    except QidoMalformedBodyError as exc:
        logging.warning("[C-FIND] QIDO malformed response: %s", exc)
        yield 0xA700, None
        return
    except httpx.HTTPError:
        logging.warning("[C-FIND] QIDO error: connection failed")
        yield 0xA700, None
        return

    # PS3.4 C.6.1.1.2: NumberOfPatientRelated* are TOTALS over the patient's
    # studies, series and instances - not one study's own counts. The fold
    # emits a row while walking, and the first study of a patient cannot know
    # how many more follow, so the totals are computed in one pass FIRST.
    counts = Counter()
    series_sums = {}
    instance_sums = {}
    for study_row in study_rows:
        key = _patient_group_key(study_row)
        counts[key] += 1
        series_sums[key] = series_sums.get(key, 0) + _int_or_zero(
            _json_first_value(study_row, "00201206")
        )
        instance_sums[key] = instance_sums.get(key, 0) + _int_or_zero(
            _json_first_value(study_row, "00201208")
        )

    count = 0
    truncated = False
    seen = set()
    for study_row in study_rows:
        if getattr(event, "is_cancelled", False):
            find_responses.labels(type="patient").inc(count)
            yield 0xFE00, None
            return
        if _shutdown_requested.is_set():
            find_responses.labels(type="patient").inc(count)
            yield 0xC000, None
            return
        group_key = _patient_group_key(study_row)
        if group_key in seen:
            continue
        seen.add(group_key)
        if max_responses and count >= max_responses:
            truncated = True
            logging.warning(
                "[C-FIND] Response limit reached (%d). Patients truncated.",
                max_responses,
            )
            break
        row_ds = _json_to_dataset_patient(study_row)
        # The three Patient-level counters (0020,1200/1202/1204) are the
        # fold's own totals, not values read off a study row, so they are
        # added here as IS after the study row is projected to the level.
        row_ds.add_new((0x0020, 0x1200), "IS", counts[group_key])
        row_ds.add_new((0x0020, 0x1202), "IS", series_sums[group_key])
        row_ds.add_new((0x0020, 0x1204), "IS", instance_sums[group_key])
        _stamp_cfind_response(event, row_ds)
        yield 0xFF00, row_ds
        count += 1

    find_responses.labels(type="patient").inc(count)
    # PS3.7 9.3.2 and the same rule as the common handler: a cancel that
    # arrived during the HTTP request is only visible here, before the
    # terminal status. 0xB001 is not defined for Query/Retrieve either, so an
    # incomplete answer is the defined refusal 0xA700.
    if getattr(event, "is_cancelled", False):
        yield 0xFE00, None
        return
    if truncated:
        yield 0xA700, None
    else:
        yield 0x0000, None

def _handle_patient_root(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """C-FIND Patient Root -> QIDO-RS.

    PATIENT level: one row per patient, folded from the study query
    (_handle_patient_level) - see PS3.4 C.6.1.1.2 Table C.6-1.
    STUDY level (or level absent): GET /studies - unchanged.
    SERIES level (31.08): two-step series search, the same routing Study
    Root already applies - a patient-root SERIES query used to fall through
    to the study path and relabel study rows as SERIES, so the SCU received
    rows with no SeriesInstanceUID.
    IMAGE level: three-step series search (study -> series -> instances), the
    same routing Study Root applies - PS3.4 Table C.6-4 defines the Composite
    Object Instance level for both models.
    """
    level = (
        str(getattr(event.identifier, "QueryRetrieveLevel", "") or "").strip().upper()
    )
    if level == "SERIES":
        yield from _handle_series_search(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
        return
    if level == "IMAGE":
        yield from _handle_image_search(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
        return
    if level == "PATIENT":
        yield from _handle_patient_level(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
        return
    if level not in ("", "STUDY"):
        # R5: an unrecognised level has no study-level equivalent. Falling
        # through relabelled study rows with that level and no SOPInstanceUID,
        # which the SCU cannot use - and the server drops a return key it
        # cannot honour, so the rows looked plausible. PS3.4 C.4.1.3.1 / PS3.7:
        # the honest answer is Error: Data Set does not match SOP Class.
        yield 0xA900, None
        return
    yield from _handle_qido_search(
        event,
        clarus_url,
        verbose,
        max_responses,
        http_timeout,
        {},
        "study",
        tls=tls,
        expose_rejected=expose_rejected,
        qa_url=qa_url,
    )

def _handle_study_root(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """C-FIND Study Root -> QIDO-RS.

    STUDY level (or level absent): GET /studies - unchanged.
    SERIES level (31.08, MicroDicom series search): two-step search
    (study -> per-study series), see _handle_series_search.
    IMAGE level: three-step search (study -> series -> instances), see
    _handle_image_search. PS3.4 C.6.2.1.4 assigns the Study Root the same
    Composite Object Instance level as the Patient Root.
    """
    level = (
        str(getattr(event.identifier, "QueryRetrieveLevel", "") or "").strip().upper()
    )
    if level == "SERIES":
        yield from _handle_series_search(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
        return
    if level == "IMAGE":
        yield from _handle_image_search(
            event,
            clarus_url,
            verbose,
            max_responses,
            http_timeout,
            tls,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
        return
    if level not in ("", "STUDY"):
        # R5: see _handle_patient_root - an unrecognised level has no
        # study-row equivalent.
        yield 0xA900, None
        return
    yield from _handle_qido_search(
        event,
        clarus_url,
        verbose,
        max_responses,
        http_timeout,
        {},
        "study",
        tls=tls,
        expose_rejected=expose_rejected,
        qa_url=qa_url,
    )

def _handle_series_search(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """Study Root C-FIND at SERIES level: two-step QIDO search (31.08).

    Step a: GET /studies with the study-level keys -> study rows (identity:
    StudyInstanceUID + PatientName/PatientID for enrichment).
    Step b: per study, GET /studies/{study}/series with the series-level
    keys (+ Modality) -> series rows.

    Rows from all studies merge into ONE 0xFF00 stream; max_responses
    applies to the TOTAL (0xB001 truncation preserved). An empty step (a)
    yields an empty result (0x0000), not an error.
    """
    ds = event.identifier
    request_keywords = _extract_request_keywords(ds)
    logging.info(
        "[C-FIND] series keywords: %s",
        ", ".join(sorted(request_keywords)) if request_keywords else "(none)",
    )
    study_params, series_params = _split_qido_params(ds)
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    # One row beyond the limit keeps the local truncation guard reachable
    # (PS3.4 Table C.4.1-1: further matches exist).
    qido_limit = max_responses + 1 if max_responses else None

    # ---- step a: studies ----
    #
    # The response budget limits MATCHING DESCENDANTS, not parent rows. A
    # SERIES query with a limit of one used to ask for two studies and then
    # stop, so a match in the third study was never looked at - the limit was
    # silently applied to the level above the one it describes. Parents are
    # therefore paged until the walk finds an extra matching series or runs
    # out of studies.
    studies_url = f"{base}/studies"
    try:
        study_rows = _qido_request(
            studies_url,
            study_params,
            http_timeout,
            limit=None,
            tls=tls,
        )
        if not isinstance(study_rows, (list, QidoPage)):
            study_rows = []
    except httpx.HTTPStatusError as exc:
        # Status class decides the refusal: 4xx is this query's fault
        # (0xC000), 5xx is the server or a proxy failing (0xA700, retryable).
        # R14: 429 is upstream rate-limiting and is transient, so the shared
        # classifier decides rather than a bare `>= 500` threshold.
        logging.warning(
            "[C-FIND] QIDO HTTP %d: %s?%s",
            exc.response.status_code,
            studies_url,
            _masked_query(study_params),
        )
        dimse, _code, _desc = _http_status_to_dimse(exc.response.status_code)
        yield dimse, None
        return
    except QidoMalformedBodyError as exc:
        # R16: an unreadable 2xx body is a transient upstream failure, not an
        # empty result; see the single-study handler above.
        logging.warning("[C-FIND] QIDO malformed response: %s", exc)
        yield 0xA700, None
        return
    except httpx.HTTPError:
        # A broken transport is transient: 0xA700 tells the SCU to retry,
        # while 0xC000 would read as a permanent refusal and lose a query
        # the network happened to interrupt.
        logging.warning("[C-FIND] QIDO error: connection failed")
        yield 0xA700, None
        return

    study_by_uid = {}
    for row in study_rows:
        study_uid = _json_first_value(row, "0020000D")
        if study_uid:
            study_by_uid[study_uid] = row
    # The study step asking for one row more than the caller's limit is how a
    # cap is DETECTED: if that many studies came back, there are more studies
    # than this search can walk. Their series were never fetched, so the answer
    # is already incomplete before step (b) produces a single row - and a
    # transfer that reported 0x0000 ("complete, no matches") while matches sit
    # beyond the cap tells the SCU the study set is empty when it is not.
    study_cap_hit = qido_limit is not None and len(study_rows) >= qido_limit
    # An origin can leave the study set unfinished on its own (`more`), e.g.
    # when its configured page is smaller than this walk asked for. The rows
    # beyond that page are unknown, so the answer cannot be called complete.
    origin_more = isinstance(study_rows, QidoPage) and study_rows.more
    if not study_by_uid:
        # Empty step (a) -> empty result, per the prompt.
        yield 0x0000, None
        return

    # ---- step b: per-study series ----
    count = 0
    # PS3.4 Table C.4.1-1: 0xB001 states that FURTHER MATCHES EXIST. Reaching the
    # response cap alone does not prove that - the studies not yet walked may
    # contain no matching series at all. So the walk keeps going after the cap
    # until it either finds one extra matching descendant (then it really can
    # say "more matches exist") or runs out of parents.
    extra_match = False
    for study_uid, study_row in study_by_uid.items():
        # A C-CANCEL from the SCU, or a bridge shutdown, must stop a broad
        # SERIES walk: each iteration can block for http_timeout and the walk
        # otherwise has no way out. Mirror the metric bookkeeping the terminal
        # paths do: count the rows already sent before the non-Pending yield
        # (nothing after a non-Pending status is ever executed).
        if getattr(event, "is_cancelled", False):
            find_responses.labels(type="series").inc(count)
            yield 0xFE00, None
            return
        if _shutdown_requested.is_set():
            find_responses.labels(type="series").inc(count)
            yield 0xC000, None
            return
        if max_responses and count >= max_responses:
            # Stop EMITTING; keep checking the remaining studies, because only
            # an extra matching descendant makes 0xB001 a true statement. The
            # series loop below sees the spent budget and stops yielding.
            logging.warning(
                "[C-FIND] Response limit reached (%d). Checking for further "
                "matches.",
                max_responses,
            )
        series_url = f"{base}/studies/{quote(study_uid, safe='')}/series"
        try:
            series_rows = _qido_request(
                series_url,
                dict(series_params),
                http_timeout,
                limit=qido_limit,
                tls=tls,
            )
            if not isinstance(series_rows, (list, QidoPage)):
                series_rows = []
        except httpx.HTTPStatusError as exc:
            # Status class decides the refusal: 4xx is this query's fault
            # (0xC000), 5xx is the server or a proxy failing (0xA700).
            # R14: 429 is transient and the shared classifier already says so.
            logging.warning(
                "[C-FIND] QIDO HTTP %d: %s?%s",
                exc.response.status_code,
                series_url,
                _masked_query(series_params),
            )
            dimse, _code, _desc = _http_status_to_dimse(exc.response.status_code)
            yield dimse, None
            return
        except QidoMalformedBodyError as exc:
            # R16: same class as the single-study handler - an unreadable 2xx
            # body is a transient upstream failure, not an empty result.
            logging.warning("[C-FIND] QIDO malformed response: %s", exc)
            yield 0xA700, None
            return
        except httpx.HTTPError:
            # Same class as step (a): a transport break is retryable.
            logging.warning("[C-FIND] QIDO error: connection failed")
            yield 0xA700, None
            return
        for row in series_rows:
            # Same rule as the common loop: a cancel that arrived during the
            # HTTP call must stop the OUTPUT, not wait for the next study.
            if getattr(event, "is_cancelled", False):
                find_responses.labels(type="series").inc(count)
                yield 0xFE00, None
                return
            if _shutdown_requested.is_set():
                find_responses.labels(type="series").inc(count)
                yield 0xC000, None
                return
            if max_responses and count >= max_responses:
                # Same rule as the parent loop: one more matching series is
                # enough to justify 0xB001, and nothing else is.
                extra_match = True
                break
            row_ds = _json_to_dataset_series(
                row,
                request_keywords,
                study_row,
            )
            _stamp_cfind_response(event, row_ds)
            yield 0xFF00, row_ds
            count += 1
        if extra_match:
            break

    # Counted before the terminal yield for the same reason as the study
    # handler: nothing after a non-Pending status is ever executed.
    find_responses.labels(type="series").inc(count)
    if getattr(event, "is_cancelled", False):
        yield 0xFE00, None
        return
    # 0xB001 is not a defined Query/Retrieve status (PS3.4 Table C.4.1-1), so
    # an answer the bridge could not complete is the defined refusal 0xA700.
    #
    # An origin-imposed page limit counts: the origin answered paged rows and
    # said `more`, so the studies beyond it were never walked even though the
    # bridge's own cap was never reached (PS3.18 10.6.1.4).
    if extra_match or study_cap_hit or origin_more:
        yield 0xA700, None
    else:
        yield 0x0000, None

def _image_qido_error(url, params, exc):
    """Log and classify one failed hop of an IMAGE-level walk.

    Shared by the three steps so each of them refuses for the same reason the
    study/series handlers do (PS3.18 10.6; the status class decides): 4xx is
    this query's fault (0xC000), 5xx and 429 are transient upstream conditions
    the SCU should retry (0xA700), and a broken transport is transient too.
    Returns the DIMSE status to yield.
    """
    if isinstance(exc, httpx.HTTPStatusError):
        # R14: 429 is upstream rate-limiting and is transient, so the shared
        # classifier decides rather than a bare `>= 500` threshold.
        logging.warning(
            "[C-FIND] QIDO HTTP %d: %s?%s",
            exc.response.status_code,
            url,
            _masked_query(params),
        )
        dimse, _code, _desc = _http_status_to_dimse(exc.response.status_code)
        return dimse
    if isinstance(exc, QidoMalformedBodyError):
        # R16: an unreadable 2xx body is a transient upstream failure, not an
        # empty result.
        logging.warning("[C-FIND] QIDO malformed response: %s", exc)
        return 0xA700
    # Transport errors only (ReadError / ConnectError / Timeout): transient,
    # so 0xA700 rather than a 0xC000 that reads as a permanent refusal.
    logging.warning("[C-FIND] QIDO error: connection failed")
    return 0xA700

def _handle_image_search(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout=30,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """C-FIND at COMPOSITE OBJECT INSTANCE (IMAGE) level: three-step QIDO walk.

    PS3.4 C.4.1.3.1.1 (Hierarchical Search Method): start at the top level and
    match down until the level named by QueryRetrieveLevel is reached, so the
    walk is study -> series -> instances of the requested series, each hop
    carrying that level's own matching keys (`_split_instance_qido_params`).
    PS3.4 Table C.6-4 / C.6.2.1.4 (standard/ps3.4/image-level-C.6-4.json)
    defines the same instance level for both Query/Retrieve models.

    A row without SOPInstanceUID is dropped rather than yielded: that was the
    defect 0xA900 used to paper over - study rows relabelled as IMAGE look
    plausible to the SCU but cannot be retrieved. Every row that does go out
    carries QueryRetrieveLevel=IMAGE (C.4.1.1.3.2), the Unique Keys of the
    levels above and the instance's own SOP Instance UID.

    This is the baseline hierarchical search, not the relational extension
    (C.4.1.2.2.1): every study comes back from step (a) because a baseline
    request may omit the study Unique Key, and every series of a matched
    study is walked. A SeriesInstanceUID in the identifier narrows step (b) to
    that one series, so the common "instances of one series" query is three
    requests. Rows merge into ONE 0xFF00 stream and max_responses applies to
    the TOTAL, with 0xB001 when the cap cuts matches off.
    """
    ds = event.identifier
    request_keywords = _extract_request_keywords(ds)
    logging.info(
        "[C-FIND] image keywords: %s",
        ", ".join(sorted(request_keywords)) if request_keywords else "(none)",
    )
    study_params, series_params, instance_params = _split_instance_qido_params(ds)
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    # One row beyond the limit keeps the local truncation guard reachable
    # (PS3.4 Table C.4.1-1: B001 means further matches exist).
    qido_limit = max_responses + 1 if max_responses else None

    # ---- step a: studies ----
    studies_url = f"{base}/studies"
    try:
        study_rows = _qido_request(
            studies_url, study_params, http_timeout, limit=None, tls=tls
        )
        if not isinstance(study_rows, (list, QidoPage)):
            study_rows = []
    except (httpx.HTTPError, QidoMalformedBodyError) as exc:
        yield _image_qido_error(studies_url, study_params, exc), None
        return

    study_by_uid = {}
    for row in study_rows:
        study_uid = _json_first_value(row, "0020000D")
        if study_uid:
            study_by_uid[study_uid] = row
    # Same cap detection as the series walk: one row more than the caller's
    # limit means studies were never walked, so the answer is already
    # incomplete and 0x0000 would claim otherwise.
    study_cap_hit = qido_limit is not None and len(study_rows) >= qido_limit
    # Same rule as the series walk: an origin-imposed page limit on the study
    # hop leaves studies unvisited, so the answer is incomplete even though
    # this walk never reached its own cap.
    origin_more = isinstance(study_rows, QidoPage) and study_rows.more
    if not study_by_uid:
        yield 0x0000, None
        return

    count = 0
    truncated = False
    # Same rule as the SERIES walk (PS3.4 Table C.4.1-1): the cap alone does not
    # prove another match exists, so the walk keeps checking parents until it
    # finds one. `extra_match` is what justifies reporting an incomplete answer.
    extra_match = False
    # Set when an ORIGIN page limit (not this bridge's cap) left rows unseen.
    origin_more = False
    for study_uid, study_row in study_by_uid.items():
        # A C-CANCEL or a shutdown must stop the walk: each iteration can
        # block for http_timeout. Mirror the series walk's metric bookkeeping
        # (nothing after a non-Pending yield is ever executed).
        if getattr(event, "is_cancelled", False):
            find_responses.labels(type="image").inc(count)
            yield 0xFE00, None
            return
        if _shutdown_requested.is_set():
            find_responses.labels(type="image").inc(count)
            yield 0xC000, None
            return
        if max_responses and count >= max_responses and not truncated:
            # Emitting stops; the check for a further match does not.
            truncated = True
            logging.warning(
                "[C-FIND] Response limit reached (%d). Checking for further "
                "matches.",
                max_responses,
            )

        # ---- step b: series of this study ----
        series_url = f"{base}/studies/{quote(study_uid, safe='')}/series"
        try:
            series_rows = _qido_request(
                series_url, dict(series_params), http_timeout, limit=qido_limit, tls=tls
            )
            if not isinstance(series_rows, (list, QidoPage)):
                series_rows = []
        except (httpx.HTTPError, QidoMalformedBodyError) as exc:
            yield _image_qido_error(series_url, series_params, exc), None
            return

        for series_row in series_rows:
            series_uid = _json_first_value(series_row, "0020000E")
            # An unnamed series cannot be walked: the instance route is keyed
            # by it, and a row without it carries no Unique Key of its level.
            if not series_uid:
                continue
            # A cancel can arrive while the previous series was being read.
            if getattr(event, "is_cancelled", False):
                find_responses.labels(type="image").inc(count)
                yield 0xFE00, None
                return
            if max_responses and count >= max_responses:
                # A series not yet walked is a candidate for a further match,
                # but it is only a MATCH once an instance inside it matches.
                # Fetch it and let the instance loop decide.
                truncated = True
            # ---- step c: instances of this series ----
            #
            # A shutdown that began during the series request must stop the
            # walk HERE, before another instance request goes out. Only the
            # outermost study loop used to check the flag, so a shutdown could
            # still emit rows and issue instance requests for the same study.
            if _shutdown_requested.is_set():
                find_responses.labels(type="image").inc(count)
                yield 0xC000, None
                return
            instances_url = (
                f"{base}/studies/{quote(study_uid, safe='')}"
                f"/series/{quote(series_uid, safe='')}/instances"
            )
            try:
                instance_rows = _qido_request(
                    instances_url,
                    dict(instance_params),
                    http_timeout,
                    limit=qido_limit,
                    tls=tls,
                )
                if not isinstance(instance_rows, (list, QidoPage)):
                    instance_rows = []
            except (httpx.HTTPError, QidoMalformedBodyError) as exc:
                yield _image_qido_error(instances_url, instance_params, exc), None
                return
            # Shutdown or cancel that arrived DURING the instance request: the
            # rows it returned must not be emitted, and no further request may
            # go out for this study.
            if _shutdown_requested.is_set():
                find_responses.labels(type="image").inc(count)
                yield 0xC000, None
                return
            if isinstance(instance_rows, QidoPage) and instance_rows.more:
                # The origin answered only its own page of instances and said
                # so. Treating that as a complete answer tells the SCU the
                # search found everything, when rows beyond the page were
                # never even offered.
                origin_more = True
            for row in instance_rows:
                if not _json_first_value(row, "00080018"):
                    # PS3.4 C.6.1.1.5: SOP Instance UID is the level's Unique
                    # key. Without it the row is not an instance match at all.
                    logging.warning(
                        "[C-FIND] instance row without SOPInstanceUID dropped"
                    )
                    continue
                # A cancel during the instance read must stop the output.
                if getattr(event, "is_cancelled", False):
                    find_responses.labels(type="image").inc(count)
                    yield 0xFE00, None
                    return
                if max_responses and count >= max_responses:
                    # THIS is a matching descendant the bridge will not send: it
                    # is the fact 0xB001 asserts.
                    extra_match = True
                    break
                row_ds = _json_to_dataset_instance(
                    row,
                    request_keywords,
                    study_uid,
                    series_uid,
                    study_row,
                    series_row,
                )
                _stamp_cfind_response(event, row_ds)
                yield 0xFF00, row_ds
                count += 1
            if extra_match:
                break
        if extra_match:
            break

    # Counted before the terminal yield for the same reason as the study
    # handler: nothing after a non-Pending status is ever executed.
    find_responses.labels(type="image").inc(count)
    if getattr(event, "is_cancelled", False):
        yield 0xFE00, None
        return
    # Same rule as the series walk: 0xB001 is undefined for Query/Retrieve, so
    # an incomplete answer is 0xA700, and an origin-imposed page limit on any
    # hop means rows beyond it were never walked.
    if extra_match or study_cap_hit or origin_more:
        yield 0xA700, None
    else:
        yield 0x0000, None

def _mwl_row_in_time_window(row, bounds):
    """Whether a workitem row's start instant lies inside the requested window.

    Reads the workitem's Combined Scheduled Procedure Step Start DateTime
    (0040,4005) and compares the DATE AND TIME together: PS3.4 Table K.6-1
    defines (0040,0002) and (0040,0003) as one interval, so a July 6 workitem
    at 22:00 belongs to "July 5-7 at 10:00-18:00" (see
    `_mwl_start_datetime_bounds`). A row without the attribute is kept:
    absence is not a proven mismatch, and dropping it would hide a workitem
    the modality may still want.
    """
    stamp = _json_first_value(row, "00404005")
    if not stamp:
        return True
    return _mwl_datetime_in_bounds(stamp, bounds)

def _handle_mwl(event, clarus_url, verbose, max_responses, http_timeout=30, tls=None):
    """C-FIND MWL -> UPS-RS workitems (Stage 3: real MWL key mapping).

    Query: maps the modality's MWL matching keys to the workitem query params
    the server filters on (station_aet, modality, patient_id, workitem_uid,
    workflow_state). Response: converts the workitem DICOMweb JSON back to MWL
    attributes (scheduled procedure step + patient) so the modality sees a
    complete worklist entry.
    """
    params = _build_mwl_params(event.identifier)
    # PS3.4 Table K.6-1 makes Scheduled Procedure Step Start Date (0040,0002)
    # and Start Time (0040,0003) a SINGLE interval: July 5-7 at 10:00-18:00
    # includes a July 6 workitem at 22:00. UPS-RS has no parameter for a time
    # of day - the origin filters the combined workitem start instant - so the
    # window is applied HERE, before the response limit, with the date and
    # time bounds combined rather than as two independent filters.
    time_bounds = _mwl_start_datetime_bounds(event.identifier)
    # PS3.4 Table K.6-1 also makes Scheduled Performing Physician's Name
    # (0040,0006) a matching key with "Single Value or Wildcard", and the
    # UPS-RS workitem search has no parameter for it - so it is applied
    # locally over the candidate rows, exactly like the time window.
    physician_matchers = _mwl_physician_matchers(event.identifier)
    yield from _mwl_search(
        event,
        clarus_url,
        verbose,
        max_responses,
        http_timeout,
        params,
        time_bounds,
        tls=tls,
        physician_matchers=physician_matchers,
    )

# Candidate page size for the MWL walk, in units of `max_responses`. Two
# pages' worth is the smallest window that can prove "no more matches": the
# walk stops as soon as it has one row beyond the cap, and a page that the
# local filter rejects in full has to be followed by another.
_MWL_PAGE_FACTOR = 4

def _mwl_search(
    event,
    clarus_url,
    verbose,
    max_responses,
    http_timeout,
    params,
    time_bounds,
    tls=None,
    physician_matchers=(),
):
    """MWL search whose response limit counts MATCHING rows, not candidates.

    PS3.4 Table K.6-1 puts the matching rule on the worklist row, but the
    date/time window can only be applied locally (UPS-RS has no time-of-day
    parameter), so the origin's rows are CANDIDATES. Asking for exactly
    `max_responses + 1` candidates and filtering afterwards cannot recover a
    matching row the bridge never fetched: with a limit of one, two in-window
    candidates that fall outside the window hide a third that matches.

    So the walk pages the origin while it has room for another match, and
    stops only when it finds one extra matching row (proving more exist) or
    the origin runs out. That is the same rule the SERIES and IMAGE walks use
    for their parent hops.
    """
    base = service_base_url(clarus_url, "", False)
    url = f"{base}/workitems"
    want = max_responses or 0
    page = max(1, want * _MWL_PAGE_FACTOR) if want else None
    offset = 0
    count = 0
    # One matching row beyond the cap is the evidence that further matches
    # exist; without it the answer is complete and reports Success.
    extra_match = False
    seen_offsets = set()

    while True:
        if getattr(event, "is_cancelled", False):
            find_responses.labels(type="mwl").inc(count)
            yield 0xFE00, None
            return
        if _shutdown_requested.is_set():
            find_responses.labels(type="mwl").inc(count)
            yield 0xC000, None
            return
        page_params = dict(params)
        try:
            results = _qido_request(
                url,
                page_params,
                http_timeout,
                limit=page,
                offset=offset,
                tls=tls,
            )
            if not isinstance(results, (list, QidoPage)):
                results = []
        except (httpx.HTTPError, QidoMalformedBodyError) as exc:
            yield _image_qido_error(url, params, exc), None
            return

        for row in results:
            # A cancel can arrive while the origin is answering.
            if getattr(event, "is_cancelled", False):
                find_responses.labels(type="mwl").inc(count)
                yield 0xFE00, None
                return
            if time_bounds is not None and not _mwl_row_in_time_window(
                row, time_bounds
            ):
                continue
            if not _mwl_physician_matches(
                _json_first_value(row, "00400006"), physician_matchers
            ):
                continue
            if want and count >= want:
                # A MATCHING row the bridge will not send: this is the fact
                # that makes the answer incomplete.
                extra_match = True
                break
            row_ds = _json_to_dataset_mwl(
                row, _extract_mwl_request_keywords(event.identifier)
            )
            yield 0xFF00, row_ds
            count += 1
        if extra_match:
            break

        if page is None:
            # No cap: the single unpaged answer was the whole result.
            break
        if len(results) < page:
            # The origin had nothing left to give: the answer is complete.
            break
        origin_more = isinstance(results, QidoPage) and results.more
        offset += page
        if offset in seen_offsets:
            # A page that does not advance would loop forever.
            break
        seen_offsets.add(offset)
        if origin_more and offset == page:
            # The origin flagged the first page as unfinished but still
            # returned a full page: keep walking rather than trust the flag
            # alone. Any later page that is short ends the loop above.
            continue

    find_responses.labels(type="mwl").inc(count)
    if getattr(event, "is_cancelled", False):
        yield 0xFE00, None
        return
    # 0xA700 is the defined refusal for an answer the bridge could not
    # complete; 0xB001 is not defined for MWL (PS3.4 Table K.4-1).
    if extra_match:
        yield 0xA700, None
    else:
        yield 0x0000, None

# ---------------------------------------------------------------------------
# Bridge: handlers/cstore
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  C-STORE and C-ECHO handlers.

handle_c_store: C-STORE -> STOW-RS forwarding with size validation,
cp1251 charset fix, and SOP indexing.
handle_c_echo: Verification.
"""

import logging
import os
import struct
import threading
import time

from pydicom.datadict import keyword_dict, keyword_for_tag
from pydicom.dataset import Dataset
from pydicom.multival import MultiValue
from pydicom.tag import BaseTag, Tag

# ---------------------------------------------------------------------------
# Backpressure: limit concurrent C-STORE handlers (like nginx worker_connections)
# ---------------------------------------------------------------------------
# Prevents pynetdicom thread pool exhaustion under extreme load.
# When all slots are busy, new associations get DIMSE 0xA700 (Out of Resources)
#  -  modalities are REQUIRED by DICOM standard to retry.
# Default: max(4, cpu_count). Configurable via [advanced] max_concurrent_cstore.
_MAX_CONCURRENT_CSTORE = max(4, (os.cpu_count() or 2))
_cstore_semaphore = threading.Semaphore(_MAX_CONCURRENT_CSTORE)

def set_max_concurrent_cstore(n: int) -> None:
    """Set max concurrent C-STORE handlers (called from config parsing)."""
    global _MAX_CONCURRENT_CSTORE, _cstore_semaphore
    _MAX_CONCURRENT_CSTORE = n
    _cstore_semaphore = threading.Semaphore(n)

# ---------------------------------------------------------------------------
# Study -> PatientID guard (C-STORE, synchronous)
# ---------------------------------------------------------------------------
# The outbox is fire-and-forget: C-STORE answers 0x0000 right after enqueue,
# before the STOW verdict exists, so the server's patient-conflict refusal
# (409 -> 0xC000) never reaches the modality. The bridge must therefore refuse
# a study it already holds under a DIFFERENT non-empty PatientID,
# synchronously, BEFORE the enqueue. The map is bounded (eviction of the
# oldest entry on overflow): an unbounded dict would grow one entry per
# StudyInstanceUID for the process lifetime - a memory DoS on a long-running
# forwarder.
_STUDY_PATIENT_CAP = 1_000_000
_study_patient_lock = threading.Lock()
_study_patient_map = {}  # study_uid -> patient_id (insertion-ordered)

def _study_patient_get(study_uid):
    """Return the PatientID this bridge holds for a study, or None."""
    with _study_patient_lock:
        return _study_patient_map.get(study_uid)

def _study_patient_put(study_uid, patient_id):
    """Record a study's PatientID after a SUCCESSFUL enqueue.

    Insertion order makes the first key the oldest; on overflow the oldest is
    evicted. The map is a guard cache, not an archive - an evicted study is
    simply no longer guarded, which is the honest degradation of a bound.
    """
    with _study_patient_lock:
        if study_uid in _study_patient_map:
            _study_patient_map[study_uid] = patient_id
            return
        if len(_study_patient_map) >= _STUDY_PATIENT_CAP:
            # dict preserves insertion order, so the first key is the oldest;
            # plain dict.popitem() removes the NEWEST (LIFO), which is wrong
            # for an eviction-by-age bound.
            _study_patient_map.pop(next(iter(_study_patient_map)))
        _study_patient_map[study_uid] = patient_id

# ---------------------------------------------------------------------------
# PROD-HARDENING: Unified backpressure  -  single function for outbox
# ---------------------------------------------------------------------------
def _check_backpressure(pending, max_queue, pending_bytes=0, max_queue_bytes=0):
    """Unified adaptive backpressure with hysteresis.

    Returns DIMSE status:
      <70%  -> 0x0000  (Success, no delay)
      70-90% -> 0x0000 (rate-limit, linear 0-200ms)
      90-95% -> 0xA700  (Out of Resources)
      >=95%  -> 0xC000  (Cannot Perform)

    Args:
        pending: Current queue depth (integer count).
        max_queue: Maximum queue capacity (integer count).
        pending_bytes: Bytes currently held by the queue (0 = not measured).
        max_queue_bytes: Byte budget (0 = no byte limit).

    The fill ratio is the WORSE of the slot ratio and the byte ratio. Slots
    alone let `advanced.stow_queue_max_mb` be a documented knob that nothing
    read: 20000 slots of 0.5-50 MB is up to 10 GB against a configured 500 MB
    budget, and a queue that is 2% full by count can be far past its memory
    budget.
    """
    max_q = max_queue if max_queue > 0 else 5000
    ratio = pending / max_q if max_q > 0 else 0.0
    if max_queue_bytes > 0 and pending_bytes > 0:
        ratio = max(ratio, pending_bytes / max_queue_bytes)

    if ratio >= 0.95:
        logging.critical(
            "[BACKPRESSURE] Queue at %d/%d (%.0f%%) - CRITICAL, returning 0xC000",
            pending,
            max_q,
            ratio * 100,
        )
        return 0xC000  # Cannot Perform
    elif ratio >= 0.90:
        logging.error(
            "[BACKPRESSURE] Queue at %d/%d (%.0f%%) - returning 0xA700",
            pending,
            max_q,
            ratio * 100,
        )
        return 0xA700  # Out of Resources
    elif ratio >= 0.70:
        # Soft rate-limit: linear delay 0-200ms between 70% and 90%
        delay = 0.2 * (ratio - 0.70) / (0.90 - 0.70)
        time.sleep(delay)
        logging.warning(
            "[BACKPRESSURE] Queue at %d/%d (%.0f%%) - rate-limit delay %.0fms",
            pending,
            max_q,
            ratio * 100,
            delay * 1000,
        )
    # <70%  -  no delay, no reject

    return 0x0000  # Success

# ---------------------------------------------------------------------------
# Unified pre-stow admission gate
# ---------------------------------------------------------------------------
class _AdmissionController:
    """Single admission decision for C-STORE (health + backpressure).

    Replaces the two independent checks (health_checker + _check_backpressure)
    with one pre-flight gate. Priorities:
      1. Server dead >= 30s  -> PARK (0x0000) when store_forward=on, else 0xC000.
      2. degraded  (< 30s)   -> 0xA700 (both modes; hysteresis)
      3. backpressure        -> 0xC000 (>=95%) / 0xA700 (90-95%) /
                                rate-limit (70-90%), else 0x0000.
         (>=95% disk limit overrides parking ALWAYS.)

    store_forward: on -> a dead>=30s C-STORE is parked (0x0000; blob already
    atomically on disk before ACK), off -> 0xC000 (Cannot Perform, not transient).

    One place decides "can we take a new C-STORE". Mode
    (never/probe-disabled) handling is preserved via HealthChecker.
    """

    DEAD_SECONDS_FATAL = 30.0

    def __init__(self, outbox=None, health_checker=None, store_forward=False):
        self._outbox = outbox
        self._health = health_checker
        self._store_forward = store_forward

    def check(self):
        """Return (dimse_status, reason). 0x0000 = admit."""
        if self._health is not None:
            healthy, status, reason = self._health.check_before_stow()
            if not healthy:
                dead = self._health.dead_seconds()
                if dead >= self.DEAD_SECONDS_FATAL:
                    if self._store_forward:
                        logging.warning(
                            "[ADMISSION] Server dead %.0fs, store_forward=on "
                            "- parked (0x0000; blob on disk)",
                            dead,
                        )
                        # Parking: accept; backpressure below may still reject.
                    else:
                        logging.error(
                            "[ADMISSION] Server dead for %.0fs -> 0xC000 "
                            "(Cannot Perform)",
                            dead,
                        )
                        return 0xC000, reason or "server dead"
                else:
                    logging.warning(
                        "[ADMISSION] Server degraded for %.0fs -> 0xA700",
                        dead,
                    )
                    return status, reason or "server degraded"

        if self._outbox is not None:
            # The byte budget is optional: a queue that cannot report its
            # pending bytes (or has no budget configured) is judged on slots
            # alone, exactly as before.
            _pending_bytes = 0
            try:
                if getattr(self._outbox, "max_queue_bytes", 0):
                    _pending_bytes = self._outbox.pending_bytes()
            except Exception:
                _pending_bytes = 0
            bp = _check_backpressure(
                self._outbox.pending_count(),
                self._outbox.max_queue,
                pending_bytes=_pending_bytes,
                max_queue_bytes=getattr(self._outbox, "max_queue_bytes", 0),
            )
            if bp != 0x0000:
                return bp, "queue backpressure"

        return 0x0000, ""

# ---------------------------------------------------------------------------
# Bridge: cp1251 mojibake fixer for old Russian X-ray machines
# ---------------------------------------------------------------------------

# Module-level Cyrillic character set for mojibake detection (DRY-001).
# Defined once at import time, not re-created per C-STORE call.
# Using frozenset  -  immutable + hashable, no runtime cost on each call.
_CYRILLIC_BLOCK = frozenset(
    "АБВГДЕЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ" "абвгдежзийклмнопрстуфхцчшщъыьэюяё№"
)

def _fix_cp1251_krakozyabry(ds):
    """Detect and fix cp1251 mojibake in DICOM text fields.

    Problem: Old Russian X-ray machines encode PatientName/StudyDescription
    in Windows-1251 (cp1251) but either omit SpecificCharacterSet (0008,0005)
    or set it to ISO_IR 100 (Latin-1). pydicom then decodes the bytes as
    Latin-1, producing garbled text like "ÐŸÐµÑ‚Ñ€Ð¾Ð²" instead of "Петров".

    This function reverses the incorrect Latin-1 -> bytes step and re-decodes
    as cp1251. If the field was already valid UTF-8, it is left untouched.

    Strategy:
    1. Check if SpecificCharacterSet is missing or ISO_IR 100.
    2. For each target field: encode back to Latin-1 bytes -> decode as cp1251.
    3. If the result differs from original -> replace.
    4. Set SpecificCharacterSet to ISO_IR 192 (UTF-8) for Clarus Server.
    """
    charset = getattr(ds, "SpecificCharacterSet", None)
    if charset is not None:
        cs = str(charset).strip()
        if cs and cs not in ("", "ISO_IR 100", "ISO 2022 IR 100"):
            charset_conversions.labels(from_encoding="utf8").inc()
            return ds

    # Every TEXT-valued element is a candidate, not just five named fields.
    # Setting ISO_IR 192 for the whole dataset while repairing only PatientName
    # and friends relabelled the remaining cp1251 bytes (ReferringPhysicianName,
    # PerformingPhysicianName, OperatorsName, comments, ...) as UTF-8, which
    # turns readable Cyrillic into replacement characters downstream. The walk
    # below visits all of them (PS3.5 Table 6.2-1 text VRs).
    _TEXT_VRS = frozenset({"PN", "LO", "SH", "ST", "LT", "UT", "UC", "DA", "TM"})

    fields_to_fix = [
        "PatientName",
        "PatientID",
        "InstitutionName",
        "StudyDescription",
        "SeriesDescription",
    ]

    # fix v2: heuristic to distinguish cp1251 mojibake from valid Latin-1.

    def _has_cyrillic_run(text, min_run=3):
        """Return True if text contains >=min_run consecutive Cyrillic chars."""
        run = 0
        for ch in text:
            if ch in _CYRILLIC_BLOCK:
                run += 1
                if run >= min_run:
                    return True
            else:
                run = 0
        return False

    def _cyrillic_dominates(text):
        """Whether the Cyrillic content is the body of the value, not an island.

        A genuine cp1251 mojibake is Cyrillic throughout, because the whole
        value was Russian text. Text that merely CONTAINS a Cyrillic run - a
        Latin-1 value whose box-drawing bytes happen to decode into letters -
        keeps most of its Latin letters and spaces, so the Cyrillic share is
        small. Half is the threshold: it separates "this value IS Cyrillic"
        from "this value mentions something Cyrillic", and it is loose enough
        that a mixed value such as `Иванов Ivanov` still repairs.

        Whitespace, digits and punctuation are not counted either way, so a
        short Cyrillic surname inside a long ASCII description does not pass on
        the strength of the description's own length.
        """
        letters = 0
        cyrillic = 0
        for ch in text:
            if ch in _CYRILLIC_BLOCK:
                cyrillic += 1
                letters += 1
            elif ch.isalpha():
                letters += 1
        if letters == 0:
            return False
        return cyrillic * 2 >= letters

    def _cp1251_fix_one(value):
        """Repair one text value. Returns (new_value, examined).

        `examined` is False when the value could not be tested at all; the
        caller then keeps the dataset's original charset, because relabelling
        UTF-8 over a field nobody checked is exactly the mislabel this repair
        must not create.
        """
        try:
            raw_bytes = str(value).encode("latin-1")
        except (UnicodeEncodeError, UnicodeDecodeError):
            # Not representable byte-for-byte, so it was never cp1251-as-
            # latin-1; it is already something else and is left alone.
            malformed_tags.inc()
            return value, False
        except Exception:
            malformed_tags.inc()
            return value, False

        # R6: a value whose Latin-1 bytes decode STRICTLY as UTF-8 is text
        # that reached us through a missing SpecificCharacterSet: pydicom
        # read the UTF-8 bytes as Latin-1, so `str(value)` looks like
        # mojibake but its byte content is valid UTF-8. Re-decoding those
        # bytes as cp1251 turned "Петров" into permanent garbage and then
        # relabelled the dataset ISO_IR 192. The strict probe runs FIRST and
        # returns on success; only a strict-decode failure falls through to
        # the cp1251 repair (genuine cp1251 Cyrillic is almost never valid
        # UTF-8).
        try:
            return raw_bytes.decode("utf-8"), True
        except UnicodeDecodeError:
            pass

        fixed = raw_bytes.decode("cp1251", errors="replace")

        # A repair needs INDEPENDENT evidence, which is what a Cyrillic run is:
        # three consecutive Cyrillic letters cannot arise by accident from
        # valid Latin-1 text. The former short-name rule ("1-4 characters, all
        # Cyrillic") had no such force - a two-character Latin-1 name decodes
        # into two Cyrillic letters often enough that the bridge rewrote valid
        # ISO_IR 100 text and then relabelled the data set ISO_IR 192 on the
        # strength of it.
        #
        # A Cyrillic run is NECESSARY but not SUFFICIENT. Single-byte Latin-1
        # text built from the box-drawing/box-shade range decodes into a solid
        # Cyrillic run too: `├Й├Й├Й Industries` (a real ISO_IR 100 value) becomes
        # `ЩйЩйЩй Industries` under cp1251, passes the run test, and would have
        # been forwarded as UTF-8 - silently altering declared Latin-1 text that
        # was never mojibake. So the run must also be a MEANINGFUL proportion of
        # the value rather than a token inside otherwise-ordinary Latin text,
        # and the declared charset must not already be trustworthy.
        if fixed != value:
            if not _has_cyrillic_run(fixed, 3):
                return value, True
            if not _cyrillic_dominates(fixed):
                # A Cyrillic island in Latin text: leave the declared Latin-1
                # alone. Rewriting it is the alteration this guard exists to
                # prevent, and a genuinely misencoded Russian name is
                # Cyrillic throughout, not three letters inside a word.
                return value, True
        return fixed, True

    fixed_any = False
    # Set when some text element was NOT examined or its repair was uncertain:
    # the dataset then keeps its original charset instead of being relabelled
    # UTF-8 over a mixture of encodings.
    uncertain = False
    # id(element) -> (element, value BEFORE any repair), so a partial repair can
    # be undone whole (`_repair_dataset` writes into `element.value` as it
    # walks, and the decision to keep the original charset is only made at the
    # top).
    #
    # Keyed by the ELEMENT IDENTITY, not by tag: the SAME tag appears in every
    # item of a sequence (two SR Content Items each carry a TextValue, two
    # nested items each carry a CodeMeaning). Keying by tag kept only the
    # first item's original and then wrote it into EVERY element with that
    # tag on undo - silently replacing one item's clinical text with
    # another's.
    #
    # `id()` rather than the element itself: pydicom's DataElement defines no
    # `__hash__`, so it cannot be a dict key. The element is stored beside its
    # original, which also keeps the object alive for the life of the map.
    _uncertain_replaced = {}

    # Built from the walk so a tag added to the dataset later is not silently
    # missed: the five historical names stay FIRST (their log lines are
    # field-specific), then every other text-valued element.
    #
    # PS3.5 SpecificCharacterSet (0008,0005) applies to the WHOLE data set,
    # including every nested Sequence item: (0040,A730) Content Sequence and
    # any other SQ carries text elements in the same source encoding. Relabelling
    # the top level to ISO_IR 192 while repairing only top-level elements left
    # every nested PN/LO/ST as cp1251 bytes declared UTF-8. The walk therefore
    # descends into sequences (`_top_level=False` below).
    def _repair_dataset(ds_obj, top_level):
        """Repair one dataset level. Returns (fixed_any, uncertain)."""
        fixed_here = False
        uncertain_here = False
        _walk_tags = []
        for elem in ds_obj:
            # A sequence ELEMENT is a DataElement whose VR is 'SQ' and whose
            # .value is the Sequence - it is NOT itself a Sequence instance.
            # Testing `isinstance(elem, Sequence)` therefore never matched, so
            # the descent below never ran and nested text was never repaired.
            if elem.VR == "SQ":
                continue
            if elem.VR in _TEXT_VRS or (top_level and elem.keyword in fields_to_fix):
                _walk_tags.append(elem.tag)
        _ordered_tags = []
        if top_level:
            for field in fields_to_fix:
                tag = keyword_dict.get(field)
                if tag is not None:
                    _ordered_tags.append(Tag(tag))
        for tag in _walk_tags:
            if tag not in _ordered_tags:
                _ordered_tags.append(tag)

        for _tag in _ordered_tags:
            # `keyword_dict` yields a Tag and the walk yields a Tag: normalise
            # once so the dataset lookup and the element access agree on the
            # key. (`pydicom.tag.Tag` is a FACTORY function, so `isinstance`
            # has to test the concrete `BaseTag` class.)
            tag = _tag if isinstance(_tag, BaseTag) else Tag(_tag)
            # The keyword only drives the LOG wording; an unknown/private tag
            # has none and falls into the redacted branch.
            field = keyword_for_tag(tag)
            if tag not in ds_obj:
                continue
            element = ds_obj[tag]
            if element is None:
                continue
            if element.VR not in _TEXT_VRS:
                # A keyword listed above whose VR is not text (PatientID is
                # LO, so this is only reachable for a non-conformant file):
                # leave it and mark the walk partial.
                uncertain_here = True
                continue
            value = element.value
            if isinstance(value, (list, tuple, MultiValue)):
                # A multi-valued text element is repaired value by value; if
                # any component cannot be examined the element is uncertain.
                new_values = []
                for part in value:
                    fixed_part, ok = _cp1251_fix_one(part)
                    if not ok:
                        uncertain_here = True
                    new_values.append(fixed_part)
                    if fixed_part != part:
                        fixed_here = True
                        if id(element) not in _uncertain_replaced:
                            _uncertain_replaced[id(element)] = (element, list(value))
                element.value = new_values
                continue
            if not isinstance(value, (str, bytes)):
                try:
                    value = str(value)
                except Exception:
                    uncertain_here = True
                    continue
            if not value:
                continue
            fixed, ok = _cp1251_fix_one(value)
            if not ok:
                uncertain_here = True
                continue
            if fixed != value:
                if id(element) not in _uncertain_replaced:
                    _uncertain_replaced[id(element)] = (element, value)
                element.value = fixed
                fixed_here = True
                if field == "PatientName":
                    logging.debug(
                        "  [CP1251] Fixed %s: %s -> %s",
                        field,
                        mask_patient_name(str(value)),
                        mask_patient_name(str(fixed)),
                    )
                elif field == "PatientID":
                    # A modality's PatientID is the real identifier, not the
                    # bridge's AUTOPAT_ placeholder: it goes through the keyed
                    # token like every other log line that carries one.
                    logging.debug(
                        "  [CP1251] Fixed %s: %s -> %s",
                        field,
                        mask_patient_id(str(value)),
                        mask_patient_id(str(fixed)),
                    )
                else:
                    # Free text a site fills with names and addresses, and on a
                    # cp1251-fixed instance exactly as identifying as
                    # PatientName. Neither masker applies (not a PN, not a keyed
                    # ID), so the value is NOT logged at all: the tag and the
                    # length are enough to confirm the repair happened.
                    logging.debug(
                        "  [CP1251] Fixed %s: value redacted (%d -> %d chars)",
                        field,
                        len(str(value)),
                        len(str(fixed)),
                    )

        # Descend into every sequence at this level, including sequences
        # nested inside items of other sequences.
        for elem in ds_obj:
            if elem.VR != "SQ":
                continue
            for item in elem.value or []:
                if not isinstance(item, Dataset):
                    # A non-Dataset item cannot carry tagged text elements;
                    # it is not an encoding question, so it is not "uncertain".
                    continue
                sub_fixed, sub_uncertain = _repair_dataset(item, False)
                fixed_here = fixed_here or sub_fixed
                uncertain_here = uncertain_here or sub_uncertain
        return fixed_here, uncertain_here

    fixed_any, uncertain = _repair_dataset(ds, True)
    fixed_any = bool(fixed_any)
    uncertain = bool(uncertain)

    if fixed_any:
        if uncertain:
            # Some text element could not be examined, so the dataset is not
            # uniformly repairable. Relabelling UTF-8 would declare a charset
            # the unexamined element does not honour; but KEEPING the repaired
            # values under the original charset is just as wrong in the other
            # direction - PS3.5 (0008,0005) applies to the whole data set, so a
            # Cyrillic string left under ISO_IR 100 is written out as Latin-1
            # bytes (or raises) and the text is corrupted on the wire. Neither
            # half-label is acceptable, so the whole repair is undone: value
            # and charset stay exactly as received, mutually consistent.
            #
            # The recorded ELEMENTS are restored directly, so each one gets its
            # OWN original back and no walking is needed (nor would a walk
            # help: `ds[tag]` reaches only the top level, and matching by tag
            # is exactly the swap this undo must not make).
            for _element, _orig in list(_uncertain_replaced.values()):
                try:
                    _element.value = _orig
                except Exception:
                    pass
            # Nothing was changed after the undo, so the caller must not treat
            # this instance as repaired (the metric below records the no-op).
            fixed_any = False
            logging.warning(
                "  [CP1251] Repaired text elements but could not examine every "
                "text value - reverting the repair so the charset and the "
                "bytes stay consistent",
            )
            charset_conversions.labels(from_encoding="latin1").inc()
        else:
            ds.SpecificCharacterSet = "ISO_IR 192"
            charset_conversions.labels(from_encoding="cp1251").inc()
            logging.info(
                "  [CP1251] Detected and fixed cp1251 mojibake in %s",
                mask_patient_name(str(ds.get("PatientName", "unknown"))),
            )
    else:
        charset_conversions.labels(from_encoding="latin1").inc()

    return ds

# ---------------------------------------------------------------------------
# Bridge: C-STORE handler with size limit
# ---------------------------------------------------------------------------
def handle_c_store(
    event,
    clarus_url,
    verbose,
    sop_index=None,
    max_store_bytes=0,
    http_timeout=30,
    sop_registry=None,
    outbox=None,
    health_checker=None,
    store_forward=False,
    fix_empty_patient_id=True,
    fix_empty_patient_name=True,
    bridge_id_prefix="AUTOPAT_",
    bridge_name_prefix="Anonymous^",
    tls=None,
    forward_outbox=None,
    bridge_ae_title="CLBRIDGE",
):
    """Handle C-STORE: validate, enqueue to OutboxQueue, return immediately.

    OutboxQueue guarantees eventual delivery. C-STORE returns 0x0000 Success
    as soon as the SOP is persisted in SQLite  -  the modality is free immediately.
    Background outbox workers drain the queue via STOW-RS.

    Args:
        outbox: OutboxQueue instance (required for reliable persistence).
                Falls back to sync STOW-RS if None (demo/testing mode).
        store_forward: when on, a dead>=30s server parks the C-STORE
                (0x0000) instead of 0xC000.
    """
    # Bridge: reject new requests during shutdown
    if _shutdown_requested.is_set():
        return 0xC000  # Processing Failure

    # Backpressure: if all slots busy -> 0xA700 Out of Resources
    # Modality will retry  -  this is standard DICOM behavior (PS3.7 sec.C.4).
    # Like nginx worker_connections: accept only what you can process.
    # R17: bind the semaphore to a LOCAL before the acquire and release that
    # same object in the finally. A reloaded [advanced] max_concurrent_cstore
    # replaces the module global, and a handler still holding the OLD
    # semaphore then released the NEW one - raising its counter above the
    # configured limit for the rest of the process.
    sem = _cstore_semaphore
    if not sem.acquire(blocking=False):
        logging.warning(
            "[C-STORE] Backpressure: all %d slots busy - rejecting with 0xA700",
            _MAX_CONCURRENT_CSTORE,
        )
        return 0xA700  # Out of Resources

    try:
        # Bridge: C-STORE counter
        cstore_requests.inc()
        start_time = time.monotonic()

        # Bridge: check SOP class acceptance via registry
        if sop_registry is not None:
            context_uid = event.context.abstract_syntax
            if not _is_sop_accepted(sop_registry, context_uid):
                logging.warning(
                    "[C-STORE] Rejected: SOP class %s not in registry or accept=false",
                    context_uid,
                )
                # 0x0122 "SOP Class not supported" (PS3.7 Annex C) - 0xA801 is
                # a C-MOVE code and does NOT exist in the C-STORE status table
                # (PS3.4 Table B.2-1 lists A7xx/A9xx/Cxxx/B000/B006/B007/0000).
                return 0x0122

        # pydicom may fail to parse corrupted dataset (e.g. broken
        # sequences from Explicit->Implicit VR conversion of non-pixel objects).
        # Don't kill the association  -  return C000 and let other slices through.
        try:
            ds = event.dataset
        except (OSError, struct.error) as e:
            logging.warning("[BUG-005] C-STORE parse error, returning C000: %s", e)
            return 0xC000

        # Attach the File Meta Information BEFORE any
        # re-serialization. event.file_meta carries the NEGOTIATED transfer
        # syntax of this C-STORE. Without it, _ensure_file_meta defaults to
        # ExplicitVRLittleEndian and a 4.70 instance is silently rewritten as
        # EVRLE with its encapsulated pixel stream intact - a corrupt hybrid
        # (found by the cstore_e2e test).
        try:
            ds.file_meta = event.file_meta
        except Exception as fm_err:
            logging.warning("[C-STORE] Cannot attach file_meta: %s", fm_err)

        # The SOP Instance UID is read from the VALUE, not from `str()` of the
        # element: an element present with a null value yields the string
        # "None", which is non-empty and slipped past the missing-UID guard
        # below - so the instance was persisted under a UID literally named
        # "None" and the modality received 0x0000 for a dataset that carries no
        # Type 1 identifier (PS3.3 C.12.1.1.2). Read the raw value and require
        # a non-blank string.
        _sop_uid_value = getattr(ds, "SOPInstanceUID", None)
        sop_uid = "" if _sop_uid_value is None else str(_sop_uid_value).strip()
        study_uid = str(getattr(ds, "StudyInstanceUID", ""))
        patient = str(getattr(ds, "PatientName", "unknown"))

        # Bridge: detect malformed tags  -  missing SOPInstanceUID
        if not sop_uid:
            malformed_tags.inc()
            # SOPInstanceUID (0008,0018) is Type 1 for every Storage SOP
            # Class (PS3.4 B.2 / PS3.3 C.12.1.1.2). Enqueueing an instance
            # without it produced an empty outbox key: the row read as a
            # perpetual "duplicate", the blob was never persisted, and the
            # modality still got 0x0000 for an instance nobody stored.
            # 0xA900 "Data Set Does Not Match SOP Class" (PS3.4 Table B.2-1)
            # is the honest refusal.
            logging.warning("[C-STORE] Missing SOPInstanceUID - rejecting 0xA900")
            return 0xA900

        # Bridge: C-STORE size limit guard. The size is measured in both
        # branches: with a limit it gates the store, without one it feeds the
        # rx byte counter.
        dataset_size = _measure_dataset_bytes(ds, event)
        if max_store_bytes > 0 and dataset_size > max_store_bytes:
            logging.warning(
                "[C-STORE] Rejected oversized dataset: %d bytes "
                "(limit: %d bytes) from %s",
                dataset_size,
                max_store_bytes,
                mask_patient_name(patient),
            )
            return 0xA700  # Out of Resources  -  Refused: Out of Resources

        # rx bytes: the accepted payload size, counted before persistence so a
        # later outbox failure cannot hide received traffic.
        if dataset_size > 0:
            try:
                bytes_total.labels(
                    direction="rx", peer=ae_label(event.assoc.requestor.ae_title)
                ).inc(dataset_size)
            except Exception:
                pass

        logging.debug(
            "[C-STORE] Received: %s (SOP: %s)", mask_patient_name(patient), sop_uid
        )
        logging.debug(
            "[C-STORE] %s SOP=%s StudyUID=%s Modality=%s",
            mask_patient_name(patient),
            sop_uid[:40] if sop_uid else "(none)",
            study_uid[:50] if study_uid else "(none)",
            str(getattr(ds, "Modality", "?")),
        )

        # Track C-STORE per association for INFO-level logging.
        # Admin sees: "CT-2 connected, receiving study 1.2.840... (CT, 437 instances)".
        # One line per new study, not per SOP.
        try:
            assoc_id = id(event.assoc)  # Python object ID  -  unique per connection
        except Exception:
            assoc_id = 0
        patient_id_raw = str(getattr(ds, "PatientID", "?"))
        modality = str(getattr(ds, "Modality", "??"))
        # The tracker is told the modality only: it summarises per-study
        # counts, and PatientID has no reader there.
        is_new_study = record_cstore(assoc_id, study_uid, modality)
        if is_new_study:
            logging.info(
                "[C-STORE] Receiving: study=%s patient=%s modality=%s",
                study_uid[:50] if study_uid else "?",
                mask_patient_id(patient_id_raw) if patient_id_raw else "?",
                modality,
            )

        # Unified pre-stow admission gate (health + backpressure).
        # Rejects early (: don't do heavy work if we won't accept).
        adm_status, adm_reason = _AdmissionController(
            outbox=outbox,
            health_checker=health_checker,
            store_forward=store_forward,
        ).check()
        if adm_status != 0x0000:
            logging.warning(
                "[C-STORE] Admission denied (%s): rejecting with 0x%04X",
                adm_reason or "?",
                adm_status,
            )
            return adm_status

        # Bridge: fix cp1251 mojibake before forwarding to Clarus Server
        ds = _fix_cp1251_krakozyabry(ds)

        # Sanitize empty DICOM Type 2 fields before outbox
        # Bridge fixes what it can, server validates independently  -  two layers of protection.
        # write_audit=False: audit trail (0400,0561) is deferred to outbox worker
        # to keep the C-STORE hot-path fast. Modifications metadata is passed
        # alongside the blob and applied by the worker before STOW-RS.
        # study_uid: deterministic PatientID from StudyInstanceUID.
        # All SOPs in the same study get the SAME PatientID  -  preserves DICOM
        # patient-study relationship and prevents SQLite single-patient overflow.
        try:
            mods = sanitize_dataset(
                ds,
                fix_patient_id=fix_empty_patient_id,
                fix_patient_name=fix_empty_patient_name,
                id_prefix=bridge_id_prefix,
                name_prefix=bridge_name_prefix,
                write_audit=False,
                study_uid=study_uid,
                modifying_system=bridge_ae_title,
            )
            if mods:
                for tag, old, new in mods:
                    # Mask PatientName in logs (Russian personal-data law 152-FZ); show
                    # PatientID as-is (it is generated, not PHI).
                    display_new = (
                        mask_patient_name(new) if tag == (0x0010, 0x0010) else new
                    )
                    # The log needs a readable placeholder for an empty old
                    # value; the audit tuple that travelled with this line
                    # carries the raw empty string, never "(empty)".
                    logging.debug(
                        "Coerced %s: '%s' -> '%s' (audit trail deferred to worker)",
                        tag,
                        old or "(empty)",
                        display_new,
                    )
        except ValueError as e:
            logging.error("Validation failed: %s - returning 0xC000", e)
            return 0xC000

        # Synchronous study->PatientID guard: the outbox answers 0x0000 before
        # the STOW verdict exists, so the server's patient-conflict refusal
        # (409 -> 0xC000) can never reach this modality. Refuse a study the
        # bridge already holds under a DIFFERENT non-empty PatientID BEFORE
        # the enqueue; the rule mirrors the origin's `study_patient_conflict`,
        # and an empty PatientID is Type 2 "not stated" - never a conflict.
        _pid = str(getattr(ds, "PatientID", "") or "").strip()
        _stored_pid = _study_patient_get(study_uid)
        if _pid and _stored_pid and _stored_pid != _pid:
            logging.warning(
                "[C-STORE] Study %s already held under a different patient - "
                "refusing 0xC000",
                study_uid[:50] if study_uid else "?",
            )
            return 0xC000

        # "Don't do heavy work on the hot path. Accept bytes -> return
        # Success -> done. Everything else happens in the background."

        # Bridge: async STOW-RS via OutboxQueue  -  reliable persistence + best-effort delivery
        # (backpressure is already enforced by the unified _AdmissionController above)
        if outbox is not None:
            # Outbox-based: persist to SQLite -> immediate 0x0000 Success
            ok = outbox.enqueue(ds, modifications=mods if mods else None)
            if ok == "duplicate":
                # Idempotent  -  SOP already in outbox, return SUCCESS
                logging.info(
                    "[C-STORE] SOP %s already in outbox (duplicate) - 0x0000 Success",
                    sop_uid,
                )
                # Still a coercion warning when THIS request carried
                # modifications: the duplicate is the stored instance, and the
                # status describes the answer to the request in hand.
                return 0xB000 if mods else 0x0000
            if not ok:
                logging.error(
                    "[C-STORE] Outbox enqueue failed for %s (SOP: %s) - returning 0xA700",
                    mask_patient_name(patient),
                    sop_uid,
                )
                return 0xA700  # Out of Resources  -  transient, sender should retry

            status = 0x0000  # Success  -  SOP persisted in outbox, will be delivered
            # PS3.4 B.4: a coercion of an identifying attribute is a Warning,
            # not a plain Success. The instance WAS accepted and stored, so the
            # status stays in the warning range - but answering 0x0000 told the
            # modality (and every audit downstream of it) that the data set it
            # sent is exactly the one that was stored, when the bridge had
            # replaced its Patient ID. 0xB000 is the defined "coercion"
            # warning; without the changes the plain Success stands.
            if mods:
                status = 0xB000

            # Record the study's PatientID only AFTER a successful enqueue: a
            # failed enqueue must not poison the map (the study was not
            # accepted), and the guard above already ran on the pre-enqueue
            # state.
            if _pid:
                _study_patient_put(study_uid, _pid)

            # -- 0409 forwarder hook ----------------------------------
            # Best-effort DIMSE->DIMSE mirror to a SECOND (non-authoritative)
            # archive. Called ONLY after the PRIMARY enqueue returned True
            # (so a failed primary enqueue never touches the forward channel).
            # The forward channel can NEVER change `status`: whatever happens
            # here the modality already holds 0x0000 from the primary persist.
            if forward_outbox is not None:
                try:
                    # Blob is already atomically on disk in the primary outbox;
                    # hardlink (EXDEV fallback copy) it into forward/pending.
                    #
                    # The drain worker can claim the item (pending/ ->
                    # in_progress/) between the enqueue returning and this
                    # hook running, so pending/ alone is not where the blob has
                    # to be. A hardlink to either name is safe: mark_delivered
                    # only unlinks the name the PRIMARY owns.
                    primary_blob = outbox._dcm_path(outbox._pending, sop_uid)
                    if not os.path.isfile(primary_blob):
                        primary_blob = outbox._dcm_path(outbox._in_progress, sop_uid)
                    _ = forward_outbox.enqueue_from_blob(
                        primary_blob,
                        sop_uid,
                        modifications=mods if mods else None,
                    )
                    # Result is intentionally ignored: forward is best-effort.
                    # Dropped/full/failure are logged + counted inside
                    # enqueue_from_blob; the modality status stays 0x0000.
                except Exception as fwd_err:  # defensive: never touch status
                    logging.warning(
                        "[C-STORE] Forward enqueue raised %s for %s "
                        "(0x0000 unchanged)",
                        type(fwd_err).__name__,
                        sop_uid,
                    )
                    if hasattr(forward_outbox, "_inc_forward_dropped"):
                        forward_outbox._inc_forward_dropped()
        else:
            # Fallback: sync forwarding (no outbox, no legacy queue)
            logging.warning(
                "[C-STORE] No queue configured - falling back to sync forward"
            )
            # `sanitize_dataset` ran with write_audit=False, on the assumption
            # that an outbox worker would apply the audit trail from `mods`
            # before the STOW. On THIS path there is no worker: the dataset goes
            # out immediately, so the coercion of an empty Patient ID reached
            # the origin with no Modified Attributes Sequence and no record of
            # the original value anywhere. The audit is therefore applied
            # inline, here, before the send - the deferred form is only correct
            # where something is actually deferred TO.
            if mods:
                try:
                    for tag, old, _new in mods:
                        record_modification(
                            ds,
                            tag,
                            old,
                            reason="COERCE",
                            modifying_system=bridge_ae_title,
                        )
                except Exception as audit_err:
                    # Without the audit trail the forwarded record no longer
                    # matches what this bridge documents, so the instance is
                    # refused instead of stored anonymously.
                    logging.error(
                        "[C-STORE] Cannot record the coercion audit for %s "
                        "(%s) - refusing the instance rather than forwarding "
                        "it without provable audit data",
                        sop_uid,
                        audit_err,
                    )
                    return 0xC000
            status, http_status, reason = stow_single_instance(
                ds,
                clarus_url,
                http_timeout,
                tls=tls,
            )
            if status != 0x0000:
                logging.warning(
                    "[C-STORE] Rejected %s (SOP: %s): %s - %s",
                    mask_patient_name(patient),
                    sop_uid,
                    _dimse_status_name(status),
                    reason,
                )
            elif _pid:
                _study_patient_put(study_uid, _pid)

        # Bridge: translation duration observation
        translation_duration.observe(time.monotonic() - start_time)

        return status
    finally:
        sem.release()

# ---------------------------------------------------------------------------
# Bridge: C-ECHO handler
# ---------------------------------------------------------------------------
def handle_c_echo(event):
    """Handle C-ECHO (Verification)."""
    return 0x0000  # Success

# ---------------------------------------------------------------------------
# Bridge: handlers/mpps
# ---------------------------------------------------------------------------

"""Clarus Bridge - MPPS translator (DIMSE N-CREATE/N-SET -> DICOMweb MPPS).

PS3.18 section 15 serves Modality Performed Procedure Step over DICOMweb and
maps it onto the DIMSE operations one-to-one: Create (15.4) is
`POST /modality-performed-procedure-steps/{mppsUID}`, Update (15.5) is the
SAME URI with the mandatory `update` query parameter - the only thing that
distinguishes the two transactions - and Retrieve (15.6, N-GET) is optional
for the origin server and is not translated here.

The bridge holds no MPPS state: the origin server owns the record and its
state machine (PS3.4 F.7). Every parse and transport path answers with a DIMSE
status, never raises into the association reactor.
"""

import json
import logging
from urllib.parse import quote

import httpx
from pydicom.dataset import Dataset
from pydicom.multival import MultiValue

# PS3.4 Table F.7.2-1 (standard/ps3.4/mpps-f.7.2.1-attribute-table.json): every
# attribute the translator reads, with the VR the standard fixes for it. The
# VR is never guessed from a value's shape - a UID- or date-shaped string
# assigned the wrong VR makes the origin reject the whole body.
MPPS_ATTR_TAGS = {
    # SOP Common (PS3.3 C.3.3.1) - written by the translator, not forwarded.
    "00080016": (0x0008, 0x0016, "UI"),
    "00080018": (0x0008, 0x0018, "UI"),
    # Patient / study keys.
    "00080005": (0x0008, 0x0005, "CS"),
    "00100010": (0x0010, 0x0010, "PN"),
    "00100020": (0x0010, 0x0020, "LO"),
    "00100030": (0x0010, 0x0030, "DA"),
    "00100040": (0x0010, 0x0040, "CS"),
    "00080050": (0x0008, 0x0050, "SH"),
    # Procedure keys.
    "00080060": (0x0008, 0x0060, "CS"),
    "00400241": (0x0040, 0x0241, "AE"),
    "00400242": (0x0040, 0x0242, "SH"),
    "00400243": (0x0040, 0x0243, "SH"),
    "00400244": (0x0040, 0x0244, "DA"),
    "00400245": (0x0040, 0x0245, "TM"),
    "00400250": (0x0040, 0x0250, "DA"),
    "00400251": (0x0040, 0x0251, "TM"),
    "00400252": (0x0040, 0x0252, "CS"),
    "00400253": (0x0040, 0x0253, "SH"),
    "00400254": (0x0040, 0x0254, "LO"),
}

MPPS_SOP_CLASS_UID = "1.2.840.10008.3.1.2.3.3"

_STATUS = "00400252"
STATUS_IN_PROGRESS = "IN PROGRESS"
STATUS_COMPLETED = "COMPLETED"
STATUS_DISCONTINUED = "DISCONTINUED"

# PS3.4 F.7.2.1: "the SCU shall only send the N-CREATE request with Performed
# Procedure Step Status (0040,0252) set to IN PROGRESS. The SCP shall accept
# N-CREATE only if the value is IN PROGRESS; otherwise it shall return Failure
# Status 0106H 'Invalid Attribute Value' with an Attribute List." The same code
# is what PS3.7 lists for an out-of-range enumerated value on N-SET.
_INVALID_ATTRIBUTE_VALUE = 0x0106

# PS3.18 Table F.2.3-1: the VRs whose JSON type is a Number. The binary
# integer VRs are packed as integers on the wire; IS is decimal text that also
# maps to Number. FD/FL are the real-valued pair.
_INTEGER_VRS = frozenset({"US", "SS", "UL", "SL", "UV", "SV", "IS"})
_FLOAT_VRS = frozenset({"FD", "FL"})

# PS3.7 (standard/ps3.7/status-codes.json, service "mpps"):
#   0x0110 Processing Failure       - the request will never succeed
#   0x0111 Duplication SOP Instance - the UID is already in use
#   0x0112 No Such SOP Instance     - the instance N-SET addresses does not exist
#   0x0120 Missing Attribute        - a Type 1 attribute is absent
#   0x0121 Missing Attribute Value  - present but empty
#   0x0213 Resource Limitation      - the origin cannot take the work right now
_PROCESSING_FAILURE = 0x0110
_DUPLICATE_INSTANCE = 0x0111
_NO_SUCH_INSTANCE = 0x0112
_MISSING_ATTRIBUTE = 0x0120
_MISSING_ATTRIBUTE_VALUE = 0x0121
_RESOURCE_LIMITATION = 0x0213

class _Refusal(Exception):
    """A DIMSE refusal decided while parsing, carrying the status to answer."""

    def __init__(self, status, reason):
        super().__init__(reason)
        self.status = status
        self.reason = reason

# ---------------------------------------------------------------------------
# DIMSE data set -> DICOMweb JSON
# ---------------------------------------------------------------------------
def _json_value(vr, value):
    """One element value as a DICOMweb JSON `Value` entry (PS3.18 F.2.3).

    Table F.2.3-1 fixes the JSON type per VR: PN is a component-group object,
    and a numeric VR written as a JSON Number must stay a Number. A sequence
    is not handled here - its items are Data Sets, recursed into by
    `_element_json`.
    """
    if vr == "PN":
        return _pn_json(value)
    if vr in _INTEGER_VRS:
        # Integer binary VRs plus IS: the JSON type is Number. `UL` and the
        # other binary integer VRs were falling through to `str()`, so a
        # forwarded `UL` of 7 became "7" - a different JSON type from what the
        # VR allows, and one an origin validating against Table F.2.3-1
        # rejects. A value that will not parse stays as text rather than
        # raising: it is legal on the wire for IS, and for a binary VR it can
        # only come from a nonconforming source.
        try:
            return int(value)
        except (TypeError, ValueError):
            return str(value)
    if vr in _FLOAT_VRS:
        try:
            return float(value)
        except (TypeError, ValueError):
            return str(value)
    return str(value)

def _pn_json(value):
    """A PN value as its component-GROUP object (PS3.18 F.2.2).

    A Person Name is three component groups separated by `=`: Alphabetic,
    Ideographic and Phonetic. Annex F.2.2 gives each populated group its OWN
    property, so folding the whole value into `Alphabetic` (which is what a
    plain `str(value)` of `Yamada^Tarou=...==...` produced) made the origin
    read the two extra groups as part of the alphabetic name - and a name that
    has ONLY an ideographic group was published as an alphabetic one.

    Leading groups are kept even when empty, as `str()` preserves the
    separators, so the origin can still identify which group a value belongs
    to. A value with no separator is a single alphabetic group.
    """
    text = str(value)
    groups = text.split("=")
    names = ("Alphabetic", "Ideographic", "Phonetic")
    out = {}
    for name, group in zip(names, groups):
        if group:
            out[name] = group
    return out if out else {"Alphabetic": ""}

def _element_json(elem):
    """One DICOM element as a DICOMweb JSON attribute object (PS3.18 F.2.2).

    A zero-length attribute is written as an object with NO `Value`: F.2.5
    says an attribute that is present in DICOM but empty "shall be preserved in
    the DICOM JSON attribute object containing no Value, BulkDataURI or
    InlineBinary". Writing `{"Value": [""]}` would instead assert that ONE
    value exists and that it is the empty string - a different statement.
    """
    vr = elem.VR
    value = elem.value
    if vr == "SQ":
        items = [_dataset_json(item) for item in (value or [])]
        return {"vr": vr, "Value": items} if items else {"vr": vr}
    if value is None:
        return {"vr": vr}
    values = value if isinstance(value, (list, tuple, MultiValue)) else [value]
    # Value Length 0 is the same statement as "no value", and F.2.5 writes it
    # as an object with no `Value`. `{"Value": [""]}` would assert that ONE
    # value exists and that it is the empty string - pydicom hands over both
    # forms (an empty list for a sequence, an empty string for a text VR), so
    # both are folded here.
    rendered = [
        None if item in (None, "") else _json_value(vr, item) for item in values
    ]
    if not any(r is not None for r in rendered):
        # Every position is empty: F.2.5 says the attribute is written with no
        # `Value` at all, which is what the caller checks for.
        return {"vr": vr}
    return {"vr": vr, "Value": rendered}

def _dataset_json(ds):
    """A full Data Set as a DICOMweb JSON object, tags in ascending order."""
    return {
        f"{elem.tag.group:04X}{elem.tag.element:04X}": _element_json(elem)
        for elem in sorted(ds, key=lambda e: e.tag)
    }

# ---------------------------------------------------------------------------
# Validation of the untrusted request
# ---------------------------------------------------------------------------
def _read_dataset(event, attr):
    """Read the event's request data set, or refuse.

    pydicom decodes a Data Set DEFERRED, so a body with broken element encoding
    only raises when an element is first touched. Walking the set here turns
    that into a documented 0x0110 Processing Failure instead of an exception
    escaping the handler into the association reactor.
    """
    try:
        ds = getattr(event, attr)
    except AttributeError:
        raise _Refusal(_MISSING_ATTRIBUTE, f"request carries no {attr}") from None
    if ds is None:
        raise _Refusal(_MISSING_ATTRIBUTE, f"request carries no {attr}")
    try:
        for _elem in ds:
            pass
    except Exception as e:
        raise _Refusal(_PROCESSING_FAILURE, f"{attr} could not be decoded: {e}") from e
    return ds

def _text(ds, tag):
    """The stripped string value of one element; None when absent or empty."""
    elem = ds.get(MPPS_ATTR_TAGS[tag][:2])
    if elem is None or elem.value is None:
        return None
    text = str(elem.value).strip()
    return text or None

def _item_text(item, tag, name, series_number, ref_number=None):
    """A Type 1 value inside a sequence item, or a refusal naming the item."""
    elem = item.get(tag)
    text = (
        str(elem.value).strip() if elem is not None and elem.value is not None else ""
    )
    if text:
        return text
    where = f"Performed Series Sequence item {series_number}"
    if ref_number is not None:
        where += f", Referenced Image Sequence item {ref_number}"
    raise _Refusal(_MISSING_ATTRIBUTE, f"{where} has no {name}")

def _check_performed_series(ds, final=False):
    """Validate Performed Series Sequence (0040,0340) item shape.

    PS3.4 Table F.7.2-1 makes Series Instance UID (0020,000E) Type 1 inside
    every item, and puts the (0008,1150)/(0008,1155) reference pair in the
    NESTED Referenced Image Sequence (0008,1140), not on the item itself. The
    origin server stores whatever it is sent, so an item without its series UID
    would create a record no consumer can attribute to a series - refused here,
    while the offending SCU is still on the wire to be told.

    `final` says the update moves the step to COMPLETED/DISCONTINUED, where
    PS3.4 F.7.2.2 stops allowing "no series yet": an empty item is then a
    defect rather than the wire encoding of an absent sequence.
    """
    seq = ds.get((0x0040, 0x0340))
    if seq is None or seq.value is None:
        return
    # PS3.4 F.7.2.2 requires a NON-EMPTY Performed Series Sequence once the
    # status becomes COMPLETED/DISCONTINUED. An explicitly empty sequence is
    # not "the attribute was omitted": it states that no series was performed,
    # which contradicts the final status. Letting it through posted an empty
    # sequence to an origin that stores whatever it is sent, so the study
    # ended up with a completed MPPS and no performed series at all.
    #
    # Omission stays legal on a PARTIAL update (a valid series may already be
    # stored by the origin), so only the explicit-empty case is refused here.
    if final and len(seq.value) == 0:
        raise _Refusal(
            _MISSING_ATTRIBUTE_VALUE,
            "Performed Series Sequence (0040,0340) is empty; a final status "
            "requires at least one performed series (PS3.4 F.7.2.2)",
        )
    for number, item in enumerate(seq.value, start=1):
        if not isinstance(item, Dataset):
            raise _Refusal(
                _PROCESSING_FAILURE,
                f"Performed Series Sequence item {number} is not a Data Set",
            )
        # PS3.4 F.7.2-1 makes Performed Series Sequence (0040,0340) Type 2 at
        # N-CREATE: it may be empty because the series has not been performed
        # yet. A zero-length item is the wire encoding of "no series", and it
        # carries no Type 1 Series Instance UID to enforce - skip it instead of
        # refusing a conformant N-CREATE that has not acquired anything yet.
        #
        # The same skip is NOT correct on a FINAL N-SET: PS3.4 F.7.2.2 requires
        # a non-empty Performed Series Sequence once the status becomes
        # COMPLETED/DISCONTINUED, so an item present but empty there is a
        # malformed update, not "no series". `final` selects the rule.
        if len(item) == 0:
            if final:
                raise _Refusal(
                    _MISSING_ATTRIBUTE,
                    f"Performed Series Sequence item {number} is empty; a final "
                    "status requires a Series Instance UID (0020,000E)",
                )
            continue
        _item_text(item, (0x0020, 0x000E), "Series Instance UID (0020,000E)", number)
        ref_seq = item.get((0x0008, 0x1140))
        if ref_seq is None or ref_seq.value is None:
            continue
        for ref_number, ref in enumerate(ref_seq.value, start=1):
            if not isinstance(ref, Dataset):
                raise _Refusal(
                    _PROCESSING_FAILURE,
                    f"Referenced Image Sequence item {ref_number} of performed "
                    f"series {number} is not a Data Set",
                )
            _item_text(
                ref,
                (0x0008, 0x1150),
                "Referenced SOP Class UID (0008,1150)",
                number,
                ref_number,
            )
            _item_text(
                ref,
                (0x0008, 0x1155),
                "Referenced SOP Instance UID (0008,1155)",
                number,
                ref_number,
            )

def _check_status_for_create(ds):
    """An N-CREATE body must carry IN PROGRESS (PS3.4 F.7.2.1)."""
    status = _text(ds, _STATUS)
    if status is None:
        raise _Refusal(
            _MISSING_ATTRIBUTE,
            "Performed Procedure Step Status (0040,0252) is missing or empty",
        )
    # The comparison is EXACT, not case-folded. PS3.4 F.7.2.1 defines the
    # value as the enumerator `IN PROGRESS`, and the DICOM CS VR is
    # case-sensitive for defined terms; accepting `in progress` and then
    # posting it unchanged sent the origin a value it may reject or store as
    # an unknown term. The request is refused at the DIMSE boundary instead.
    if status != STATUS_IN_PROGRESS:
        raise _Refusal(
            _INVALID_ATTRIBUTE_VALUE,
            "Performed Procedure Step Status must be IN PROGRESS at N-CREATE "
            f"(PS3.4 F.7.2.1), got '{status}'",
        )

def _check_status_for_update(ds):
    """An N-SET body may carry a status, but only one of the three legal ones.

    The value that goes to the origin is the NORMALISED one (`_normalise_status`
    is called by the caller): a set that compared IN PROGRESS only after
    upper-casing used to forward the lower-case spelling unchanged, so the
    origin received a status it may not accept while the bridge had already
    validated it as legal.
    """
    status = _text(ds, _STATUS)
    if status is None:
        # N-SET is a partial update (PS3.4 F.7.2.2): omitting the attribute
        # keeps the stored status, so this is not an error.
        return None
    upper = status.upper()
    if upper not in (
        STATUS_IN_PROGRESS,
        STATUS_COMPLETED,
        STATUS_DISCONTINUED,
    ):
        raise _Refusal(
            _INVALID_ATTRIBUTE_VALUE,
            f"Invalid Performed Procedure Step Status '{status}' (0040,0252)",
        )
    return upper

def _normalise_status(ds, normalised):
    """Write the validated status back so the origin sees the legal spelling.

    Only a value the validator already accepted is rewritten, and only when the
    element is present: an absent status stays absent, keeping the N-SET
    partial-update semantics intact. A present-but-EMPTY status is REMOVED - it
    is the wire encoding of "no value", and forwarding it as `[""]` asserted a
    status the SCU never supplied.
    """
    tag = MPPS_ATTR_TAGS[_STATUS][:2]
    elem = ds.get(tag)
    if elem is None:
        return
    if normalised is None:
        del ds[tag]
        return
    elem.value = normalised

def _invalid_status_attribute_list(ds):
    """The Attribute List returned with an Invalid Attribute Value refusal.

    PS3.4 F.7.2.1: the SCP shall return status 0106H "with an Attribute List"
    for an N-CREATE whose status is not IN PROGRESS. The offending attribute is
    Performed Procedure Step Status (0040,0252) itself, so the list names that
    attribute rather than echoing the request - the SCU already knows the rest
    of what it sent, and the point of the list is to identify the offender.

    A single-element Data Set in DIMSE encoding terms; pynetdicom encodes it
    into the response's Attribute List identifier region. Built here rather
    than reused from the request because the refused value must NOT travel
    back as if it were accepted.
    """
    out = Dataset()
    out.PerformedProcedureStepStatus = STATUS_IN_PROGRESS
    return out

def _body(ds, mpps_uid):
    """The DICOMweb request body for a validated DIMSE data set.

    The SOP Common pair comes from the translator, not from the client's data
    set: DIMSE carries the instance UID as a command field (PS3.7 10.1.5.1 /
    10.3.5), so a data set that also names a DIFFERENT UID is describing an
    object it is not addressing. The command field wins.
    """
    body = _dataset_json(ds)
    body["00080016"] = {"vr": "UI", "Value": [MPPS_SOP_CLASS_UID]}
    body["00080018"] = {"vr": "UI", "Value": [mpps_uid]}
    return body

# ---------------------------------------------------------------------------
# HTTP -> DIMSE status
# ---------------------------------------------------------------------------
def _http_dimse_status(status_code, on_conflict, on_missing):
    """Map the origin's HTTP answer onto a DIMSE status.

    PS3.18 Table 15.4.3-1 enumerates the Create answers: 201 Created, 400 Bad
    Request, 409 Conflict ("the provided MPPS UID is already in use"), 503
    Service Unavailable. Update answers 200 on success and 404 when the
    instance is unknown.
    """
    if 200 <= status_code < 300:
        return 0x0000
    if status_code == 409:
        return on_conflict
    if status_code == 404:
        return on_missing
    if status_code in (429, 503):
        # The origin is asking to be retried. Both listed values are the
        # enumerated "come back later" failure; 0xA700 is a C-STORE/C-FIND
        # warning and is not a legal MPPS status.
        return _RESOURCE_LIMITATION
    return _PROCESSING_FAILURE

def _mpps_url(clarus_url, mpps_uid, update):
    """`{base}/modality-performed-procedure-steps/{mppsUID}` (+ `?update`).

    `safe=""` per segment: a UID is one path element, so `/`, `?` and `#`
    inside it must not change which resource the POST addresses (PS3.18 10.1
    resource paths). `update` is the query parameter PS3.18 15.5 makes
    mandatory for the Update transaction - without it the same URI addresses
    the Create transaction instead.
    """
    base = dicomweb_base(clarus_url)
    url = f"{base}/modality-performed-procedure-steps/{quote(mpps_uid, safe='')}"
    return url + "?update" if update else url

def _push(label, url, body, mpps_uid, http_timeout, tls):
    """POST one transaction and answer ``(http_status, None)`` or ``(None, why)``.

    No retry here on purpose: an N-CREATE/N-SET runs inside the DIMSE reactor
    while the modality waits on one request, and a repeated Create after a
    timeout the origin actually processed would come back 409 on the second
    attempt - a duplicate reported for an instance that exists BECAUSE of the
    first. A failure is answered as a failure and the modality decides.

    The response body is not read: neither transaction returns an attribute the
    bridge forwards (Create/Update answer a render of the stored record), and
    the context-managed client releases the connection either way.
    """
    try:
        client = httpx.Client(timeout=httpx.Timeout(http_timeout + 10.0), cert=tls)
        try:
            resp = client.post(
                url,
                content=json.dumps(body).encode("utf-8"),
                headers={
                    "Accept": "application/dicom+json",
                    "Content-Type": "application/dicom+json",
                },
            )
        finally:
            client.close()
    except httpx.TimeoutException as e:
        return None, f"origin timeout ({e})"
    except httpx.HTTPError as e:
        return None, f"transport error {type(e).__name__}: {e}"
    return resp.status_code, None

def _calling_ae(event):
    """The calling AE Title for the log line; '' when the event carries none."""
    try:
        return str(event.assoc.requestor.ae_title)
    except Exception:
        return ""

def _request_uid(event, attr, label):
    """The instance UID from the DIMSE command field, or a refusal.

    N-CREATE carries the Affected SOP Instance UID (0000,1000) and N-SET the
    Requested SOP Instance UID (0000,1001) (PS3.7 10.1.5.1 / 10.3.5). Neither
    is a data set attribute, so a data set cannot substitute for one; both live
    on the request primitive, which `event.request` is.
    """
    try:
        uid = getattr(event.request, attr)
    except AttributeError:
        uid = None
    text = str(uid).strip() if uid is not None else ""
    if not text:
        raise _Refusal(_MISSING_ATTRIBUTE, f"{label} carries no {attr}")
    return text

def _handle(event, clarus_url, label, uid_attr, ds_attr, update, http_timeout, tls):
    """Shared body of N-CREATE and N-SET: validate, POST, map the answer.

    `uid_attr` is the request primitive's own field: N-CREATE reads the
    Affected SOP Instance UID and N-SET the Requested SOP Instance UID (PS3.7
    10.1.5.1 / 10.3.5). `update` selects the transaction, because PS3.18 15.5
    distinguishes Create from Update ONLY by the `update` query parameter on an
    otherwise identical URI - so the choice is a parameter of one code path,
    never two paths that could drift apart.
    """
    if _shutdown_requested.is_set():
        return 0xC000, None
    ds = None
    try:
        mpps_uid = _request_uid(event, uid_attr, label)
        ds = _read_dataset(event, ds_attr)
        if update:
            normalised = _check_status_for_update(ds)
            # The validator upper-cases for its comparison; the origin must
            # receive the same legal spelling, not the raw one.
            _normalise_status(ds, normalised)
            _check_performed_series(
                ds,
                final=normalised in (STATUS_COMPLETED, STATUS_DISCONTINUED),
            )
        else:
            _check_status_for_create(ds)
            _check_performed_series(ds)
        body = _body(ds, mpps_uid)
    except _Refusal as refusal:
        logging.warning(
            "[%s] MPPS refused 0x%04X: %s", label, refusal.status, refusal.reason
        )
        # PS3.4 F.7.2.1 requires the Invalid Attribute Value refusal on
        # N-CREATE to be accompanied by an Attribute List identifying the
        # offending attribute. Answering the bare status leaves a conformant
        # SCU with no way to learn WHICH attribute was wrong.
        #
        # Only 0x0106 qualifies: the other refusals this handler raises are
        # missing/undecodable data, where no attribute list is defined.
        if refusal.status == _INVALID_ATTRIBUTE_VALUE and not update and ds is not None:
            return refusal.status, _invalid_status_attribute_list(ds)
        return refusal.status, None
    except Exception as e:
        # A refusal with an evidence-free traceback would escape into the
        # association reactor, so every other parse surprise is answered as
        # the documented Processing Failure.
        logging.error("[%s] unexpected parse error: %s", label, e)
        logging.debug("[%s] Full traceback follows:", label, exc_info=True)
        return _PROCESSING_FAILURE, None

    status_code, error = _push(
        label,
        _mpps_url(clarus_url, mpps_uid, update),
        body,
        mpps_uid,
        http_timeout,
        tls,
    )
    if status_code is None:
        logging.warning(
            "[%s] MPPS %s: %s -> 0x%04X", label, mpps_uid, error, _PROCESSING_FAILURE
        )
        return _PROCESSING_FAILURE, None

    # A 409 on Create is the "UID already in use" case PS3.18 Table 15.4.3-1
    # names; on Update it cannot mean a duplicate instance (the MPPS already
    # exists), so it falls through to the general refusal.
    status = _http_dimse_status(
        status_code,
        on_conflict=_DUPLICATE_INSTANCE if not update else _PROCESSING_FAILURE,
        on_missing=_PROCESSING_FAILURE if not update else _NO_SUCH_INSTANCE,
    )
    log = logging.info if status == 0x0000 else logging.warning
    # N-CREATE carries the Affected SOP Instance UID, N-SET the Requested one,
    # so the same log line names the field this request actually used.
    log(
        "[%s] MPPS %s=%s from %s: HTTP %d -> 0x%04X",
        label,
        uid_attr,
        mpps_uid,
        _calling_ae(event),
        status_code,
        status,
    )
    return status, None

def handle_n_create(event, clarus_url, http_timeout=30, tls=None):
    """N-CREATE-RQ -> PS3.18 15.4 Create. Returns (status, None).

    A created instance is acknowledged with no Attribute List: the record the
    origin stored IS the result, and echoing the request back would let an
    attribute the origin rejected travel back as if it had been accepted.
    """
    return _handle(
        event,
        clarus_url,
        "N-CREATE",
        "AffectedSOPInstanceUID",
        "attribute_list",
        update=False,
        http_timeout=http_timeout,
        tls=tls,
    )

def handle_n_set(event, clarus_url, http_timeout=30, tls=None):
    """N-SET-RQ -> PS3.18 15.5 Update. Returns (status, None).

    The Modification List is a PARTIAL data set: PS3.4 F.7.2.2 merges it onto
    the stored instance, so nothing here demands a Type 1 attribute that the
    creation already supplied. Only the status value and the shape of a
    sequence that IS present are checked.
    """
    return _handle(
        event,
        clarus_url,
        "N-SET",
        "RequestedSOPInstanceUID",
        "modification_list",
        update=True,
        http_timeout=http_timeout,
        tls=tls,
    )

# ---------------------------------------------------------------------------
# Bridge: handlers/naction
# ---------------------------------------------------------------------------

"""Clarus Bridge - N-ACTION handler (Storage Commitment).

handle_n_action: parses Storage Commitment Request, verifies SOPs via WADO-RS,
builds N-ACTION-RSP with success/failed SOP sequences, and registers the batch
in the CommitTracker for the async N-EVENT-REPORT (closes the
RSP->report loop).
"""

import logging
from urllib.parse import quote

import httpx

# ---------------------------------------------------------------------------
# Per-SOP Storage Commitment confirmation (shared by sync RSP + async report)
# ---------------------------------------------------------------------------
def _sop_confirm(sop_uid, sop_index, clarus_url, http_timeout, tls=None):
    """Confirm one SOP is actually stored in Clarus. Returns DIMSE reason.

    0      - confirmed (in index AND WADO-RS metadata 200), also marks verified.
    0xC201 - not in index / not on server.
    0xC202 - server unavailable (timeout / connection refused).
    0xC210 - processing failure.
    """
    entry = sop_index.lookup_sop(sop_uid)
    if entry is None:
        return 0xC201

    study_uid = entry["study_uid"]
    series_uid = entry["series_uid"]
    base = dicomweb_base(clarus_url)
    # `safe=""` per segment: a UID is one path element, so `/`, `?` and `#`
    # inside it must not change which resource the GET addresses
    # (PS3.18 10.1 resource paths). Unescaped, a crafted UID of `1.2?a=b`
    # pointed the verification at a DIFFERENT resource, and a 200 there
    # confirmed a SOP the server never stored.
    url = (
        f"{base}/studies/{quote(study_uid, safe='')}"
        f"/series/{quote(series_uid, safe='')}/instances/{quote(sop_uid, safe='')}"
        "/metadata"
    )
    try:
        resp = _wado_metadata_request(url, http_timeout, tls=tls)
    except (httpx.TimeoutException, httpx.ConnectError):
        return 0xC202
    except Exception as e:
        logging.warning("  [N-ACTION] SOP %s: WADO error (%s)", sop_uid, e)
        return 0xC210

    if resp.status_code == 200:
        try:
            sop_index.mark_verified(sop_uid)
        except Exception:
            pass
        return 0
    logging.warning(
        "  [N-ACTION] SOP %s: WADO-RS HTTP %d -> not confirmed",
        sop_uid,
        resp.status_code,
    )
    return 0xC201

# ---------------------------------------------------------------------------
# N-ACTION handler (Storage Commitment)
# ---------------------------------------------------------------------------
def _register_commit(
    commit_tracker,
    tx_uid,
    calling_ae,
    sop_list,
    event,
    resolve_scp=None,
):
    """Register the batch so the async N-EVENT-REPORT can be pushed later.

    PS3.8: A-ASSOCIATE carries no listening port, and `requestor.port` is the
    EPHEMERAL SOURCE port of this very connection - pushing an N-EVENT-REPORT
    there always failed, because that socket is gone once the association
    closes. The destination port therefore comes from the peer config (the same
    lookup C-MOVE uses) and nowhere else. A peer that cannot be resolved is
    reported as skipped rather than guessed at.

    Returns True when the batch was registered (its N-EVENT-REPORT will be
    pushed); False when there is no resolvable requestor address/port, so the
    caller can refuse the request instead of acknowledging a commitment whose
    report can never go out.
    """
    requestor = getattr(getattr(event, "assoc", None), "requestor", None)
    address = getattr(requestor, "address", None)
    port_ = None
    if resolve_scp is not None and calling_ae and address:
        try:
            target = resolve_scp(calling_ae, address)
            if target:
                address, port_ = target[0], target[1]
        except Exception as e:
            logging.warning("[N-ACTION] resolve_scp for %s failed: %s", calling_ae, e)

    if address and port_:
        try:
            commit_tracker.register(tx_uid, calling_ae, address, int(port_), sop_list)
        except Exception as e:
            # Persistence failed, so the commitment cannot be honoured later.
            # Answer Failure (0x0110) instead of acknowledging a request whose
            # N-EVENT-REPORT would never be pushed (PS3.4 J.3.3.1).
            logging.error("[N-ACTION] tx=%s could not be registered: %s", tx_uid, e)
            return False
        return True

    logging.warning(
        "[N-ACTION] No requestor address/port for tx=%s - report skipped",
        tx_uid,
    )
    return False

def handle_n_action(
    event,
    clarus_url,
    verbose,
    sop_index,
    http_timeout=30,
    commit_tracker=None,
    resolve_scp=None,
    tls=None,
    stc_presence=False,
):
    """Handle N-ACTION-RQ (Storage Commitment Push Model, PS3.4 K.2).

    Two modes, selected once at startup by ``[dicomweb]
    storage_commitment_presence``:

    - ``stc_presence=False`` (default, today's behaviour): confirm each SOP
      against the local index + WADO-RS, build the RSP with provisional
      Success/Failed sequences, and register the batch for the async
      N-EVENT-REPORT.
    - ``stc_presence=True``: the ORIGIN owns commitment. The RSP is
      status-only 0x0000 (the standard's shape, J.3.2.1.3) - the verdict is
      not known yet, because the bridge's own STOW may still be queued - and
      the batch is registered so the tracker asks the origin ONCE when the
      bridge has delivered every SOP.

    Registers only when a commit_tracker is provided (fire-and-forget); the
    N-ACTION-RSP itself stays synchronous.
    """
    # Bridge: reject new requests during shutdown
    if _shutdown_requested.is_set():
        return 0xC000, None

    # Validate action_type (1 = Storage Commitment Request).
    # 0x0123 "No Such Action" (PS3.7): this action_type is not one the bridge
    # implements. 0x0122 would claim the SOP CLASS is unsupported - a different
    # refusal - so it must not be used here.
    action_type = getattr(event, "action_type", None)
    if action_type is not None and action_type != 1:
        logging.warning(
            "[N-ACTION] Unsupported action_type=%s (only type 1 supported)",
            action_type,
        )
        return 0x0123, None

    calling_ae = event.assoc.requestor.ae_title
    logging.debug("[DIMSE] N-ACTION from %s", calling_ae)

    try:
        naction_requests.inc()
    except Exception:
        pass

    try:
        tx_uid, sop_list = _parse_n_action_rq(event)
    except ValueError as e:
        # Unparsable request (e.g. missing TransactionUID) -> 0x0110
        # Processing Failure (the 0107/0110 class).
        logging.warning("[N-ACTION] Parse error: %s", e)
        return 0x0110, None
    except Exception as e:
        # 0x0110 Processing Failure: the request cannot be parsed and will
        # never succeed, so the SCU must not read this as a temporary
        # condition (0x0213 Resource Limitation invites a retry).
        logging.error("[N-ACTION] Unexpected parse error: %s", e)
        logging.debug("[N-ACTION] Full traceback follows:", exc_info=True)
        return 0x0110, None

    logging.info(
        "[N-ACTION] TransactionUID: %s, SOPs to verify: %d", tx_uid, len(sop_list)
    )

    # J.3.2: a successful N-ACTION-RSP says only that the SCP RECEIVED the
    # request; the per-SOP verdict travels in the N-EVENT-REPORT (J.3.3.1).
    # The RSP is therefore ALWAYS status-only 0x0000 here, and the verdict is
    # left entirely to the tracker, which probes asynchronously.
    #
    # Confirming every referenced SOP before answering meant one WADO
    # round-trip per instance inside the DIMSE reactor: a modality that sends
    # a 500-instance batch held its association open for tens of minutes
    # waiting for an acknowledgement that, by the standard, carries nothing.
    # A caller-supplied `sop_index` is no longer consulted here; the tracker's
    # `verify` callable is the one place that knows how a SOP is confirmed.
    rsp = None
    if stc_presence:
        # Origin-owned commitment. The verdict is not knowable here: the
        # bridge may still be holding some of these SOPs in its own outbox,
        # so any sequence content would be a guess. The tracker resolves the
        # batch against the origin once every SOP has been delivered (or the
        # deadline passes).
        logging.info(
            "[N-ACTION] tx=%s: origin STC mode - status-only RSP, "
            "%d SOP(s) registered for the origin's verdict",
            tx_uid,
            len(sop_list),
        )
    else:
        # Local heuristic. The tracker's `verify` (the SOP index + WADO-RS
        # path) decides per SOP on its own tick; this handler acknowledges
        # receipt and gets out of the way.
        #
        # The SOPs the RSP used to report as failures are NOT reported as
        # failures here: at this instant nothing has been checked, so a
        # 0x0110 for each of them would be a claim the bridge has no evidence
        # for. The N-EVENT-REPORT the tracker sends is where that verdict
        # legitimately appears.
        logging.info(
            "[N-ACTION] tx=%s: %d SOP(s) accepted for asynchronous "
            "verification (status-only RSP)",
            tx_uid,
            len(sop_list),
        )

    # Register the batch for the async N-EVENT-REPORT. A batch that cannot be
    # registered (no resolvable requestor address/port) would otherwise be
    # answered 0x0000 while its N-EVENT-REPORT can never go out, leaving the
    # Transaction UID hanging at the modality. Refuse with 0x0110 (Processing
    # Failure) so the SCU knows the request is not being processed.
    #
    # A request that NAMES SOPs has committed the SCP to reporting on them, so
    # it is refused when no tracker exists either: with `commit_tracker=None`
    # nothing was registered and nothing guarantees the N-EVENT-REPORT
    # (PS3.4 J.3.3.1 - the report IS the result), yet the request was
    # acknowledged 0x0000. Answering success for work that was silently
    # dropped is worse than refusing it.
    if sop_list:
        if commit_tracker is None:
            logging.error(
                "[N-ACTION] tx=%s references %d SOP(s) but no commitment "
                "tracker is available - refusing (no N-EVENT-REPORT possible)",
                tx_uid,
                len(sop_list),
            )
            return 0x0110, None
        if not _register_commit(
            commit_tracker,
            tx_uid,
            calling_ae,
            sop_list,
            event,
            resolve_scp=resolve_scp,
        ):
            return 0x0110, None

    # A correctly-parsed request is ALWAYS acknowledged 0x0000 (J.3.2.1.4: no
    # service-class specific values; RSP only says "received / not handling").
    # In false-mode success, partial and total failure differ ONLY by the
    # content of the Success / Failed SOP sequences built above; in true-mode
    # `rsp` is None (status-only) and every per-SOP outcome travels in the
    # async N-EVENT-REPORT, which is untouched here.
    return 0x0000, rsp

def _display_reason(reason, sop_uid):
    """Log helper: emits per-SOP WADO failure line, returns the reason code."""
    if reason == 0xC202:
        logging.warning(
            "  [N-ACTION] SOP %s: WADO-RS UNAVAILABLE -> FAILED (0xC202)", sop_uid
        )
    elif reason == 0xC210:
        logging.warning(
            "  [N-ACTION] SOP %s: WADO-RS ERROR -> FAILED (0xC210)", sop_uid
        )
    else:
        logging.warning(
            "  [N-ACTION] SOP %s: NOT CONFIRMED -> FAILED (0xC201)", sop_uid
        )
    return reason

# ---------------------------------------------------------------------------
# Bridge: handlers/cmove
# ---------------------------------------------------------------------------

"""Clarus Bridge  -  C-MOVE handler: WADO-RS streaming + C-STORE forwarding.

handle_c_move: accepts C-MOVE-RQ, creates job in queue, returns Pending.
_execute_cmove_job: streams study from Clarus, sends instances to target SCP.
_send_storage_commitment: pushes Storage Commitment N-ACTION after successful C-MOVE.

MAJ-002: _execute_cmove_job split into _associate_for_move() and _stream_and_send_study().
"""

import io
import json
import logging
import re
import shutil
import struct
import threading
import time
from urllib.parse import quote as _quote

# HTTP client + URL helpers for the R1 pre-flight (QIDO series lookup uses
# httpx via _qido_request; the per-series WADO metadata GET uses plain
# requests).
import httpx as _httpx
import requests
from pydicom import Dataset, dcmread
from pydicom.uid import (
    ExplicitVRLittleEndian,
    ImplicitVRLittleEndian,
    generate_uid,
)
from pynetdicom import AE
from pynetdicom.sop_class import (
    StorageCommitmentPushModel,
    Verification,
)

# TS-order constants (IMAGE_TS EVRLE-first etc.) live in clean_code.protocol
# (single definition - the bundle warns on duplicate module-level names).
# The main C-MOVE outbound association proposes each SOP class with its
# uncompressed family (EVRLE, IVRLE) first and then any stored/compressed
# transfer syntaxes from the pre-flight; negotiation is acceptor-driven, so a
# 4.80-capable viewer still negotiates 4.80 and a stored 4.80 sends as-is on
# the accepted 4.80 context.

# ---------------------------------------------------------------------------
# No probe/second association: the bridge NEVER opens one to a C-MOVE
# destination. The main association is the ONLY delivery association; a stored
# TS the viewer did not accept is either refetched on the MAIN association (if
# the server can produce an accepted TS) or fails honestly. There is no
# fallback/probe/reject-cache machinery. Retrying the main association is
# governed by the single outbound_assoc_attempts knob (PS3.8 9.1.4 Note 2
# leaves retry policy to the implementation).
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# per-thread flag to suppress pynetdicom noise during streaming/SC
# ---------------------------------------------------------------------------
# Thread-local, not a module global: the module global silenced pynetdicom
# logs for EVERY thread (C-STORE, C-FIND, incoming associations) while any
# single C-MOVE was streaming, hiding real errors from unrelated dialogs.
_suppress_state = threading.local()

class _SuppressPynetdicomFilter(logging.Filter):
    """Suppress pynetdicom logs only on the thread that requested it."""

    def filter(self, record):
        return not getattr(_suppress_state, "suppress", False)

_pynetdicom_suppress = _SuppressPynetdicomFilter()
logging.getLogger("pynetdicom").addFilter(_pynetdicom_suppress)

# Enrich pynetdicom timeout messages with context: which timer,
# inbound/outbound, AE title, timeout value.
import pynetdicom.association as _assoc_module

_original_assoc_error = _assoc_module.LOGGER.error

def _patched_assoc_error(msg, *args, **kwargs):
    if msg == "Network timeout reached":
        msg = (
            "Network timeout reached (idle socket > network_timeout - "
            "check inbound_network_timeout / outbound_network_timeout in config)"
        )
    elif msg and "DIMSE timeout reached" in str(msg):
        msg = (
            "DIMSE timeout reached (no response to command within dimse_timeout - "
            "check inbound_dimse_timeout / outbound_dimse_timeout in config)"
        )
    _original_assoc_error(msg, *args, **kwargs)

_assoc_module.LOGGER.error = _patched_assoc_error

# ---------------------------------------------------------------------------
# Bridge: C-MOVE  -  extract MoveDestination from C-MOVE-RQ
# ---------------------------------------------------------------------------
def _scoped_uid_values(ds, keyword):
    """Every usable value of a scoped identifier key, in request order.

    PS3.4 C.4.2.1.2 lists SeriesInstanceUID and SOPInstanceUID as single-value
    keys, but a sender may still put several values in one identifier, and
    PS3.4 Annex C.4.2 permits UID-list matching at the SERIES and IMAGE levels.
    Narrowing such a request to its first value silently dropped the rest: the
    bridge then answered Success for data it never sent.
    """
    raw = getattr(ds, keyword, None)
    if raw is None:
        return []
    if isinstance(raw, (str, bytes)):
        values = [str(raw).strip()]
    elif hasattr(raw, "__iter__"):
        values = [str(v).strip() for v in raw if v is not None and str(v).strip()]
    else:
        values = [str(raw).strip()]
    return [v for v in values if v]

def _parse_scoped_uid(ds, keyword, tag_text):
    """One SINGLE-VALUE scoped UID from the C-MOVE identifier.

    SeriesInstanceUID (0020,000E) and SOPInstanceUID (0008,0018) are Type 1
    single-value keys in the C-MOVE identifier (PS3.4 C.4.2.1.2), but a
    request can still carry several values. `str()` on a pydicom MultiValue
    renders the Python list ("['1.2.3', '1.2.4']"), which then becomes a path
    segment of the WADO-RS GET - an unroutable URL, a 404 and a failed job for
    what was a legitimate request.

    A value LIST is no longer truncated: `_scoped_uid_values` returns every
    value and the caller scopes one job per entry. This accessor answers the
    single-value case (no duplicates, one entry) and refuses a rendered
    container, which is the only remaining ambiguity.
    """
    values = _scoped_uid_values(ds, keyword)
    if not values:
        return ""
    if len(values) > 1:
        raise ValueError(f"C-MOVE-RQ: invalid {keyword} ({tag_text})")
    value = values[0]
    if "[" in value or "]" in value or "," in value:
        # A rendered container reached here (a caller stringified it before
        # storing it): `str(MultiValue)` -> "['1.2.3', '1.2.4']". Never let
        # that text into a URL path. A SINGLE-element container still scopes
        # one series/instance, so its UID is recovered; two or more values are
        # an identifier conflict the level cannot resolve, so they are refused
        # rather than silently narrowed to the first.
        inner = value.strip().strip("[]").strip()
        if "," in inner:
            raise ValueError(f"C-MOVE-RQ: invalid {keyword} ({tag_text})")
        head = inner.strip("'\"").strip()
        if not head or any(ch in head for ch in "[]'\" "):
            raise ValueError(f"C-MOVE-RQ: invalid {keyword} ({tag_text})")
        return head
    return value

def _parse_c_move_rq(event):
    """Extract StudyInstanceUID(s) and MoveDestination from C-MOVE-RQ.

    Returns (list_of_study_uids, move_dest_ae).
    Raises ValueError if StudyInstanceUID or MoveDestination is missing.

    MoveDestination (0000,0600) is a DIMSE command field, not an identifier
    element  -  accessed via event.move_destination in pynetdicom.

    A sender may put MULTIPLE StudyInstanceUIDs in a single C-MOVE-RQ.
    Discarding all but the first would silently drop studies, so every
    requested UID is processed.
    """
    move_dest = event.move_destination
    if not move_dest or str(move_dest).strip() == "":
        raise ValueError("C-MOVE-RQ: missing MoveDestination (0000,0600)")

    ds = event.identifier
    study_uid_raw = getattr(ds, "StudyInstanceUID", None)
    if not study_uid_raw or str(study_uid_raw).strip() == "":
        raise ValueError("C-MOVE-RQ: missing StudyInstanceUID (0020,000D)")

    # pynetdicom may return multi-valued StudyInstanceUID as list, tuple,
    # or pydicom MultiString (all iterable, none are str).
    # process ALL StudyInstanceUIDs in the request.
    if isinstance(study_uid_raw, str):
        study_uids = [str(study_uid_raw)]
    else:
        try:
            study_uids = [str(uid) for uid in list(study_uid_raw)]
        except (TypeError, IndexError):
            raise ValueError("C-MOVE-RQ: invalid StudyInstanceUID (0020,000D)")

    if not study_uids:
        raise ValueError("C-MOVE-RQ: empty StudyInstanceUID list")

    # PS3.4 C.4.2.1.2: the level decides the SCOPE. A SERIES-level C-MOVE must
    # retrieve the named series, not the whole study - ignoring the level
    # transferred every instance of the study to a viewer that asked for one
    # series. The identifier carries SeriesInstanceUID (0020,000E) at SERIES
    # and additionally SOPInstanceUID (0008,0018) at IMAGE.
    #
    # Both keys are UID-LIST matchable at these levels (PS3.4 Annex C.4.2), so
    # the values are returned as LISTS: the caller scopes one job per value and
    # the single-UID path is just the one-element case.
    level = str(getattr(ds, "QueryRetrieveLevel", "") or "").strip().upper()
    series_uids = _scoped_uid_values(ds, "SeriesInstanceUID")
    sop_uids = _scoped_uid_values(ds, "SOPInstanceUID")

    if level == "SERIES" and not series_uids:
        raise ValueError(
            "C-MOVE-RQ: SERIES level without SeriesInstanceUID (0020,000E)"
        )
    if level == "IMAGE" and not (series_uids and sop_uids):
        raise ValueError(
            "C-MOVE-RQ: IMAGE level without SeriesInstanceUID and "
            "SOPInstanceUID (0020,000E / 0008,0018)"
        )
    if level not in ("", "STUDY", "SERIES", "IMAGE"):
        # An unknown level cannot be honoured; refuse rather than fall back to
        # whole-study retrieval, which would hand the SCU data it did not ask
        # for (PS3.4 Table C.4-2 'Unable to process').
        raise ValueError(f"C-MOVE-RQ: unsupported QueryRetrieveLevel {level!r}")

    # A rendered container in a value list is a malformed identifier: refuse it
    # here rather than let "['1.2.3', '1.2.4']" reach a URL path.
    for value in series_uids + sop_uids:
        if any(ch in value for ch in "[]'\""):
            raise ValueError(f"C-MOVE-RQ: invalid scoped UID {value!r}")

    return study_uids, str(move_dest), level, series_uids, sop_uids

# One C-MOVE-RQ may scope several studies (Weasis sends a list) and, at the
# SERIES/IMAGE levels, several series or instance UIDs (PS3.4 Annex C.4.2
# permits UID-list matching). Each becomes its own job, because a job carries
# ONE scope and the worker no longer has the event. The cap bounds the work a
# single request can queue on this bridge; a request over it is refused with a
# stated reason rather than partially honoured, which would drop scopes
# silently.
_MAX_SCOPED_JOBS = 64

def _scope_cardinality(level, series_uids, sop_uids):
    """How many retrieval scopes a request names, WITHOUT expanding them.

    `_request_scopes` materialises the series-by-instance product for an IMAGE
    request, so a request naming 1000 series and 1000 instances allocated a
    million tuples before the caller's cap could reject it. The count is
    arithmetic on the input lengths, so the cap can be applied first and the
    allocation only ever happens for a request that fits.
    """
    if level == "IMAGE":
        return len(series_uids) * len(sop_uids)
    if level == "SERIES":
        return len(series_uids)
    return 1

def _request_scopes(level, series_uids, sop_uids):
    """`[(series_uid, sop_uid), ...]` - one entry per retrieval scope.

    STUDY scopes the whole study, so it carries neither key (the study UID
    already scopes it). IMAGE pairs each requested instance with its series
    and, when the sender gives several series for one instance list, every
    combination that can be addressed. SERIES carries one entry per series.

    Callers must check `_scope_cardinality` first: this function allocates the
    full product.
    """
    if level == "IMAGE":
        return [
            (series_uid, sop_uid) for series_uid in series_uids for sop_uid in sop_uids
        ]
    if level == "SERIES":
        return [(series_uid, "") for series_uid in series_uids]
    return [("", "")]

def _json_loads(payload):
    """json.loads over bytes/str - no new dependency, no external stream."""
    if isinstance(payload, (bytes, bytearray)):
        return json.loads(bytes(payload).decode("utf-8", "replace"))
    return json.loads(payload)

def split_multipart_parts(raw, boundary):
    """Split a multipart body into (headers_bytes, body_bytes) parts.

    Minimal, dependency-free (no python-multipart) parser for the PS3.18
    10.4.4 metadata response. `raw` is the bytes body; `boundary` is the
    Content-Type boundary parameter (already unquoted by the caller). A
    body of two consecutive boundaries (Preamble / Epilogue around the
    parts) is handled by dropping empty segments and lone boundary
    markers. Each returned part is (raw_header_bytes, raw_body_bytes) with
    the CRLFCRLF boundary removed. Returns [] on any structural failure.
    """
    try:
        if not raw or not boundary:
            return []
        if isinstance(raw, str):
            raw = raw.encode("utf-8")
        # Find every boundary line ("--boundary" as a whole line, i.e. on its
        # own line: preceded by CRLF or start-of-string; optionally followed
        # by "--" for the closing "--boundary--").
        delim = re.compile(
            rb"(?:\r\n|\r|\n|^)--" + re.escape(boundary.encode("utf-8")),
            re.MULTILINE,
        )
        # Content between two consecutive boundary lines is one part (headers
        # then a blank line then the body). The preamble before the first
        # boundary (often empty) is skipped.
        matches = list(delim.finditer(raw))
        parts = []
        for k in range(1, len(matches)):
            seg_start = matches[k - 1].end()
            seg_end = matches[k].start()
            # Drop an optional trailing CRLF that ends the previous segment
            # (it belongs to the boundary line break, not the part body).
            if raw[seg_start : seg_start + 2] == b"\r\n":
                seg_start += 2
            elif seg_start < len(raw) and raw[seg_start : seg_start + 1] == b"\n":
                seg_start += 1
            content = raw[seg_start:seg_end].rstrip(b"\r\n")
            # Skip empty segments (double boundaries / stray separators).
            if not content:
                continue
            sep = content.find(b"\r\n\r\n")
            if sep == -1:
                sep2 = content.find(b"\n\n")
                if sep2 == -1:
                    continue  # not a well-formed part (no header/body split)
                header_bytes = content[:sep2]
                body_bytes = content[sep2 + 2 :]
            else:
                header_bytes = content[:sep]
                body_bytes = content[sep + 4 :]
            parts.append((header_bytes, body_bytes))
        return parts
    except Exception:
        return []

# ---------------------------------------------------------------------------
# R1 pre-flight (0609): learn each class's stored TS BEFORE the association.
# Source: the standard per-instance metadata resource (PS3.18 10.4.4)
# /studies/{study}/series/{series}/instances/{sop}/metadata, whose elements
# ALWAYS carry (0002,0010) TransferSyntaxUID (and (0008,0016) SOPClassUID).
# Series are enumerated via QIDO-RS /studies/{study}/series, and the probe
# instance via QIDO-RS /studies/{study}/series/{series}/instances.
# ---------------------------------------------------------------------------
# TTL cache of successful pre-flights (0609 field): a repeated C-MOVE of
# the same study skips the probe walk (one QIDO instance list + one metadata
# GET per series) plus the association's wait on it. Failures are NOT cached
# - the degrade path must retry. A new stored TS appearing inside the TTL
# window stays deliverable: such an instance misses its context and takes the
# legacy fallback path (spec R4 rule 3).
_PREFLIGHT_TTL_S = 120.0
_preflight_cache = {}  # study_uid -> (expires_monotonic, result dict)

# Entries expire on their own deadline, but nothing removed them, so a bridge
# serving many studies grew this dict without bound (each value also holds a
# set per SOP class). The cap is generous against the TTL: at the observed
# rate a full 120 s window holds a few hundred entries, and 1024 is well past
# that while still bounding memory.
_CACHE_MAX_ENTRIES = 1024

def _cache_evict(cache, now):
    """Drop expired entries, then the oldest until the cache fits the cap."""
    for key, value in list(cache.items()):
        if now >= value[0]:
            # pop, not del: two workers can evict the same expired key, and a
            # plain `del` on the second one raised KeyError (a race on shared
            # mutable state with no lock). pop(key, None) is idempotent.
            cache.pop(key, None)
    if len(cache) <= _CACHE_MAX_ENTRIES:
        return
    # Oldest-expiring first: those are the entries closest to being useless.
    for key, _value in sorted(cache.items(), key=lambda kv: kv[1][0])[
        : len(cache) - _CACHE_MAX_ENTRIES
    ]:
        cache.pop(key, None)

def _split_preflight(result):
    """Normalise a pre-flight answer into `(map_or_None, partial)`.

    The walk returns `(map, partial)`. A caller (or a test) may hand back a
    bare map or None, which is the pre-batch-8 shape: that result carried no
    completeness signal, so it can only be treated as COMPLETE - filling in
    the registry from an answer of unknown coverage is what spent the whole
    context budget on classes the study does not hold.
    """
    if result is None:
        return None, False
    if isinstance(result, tuple):
        value, partial = (result + (False,))[:2]
        return value, bool(partial)
    return result, False

def _preflight_study_ts_by_class(
    study_uid,
    clarus_url,
    http_timeout=2.0,
    tls=None,
    budget_s=4.0,
    expose_rejected=False,
    qa_url="",
):
    """Return (dict[sop_class -> set[stored transfer syntax UID]], partial).

    `partial` is True when the walk could not cover every series (a timeout,
    a budget stop, a failed probe), so the class map is a SUBSET of the study.
    It is False for a complete walk, including the empty answer of a study
    with no series.

    The map is None when pre-flight cannot be completed at all.

    Used to shape the outbound association's per-TS contexts so the stored
    transfer syntax of every instance is PROPOSED and its acceptance is
    explicit at negotiation time (spec R1/R2). Failure is NEVER fatal: any
    error/timeout/404/over-budget returns None and the caller degrades to
    the fixed [EVRLE, IVRLE, 4.80, 4.70] proposal (today's behavior).

    1. QIDO series lookup /studies/{study}/series -> SeriesInstanceUIDs.
    2. Per series, QIDO instance list /studies/{study}/series/{series}/instances
       -> the FIRST instance's SOP Instance UID.
    3. Per series, WADO metadata for that ONE instance
       /studies/{study}/series/{series}/instances/{sop}/metadata
       (Accept application/dicom+json) -> (0008,0016) and (0002,0010).

    The series-level metadata resource renders every non-PixelData element of
    EVERY instance: measured on the stand, 432 instances answered 1.45 MB in
    663 ms while the same two tags from one instance answered 3.5 KB in 26 ms
    - about 100x the bytes and the time for the same answer, because the two
    tags repeat on every instance. A series-level response also costs more
    than the 2.0 s request timeout on the slow runs, which is why the old
    pre-flight lost the race and the proposal fell back to registry-wide.

    The probe is EVIDENCE BY CONVENTION, not by conformance: PS3.3 does not
    require every instance of a series to share a transfer syntax. That is
    acceptable because a wrong probe is RECOVERABLE - an instance whose
    stored TS misses its context takes the existing per-instance refetch
    path (R4 rule 3), which is unchanged. A probe that says nothing at all
    (today's degrading behaviour) is strictly worse.

    A series-level failure no longer abandons the study: a slow series 9 of
    30 used to discard the 8 series already probed, which left the caller
    with no stored-TS information at all. The probed series are returned and
    the missed instances fall back to the refetch path.

    The metadata resource is answered with the mandatory media type
    multipart/related; type="application/dicom+json" (PS3.18 10.4.4) - the
    single part is parsed; a plain application/dicom+json body is handled as
    before. Successful non-empty results are cached for _PREFLIGHT_TTL_S
    seconds.
    """
    _now = time.monotonic()
    # The cache key carries the expose mode: the two AEs see DIFFERENT instance
    # sets for the same study, so a shared entry would let a normal-AE job
    # propose contexts for instances it must not retrieve.
    _cache_key = (study_uid, bool(expose_rejected))
    _hit = _preflight_cache.get(_cache_key)
    if _hit is not None and _now < _hit[0]:
        logging.info(
            "[C-MOVE] pre-flight %s: cache hit (TTL %.0fs), %d class(es)",
            str(study_uid)[:50],
            _PREFLIGHT_TTL_S,
            len(_hit[1]),
        )
        return {k: set(v) for k, v in _hit[1].items()}, False
    _preflight_cache.pop(_cache_key, None)
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    start = time.monotonic()

    def _over_budget():
        return (time.monotonic() - start) >= budget_s

    def _normalize_rows(value):
        """Coerce a parsed metadata JSON value into a list of instance dicts.

        Some deployments answer WADO metadata as a single JSON array of
        instance objects; others (PS3.18 Annex F allows either a single
        array or one object per multipart part) answer as one JSON
        object per instance per multipart part. Accept a list (extend) or a
        bare dict (one instance). Anything else yields nothing.
        """
        if isinstance(value, list):
            return [v for v in value if isinstance(v, dict)]
        if isinstance(value, dict):
            return [value]
        return []

    def _parse_metadata_body(content_type, raw):
        """Parse the metadata response body into a list of JSON dicts.

        PS3.18 8.9.3 + 10.4.4: metadata is conveyed as the mandatory
        multipart/related media type. Two conformant shapes occur in the
        field:
          * one part whose payload is a JSON array of instance objects, or
          * one JSON object per instance, one instance per multipart part.
        Both are parsed here: when content_type starts with multipart/related
        the raw body is split on the boundary and EVERY part's payload is
        parsed (each as an array -> extended, or a bare object -> appended);
        otherwise the whole body is parsed directly as JSON. Returns [] on
        any parse failure.
        """
        ct = content_type or ""
        if not ct.lower().startswith("multipart/related"):
            try:
                rows = raw.json() if hasattr(raw, "json") else _json_loads(raw)
                return _normalize_rows(rows)
            except Exception:
                return []
        # Extract the boundary parameter, e.g.
        #   boundary="18d3aa...".
        boundary = ""
        for piece in ct.split(";"):
            piece = piece.strip()
            if piece.lower().startswith("boundary="):
                boundary = piece[len("boundary=") :].strip().strip('"')
                break
        if not boundary:
            return []
        try:
            body_bytes = raw.content if hasattr(raw, "content") else raw
            parts = split_multipart_parts(body_bytes, boundary)
            if not parts:
                return []
            out = []
            for _headers, body in parts:
                try:
                    out.extend(_normalize_rows(_json_loads(body)))
                except Exception:
                    # A malformed part must not sink a good response: skip it.
                    continue
            return out
        except Exception:
            return []

    # 1. enumerate series (QIDO-RS, same shape the series C-FIND step-b uses).
    # `_qido_request` returns the parsed JSON list (or []); a 4xx raises an
    # httpx.HTTPStatusError which is a subclass of httpx.HTTPError.
    try:
        series_url = f"{base}/studies/{_quote(study_uid, safe='')}/series"
        series_rows = _qido_request(series_url, {}, http_timeout, limit=None, tls=tls)
        if not isinstance(series_rows, (list, QidoPage)):
            raise ValueError("series QIDO did not return a JSON list")
    except (_httpx.HTTPError, ValueError, KeyError, TypeError):
        logging.debug(
            "[C-MOVE] pre-flight: series QIDO for %s failed - no stored-TS "
            "contexts proposed",
            str(study_uid)[:50],
        )
        return None, False
    if _over_budget():
        return None, False

    series_uids = []
    for row in series_rows:
        if not isinstance(row, dict):
            continue
        suid = _json_first_value(row, "0020000E")
        if suid:
            series_uids.append(suid)
    if not series_uids:
        # Empty study (no series) - nothing to pre-liquidate; caller uses the
        # default proposal and the study stream will simply return 0 parts.
        return {}, False

    result = {}
    probed = 0
    missed = 0
    # Set when a series was probed by a SINGLE instance: the class map then
    # samples the series rather than enumerating it (see the probe below).
    sampled_class_coverage = False
    for suid in series_uids:
        if _over_budget():
            # Circuit breaker only. With per-instance probes a 4.0 s budget
            # fits ~180 series (measured 22-26 ms each), so this firing means
            # the server is sick, not that the study is large.
            logging.warning(
                "[C-MOVE] pre-flight %s: budget %.1fs exhausted after %d/%d "
                "series - returning what was probed",
                str(study_uid)[:50],
                budget_s,
                probed,
                len(series_uids),
            )
            break
        try:
            inst_url = (
                f"{base}/studies/{_quote(study_uid, safe='')}"
                f"/series/{_quote(suid, safe='')}/instances"
            )
            inst_rows = _qido_request(inst_url, {}, http_timeout, limit=None, tls=tls)
            if not isinstance(inst_rows, (list, QidoPage)) or not inst_rows:
                missed += 1
                continue
            sop_uid = ""
            for inst_row in inst_rows:
                if not isinstance(inst_row, dict):
                    continue
                sop_uid = _json_first_value(inst_row, "00080018")
                if sop_uid:
                    # The first instance is the probe: measured 3.5 KB / 26 ms
                    # against 1.45 MB / 663 ms for the whole series. A second
                    # probe at the far end would catch a series mixed by two
                    # acquisitions, but this one already removes the whole
                    # reason the pre-flight was failing.
                    break
            # A series can hold MORE THAN ONE SOP class (a mixed acquisition,
            # or an SR written into an image series). One probed instance
            # therefore proves only that ONE class is present, so the class map
            # this study reports is a SAMPLE, not an inventory. The association
            # then has no context for a class the probe never saw, and refetch
            # cannot repair that: refetch can only choose among contexts the
            # association already accepted.
            #
            # The probe stays single (its cost is why it exists); the flag
            # below records that the walk's class coverage is unproven, so the
            # registry still supplies classes the sample could not rule out.
            sampled_class_coverage = True
            if not sop_uid:
                missed += 1
                continue
            meta_url = (
                f"{base}/studies/{_quote(study_uid, safe='')}"
                f"/series/{_quote(suid, safe='')}"
                f"/instances/{_quote(sop_uid, safe='')}/metadata"
            )
            mresp = requests.get(
                meta_url,
                headers={"Accept": "application/dicom+json"},
                timeout=http_timeout,
                cert=tls,
            )
            mresp.raise_for_status()
            _mh = getattr(mresp, "headers", {}) or {}
            rows = _parse_metadata_body(
                _mh.get("Content-Type", ""),
                mresp,
            )
            if not rows:
                # add ONE debug line with the reason so a failing field
                # pre-flight is not silent.
                logging.debug(
                    "[C-MOVE] pre-flight: metadata for series %s: %d bytes, "
                    "content-type=%s - no JSON rows parsed",
                    str(suid)[:50],
                    len(mresp.content) if hasattr(mresp, "content") else -1,
                    _mh.get("Content-Type", "?"),
                )
                missed += 1
                continue
        except Exception as _pref_exc:
            # ONE series failing must not discard the rest: the probed series
            # are real information, and the missed ones take the per-instance
            # refetch path (R4 rule 3) instead of costing the whole study its
            # stored-TS contexts.
            logging.debug(
                "[C-MOVE] pre-flight: probe for series %s failed (%s) - "
                "skipped, its instances fall back to per-instance refetch",
                str(suid)[:50],
                _pref_exc,
            )
            missed += 1
            continue
        probed += 1
        for inst in rows:
            if not isinstance(inst, dict):
                continue
            sop_class = _json_first_value(inst, "00080016")
            ts_uid = _json_first_value(inst, "00020010")
            if not sop_class:
                continue
            # The class is the fact that matters: it is KNOWN to be in the
            # study, so the proposal must carry it or the instances are
            # undeliverable whatever the syntax says. The stored syntax only
            # refines the proposal.
            #
            # Keeping the two together (the old rule: both or neither) meant a
            # sender that omits group 0002 - which standard DICOMweb metadata
            # MAY, PS3.18 10.4.4 only requires the dataset attributes - silently
            # dropped its class from the map. The association then never
            # proposed that class, so a passthrough origin could not deliver it
            # and no transcoding could recover it either: there was no context
            # to accept on.
            bucket = result.setdefault(sop_class, set())
            if ts_uid:
                bucket.add(ts_uid)
    # A class whose stored syntax never appeared keeps its EMPTY set: it is
    # still known to be in the study, so `_associate_for_move` proposes its
    # baseline pair and the per-instance refetch can find a target from the
    # server's capability list. Dropping it here is what made the class vanish.
    n_classes = len(result)
    n_ts = sum(len(v) for v in result.values())
    logging.info(
        "[C-MOVE] pre-flight %s: %d class(es), %d stored TS total from %d/%d "
        "probed series (%d not probed)",
        str(study_uid)[:50],
        n_classes,
        n_ts,
        probed,
        len(series_uids),
        missed,
    )
    # A partial walk must not be cached: the missed series would stay out of
    # the proposal for the whole TTL, and every C-MOVE in that window falls
    # back to the registry-wide set - the failure mode this probe exists to
    # remove. The partial result is still RETURNED below; it is useful for
    # this C-MOVE, it is just not remembered.
    if result and not missed and probed == len(series_uids):
        _preflight_cache[(study_uid, bool(expose_rejected))] = (
            time.monotonic() + _PREFLIGHT_TTL_S,
            {k: set(v) for k, v in result.items()},
        )
        _cache_evict(_preflight_cache, time.monotonic())
    # `partial` is what decides the registry fill-in: a walk that missed a
    # series, or whose per-series sample could not prove the series' class
    # set, has an INCOMPLETE class map, so the registry supplies the classes
    # it could not learn.
    partial = bool(missed) or probed != len(series_uids) or sampled_class_coverage
    return result, partial

# ---------------------------------------------------------------------------
# _study_sop_uids - ordered, de-duplicated SOP instance UID list of a study
# (PS3.18 10.4.4 metadata): the authoritative UNDELIVERED tail for
# the (0008,0058) Failed SOP Instance UID List on a GIVE_UP / partial final is
# computed as (this list) minus (the UIDs actually delivered across all
# resume passes). Kept separate from `_preflight_study_ts_by_class` so the
# negotiation map and its tests are untouched. Returns the ordered list of
# SOP UIDs, or None when the study metadata cannot be enumerated (the worker
# then degrades to the per-attempt failed list).
# ---------------------------------------------------------------------------
_study_sop_uids_cache = {}  # (study, expose, level, series, sop) -> (exp, uids)

def _study_sop_uids(
    study_uid,
    clarus_url,
    http_timeout=2.0,
    tls=None,
    budget_s=4.0,
    expose_rejected=False,
    qa_url="",
    request_level="",
    request_series_uid="",
    request_sop_uid="",
):
    """Return ordered, de-duplicated SOP instance UID list of a study from
    the standard per-instance metadata resources (PS3.18 10.4.4), or None if
    the study cannot be enumerated (best effort; the caller degrades).

    PS3.4 C.4.2.1.2: the list is filtered to the requested Query/Retrieve
    SCOPE. A SERIES-level C-MOVE must not enumerate (and later report) the
    study's other series, and an IMAGE-level one must not report its sibling
    instances - this list is the authority for `total` and for the (0008,0058)
    tail, so an unscoped list made a correctly-scoped transfer look partial.
    """

    def _normalize(value):
        if isinstance(value, list):
            return [v for v in value if isinstance(v, dict)]
        if isinstance(value, dict):
            return [value]
        return []

    def _parse_body(ct, raw):
        """Metadata body -> list of instance dicts (array part or object-per-
        part; mirrored from `_preflight_study_ts_by_class`)."""
        ctype = ct or ""
        try:
            if not ctype.lower().startswith("multipart/related"):
                rows = raw.json() if hasattr(raw, "json") else _json_loads(raw)
                return _normalize(rows)
            boundary = ""
            for piece in ctype.split(";"):
                piece = piece.strip()
                if piece.lower().startswith("boundary="):
                    boundary = piece[len("boundary=") :].strip().strip('"')
                    break
            if not boundary:
                return []
            body_bytes = raw.content if hasattr(raw, "content") else raw
            parts = split_multipart_parts(body_bytes, boundary)
            out = []
            for _h, body in parts:
                out.extend(_normalize(_json_loads(body)))
            return out
        except Exception:
            return []

    now = time.monotonic()
    # The cache key carries the SCOPE: a SERIES-scoped list must not be served
    # to a whole-study C-MOVE of the same study.
    _cache_key = (
        study_uid,
        bool(expose_rejected),
        request_level,
        request_series_uid,
        request_sop_uid,
    )
    hit = _study_sop_uids_cache.get(_cache_key)
    if hit is not None and now < hit[0]:
        return list(hit[1])
    _study_sop_uids_cache.pop(_cache_key, None)
    base = service_base_url(clarus_url, qa_url, expose_rejected)
    start = time.monotonic()

    def _over_budget():
        return (time.monotonic() - start) >= budget_s

    try:
        series_url = f"{base}/studies/{_quote(study_uid, safe='')}/series"
        series_rows = _qido_request(series_url, {}, http_timeout, limit=None, tls=tls)
    except Exception:
        return None
    series_uids = []
    if isinstance(series_rows, (list, QidoPage)):
        for row in series_rows:
            if isinstance(row, dict):
                s = _json_first_value(row, "0020000E")
                if s:
                    series_uids.append(s)
    # SERIES / IMAGE scope: only the series named in the request is walked.
    if request_level in ("SERIES", "IMAGE") and request_series_uid:
        series_uids = [s for s in series_uids if s == request_series_uid]
        if not series_uids:
            logging.info(
                "[C-MOVE] requested series %s is not in study %s - empty scope",
                str(request_series_uid)[:50],
                str(study_uid)[:50],
            )
    if not series_uids:
        return []
    uids = []
    seen = set()
    for suid in series_uids:
        if _over_budget():
            return None
        # Only the SOP Instance UIDs are needed, and the QIDO instance list
        # returns exactly those: one row per instance with (0008,0018) plus
        # InstanceNumber. The previous series-level /metadata call rendered
        # every non-PixelData element of every instance (measured 1.4 MB /
        # ~500 ms for a 432-instance series) and ran while the outbound
        # association was already open, so the viewer waited on a rendering
        # that carried nothing this function uses.
        inst_url = (
            f"{base}/studies/{_quote(study_uid, safe='')}"
            f"/series/{_quote(suid, safe='')}/instances"
        )
        try:
            inst_rows = _qido_request(inst_url, {}, http_timeout, limit=None, tls=tls)
        except Exception:
            return None
        if not isinstance(inst_rows, (list, QidoPage)):
            return None
        for inst in inst_rows:
            if not isinstance(inst, dict):
                continue
            sop = _json_first_value(inst, "00080018")
            # IMAGE scope: exactly one instance.
            if request_level == "IMAGE" and request_sop_uid:
                if sop != request_sop_uid:
                    continue
            if sop and sop not in seen:
                seen.add(sop)
                uids.append(sop)
    if uids:
        # The cache key carries the SCOPE: a SERIES-scoped list must not be
        # served to a whole-study C-MOVE of the same study.
        _study_sop_uids_cache[
            (
                study_uid,
                bool(expose_rejected),
                request_level,
                request_series_uid,
                request_sop_uid,
            )
        ] = (
            time.monotonic() + _PREFLIGHT_TTL_S,
            list(uids),
        )
        _cache_evict(_study_sop_uids_cache, time.monotonic())
    return uids

# ---------------------------------------------------------------------------
# (2608): self-delivery guard  -  is the target the bridge's own listener?
# ---------------------------------------------------------------------------
# The comparison rule lives in utils so the peer lookup in move_jobs can use
# the same one without importing a handler (manager -> handler is the wrong
# direction). Re-exported here under the name this module has always used.
_normalize_host = normalize_host

def _is_self_delivery_target(
    target_host, target_port, bridge_dimse_host, bridge_dimse_port
):
    """Return True if (target_host, target_port) is the bridge's own DIMSE listener.

    Loopback aliases (127.0.0.1, localhost, ::1) and bind-any addresses
    (0.0.0.0, ::) are treated as one endpoint: a peers.conf entry pointing
    at any alias with the bridge port would loop C-MOVE back into the
    bridge's own C-STORE SCP.
    """
    if bridge_dimse_port is None or target_port != bridge_dimse_port:
        return False
    if target_host is None:
        return False

    aliases = {"127.0.0.1", "::1"}
    if bridge_dimse_host:
        aliases.add(_normalize_host(bridge_dimse_host))
    return _normalize_host(target_host) in aliases

def _failure_dataset(uids, error_comment=None):
    """Response-Identifier Data Set for a non-success C-MOVE-RSP final status.

    - (0008,0058) Failed SOP Instance UID List (UI, VM 1-n): the SOP instance
      UIDs that were attempted but not delivered - PS3.4 Table C.4-2 requires
      Cancel, Failure and Warning to contain it (PS3.4 C.4.2.1.4.2).

    `error_comment` is logged, NOT carried in the Identifier: (0000,0902)
    Error Comment is a COMMAND-SET element (PS3.7 Table 9.1-1), and the
    C-MOVE-RSP Identifier is a data set. A command element in a data set is
    a protocol violation a strict SCU rejects.
    """
    if error_comment:
        logging.warning("[C-MOVE] %s", error_comment)
    ds = Dataset()
    if uids:
        try:
            ds.add_new((0x0008, 0x0058), "UI", [str(u) for u in uids])
        except Exception:
            pass
    return ds

# Bridge: C-MOVE handler  -  synchronous transfer with per-instance progress
def handle_c_move(
    event,
    move_jobs,
    peers_file,
    clarus_url,
    bridge_ae_title,
    http_timeout=30,
    sop_registry=None,
    storage_commit_after_move=True,
    sop_index=None,
    outbound_network_timeout=60,
    outbound_dimse_timeout=60,
    outbound_acse_timeout=15,
    bridge_dimse_host=None,
    bridge_dimse_port=None,
    move_poll_timeout=600,
    tls=None,
    expose_rejected=False,
    qa_url="",
):
    """Handle C-MOVE-RQ: fire-and-forget dispatch + held reactor for the final.

    DICOM PS3.4 sec.C.4.2.2: the SCP shall have prior knowledge of the
    Move Destination AE Title and Presentation Address.

    Combo model (fire-and-forget + DB-polling for the final response):
    - jobs are created in SQLite; _cmove_worker pool streams in background
      (worker threads associate and send C-STORE, independently of reactor)
    - yield (addr, port) -> pynetdicom primes store_assoc
    - reactor is DELIBERATELY held: the generator polls job progress from
      the DB (0.5 s interval, bounded by move_poll_timeout) until every job
      is terminal, and only then emits the pending-count int + final status
    - success -> yield 0 (zero sub-operations): pynetdicom sends the final
      0000 immediately and opens no store_assoc
    - failure / cancel -> yield 1, then the honest final status (0xB000 or
      0xC000 / 0xFE00) with its (0008,0058) Identifier

    Pending C-MOVE-RSPs are optional (PS3.4 C.1.4) and the bridge does not
    send them: the final response is delayed until the transfer actually
    finishes (so its timing and statuses stay honest), and the final
    sub-operation counters reflect the sub-operations the DIMSE framework
    performed synchronously  -  which in this fire-and-forget model is zero.

    The reactor is freed only after the final response  -  NOT after dispatch:
    this protects SCUs that treat the final C-MOVE-RSP as "all stores done".

    Actual transfer runs in _cmove_worker thread pool.
    Real progress tracked via Prometheus metrics + job status.

    Self-delivery guard (2608): if the resolved Move Destination is the
    bridge's own DIMSE listener (host/port match incl. loopback aliases),
    the request is rejected with 0xA801 before any job is created.

    Poll timeout (2608): the progress poll is bounded by move_poll_timeout;
    on expiry unfinished jobs are finished as failed and 0xB000 is returned.
    """
    calling_ae = event.assoc.requestor.ae_title
    model_uid = str(event.context.abstract_syntax) if event.context else "?"

    # DEBUG: log full C-MOVE-RQ identifier to diagnose Weasis multi-study import
    ds = event.identifier
    patient_id = (
        str(getattr(ds, "PatientID", "")).strip() if hasattr(ds, "PatientID") else ""
    )
    study_uid = (
        str(getattr(ds, "StudyInstanceUID", "")).strip()
        if hasattr(ds, "StudyInstanceUID")
        else ""
    )
    logging.info(
        "[DIMSE] C-MOVE from %s model=%s PatientID=%s StudyUID=%s",
        calling_ae,
        model_uid,
        mask_patient_id(patient_id) if patient_id else "(none)",
        study_uid[:50] if study_uid else "(none)",
    )

    try:
        (
            study_uids,
            move_dest_ae,
            request_level,
            request_series_uids,
            request_sop_uids,
        ) = _parse_c_move_rq(event)
    except ValueError as e:
        # An unhonourable level (SERIES without a series UID, an unknown
        # level) arrives here: refusing is right, because falling back to
        # whole-study retrieval would send the viewer data it did not ask for.
        #
        # The refusal is 0x0110 (Processing Failure) with NO address yield.
        # The old path yielded 0xC000 as the destination pair, which
        # pynetdicom 3.0.4 reads as (address, port): the port was None, so it
        # answered 0xA801 "Move Destination unknown" instead - a wrong status
        # for a malformed request, and the honest one is only reachable by
        # yielding the status first.
        logging.warning("[C-MOVE] Parse error: %s", e)
        yield 0x0110, None
        return

    if peers_file:
        move_jobs.reload_peers_from_file(peers_file)

    calling_ip = event.assoc.requestor.address
    target = move_jobs.lookup_scp(move_dest_ae, client_ip=calling_ip)
    if target is None:
        logging.warning(
            "[C-MOVE] Unknown Move Destination: %s. Add '%s  <IP>:<port>' to peers.conf.",
            move_dest_ae,
            move_dest_ae,
        )
        yield 0xA801, None
        return

    target_host, target_port = target

    # P2 (2608): CIDR peers entries carry an informational host  -  the real
    # destination is the calling client itself (subnet match, PS3.4 sec.C.4.2.2).
    # Without substitution _associate_for_move would get the CIDR string and
    # silently fail to associate.
    #
    # The REGISTRY key and the CONNECTION address are kept apart: replacing
    # `target_host` wholesale made every later `record_scp_success/failure`
    # name the client IP, while `scp_targets` is keyed by the configured host,
    # so a subnet-backed peer never had its failure streak updated (an exact
    # `(ae_title, host)` UPDATE matched no row). The client IP is used to
    # connect; the configured key is what gets recorded.
    registry_host = target_host
    if "/" in target_host:
        logging.info(
            "[C-MOVE] Move Destination %s: CIDR host %s is informational - "
            "routing via calling client IP %s.",
            move_dest_ae,
            target_host,
            calling_ip,
        )
        target_host = calling_ip

    # (2608): self-delivery guard  -  never C-STORE back into the bridge's
    # own DIMSE listener. Field incident: misconfigured peers.conf pointed
    # the Move Destination at the bridge itself; the bridge answered its own
    # C-STORE with success and the viewer received nothing.
    if _is_self_delivery_target(
        target_host, target_port, bridge_dimse_host, bridge_dimse_port
    ):
        logging.warning(
            "[C-MOVE] Move Destination %s resolves to the bridge itself "
            "(%s:%d) - rejecting with 0xA801 (self-delivery loop).",
            move_dest_ae,
            target_host,
            target_port,
        )
        yield 0xA801, None
        return

    if _normalize_host(target_host) != _normalize_host(calling_ip):
        logging.warning(
            "[C-MOVE] IP MISMATCH: %s registered at %s but C-MOVE from %s "
            "(normalised: %s vs %s).",
            move_dest_ae,
            target_host,
            calling_ip,
            _normalize_host(target_host),
            _normalize_host(calling_ip),
        )
        yield 0xA801, None
        return

    # create a job for EACH requested scope.
    #
    # Weasis sends multiple StudyUIDs in one C-MOVE-RQ - process them all.
    # A SERIES- or IMAGE-level request can carry several SeriesInstanceUID /
    # SOPInstanceUID values too (PS3.4 Annex C.4.2 permits UID-list matching
    # at both levels), and narrowing that to the first value queued one series
    # while the final response still said Success for the others.
    #
    # The number of jobs is capped by `_MAX_SCOPED_JOBS` so one request cannot
    # queue an unbounded amount of work on this bridge; the excess is refused
    # LOUDLY rather than dropped, because a silent drop is the defect.
    # The cap is checked TWICE, and the order matters:
    #   1. on the cardinality, computed from the input lengths, so an absurd
    #      request is refused before `_request_scopes` allocates the
    #      series-by-instance product (1000 x 1000 tuples used to be built
    #      first and rejected afterwards);
    #   2. on the study-multiplied plan, because one request can name several
    #      studies as well as several scopes.
    scope_count = _scope_cardinality(
        request_level, request_series_uids, request_sop_uids
    )
    if study_uids:
        scope_count *= len(study_uids)
    if scope_count > _MAX_SCOPED_JOBS:
        logging.warning(
            "[C-MOVE] Request scopes %d retrievals (%d studies x %d scope "
            "values) - over the %d limit, refusing the whole request",
            scope_count,
            len(study_uids),
            scope_count // max(1, len(study_uids)),
            _MAX_SCOPED_JOBS,
        )
        yield 0xC000, _failure_dataset(
            [],
            error_comment=(
                f"Unable to process: request scopes {scope_count} retrievals, "
                f"over the {_MAX_SCOPED_JOBS} limit"
            ),
        )
        return

    scope_pairs = _request_scopes(request_level, request_series_uids, request_sop_uids)
    if not study_uids or not scope_pairs:
        yield 0x0110, None
        return

    planned = [
        (study, series_uid, sop_uid)
        for study in study_uids
        for series_uid, sop_uid in scope_pairs
    ]
    if len(planned) > _MAX_SCOPED_JOBS:
        logging.warning(
            "[C-MOVE] Request scopes %d retrievals (%d studies x %d scope "
            "values) - over the %d limit, refusing the whole request",
            len(planned),
            len(study_uids),
            len(scope_pairs),
            _MAX_SCOPED_JOBS,
        )
        yield 0xC000, _failure_dataset(
            [],
            error_comment=(
                f"Unable to process: request scopes {len(planned)} retrievals, "
                f"over the {_MAX_SCOPED_JOBS} limit"
            ),
        )
        return

    job_ids = []
    for study_uid, series_uid, sop_uid in planned:
        job_id = move_jobs.create_job(
            study_uid,
            move_dest_ae,
            target_host,
            target_port,
            expose_rejected=expose_rejected,
            request_level=request_level,
            request_series_uid=series_uid,
            request_sop_uid=sop_uid,
            registry_host=registry_host,
            # HELD, not pending: no worker may start the first scope while the
            # rest of this request is still being inserted and its
            # cancellation state is not installed yet. Released in one UPDATE
            # below, after the callbacks are in place.
            claimable=False,
        )
        job_ids.append(job_id)
        logging.info(
            "[C-MOVE] Job #%d created for Study %s%s%s -> %s (level=%s)",
            job_id,
            study_uid,
            f" series {series_uid}" if series_uid else "",
            f" instance {sop_uid}" if sop_uid else "",
            move_dest_ae,
            request_level or "STUDY",
        )

    logging.info(
        "[C-MOVE] Move Destination: %s -> %s:%d, Studies: %d, jobs: %d (%s)",
        move_dest_ae,
        target_host,
        target_port,
        len(study_uids),
        len(job_ids),
        ", ".join(study_uids),
    )

    # Set cancel callback on ALL jobs.
    #
    # `hasattr(event, "is_cancelled")` is NOT a harmless probe: on a
    # pynetdicom service event the name is a property that READS the
    # association's cancel state, and that read consumes a C-CANCEL already
    # received. Probing with it therefore discarded a cancel that arrived
    # before this point, and every later poll saw False. Presence is
    # decided on the TYPE, which never invokes the getter.
    #
    # The state is also LATCHED: one property read per poll writes True into a
    # holder both the poller and the worker read, so whichever of them asks
    # first cannot swallow the cancel out from under the other.
    class _CancelState:
        __slots__ = ("cancelled",)

        def __init__(self):
            self.cancelled = False

    _cancel_state = _CancelState()
    _has_cancel = getattr(type(event), "is_cancelled", None) is not None or (
        "is_cancelled" in getattr(event, "__dict__", {})
    )

    def _is_cancelled():
        # Read at most once per poll and remember a True: the property is
        # consumed by reading it, so a second reader in the same window would
        # otherwise see the state already drained.
        if _cancel_state.cancelled:
            return True
        if not _has_cancel:
            return False
        state = event.is_cancelled
        if state() if callable(state) else state:
            _cancel_state.cancelled = True
            return True
        return False

    for job_id in job_ids:
        move_jobs.set_job_cancel_callback(job_id, _is_cancelled)

    # PUBLICATION BARRIER. Every scope above was inserted as 'held'. Nothing
    # could claim one; the cancellation callback above is the last piece of
    # request state a worker reads. Releasing in a single UPDATE means a worker
    # either sees no row at all or a row whose cancel callback is already
    # installed - never the first scope of a request that is still being
    # built, and never a job that reports is_job_cancelled() == False because
    # the callback had not been registered yet.
    move_jobs.release_held_jobs(job_ids)

    def _clear_callbacks():
        # Terminal cleanup: the callback closes over `event` (and through it
        # the association). Leaving it in the registry keeps the whole
        # request object alive for the life of the process, so the terminal
        # path drops it once every job is finished and no worker will poll it
        # again.
        for job_id in job_ids:
            move_jobs.clear_job_callback(job_id)

    def _latch_cancelled():
        # Cancel path: the callback also closes over `event`, so it must be
        # dropped - but CLEARING it makes the worker's is_job_cancelled() see
        # "no callback" -> False, so a worker mid-stream would keep sending
        # the rest of the study (and push Storage Commitment) after the
        # reactor already answered Cancel. The latch answers True forever and
        # holds NO reference to `event`: the worker reads "cancelled", stops,
        # and removes the latch itself in its own finally.
        #
        # Only jobs that still have a WORKER get a latch. A job the reactor
        # just marked finished (or one that finished on its own) has nobody
        # left to read it, and a job nobody ever claimed has no worker to
        # stop - installing a latch there left an entry in the callback
        # registry that nothing would ever remove.
        for job_id in job_ids:
            try:
                _c, _t, status = move_jobs.get_job_progress(job_id)
            except Exception:
                status = None
            if status in ("success", "failed", "cancelled"):
                move_jobs.clear_job_callback(job_id)
                continue
            if not move_jobs.job_has_live_worker(job_id):
                move_jobs.clear_job_callback(job_id)
                continue
            move_jobs.set_job_cancel_callback(job_id, lambda: True)

    # yield 1: (addr, port)  -  pynetdicom primes store_assoc
    yield (target_host, target_port)

    def _agg_failed_uids():
        """(0008,0058) material across all finished jobs (PS3.4 C.4.2.1.4.2)."""
        out = []
        for job_id in job_ids:
            getter = getattr(move_jobs, "get_job_failed_sops", None)
            if getter is None:
                continue
            try:
                for u in getter(job_id):
                    if u and u not in out:
                        out.append(u)
            except Exception:
                continue
        return out

    def _scan_jobs():
        """`(completed, failed_tally, all_finished, any_failed)` right now.
        poll: a job can finish between an earlier snapshot and the timeout
        branch, and a stale zero-completed snapshot then answered 0xC000
        ("nothing delivered") for a transfer that had just completed.

        `failed_tally` is the number of instances the finished jobs accounted
        for as NOT delivered. It is what the final response reports, because
        pynetdicom copies the yielded count into
        NumberOfFailedSuboperations and NumberOfCompletedSuboperations.
        """
        completed_total = 0
        failed_tally = 0
        finished = True
        failed_job = False
        for job_id in job_ids:
            c, t, status = move_jobs.get_job_progress(job_id)
            completed_total += c
            if status not in ("success", "failed"):
                finished = False
            else:
                failed_tally += max(0, t - c)
                if status == "failed":
                    failed_job = True
        return completed_total, failed_tally, finished, failed_job

    def _finish_jobs_cancelled():
        # LATCH FIRST, then finish. `finish_job` makes the row terminal, and a
        # terminal job has no reader left - latching afterwards therefore
        # looked at a finished row and skipped every job, so each worker's
        # `is_job_cancelled()` read False and kept streaming the study
        # (including its Storage Commitment) after the SCU had been told the
        # move was cancelled.
        _latch_cancelled()
        for job_id in job_ids:
            if move_jobs.finish_job(
                job_id, success=False, error_message="Cancelled by SCU"
            ):
                # Count only when THIS call finished the job: the worker can
                # finish it first, and a second counter bump would double-count.
                move_jobs_counter.labels(status="failed").inc()

    # yield 2+: hold the DIMSE dialog (0.5 s DB poll, bounded by
    # move_poll_timeout) until every job is terminal  -  the final response is
    # not emitted until the transfer actually finishes. Pending C-MOVE-RSPs
    # are optional (PS3.4 C.1.4) and the bridge does not send them, so no
    # per-instance progress yield occurs; the pending-count int is emitted
    # only once the poll concludes.
    logging.info(
        "[C-MOVE] %d job(s) dispatched to worker (polling DB for progress)",
        len(job_ids),
    )

    # P3 (2608): bound the poll with an overall timeout. If a worker dies
    # between picking a job and finishing it, the viewer must get 0xB000
    # instead of a hung association.
    poll_started = time.monotonic()

    # The bare count yielded just before a terminal status decides whether
    # pynetdicom 3.0.4 reads that status at all. Its C-MOVE SCP branch
    #
    #     if nr_suboperations < 1:
    #         rsp.Status = 0x0000
    #         self.dimse.send_msg(rsp, cx_id)
    #         return            # the generator is NOT read again
    #
    # sends 0x0000 Success and stops reading, so yielding 0 before an honest
    # 0xB000/0xC000 replaced the failure with Success. The count is therefore
    # the tally the WORKERS produced (see below), and it is only ever 0 for a
    # confirmed all-success transfer.
    #
    # pynetdicom counts the sub-operations per Pending response. Because the
    # bridge performs the stores on its OWN association, a Pending yield is
    # never emitted, so the framework's counters are whatever this generator
    # hands it as the initial count minus nothing - which makes that number the
    # one the SCU reads as "failed" and "completed". That is why it is the real
    # tally and not the study size.
    while True:
        if _is_cancelled():
            _finish_jobs_cancelled()
            # Non-empty sub-operation count so pynetdicom keeps the dialog
            # open for the Cancel status yield below.
            yield 1
            # PS3.4 Table C.4-2 FE00 Cancel; C.4.2.1.4.2: the Identifier
            # carries (0008,0058) Failed SOP Instance UID List (may be empty).
            yield 0xFE00, _failure_dataset(_agg_failed_uids())
            return

        # Aggregate terminal state across all jobs
        total_completed, failed_tally, all_finished, any_failed = _scan_jobs()

        # 0 is reserved for a CONFIRMED all-success transfer. On a failure path
        # the counters cannot prove completeness: `_stream_and_send_study`
        # writes total = idx + 1 per instance as it streams, so
        # completed == total holds for a job that delivered its last instance
        # and then lost the association. A 0 there makes pynetdicom send 0x0000
        # Success and stop reading, and the 0xB000/0xC000 never reaches the
        # viewer. Keep the dialog open with a non-zero count.
        #
        # The count handed to pynetdicom is the tally the WORKERS produced, not
        # the study's size: the framework counts sub-operations itself and
        # writes its counters into the final RSP, and since the bridge does the
        # storing on its own association the framework performs none of them.
        # `failed_tally` carries the undelivered instances so a partial move
        # reports both sides honestly instead of "N failed, 0 completed".
        failure_extra = failed_tally
        if all_finished:
            if any_failed:
                failed_uids = _agg_failed_uids()
                # Two yields, not one tuple: the reactor protocol is a bare
                # sub-operation count followed by (status, identifier).
                #
                # The count is the number of instances the WORKERS accounted
                # for, not the study's size. pynetdicom counts the
                # sub-operations itself (`store_results`) and writes its own
                # numbers into the final RSP - and since the bridge delivers
                # over its own association, the framework performs NONE of the
                # stores, so a count of N made the SCU read "N failed, 0
                # completed" for a transfer that had in fact delivered most of
                # them. Yielding the real tally keeps the response honest while
                # still being non-zero, which is what keeps the dialog open for
                # the status yield below.
                yield max(1, total_completed + failure_extra)
                if total_completed == 0:
                    # Zero sub-operations completed: B000 ("Sub-operations
                    # Complete") would be a lie - say Failure (PS3.4 Table
                    # C.4-2, "Failed: Unable to process") with an honest
                    # Error Comment (PS3.4 C.4.2.1.4.2 Identifier).
                    comment = "Unable to process: no SOP instances delivered"
                    yield 0xC000, _failure_dataset(
                        failed_uids,
                        error_comment=comment,
                    )
                else:
                    # Partial: some sub-operations failed -> Warning (Table
                    # C.4-2) + (0008,0058) Failed SOP Instance UID List.
                    yield 0xB000, _failure_dataset(failed_uids)
            else:
                # All jobs succeeded. Yield 0 sub-operations: pynetdicom
                # short-circuits to 0x0000 and opens NO move-destination
                # association (which would raise, since the SCP AE has no
                # requested contexts). A non-zero count made pynetdicom open
                # store_assoc and answer 0xC515.
                yield 0
            _clear_callbacks()
            return

        # P3 (2608): poll timeout  -  finish unfinished jobs as failed, then
        # report the honest failure/warning. The reactor releases the
        # association after the final yields.
        if (
            move_poll_timeout is not None
            and time.monotonic() - poll_started >= move_poll_timeout
        ):
            timed_out_jobs = []
            for job_id in job_ids:
                _, _, job_status = move_jobs.get_job_progress(job_id)
                if job_status not in ("success", "failed"):
                    if move_jobs.finish_job(
                        job_id, success=False, error_message="Move poll timeout"
                    ):
                        # Count only when THIS call finished the job.
                        move_jobs_counter.labels(status="failed").inc()
                        timed_out_jobs.append(job_id)
            # The worker streams instances and only finishes the job when it
            # runs out of them, so marking the row failed is not enough: it
            # would keep sending and then rewrite the row to success. The
            # cancel state is what the worker already polls per instance.
            _cancel_state.cancelled = True
            # Re-read the terminal state AFTER the timeout transitions: a job
            # may have finished successfully between the snapshot above and
            # here, and the earlier zero-completion view then answered 0xC000
            # ("nothing delivered") for a transfer that just completed.
            (
                _completed_after,
                _failed_after,
                _finished_after,
                _any_failed_after,
            ) = _scan_jobs()
            if _finished_after and not _any_failed_after:
                # Every job completed on its own before the timeout landed.
                logging.warning(
                    "[C-MOVE] Move poll timeout (%ds) expired, but every job "
                    "finished successfully - reporting Success",
                    move_poll_timeout,
                )
                yield 0
                _clear_callbacks()
                return
            logging.warning(
                "[C-MOVE] Move poll timeout (%ds) expired: %d job(s) still "
                "unfinished (%s) - finished as failed, final status %s.",
                move_poll_timeout,
                len(timed_out_jobs),
                (
                    ", ".join(str(j) for j in timed_out_jobs)
                    if timed_out_jobs
                    else "(none)"
                ),
                "0xC000" if _completed_after == 0 else "0xB000",
            )
            yield max(1, _completed_after + _failed_after)
            failed_uids = _agg_failed_uids()
            if _completed_after == 0:
                # Nothing delivered before the poll timeout -> Failure, not a
                # "sub-operations complete" Warning (PS3.4 Table C.4-2).
                yield 0xC000, _failure_dataset(
                    failed_uids,
                    error_comment="Unable to process: no SOP instances delivered (move poll timeout)",
                )
            else:
                yield 0xB000, _failure_dataset(failed_uids)
            _latch_cancelled()
            return

        time.sleep(0.5)

# ---------------------------------------------------------------------------
# Bridge: Storage Commitment push after C-MOVE (CMP-008)
# ---------------------------------------------------------------------------
# PS3.4 J.3.2: the N-ACTION primitive operates on the Storage Commitment
# Push Model's CONSTANT well-known SOP Instance (conceptually created at SCP
# startup). The Transaction UID is NOT the Affected SOP Instance UID - it
# travels inside the data set as (0008,1195). Sending the Transaction UID as
# the instance UID makes a strict SCP reject the request it cannot correlate.
WELL_KNOWN_SOP_INSTANCE_UID = "1.2.840.10008.1.20.1.1"

def _send_storage_commitment(
    move_dest_ae, target_host, target_port, sop_list, bridge_ae_title, assoc=None
):
    """Send N-ACTION Storage Commitment Request to move destination AE.

    `assoc` is the C-MOVE association that just delivered `sop_list`. It is
    reused when Storage Commitment was negotiated on it, which is the normal
    case: `_associate_for_move` proposes the push-model context up front, so
    the N-ACTION rides a context that already exists instead of paying a
    second ACSE round trip to the same peer. The old separate association is
    kept only as the fallback for a caller that has no live association.

    Args:
        move_dest_ae: AE Title of the move destination (SCU)
        target_host: IP/hostname of the move destination
        target_port: port of the move destination
        sop_list: list of (sop_class_uid, sop_instance_uid) tuples
        bridge_ae_title: Bridge's own AE Title
        assoc: live association to the move destination, or None

    Returns:
        True if commitment request was sent successfully.
    """
    logging.info(
        "[C-MOVE-COMMIT] Sending Storage Commitment to %s@%s:%d for %d SOPs",
        move_dest_ae,
        target_host,
        target_port,
        len(sop_list),
    )

    # `owned_assoc` is the association THIS call opened (fallback path); it is
    # the only one this call may release. On the reuse path the caller still
    # owns `assoc` and releases it itself.
    owned_assoc = None
    if assoc is None or not assoc.is_established:
        ae = AE(ae_title=bridge_ae_title)
        # Storage Commitment is optional (PS3.4 sec.C.4.2.5). Fast-fail ACSE:
        # if viewer doesn't respond in 3s, it doesn't support SC. Don't
        # waste 10s on a feature that most viewers don't implement.
        ae.network_timeout = 5
        ae.acse_timeout = 3
        ae.dimse_timeout = 30
        # Symmetric with nevent.py: bound the raw TCP connect too, or a
        # black-hole peer holds this fallback association on the OS SYN
        # timeout. 5 s matches the fast-fail ACSE posture below.
        ae.connection_timeout = 5
        ae.add_requested_context(StorageCommitmentPushModel)
        ae.add_requested_context(
            Verification
        )  # Fallback: allows association even if no SC support

        # suppress pynetdicom's "No accepted presentation contexts" ERROR  -
        # it's normal for SCPs that don't support Storage Commitment.
        _suppress_state.suppress = True
        try:
            owned_assoc = ae.associate(target_host, target_port, ae_title=move_dest_ae)
        finally:
            _suppress_state.suppress = False
        assoc = owned_assoc
    if not assoc.is_established:
        logging.info(
            "[C-MOVE-COMMIT] SCP %s:%d unavailable - skipping Storage Commitment",
            target_host,
            target_port,
        )
        return False

    sc_accepted = any(
        str(ctx.abstract_syntax) == StorageCommitmentPushModel
        for ctx in assoc.accepted_contexts
    )
    if not sc_accepted:
        logging.info(
            "[C-MOVE-COMMIT] SCP %s does not support Storage Commitment - skipping",
            move_dest_ae,
        )
        if owned_assoc is not None:
            _release_or_abort(owned_assoc, timeout=2.0)
        return False

    try:
        # Build N-ACTION request dataset
        ds = Dataset()
        ds.TransactionUID = generate_uid()

        ref_seq = []
        for sop_class, sop_uid in sop_list:
            item = Dataset()
            item.ReferencedSOPClassUID = sop_class
            item.ReferencedSOPInstanceUID = sop_uid
            ref_seq.append(item)
        ds.ReferencedSOPSequence = ref_seq

        # Send N-ACTION with action type 1 (Storage Commitment Request)
        # pynetdicom 3.x signature: send_n_action(dataset, action_type, class_uid,
        #   meta_uid=None, instance_uid=None)
        # action_type=1 (PS3.4 sec.J.3.1), class_uid=StorageCommitmentPushModel.
        # instance_uid is the well-known constant (PS3.4 J.3.2); the
        # Transaction UID already travels in the data set as (0008,1195).
        status, response = assoc.send_n_action(
            ds,
            1,  # action_type: Storage Commitment Request (PS3.4 sec.J.3.1)
            StorageCommitmentPushModel,
            instance_uid=WELL_KNOWN_SOP_INSTANCE_UID,
        )

        if status:
            status_code = status.Status if hasattr(status, "Status") else status
            # PS3.4 J.3.2 + PS3.7: the Storage Commitment Push Model N-ACTION
            # Response carries exactly two outcomes - 0x0000 (Success: the
            # transaction was opened) and 0x0110 (Processing Failure). The
            # Warning class there is 0x0107/0x0116 (attribute notes); 0x0001 and
            # 0x0002 are the C-* space "warning - SOP class/instance not
            # supported", which this service does not define at all. Claiming a
            # commitment for them reported a transaction no SCP holds; only
            # Success means the SCP accepted the request.
            if status_code == 0x0000:
                logging.info(
                    "[C-MOVE-COMMIT] %s: Storage Commitment %s.",
                    move_dest_ae,
                    _dimse_status_name(status_code),
                )
                return True
            # Any non-Success answer - warning included - is non-fatal: the move
            # already succeeded and Storage Commitment is optional (PS3.4
            # C.4.2.5). Non-fatal is not the same as successful, hence False.
            logging.warning(
                "[C-MOVE-COMMIT] %s: Storage Commitment %s - not committed. "
                "Non-fatal (SC optional, PS3.4 C.4.2.5).",
                move_dest_ae,
                _dimse_status_name(status_code),
            )
            return False
        else:
            logging.warning(
                "[C-MOVE-COMMIT] N-ACTION no status returned for %s",
                move_dest_ae,
            )
            return False
    except Exception as e:
        logging.warning(
            "[C-MOVE-COMMIT] N-ACTION failed for %s: %s",
            move_dest_ae,
            e,
        )
        return False
    finally:
        # Only an association this call opened is this call's to release: the
        # caller's own association outlives the N-ACTION.
        if owned_assoc is not None:
            _release_or_abort(owned_assoc, timeout=2.0)

# ---------------------------------------------------------------------------
# Lazy-load Clarus capabilities (GET /dicomweb) at first C-MOVE.
# Don't query at startup  -  server may not be running yet.
# Query on first use, cache result, fall back to defaults if unreachable.
# ---------------------------------------------------------------------------
_TS_NAMES = {
    "1.2.840.10008.1.2": "Implicit VR Little Endian",
    "1.2.840.10008.1.2.1": "Explicit VR Little Endian",
    "1.2.840.10008.1.2.1.99": "Deflated Explicit VR Little Endian",
    "1.2.840.10008.1.2.2": "Explicit VR Big Endian",
    "1.2.840.10008.1.2.4.50": "JPEG Baseline",
    "1.2.840.10008.1.2.4.51": "JPEG Extended",
    "1.2.840.10008.1.2.4.57": "JPEG Lossless SV1",
    "1.2.840.10008.1.2.4.70": "JPEG Lossless SV1 (first-order)",
    "1.2.840.10008.1.2.4.80": "JPEG-LS Lossless",
    "1.2.840.10008.1.2.4.81": "JPEG-LS Near-Lossless",
    "1.2.840.10008.1.2.4.90": "JPEG 2000 Lossless",
    "1.2.840.10008.1.2.4.91": "JPEG 2000",
    "1.2.840.10008.1.2.4.92": "JPEG 2000 Part 2",
    "1.2.840.10008.1.2.5": "RLE Lossless",
}

def _ts_name(uid):
    """Human-readable transfer syntax name for CAPS logging.

    Was a NameError before: the helper was called but never defined, so the
    whole caps fetch died and the bridge always fell back to passthrough.
    """
    return _TS_NAMES.get(uid, uid)

def _get_clarus_transfer_syntaxes(clarus_url, timeout=5.0, tls=None):
    """Query Clarus /dicomweb for transfer syntax capabilities.

    Result is cached in the function's closure after first success.

    IMPORTANT: CAPS announces only encode-capable
    transcode-target codecs. An empty CAPS means "no transcoding available,
    request without ?transferSyntax=, receive stored bytes as-is."
    Bridge MUST NOT invent capabilities the server doesn't claim.

    NB: "MUST NOT invent" applies to *compressed*
    transcode targets - we never refetch to a compressed TS the server did
    not announce. It does NOT exclude EVRLE: a transcode-capable server is
    expected to be able to return the standard default EVRLE representation
    (PS3.18 8.7.3.1), so `_pick_refetch_ts` adds EVRLE on its own when
    `server_ts_list` is non-empty. On a no-transcode server (this list empty)
    nothing - including EVRLE - is invented or requested.

    Args:
        clarus_url: Clarus DICOMweb base URL (single knob, 2908).
        timeout: HTTP request timeout in seconds.
        tls: optional (cert_path, key_path) tuple for mTLS.

    Returns:
        List of transfer syntax UID strings (empty if server can't transcode).
    """
    cache_key = clarus_url
    if not hasattr(_get_clarus_transfer_syntaxes, "cache"):
        _get_clarus_transfer_syntaxes.cache = {}
    cache = _get_clarus_transfer_syntaxes.cache
    cached_entry = cache.get(cache_key)
    if cached_entry:
        ts_list, cached_at = cached_entry
        if time.time() - cached_at < 60:
            return ts_list

    ts_list = []
    base = dicomweb_base(clarus_url)
    try:
        resp = requests.get(
            base,
            timeout=timeout,
            cert=tls,
        )
        resp.raise_for_status()
        caps = resp.json()
        tc_list = caps.get("transferCapabilities")
        if tc_list:
            for tc in tc_list:
                ts_list.extend(tc.get("transferSyntaxUid", []))
            ts_list = sorted(set(ts_list))
            logging.info(
                "[CAPS] %s -> %d transfer syntax(es):",
                base,
                len(ts_list),
            )
            for ts in ts_list:
                logging.info("[CAPS]   %s", _ts_name(ts))
        elif tc_list is not None:
            # Empty array []  -  server honestly reports: no transcoding.
            logging.info(
                "[CAPS] Server %s: empty transferCapabilities - "
                "passthrough mode (no transcoding, bridge will not request ?transferSyntax=)",
                clarus_url,
            )
        else:
            # null/absent  -  treat as empty (no transcode).
            logging.info(
                "[CAPS] Server %s: no transferCapabilities field - " "passthrough mode",
                clarus_url,
            )
    except Exception as e:
        logging.warning(
            "[CAPS] Clarus %s unreachable: %s - assuming passthrough mode",
            clarus_url,
            e,
        )
        ts_list = []

    _get_clarus_transfer_syntaxes.cache[cache_key] = (ts_list, time.time())
    return ts_list

# ---------------------------------------------------------------------------
# _associate_for_move  -  establish C-STORE association with target SCP
# ---------------------------------------------------------------------------
def _is_image_sop(sop_uid, sop_registry=None):
    """Check sop_registry for the non_image flag, fall back to the prefix
    heuristic. Non-image SOPs (SR/PR/RTSTRUCT) are always sent as-is."""
    if sop_registry and sop_uid in sop_registry:
        entry = sop_registry[sop_uid]
        if isinstance(entry, dict) and entry.get("non_image"):
            return False
    # Fallback prefix heuristic
    _PFX = (
        "1.2.840.10008.5.1.4.1.1.88.",
        "1.2.840.10008.5.1.4.1.1.11.",
        "1.2.840.10008.5.1.4.1.1.104.",
        "1.2.840.10008.5.1.4.1.1.66.",
    )
    _EXACT = {
        "1.2.840.10008.5.1.4.1.1.481.3",
        "1.2.840.10008.5.1.4.1.1.481.4",
        "1.2.840.10008.5.1.4.1.1.481.5",
        "1.2.840.10008.5.1.4.1.1.481.6",
        "1.2.840.10008.5.1.4.1.1.481.7",
        "1.2.840.10008.5.1.4.1.1.481.8",
        "1.2.840.10008.5.1.4.1.1.481.9",
    }
    if sop_uid in _EXACT:
        return False
    return not sop_uid.startswith(_PFX)

def _proposed_ts_per_class(sop_registry):
    """Yield the storage SOP classes (as UIDs) this bridge will propose on a
    C-MOVE outbound association.

    PS3.8 7.1.1.13: a presentation context = one abstract syntax + a list of
    transfer syntaxes. Proposing the SAME abstract syntax several times, once
    per transfer syntax (the multi-context shape), is conformance-legal and is
    exactly the arrangement PS3.7 C.2.2.1.1 wants: the C-STORE dataset is
    encoded in the negotiated transfer syntax of the presentation context that
    is used, so per-TS contexts let the bridge pick the context whose transfer
    syntax equals the instance's stored transfer syntax.
    """
    if sop_registry is not None:
        return list(_get_sop_registry_uids(sop_registry))
    return list(_BUILTIN_SOP_CLASSES())

# Context-ID budget for one A-ASSOCIATE (PS3.8 7.1.1.13: Presentation Context
# IDs are the odd bytes 1..255, so at most 128 contexts). 1 is reserved for
# the Storage Commitment context proposed on the main association.
_MAX_CONTEXTS = 128

# Bytes read from the head of a refetched instance to locate its file meta
# group. A Part 10 preamble plus group 0002 is tens of bytes; 64 KiB is a
# whole-megabyte-plus margin that still never pulls a dataset into memory.
_FILE_META_PROBE = 64 * 1024

# Bounded copy size for rebuilding a refetched instance behind a length-changing
# file-meta prefix. One MiB keeps the copy at the same footprint as the download
# loop above and never scales with the instance, which is the point: the refetch
# path must not allocate in proportion to the blob it is rewriting.
_TAIL_COPY_CHUNK = 1024 * 1024

def _trim_optional_ts(num_classes, has_sc, optional_tokens):
    """Return the subset of optional tokens that fit the 128-context budget.

    optional_tokens: list of (sop_class_uid, ts_uid, kind) in canonical
    ascending order, where kind is 'stored' (a class's stored TS from
    pre-flight) or 'fixed' (the 4.80/4.70 extras of the pre-flight-less path).
    Each class always keeps its 2 baselines (EVRLE, IVRLE), which are never
    dropped (they are the refetch targets).

    The class is part of the token because the budget is shared: dropping a
    token identified only by its transfer syntax would remove that syntax from
    EVERY class, so one overfull class would cost another class a syntax it
    actually needed.

    Real studies propose far fewer than 128 contexts; this runs only as a
    defensive trim. Drop order (spec 12 / R2): stored extras first in
    reverse canonical priority (lowest-priority stored TS first), and the
    4.80/4.70 'fixed' extras only after every stored extra is gone.
    """
    fixed = 1 if has_sc else 0
    budget = _MAX_CONTEXTS - fixed - (2 * num_classes)
    if budget >= len(optional_tokens):
        return optional_tokens
    # Victim order: stored extras dropped from the LOWEST canonical priority
    # (largest canonical rank) upward first; fixed extras only after all
    # stored extras are gone. `stored` group sorts before `fixed` so the
    # fixed 4.80/4.70 extras survive longer.
    _group = {"stored": 0, "fixed": 1}

    def _victim_key(item):
        _sop_uid, ts_uid, kind = item
        # within stored: drop higher canonical index first (lower priority)
        rank = canonical_ts_sort_key(ts_uid)
        return (_group.get(kind, 1), -rank)

    victims = sorted(optional_tokens, key=_victim_key)
    drop_n = len(optional_tokens) - budget
    dropped = {tok for tok in victims[: max(0, drop_n)]}
    return [tok for tok in optional_tokens if tok not in dropped]

# ---------------------------------------------------------------------------
# Per-peer job gate
# ---------------------------------------------------------------------------
# Two jobs toward the SAME peer are serialized (busy exclusion): the second
# waits only while the first is actively running and then starts
# immediately. There is no post-job cooldown; the gate opens as soon
# as the peer is free.
# No client-specific logic involved - the gate applies equally to any peer.
_ASSOC_GATE_LOCK = threading.Lock()
_ASSOC_BUSY = {}  # peer -> (owner_thread_ident, acquisition_depth)
# Peer -> monotonic time of the LAST "busy - waiting" DEBUG line (throttled
# to at most one per _ASSOC_GATE_LOG_INTERVAL seconds, C3).
_ASSOC_GATE_LOG_LAST = {}
_ASSOC_GATE_LOG_INTERVAL = 10.0

class _AssocGateAborted(Exception):
    """The peer gate was abandoned because the bridge is stopping or the job
    was cancelled. Separate from RuntimeError so a caller can distinguish
    "could not get the peer" from "we gave up waiting for it"."""

    def __init__(self, host, port, ae_title):
        super().__init__(f"{ae_title}@{host}:{port}: gate wait abandoned")
        self.host = host
        self.port = port
        self.ae_title = ae_title

def _try_reserve_peer(host, port, ae_title):
    """Reserve the peer for THIS thread without blocking; True on success.

    The reservation is what makes "do not park a worker on a peer another
    worker just claimed" enforceable: it is one atomic test-and-set under the
    gate lock, so two workers cannot both observe the peer free and then claim
    two jobs for it. The winner claims a job immediately afterwards; the loser
    leaves the row pending and looks at another peer, so a job for a DIFFERENT
    peer is never left unserved behind a blocking wait.

    Re-entrant for the owning thread, counted like `_job_gate_enter`, so a
    resume path that reserves again unwinds with the matching exits.
    """
    key = (host, port, ae_title)
    me = threading.get_ident()
    with _ASSOC_GATE_LOCK:
        owner = _ASSOC_BUSY.get(key)
        if owner is not None and owner[0] != me:
            return False
        _ASSOC_BUSY[key] = (me, owner[1] + 1) if owner else (me, 1)
        return True

def _job_gate_enter(host, port, ae_title, give_up=None):
    """Serialise concurrent jobs toward the same peer (busy exclusion).

    Waits until the peer has no actively running job, then marks it busy and
    returns; there is no post-job cooldown (immediate start once free).

    RE-ENTRANT for the thread that already owns the peer: a worker that holds
    a claimed job and reaches the gate again (the resume path re-associates,
    and any helper that runs the same job re-takes the gate) used to block on
    a gate it was holding itself - forever. The owner is recorded per peer and
    the same thread passes straight through, with the acquisition counted so
    the matching `_job_gate_exit` calls unwind it.

    The wait is bounded by `give_up` (a zero-arg predicate): shutdown and
    job cancellation both end a wait that could otherwise last as long as a
    slow peer holds the gate, which is what made a stopped bridge hang on the
    worker join. Raises `_AssocGateAborted` when the predicate fires.

    Logging: the per-tick "busy - waiting" DEBUG line is throttled to
    no more than one per _ASSOC_GATE_LOG_INTERVAL (default 10 s) seconds per
    peer, and exactly ONE line is emitted on entry carrying the total time
    the caller waited for the peer.
    """
    key = (host, port, ae_title)
    me = threading.get_ident()
    started = time.monotonic()
    waited_any = False
    if give_up is None:
        give_up = _shutdown_requested.is_set
    while True:
        with _ASSOC_GATE_LOCK:
            owner = _ASSOC_BUSY.get(key)
            if owner is None:
                _ASSOC_BUSY[key] = (me, 1)
                if waited_any:
                    logging.info(
                        "[ASSOC-GATE] %s@%s:%s waited %.1fs for the peer",
                        ae_title,
                        host,
                        port,
                        time.monotonic() - started,
                    )
                return
            if owner[0] == me:
                # Same thread, same peer: it already holds the claim, so
                # waiting here would deadlock against itself.
                _ASSOC_BUSY[key] = (me, owner[1] + 1)
                return
            waited_any = True
        if give_up():
            logging.info(
                "[ASSOC-GATE] %s@%s:%s abandoned after %.1fs (stopping)",
                ae_title,
                host,
                port,
                time.monotonic() - started,
            )
            raise _AssocGateAborted(host, port, ae_title)
        # Sleep OUTSIDE the lock so other workers can gate.
        now = time.monotonic()
        with _ASSOC_GATE_LOCK:
            last = _ASSOC_GATE_LOG_LAST.get(key, 0.0)
            if now - last >= _ASSOC_GATE_LOG_INTERVAL:
                _ASSOC_GATE_LOG_LAST[key] = now
                logging.debug(
                    "[ASSOC-GATE] %s@%s:%s busy - waiting for it to free",
                    ae_title,
                    host,
                    port,
                )
        time.sleep(0.05)

def _peer_is_busy(host, port, ae_title):
    """True when another thread holds the gate for this peer (R9).

    An advisory read only: it is NOT the claim. `_try_reserve_peer` is what a
    worker must go through, because a read followed by a separate claim lets
    two workers both see the peer free.
    """
    key = (host, port, ae_title)
    with _ASSOC_GATE_LOCK:
        owner = _ASSOC_BUSY.get(key)
        return owner is not None and owner[0] != threading.get_ident()

def _job_gate_exit(host, port, ae_title):
    """Release the peer so the next queued job to it can start."""
    key = (host, port, ae_title)
    with _ASSOC_GATE_LOCK:
        owner = _ASSOC_BUSY.get(key)
        me = threading.get_ident()
        if owner is not None and owner[0] == me:
            # Nested acquisition by the owner: unwind one level.
            if owner[1] > 1:
                _ASSOC_BUSY[key] = (me, owner[1] - 1)
                return
        _ASSOC_BUSY.pop(key, None)
        # Drop the throttle timestamp so the next wait starts clean.
        _ASSOC_GATE_LOG_LAST.pop(key, None)

def _associate_for_move(
    move_dest_ae,
    bridge_ae_title,
    sop_registry,
    target_host,
    target_port,
    network_timeout=60,
    dimse_timeout=60,
    acse_timeout=15,
    outbound_assoc_attempts=3,
    study_ts_by_class=None,
    partial_preflight=False,
):
    """Establish C-STORE association with target SCP (multi-context).

    Standard-shaped negotiation (PS3.8 7.1.1.13 +
    9.3.2.2, PS3.7 C.2.2.1.1): each SOP class is proposed as ONE presentation
    context per transfer syntax, in canonical order (uncompressed family
    first, then compressed). This lets the acceptor accept exactly the
    transfer syntaxes it supports and the SCU pick the context whose TS
    matches each instance's stored TS.

    Proposal per class:
    - WITH pre-flight (`study_ts_by_class` set): [EVRLE, IVRLE] + the class's
      stored TS set from the pre-flight (single-TS contexts, dedup).
    - WITHOUT pre-flight: [EVRLE, IVRLE, 4.80, 4.70] (today's IMAGE_TS as
      separate contexts - preserves the negotiated outcomes of 4.80-capable
      receivers; see test_bridge_ts_order.py).
    Non-image classes (SR/PR/RTSTRUCT) keep the uncompressed family plus any
    stored extras seen.

    Budget: total contexts + Storage Commitment <= 128 (PS3.8, PCID 1..255
    odd). Overflow trims stored extras in reverse canonical priority, then the
    4.80/4.70 extras; EVRLE/IVRLE are never trimmed (refetch targets).

    Args:
        move_dest_ae: AE Title of the move destination.
        bridge_ae_title: Bridge's own AE Title.
        sop_registry: SOP class registry dict.
        target_host: IP/hostname of the move destination.
        target_port: port of the move destination.
        network_timeout: socket-level (outbound, viewer may be slow).
        dimse_timeout: per C-STORE response (outbound).
        acse_timeout: A-ASSOCIATE negotiation.
        outbound_assoc_attempts: total A-ASSOCIATE attempts (main), immediate.
        study_ts_by_class: dict[sop_class -> set[ts]] from pre-flight, or None.
        partial_preflight: True when `study_ts_by_class` covers only PART of
            the study. The registry fill-in (proposing classes the pre-flight
            could not learn) runs only then; a complete pre-flight already
            names the study's real class set.

    Returns:
        (assoc, accepted_contexts_map) tuple.
        accepted_contexts_map: dict[sop_class_uid -> SET[ts]].

    Raises:
        RuntimeError if association fails after all attempts.
    """
    ae = AE(ae_title=bridge_ae_title)
    ae.network_timeout = network_timeout
    ae.acse_timeout = acse_timeout
    ae.dimse_timeout = dimse_timeout
    # `connection_timeout` is the ONLY bound on the raw TCP connect:
    # pynetdicom does `socket.settimeout(assoc.connection_timeout)` before
    # `connect()`, and the AE default (None) leaves a black-hole peer parked
    # on the OS SYN timeout for minutes per attempt - while this worker holds
    # the per-peer gate, so two such jobs block every C-MOVE. The ACSE
    # timeout is a sane connect bound (same order as the negotiation itself).
    ae.connection_timeout = acse_timeout

    # Proposal is shaped from the canonical order: uncompressed family first,
    # then compressed in the taxonomy order (RLE, JPEG lossless, JPEG-LS,
    # JPEG lossy, JPEG 2000). Deterministic proposer order; a
    # conforming acceptor (PS3.8 9.3.2.2) accepts per-context by its own
    # support set, so proposer order is not a correctness input for standard
    # peers - only deterministic output for the bridge.
    # Field-observed: the registry-wide proposal
    # overflows the 128-context budget. With pre-flight knowledge the
    # proposal covers ONLY the classes the study actually contains
    # (PS3.18 10.4.4 metadata is per-instance, so its class map is the
    # study's real class set); the pre-flight-less legacy path keeps the
    # registry-wide proposal, subject to the whole-class budget drop
    # below.
    has_preflight = bool(study_ts_by_class)
    if has_preflight:
        class_uids = sorted(study_ts_by_class.keys())
        # A pre-flight that timed out or answered only partly covers a SUBSET
        # of the classes. Proposing just that subset made every unlearned
        # class fail with "no presentation context" - a whole SOP class
        # silently dropped from the move because of a partial answer. Learn
        # what we can and fall back to the registry for the rest.
        #
        # The fill-in runs ONLY on a PARTIAL pre-flight. Keying it on "a
        # registry was supplied" meant the full registry was added to EVERY
        # move: with a 60+ class registry the baseline pairs alone then ate
        # the 128-context budget, `_trim_optional_ts` was left with a
        # non-positive budget, and the study's OWN stored syntaxes (RLE,
        # JPEG-LS, J2K) were trimmed away - so a compressed study on a
        # passthrough server proposed only EVRLE/IVRLE and every instance
        # failed the send-path decision.
        if sop_registry is not None and partial_preflight:
            known = set(class_uids)
            missing = sorted(
                uid for uid in _proposed_ts_per_class(sop_registry) if uid not in known
            )
            if missing:
                logging.info(
                    "[C-MOVE] partial pre-flight covers %d class(es); "
                    "proposing %d registry class(es) alongside",
                    len(known),
                    len(missing),
                )
                class_uids = sorted(known | set(missing))
    else:
        class_uids = _proposed_ts_per_class(sop_registry)
    # Per-class optional (non-baseline) TS, in canonical ascending order, each
    # tagged 'stored' (from pre-flight) or 'fixed' (4.80/4.70, no pre-flight).
    per_class_optional = {}
    for sop_uid in class_uids:
        is_image = _is_image_sop(sop_uid, sop_registry)
        if has_preflight:
            stored = set(study_ts_by_class.get(sop_uid, set()) or set())
            stored = {
                t
                for t in stored
                if t not in (ExplicitVRLittleEndian, ImplicitVRLittleEndian)
            }
            per_class_optional[sop_uid] = [
                (sop_uid, t, "stored")
                for t in sorted(stored, key=canonical_ts_sort_key)
            ]
        else:
            extra = [JPEGLS_LOSSLESS_TS, "1.2.840.10008.1.2.4.70"] if is_image else []
            per_class_optional[sop_uid] = [
                (sop_uid, t, "fixed")
                for t in extra
                if t not in (ExplicitVRLittleEndian, ImplicitVRLittleEndian)
            ]
    flat = [tok for cls in per_class_optional.values() for tok in cls]
    # NOTE: the optional-TS trim runs AFTER the whole-class drop below. It used
    # to run here, against the FULL class list: with a large registry the
    # baselines alone exceeded the budget, `_trim_optional_ts` got a
    # non-positive budget and dropped every stored token - and the class drop
    # that followed removed fill-in classes but brought no stored token back.
    # Trim what actually survived, so the syntaxes a class really needs are
    # only sacrificed when the surviving classes genuinely do not fit.
    proposals = {}
    for sop_uid in class_uids:
        proposals[sop_uid] = [ExplicitVRLittleEndian, ImplicitVRLittleEndian]

    # PS3.8 7.1.1.13: PCIDs are the odd bytes 1..255 -> at most 128
    # contexts, one reserved for Storage Commitment. Baselines alone can
    # overflow on the registry-wide (pre-flight-less) proposal: drop WHOLE
    # classes from the END of the list (reverse registry priority) until
    # the budget fits. Never truncate a class's own baseline pair -
    # EVRLE/IVRLE are the refetch targets (spec R2).
    #
    # A class the pre-flight actually SAW is never a drop candidate: it is
    # known to be in the study, so dropping it makes the move silently
    # incomplete. The registry fill-in classes (CM7) are the ones dropped.
    budget = _MAX_CONTEXTS - 1  # Storage Commitment slot
    observed = set(study_ts_by_class.keys()) if has_preflight else set()
    protected = set(observed)
    if len(protected) * 2 > budget:
        logging.warning(
            "[C-MOVE] %d class(es) known to be in the study need %d baseline "
            "contexts, over the %d budget - the excess may be dropped",
            len(protected),
            len(protected) * 2,
            budget,
        )
        protected = set()
    while sum(len(v) for v in proposals.values()) > budget:
        candidates = [uid for uid in proposals if uid not in protected]
        if not candidates:
            # Every remaining class is one the pre-flight actually observed, so
            # dropping one would make the move silently incomplete. The
            # baselines still do not fit, which means the study itself has more
            # SOP classes than 128 PCIDs can carry (PS3.8 7.1.1.13). Keep the
            # proposal within the limit rather than raising: the classes that
            # survive are still delivered, and the drop is logged as the
            # incompleteness it is. Raising here failed the whole move for a
            # study wide enough to trip this - the SCU got a Failure with no
            # instance transferred at all.
            while sum(len(v) for v in proposals.values()) > budget:
                dropped_cls = list(proposals)[-1]
                dropped_ts = proposals.pop(dropped_cls)
                protected.discard(dropped_cls)
                logging.error(
                    "[C-MOVE] 128-context budget (PS3.8 7.1.1.13): study needs "
                    "more SOP classes than one association can propose - "
                    "dropped OBSERVED class %s (%d TS contexts); its "
                    "instances cannot be delivered",
                    dropped_cls,
                    len(dropped_ts),
                )
            break
        dropped_cls = candidates[-1]
        dropped_ts = proposals.pop(dropped_cls)
        logging.info(
            "[C-MOVE] 128-context budget (PS3.8 7.1.1.13): dropped class "
            "%s (%d TS contexts) from the proposal",
            dropped_cls,
            len(dropped_ts),
        )

    # Optional-TS trim, over what SURVIVED the class drop: the classes still
    # proposed keep their stored syntaxes as far as the budget allows.
    survivors = set(proposals)
    flat = [
        tok
        for cls_uid, toks in per_class_optional.items()
        if cls_uid in survivors
        for tok in toks
    ]
    # ORDER MATTERS: the whole-class drop above runs first, and the STORED
    # syntaxes of classes the pre-flight proved are in scope are reserved
    # before any speculative token is considered. The old order let a registry
    # guess take the last free slot and then trimmed away the stored syntax of
    # a class KNOWN to be in the study - invisible on a transcoding origin,
    # fatal on a passthrough one, where it is the only form that can be sent.
    reserved = [tok for tok in flat if tok[2] == "stored"]
    speculative = [tok for tok in flat if tok[2] != "stored"]
    # Storage Commitment is always requested on this association.
    _room = (_MAX_CONTEXTS - 1) - (2 * len(survivors)) - len(reserved)
    if _room >= len(speculative):
        kept_tokens = set(reserved) | set(speculative)
    elif _room <= 0:
        if speculative:
            logging.warning(
                "[C-MOVE] 128-context budget: %d stored syntax(es) reach the "
                "limit - dropping %d speculative context(s)",
                len(reserved),
                len(speculative),
            )
        # PS3.8 7.1.1.13 caps PCIDs at 128, and the Storage Commitment context
        # is one of them. The stored syntaxes the pre-flight actually observed
        # are what makes a passthrough origin deliverable, so they OUTRANK the
        # registry fill-in classes: drop speculative classes first, and only
        # trim a stored syntax when the budget is exhausted even without them.
        # The baseline pair of every surviving class stays - EVRLE/IVRLE are
        # the refetch targets, so a class with neither cannot be recovered.
        _cap = _MAX_CONTEXTS - 1
        while len(reserved) + 2 * len(survivors) > _cap:
            drop_candidates = [uid for uid in proposals if uid not in protected]
            if not drop_candidates:
                # Every remaining class is observed. Failing here would refuse
                # the whole move, so trim a stored syntax instead - the same
                # overflow guard, one level down.
                break
            dropped_cls = drop_candidates[-1]
            dropped_ts = proposals.pop(dropped_cls)
            survivors.discard(dropped_cls)
            # The class is gone from the proposal, so its stored token must go
            # with it: leaving it in `reserved` would spend a context on a
            # class no longer requested and could overflow the very budget this
            # loop is protecting.
            reserved = [tok for tok in reserved if tok[0] != dropped_cls]
            logging.info(
                "[C-MOVE] 128-context budget: dropped speculative class %s "
                "(%d TS contexts) to keep %d observed stored syntax(es)",
                dropped_cls,
                len(dropped_ts),
                len(reserved),
            )
        _stored_room = max(0, _cap - (2 * len(survivors)))
        if len(reserved) > _stored_room:
            logging.warning(
                "[C-MOVE] 128-context budget: %d stored syntax(es) exceed the "
                "%d slot(s) left after %d class baseline(s) - keeping the "
                "first %d in canonical order",
                len(reserved),
                _stored_room,
                len(survivors),
                _stored_room,
            )
            reserved = reserved[:_stored_room]
        kept_tokens = set(reserved)
    else:
        logging.info(
            "[C-MOVE] 128-context budget: kept %d speculative context(s) of "
            "%d after reserving %d stored syntax(es)",
            int(_room),
            len(speculative),
            len(reserved),
        )
        kept_tokens = set(reserved) | set(speculative[: int(_room)])
    for tok in flat:
        if tok in kept_tokens:
            sop_uid, ts_uid, _kind = tok
            if ts_uid not in proposals[sop_uid]:
                proposals[sop_uid].append(ts_uid)

    # ----- add requested contexts -----
    contexts_req = 0
    for sop_uid in proposals:
        for ts_uid in proposals[sop_uid]:
            ae.add_requested_context(sop_uid, ts_uid)
            contexts_req += 1
    contexts_dropped = len(
        [
            tok
            for cls_uid, toks in per_class_optional.items()
            for tok in toks
            if cls_uid not in survivors
        ]
    ) + (len(flat) - len(kept_tokens))

    # Storage Commitment on the main association, as today (a separate SC
    # association burned ACSE timeouts; see _send_storage_commitment).
    ae.add_requested_context(StorageCommitmentPushModel)

    # ----- main association with retries (single config knob) + outcome -----
    # Classify the associate() outcome. pynetdicom 3.0.4 returns a
    # non-established Association for TCP connect-refused/RST/timeout AND for
    # ACSE silence (the latter two are indistinguishable at the API boundary,
    # both `is_established == False`); it RAISES only for terminal local/
    # lookup/transport errors (e.g. socket.gaierror on DNS). Therefore:
    #   * an exception from associate()  -> TERMINAL transport -> NO retry
    #     (immediate failure; retrying a dead/unresolvable peer is only noise -
    #      PS3.8 9.1.4 Note 2: retry policy is implementation freedom);
    #   * a non-established return        -> ACSE-retry per outbound_assoc_attempts
    #     (a live peer whose ACSE is momentarily silent may come back, existing
    #      behaviour). Refused and silent are indistinguishable at this API
    #      boundary, so both take the retry path.
    attempts = max(1, int(outbound_assoc_attempts or 3))
    assoc = None
    outcome = None  # 'established' | 'acse-retry' | 'terminal' (last attempt)
    for attempt in range(1, attempts + 1):
        try:
            assoc = ae.associate(target_host, target_port, ae_title=move_dest_ae)
        except (OSError, RuntimeError) as _tcp_err:
            # Terminal transport: connection refused/RST/DNS/lookup surfaced as
            # an exception - no point retrying a peer/protocol that is down.
            outcome = "terminal"
            logging.error(
                "[C-MOVE] %s@%s:%s: terminal transport (attempt %d/%d) - "
                "not retrying: %s: %s",
                move_dest_ae,
                target_host,
                target_port,
                attempt,
                attempts,
                type(_tcp_err).__name__,
                _tcp_err,
            )
            raise RuntimeError(
                f"Cannot associate with {move_dest_ae} at "
                f"{target_host}:{target_port} - terminal transport "
                f"({type(_tcp_err).__name__}: {_tcp_err})"
            ) from _tcp_err
        if assoc.is_established:
            try:
                associations_total.labels(role="to", ae=ae_label(move_dest_ae)).inc()
            except Exception:
                pass
            outcome = "established"
            break
        # ACSE silence / refused-RST swallowed to a non-established return:
        # retry per the single knob (immediate), PS3.8 9.1.4 Note 2.
        logging.info(
            "[C-MOVE] %s@%s:%s main association not established "
            "(attempt %d/%d) - acse-retry immediately (PS3.8 9.1.4 Note 2: "
            "retry policy is implementation freedom)",
            move_dest_ae,
            target_host,
            target_port,
            attempt,
            attempts,
        )
        outcome = "acse-retry"
    if not assoc or not assoc.is_established:
        raise RuntimeError(
            f"Cannot associate with {move_dest_ae} at {target_host}:{target_port}"
        )

    # Build set-valued map: dict[sop_class_uid -> SET[ts]] - a rejected
    # context for one TS must not erase another accepted TS of the same class.
    accepted_contexts_map = {}
    for ctx in assoc.accepted_contexts:
        sop_uid = str(ctx.abstract_syntax)
        ts_uid = str(ctx.transfer_syntax[0]) if ctx.transfer_syntax else None
        if ts_uid:
            accepted_contexts_map.setdefault(sop_uid, set()).add(ts_uid)
    contexts_acc = sum(len(v) for v in accepted_contexts_map.values())
    logging.info(
        "[C-MOVE] Association with %s: contexts_req=%d contexts_acc=%d "
        "contexts_dropped=%d assocs=%d attempts[1/%d] outcome=%s",
        move_dest_ae,
        contexts_req,
        contexts_acc,
        contexts_dropped,
        1,
        attempts,
        outcome or "established",
    )
    return assoc, accepted_contexts_map

# ---------------------------------------------------------------------------
# _ensure_file_meta_bytes - synthesize/rewrite group 0002 (canonical trio)
# ---------------------------------------------------------------------------
_LONG_VRS = {
    b"OB",
    b"OD",
    b"OF",
    b"OL",
    b"OV",
    b"OW",
    b"SQ",
    b"UC",
    b"UN",
    b"UR",
    b"UT",
}

# The VRs that use the 12-byte header inside the FILE META group. pydicom's
# own writer emits (0002,0000) UL and (0002,0001) OB with the 8-byte SHORT
# header (verified against a dcmwrite() Part 10 file), so the meta group uses
# this narrower set - using `_LONG_VRS` here made the walk demand four bytes
# that the writer never wrote and stop after the group length.
_META_LONG_VRS = {
    b"OB",
    b"OD",
    b"OF",
    b"OL",
    b"OV",
    b"OW",
    b"SQ",
    b"UC",
    b"UN",
    b"UR",
    b"UT",
}

def _meta_data_start(dicom_bytes):
    """Preamble-aware start of the meta group: 132 (full preamble), 4
    (bare DICM) or 0 (no magic at all)."""
    if len(dicom_bytes) >= 132 and dicom_bytes[128:132] == b"DICM":
        return 132
    if len(dicom_bytes) >= 4 and dicom_bytes[:4] == b"DICM":
        return 4
    return 0

def _walk_meta(dicom_bytes):
    """Walk group 0002 (explicit VR LE); return (data_start, elements,
    meta_end). Reader-side tolerance: the value skip is vlen + (vlen % 2),
    so old externally-padded files keep parsing.

    A TRUNCATED group ends the walk at the last element that parsed instead
    of discarding the group: the caller replaces the whole group anyway, and
    returning `meta_end = data_start` made it splice its new group in front of
    the OLD one - leaving two group 0002 blocks in the file.
    """
    data_start = _meta_data_start(dicom_bytes)
    pos = data_start
    elems = []
    while pos + 8 <= len(dicom_bytes):
        group = struct.unpack_from("<H", dicom_bytes, pos)[0]
        if group != 0x0002:
            break
        elem = struct.unpack_from("<H", dicom_bytes, pos + 2)[0]
        vr = dicom_bytes[pos + 4 : pos + 6]
        if vr in _META_LONG_VRS:
            if pos + 12 > len(dicom_bytes):
                break
            vlen = struct.unpack_from("<I", dicom_bytes, pos + 8)[0]
            vo = pos + 12
        else:
            vlen = struct.unpack_from("<H", dicom_bytes, pos + 6)[0]
            vo = pos + 8
        if vo + vlen > len(dicom_bytes):
            break
        elems.append((elem, dicom_bytes[vo : vo + vlen]))
        pos = vo + vlen + (vlen % 2)
    return data_start, elems, pos

def _ui_elem(elem, value):
    """One canonical UI meta element (3008): even length with the trailing
    NULL INSIDE the length (PS3.5 sec 6.2), no external pad byte."""
    v = value.encode("ascii") if isinstance(value, str) else bytes(value)
    if len(v) % 2:
        v += b"\x00"
    return struct.pack("<HH2sH", 0x0002, elem, b"UI", len(v)) + v

def _extract_meta_ui(dicom_bytes, elem):
    """Byte-level read of the source meta group for (0002,elem), explicit
    VR LE, preamble-aware. Returns the UID string or None."""
    _, elems, _ = _walk_meta(dicom_bytes)
    for e, value in elems:
        if e == elem:
            raw = value.rstrip(b"\x00 ").decode("ascii", "replace")
            return raw if raw else None
    return None

def _skip_undefined_element(dicom_bytes, value_off, implicit_vr=False):
    """Skip an undefined-length body (SQ/UN element or item content):
    walks items AND raw dataset elements until the enclosing sequence
    delimitation item (FFFE,E0DD). Undefined-length items and elements
    recurse; an item delimitation item (FFFE,E00D) ends only the inner
    body, a sequence delimitation ends ALL enclosing bodies (the
    ZONARE 0109 shape omits E00D). implicit_vr: elements carry NO VR
    field (tag + 4-byte LE length); items and delimitation codes are
    identical in both encodings. Returns (offset, is_final): offset
    AFTER the terminator (None on malformed bytes), is_final=True when
    the terminator was E0DD."""
    p = value_off
    n = len(dicom_bytes)
    while p + 8 <= n:
        g = struct.unpack_from("<H", dicom_bytes, p)[0]
        e = struct.unpack_from("<H", dicom_bytes, p + 2)[0]
        if (g, e) == (0xFFFE, 0xE0DD):  # sequence delimitation
            return p + 8, True
        if (g, e) == (0xFFFE, 0xE00D):  # item delimitation
            return p + 8, False
        if (g, e) == (0xFFFE, 0xE000):  # item
            it_len = struct.unpack_from("<I", dicom_bytes, p + 4)[0]
            if it_len == 0xFFFFFFFF:
                p, final = _skip_undefined_element(
                    dicom_bytes,
                    p + 8,
                    implicit_vr,
                )
                if p is None:
                    return None, False
                if final:
                    return p, True  # E0DD closed this body too
                continue
            p = p + 8 + it_len + (it_len % 2)
            continue
        # Regular dataset element (explicit or implicit VR LE).
        if implicit_vr:
            if p + 8 > n:
                return None, False
            vlen = struct.unpack_from("<I", dicom_bytes, p + 4)[0]
            vo = p + 8
        else:
            vr = dicom_bytes[p + 4 : p + 6]
            if vr in _LONG_VRS:
                if p + 12 > n:
                    return None, False
                vlen = struct.unpack_from("<I", dicom_bytes, p + 8)[0]
                vo = p + 12
            else:
                vlen = struct.unpack_from("<H", dicom_bytes, p + 6)[0]
                vo = p + 8
        if vlen == 0xFFFFFFFF:
            p, final = _skip_undefined_element(dicom_bytes, vo, implicit_vr)
            if p is None:
                return None, False
            if final:
                return p, True
        else:
            if vo + vlen > n:
                return None, False
            p = vo + vlen + (vlen % 2)
    return None, False

def _extract_dataset_ui(dicom_bytes, elem, group=0x0008, implicit_vr=False):
    """Byte-level scan of the top-level dataset for (group,elem) - SOP
    Class UID (0x0008,0x0016) / SOP Instance UID (0x0008,0x0018) /
    Series UID (0x0020,0x000E). Explicit VR LE by default; implicit_vr
    reads elements WITHOUT the VR field (tag + 4-byte LE length - the
    stored IVRLE shape). Undefined-length elements
    (SQ/UN) are skipped over their item lists (0109 field: ZONARE
    (0008,2112) SQ stopped the scan before (0020,000E) and killed the
    C-MOVE refetch rescue)."""
    pos = _meta_data_start(dicom_bytes)
    # Skip the meta group (always explicit VR LE).
    while pos + 8 <= len(dicom_bytes):
        g = struct.unpack_from("<H", dicom_bytes, pos)[0]
        if g != 0x0002:
            break
        vr = dicom_bytes[pos + 4 : pos + 6]
        if vr in _LONG_VRS:
            if pos + 12 > len(dicom_bytes):
                return None
            vlen = struct.unpack_from("<I", dicom_bytes, pos + 8)[0]
            vo = pos + 12
        else:
            vlen = struct.unpack_from("<H", dicom_bytes, pos + 6)[0]
            vo = pos + 8
        pos = vo + vlen + (vlen % 2)
    # Walk the dataset (explicit or implicit VR LE).
    while pos + 8 <= len(dicom_bytes):
        g = struct.unpack_from("<H", dicom_bytes, pos)[0]
        e = struct.unpack_from("<H", dicom_bytes, pos + 2)[0]
        if implicit_vr:
            vlen = struct.unpack_from("<I", dicom_bytes, pos + 4)[0]
            vo = pos + 8
        else:
            vr = dicom_bytes[pos + 4 : pos + 6]
            if vr in _LONG_VRS:
                if pos + 12 > len(dicom_bytes):
                    break
                vlen = struct.unpack_from("<I", dicom_bytes, pos + 8)[0]
                vo = pos + 12
            else:
                vlen = struct.unpack_from("<H", dicom_bytes, pos + 6)[0]
                vo = pos + 8
        if vlen == 0xFFFFFFFF:
            # Undefined-length element (SQ/UN): skip the item list to
            # the delimitation item - UIDs never live inside items.
            after, _final = _skip_undefined_element(
                dicom_bytes,
                vo,
                implicit_vr,
            )
            if after is None:
                break
            pos = after
            continue
        if vo + vlen > len(dicom_bytes):
            break
        if (g, e) == (group, elem):
            raw = dicom_bytes[vo : vo + vlen].rstrip(b"\x00 ")
            s = raw.decode("ascii", "replace")
            return s if s else None
        pos = vo + vlen + (vlen % 2)
    return None

# PS3.10 7.1 Table 7.1-1: (0002,0012) Implementation Class UID is Type 1 - it
# names the implementation that wrote the file. A single constant keeps every
# repaired instance in one implementation family without inventing a per-build
# UID (the version element (0002,0013) is Type 3 and is not emitted).
_BRIDGE_IMPLEMENTATION_CLASS_UID = "1.2.826.0.1.3680043.10.1316"

def _ensure_file_meta_bytes(dicom_bytes, sop_class_uid, sop_uid, ts_uid):
    """Return bytes whose meta group is the canonical ascending trio -
    (0002,0002) MediaStorageSOPClassUID, (0002,0003)
    MediaStorageSOPInstanceUID, (0002,0010) TransferSyntaxUID LAST - each
    Explicit VR LE UI with an even value length and the trailing NULL
    INSIDE the length (PS3.5 sec 6.2).

    The group also carries the other Table 7.1-1 Type 1 elements: Group Length
    (0002,0000) as the first element, Version (0002,0001) after it and
    Implementation Class UID (0002,0012) after the transfer syntax - ascending
    order is the encoding requirement (PS3.5 7.1).
    cltranscode-stored files have NO group 0002 at
    all, and the server's transcoded WADO response copies that gap.
    pynetdicom `send_c_store` then refuses the file and the whole C-MOVE
    dies with 0xB000.

    ONE canonical writer. UID resolution order: (a) byte-level meta
    group, (b) byte-level dataset scan for (0008,0016)/(0008,0018),
    (c) the pydicom-parsed value. A parser returning '' never suppresses
    (0002,0003). If the existing meta group is already byte-exactly the
    canonical trio, the input is returned unchanged; otherwise the WHOLE
    group is replaced (never spliced after non-ascending or
    externally-padded elements).
    """
    data_start = _meta_data_start(dicom_bytes)
    if len(dicom_bytes) >= 132 and dicom_bytes[128:132] == b"DICM":
        prefix = dicom_bytes[:132]
    elif len(dicom_bytes) >= 4 and dicom_bytes[:4] == b"DICM":
        prefix = dicom_bytes[:4]
    else:
        # No DICM magic at all: build a full preamble (pynetdicom reads
        # files, DICM expected).
        prefix = b"\x00" * 128 + b"DICM"

    _, existing, meta_end = _walk_meta(dicom_bytes)

    # 02.09 field Job #38: ts_uid==IVRLE means the dataset bytes are
    # implicit VR (no VR field). The meta group is ALWAYS explicit, so
    # only the dataset fallback scans switch encoding.
    _implicit = ts_uid == ImplicitVRLittleEndian
    resolved_sc = (
        _extract_meta_ui(dicom_bytes, 0x0002)
        or _extract_dataset_ui(dicom_bytes, 0x0016, implicit_vr=_implicit)
        or (sop_class_uid or None)
    )
    resolved_si = (
        _extract_meta_ui(dicom_bytes, 0x0003)
        or _extract_dataset_ui(dicom_bytes, 0x0018, implicit_vr=_implicit)
        or (sop_uid or None)
    )
    ts = ts_uid or "1.2.840.10008.1.2.1"

    # PS3.10 7.1 Table 7.1-1 marks SIX elements Type 1 in the File Meta
    # Information: (0002,0000) Group Length, (0002,0001) Version,
    # (0002,0002) Media Storage SOP Class UID, (0002,0003) Media Storage SOP
    # Instance UID, (0002,0010) Transfer Syntax UID and (0002,0012)
    # Implementation Class UID. The writer used to emit only the SOP/TS trio,
    # so every file it repaired was a non-conformant Part 10 file.
    body = b""
    # (0002,0001) Version: OB, two bytes, bit 0 of the first byte set. OB is a
    # LONG-VR: 8-byte tag+VR header, 2 reserved bytes, 4-byte length
    # (PS3.5 7.1.2 Table 7.1-2), then the value - byte-for-byte what pydicom's
    # own writer emits for this element.
    body += (
        struct.pack("<HH2sH", 0x0002, 0x0001, b"OB", 0)
        + struct.pack("<I", 2)
        + b"\x00\x01"
    )
    # (0002,0002) and (0002,0003) are Type 1 as well, so they are emitted even
    # when no source value could be resolved: a group 0002 that omits either
    # is non-conformant exactly like one that omits the group length. The
    # fallback is the caller's argument and, failing that, an empty UID value -
    # a receiver can still identify the file by the dataset, whereas a missing
    # element is a Part 10 conformance failure.
    body += _ui_elem(0x0002, resolved_sc or sop_class_uid or "")
    body += _ui_elem(0x0003, resolved_si or sop_uid or "")
    body += _ui_elem(0x0010, ts)
    body += _ui_elem(
        0x0012, _BRIDGE_IMPLEMENTATION_CLASS_UID
    )  # (0002,0000) is the number of bytes AFTER its own value field, so it is
    # written last and computed from the body. Encoded exactly the way pydicom
    # writes it: UL is a SHORT-VR element in this writer's grammar (see
    # `_walk_meta`), so 8-byte header + 4-byte value.
    trio = struct.pack("<HH2sHI", 0x0002, 0x0000, b"UL", 4, len(body)) + body

    if dicom_bytes[data_start:meta_end] == trio:
        return dicom_bytes
    return prefix + trio + dicom_bytes[meta_end:]

def _pick_refetch_ts(accepted_ts_for_class, server_ts_list):
    """Choose the refetch transfer syntax for a stored-not-accepted instance.

    The bridge NEVER opens a second/probe association; a stored TS the viewer
    did not accept is delivered only if the server can produce an accepted TS.
    The refetch target is drawn from the intersection of the viewer's accepted
    set for the class and the server's producible set (caps). Priority within
    that intersection: EVRLE, then IVRLE, then any remaining accepted TS
    (deterministic order).

    The caps endpoint declares only the compressed transcode-target codecs and
    does NOT declare EVRLE/IVRLE, yet a server that serves `?transferSyntax=`
    (transcode-capable) requests is expected to be able to return an
    uncompressed form. PS3.18 8.7.3.1 (Table 8.7.3-2) makes Explicit VR Little
    Endian the Default (D) media-type transfer syntax for Image/Video/Text/Other
    instances and returns it "unless the origin server has only access to the
    pixel data in lossy compressed form or ... such length that it cannot be
    encoded in the Explicit VR Little Endian Transfer Syntax" - i.e. EVRLE is
    the standard default representation, not an optional transcode target, so a
    transcode-capable origin server can be expected to produce it.
    Therefore, when the server reports transcode capabilities
    (`server_ts_list` non-empty) EVRLE is treated as producible and added to
    the candidate set before the intersection - a transcode build has an EVRLE
    encoder. This is not inventing a capability. If the server in fact cannot
    produce EVRLE the refetch itself returns 406 and the instance fails
    honestly (the same outcome as before, so this cannot regress). When
    `server_ts_list` is EMPTY (a no-transcode server) EVRLE is NOT added -
    nothing can be transcoded, a refetch call would be wasted, and the
    instance fails honestly as today.

    Returns the chosen TS UID, or '' when no deliverable form exists (the
    caller must fail the instance honestly).
    """
    if isinstance(accepted_ts_for_class, str):
        acc = {accepted_ts_for_class} if accepted_ts_for_class else set()
    elif isinstance(accepted_ts_for_class, (list, tuple)):
        acc = set(accepted_ts_for_class)
    else:
        acc = set(accepted_ts_for_class or set())
    prod = set(server_ts_list or [])
    if prod:
        # A transcode-capable origin server is expected to be able to produce
        # EVRLE (PS3.18 8.7.3.1: EVRLE is the Default D transfer syntax for
        # image instances). EVRLE is never invented on a no-transcode server
        # (prod empty below).
        prod.add(ExplicitVRLittleEndian)
    cand = acc & prod
    if not cand:
        return ""
    for ts in (ExplicitVRLittleEndian, ImplicitVRLittleEndian):
        if ts in cand:
            return ts
    return sorted(cand)[0]

def _decide_send_path(accepted_ts_for_class, actual_ts, is_image):
    """Pure per-instance send-path decision (no probe is ever opened).

    Returns 'send_as_is' (C-STORE the stored bytes on the main association
    - the stored TS is accepted by the viewer, or it is a non-image SOP, or
    the stored TS is unknown) or 'needs_deliver' (a stored TS the viewer did
    NOT accept on the main association - the caller then chooses a
    deliverable refetch TS via `_pick_refetch_ts`, or fails the instance
    honestly when the server cannot produce one).

    obligation: the bridge NEVER opens a probe / second association to a
    C-MOVE destination. The fallback path is gone; the only outcomes per
    stored-not-accepted image are refetch on the MAIN association (if the
    server can produce an accepted TS) or an honest per-instance failure with
    reason (no silent drops).
    """
    if not is_image:
        return "send_as_is"
    if not actual_ts:
        return "send_as_is"
    accepted = accepted_ts_for_class
    if isinstance(accepted, str):
        accepted = {accepted} if accepted else set()
    elif isinstance(accepted, (list, tuple)):
        accepted = set(accepted)
    else:
        accepted = accepted or set()
    if accepted and actual_ts in accepted:
        return "send_as_is"
    return "needs_deliver"

def _pydicom_file_meta_ts(dicom_bytes):
    """Last-resort transfer-syntax read (pydicom). Used ONLY when neither
    the part Content-Type parameter nor the byte-level (0002,0010) read
    produced a TS. Returns '' on any failure."""
    try:
        ds = dcmread(io.BytesIO(dicom_bytes), stop_before_pixels=True)
        return str(
            getattr(getattr(ds, "file_meta", None), "TransferSyntaxUID", "") or ""
        )
    except Exception:
        return ""

# ---------------------------------------------------------------------------
# _stream_and_send_study  -  stream study from Clarus, send via C-STORE
# ---------------------------------------------------------------------------
def _stream_and_send_study(
    assoc,
    study_uid,
    clarus_url,
    http_timeout,
    move_jobs,
    job_id,
    accepted_contexts_map=None,
    server_ts_list=None,
    sop_registry=None,
    tls=None,
    spill_threshold=SPILL_THRESHOLD,
    peer_ae="",
    _skip_ids=None,
    _resumed=False,
    _report_lost=False,
    _prior_completed=0,
    _prior_failed=0,
    _prior_total=0,
    request_level="",
    request_series_uid="",
    request_sop_uid="",
    expose_rejected=False,
    qa_url="",
):
    """Stream study from Clarus via WADO-RS, send via C-STORE.

    stored-first: ONE study-level streaming multipart GET WITHOUT
    ?transferSyntax= (stored bytes, zero server CPU). Per instance the
    stored transfer syntax is decided byte-level.

    The bridge NEVER opens a probe / second association to a C-MOVE
    destination. Delivery per instance follows the negotiation result on the
    MAIN association:
    - stored TS accepted -> send_as_is (passthrough);
    - stored TS not accepted AND the server can produce an accepted TS (the
      intersection of the viewer's accepted set and the server caps) ->
      refetch the instance on the MAIN association with ?transferSyntax=
      (priority EVRLE -> IVRLE -> any);
    - otherwise -> an honest per-instance failure (the undelivered SOP UID
      lands in the (0008,0058) list of the final response).

    Resume: on an association loss the driver re-associates ONCE and calls
    this function a SECOND time with *_skip_ids* = the SOP UIDs already
    delivered on the first pass (they are refused a re-send, so every instance
    is delivered exactly once), *_resumed*=True (adds resumed=1 to the final
    INFO), and *_report_lost=True so this pass can report a further association
    loss via a trailing boolean. A resumed pass issues a FRESH study-level GET
    (a conformant continuation - PS3.7 9.1.4.2 (e) sub-operations may occur on
    a different Association than the C-MOVE; PS3.8 9.1.4 Note 2 + 9.1.5
    re-association freedom). When *_report_lost* is False the returned tuple
    has the historical 7 elements; when True an 8th element `lost` (0/1) is
    appended so the driver can tell "association lost again -> GIVE_UP".

    sop_registry: SOP class registry for image/non-image classification.
    spill_threshold: multipart parser spill threshold (W3); tests inject a
    small value, production uses the 16 MB default.

    Returns (completed, failed, total, sent_sop_uids, failed_sop_uids,
             cancelled, no_common_ts[, lost]). failed_sop_uids = the SOP
    instance UIDs that were seen and not delivered in THIS pass (PS3.4
    C.4.2.1.4.2 material); the driver reconciles the (0008,0058) tail across
    passes from the study-level list.

    The returned counters describe THIS pass. `_prior_*` carries what earlier
    passes delivered and is used only for the LIVE progress row, so the
    poller never sees a resumed pass reset the job to 0 of N.
    """
    completed = 0
    failed = 0
    total = 0
    total_bytes = 0
    passthrough = 0
    transcoded = 0
    refetched = 0
    # Instances the peer ACCEPTED with a Warning status (PS3.4 B.2.3.1). They
    # count as delivered - the SCP holds them - so they are not in `failed`.
    warned = 0
    sent_sop_uids = []
    # 0709: every SOP instance UID this job attempted, so the failed set
    # (seen minus delivered) feeds the (0008,0058) Failed SOP Instance UID
    # List on the final C-MOVE-RSP (PS3.4 C.4.2.1.4.2).
    seen_sop_uids = set()

    def _out(cancelled=False, no_common=False, lost=False):
        """Assemble the return tuple; a `lost` element is appended ONLY when
        the driver requested it via `_report_lost` (test_spill unpacks the
        historical 7 elements and does not set `_report_lost`). The
        (0008,0058) tail is computed here from the current seen/delivered
        sets so the helper has no forward dependency.

        The C-STORE warning tally is NOT part of this tuple: it is persisted
        here (see `set_job_warning_count`) because widening a return value that
        the tests and two call sites unpack positionally turned a repair into a
        contract break. The worker already owns `move_jobs` and `job_id`, so it
        can record the tally itself.
        """
        try:
            move_jobs.set_job_warning_count(job_id, warned)
        except Exception:
            logging.debug("[C-MOVE] Job #%s: warning count not recorded", job_id)
        _d = {u for _c, u in sent_sop_uids if u}
        _f = sorted(u for u in seen_sop_uids if u not in _d)
        base = (completed, failed, total, sent_sop_uids, _f, cancelled, no_common)
        if _report_lost:
            return base + (lost,)
        return base

    # Negotiate transfer syntax between viewer and server
    server_ts = server_ts_list if server_ts_list else []
    if accepted_contexts_map is not None and not accepted_contexts_map:
        # No accepted presentation context and therefore no refetch target.
        # The job finishes failed with zero slices delivered and the C-MOVE
        # generator reports a Failure (0xC000, PS3.4 Table C.4-2 "Failed:
        # Unable to process") - the wire status and this log agree. 0xC001
        # stayed a log-only claim in the past; it is NOT a response status.
        logging.warning(
            "[C-MOVE] Viewer accepted no presentation contexts - "
            "no common transfer syntax; job fails with 0 slices, "
            "C-MOVE-RSP is a Failure (0xC000)",
        )
        return _out(no_common=True)
    if server_ts:
        # Stored-first: the study-level GET NEVER carries
        # ?transferSyntax=. The server can transcode; per-instance
        # refetch picks a target from the accepted set.
        logging.info(
            "[C-MOVE] Server transcode available (%d TS); streams stored "
            "bytes; not-accepted instances refetch on the main association",
            len(server_ts),
        )
    else:
        # Passthrough mode: server has no transcode capabilities. Don't
        # request ?transferSyntax=. Server returns stored bytes as-is. The
        # bridge forwards whatever it receives; a stored TS the viewer did
        # not accept cannot be produced -> honest per-instance failure.
        logging.info(
            "[C-MOVE] Passthrough mode - server has no transcode; stored "
            "bytes only, not-accepted instances fail honestly",
        )

    # ONE streaming GET WITHOUT ?transferSyntax=, scoped to the requested
    # level (PS3.4 C.4.2.1.2): STUDY fetches the study, SERIES the named
    # series, IMAGE the single instance. Without the scope a SERIES C-MOVE
    # pushed every instance of the study to the viewer.
    accept_value = "multipart/related; type=application/dicom"
    _base = service_base_url(clarus_url, qa_url, expose_rejected)
    # Every UID goes into the path through `_quote`: they are client input, and
    # `1.2?a=b` or `../x` in one would steer the GET at a different resource.
    _study_path = f"/studies/{_quote(study_uid, safe='')}"
    if request_level == "IMAGE" and request_series_uid and request_sop_uid:
        url = (
            f"{_base}{_study_path}"
            f"/series/{_quote(request_series_uid, safe='')}"
            f"/instances/{_quote(request_sop_uid, safe='')}"
        )
    elif request_level == "SERIES" and request_series_uid:
        url = f"{_base}{_study_path}/series/{_quote(request_series_uid, safe='')}"
    else:
        url = f"{_base}{_study_path}"
    headers = {"Accept": accept_value}

    logging.info(
        "[C-MOVE] Streaming %s from DICOMweb server...",
        (
            f"instance {request_sop_uid} of series {request_series_uid}"
            if request_level == "IMAGE"
            else (
                f"series {request_series_uid}"
                if request_level == "SERIES"
                else f"study {study_uid}"
            )
        ),
    )
    resp = None
    try:
        resp = requests.get(
            url, headers=headers, timeout=http_timeout, stream=True, cert=tls
        )
        resp.raise_for_status()
    except requests.RequestException as _get_err:
        # The status check runs before a single body byte is read, so nothing
        # will ever close this response for us: the pooled connection stays
        # checked out for the life of the process and every later WADO GET
        # opens another one. Release it before the failure propagates.
        logging.warning(
            "[C-MOVE] WADO-RS GET failed for study %s: %s", study_uid, _get_err
        )
        if resp is not None:
            try:
                resp.close()
            except Exception:
                pass
        raise

    # B1 (2508): a reader thread prefetches the streamed multipart parts into a
    # bounded FIFO while this sender loop C-STORE-s them - the serial pipeline
    # left the Clarus server leg idle during each network C-STORE. Structural
    # backpressure is the bounded queue (4 parts ~ 20 MB, FIFO). The sender
    # loop below is unchanged; every early return must stop the reader thread.
    prefetch = PartPrefetcher(
        _stream_multipart_instances(resp, spill_threshold=spill_threshold),
        # Closing the response is what wakes a reader parked inside
        # `iter_content`; draining the queue only frees one blocked in `put`.
        on_stop=resp.close,
    ).start()

    import os as _os
    import tempfile

    def _refetch_and_send(
        idx, sop_uid, sop_class_uid, actual_ts, refetch_ts, series_uid, peer_ae=""
    ):
        """Per-instance refetch + C-STORE on the MAIN association.

        Called when the stored TS is not accepted but a deliverable TS exists
        (the caller passes `refetch_ts` chosen from the accepted x server
        intersection via `_pick_refetch_ts` - never a probe/second
        association). A series UID is required to build the instance URL.
        Updates the refetched/failed counters and returns the C-STORE status
        (None = failure already counted).
        """
        nonlocal refetched, failed
        if not (refetch_ts and series_uid):
            reason = (
                "no series UID for the instance URL"
                if not series_uid
                else "no accepted refetch TS for this class"
            )
            logging.warning(
                "[C-MOVE] Instance %d (%s): stored TS %s not accepted "
                "and refetch impossible (%s) - counted failed",
                idx,
                sop_uid,
                actual_ts,
                reason,
            )
            failed += 1
            return None
        refetched += 1
        # Every UID goes into the path through `_quote`: a UID is not trusted
        # input just because it arrived over DIMSE, and `1.2?a=b` or `../x` in
        # one would steer the GET at a different resource than the instance the
        # peer asked for.
        inst_url = (
            f"{service_base_url(clarus_url, qa_url, expose_rejected)}"
            f"/studies/{_quote(study_uid, safe='')}"
            f"/series/{_quote(series_uid, safe='')}"
            f"/instances/{_quote(sop_uid, safe='')}"
            f"?transferSyntax={_quote(refetch_ts, safe='')}"
        )
        logging.info(
            "[C-MOVE] Instance %d (%s): stored TS %s not accepted; "
            "refetching on the MAIN association with transfer-syntax=%s",
            idx,
            sop_uid,
            actual_ts,
            refetch_ts,
        )
        r2 = None
        try:
            r2 = requests.get(
                inst_url,
                headers={"Accept": f"application/dicom; transfer-syntax={refetch_ts}"},
                timeout=http_timeout,
                cert=tls,
                stream=True,
            )
            r2.raise_for_status()
        except requests.RequestException as rf_err:
            logging.warning(
                "[C-MOVE] Instance %d (%s): refetch failed: %s",
                idx,
                sop_uid,
                rf_err,
            )
            # `raise_for_status()` raises BEFORE the streaming body is read, so
            # the pooled socket this response holds is never returned by
            # `iter_content` reaching EOF. Without this close the connection
            # stayed checked out of the pool for the life of the process, and
            # every subsequent refetch opened another one.
            if r2 is not None:
                try:
                    r2.close()
                except Exception:
                    pass
            failed += 1
            return None
        # The replacement is written STRAIGHT to a managed temp file in bounded
        # chunks. Reading it into `r2.content` first buffered the whole instance
        # in memory and bypassed the spill threshold the study stream respects:
        # a large spilled instance needing a different transfer syntax cost
        # exactly the memory the spill exists to avoid.
        #
        # `_ensure_file_meta_bytes` needs the LEADING bytes to locate the
        # dataset, so the group-0002 prefix is rewritten once the whole file is
        # on disk: the replacement header is written over the old one and the
        # remainder of the file follows untouched when the length is unchanged.
        # A length change is handled by a BOUNDED copy of the retained tail
        # into a second temp file - reading the instance back to do it defeated
        # the spill this whole path exists to respect.
        _rtmp = None
        _rtmp2 = None
        try:
            with tempfile.NamedTemporaryFile(suffix=".dcm", delete=False) as _f2:
                _rtmp = _f2.name
            _prefix = b""
            _written = 0
            with open(_rtmp, "wb") as _out:
                try:
                    for chunk in r2.iter_content(1024 * 1024):
                        if not chunk:
                            continue
                        if len(_prefix) < _FILE_META_PROBE:
                            _prefix += chunk[: _FILE_META_PROBE - len(_prefix)]
                        _out.write(chunk)
                        _written += len(chunk)
                finally:
                    try:
                        r2.close()
                    except Exception:
                        pass
            if _written == 0:
                raise ValueError("empty refetch body")
            _fixed = _ensure_file_meta_bytes(
                _prefix, sop_class_uid, sop_uid, refetch_ts
            )
            if _fixed != _prefix:
                # Only the prefix changed. When its LENGTH is unchanged the
                # dataset behind it is already correct in place.
                if len(_fixed) == len(_prefix):
                    with open(_rtmp, "r+b") as _out:
                        _out.seek(0)
                        _out.write(_fixed)
                else:
                    # Length-changing prefix: build the replacement in a second
                    # file from the new prefix plus the tail, copied in bounded
                    # chunks. `_out.read()` loaded the entire instance into
                    # memory to move a few bytes of header, which defeated
                    # spilling for exactly the large instances it protects.
                    _rtmp2 = _rtmp + ".fixed"
                    with open(_rtmp, "rb") as _src, open(_rtmp2, "wb") as _dst:
                        _dst.write(_fixed)
                        _src.seek(len(_prefix))
                        while True:
                            _buf = _src.read(_TAIL_COPY_CHUNK)
                            if not _buf:
                                break
                            _dst.write(_buf)
                    try:
                        _os.replace(_rtmp2, _rtmp)
                    except OSError:
                        _os.unlink(_rtmp2)
                        _rtmp2 = None
                        raise
                    _rtmp2 = None
        except Exception as _wf:
            # A failed write or copy must not leave a partial file behind: the
            # unlink below only runs on the success path. Both temp files are
            # released here, because the second is created before the copy that
            # can fail.
            logging.warning(
                "[C-MOVE] Instance %d (%s): refetched bytes could not be "
                "written (%s)",
                idx,
                sop_uid,
                _wf,
            )
            for _p in (_rtmp, _rtmp2):
                if _p:
                    _unlink_quiet(_p)
            failed += 1
            return None
        try:
            _t0 = time.perf_counter()
            # C-CANCEL can arrive during the download above, after the
            # per-instance check that preceded this instance. Sending now would
            # open a new C-STORE after the SCU has been told the move stopped
            # (PS3.4 C.4.2.3: no further sub-operations once cancelled).
            if _shutdown_requested.is_set() or move_jobs.is_job_cancelled(job_id):
                logging.info(
                    "[C-MOVE] Instance %d (%s): cancelled after the refetch - "
                    "not sending the replacement",
                    idx,
                    sop_uid,
                )
                failed += 1
                return None
            status = assoc.send_c_store(_rtmp)
        except Exception as rs_err:
            logging.warning(
                "[C-MOVE] Instance %d (%s): C-STORE of refetched " "bytes failed: %s",
                idx,
                sop_uid,
                rs_err,
            )
            status = None
        finally:
            if _rtmp:
                _unlink_quiet(_rtmp)
        try:
            cstore_outbound_duration.labels(peer=ae_label(peer_ae)).observe(
                time.perf_counter() - _t0
            )
            # bytes_total is NOT incremented here: the main send loop counts
            # `part_size` once when the peer answers 0x0000, and that is the
            # only place allowed to - a send-time count here double-counted
            # every refetched instance (once with the refetched size, once
            # with the stored size) and also counted instances the peer
            # rejected. bytes_total describes accepted traffic.
        except Exception:
            pass
        if status is None:
            failed += 1
        return status

    def _refetch_after_rejection(
        inst_idx, sop_uid, sop_class_uid, actual_ts, dicom_bytes, peer_ae=""
    ):
        """Refetch one not-accepted instance on the MAIN association.

        Refetch target = a TS the viewer accepts AND the server can produce,
        chosen by `_pick_refetch_ts` (EVRLE -> IVRLE -> any). No probe /
        second association is ever used. Returns the C-STORE status
        (None = failure already counted by _refetch_and_send; the caller then
        lets the undelivered SOP UID land in the (0008,0058) failed list).
        """
        _acc = (
            accepted_contexts_map.get(sop_class_uid) if accepted_contexts_map else None
        )
        refetch_ts = _pick_refetch_ts(_acc, server_ts)
        if not refetch_ts:
            # No deliverable form - honest per-instance failure. The SOP
            # UID stays in seen_sop_uids so the final (0008,0058) lists it.
            logging.warning(
                "[C-MOVE] Instance %d (%s): stored TS %s not accepted and "
                "no accepted TS the server can produce - counted failed",
                inst_idx,
                sop_uid,
                actual_ts,
            )
            return None
        # Field-observed: stored IVRLE bytes carry no VR field -
        # scan in implicit mode so the series UID (and the refetch URL)
        # survives the refetch rescue.
        series_uid = (
            _extract_dataset_ui(
                dicom_bytes,
                0x000E,
                group=0x0020,
                implicit_vr=(actual_ts == ImplicitVRLittleEndian),
            )
            or ""
        )
        return _refetch_and_send(
            inst_idx,
            sop_uid,
            sop_class_uid,
            actual_ts,
            refetch_ts,
            series_uid,
            peer_ae,
        )

    def _unlink_quiet(path):
        """Best-effort temp-file cleanup - cleanup must never fail the job."""
        try:
            _os.unlink(path)
        except OSError:
            pass

    def _failed_uids():
        """Sorted (0008,0058) material: seen-but-not-delivered SOP instance
        UIDs (PS3.4 C.4.2.1.4.2). Deterministic order for the wire list."""
        _delivered = {u for _c, u in sent_sop_uids if u}
        return sorted(u for u in seen_sop_uids if u not in _delivered)

    # The streamed response stays open for the whole loop; every exit
    # path must release it, early returns included, or the pooled
    # connection stays checked out for the life of the process.
    try:
        for part, idx, part_ts in prefetch:
            # A spilled part arrives as (head bytes, temp-file path).
            # The head carries the file meta group read below; the rest is
            # streamed from disk, never read whole into memory.
            spill_path = None
            if isinstance(part, SpilledPart):
                dicom_bytes = part.head
                spill_path = part.path
            else:
                dicom_bytes = part

            # Bridge: check C-MOVE-CANCEL before each C-STORE
            if move_jobs.is_job_cancelled(job_id):
                logging.warning(
                    "[C-MOVE] Job #%d cancelled by SCU after %d/%d instances",
                    job_id,
                    completed,
                    total if total else idx,
                )
                if spill_path is not None:
                    _unlink_quiet(spill_path)
                prefetch.stop()
                return _out(cancelled=True)

            # Bridge: check shutdown flag during long transfers
            if _shutdown_requested.is_set():
                logging.warning("[C-MOVE] Shutdown requested, aborting job #%d", job_id)
                if spill_path is not None:
                    _unlink_quiet(spill_path)
                prefetch.stop()
                return _out(cancelled=True)

            part_size = len(dicom_bytes)
            if spill_path is not None:
                part_size += _os.path.getsize(spill_path)
            total_bytes += part_size
            total = idx + 1  # Update total as we stream
            # DEBUG: log only every 50th part + first/last to avoid I/O spam
            if idx == 0 or idx % 50 == 0:
                logging.debug("[C-MOVE] Streamed part %d: %d bytes", idx + 1, part_size)

            # Stored-first hot loop: byte-level UIDs/TS, NO dcmread in the
            # send path (ap101 discipline - pydicom only as the TS last resort).
            sent_via_refetch = False
            try:
                # The transfer syntax decides how the dataset below must be
                # scanned, so it is resolved FIRST: an Implicit VR instance has no
                # VR field in any element, and reading it as explicit VR makes
                # every tag walk stop at the first element - the SOP UIDs then come
                # back empty and a delivered instance is counted failed.
                # Chain, PER PART:
                # 1) transfer-syntax= of the part Content-Type header;
                # 2) byte-level read of (0002,0010);
                # 3) pydicom - last resort only.
                actual_ts = (
                    part_ts
                    or _extract_meta_ui(dicom_bytes, 0x0010)
                    or _pydicom_file_meta_ts(dicom_bytes)
                )
                implicit_vr = actual_ts == ImplicitVRLittleEndian
                sop_class_uid = (
                    _extract_meta_ui(dicom_bytes, 0x0002)
                    or _extract_dataset_ui(dicom_bytes, 0x0016, implicit_vr=implicit_vr)
                    or ""
                )
                sop_uid = (
                    _extract_meta_ui(dicom_bytes, 0x0003)
                    or _extract_dataset_ui(dicom_bytes, 0x0018, implicit_vr=implicit_vr)
                    or ""
                )
                if sop_uid:
                    seen_sop_uids.add(str(sop_uid))
                # Resume: an instance already DELIVERED on the first pass
                # must not be re-sent or re-counted on the resumed pass. Skip it
                # (bytes were only fetched to identify it); exactly-once holds.
                if _skip_ids and sop_uid and str(sop_uid) in _skip_ids:
                    if spill_path is not None:
                        _unlink_quiet(spill_path)
                    logging.debug(
                        "[C-MOVE] Resume: skipping already-delivered instance %s "
                        "(part %d)",
                        sop_uid,
                        idx + 1,
                    )
                    continue
                # actual_ts was resolved before the byte scans above, because it
                # decides how those scans read the dataset.
                viewer_ts = accepted_contexts_map.get(sop_class_uid) or set()
                is_image = _is_image_sop(sop_class_uid, sop_registry)
                decision = _decide_send_path(viewer_ts, actual_ts, is_image)
                # The bridge NEVER opens a probe/second association.
                # A stored TS the viewer did NOT accept is either delivered on the
                # MAIN association by refetching in a producible accepted TS
                # (EVRLE -> IVRLE -> any from accepted x server intersection), or
                # - when the server cannot produce one - failed honestly.
                if decision == "needs_deliver":
                    refetch_ts = _pick_refetch_ts(viewer_ts, server_ts)
                    decision = "refetch_main" if refetch_ts else "fail"

                # Pass-through: raw bytes -> temp file -> pynetdicom reads directly.
                # No dcmread(), no write_dataset(). Bytes untouched.
                #
                # Creation, writing, sending and unlinking are ONE cleanup
                # scope: the old shape only unlinked after the send file had
                # been built, so a filesystem that filled during the spill copy
                # left a partial `.dcm` behind for the life of the process.
                _tmp_path = None
                try:
                    with tempfile.NamedTemporaryFile(suffix=".dcm", delete=False) as _f:
                        _tmp_path = _f.name
                        _f.write(
                            _ensure_file_meta_bytes(
                                dicom_bytes,
                                sop_class_uid,
                                sop_uid,
                                actual_ts,
                            )
                        )
                        if spill_path is not None:
                            # W3 (0209): append the spilled excess from disk in
                            # 1 MiB chunks - the spill file is never read whole.
                            with open(spill_path, "rb") as _src:
                                shutil.copyfileobj(_src, _f, 1024 * 1024)
                    # The job can be cancelled or stopped while the instance is
                    # being fetched or its send file built - work that can take
                    # as long as the transfer itself. The check at the top of the
                    # loop happened BEFORE it, so a cancel arriving in between
                    # still started a new C-STORE.
                    if (
                        move_jobs.is_job_cancelled(job_id)
                        or _shutdown_requested.is_set()
                    ):
                        logging.warning(
                            "[C-MOVE] Job #%d cancelled/stopping before C-STORE "
                            "of instance %d",
                            job_id,
                            idx + 1,
                        )
                        prefetch.stop()
                        resp.close()
                        return _out(cancelled=True)
                    if decision == "send_as_is":
                        # Stored TS accepted for this class -> main association.
                        _t0 = time.perf_counter()
                        status = assoc.send_c_store(_tmp_path)
                        try:
                            cstore_outbound_duration.labels(
                                peer=ae_label(peer_ae)
                            ).observe(time.perf_counter() - _t0)
                        except Exception:
                            pass
                    elif decision == "refetch_main":
                        # Not accepted + a producible accepted TS exists ->
                        # refetch ON THE MAIN association in that TS. No fallback,
                        # no probe, no second association.
                        status = _refetch_after_rejection(
                            idx + 1,
                            sop_uid,
                            sop_class_uid,
                            actual_ts,
                            dicom_bytes,
                            peer_ae,
                        )
                        if status is None:
                            # _refetch_after_rejection returned ''-target or
                            # _refetch_and_send already counted the failure.
                            continue
                        sent_via_refetch = True
                    else:  # decision == "fail"
                        # Not accepted and no producible accepted TS (server lacks
                        # transcode or nothing in common): honest per-instance
                        # failure - the SOP UID stays in seen_sop_uids so the
                        # final (0008,0058) lists it. No silent drop (R3).
                        logging.warning(
                            "[C-MOVE] Instance %d (%s): stored TS %s not accepted "
                            "and the server cannot produce an accepted TS - "
                            "counted failed",
                            idx + 1,
                            sop_uid,
                            actual_ts,
                        )
                        failed += 1
                        continue
                    if not status or "Status" not in status:
                        # pynetdicom 3.0.4 `send_c_store` returns an EMPTY
                        # Dataset (not None) when the association is gone. A
                        # falsy status or one without a Status element says
                        # nothing about the instance: counting it failed
                        # reported a SOP the viewer may hold, and never armed
                        # the resume the owner of this defect exists for.
                        logging.warning(
                            "[DIMSE-OUT] %s:%d: association LOST after %d/%d "
                            "C-STORE (no response). %s",
                            getattr(assoc, "ae_title", "?"),
                            getattr(assoc, "port", 0),
                            completed,
                            total if total else idx + 1,
                            (
                                "Resuming once."
                                if _report_lost and not _resumed
                                else "Viewer must re-request or resume fails."
                            ),
                        )
                        prefetch.stop()
                        resp.close()
                        return _out(lost=True)
                except (TypeError, ValueError) as send_err:
                    err_msg = str(send_err)
                    if "presentation context" in err_msg.lower():
                        logging.warning(
                            "[C-MOVE] Instance %d (%s): SOP class %s not negotiated "
                            "with viewer - viewer doesn't accept this class/TS. "
                            "Counted failed. Error: %s",
                            idx + 1,
                            sop_uid,
                            sop_class_uid,
                            send_err,
                        )
                        failed += 1
                        continue
                    else:
                        logging.warning(
                            "[C-MOVE] Instance %d (%s): cannot encode for C-STORE - "
                            "corrupted DICOM metadata (tag encoding error). "
                            "Counted failed. Error: %s",
                            idx + 1,
                            sop_uid,
                            send_err,
                        )
                        failed += 1
                        continue
                except Exception as e:
                    # pynetdicom network_timeout false positive: timer fires
                    # even while data IS flowing (e.g. 432 slices, 45s).
                    # If association is alive and C-STORE succeeded before  -  ignore.
                    err_msg = str(e)
                    is_timeout = any(
                        kw in err_msg.lower()
                        for kw in ("timeout", "timed out", "network")
                    )
                    assoc_alive = getattr(assoc, "is_established", False)
                    if is_timeout and assoc_alive and completed > 0:
                        logging.warning(
                            "[DIMSE-OUT] %s:%d: network_timeout fired, "
                            "but association alive, %d C-STORE sent, "
                            "%d bytes transferred. Ignoring - data IS flowing. "
                            "Error: %s",
                            getattr(assoc, "ae_title", "?"),
                            getattr(assoc, "port", 0),
                            completed,
                            total_bytes,
                            err_msg,
                        )
                        failed += 1
                        continue
                    else:
                        # Association DEAD  -  viewer crashed or disconnected. The
                        # driver may resume ONCE. We stop this pass's
                        # stream and report `lost=True` (only when the driver
                        # requested it) so `_execute_cmove_job` can re-associate
                        # and run a skip-delivered second pass.
                        logging.warning(
                            "[DIMSE-OUT] %s:%d: association LOST after %d/%d "
                            "C-STORE sent (%d failed). %s Error: %s",
                            getattr(assoc, "ae_title", "?"),
                            getattr(assoc, "port", 0),
                            completed,
                            total if total else idx + 1,
                            failed + 1,
                            (
                                "Resuming once."
                                if _report_lost and not _resumed
                                else "Viewer must re-request or resume fails."
                            ),
                            err_msg,
                        )
                        prefetch.stop()
                        resp.close()
                        return _out(lost=True)
                finally:
                    if _tmp_path:
                        _unlink_quiet(_tmp_path)
                    if spill_path is not None:
                        _unlink_quiet(spill_path)

                if not status or "Status" not in status:
                    # Same reading as above: a falsy status or one without a
                    # Status element is a lost association, not a rejected
                    # instance. Leave it UNCOUNTED (neither completed nor
                    # failed) and hand control to the resume driver, which
                    # re-sends it while skipping the delivered prefix - so
                    # nothing is lost and nothing is double counted.
                    logging.warning(
                        "[DIMSE-OUT] %s:%d: association LOST after %d/%d "
                        "C-STORE (no response). %s",
                        getattr(assoc, "ae_title", "?"),
                        getattr(assoc, "port", 0),
                        completed,
                        total if total else idx + 1,
                        (
                            "Resuming once."
                            if _report_lost and not _resumed
                            else "Viewer must re-request or resume fails."
                        ),
                    )
                    prefetch.stop()
                    resp.close()
                    return _out(lost=True)
                if status.Status == 0x0000:
                    completed += 1
                    if sent_via_refetch:
                        transcoded += 1
                    else:
                        passthrough += 1
                    # A-M-03: the byte counter describes bytes the peer ACCEPTED.
                    # Counting at send time recorded attempts - a resumed instance
                    # was counted again, and the ambiguous-timeout branch counted
                    # a send whose outcome nobody observed - under a metric name
                    # the dashboards read as delivered traffic.
                    try:
                        bytes_total.labels(direction="tx", peer=ae_label(peer_ae)).inc(
                            part_size
                        )
                    except Exception:
                        pass
                    # Bridge: track successfully sent SOPs for Storage Commitment
                    if sop_uid:
                        sent_sop_uids.append((sop_class_uid, sop_uid))
                        # Also on the JOB, immediately: this list is what the
                        # resume skips, and a pass that raises never returns
                        # its local copy - so an acknowledged instance was
                        # re-sent on the resumed pass.
                        try:
                            move_jobs.add_job_delivered_sop(
                                job_id, sop_uid, sop_class_uid
                            )
                        except Exception:
                            logging.debug(
                                "[C-MOVE] Job #%d: delivered SOP not recorded",
                                job_id,
                            )
                else:
                    _st = int(status.Status or 0)
                    if 0xB000 <= _st <= 0xBFFF:
                        # PS3.4 B.2.3.1: a Warning status means the SCP ACCEPTED
                        # the instance and stored it, having coerced one or more
                        # elements. Counting it failed listed the SOP as
                        # undelivered, made the move answer 0xC000, and re-sent
                        # it on resume - while the peer already holds it.
                        # Warnings are tracked on their own counter.
                        warned += 1
                        completed += 1
                        if sent_via_refetch:
                            transcoded += 1
                        else:
                            passthrough += 1
                        try:
                            cstore_warnings.labels(peer=ae_label(peer_ae)).inc()
                        except Exception:
                            pass
                        if sop_uid:
                            sent_sop_uids.append((sop_class_uid, sop_uid))
                            try:
                                move_jobs.add_job_delivered_sop(
                                    job_id, sop_uid, sop_class_uid
                                )
                            except Exception:
                                logging.debug(
                                    "[C-MOVE] Job #%d: delivered SOP not recorded",
                                    job_id,
                                )
                        logging.warning(
                            "[C-MOVE] C-STORE warning for instance %d: status=%s "
                            "- instance stored by the peer, counted as "
                            "acknowledged",
                            idx + 1,
                            _dimse_status_name(_st),
                        )
                    else:
                        failed += 1
                        logging.warning(
                            "[C-MOVE] C-STORE failed for instance %d: status=%s",
                            idx + 1,
                            _dimse_status_name(_st),
                        )
            except (requests.RequestException, OSError, ValueError, KeyError) as e:
                failed += 1
                if spill_path is not None:
                    # W3: the send file was never handed to pynetdicom - drop
                    # the spill file right here (the inner finally is not hit).
                    _unlink_quiet(spill_path)
                logging.warning(
                    "[C-MOVE] C-STORE error for instance %d/%d: %s",
                    idx + 1,
                    total,
                    e,
                )
                logging.debug(
                    "[C-MOVE] C-STORE traceback for instance %d/%d:",
                    idx + 1,
                    total,
                    exc_info=True,
                )

            # Bridge: update job progress counters.
            #
            # The RESUMED pass reports the UNION with what pass 1 delivered,
            # not its own zero-based counters. A resumed pass restarts
            # `completed` at 0 because it skips the delivered prefix, so
            # writing it verbatim told the poller "0 of N delivered" - and a
            # poll timeout there answered 0xC000 for a study whose first pass
            # had delivered most of it. The driver still reconciles the final
            # numbers; this only keeps the LIVE row honest, which is what the
            # poller reads.
            #
            # `completed` sums because pass 2 counts only what it added; the
            # resumed pass already covered the full study (`total = idx + 1`
            # is set BEFORE the skip), so `total` and `failed` must not be
            # SUMMED with the prior pass - a re-failed instance is the same
            # failure, not a second one, and `total + prior` double-counts
            # the skipped prefix.
            move_jobs.update_job_progress(
                job_id,
                completed + _prior_completed,
                max(failed, _prior_failed) if _resumed else failed,
                max(total, _prior_total) if _resumed else total,
            )

    except (requests.RequestException, OSError, ValueError, KeyError) as _stream_err:
        # The READ failed, not a single instance: `for part, idx, part_ts in
        # prefetch` raises the reader thread's error here (a truncated chunked
        # body, a missing Content-Length, a socket reset mid-part). Letting it
        # escape to the driver cost it this pass's `sent_sop_uids`, so the
        # resume re-sent everything already delivered and a pass without a
        # resume answered 0xC000 ("nothing delivered") for a study that had
        # moved most of its instances. Returning `_out(lost=True)` hands the
        # partial delivered list to the caller, which reconciles by union.
        logging.warning(
            "[C-MOVE] Job #%d: stream read failed after %d delivered (%s) - "
            "reporting the partial pass so the resume can continue",
            job_id,
            completed,
            _stream_err,
        )
        logging.debug("[C-MOVE] stream read traceback:", exc_info=True)
        return _out(lost=True)

    finally:
        prefetch.stop()
        resp.close()

    if total == 0:
        logging.info(
            "[C-MOVE] Job #%d: study %s returned 0 instances", job_id, study_uid
        )

    logging.info(
        "[C-MOVE] Job #%d study %s: passthrough=%d transcoded=%d refetched=%d"
        " resumed=%d",
        job_id,
        study_uid,
        passthrough,
        transcoded,
        refetched,
        1 if _resumed else 0,
    )
    logging.info(
        "[C-MOVE] Streamed study %s: %d instances, %d bytes total",
        study_uid,
        total,
        total_bytes,
    )

    return _out()

# ---------------------------------------------------------------------------
# Bridge: A-RELEASE with A-ABORT fallback (polite first, then force)
# ---------------------------------------------------------------------------
def _release_or_abort(assoc, timeout=3.0):
    """Polite A-RELEASE, then A-ABORT if viewer doesn't respond.

    Release politely first, but do not wait forever.
    Data is already delivered (C-STORE-RSP status=0x0000 received
    for every instance). A-RELEASE is protocol courtesy, not data integrity.

    Orthanc/dcm4che: both try A-RELEASE with a timeout, then force-close.
    pynetdicom: release() blocks indefinitely if peer doesn't respond.
    This wrapper adds the missing timeout.
    """
    if assoc is None or not assoc.is_established:
        return

    released = threading.Event()

    def _do_release():
        try:
            assoc.release()
        except Exception:
            pass
        finally:
            released.set()

    t = threading.Thread(target=_do_release, daemon=True)
    t.start()

    if not released.wait(timeout=timeout):
        peer = getattr(assoc, "ae_title", "?")
        logging.warning(
            "[DIMSE] A-RELEASE timed out after %.0fs - " "sending A-ABORT to %s",
            timeout,
            peer,
        )
        try:
            assoc.abort()
        except Exception:
            pass

    t.join(timeout=1.0)

# ---------------------------------------------------------------------------
# Bridge: execute a single C-MOVE job: stream -> send -> finish
# ---------------------------------------------------------------------------
# Delivered UIDs recovered from the job record carry no SOP class when the
# class was never recorded (an older row): the class is only needed for the
# C-STORE context, which is already negotiated, so an empty string is harmless
# there. Storage Commitment is skipped for such an entry, because a
# Referenced SOP Class that was never observed must not be invented.
_SOP_CLASS_UNKNOWN = ""

def _delivered_sops_of(move_jobs, job_id):
    """`[(sop_class, sop_uid), ...]` the job has already delivered, or None.

    Read back after a pass raised: the pass's return value is the only other
    carrier of this set, and a raise never produces one. `None` means the
    record could not be read, so the caller keeps its aggregate fallback.
    """
    getter = getattr(move_jobs, "get_job_delivered_sops", None)
    if getter is None:
        return None
    try:
        return [(cls or _SOP_CLASS_UNKNOWN, uid) for cls, uid in getter(job_id)]
    except Exception:
        return None

def _job_total_of(move_jobs, job_id):
    """Instances the job has observed so far (0 when unreadable)."""
    try:
        _c, total, _s = move_jobs.get_job_progress(job_id)
        return int(total or 0)
    except Exception:
        return 0

def _execute_cmove_job(
    job_id,
    study_uid,
    move_dest_ae,
    move_jobs,
    clarus_url,  # Clarus Server DICOMweb base URL (single knob, 2908)
    http_timeout,
    bridge_ae_title,  # Bridge: own AE Title for C-STORE associations
    target_host="",  # Resolved Move Destination host (subnet support)
    target_port=0,  # Resolved Move Destination port
    sop_registry=None,
    storage_commit_after_move=True,
    sop_index=None,
    peers_file=None,
    outbound_network_timeout=60,
    outbound_dimse_timeout=60,
    outbound_acse_timeout=15,
    outbound_assoc_attempts=3,
    tls=None,
    spill_threshold=SPILL_THRESHOLD,
    expose_rejected=False,
    qa_url="",
    request_level="",
    request_series_uid="",
    request_sop_uid="",
    registry_host="",
):
    """Execute C-MOVE: stream study from Clarus, send instances to target SCP.

    Stage 1 (bridge-only): before the main A-ASSOCIATE a lightweight
    pre-flight learns each class's stored TS set from the standard metadata
    resource so the association proposal can carry per-TS contexts;
    delivery follows the negotiation result. Retry policy is the single
    outbound_assoc_attempts knob with immediate retries.

    1. Pre-flight stored TS - best effort, never fails the job.
    2. Stream study as multipart DICOM from Clarus (WADO-RS) - no temp file.
    3. Send each instance via C-STORE to move_dest_ae.
    4. Check C-MOVE-CANCEL before each C-STORE.
    5. Optionally send Storage Commitment N-ACTION after success.
    """
    # Bridge: target_host/target_port come from job (resolved in handle_c_move).
    # No re-lookup needed  -  subnet resolution happened at C-MOVE time.
    #
    # `registry_host` is the peers.conf key the destination matched under. For
    # a CIDR peer it is the SUBNET, while target_host is the client IP the
    # association goes to; `scp_targets` is keyed by the former, so SCP health
    # is recorded against it. A legacy job (no column) falls back to the
    # connection address, which is what it recorded before.
    health_host = registry_host or target_host
    if not target_host or not target_port:
        # Legacy job without target info  -  fall back to lookup
        if peers_file:
            move_jobs.reload_peers_from_file(peers_file)
        target = move_jobs.lookup_scp(move_dest_ae)
        if target is None:
            logging.error(
                "[C-MOVE] Unknown Move Destination: %s",
                move_dest_ae,
            )
            if move_jobs.finish_job(
                job_id,
                success=False,
                error_message=f"Unknown Move Destination: {move_dest_ae}",
            ):
                move_jobs_counter.labels(status="failed").inc()
            return
        target_host, target_port = target

    assoc = None
    gate_held = False
    try:
        # Per-peer job gate: serialize jobs to the same peer (busy exclusion).
        # No post-job cooldown: the next job starts immediately once the
        # previous one to this peer ends. Taken inside the try so the
        # finally releases it on every path, including a pre-flight raise.
        # The wait gives up on shutdown or on cancellation of THIS job: a
        # stopped bridge must not block its worker join on a slow peer.
        def _give_up_gate():
            if _shutdown_requested.is_set():
                return True
            try:
                return bool(move_jobs.is_job_cancelled(job_id))
            except Exception:
                return False

        _job_gate_enter(target_host, target_port, move_dest_ae, _give_up_gate)
        gate_held = True

        # -- Pre-flight: learn each class's stored TS BEFORE the association
        # (best effort - any failure degrades to the default proposal). --
        _pre = _preflight_study_ts_by_class(
            study_uid,
            clarus_url,
            http_timeout=2.0,
            tls=tls,
            budget_s=4.0,
            expose_rejected=expose_rejected,
            qa_url=qa_url,
        )
        study_ts_by_class, partial_preflight = _split_preflight(_pre)

        try:
            assoc, accepted_contexts_map = _associate_for_move(
                move_dest_ae,
                bridge_ae_title,
                sop_registry,
                target_host,
                target_port,
                network_timeout=outbound_network_timeout,
                dimse_timeout=outbound_dimse_timeout,
                acse_timeout=outbound_acse_timeout,
                outbound_assoc_attempts=outbound_assoc_attempts,
                study_ts_by_class=study_ts_by_class,
                partial_preflight=partial_preflight,
            )
        except RuntimeError as e:
            logging.error("[C-MOVE] %s", e)
            logging.debug("[C-MOVE] Association traceback:", exc_info=True)
            move_jobs.record_scp_failure(move_dest_ae, host=health_host)
            if move_jobs.finish_job(job_id, success=False, error_message=str(e)):
                move_jobs_counter.labels(status="failed").inc()
            return

        server_ts_list = _get_clarus_transfer_syntaxes(clarus_url, tls=tls)

        _suppress_state.suppress = True
        # -- Resume driver: at most ONE resume. The whole study is
        # re-streamed on a FRESH GET for the resumed pass (a conformant
        # continuation; PS3.7 9.1.4.2(e) / PS3.8 9.1.4 Note 2 + 9.1.5), and
        # only the SOP UIDs NOT yet delivered are re-sent, so each instance
        # is delivered at most once. Counters are reconciled by UNION of the
        # delivered sets at the end (never sum regression). --
        study_sop_uids = None
        try:
            # Authoritative SOP list for the (0008,0058) tail ++ total, scoped
            # to the requested level (PS3.4 C.4.2.1.2).
            study_sop_uids = _study_sop_uids(
                study_uid,
                clarus_url,
                tls=tls,
                expose_rejected=expose_rejected,
                qa_url=qa_url,
                request_level=request_level,
                request_series_uid=request_series_uid,
                request_sop_uid=request_sop_uid,
            )
        except Exception:
            study_sop_uids = None
        sent_sop_uids = []  # union across passes (SC material)
        cancelled = False
        no_common_ts = False
        resumed_lost = False
        # Bound BEFORE the passes: the reconciliation below reads it on every
        # path, including a pass 2 that never ran (no resume, or a resume whose
        # re-association failed). A name that only exists inside the pass-2
        # try is read through a default and hides exactly this kind of gap.
        _fs2 = []

        # Pass 1 (initial).
        try:
            r1 = _stream_and_send_study(
                assoc,
                study_uid,
                clarus_url,
                http_timeout,
                move_jobs,
                job_id,
                accepted_contexts_map=accepted_contexts_map,
                server_ts_list=server_ts_list,
                sop_registry=sop_registry,
                tls=tls,
                spill_threshold=spill_threshold,
                peer_ae=move_dest_ae,
                _skip_ids=None,
                _resumed=False,
                _report_lost=True,
                request_level=request_level,
                request_series_uid=request_series_uid,
                request_sop_uid=request_sop_uid,
                expose_rejected=expose_rejected,
                qa_url=qa_url,
            )
            _c1, _f1, _t1, _s1, _fs1, _ca1, _nc1, _lost1 = r1
            sent_sop_uids = list(_s1)
            cancelled = _ca1
            no_common_ts = _nc1
            resumed_lost = _lost1
        except Exception:
            # A mid-stream raise does not undo what was already delivered.
            #
            # The counters and the delivered UID list live in the pass's return
            # value, which a raise never produces - so rebuilding the resume
            # state from `get_job_progress` kept only AGGREGATE numbers and the
            # skip set came back EMPTY. The resumed pass then re-sent instances
            # the destination had already acknowledged. The per-instance
            # accounting is recovered from the job's own delivered list
            # instead; the aggregate counters remain the fallback for a job
            # whose list is unreadable.
            logging.error(
                "[C-MOVE] Job #%d: pass 1 raised mid-stream - preserving the "
                "progress counted so far",
                job_id,
            )
            recovered = _delivered_sops_of(move_jobs, job_id)
            if recovered is not None:
                sent_sop_uids = list(recovered)
                _c1 = len(recovered)
                _t1 = max(_c1, _job_total_of(move_jobs, job_id))
                _f1 = 0
            else:
                try:
                    # (completed_instances, total_instances, status), the same
                    # counters the 0xFF00 poll reports and the final RSP sums.
                    _c1, _t1, _ = move_jobs.get_job_progress(job_id)
                    _f1 = max(0, _t1 - _c1)
                except Exception:
                    _c1, _f1, _t1 = 0, 0, 0
            _fs1 = []
            cancelled = False
            no_common_ts = False
            # Do NOT re-raise: the bare `raise` let the worker's outer handler
            # finish the job without `set_job_failed_sops`, so the final
            # 0xB000/0xC000 carried an EMPTY (0008,0058) even though
            # instances were lost. Marking the pass lost routes into the
            # reconciliation below, which builds the failed list from the
            # study SOP set and persists it.
            resumed_lost = True

        # Resume ONCE on association loss (not on cancel/shutdown/no-common).
        if resumed_lost and not cancelled and not no_common_ts:
            delivered1 = {u for _c, u in sent_sop_uids if u}
            logging.info(
                "[C-MOVE] Job #%d: association lost after %d delivered - "
                "re-associating ONCE to resume (skip %d delivered)",
                job_id,
                len(delivered1),
                len(delivered1),
            )
            _release_or_abort(assoc)
            assoc = None
            try:
                assoc, accepted_contexts_map = _associate_for_move(
                    move_dest_ae,
                    bridge_ae_title,
                    sop_registry,
                    target_host,
                    target_port,
                    network_timeout=outbound_network_timeout,
                    dimse_timeout=outbound_dimse_timeout,
                    acse_timeout=outbound_acse_timeout,
                    outbound_assoc_attempts=outbound_assoc_attempts,
                    study_ts_by_class=study_ts_by_class,
                    partial_preflight=partial_preflight,
                )
            except RuntimeError as e:
                # Resume's re-association failed -> GIVE_UP (honest partial).
                logging.error(
                    "[C-MOVE] Job #%d: resume re-association failed (%s) - "
                    "GIVE_UP with the delivered prefix",
                    job_id,
                    e,
                )
                resumed_lost = True
            else:
                # Pass 2 (resumed) - only the still-undelivered instances.
                try:
                    r2 = _stream_and_send_study(
                        assoc,
                        study_uid,
                        clarus_url,
                        http_timeout,
                        move_jobs,
                        job_id,
                        accepted_contexts_map=accepted_contexts_map,
                        server_ts_list=server_ts_list,
                        sop_registry=sop_registry,
                        tls=tls,
                        spill_threshold=spill_threshold,
                        peer_ae=move_dest_ae,
                        _skip_ids=delivered1,
                        _resumed=True,
                        _report_lost=True,
                        _prior_completed=_c1,
                        _prior_failed=_f1,
                        _prior_total=_t1,
                        request_level=request_level,
                        request_series_uid=request_series_uid,
                        request_sop_uid=request_sop_uid,
                        expose_rejected=expose_rejected,
                        qa_url=qa_url,
                    )
                    _c2, _f2, _t2, _s2, _fs2, _ca2, _nc2, _lost2 = r2
                    # Merge pass 2 into what is ALREADY accumulated, never
                    # into `_s1`: when pass 1 raised, `_s1` was never assigned
                    # and this expression raised UnboundLocalError, which the
                    # `except` below swallowed - so B was reported failed even
                    # though the destination acknowledged it.
                    sent_sop_uids = list(sent_sop_uids) + list(_s2)
                    cancelled = cancelled or _ca2
                    no_common_ts = no_common_ts or _nc2
                    resumed_lost = _lost2  # second loss => GIVE_UP below
                except Exception:
                    # The resumed pass may have delivered instances before it
                    # raised, and a raise never produces a return value. Read
                    # the job's own delivered journal so those
                    # acknowledgements are not reported as failures.
                    recovered2 = _delivered_sops_of(move_jobs, job_id)
                    if recovered2 is not None:
                        known = {u for _c, u in sent_sop_uids if u}
                        sent_sop_uids = list(sent_sop_uids) + [
                            (None, u) for u in recovered2 if u not in known
                        ]
                    resumed_lost = True

        if resumed_lost:
            logging.warning(
                "[C-MOVE] Job #%d: gave up after association failure or "
                "failed resume - finishing as a partial job",
                job_id,
            )

        # Reconcile the final counters by UNION of the delivered SOP UIDs.
        # Every instance is either delivered (its SOP uid is in sent_sop_uids)
        # or failed - never double counted, never a sum regression. The
        # authoritative study SOP list (when available) fixes
        # `total` and gives the honest (0008,0058) tail.
        delivered = {u for _c, u in sent_sop_uids if u}
        completed = len(delivered)
        _obs_total_p1 = _t1 if not no_common_ts else 0
        # The resumed pass observed the study AGAIN on a fresh GET. Its total
        # is the widest view the job ever got, and on a failed re-association
        # `_t2` was never assigned - the binding stays inside the `try` that
        # raised, so it is read through a default instead of a NameError.
        _obs_total_p2 = (locals().get("_t2", 0) or 0) if not no_common_ts else 0
        # What the passes OBSERVED as undelivered. This is evidence from the
        # transfer itself and outranks the cached enumeration, which can be
        # STALE: the WADO stream may hold instances the cache does not (a study
        # that grew between the enumeration and the stream), and the peer can
        # reject one of those. Reconciling only against the cache reported
        # Success for a job that really left an instance behind.
        observed_failed = {u for u in (set(_fs1) | set(_fs2)) if u}
        observed_failed -= delivered
        if study_sop_uids is not None and study_sop_uids:
            study_uids_set = set(study_sop_uids)
            # The cache fixes the ORDER and the baseline of the tail, and the
            # observed failures extend BOTH membership and total: an instance
            # the cache never listed but the peer refused is part of the
            # result, or the report claims a completeness the transfer did not
            # have.
            # The cache fixes the ORDER and the baseline of the tail, the
            # delivered set and the observed failures extend BOTH membership
            # and total. A UID the cache never listed but the transfer
            # delivered is part of the result too: excluding it made the total
            # smaller than the completed count on a study that grew between the
            # enumeration and the stream.
            total = len(study_uids_set | observed_failed | delivered)
            ordered_uids = list(study_sop_uids) + sorted(
                u for u in observed_failed if u not in study_uids_set
            )
        else:
            # No authoritative list (degradation): total = largest pass total.
            # Pass 2 is included ONLY when it actually ran: a resumed job that
            # gave up mid-study still saw the rest of the study on its fresh
            # GET, and ignoring that total reported 0 failures for a job whose
            # GIVE_UP is the one thing we know about it (PS3.4 C.4.2.1.4.2:
            # the final status must be honest about undelivered instances).
            total = max(_obs_total_p1, _obs_total_p2, completed, len(observed_failed))
            ordered_uids = None
        if ordered_uids is not None:
            failed_sop_uids = [u for u in ordered_uids if u not in delivered]
        else:
            # Degrade to the per-attempt failed sets when present, else [].
            #
            # Both passes lose instances: _fs1 and _fs2 still name what each
            # pass OBSERVED as failed, so dropping them left (0008,0058) EMPTY
            # on a 0xB000 - PS3.4 C.4.2.1.4.2 requires the list on a Failure,
            # Warning or Cancel final. The union may be incomplete (an
            # unobserved tail cannot be named), but it must not be empty when
            # the status says instances were lost.
            #
            # Subtracting `delivered` is what makes the union honest: each
            # pass reports `seen in THIS pass minus delivered in THIS pass`,
            # so an instance lost in pass 1 and delivered in pass 2 is still
            # in _fs1, and an instance delivered in pass 1 and skipped by
            # pass 2 is in _fs2 (a skipped instance is not in pass 2's sent
            # list). Naming either in (0008,0058) answered 0xB000 for a
            # complete transfer and skipped Storage Commitment.
            observed_failed = set(_fs1) | set(_fs2)
            # If nothing was ever OBSERVED failing the list stays empty: no UID
            # may be invented, and the floors below still keep the status
            # honest. An empty list here is the best available answer, not an
            # oversight.
            failed_sop_uids = sorted(
                u for u in observed_failed if u and u not in delivered
            )
        # PS3.4 C.4.2.1.4.2: the failure count is the number of instances
        # that were seen and NOT delivered, which is exactly the (0008,0058)
        # list. Deriving it as `total - completed` counted every instance
        # that never reached this pass at all as a failure, so a resumed job
        # reported failures it never observed.
        failed = len(failed_sop_uids)
        # Ensure total never falls below the delivered count.
        total = max(total, completed)
        # Lower bound: an instance whose SOP UID never parsed (empty UID)
        # never entered seen_sop_uids / _fs1, so len(failed_sop_uids) can be
        # 0 while the study still holds more instances than were delivered -
        # which would answer 0x0000 for a study with losses. The gap between
        # what the study holds and what was delivered is the honest floor.
        failed = max(failed, total - completed)

        # Lower bound on the failure count. With no authoritative list the
        # failed tail cannot be named from `_fs1`/`_fs2`, so the job could
        # claim 0 failures while `resumed_lost` says the study was cut short:
        # at least one instance is unaccounted for, and PS3.4 C.4.2.1.4.2
        # forbids answering 0x0000 for a study with losses.
        if resumed_lost and not failed and not (study_sop_uids or []):
            failed = 1
            logging.info(
                "[C-MOVE] Job #%d: no authoritative SOP list and the resume "
                "failed - reporting at least one undelivered instance",
                job_id,
            )

        # 0709: persist the (0008,0058) Failed SOP Instance UID List so the
        # C-MOVE generator can attach it to the final Failed/Warning/Cancel
        # status (PS3.4 C.4.2.1.4.2).
        try:
            move_jobs.set_job_failed_sops(job_id, failed_sop_uids)
        except Exception:
            # Best-effort: the progress/status path must not fail on logging.
            logging.debug("[C-MOVE] set_job_failed_sops failed for job #%d", job_id)

        # Store the RECONCILED counters before the job is finished. The last
        # write so far came from _stream_and_send_study, which reports the
        # current pass only: after a resume pass 2 restarts `completed` at 0, so
        # a job that delivered 100 instances and then failed its first unsent
        # one was stored as completed=0 and the reactor answered 0xC000 ("no
        # SOP instances delivered") although 100 had arrived.
        try:
            move_jobs.update_job_progress(job_id, completed, failed, total)
        except Exception as e:
            logging.debug("[C-MOVE] reconciled progress write failed: %s", e)

        # A C-STORE Warning means the peer STORED the instance (PS3.4
        # B.2.3.1), so those UIDs stay out of the failed/undelivered tail. The
        # tally itself is recorded by `_stream_and_send_study` as it goes (see
        # `set_job_warning_count`), because the reactor - not this function -
        # builds the final C-MOVE-RSP that reports 0xB000 for them.

        if no_common_ts:
            # No common transfer syntax: the job ends failed with zero slices
            # delivered, so the C-MOVE generator emits a Failure (0xC000) -
            # not 0xC001 (which was a log-only claim; it is not a response
            # status). The viewer log and the wire now agree.
            logging.warning(
                "[C-MOVE] Job #%d: no common transfer syntax - "
                "job ends failed, 0 slices, C-MOVE-RSP is a Failure (0xC000)",
                job_id,
            )
            if move_jobs.finish_job(
                job_id,
                success=False,
                error_message="No common transfer syntax between viewer and server",
            ):
                move_jobs_counter.labels(status="failed").inc()
            return

        if cancelled:
            if move_jobs.is_job_cancelled(job_id):
                finished = move_jobs.finish_job(
                    job_id, success=False, error_message="Cancelled by SCU"
                )
            else:
                finished = move_jobs.finish_job(
                    job_id, success=False, error_message="Shutdown"
                )
            if finished:
                move_jobs_counter.labels(status="failed").inc()
            return

        # -- Storage Commitment after successful C-MOVE --
        # Controlled by [dimse] no_storage_commit config flag only.
        # The commit push is attempted only when Storage Commitment was
        # the commit push is attempted ONLY when Storage Commitment was
        # negotiated in the MAIN association (_associate_for_move requests
        # it). Viewers without SC (MicroDicom) burned ACSE timeouts when a
        # separate SC-only association was opened - skip instead of trying.
        # A failed re-association leaves `assoc` None (released above and only
        # re-created on success), so reading `accepted_contexts` here would
        # raise AttributeError out of the worker and lose the honest partial
        # result the job already earned.
        if failed == 0 and total > 0 and assoc is not None:
            if storage_commit_after_move and sent_sop_uids:
                sc_negotiated = any(
                    str(ctx.abstract_syntax) == StorageCommitmentPushModel
                    for ctx in assoc.accepted_contexts
                )
                if not sc_negotiated:
                    logging.info(
                        "[C-MOVE] Job #%d: Storage Commitment not negotiated "
                        "in the main association - skipping SC push",
                        job_id,
                    )
                else:
                    try:
                        _send_storage_commitment(
                            move_dest_ae,
                            target_host,
                            target_port,
                            sent_sop_uids,
                            bridge_ae_title,
                            assoc=assoc,
                        )
                    except Exception as e:
                        logging.warning(
                            "[C-MOVE] Job #%d: Storage Commitment push failed: %s",
                            job_id,
                            e,
                        )

        # -- Record SCP result  -  the peer is HEALTHY if the association was
        # established and (some or all) slices were delivered. A partial job
        # (failed > 0) is NOT a peer failure: a single bad minute must not
        # evict an alive peer, so only a MAIN-association failure (handled in
        # the RuntimeError catch above) touches the consecutive-failure
        # counter (D3, spec task #1).
        if failed == 0 and total > 0:
            move_jobs.record_scp_success(move_dest_ae, host=health_host)

        # -- Finish job --
        job_success = failed == 0 and total > 0
        if move_jobs.finish_job(
            job_id,
            success=job_success,
            error_message=f"{completed} sent, {failed} failed" if failed > 0 else None,
        ):
            # Count only when THIS call finished the job: the poll reactor
            # can finish it first, and a second bump would double-count.
            move_jobs_counter.labels(
                status="completed" if job_success else "failed"
            ).inc()
        logging.info(
            "[C-MOVE] Job #%d finished: %d/%d success, %d failed",
            job_id,
            completed,
            total,
            failed,
        )

        if failed == 0 and total > 0:
            logging.debug("[C-MOVE] Job #%d: all %d instances succeeded", job_id, total)
        elif completed > 0 and failed > 0:
            logging.info(
                "[C-MOVE] Job #%d: partial - %d/%d succeeded, %d failed",
                job_id,
                completed,
                total,
                failed,
            )
        else:
            logging.info("[C-MOVE] Job #%d: no instances delivered", job_id)

    except requests.exceptions.RequestException as e:
        logging.error("[C-MOVE] Download/stream failed for job #%d: %s", job_id, e)
        logging.debug(
            "[C-MOVE] Download/stream traceback for job #%d:", job_id, exc_info=True
        )
        if move_jobs.finish_job(
            job_id, success=False, error_message=f"Download failed: {e}"
        ):
            move_jobs_counter.labels(status="failed").inc()
    except _AssocGateAborted:
        # Bridge stopping (or this job cancelled) while the peer was busy.
        # Not a peer failure: the job stays resumable, so leave the
        # consecutive-failure counter alone.
        logging.info(
            "[C-MOVE] Job #%d abandoned while waiting for %s", job_id, move_dest_ae
        )
    finally:
        _suppress_state.suppress = False
        _release_or_abort(assoc)
        # Release the peer gate so the next job to this peer can start.
        if gate_held:
            _job_gate_exit(target_host, target_port, move_dest_ae)

# ---------------------------------------------------------------------------
# Bridge: C-MOVE background worker pool  -  parallel execution
# ---------------------------------------------------------------------------
def _cmove_worker(
    move_jobs,
    clarus_url,  # Clarus Server DICOMweb base URL (single knob, 2908)
    http_timeout,
    bridge_ae_title,
    num_workers=2,
    sop_registry=None,
    storage_commit_after_move=True,
    sop_index=None,
    peers_file=None,
    outbound_network_timeout=60,
    outbound_dimse_timeout=60,
    outbound_acse_timeout=15,
    outbound_assoc_attempts=3,
    tls=None,
    qa_url="",
):
    """Multi-threaded C-MOVE job executor.

    Spawns num_workers threads, each picking one pending job from queue.
    Executes: pre-flight -> stream -> send -> finish.
    Sleeps 5 seconds when queue is empty.
    Checks _shutdown_requested before each iteration.
    """

    def _worker_loop(worker_id):
        """Single worker thread: pick job, execute, repeat."""
        logging.info("[C-MOVE] Worker-%d started", worker_id)

        while not _shutdown_requested.is_set():
            # Bridge: pick next pending job, LIMIT 1, RESERVING its peer
            # atomically.
            #
            # The reservation is the claim test, not a peek: an earlier design
            # read "is the peer busy?" and then claimed the row as two steps,
            # so two workers could both find the peer free and claim two jobs
            # for it - one then parked in the gate while a job for a DIFFERENT
            # peer sat unserved. A failed reservation hands the row back
            # WITHOUT charging an attempt, so a busy peer never burns a job's
            # retry budget.
            job = None
            while job is None and not _shutdown_requested.is_set():
                job = move_jobs.pick_pending_job(
                    timeout=1.0,
                    reserve=lambda host, port, ae: (
                        _try_reserve_peer(host, int(port), ae)
                        if host and port
                        else True
                    ),
                    release=lambda host, port, ae: (
                        _job_gate_exit(host, int(port), ae) if host and port else None
                    ),
                )
            if job is None:
                continue

            job_id = job["id"]
            study_uid = job["study_uid"]
            move_dest_ae = job["move_dest_ae"]
            attempt = job["attempts"]
            # Queued over the Expose Rejected Instances AE? Read from the job
            # row, not the event: the worker outlives the association.
            job_expose_rejected = bool(job.get("expose_rejected", 0))

            # Bridge: log retry attempts for recovery awareness
            if attempt > 0:
                logging.info(
                    "[C-MOVE] Worker-%d: Job #%d retry attempt %d (recovery)",
                    worker_id,
                    job_id,
                    attempt + 1,
                )

            logging.info(
                "[C-MOVE] Worker-%d picked job #%d: Study=%s -> %s (attempt %d)",
                worker_id,
                job_id,
                study_uid,
                move_dest_ae,
                attempt + 1,
            )

            try:
                # Bridge: execute C-MOVE job
                _execute_cmove_job(
                    job_id,
                    study_uid,
                    move_dest_ae,
                    move_jobs,
                    clarus_url,
                    http_timeout,
                    bridge_ae_title,
                    target_host=job.get("target_host", ""),
                    target_port=job.get("target_port", 0),
                    sop_registry=sop_registry,
                    storage_commit_after_move=storage_commit_after_move,
                    sop_index=sop_index,
                    peers_file=peers_file,
                    outbound_network_timeout=outbound_network_timeout,
                    outbound_dimse_timeout=outbound_dimse_timeout,
                    outbound_acse_timeout=outbound_acse_timeout,
                    outbound_assoc_attempts=outbound_assoc_attempts,
                    tls=tls,
                    expose_rejected=job_expose_rejected,
                    qa_url=qa_url,
                    request_level=job.get("request_level", ""),
                    request_series_uid=job.get("request_series_uid", ""),
                    request_sop_uid=job.get("request_sop_uid", ""),
                    registry_host=job.get("registry_host", ""),
                )
            except Exception as e:
                logging.error(
                    "[C-MOVE] Worker-%d: Job #%d failed with exception: %s",
                    worker_id,
                    job_id,
                    e,
                )
                if move_jobs.finish_job(job_id, success=False, error_message=str(e)):
                    move_jobs_counter.labels(status="failed").inc()
            finally:
                # Release the PICKER's reservation too.
                #
                # `pick_pending_job` reserved this peer at depth 1 and
                # `_execute_cmove_job` took the same gate at depth 2 (it is
                # re-entrant), then released only ITS OWN acquisition on the
                # way out. The depth-1 claim therefore stayed in `_ASSOC_BUSY`
                # for the life of the process, so every other worker saw that
                # peer as permanently busy and skipped its jobs - one job per
                # peer was the effective concurrency limit, and the leak grew
                # with every peer tried.
                _job_gate_exit(
                    job.get("target_host", ""),
                    int(job.get("target_port", 0) or 0),
                    move_dest_ae,
                )
                # Bridge: clear cancel callback after job completes
                move_jobs.clear_job_callback(job_id)

        logging.info("[C-MOVE] Worker-%d stopped", worker_id)

    logging.info("[C-MOVE] Starting %d worker thread(s)", num_workers)
    workers = []
    for i in range(num_workers):
        t = threading.Thread(
            target=_worker_loop,
            args=(i,),
            name=f"cmove-worker-{i}",
            daemon=True,
        )
        t.start()
        workers.append(t)

    # Bridge: wait for all workers to finish (they stop when _shutdown_requested is set)
    for t in workers:
        t.join()

    logging.info("[C-MOVE] All worker threads stopped")

# ---------------------------------------------------------------------------
# Bridge: periodic cleanup of old C-MOVE jobs
# ---------------------------------------------------------------------------
def _cmove_cleanup_worker(move_jobs, max_age_hours=24, commit_tracker_holder=None):
    """Background thread: delete success/failed jobs older than max_age_hours.

    Runs once per hour. Stops when _shutdown_requested is set. The same cycle
    also expires abandoned Storage Commitment batches (R10): they can never be
    delivered, so retaining them forever only grows `commit_jobs`.

    `commit_tracker_holder` is a one-slot list, not the tracker itself: the
    tracker is constructed after this thread starts, and re-reading the slot
    each cycle is simpler than reordering the startup sequence around it.
    """
    max_age_seconds = max_age_hours * 3600
    logging.info(
        "[C-MOVE] Cleanup worker started (max age: %dh)",
        max_age_hours,
    )

    while not _shutdown_requested.is_set():
        # Bridge: sleep 1 hour between cleanup cycles
        _shutdown_requested.wait(timeout=3600.0)
        if _shutdown_requested.is_set():
            break
        move_jobs.cleanup_old_jobs(max_age_seconds)
        tracker = commit_tracker_holder[0] if commit_tracker_holder else None
        if tracker is not None:
            try:
                tracker.purge_abandoned()
            except Exception as e:
                # The retention sweep must not kill the C-MOVE cleanup that
                # shares the cycle.
                logging.error("[COMMIT] abandoned purge failed: %s", e)
        logging.debug("[C-MOVE] Old job cleanup completed")

    logging.info("[C-MOVE] Cleanup worker stopped")

# ---------------------------------------------------------------------------
# Bridge: nevent
# ---------------------------------------------------------------------------

"""Clarus Bridge - N-EVENT-REPORT SCU (Storage Commitment push report).

Closes the RSP->report loop: after the
N-ACTION-RSP is returned, one N-EVENT-REPORT per batch is sent back to the
modality over a SEPARATE SCU association (PS3.4 Push Model).

EventTypeID (PS3.7 F.2 / table): 1 = "Storage Commitment Request Successful",
2 = "Storage Commitment Request Complete - Failures Exist". A failed SOP
carries a Failure Reason in its FailedSOPSequence item (PS3.3 C.14.1.1). The
modality keeps its local copy of any SOP it was NOT confirmed for.
"""

import logging
import threading
import time

from pydicom import Dataset
from pydicom.uid import ImplicitVRLittleEndian
from pynetdicom import AE, build_role
from pynetdicom.sop_class import StorageCommitmentPushModel

# EventTypeID (see module docstring).
EVENT_SUCCESS = 1
EVENT_FAILURE = 2

# PS3.4 J.3.2/J.3.3.1: an N-EVENT-REPORT on the Push Model addresses the SOP
# Instance this SOP Class defines as a constant, created conceptually at SCP
# startup. The Transaction UID is NOT the Affected SOP Instance UID - it travels
# inside the dataset as (0008,1195) and is how the SCU correlates the report with
# its request. Sending the UID as the instance makes a strict SCU drop the
# report: it does not recognise the affected instance as the commitment one.
WELL_KNOWN_SOP_INSTANCE_UID = "1.2.840.10008.1.20.1.1"

# Expected chatter from pynetdicom while a Storage Commitment association is
# negotiated: "No accepted presentation contexts" is the normal answer from an
# SCP that does not implement the push model, and it must not spam the journal.
#
# It is suppressed with a per-THREAD filter on the library logger, not by
# moving the logger's level: the level is one object shared by the whole
# process, so silencing it also dropped every pynetdicom record of the C-STORE
# and C-MOVE workers for as long as an association took (seconds, times the
# retries), for no reason of theirs. A filter sees only the thread that
# installed it, so the level never has to change and no lock is needed.
_PN_QUIET = threading.local()

def _pn_quiet_filter(record):
    """Drop pynetdicom records from a thread that asked for silence."""
    return not getattr(_PN_QUIET, "on", False)

# PS3.4 J.3.2 / J.3.3: a Storage Commitment transaction needs the requestor to
# receive the N-EVENT-REPORT the SCP pushes back, so the requestor must hold
# BOTH roles. PS3.7 D.3.3.4 spells the requestor's proposal as an SCP/SCU Role
# Selection item, which is a SEPARATE negotiation primitive - it is not a
# property of a presentation context (`PresentationContext` only carries the
# acceptor-side scp_role/scu_role), so it must travel in `ext_neg`.

def send_n_event_report(
    host,
    port,
    calling_ae,
    tx_uid,
    event_type,
    success_sops,
    failed_sops,
    bridge_ae_title,
    max_retries=3,
    retry_delay=2.0,
):
    """Send ONE N-EVENT-REPORT-RQ to the modality (SCU role).

    Push model: a separate SCU association to (host, port). Retries with
    fixed backoff; on final failure only a WARN is logged (no persistence in
    v1 - the modality re-requests commitment, and we only confirm what is
    actually stored, so no data is at risk).

    Args:
        success_sops: list of (sop_class_uid, sop_instance_uid).
        failed_sops:  list of (sop_class_uid, sop_instance_uid, failure_reason).
        bridge_ae_title: Calling AE Title for this push - the configured
            [server] ae_title. A modality that knows the commitment-requestor
            AE rejects the report it did not expect, so this is required
            rather than defaulted here.
    """
    reported = False
    last_err = None

    for attempt in range(max_retries + 1):
        if attempt > 0:
            logging.warning(
                "[N-EVENT] Report attempt %d/%d after %.0fs (tx=%s)",
                attempt + 1,
                max_retries + 1,
                retry_delay,
                tx_uid,
            )
            time.sleep(retry_delay)

        ae = AE(ae_title=bridge_ae_title)
        # `connection_timeout` is the ONLY setting that bounds the raw TCP
        # connect: pynetdicom's transport does
        # `socket.settimeout(self.assoc.connection_timeout)` immediately
        # before `socket.connect()`, and the AE default is None - which means
        # blocks for the OS SYN timeout (minutes) behind a black-hole peer.
        # `network_timeout` and `acse_timeout` cover DIMSE and ACSE only, so
        # setting them alone left the connect unbounded (verified against the
        # installed pynetdicom, transport.AssociationSocket.connect).
        ae.connection_timeout = 5
        ae.network_timeout = 5
        ae.acse_timeout = 3
        ae.dimse_timeout = 30
        # PS3.7 D.3.3.4: without a role item the requestor is SCU and the
        # acceptor is SCP, so the SCP could never send the N-EVENT-REPORT that
        # carries the Storage Commitment Result (PS3.4 J.3.3.1). The bridge
        # proposes BOTH roles; a peer that declines leaves the default roles,
        # which the response check below reports.
        ae.add_requested_context(StorageCommitmentPushModel, ImplicitVRLittleEndian)
        sc_role = build_role(StorageCommitmentPushModel, scu_role=True, scp_role=True)

        # "No accepted presentation contexts" is normal for SCPs that
        # do not implement the push model. Quiet ONLY this thread's pynetdicom
        # records around associate() so that expected ERROR does not spam the
        # journal, without touching the level other threads are logging at.
        _pn_logger = logging.getLogger("pynetdicom")
        if _pn_quiet_filter not in _pn_logger.filters:
            # Added once per process; the filter is inert outside a silenced
            # thread, so it never filters anything another thread logs.
            _pn_logger.addFilter(_pn_quiet_filter)
        try:
            _PN_QUIET.on = True
            try:
                assoc = ae.associate(host, port, ae_title=calling_ae, ext_neg=[sc_role])
                try:
                    associations_total.labels(role="to", ae=ae_label(calling_ae)).inc()
                except Exception:
                    pass
            finally:
                _PN_QUIET.on = False
        except Exception as e:
            # A setup error (AE/role construction, a resolver failure, a
            # socket error escaping transport) is a TRANSIENT failure like any
            # other: this attempt has nothing to deliver, so record it and let
            # the loop's backoff try again. Letting it escape turned a
            # recoverable peer problem into an unreported commitment - the
            # verdict was never sent and nothing retried it (PS3.7 D.3.3.4:
            # the association is the transport, not the outcome).
            assoc = None
            last_err = f"association setup failed: {e}"
            logging.warning("[N-EVENT] %s (tx=%s)", last_err, tx_uid)
            continue

        if assoc is None or not assoc.is_established:
            last_err = (
                f"SCP {calling_ae}@{host}:{port} unavailable (attempt {attempt + 1})"
            )
            logging.warning("[N-EVENT] %s", last_err)
            _release_or_abort(assoc, timeout=2.0)
            continue

        # The abstract syntax present in the accepted set is what the
        # presentation context negotiation actually granted, and it is the only
        # thing `send_n_event_report()` selects its context by.
        #
        # `as_scp` is NOT a usable precondition here. It reports the Role
        # Selection outcome, and Role Selection is OPTIONAL (PS3.7 D.3.3.4):
        # an SCP that accepts the Storage Commitment context and simply omits
        # the role item leaves `as_scp` False while the context is perfectly
        # usable. Rejecting on that closed the association before the report
        # was even sent, so a conformant peer never received a report the
        # library would have delivered. The N-EVENT-REPORT RESPONSE is the
        # authority on delivery, and it is checked after the send.
        #
        # `accepted_contexts` only ever holds contexts the acceptor ACCEPTED
        # (PS3.8 9.3.3: a rejected context is reported in the A-ASSOCIATE-AC
        # and is not in this list), so membership is the whole test.
        sc_accepted = any(
            str(ctx.abstract_syntax) == StorageCommitmentPushModel
            for ctx in assoc.accepted_contexts
        )
        if not sc_accepted:
            last_err = (
                f"SCP {calling_ae} did not accept a storage commitment "
                "presentation context"
            )
            logging.warning("[N-EVENT] %s", last_err)
            _release_or_abort(assoc, timeout=2.0)
            continue

        try:
            # EventTypeID (0000,1002) is a COMMAND-SET element (PS3.7 Table
            # 9.1-1); it travels as the separate `event_type` argument to
            # send_n_event_report below, not inside the Event Information data
            # set. Embedding a group-0000 element in the data set makes a
            # strict SCP reject the report.
            ds = Dataset()
            ds.TransactionUID = tx_uid

            if success_sops:
                seq = []
                for sop_class, sop_uid in success_sops:
                    item = Dataset()
                    item.ReferencedSOPClassUID = sop_class
                    item.ReferencedSOPInstanceUID = sop_uid
                    seq.append(item)
                ds.ReferencedSOPSequence = seq

            if failed_sops:
                fseq = []
                for sop_class, sop_uid, reason in failed_sops:
                    item = Dataset()
                    item.ReferencedSOPClassUID = sop_class
                    item.ReferencedSOPInstanceUID = sop_uid
                    item.FailureReason = reason
                    fseq.append(item)
                ds.FailedSOPSequence = fseq

            # pynetdicom 3.x signature: send_n_event_report(dataset, event_type,
            # class_uid, instance_uid) -> (status, response_dataset).
            # PS3.4 J.3.2: the Affected SOP Instance UID is the well-known
            # constant, not the Transaction UID (which is in the dataset).
            status, _resp = assoc.send_n_event_report(
                ds,
                event_type,
                StorageCommitmentPushModel,
                WELL_KNOWN_SOP_INSTANCE_UID,
            )
            if status is None or not hasattr(status, "Status"):
                # PS3.7 9.3: a response is mandatory. An empty one means the
                # association went away mid-request (timeout, abort), and the
                # modality was NOT told the outcome - treating it as delivered
                # stopped the retries and left the commitment never reported.
                last_err = "no N-EVENT-REPORT response"
                logging.warning("[N-EVENT] %s (tx=%s)", last_err, tx_uid)
                continue
            code = status.Status
            logging.info(
                "[N-EVENT] tx=%s type=%d sent to %s: %s (%d ok / %d failed)",
                tx_uid,
                event_type,
                calling_ae,
                _dimse_status_name(code),
                len(success_sops),
                len(failed_sops),
            )
            # PS3.7 9.1: only 0x0000 means the primitive succeeded. Any other
            # code says the SCP did not receive the report, so the modality was
            # never told the outcome - counting it as delivered stopped the
            # retries and left the commitment unreported for good.
            if code == 0x0000:
                reported = True
            else:
                last_err = f"N-EVENT-REPORT rejected with {_dimse_status_name(code)}"
                logging.warning("[N-EVENT] %s (tx=%s)", last_err, tx_uid)
        except Exception as e:
            last_err = f"send_n_event_report error: {e}"
            logging.warning("[N-EVENT] %s (tx=%s)", last_err, tx_uid)
        finally:
            _release_or_abort(assoc, timeout=2.0)

        if reported:
            try:
                nevent_delivered_total.inc()
            except Exception:
                pass
            return True

    logging.error(
        "[N-EVENT] Report NOT delivered for tx=%s after %d attempts: %s",
        tx_uid,
        max_retries + 1,
        last_err,
    )
    try:
        nevent_failed_total.inc()
    except Exception:
        pass
    return False

# ---------------------------------------------------------------------------
# Bridge: main
# ---------------------------------------------------------------------------

"""Clarus Bridge - DIMSE to DICOMweb adapter.

Configuration: clbridge.conf (nginx-style)
Sections: [server], [dicomweb], [dimse], [logging], [metrics], [advanced]

CLI:
  --config <path>   Path to config file (default: ./clbridge.conf)
  --version          Print version and exit
  --help             Print this help
"""

import ctypes
import functools
import logging
import os
import signal
import socket
import sys
import threading
import time

try:
    import yaml
except ImportError:
    yaml = None  # type: ignore

from http.server import ThreadingHTTPServer

from pydicom.uid import ImplicitVRLittleEndian
from pynetdicom import AE, _config, evt
from pynetdicom.sop_class import (
    ModalityPerformedProcedureStep,
    ModalityWorklistInformationFind,
    PatientRootQueryRetrieveInformationModelFind,
    PatientRootQueryRetrieveInformationModelMove,
    StorageCommitmentPushModel,
    StudyRootQueryRetrieveInformationModelFind,
    StudyRootQueryRetrieveInformationModelMove,
)

# pass-through C-STORE - raw bytes from temp file.
# pynetdicom reads file_meta only, sends dataset bytes directly from disk.
# No dcmread(), no encode(), no re-serialization. One line.
_config.STORE_SEND_CHUNKED_DATASET = True

# TS-order constants (IMAGE_TS EVRLE-first etc.) live in clean_code.protocol
# (single definition - the bundle warns on duplicate module-level names).

# Bridge: C-PRINT driver framework - optional, graceful fallback
try:
    from drivers.base import AbstractPrintDriver, PrintResult
    from drivers.generic_dicom import GenericDicomPrintDriver

    _CPRINT_AVAILABLE = True
except ImportError:
    _CPRINT_AVAILABLE = False
    AbstractPrintDriver = None  # type: ignore
    PrintResult = None  # type: ignore
    GenericDicomPrintDriver = None  # type: ignore

import argparse

# SCP peer auto-remove threshold: an auto-registered move destination is
# dropped from the peer list after this many CONSECUTIVE association
# failures.
_SCP_FAILURES_BEFORE_REMOVE = 3

# Watchdog stall threshold. The idle worker refreshes its heartbeat once per
# pass, so this is how long a SINGLE pass (a blocked dequeue, a stuck
# filesystem call) must run before the worker is treated as stalled. The idle
# wait itself is bounded by next_retry_wait_sec() (5s), so a healthy loop stays
# far below this. Named so a test can drive the branch without waiting 120s.
_OUTBOX_STALL_SEC = 120.0

# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# _parse_args - CLI: only --version and --config
# ---------------------------------------------------------------------------
def _parse_args():
    """Parse CLI arguments. Returns argparse.Namespace with --config path only."""
    parser = argparse.ArgumentParser(
        description="Clarus Bridge - DICOM Bridge (C-STORE/C-FIND/C-MOVE/N-ACTION/C-PRINT)"
    )
    parser.add_argument("--version", action="version", version=f"clbridge v{VERSION}")
    # Default config path: next to the .exe (PyInstaller) or .py script.
    # PyInstaller one-file: sys.executable - actual .exe location.
    # Regular Python: __file__ - script location.
    if getattr(sys, "frozen", False):
        _script_dir = os.path.dirname(os.path.abspath(sys.executable))
    else:
        _script_dir = os.path.dirname(os.path.abspath(__file__))
    _default_config = os.path.join(_script_dir, "clbridge.conf")
    parser.add_argument(
        "--config",
        default=_default_config,
        help="Path to configuration file (default: clbridge.conf "
        "in the SCRIPT/EXECUTABLE directory, NOT the current working "
        "directory - pass --config ./clbridge.conf to read the one here)",
    )
    # --regenerate-uids for tests/anonymization (NOT in config - too dangerous for prod)
    parser.add_argument(
        "--regenerate-uids",
        action="store_true",
        default=False,
        help="Regenerate Study/Series/SOP UIDs (tests/anonymization only)",
    )
    return parser.parse_args()

# ---------------------------------------------------------------------------
# CONFIG-DISCIPLINE: _populate_args - read ALL settings from clbridge.conf
# ---------------------------------------------------------------------------
def _populate_args(cfg):
    """Read all configuration values into a namespace. No CLI defaults - config is authoritative.

    Returns argparse.Namespace with all settings populated.
    """
    args = argparse.Namespace()

    # [server]
    args.bridge_host = cfg.get("server", "host", default="127.0.0.1")
    args.bridge_port = cfg.get_int("server", "port", default=8104)
    args.ae_title = cfg.get("server", "ae_title", default="CLBRIDGE")
    # QA / Expose Rejected Instances AE (AIRA 57.2.1). A DIMSE association has
    # no per-query "show rejected" flag, so the standard mechanism is a second
    # AE Title whose queries go to a separately configured QA webservice
    # endpoint. Empty port = off, which leaves the bridge with exactly one AE.
    args.expose_port = cfg.get_int("server", "expose_port", default=None)
    args.expose_ae_title = cfg.get("server", "expose_ae_title", default="CLBRIDGE_QA")
    # [server] require_known_peers: refuse an inbound association whose
    # Calling AE Title is not listed in peers.conf. Default ON - the allowlist
    # is the deployment's own peer list, and an unknown caller is either a
    # typo or an unauthorised peer. A deployment whose modalities cannot be
    # enumerated in the file turns it off; nothing else changes.
    args.require_known_peers = cfg.get_bool(
        "server", "require_known_peers", default=True
    )

    # [dicomweb]
    # 2908: single clarus_url knob (replaces host/clarus_port, NO fallback).
    clarus_url, tls_cert, tls_key = validate_clarus_url(cfg)
    args.clarus_url = clarus_url
    # The QA webservice endpoint AIRA 57.2.1 calls "specifically configured to
    # provide access to hidden instances". It is a SEPARATE BASE URL, not a
    # query parameter: the bridge must work against any DICOMweb server, and a
    # Clarus-only parameter would make it useless elsewhere.
    args.qa_url = cfg.get("dicomweb", "qa_url", default="").strip().rstrip("/")
    # A relative mTLS path in the config file means "next to that file". Passing
    # it through verbatim made the certificate resolvable only from the working
    # directory the service manager happened to choose, so a restart from a
    # different cwd silently failed to load the key pair.
    _cfg_path = getattr(cfg, "path", None) or getattr(cfg, "config_path", None)
    tls_cert = resolve_config_path(tls_cert, _cfg_path)
    tls_key = resolve_config_path(tls_key, _cfg_path)
    args.tls_client_cert = tls_cert
    args.tls_client_key = tls_key
    args.tls_pair = (tls_cert, tls_key) if tls_cert and tls_key else None
    args.health_check_mode = cfg.get(
        "dicomweb", "health_check_mode", default="probe"
    ).lower()

    # [dicomweb] storage_commitment_presence: does the ORIGIN have a
    # Storage Commitment resource (PS3.18 13.4/13.5)? true => commitment
    # verdicts come from the origin's own honest check; false (default) =>
    # today's local heuristic. Unrelated to [dimse] no_storage_commit.
    args.storage_commitment_presence = cfg.get_bool(
        "dicomweb", "storage_commitment_presence", default=False
    )

    # [dimse]
    args.c_find_max_responses = cfg.get_int(
        "dimse", "c_find_max_responses", default=200
    )
    # c_move_workers: auto-scale - I/O-bound workers (TCP to viewer + HTTP from Clarus).
    # min(16, max(2, cpu_count()//2)): the lower bound keeps at least one
    # reader and one writer, the 16 ceiling keeps the pool bounded even on
    # many-core hosts (the valid config range caps at 16; an unbounded
    # cpu//2 gave 32 workers on 64 cores, outside the validated maximum).
    # 2-2, 4-2, 8-4, 16-8 ... 64-16. Admin can override in config.
    _default_cmove = min(16, max(2, (os.cpu_count() or 2) // 2))
    args.c_move_workers = cfg.get_int("dimse", "c_move_workers", default=_default_cmove)
    args.no_storage_commit = cfg.get_bool("dimse", "no_storage_commit", default=False)
    # peers_file: path to peers.conf (chmod 644, public peer list)
    args.peers_file = cfg.get("peers", "peers_file", default="./peers.conf")
    # [peers] - peer auto-registration
    args.lazyload = cfg.get_bool("peers", "lazyload", default=True)
    args.lazyload_interval = cfg.get_int("peers", "lazyload_interval", default=30)
    # - DIMSE timeouts (inbound - outbound) -
    # Inbound: bridge as SCP (C-STORE from modality, C-FIND from viewer)
    args.inbound_dimse_timeout = cfg.get_int(
        "dimse", "inbound_dimse_timeout", default=60
    )
    # inbound_network_timeout: 0 = disabled (SCP waits for client - ).
    # Viewers keep associations open during C-MOVE (PS3.4 -C.4.2.2).
    # Non-zero: kill idle associations after N seconds.
    args.inbound_network_timeout = cfg.get_int(
        "dimse", "inbound_network_timeout", default=0
    )
    args.inbound_acse_timeout = cfg.get_int("dimse", "inbound_acse_timeout", default=15)
    # Outbound: bridge as SCU (C-MOVE - C-STORE to viewer)
    args.outbound_dimse_timeout = cfg.get_int(
        "dimse", "outbound_dimse_timeout", default=60
    )
    args.outbound_network_timeout = cfg.get_int(
        "dimse", "outbound_network_timeout", default=60
    )
    args.outbound_acse_timeout = cfg.get_int(
        "dimse", "outbound_acse_timeout", default=15
    )
    # Total outbound A-ASSOCIATE attempts (main AND fallback) with
    # immediate retries, default 3, range 1..5 (spec sec.12.2 single knob).
    args.outbound_assoc_attempts = cfg.get_int(
        "dimse", "outbound_assoc_attempts", default=3
    )
    # C-MOVE progress poll timeout (2608): the bridge holds the viewer's
    # association and polls job progress in the DB. If a worker dies mid-job
    # the poll must not run forever - on expiry unfinished jobs are failed
    # and 0xB000 is returned. Range: 30..3600.
    args.move_poll_timeout = cfg.get_int("dimse", "move_poll_timeout", default=600)
    # [dimse] inbound association cap (0509 capacity): pynetdicom default
    # is 8 simultaneous inbound associations per AE. One C-MOVE holds its
    # association for the whole study transfer, and TS-fallback opens a
    # SECOND association, so 8 caps concurrent C-MOVE viewers at ~5
    # (measured 05.09: "Local limit exceeded" at step 6). Each held
    # association costs one pynetdicom thread, idle while the study
    # transfers. Default is DELIBERATELY 8 (pynetdicom parity): on weak
    # boxes the bridge then fails SOFT at the cap instead of going deep
    # into memory pressure (05.09 zram RCA: small hosts die of memory,
    # not of thread count). The bench measured 6-7 viewers clean at 32
    # with c_move_workers=2 - raise deliberately. Admin rule:
    # max_associations >= 2 x concurrent C-MOVE viewers + 4 headroom.
    # Range: 4..256.
    args.max_associations = cfg.get_int("dimse", "max_associations", default=16)

    # [bridge] - DICOM field coercion
    args.fix_empty_patient_id = cfg.get_bool(
        "bridge", "fix_empty_patient_id", default=True
    )
    args.fix_empty_patient_name = cfg.get_bool(
        "bridge", "fix_empty_patient_name", default=True
    )
    args.bridge_id_prefix = cfg.get("bridge", "id_prefix", default="AUTOPAT_")
    args.bridge_name_prefix = cfg.get("bridge", "name_prefix", default="Anonymous^")

    # [logging]
    args.log_level = cfg.get("logging", "log_level", default="INFO").upper()
    args.log_file = cfg.get("logging", "log_file", default=None)

    # [metrics]
    args.http_port = cfg.get_int("metrics", "health_port", default=8105)
    args.http_print_bind = cfg.get("metrics", "http_bind", default="127.0.0.1")

    # [advanced]
    args.sop_registry = cfg.get(
        "advanced", "sop_registry", default="clbridge/sop_classes.yaml"
    )
    args.printers_yaml = cfg.get(
        "advanced", "printers_yaml", default="clbridge/printers.yaml"
    )
    args.sop_index_dir = cfg.get(
        "advanced", "sop_index_dir", default="./clbridge/sop_index"
    )
    args.max_store_mb = cfg.get_int("advanced", "max_store_mb", default=0)
    args.http_timeout = cfg.get_int("advanced", "http_timeout", default=30)
    args.health_check_interval = cfg.get_float(
        "advanced", "health_check_interval_sec", default=5.0
    )
    args.stow_queue_max_mb = cfg.get_int("advanced", "stow_queue_max_mb", default=500)
    args.stow_queue_size = cfg.get_int("advanced", "stow_queue_size", default=20000)
    args.outbox_dir = cfg.get("outbox", "outbox_dir", default="clbridge/outbox")
    args.outbox_cleanup = cfg.get_bool("outbox", "cleanup", default=True)
    args.outbox_max_retries = cfg.get_int("outbox", "max_retries", default=10)
    args.outbox_retry_interval = cfg.get_int("outbox", "retry_interval", default=0)
    # Outbox STOW batching: flush a study-batch when any trigger fires.
    args.outbox_batch_max_sop = cfg.get_int("outbox", "batch_max_sop", default=100)
    args.outbox_batch_max_bytes = cfg.get_int(
        "outbox", "batch_max_bytes", default=96 * 1024 * 1024
    )
    args.outbox_batch_idle_sec = cfg.get_float("outbox", "batch_idle_sec", default=5.0)
    # STORE-FORWARD: when on, a C-STORE against a dead server (>=30s)
    # is PARKED (0x0000; blob already atomically on disk) instead of 0xC000.
    args.outbox_store_forward = cfg.get_bool("outbox", "store_forward", default=False)

    # [forward] - 0409: best-effort DIMSE->DIMSE mirror to a second archive.
    # Absent or enabled=false keeps behaviour byte-identical to pre-0409.
    args.forward_enabled = cfg.get_bool("forward", "enabled", default=False)
    args.forward_dest_ae = cfg.get("forward", "dest_ae", default=None)
    args.forward_dest_host = cfg.get("forward", "dest_host", default=None)
    args.forward_dest_port = cfg.get_int("forward", "dest_port", default=0)
    args.forward_max_queue = cfg.get_int("forward", "forward_max_queue", default=20000)

    # Backpressure: max concurrent C-STORE handlers
    max_cstore = cfg.get_int("advanced", "max_concurrent_cstore", default=None)
    if max_cstore is not None:
        max_cstore = max(1, min(50, max_cstore))
        set_max_concurrent_cstore(max_cstore)
        logging.info("[CONFIG] max_concurrent_cstore = %d", max_cstore)

    return args

# ---------------------------------------------------------------------------
# CONFIG-DISCIPLINE: _validate_config - validate all config values
# ---------------------------------------------------------------------------
def _validate_config(cfg):
    """Validate config values are within allowed ranges. Raises ValueError on violation."""
    errors = []

    def check(cond, msg):
        if not cond:
            errors.append(msg)

    # Server
    port = cfg.get_int("server", "port", default=8104)
    check(1 <= port <= 65535, f"server.port {port} out of range [1..65535]")
    # The QA AE listens on its own socket, and binding a port outside 1..65535
    # raises OverflowError - which is NOT an OSError and so escaped the bind
    # error handling as a traceback. Range-check it here, with `server.port`,
    # and leave 0 (the "QA AE disabled" default) alone.
    eport = cfg.get_int("server", "expose_port", default=0)
    check(
        eport == 0 or 1 <= eport <= 65535,
        f"server.expose_port {eport} out of range [0 or 1..65535]",
    )
    check(
        eport != port,
        f"server.expose_port {eport} must differ from server.port",
    )
    # [server] require_known_peers: a boolean knob. get_bool maps anything it
    # does not recognise to False, which would silently DISARM the inbound
    # allowlist - so a value that is neither a known truthy nor a known falsy
    # spelling is a startup error rather than a quiet downgrade.
    _knob = cfg.get("server", "require_known_peers")
    if _knob is not None and _knob.strip().lower() not in (
        "true",
        "1",
        "yes",
        "on",
        "false",
        "0",
        "no",
        "off",
    ):
        check(
            False,
            f"server.require_known_peers {_knob!r} is not a boolean "
            "(true/false, 1/0, yes/no, on/off)",
        )

    # DICOMweb
    # 2908: clarus_url validated fail-fast (scheme, host, legacy-key removal,
    # mTLS pair symmetry). Raises ValueError with a clear message.
    validate_clarus_url(cfg)

    # Dimse
    cmove = cfg.get_int("dimse", "c_move_workers", default=2)
    check(0 <= cmove <= 16, f"dimse.c_move_workers {cmove} out of range [0..16]")
    cfind = cfg.get_int("dimse", "c_find_max_responses", default=200)
    check(
        0 <= cfind <= 10000,
        f"dimse.c_find_max_responses {cfind} out of range [0..10000]",
    )
    # Inbound DIMSE timeouts (bridge as SCP)
    idt = cfg.get_int("dimse", "inbound_dimse_timeout", default=60)
    check(10 <= idt <= 300, f"dimse.inbound_dimse_timeout {idt} out of range [10..300]")
    int_ = cfg.get_int("dimse", "inbound_network_timeout", default=0)
    check(
        int_ == 0 or (10 <= int_ <= 600),
        f"dimse.inbound_network_timeout {int_} out of range [0 or 10..600]",
    )
    iat = cfg.get_int("dimse", "inbound_acse_timeout", default=15)
    check(5 <= iat <= 60, f"dimse.inbound_acse_timeout {iat} out of range [5..60]")
    # Outbound DIMSE timeouts (bridge as SCU, C-MOVE)
    odt = cfg.get_int("dimse", "outbound_dimse_timeout", default=60)
    check(
        10 <= odt <= 600, f"dimse.outbound_dimse_timeout {odt} out of range [10..600]"
    )
    ont = cfg.get_int("dimse", "outbound_network_timeout", default=60)
    check(
        10 <= ont <= 600, f"dimse.outbound_network_timeout {ont} out of range [10..600]"
    )
    oat = cfg.get_int("dimse", "outbound_acse_timeout", default=15)
    check(5 <= oat <= 60, f"dimse.outbound_acse_timeout {oat} out of range [5..60]")
    # Outbound association attempts (main + fallback), range 1..5.
    oaa = cfg.get_int("dimse", "outbound_assoc_attempts", default=3)
    check(1 <= oaa <= 5, f"dimse.outbound_assoc_attempts {oaa} out of range [1..5]")
    # C-MOVE progress poll timeout (2608): bounds the held reactor's poll of
    # job progress. On expiry unfinished jobs are failed and 0xB000 returned.
    mpt = cfg.get_int("dimse", "move_poll_timeout", default=600)
    check(30 <= mpt <= 3600, f"dimse.move_poll_timeout {mpt} out of range [30..3600]")
    mas = cfg.get_int("dimse", "max_associations", default=16)
    check(4 <= mas <= 256, f"dimse.max_associations {mas} out of range [4..256]")

    # Logging
    level = cfg.get("logging", "log_level", default="INFO").upper()
    check(
        level in ("DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"),
        f"logging.log_level '{level}' must be DEBUG|INFO|WARNING|ERROR|CRITICAL",
    )

    # Metrics
    hp = cfg.get_int("metrics", "health_port", default=8105)
    check(1 <= hp <= 65535, f"metrics.health_port {hp} out of range [1..65535]")

    # Advanced
    ms = cfg.get_int("advanced", "max_store_mb", default=0)
    check(ms >= 0, f"advanced.max_store_mb {ms} must be >= 0")
    ht = cfg.get_int("advanced", "http_timeout", default=30)
    check(1 <= ht <= 300, f"advanced.http_timeout {ht} out of range [1..300]")
    sqm = cfg.get_int("advanced", "stow_queue_max_mb", default=500)
    check(
        10 <= sqm <= 2000, f"advanced.stow_queue_max_mb {sqm} out of range [10..2000]"
    )
    sqs = cfg.get_int("advanced", "stow_queue_size", default=20000)
    check(
        100 <= sqs <= 100000,
        f"advanced.stow_queue_size {sqs} out of range [100..100000]",
    )
    hi = cfg.get_float("advanced", "health_check_interval_sec", default=5.0)
    check(
        1.0 <= hi <= 60.0,
        f"advanced.health_check_interval_sec {hi} out of range [1.0..60.0]",
    )

    # DICOMweb health check mode
    hcm = cfg.get("dicomweb", "health_check_mode", default="probe").lower()
    check(
        hcm in ("probe", "always", "never"),
        f"dicomweb.health_check_mode '{hcm}' must be probe|always|never",
    )

    # Outbox STOW batching
    bs = cfg.get_int("outbox", "batch_max_sop", default=100)
    check(1 <= bs <= 500, f"outbox.batch_max_sop {bs} out of range [1..500]")
    bb = cfg.get_int("outbox", "batch_max_bytes", default=96 * 1024 * 1024)
    check(
        1 <= bb <= 2048 * 1024 * 1024,
        f"outbox.batch_max_bytes {bb} out of range [1..2048MB]",
    )
    bi = cfg.get_float("outbox", "batch_idle_sec", default=5.0)
    check(0.1 <= bi <= 60.0, f"outbox.batch_idle_sec {bi} out of range [0.1..60]")

    # [forward] - 0409: best-effort DIMSE->DIMSE second-archive mirror.
    # When enabled, the destination modality/host/port are REQUIRED and the
    # port/queue-size ranges are enforced. When disabled (or the section
    # absent), nothing is required - an upgrade changes no behaviour.
    if cfg.get_bool("forward", "enabled", default=False):
        if not cfg.get("forward", "dest_ae", default=None):
            errors.append("forward.dest_ae is required when forward.enabled=true")
        if not cfg.get("forward", "dest_host", default=None):
            errors.append("forward.dest_host is required when forward.enabled=true")
        fdp = cfg.get_int("forward", "dest_port", default=0)
        check(1 <= fdp <= 65535, f"forward.dest_port {fdp} out of range [1..65535]")
        fqm = cfg.get_int("forward", "forward_max_queue", default=20000)
        check(
            1 <= fqm <= 100000,
            f"forward.forward_max_queue {fqm} out of range [1..100000]",
        )

    if errors:
        raise ValueError("Configuration errors:\n  " + "\n  ".join(errors))

    logging.info("[CONFIG] All values validated - OK")

# _init_components - initialize managers and registries
# ---------------------------------------------------------------------------
class _LockedDb:
    """The `SharedDb.locked()` context: one connection, one lock."""

    def __init__(self, lock, conn):
        self._lock = lock
        self._conn = conn

    def __enter__(self):
        self._lock.acquire()
        return self._conn

    def __exit__(self, *args):
        self._lock.release()

class _MoveJobsDb:
    """Minimal SharedDb-compatible wrapper.

    One file, one connection, one lock. Two consumers share the shape - the
    C-MOVE state machine (`move_jobs.db`) and the Storage Commitment
    tracker's outstanding batches (`commit_jobs.db`) - and a single
    serialized writer is what keeps both free of SQLite busy-handler
    tuning. They get separate FILES, not separate classes: a tracker write
    that cannot proceed must not be able to block a C-MOVE claim.
    """

    def __init__(self, path):
        import sqlite3 as _sqlite3

        self._conn = _sqlite3.connect(path, check_same_thread=False)
        self._conn.execute("PRAGMA journal_mode=WAL")
        self._lock = threading.Lock()

    def locked(self):
        return _LockedDb(self._lock, self._conn)

    def close(self):
        with self._lock:
            try:
                self._conn.close()
            except Exception:
                pass

def _init_components(args):
    """Initialize SopIndexManager, MoveJobManager, printer_registry, driver_registry.

    Returns (sop_index, move_jobs, printer_registry, driver_registry).
    """
    sop_index = SopIndexManager(index_dir=args.sop_index_dir)
    # move_jobs keeps its own SQLite - it's the right tool for state machine + multi-worker claim.
    move_jobs_db_path = os.path.join(
        os.path.dirname(args.sop_index_dir), "move_jobs.db"
    )
    # SCP peer auto-remove threshold is a fixed constant.
    move_jobs = MoveJobManager(
        shared_db=_MoveJobsDb(move_jobs_db_path),
        max_workers=args.c_move_workers,
        scp_remove_failures=_SCP_FAILURES_BEFORE_REMOVE,
    )
    move_jobs.lazyload_peers_interval = args.lazyload_interval if args.lazyload else 0

    # Bridge: recover in-progress jobs from previous crash
    recovered = move_jobs.recover_in_progress_jobs()
    if recovered > 0:
        logging.warning(
            "[C-MOVE] Recovered %d in-progress job(s) from previous session. "
            "They are now available for retry by the C-MOVE worker.",
            recovered,
        )

    # Bridge: peers are loaded on first C-MOVE, not at startup.
    # Weasis/OHIF/modality will NEVER be running before the bridge.
    # Lazy registration via lookup_scp miss - reload_peers_from_file.

    # Bridge: load printer registry
    printer_registry = _load_printer_registry(args.printers_yaml)

    # Bridge: register C-PRINT drivers - only if drivers/ folder is present
    driver_registry = {}
    if _CPRINT_AVAILABLE:
        driver_registry["generic_dicom"] = GenericDicomPrintDriver()
        logging.info("[C-PRINT] Generic DICOM Print driver loaded")
    else:
        logging.info(
            "[C-PRINT] drivers/ folder not found - print support disabled. "
            "Download drivers/ from https://github.com/clarus-pacs/clarus to enable."
        )

    return sop_index, move_jobs, printer_registry, driver_registry

# ---------------------------------------------------------------------------
# BR-P31: SOP index periodic cleanup worker - prevents unbounded :memory: growth
# ---------------------------------------------------------------------------
def _sop_index_cleanup_worker(sop_index, max_age_hours=24):
    """Background thread: remove SOP index entries older than max_age_hours.

    Without periodic cleanup, the SopIndexManager's :memory: SQLite B-tree grows
    unbounded - 55K objects = ~15-25 MB, millions of objects after weeks of 24/7
    operation = hundreds of MB of RSS - Python GC gen2 pauses - GIL stalls.

    Runs once per hour. Stops when _shutdown_requested is set.
    """

    max_age_seconds = max_age_hours * 3600
    logging.info(
        "[SOP-INDEX] Cleanup worker started (max age: %dh)",
        max_age_hours,
    )

    while not _shutdown_requested.is_set():
        _shutdown_requested.wait(timeout=3600.0)  # Every hour
        if _shutdown_requested.is_set():
            break
        try:
            before = sop_index.count()
            sop_index.cleanup(max_age_seconds)
            after = sop_index.count()
            if before != after:
                logging.info(
                    "[SOP-INDEX] Cleanup: %d entries removed, %d remain",
                    before - after,
                    after,
                )
        except Exception as e:
            logging.error("[SOP-INDEX] Cleanup error: %s", e)

    logging.info("[SOP-INDEX] Cleanup worker stopped")

# ---------------------------------------------------------------------------
# Duplicate instance detection - three layers
# ---------------------------------------------------------------------------

def _check_port_available(port: int, bind_addr: str, name: str) -> None:
    """Layer 1: TCP bind() with the listener's own reuse semantics.

    The check must match how the real listeners bind, or it reports a free
    port as taken: a listener that closes leaves the port in TIME_WAIT for
    about a minute on Linux, and a probe without SO_REUSEADDR fails with
    EADDRINUSE for that whole window - which turns an ordinary restart into a
    manual wait.

    Windows is the exception in the other direction: there SO_REUSEADDR lets a
    second socket bind a port that is ACTIVELY listening, so it would weaken
    exactly the duplicate-instance guard this function exists for.
    SO_EXCLUSIVEADDRUSE is its counterpart - it refuses a port another socket
    holds, including one in TIME_WAIT.
    """
    import socket

    # The family must match the address, not the platform default: `[server]
    # host = ::` is a legitimate IPv6 listener choice, and binding an AF_INET
    # socket to `::` raises, which turned a valid configuration into
    # "[FATAL] ... Refusing to start".
    family = socket.AF_INET6 if ":" in str(bind_addr) else socket.AF_INET
    sock = socket.socket(family, socket.SOCK_STREAM)
    try:
        if sys.platform == "win32":
            exclusive = getattr(socket, "SO_EXCLUSIVEADDRUSE", None)
            if exclusive is not None:
                sock.setsockopt(socket.SOL_SOCKET, exclusive, 1)
        else:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        sock.bind((bind_addr, port))
    except OSError as e:
        logging.error(
            "[FATAL] bind() to %s:%d (%s) failed: %s - "
            "another process may be using this port. Refusing to start.",
            bind_addr,
            port,
            name,
            e,
        )
        sys.exit(1)
    finally:
        sock.close()

def _qa_port_will_bind(args):
    """True when the Expose Rejected Instances listener will actually bind.

    The QA AE is constructed only under `args.expose_port AND args.qa_url`;
    either half alone is dead config and is reported as a warning instead of
    started. The startup port probe asks this so it can never refuse to start
    on a port this configuration never binds.
    """
    return bool(args.expose_port) and bool(args.qa_url)

def _check_dimse_unique(host: str, port: int, my_ae_title: str) -> None:
    """Layer 2: C-ECHO probe against the DICOMweb server via pynetdicom.

    Probes the Clarus Bridge AE over DIMSE; a live association proves
    the configured server address and AE settings are reachable.
    - AE Title is echoed back by the server (Clarus Bridge).
    - AE Title mismatch is reported without aborting the DICOMweb path.
    """
    from pynetdicom import AE as ProbeAE
    from pynetdicom.sop_class import Verification

    # Resolve 0.0.0.0 / :: to loopback - can't connect to bind-any address.
    probe_host = host
    if host in ("0.0.0.0", "::"):
        probe_host = "127.0.0.1"

    probe_ae_title = (f"{my_ae_title}_PROBE")[:16]  # DICOM AE: max 16 chars
    probe_ae = ProbeAE(ae_title=probe_ae_title)
    probe_ae.add_requested_context(Verification)
    probe_ae.network_timeout = 2
    probe_ae.acse_timeout = 2

    # Suppress pynetdicom internal logging during probe - connection
    # refusal is expected (means we're the only process on this port).
    _probe_logger = logging.getLogger("pynetdicom")
    _probe_prev_level = _probe_logger.level
    _probe_logger.setLevel(logging.CRITICAL + 1)

    assoc = None
    try:
        # Call as the bridge's own AE title - with require_called_aet=True a
        # running bridge instance rejects the generic probe title.
        assoc = probe_ae.associate(probe_host, port, ae_title=my_ae_title)
        if assoc.is_established:
            remote_ae = (
                assoc.acceptor.ae_title
                if hasattr(assoc, "acceptor") and assoc.acceptor
                else "unknown"
            )
            if remote_ae == my_ae_title:
                logging.error(
                    "[FATAL] C-ECHO: another Clarus Bridge (AE=%s) already "
                    "listening on %s:%d. Refusing to start.",
                    remote_ae,
                    host,
                    port,
                )
            else:
                logging.error(
                    "[FATAL] C-ECHO: DIMSE port %s:%d already in use "
                    "by AE=%s. Refusing to start.",
                    host,
                    port,
                    remote_ae,
                )
            sys.exit(1)
    except (ConnectionRefusedError, ConnectionResetError, TimeoutError, OSError) as e:
        # These mean "nothing is listening on that port", which is the clean
        # answer this probe exists to produce. Any other exception is a FAILED
        # probe, and reporting it as clean is the optimistic default: the check
        # would pass without ever having looked.
        logging.debug("[STARTUP] C-ECHO probe on %s:%d: %s", host, port, e)
    except Exception as e:
        logging.warning(
            "[STARTUP] C-ECHO probe on %s:%d could not complete (%s: %s) - "
            "duplicate-instance state is UNKNOWN, continuing",
            host,
            port,
            type(e).__name__,
            e,
        )
    finally:
        _probe_logger.setLevel(_probe_prev_level)
        try:
            if assoc is not None and assoc.is_established:
                assoc.release()
        except Exception:
            pass

def _default_pid_path(port: int) -> str:
    """Platform default path for the bridge PID file.

    Linux: `/var/run/clbridge-{port}.pid`. A PID file is a system-level
    thing on Unix; the FHS location is what an operator's init scripts
    expect. It is NOT guaranteed writable (that needs root), which is
    exactly why `_write_pid_file` degrades instead of dying - see below.

    Elsewhere (Windows, macOS): next to the executable/script, which is
    the historical location and always writable by the user who can start
    the process in the first place.
    """
    if sys.platform.startswith("linux"):
        return os.path.join("/var/run", f"clbridge-{port}.pid")
    script_dir = os.path.dirname(
        os.path.abspath(sys.executable if getattr(sys, "frozen", False) else __file__)
    )
    return os.path.join(script_dir, f"clbridge-{port}.pid")

def _fallback_pid_path(port: int) -> str:
    """Fallback PID path when the default is not writable.

    Next to the script/executable. This is the pre-04.09 behaviour and it
    worked everywhere except when the install directory itself was read-only.
    """
    script_dir = os.path.dirname(
        os.path.abspath(sys.executable if getattr(sys, "frozen", False) else __file__)
    )
    return os.path.join(script_dir, f"clbridge-{port}.pid")

def _pid_is_alive(pid: int) -> bool:
    """True when `pid` names a running process.

    `os.kill(pid, 0)` is the POSIX idiom, but on Windows it does NOT probe:
    CPython implements it with TerminateProcess, so signal 0 KILLS the process
    it was asked to check. The bridge's own PID file then took down whatever
    held that pid - which on a recycled pid is an unrelated program.
    """
    if pid <= 0:
        return False
    if os.name == "nt":
        # Windows: ask for the process handle and its exit code instead.
        import ctypes
        from ctypes import wintypes

        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        STILL_ACTIVE = 259
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        handle = kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if not handle:
            err = ctypes.get_last_error()
            # 5 = ACCESS_DENIED: the process exists but is not ours to inspect.
            return err == 5
        try:
            code = wintypes.DWORD()
            if not kernel32.GetExitCodeProcess(handle, ctypes.byref(code)):
                return True  # cannot tell: assume alive and refuse to steal
            return code.value == STILL_ACTIVE
        finally:
            kernel32.CloseHandle(handle)
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        # The process exists but belongs to another user.
        return True

def _write_pid_file(path: str) -> bool:
    """Layer 3: atomic PID file via O_EXCL. Returns True when the file is OURS.

    Order: platform default (/var/run on Linux, next to the script
    elsewhere); if not writable, fall back next to the script; if
    neither is writable, WARN and run WITHOUT a PID file. FATAL only
    when a live foreign pid occupies the path.

    The FATAL path exits via os._exit(1) because _write_pid_file is
    called from _fatal_pid_error.

    A False return is the only signal that the create failed for a reason the
    caller can work around (a permission or space error, NOT a live foreign
    pid). The old signature returned None on every path, so the caller could
    not tell "written" from "gave up" and reported a path it did not own to
    the shutdown path, which then deleted a file it had never created.
    """
    pid = str(os.getpid())
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
    except FileExistsError:
        # Reading the stale file is the next thing that can fail, and it is
        # NOT the same class as the create above: permission-denied or a file
        # deleted between the two calls raised straight out of process start.
        try:
            with open(path) as f:
                old_pid = f.read().strip()
        except OSError as e:
            logging.warning(
                "[WARN] Existing PID file %s cannot be read: %s. Removing it "
                "and continuing.",
                path,
                e,
            )
            try:
                os.remove(path)
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
            except OSError as e2:
                logging.warning(
                    "[WARN] Cannot rewrite PID file %s: %s. Continuing without it.",
                    path,
                    e2,
                )
                return False
        else:
            try:
                old_pid_int = int(old_pid)
            except ValueError:
                old_pid_int = None
            # Our OWN pid is not a competing instance. After a crash / SIGKILL the
            # file survives, and in a container with a stable filesystem across
            # `docker restart` the new process gets the same pid (1 or 7 is common
            # when /var/run is unwritable and the fallback path is used) - the
            # liveness probe then answered "alive" for the current process and the
            # bridge refused to start on every restart. Layers 1 and 2 already
            # detect a live second instance, so this check only has to reject a
            # FOREIGN live pid.
            alive = (
                old_pid_int is not None
                and old_pid_int != os.getpid()
                and _pid_is_alive(old_pid_int)
            )
            if alive:
                logging.error(
                    "[FATAL] PID file %s exists and pid=%s is ALIVE. "
                    "Another instance is running. Remove %s manually if stale.",
                    path,
                    old_pid,
                    path,
                )
                # os._exit: immediate process termination, works on Win+*nix.
                # sys.exit only raises SystemExit - non-daemon threads prevent exit.
                os._exit(1)
            else:
                logging.warning(
                    "[WARN] Stale PID file %s (pid=%s is dead). Overwriting.",
                    path,
                    old_pid,
                )
                try:
                    os.remove(path)
                    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
                except OSError as e:
                    logging.warning(
                        "[WARN] Cannot rewrite stale PID file %s: %s. Continuing without it.",
                        path,
                        e,
                    )
                    return False
    except OSError as e:
        # PermissionError is an OSError. NOT fatal: the service must start.
        logging.warning(
            "[WARN] Cannot create PID file %s: %s. Continuing without it.",
            path,
            e,
        )
        return False
    # The write and the close can fail too, and a buffered write reports its
    # error from `close()` inside the `with` block, not from `os.open`. An
    # exception escaping here aborted startup instead of falling back to the
    # next candidate location. The record this call created is removed on the
    # way out so a later instance does not read a truncated pid as stale-but-
    # live; `True` is returned only once the full record is on disk.
    #
    # The file object is gone BEFORE the unlink: on Windows an open handle
    # makes `os.remove` fail with a sharing violation, which is how the first
    # version of this guard left the very record it meant to delete.
    try:
        with os.fdopen(fd, "w") as f:
            f.write(pid)
            f.flush()
            os.fsync(f.fileno())
    except (OSError, ValueError) as e:
        logging.warning(
            "[WARN] Cannot write PID file %s: %s. Continuing without it.",
            path,
            e,
        )
        try:
            os.remove(path)
        except OSError:
            pass
        return False
    logging.info("[PID] %s written (pid=%s)", path, pid)
    return True

def _acquire_pid_file(port: int) -> str:
    """Resolve, write and register the PID file. Returns the path in use.

    There is deliberately NO configuration for this: no config key, no CLI
    flag, no environment variable. The PID file is an internal artefact and
    the operator never needs to know about it.

    Order (owner directive, incident 04.09):
      1. platform default (`/var/run/...` on Linux, next to the script
         elsewhere);
      2. if that is not writable - fall back next to the script;
      3. if neither is writable - WARN and run WITHOUT a PID file.

    A live foreign pid is fatal, because two instances must not silently
    coexist.
    """
    candidates = []
    default = _default_pid_path(port)
    fallback = _fallback_pid_path(port)
    candidates.append(default)
    if fallback != default:
        candidates.append(fallback)

    for candidate in candidates:
        directory = os.path.dirname(candidate) or "."
        if not os.path.isdir(directory):
            logging.warning(
                "[WARN] PID directory %s does not exist; skipping %s.",
                directory,
                candidate,
            )
            continue
        if not os.access(directory, os.W_OK):
            logging.warning(
                "[WARN] PID directory %s is not writable; skipping %s.",
                directory,
                candidate,
            )
            continue
        # A live foreign pid inside _write_pid_file exits the process; a stale
        # one is overwritten and True is returned. A False means THIS candidate
        # could not be taken, so the next one is tried instead of reporting a
        # path the process does not own.
        if _write_pid_file(candidate):
            return candidate
        logging.warning(
            "[WARN] PID file %s could not be acquired; trying the next location.",
            candidate,
        )

    logging.warning(
        "[WARN] No writable PID file location found (tried: %s). "
        "Continuing without a PID file.",
        ", ".join(candidates),
    )
    return ""

# ---------------------------------------------------------------------------
# Startup ownership lock - one instance per DIMSE port, OS-backed
# ---------------------------------------------------------------------------
# The PID file is a RECORD, not a lock: it is created empty and filled two
# lines later, so a second process that reads it in that window sees an empty
# file, calls it stale, and replaces it. Both then reach
# `_init_components()` - and its `recover_in_progress_jobs()` rewrites the
# shared database - before either listener binds. The port probes do not close
# that window either: they are separate checks, and both processes can pass
# them.
#
# The lock below is the OS's own answer to "who owns this name", held for the
# life of the process and released by the kernel if the process dies. It is
# taken BEFORE recovery and released only at exit, so no second instance can
# reach the database while the first is starting up.
_startup_lock_handle = None

def _acquire_startup_lock(port: int) -> bool:
    """Take the exclusive per-port startup lock. False when another instance holds it.

    POSIX: `flock(LOCK_EX | LOCK_NB)` on a lock file beside the PID file.
    Windows: `msvcrt.locking` on the first byte, which is exclusive and
    non-blocking.

    Non-blocking on purpose: a second instance must FAIL FAST with a clear
    message rather than queue behind the first and start when it stops.

    The handle is kept in a module global so it stays open for the process
    lifetime; the kernel drops it on any exit, including SIGKILL, which is what
    makes a crash self-healing where a plain PID file is not.
    """
    global _startup_lock_handle
    candidates = []
    default = _default_pid_path(port)
    fallback = _fallback_pid_path(port)
    candidates.append(default + ".lock")
    if fallback != default:
        candidates.append(fallback + ".lock")

    for lock_path in candidates:
        directory = os.path.dirname(lock_path) or "."
        if not os.path.isdir(directory) or not os.access(directory, os.W_OK):
            continue
        try:
            handle = open(lock_path, "a+b")
        except OSError as e:
            logging.debug("[STARTUP-LOCK] cannot open %s: %s", lock_path, e)
            continue
        try:
            if os.name == "nt":
                import msvcrt

                handle.seek(0)
                msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl

                fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            handle.close()
            logging.error(
                "[FATAL] Another clbridge instance owns %s - refusing to "
                "start a second one on this DIMSE port.",
                lock_path,
            )
            return False
        except Exception as e:  # pragma: no cover - platform oddity
            handle.close()
            logging.debug("[STARTUP-LOCK] %s unusable: %s", lock_path, e)
            continue
        _startup_lock_handle = handle
        logging.info("[STARTUP-LOCK] %s acquired", lock_path)
        return True

    # No writable location: the PID-file policy already WARNs and runs without
    # it, and refusing to start would break deployments that run from a
    # read-only image. The lock is the stronger guard; say clearly that it is
    # not in use.
    logging.warning(
        "[STARTUP-LOCK] no writable lock location - starting WITHOUT the "
        "exclusive startup guard"
    )
    return True

# ---------------------------------------------------------------------------
# Persistent-state lock - one owner per STATE DIRECTORY, whatever the ports
# ---------------------------------------------------------------------------
# The startup lock above is keyed by DIMSE port, which answers "who serves this
# port". It does NOT answer "who owns this database": two instances can take
# different ports - and therefore different locks - while pointing at the same
# `sop_index_dir`, and `_init_components` then calls
# `recover_in_progress_jobs()` on the SAME move_jobs.db. The second instance
# resets the first's in-progress jobs to pending, both claim them, and the same
# instances are delivered twice.
#
# This lock is keyed by the resolved state directory and is held only across
# startup, which is the window where recovery rewrites shared state. It is
# deliberately separate from the port lock: running two bridges with distinct
# ports AND distinct state stays supported.
_state_lock_handle = None

def _acquire_state_lock(state_dir: str) -> bool:
    """Take a non-blocking exclusive lock on `state_dir`. False when held.

    Held for the process lifetime, like the port lock: the OS drops it on any
    exit, so a crash cannot leave the state directory permanently locked.
    """
    global _state_lock_handle
    lock_path = os.path.join(state_dir, ".clbridge-state.lock")
    try:
        handle = open(lock_path, "a+b")
    except OSError as e:
        logging.warning(
            "[STATE-LOCK] cannot open %s: %s - starting WITHOUT the state "
            "lock; two instances sharing this directory could reset each "
            "other's in-progress jobs",
            lock_path,
            e,
        )
        return True
    try:
        if os.name == "nt":
            import msvcrt

            handle.seek(0)
            msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl

            fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        handle.close()
        logging.error(
            "[FATAL] Another clbridge instance owns the state directory %s - "
            "refusing to start a second one against the same move_jobs.db.",
            state_dir,
        )
        return False
    _state_lock_handle = handle
    logging.info("[STATE-LOCK] %s acquired", lock_path)
    return True

# ---------------------------------------------------------------------------
# _start_background_services - HTTP server, C-MOVE workers, cleanup
# ---------------------------------------------------------------------------
def _start_background_services(
    args, driver_registry, printer_registry, move_jobs, sop_index, sop_registry
):
    """Start HTTP server, C-MOVE workers, cleanup thread.

    Returns (http_server, http_thread, cmove_thread, cleanup_thread, sop_cleanup_thread,
             outbox, outbox_workers, health_checker, commit_tracker, commit_thread,
             forward_outbox, forward_worker_thread).
    """
    # Outbox Queue - filesystem-backed reliable DICOM persistence + delivery
    max_queue = args.stow_queue_size
    outbox = OutboxQueue(
        outbox_dir=args.outbox_dir,
        max_queue=max_queue,
        max_retries=args.outbox_max_retries,
        cleanup=args.outbox_cleanup,
        retry_interval=args.outbox_retry_interval,
        # R7: the documented RAM budget becomes a real limit. Backpressure
        # takes the worse of the slot ratio and this byte ratio, so a queue
        # that is 2% full by count but 400% over its memory budget still
        # refuses.
        max_queue_bytes=int(args.stow_queue_max_mb) * 1024 * 1024,
    )
    recovered, undelivered = outbox.recover_stuck(force=True)
    outbox_pending.set(outbox.pending_count())
    if recovered > 0:
        outbox_recovery_total.inc(recovered)
    # Update disk bytes metric
    try:
        total = sum(
            os.path.getsize(os.path.join(root, f))
            for root, _, files in os.walk(args.outbox_dir)
            for f in files
        )
        outbox_disk_bytes.set(total)
    except OSError:
        pass

    # Forwarder: SECOND OutboxQueue instance pointed at its own
    # directory (<outbox_dir>/forward). Only constructed when forward is
    # enabled - an upgrade without the config block creates NO new dirs and
    # changes NO metric behaviour. Feeding it forward_pending (not
    # outbox_pending) keeps the two queues' gauges isolated. The drain worker
    # that consumes this queue is the drain worker; reception-only wiring lives here.
    forward_outbox = None
    if getattr(args, "forward_enabled", False):
        forward_dir = os.path.join(args.outbox_dir, "forward")
        forward_outbox = OutboxQueue(
            outbox_dir=forward_dir,
            max_queue=args.forward_max_queue,
            max_retries=10,  # 0409: forward-queue retry budget (like outbox)
            cleanup=args.outbox_cleanup,
            pending_gauge=forward_pending,
            undelivered_total=forward_undelivered_total,
        )
        # Same startup sweep as the primary queue: a fresh in_progress/ item
        # from a crashed drain worker must be visible immediately.
        forward_outbox.recover_stuck(force=True)
        logging.info(
            "[FORWARD] secondary queue enabled -> %s (max_queue=%d, max_retries=10)",
            forward_dir,
            args.forward_max_queue,
        )

    # HealthChecker - background poller + pre-flight gate
    hc_mode = getattr(args, "health_check_mode", "probe")
    hc_interval = getattr(args, "health_check_interval", 5.0)
    health_checker = HealthChecker(
        clarus_url=args.clarus_url,
        mode=hc_mode,
        interval=hc_interval,
        http_timeout=args.http_timeout,
        tls=args.tls_pair,
    )
    health_checker.start()

    # Bridge: start HTTP server in daemon thread
    bridge_up.set(1)  # mark bridge as running

    # P2.10: ThreadingHTTPServer - each request handled in its own thread.
    # Single-threaded HTTPServer serialized /health behind heavy /metrics
    # (Prometheus rendering), causing >5s response times under load.
    HandlerCls = make_bridge_handler(
        driver_registry,
        printer_registry,
        args.ae_title,
        outbox=outbox,
        health_checker=health_checker,
        move_jobs=move_jobs,
    )
    # HTTPServer defaults to AF_INET, so an IPv6 http_bind (e.g. "::1" or
    # "::") dies at bind time with a name-resolution error and takes the whole
    # bridge down - a site that only has IPv6 management connectivity gets no
    # health/metrics endpoint at all. Pick the family from the literal address;
    # DualStack keeps "::" reachable over IPv4 too.
    bind_host = args.http_print_bind
    family = socket.AF_INET
    if ":" in bind_host:
        family = socket.AF_INET6
    elif bind_host:
        try:
            family = socket.getaddrinfo(
                bind_host, args.http_port, 0, socket.SOCK_STREAM
            )[0][0]
        except OSError:
            family = socket.AF_INET

    class _BridgeHTTPServer(ThreadingHTTPServer):
        address_family = family
        daemon_threads = True

    http_server = _BridgeHTTPServer(
        (bind_host, args.http_port),
        HandlerCls,
    )
    http_thread = threading.Thread(
        target=http_server.serve_forever,
        name="http-bridge-server",
        daemon=False,
    )
    http_thread.start()
    logging.info(
        "[HTTP] Bridge server listening on %s:%d (/print, /metrics, /health)",
        args.http_print_bind,
        args.http_port,
    )

    # Start single outbox background worker (KISS: one worker, N SOPs per STOW-RS)
    outbox_workers = _start_outbox_workers(
        outbox,
        args.clarus_url,
        args.http_timeout,
        sop_index,
        move_jobs,
        batch_max_sop=args.outbox_batch_max_sop,
        batch_max_bytes=args.outbox_batch_max_bytes,
        batch_idle_sec=args.outbox_batch_idle_sec,
        health_checker=health_checker,
        tls=args.tls_pair,
        bridge_ae_title=args.ae_title,
    )
    logging.info(
        "[OUTBOX-WORKER] Started 1 worker, outbox: %s "
        "(batch: sop<=%d bytes<=%d idle<=%.0fs)",
        args.outbox_dir,
        args.outbox_batch_max_sop,
        args.outbox_batch_max_bytes,
        args.outbox_batch_idle_sec,
    )

    # Bridge: start C-MOVE background worker pool
    cmove_thread = threading.Thread(
        target=_cmove_worker,
        args=(
            move_jobs,
            args.clarus_url,
            args.http_timeout,
            args.ae_title,
        ),
        kwargs={
            "num_workers": args.c_move_workers,
            "sop_registry": sop_registry,
            "storage_commit_after_move": not args.no_storage_commit,
            "sop_index": sop_index,
            "peers_file": args.peers_file,
            "outbound_network_timeout": args.outbound_network_timeout,
            "outbound_dimse_timeout": args.outbound_dimse_timeout,
            "outbound_acse_timeout": args.outbound_acse_timeout,
            "outbound_assoc_attempts": args.outbound_assoc_attempts,
            "tls": args.tls_pair,
            "qa_url": args.qa_url,
        },
        name="cmove-worker-pool",
        daemon=False,
    )
    cmove_thread.start()
    logging.info(
        "[C-MOVE] Background worker pool started (%d workers)", args.c_move_workers
    )

    # Bridge: start C-MOVE cleanup worker
    #
    # R10: it also expires abandoned Storage Commitment batches, so the
    # retention sweep rides this existing hourly cycle rather than adding a
    # thread. The tracker is built later in this function, so the worker
    # receives a holder it reads each cycle instead of the object itself.
    cleanup_thread_tracker = [None]
    cleanup_thread = threading.Thread(
        target=_cmove_cleanup_worker,
        args=(move_jobs, 24),
        kwargs={"commit_tracker_holder": cleanup_thread_tracker},
        name="cmove-cleanup",
        daemon=False,
    )
    cleanup_thread.start()

    # BR-P31: start SOP index cleanup worker - prevents unbounded :memory: growth
    sop_cleanup_thread = threading.Thread(
        target=_sop_index_cleanup_worker,
        args=(sop_index, 24),
        name="sop-index-cleanup",
        daemon=False,
    )
    sop_cleanup_thread.start()

    # Async Storage Commitment report loop (N-EVENT-REPORT). Fire-and-
    # forget: N-ACTION registers a batch; this worker resolves it and sends
    # ONE report back.
    #
    # Two modes (2409), selected once here by storage_commitment_presence:
    #   false (default) - the readiness gate is the local probe: all SOPs
    #     confirmed via WADO-RS, or the 300s deadline, then the local
    #     heuristic's verdict (unconfirmed -> 0x0110).
    #   true - the readiness gate is the bridge's OWN outbox delivery state
    #     (a C-STORE returns before its STOW completes, so an immediate
    #     origin-side ask would report false "not stored" verdicts), then
    #     ONE POST to the origin's Commit resource and its verdict verbatim.
    def _verify_cb(sop_class, sop_uid):
        return (
            _sop_confirm(
                sop_uid,
                sop_index,
                args.clarus_url,
                args.http_timeout,
                tls=args.tls_pair,
            )
            == 0
        )

    stc_presence = bool(getattr(args, "storage_commitment_presence", False))

    class _CommitStillPending(Exception):
        """The origin accepted the commitment request and has not decided yet.

        Raised from `_resolve_stc` so the tracker treats this tick as "nothing
        delivered": the batch stays in its working set and is asked again,
        rather than reporting a verdict the origin never produced (PS3.18
        13.4.3).
        """

    def _resolve_stc(job):
        """Ask the origin ONCE and report its verdict verbatim (true-mode).

        Only wired in true-mode; false-mode leaves `resolve` unset so the
        tracker runs its own heuristic, byte-for-byte as before.

        Raises `_CommitStillPending` when the origin answers 202: PS3.18 13.4.3
        says that means "accepted, not yet decided", so there is no verdict to
        report and the batch must stay in the tracker. `_resolve` treats a
        raised exception as "not delivered", which is exactly the desired
        outcome here - the next tick asks again - whereas reporting would have
        invented an answer the origin never gave.
        """
        committed, failed, sentinel = _stc_commit_request(
            args.clarus_url,
            job.tx_uid,
            job.sops,
            http_timeout=args.http_timeout,
            tls=args.tls_pair,
        )
        if sentinel == STC_PENDING:
            raise _CommitStillPending(job.tx_uid)
        if sentinel == STC_NO_RESOURCE:
            # The WARN already named the misconfiguration; there is
            # deliberately no fallback to the local path.
            logging.warning(
                "[N-EVENT] tx=%s: origin has no Commit resource - reporting "
                "every SOP failed (0x0110)",
                job.tx_uid,
            )
        event_type = 1 if not failed else 2
        send_n_event_report(
            job.host,
            job.port,
            job.calling_ae,
            job.tx_uid,
            event_type,
            committed,
            failed,
            args.ae_title,
        )

    # Storage Commitment batches are a promise to the modality (PS3.4
    # J.3.3.1: the N-EVENT-REPORT IS the result), so an outstanding batch has
    # to survive a restart. It gets its OWN database file rather than a table
    # alongside move_jobs: a tracker write must not contend with a C-MOVE
    # claim, and the two have nothing to join on.
    commit_db_path = os.path.join(os.path.dirname(args.sop_index_dir), "commit_jobs.db")

    if stc_presence:
        # Origin-owned commitment: the readiness signal is the bridge's OWN
        # delivery state, not a probe (a C-STORE returns before its STOW
        # completes, so an immediate origin-side ask would report false "not
        # stored" verdicts). `delivered` is the outbox's read-side query.
        commit_tracker = CommitTracker(
            verify=lambda sop_class, sop_uid: outbox.delivered(sop_uid),
            report=functools.partial(
                send_n_event_report, bridge_ae_title=args.ae_title
            ),
            resolve=_resolve_stc,
            deadline_sec=300.0,
            db=_MoveJobsDb(commit_db_path),
        )
    else:
        # Unchanged local heuristic: the tracker's own _resolve owns it.
        commit_tracker = CommitTracker(
            verify=_verify_cb,
            report=functools.partial(
                send_n_event_report, bridge_ae_title=args.ae_title
            ),
            deadline_sec=300.0,
            db=_MoveJobsDb(commit_db_path),
        )
    commit_thread = threading.Thread(
        target=commit_tracker.run,
        name="commit-tracker",
        daemon=False,
    )
    commit_thread.start()
    # R10: hand the tracker to the cleanup worker started earlier, which
    # expires abandoned batches once an hour.
    try:
        cleanup_thread_tracker[0] = commit_tracker
    except NameError:
        pass
    # Expose the tracker to the /metrics scrape (pending-batch gauges). The
    # HTTP server is already serving, so the ref is attached to its handler
    # class once the tracker exists.
    try:
        HandlerCls._commit_tracker_ref = commit_tracker
    except Exception:
        pass
    logging.info(
        "Storage Commitment: %s",
        "origin STC" if stc_presence else "local heuristic",
    )

    # Forwarder: separate DIMSE drain thread for the second,
    # NON-authoritative archive. Started ONLY when the forward queue exists
    # (enabled). It shares NO state with the primary STOW drain thread and
    # runs on its own queue, so a dead second server can only pause its own
    # batch - never the primary reception/delivery (isolation).
    forward_worker_thread = None
    if forward_outbox is not None:
        forward_worker_thread = threading.Thread(
            target=_forward_worker,
            args=(
                forward_outbox,
                args.forward_dest_ae,
                args.ae_title,
                args.forward_dest_host,
                args.forward_dest_port,
            ),
            kwargs={
                "network_timeout": args.outbound_network_timeout,
                "dimse_timeout": args.outbound_dimse_timeout,
                "acse_timeout": args.outbound_acse_timeout,
            },
            name="forward-worker",
            daemon=False,
        )
        forward_worker_thread.start()
        logging.info(
            "[FORWARD] drain worker started: %s@%s:%d (best-effort DIMSE mirror)",
            args.forward_dest_ae,
            args.forward_dest_host,
            args.forward_dest_port,
        )

    return (
        http_server,
        http_thread,
        cmove_thread,
        cleanup_thread,
        sop_cleanup_thread,
        outbox,
        outbox_workers,
        health_checker,
        commit_tracker,
        commit_thread,
        forward_outbox,
        forward_worker_thread,
    )

# ---------------------------------------------------------------------------
# Outbox Queue: background STOW workers (replaces sync STOW-RS in handler)
# ---------------------------------------------------------------------------

def _outbox_worker(
    outbox,
    clarus_url,
    http_timeout,
    sop_index,
    move_jobs,
    batch_max_sop=100,
    batch_max_bytes=96 * 1024 * 1024,
    batch_idle_sec=5.0,
    health_checker=None,
    tls=None,
    bridge_ae_title="CLBRIDGE",
):
    """Background worker: drains outbox, batches same-study SOPs into one STOW-RS.

    Fieldtest: 1 SLICE = 1 POST -> N SLICES = 1 POST (1063 -> ~20).
    Flush triggers, whoever fires first:
      - count  >= batch_max_sop
      - bytes  >= batch_max_bytes (buffer cap; on-disk blob size as proxy)
      - idle   >= batch_idle_sec  (study tail, non-empty buffer)
      - study boundary: SWITCH to another study flushes the tail IMMEDIATELY.
    Studies never mix in one batch. Single worker drains sequentially; each
    flush is independent (no cross-study waiting). P8 raw pass-through kept
    per part (byte-identical content for CAS dedup).

    Stage 5 (store_forward): while the server is down (health_checker reports
    unhealthy), the worker PAUSES instead of burning STOW retries
    (MAX_RETRIES=10 -> undelivered -> manual intervention). No HTTP on this
    hot path - it only reads the health checker's cached event.

    nginx-way: one worker drains STOW. Outbox decouples C-STORE from
    delivery: C-STORE ACKs once the blob is on disk, worker forwards later.
    """
    import os

    import httpx

    # P30: persistent HTTP client -- Keep-Alive. One handshake for the whole
    # queue drain instead of one per instance (x2 throughput).
    # 2908: cert=tls enables mTLS when configured; verify is ALWAYS on
    # (httpx default) - there is no knob to disable it.
    _http = httpx.Client(
        timeout=httpx.Timeout(http_timeout + 10),
        limits=httpx.Limits(max_keepalive_connections=1, max_connections=1),
        cert=tls,
    )

    _last_stuck_check = time.time()  # periodic reaper timer
    # P8: watchdog -- last successful delivery for liveness monitoring
    _last_progress = time.time()
    _progress_lock = threading.Lock()
    # Log "paused"/"resumed" once per transition, not every 5s poll.
    _was_paused = False
    # 2908: 507 backpressure state (Retry-After pause, files stay pending).
    _pause_until = 0.0
    _was_507_paused = False

    # Delivery summary ("432/432 delivered", not 432 "201 Created").
    _delivered_total = 0
    _delivered_failed = 0
    _last_summary_log = time.time()  # throttle progress logs to every 30s
    _queue_was_empty = True  # detect queue-empty -> summary transition
    # Per-study tracking: {study_uid -> {delivered, failed, patient, modalities}}
    _study_stats: dict[str, dict] = {}
    _current_study: str | None = None

    # Batching state: current same-study buffer + its byte total.
    _batch: list = []  # (sop_uid, ds, blob_path, raw_bytes, dataset_modified)
    _batch_study: str | None = None
    _batch_bytes = 0
    # R3: monotonic instant the FIRST item of the open batch was buffered.
    # The idle flush only fires on a dequeue gap, so a source trickling one
    # instance every `batch_idle_sec - 1` s keeps the batch open indefinitely;
    # past STUCK_ITEM_TIMEOUT the reaper returns the oldest claimed item to
    # pending, and the next dequeue sends it a SECOND time (delivered twice,
    # mark_delivered twice, backpressure and metrics wrong).
    _batch_started_at = 0.0

    # R3: hard cap on how long ONE batch may stay open. It must stay well
    # below the stuck-item timeout (300 s), because past that instant the
    # reaper hands the oldest CLAIMED item back to pending while this batch
    # still owns it - and the next dequeue sends it a second time. A quarter
    # of the reaper window leaves three intervals of slack for one flush to
    # finish before the item could be reclaimed, and 60 s bounds it anyway.
    _batch_max_age_sec = min(60.0, STUCK_ITEM_TIMEOUT / 4)

    def _log_study_start(sop_uid, ds, study_uid):
        """First SOP of a study: log and seed per-study stats."""
        if study_uid not in _study_stats:
            try:
                _patient_id = mask_patient_id(str(getattr(ds, "PatientID", "?")))
            except Exception:
                _patient_id = "?"
            try:
                _modality = str(getattr(ds, "Modality", "??"))
            except Exception:
                _modality = "??"
            _study_stats[study_uid] = {
                "delivered": 0,
                "failed": 0,
                "patient": _patient_id,
                "modalities": {_modality} if _modality and _modality != "??" else set(),
            }
        else:
            # Track all modalities seen (studies often mix DX + SR etc.)
            try:
                _modality = str(getattr(ds, "Modality", "??"))
                if _modality and _modality != "??":
                    _study_stats[study_uid].setdefault("modalities", set()).add(
                        _modality
                    )
            except Exception:
                pass

    def _deliver_batch():
        """Send the accumulated same-study batch, mark per-SOP outcomes."""
        nonlocal _batch, _batch_study, _batch_bytes
        nonlocal _delivered_total, _delivered_failed, _last_summary_log
        nonlocal _queue_was_empty, _current_study
        nonlocal _pause_until
        nonlocal _last_progress
        nonlocal _batch_started_at
        if not _batch:
            return
        batch_study = _batch_study
        mods = (
            ", ".join(
                sorted(_study_stats.get(batch_study, {}).get("modalities", set()))
            )
            or "??"
        )
        logging.info(
            "[OUTBOX] Flushing batch: study=%s %d SOP(s) %d bytes %s",
            (batch_study or "")[:50],
            len(_batch),
            _batch_bytes,
            mods,
        )
        payloads = [
            (uid, ds, (None if modified else raw))
            for uid, ds, _bp, raw, modified in _batch  # P8: raw stays as-is unless modified
        ]
        try:
            results, backoff = stow_batch_instances(
                payloads,
                clarus_url,
                http_timeout=http_timeout,
                client=_http,
                tls=tls,
            )
        except Exception as e:
            logging.error("[OUTBOX-WORKER] stow_batch_instances raised: %s", e)
            logging.debug("[OUTBOX-WORKER] traceback:", exc_info=True)
            results, backoff = None, None

        if results is None:
            # Total transport failure not mapped per-SOP: fail the whole batch.
            for uid, ds, blob_path, raw_bytes, modified in _batch:
                outbox.mark_failed(uid, "Batch transport error")
            _batch = []
            _batch_study = None
            _batch_bytes = 0
            _batch_started_at = 0.0
            with _progress_lock:
                _last_progress = time.time()
            return

        # 2908: 507 Insufficient Storage -> backpressure, NOT a failure.
        # Files go back to pending without a retry bump; the worker pauses
        # for Retry-After seconds (clamped 5..300, default 30).
        if backoff is not None:
            batch_len = len(_batch)
            for uid, ds, blob_path, raw_bytes, modified in _batch:
                outbox.requeue(uid, f"Server 507 - retry after {backoff}s")
            _batch = []
            _batch_study = None
            _batch_bytes = 0
            _batch_started_at = 0.0
            with _progress_lock:
                _last_progress = time.time()
            outbox_pending_files.set(outbox.pending_count())
            logging.warning(
                "[OUTBOX-WORKER] Server 507 - %d SOP(s) returned to pending, "
                "pausing %.0fs (Retry-After)",
                batch_len,
                backoff,
            )
            _pause_until = time.time() + backoff
            return

        results_by_uid = {uid: (st, hs, msg) for uid, st, hs, msg in results}
        batch_ok = 0

        for uid, ds, blob_path, raw_bytes, modified in _batch:
            status, http_status, msg = results_by_uid.get(
                uid, (0xC000, None, "No outcome")
            )
            # P1-4: watchdog heartbeat after each STOW round.
            with _progress_lock:
                _last_progress = time.time()

            study_uid = str(getattr(ds, "StudyInstanceUID", "")) or ""
            if status == 0x0000:
                # sidecar no longer needed (audit trail embedded in
                # payload). Delete BEFORE mark_delivered so retry keeps it.
                if modified:
                    outbox.delete_mods_sidecar(blob_path)
                outbox.mark_delivered(uid)
                batch_ok += 1
                _delivered_total += 1
                if study_uid and study_uid in _study_stats:
                    _study_stats[study_uid]["delivered"] += 1
                if sop_index is not None:
                    try:
                        series_uid = str(getattr(ds, "SeriesInstanceUID", ""))
                        if uid and study_uid and series_uid:
                            sop_index.insert_sop(uid, study_uid, series_uid)
                    except Exception:
                        pass
            else:
                # PS3.18 10.5.2: a 2xx that the bridge could not read states
                # nothing about the instance - the origin may hold it. That is
                # not a refusal and must not consume a retry, or a delivery
                # nothing proved wrong reaches undelivered/. Requeue and let
                # the next pass re-send it.
                if msg and STOW_UNVERIFIED in msg:
                    outbox.requeue(uid, msg)
                    logging.warning(
                        "[OUTBOX-WORKER] SOP %s: STOW verdict unreadable - "
                        "returned to pending without a retry bump",
                        uid,
                    )
                    continue
                outbox.mark_failed(uid, msg or "Unknown error")
                _delivered_total += 1
                _delivered_failed += 1
                if study_uid and study_uid in _study_stats:
                    _study_stats[study_uid]["delivered"] += 1
                    _study_stats[study_uid]["failed"] += 1
                retries = outbox._get_retry_count(uid)
                # mark_failed already parked the item when it hit MAX_RETRIES;
                # a second unconditional move double-decrements the pending
                # counter and double-bumps undelivered_total.
                if retries >= outbox.MAX_RETRIES and not outbox._is_undelivered(uid):
                    outbox.move_to_undelivered(uid)

        logging.info(
            "[OUTBOX] Batch delivered %d/%d OK",
            batch_ok,
            len(_batch),
        )
        _batch = []
        _batch_study = None
        _batch_bytes = 0
        _batch_started_at = 0.0

        # 2908: observability - last successful STOW flush (unix time).
        if batch_ok > 0:
            outbox_last_success_timestamp.set(time.time())
        outbox_pending_files.set(outbox.pending_count())

        # P30: delivery summary -- progress every 100 SOPs or 30s.
        _now = time.time()
        pending = outbox.pending_count()
        if _delivered_total > 0 and (
            _delivered_total % 100 == 0 or _now - _last_summary_log >= 30.0
        ):
            _last_summary_log = _now
            _study_label = f"study={_current_study[:40]}" if _current_study else ""
            logging.info(
                "[OUTBOX] %d delivered, %d failed - %s",
                _delivered_total - _delivered_failed,
                _delivered_failed,
                _study_label,
            )

        # Queue drained: log per-study summaries and reset counters.
        if pending == 0 and not _queue_was_empty:
            _queue_was_empty = True
            _last_summary_log = _now
            for study_uid, s in list(_study_stats.items()):
                mods = ", ".join(sorted(s.get("modalities", set()))) or "??"
                logging.info(
                    "[OUTBOX] Study delivered: study=%s patient=%s modality=%s %d/%d OK",
                    study_uid[:50],
                    s.get("patient", "?"),
                    mods,
                    s.get("delivered", 0) - s.get("failed", 0),
                    s.get("delivered", 0),
                )
            _study_stats.clear()
            _current_study = None
            _delivered_total = 0
            _delivered_failed = 0
        elif pending > 0:
            _queue_was_empty = False

    def _dequeue_safe():
        try:
            return outbox.dequeue()
        except Exception as e:
            logging.error("[OUTBOX-WORKER] dequeue() failed: %s", e)
            logging.debug("[OUTBOX-WORKER] dequeue traceback:", exc_info=True)
            _shutdown_requested.wait(timeout=1.0)
            return (None, None, None, None)

    while not _shutdown_requested.is_set():
        # STORE-FORWARD: if the server is down, pause instead of
        # burning STOW retries (MAX_RETRIES=10 -> undelivered -> manual).
        # Reads the health checker's cached event - no HTTP on the hot path.
        if health_checker is not None and not health_checker.is_healthy():
            if _batch:
                # The paused batch's items are already CLAIMED (dequeue moved
                # them to in_progress/), and only `_deliver_batch` gives them
                # back. Pausing with a non-empty `_batch` therefore left a
                # partially built batch owned by nobody: the stuck-item sweep
                # later returned those files to pending/ and re-sent the very
                # instances this batch still held - a double delivery.
                #
                # Hand the tail back to pending UNBURNED. The peer is known
                # down, not rejecting: sending anyway costs a retry per item
                # for a guaranteed failure (ten of them park the study in
                # undelivered/), and marking them delivered would lie. A
                # store-and-forward queue exists to survive exactly this state.
                logging.warning(
                    "[OUTBOX-WORKER] Server down with %d buffered item(s) - "
                    "returning them to pending and pausing",
                    len(_batch),
                )
                # `_batch` holds 5-tuples. Passing the TUPLE to `requeue` sent
                # it into `_safe_uid`, whose string methods raised
                # AttributeError for every item - the batch was then cleared and
                # the claimed files sat in in_progress/ until the 300 s reaper
                # ran, which in Storage Commitment mode can push SOPs past the
                # CommitTracker deadline and report them not committed.
                for _uid, _ds, _bp, _raw, _mod in list(_batch):
                    try:
                        outbox.requeue(_uid, "server down")
                    except Exception as e:
                        logging.error(
                            "[OUTBOX-WORKER] Could not return %s to pending: %s",
                            _uid,
                            e,
                        )
                # Reset EVERY field of the batch state, not just the list.
                # A surviving `_batch_study` made the next enqueue look like a
                # continuation of the abandoned study, so the first instance of
                # the NEXT study was appended to it (and flushed under the old
                # study's stats); a surviving `_batch_bytes` skewed the size
                # guard and the flush log by the abandoned tail's bytes.
                _batch = []
                _batch_study = None
                _batch_bytes = 0
                _batch_started_at = 0.0
            if not _was_paused:
                _was_paused = True
                logging.warning(
                    "[OUTBOX-WORKER] Server down - worker paused "
                    "(no STOW, no HTTP); will resume on recovery"
                )
            _shutdown_requested.wait(5.0)
            with _progress_lock:
                _last_progress = time.time()
            continue
        elif _was_paused:
            _was_paused = False
            logging.info("[OUTBOX-WORKER] Server up - delivery resumed")

        # 2908: 507 backpressure - pause for Retry-After seconds (clamped
        # 5..300 by retry_after_seconds, default 30). Files stay pending.
        # WARN once per paused/resumed transition.
        if _pause_until > time.time():
            if not _was_507_paused:
                _was_507_paused = True
                logging.warning(
                    "[OUTBOX-WORKER] Server 507 - paused %.0fs (Retry-After); "
                    "files stay pending",
                    _pause_until - time.time(),
                )
            outbox_pending_files.set(outbox.pending_count())
            with _progress_lock:
                _last_progress = time.time()
            _shutdown_requested.wait(5.0)
            continue
        elif _was_507_paused:
            _was_507_paused = False
            logging.warning("[OUTBOX-WORKER] 507 pause over - delivery resumed")

        # 2908: live pending-count gauge (outbox worker view).
        outbox_pending_files.set(outbox.pending_count())

        # periodic stuck-item reaper -- every 60s, reset in_progress
        # items stuck too long (crashed worker, hung HTTP) or max-retry blobs
        # still on disk so they can be retried.
        _now = time.time()
        if _now - _last_stuck_check >= STUCK_ITEM_CHECK_INTERVAL:
            _last_stuck_check = _now
            outbox.recover_stuck()

        result = _dequeue_safe()

        if result[0] is None:
            # Nothing ready now. If a study tail is buffered, wait up to
            # batch_idle_sec for a same-study item; if none arrives, flush.
            if _batch:
                _shutdown_requested.wait(timeout=batch_idle_sec)
                with _progress_lock:
                    _last_progress = time.time()
                result = _dequeue_safe()
                # The health verdict may have flipped DURING the idle wait, and
                # the check at the top of the loop cannot see it: the wait put
                # us past that check. This applies to BOTH outcomes below - a
                # dequeue that returned an SOP from another study goes on to
                # flush the buffered batch at the study boundary, which charged
                # a retry per item for a guaranteed failure the same way an idle
                # flush did. So the verdict is read once, here, before either
                # path can send a STOW.
                if health_checker is not None and not health_checker.is_healthy():
                    logging.warning(
                        "[OUTBOX-WORKER] Server went down during the idle "
                        "wait with %d buffered item(s) - returning them to "
                        "pending instead of flushing",
                        len(_batch),
                    )
                    for _uid, _ds, _bp, _raw, _mod in list(_batch):
                        try:
                            outbox.requeue(_uid, "server down")
                        except Exception as e:
                            logging.error(
                                "[OUTBOX-WORKER] Could not return %s to " "pending: %s",
                                _uid,
                                e,
                            )
                    _batch = []
                    _batch_study = None
                    _batch_bytes = 0
                    _batch_started_at = 0.0
                    # The item dequeue just claimed was taken AFTER the server
                    # went down, so it has not failed either - give it back
                    # unburned rather than carrying it into a doomed send.
                    if result[0] is not None:
                        try:
                            outbox.requeue(result[0], "server down")
                        except Exception as e:
                            logging.error(
                                "[OUTBOX-WORKER] Could not return %s to pending: %s",
                                result[0],
                                e,
                            )
                        result = (None, None, None, None)
                    outbox_pending_files.set(outbox.pending_count())
                    continue
                if result[0] is None:
                    _deliver_batch()
                    continue
            else:
                # P8 + retry: sleep until next_retry_at (bounded by 5s).
                wait = outbox.next_retry_wait_sec()
                _shutdown_requested.wait(timeout=wait)
                # P30/P1-4: watchdog. Measure the age of the PREVIOUS
                # heartbeat, then refresh it. Writing the heartbeat before
                # measuring makes dead_sec ~0 by construction and leaves the
                # branch below unreachable.
                with _progress_lock:
                    dead_sec = time.time() - _last_progress
                    _last_progress = time.time()
                if dead_sec > _OUTBOX_STALL_SEC and outbox.pending_count() > 0:
                    logging.warning(
                        "[OUTBOX-WATCHDOG] Worker stalled %.0fs with %d pending - "
                        "running recovery",
                        dead_sec,
                        outbox.pending_count(),
                    )
                    reset_p, reset_r = outbox.recover_stuck()
                    if reset_p > 0 or reset_r > 0:
                        logging.warning(
                            "[OUTBOX-WATCHDOG] Recovery done: %d stuck in_progress, "
                            "%d moved to undelivered",
                            reset_p,
                            reset_r,
                        )
                    with _progress_lock:
                        _last_progress = time.time()
                        _last_stuck_check = time.time()
                continue

        sop_uid, ds, blob_path, raw_bytes = result
        # ds is already a pydicom Dataset from dequeue() -- no dcmread needed.

        # The queue is no longer idle the moment an item is CLAIMED, not when a
        # later flush happens to observe pending work. A steady trickle of one
        # SOP per study always emptied the queue before each flush, so
        # `pending == 0` held on every drain with `_queue_was_empty` already
        # True: the summaries never ran and `_study_stats` grew by one entry per
        # study for the life of the process.
        _queue_was_empty = False

        # Study context for batching + INFO-level delivery logging.
        try:
            _study_uid = str(getattr(ds, "StudyInstanceUID", ""))
        except Exception:
            _study_uid = ""

        # Study boundary HARD: never mix studies in one batch. Switch flushes.
        if _batch and _study_uid != _batch_study:
            _deliver_batch()
            # The flush can set `_pause_until` (a 507 with Retry-After). The
            # item just dequeued belongs to the NEXT study and is not part of
            # that failed batch, but appending it here and then meeting the
            # byte limit sent another STOW immediately - straight through the
            # backoff the server just asked for. It goes back to pending
            # UNBURNED: nothing about this item failed.
            if _pause_until > time.time():
                logging.warning(
                    "[OUTBOX-WORKER] 507 pause began during the study switch - "
                    "returning %s to pending unburned",
                    sop_uid,
                )
                try:
                    outbox.requeue(sop_uid, "retry-after pause")
                except Exception as e:
                    logging.error(
                        "[OUTBOX-WORKER] Could not return %s to pending: %s",
                        sop_uid,
                        e,
                    )
                outbox_pending_files.set(outbox.pending_count())
                continue

        if _study_uid and _study_uid != _current_study:
            _current_study = _study_uid
            _log_study_start(sop_uid, ds, _study_uid)
            mods_display = (
                ", ".join(sorted(_study_stats[_study_uid].get("modalities", set())))
                or "??"
            )
            logging.info(
                "[OUTBOX] Delivering: study=%s patient=%s modality=%s - %d SOP(s) pending",
                _study_uid[:50],
                _study_stats[_study_uid]["patient"],
                mods_display,
                outbox.pending_count() + 1,
            )

        # apply deferred audit trail (off hot-path). C-STORE handler
        # generated PatientID/Name but skipped (0400,0561); now we apply
        # record_modification() from the .mods sidecar written by enqueue().
        mods_json = outbox.read_mods_sidecar(blob_path)
        dataset_modified = False
        if mods_json:

            try:
                for entry in mods_json:
                    tag = tuple(entry["tag"])
                    record_modification(
                        ds,
                        tag,
                        entry["old"],
                        modifying_operator="DIMSE",
                        modifying_system=bridge_ae_title,
                    )
                dataset_modified = True
                logging.debug(
                    "[OUTBOX-WORKER] Applied %d audit trail entries for SOP %s",
                    len(mods_json),
                    sop_uid,
                )
            except Exception as e:
                logging.warning(
                    "[OUTBOX-WORKER] Failed to apply audit trail for SOP %s: %s",
                    sop_uid,
                    e,
                )
                # Continue delivery -- blob is valid even without audit trail

        # P8: raw pass-through for CAS dedup. Modified instances (raw=None)
        # are re-serialized by stow_batch_instances via dcmwrite.
        if not _batch:
            # R3: the batch's age is fixed by its FIRST item, not refreshed by
            # later ones - the stuck-item reaper counts from that instant.
            _batch_started_at = time.monotonic()
        _batch.append(
            (
                sop_uid,
                ds,
                blob_path,
                (None if dataset_modified else raw_bytes),
                dataset_modified,
            )
        )
        try:
            _batch_bytes += os.path.getsize(blob_path)  # on-disk size = payload proxy
        except OSError:
            _batch_bytes += len(raw_bytes) if raw_bytes else 0
        _batch_study = _study_uid

        # Flush when count, bytes or AGE trigger fires. The age limit is the
        # one that protects the oldest item from the stuck-item reaper: see
        # _batch_started_at for the double-delivery it prevents.
        if (
            len(_batch) >= batch_max_sop
            or _batch_bytes >= batch_max_bytes
            or time.monotonic() - _batch_started_at >= _batch_max_age_sec
        ):
            _deliver_batch()

    if _batch:
        _deliver_batch()  # shutdown: drain any remaining tail first
    _http.close()  # P30: clean up persistent HTTP client
    logging.info("[OUTBOX-WORKER] Worker stopped")

def _start_outbox_workers(
    outbox,
    clarus_url,
    http_timeout,
    sop_index,
    move_jobs,
    batch_max_sop=100,
    batch_max_bytes=96 * 1024 * 1024,
    batch_idle_sec=5.0,
    health_checker=None,
    tls=None,
    bridge_ae_title="CLBRIDGE",
):
    """Start single background outbox worker thread. KISS."""
    t = threading.Thread(
        target=_outbox_worker,
        args=(
            outbox,
            clarus_url,
            http_timeout,
            sop_index,
            move_jobs,
            batch_max_sop,
            batch_max_bytes,
            batch_idle_sec,
            health_checker,
            tls,
            bridge_ae_title,
        ),
        name="outbox-worker",
        daemon=False,
    )
    t.start()
    logging.info("[OUTBOX-WORKER] Started 1 worker")
    return [t]

def _drain_outbox(outbox):
    """Wait for outbox to empty, then close (graceful shutdown)."""
    pending = outbox.pending_count()
    if pending > 0:
        logging.info("[OUTBOX] Waiting for %d pending SOPs to be delivered...", pending)
        # Poll until empty or shutdown
        while outbox.pending_count() > 0 and not _shutdown_requested.is_set():
            _shutdown_requested.wait(timeout=0.5)
        remaining = outbox.pending_count()
        if remaining > 0:
            logging.warning(
                "[OUTBOX] %d SOPs remain undelivered - will survive restart",
                remaining,
            )
    outbox.close()
    logging.info("[OUTBOX] Closed")

# ---------------------------------------------------------------------------
# Forwarder: _forward_worker - best-effort DIMSE drain of the
# SECOND (non-authoritative) outbox into the second DIMSE server.
#
# The forward channel is fully isolated from the primary STOW drain: it holds
# its own OutboxQueue instance (clean_code/outbox.py, the same class), runs on
# its own thread, and pauses rather than burning retries when the second server
# is unreachable. Whatever happens here NEVER backpressures primary reception.
#
# Reuses the byte-level meta helpers from handlers/cmove.py (import only, no
# edits) to read each stored blob's (sop_class, transfer_syntax) without a full
# pydicom parse. The blob is sent as stored bytes (its own Transfer Syntax).
# ---------------------------------------------------------------------------

# Forward batching: up to 20 SOPs per association (a widely interoperable
# ceiling), drained over a short 0.5 s window to fill each association, then a
# 5 s pause before retrying after an association failure so a dead peer is not
# hammered.
_FORWARD_BATCH_MAX_SOP = 20
_FORWARD_BATCH_WINDOW_S = 0.5
_FORWARD_PAUSE_S = 5.0

# PS3.4 Table B.2-1: the C-STORE WARNING statuses. The set is ENUMERATED, not
# the 0xB000..0xBFFF range: the status space is not a range, and accepting
# undefined codes there reported an instance as archived on a code the standard
# does not define. 0xB000 and 0xB006 mean the instance was stored with a
# coercion or a discarded element; 0xB007 means it was NOT stored as sent, so it
# stays on the failure path.
_CSTORE_WARNING_STATUSES = frozenset({0xB000, 0xB006})

def _forward_blob_pair(raw_bytes):
    """Read (sop_class_uid, stored_ts_uid) from a stored DICOM file's meta.

    Uses the byte-level helpers from handlers/cmove.py:805-987 (import, no
    edits). Reads (0002,0002) MediaStorageSOPClassUID and (0002,0010)
    TransferSyntaxUID straight from the preamble-aware meta group, so a
    forward blob is identified WITHOUT a pydicom dataset parse.
    """
    sop_class = _extract_meta_ui(raw_bytes, 0x0002)
    stored_ts = _extract_meta_ui(raw_bytes, 0x0010)
    if sop_class is None:
        # Meta MS SOP class absent - fall back to dataset (0008,0016).
        sop_class = _extract_dataset_ui(raw_bytes, 0x0016, group=0x0008)
    return sop_class, stored_ts

def _forward_blob_size(blob_path):
    """Size in bytes of a forward blob, 0 when it cannot be stat'ed.

    Metrics must never break the drain, so a vanished/renamed blob degrades
    to 0 rather than raising.
    """
    try:
        return os.path.getsize(blob_path)
    except OSError:
        return 0

# True when the last `_forward_open_assoc` call reached the peer and the
# peer rejected every proposed presentation context. Reset on every call.
_LAST_OPEN_REFUSED = False

def _forward_open_assoc(
    calling_ae, dest_ae, host, port, pairs, network_timeout, dimse_timeout, acse_timeout
):
    """Open ONE association carrying one requested context per distinct
    (sop_class, stored_ts) pair of the batch. Returns the established
    association, or None on any failure.

    On None, `_LAST_OPEN_REFUSED` says whether the peer ANSWERED and rejected
    every proposed context (a capability verdict) or was never reached at all
    (a transport failure). The distinction is published here rather than in the
    return value because every caller and every test treats this function as
    "association or None", and widening that tuple would have changed a contract
    nothing else in the module needs.
    """
    ae = AE(ae_title=calling_ae)
    ae.network_timeout = network_timeout
    ae.acse_timeout = acse_timeout
    ae.dimse_timeout = dimse_timeout
    # F12 sibling: bound the raw TCP connect. A black-hole forward
    # destination otherwise parks this association on the OS SYN timeout
    # (minutes), and the forward worker is the only thing draining its queue.
    ae.connection_timeout = acse_timeout
    for sop_class, ts_uid in sorted(pairs):
        if sop_class and ts_uid:
            ae.add_requested_context(sop_class, ts_uid)
    global _LAST_OPEN_REFUSED
    _LAST_OPEN_REFUSED = False
    try:
        assoc = ae.associate(host, port, ae_title=dest_ae)
    except Exception:
        return None
    if not assoc.is_established:
        # The peer ANSWERED and refused everything it was offered: every
        # proposed presentation context was rejected, so no A-ASSOCIATE-AC was
        # sent. `is_established` is False for this AND for a silent/refused
        # peer, and an unreachable peer also reports is_aborted - so the
        # refusal evidence is taken ONLY from rejected_contexts, which is
        # populated from the A-ASSOCIATE-RJ/AC result and stays empty when no
        # response ever arrived.
        refused = False
        try:
            refused = bool(getattr(assoc, "rejected_contexts", None) or [])
        except Exception:
            refused = False
        try:
            assoc.release()
        except Exception:
            pass
        _LAST_OPEN_REFUSED = refused
        return None
    # Counted only once the association is actually established: a refused
    # association is not an association made.
    try:
        associations_total.labels(role="to", ae=ae_label(dest_ae)).inc()
    except Exception:
        pass
    return assoc

def _forward_process_batch(
    forward_outbox,
    items,
    dest_ae,
    calling_ae,
    host,
    port,
    network_timeout,
    dimse_timeout,
    acse_timeout,
    settled=None,
):
    """Deliver ONE already-claimed batch of forward items over a single
    association.

    Args:
        forward_outbox: the forward OutboxQueue.
        items: list of claimed tuples (uid, sop_class, stored_ts, blob_path),
               each ALREADY atomically claimed into forward/in_progress via
               dequeue() (so mark_delivered/mark_failed/requeue know the mover).
        dest_ae/host/port/calling_ae/timeouts: association parameters.
        settled: set the CALLER owns for THIS call. Every UID whose queue
               transition this call completed is added to it. It is passed in
               rather than published as a function attribute because an
               attribute outlives the call: a batch that raised before the
               `finally` left the previous batch's set in place, and the
               caller then skipped a UID that was due for retry. A per-call
               set also survives an exception, which is exactly when the
               caller needs it.

    Returns True if the association was usable (even if individual RSPs were
    non-zero); False if the association could NOT be established at all, in
    which case the CALLER requeues the whole batch (no retry burn) and pauses.

    Per instance it READS every C-STORE-RSP: 0x0000 -> mark_delivered;
    a non-zero RSP -> mark_failed (backoff, then undelivered at max retries);
    a lost/None RSP or an unasendable context mismatch -> requeued without a
    retry burn (association transport issue, not a per-instance failure).

    Items are sent in deterministic uid order: dequeue() claims files in
    os.listdir order, which differs across filesystems (CI failure on Linux
    ext4 vs local NTFS) - sorting here makes delivery order stable and
    reproducible everywhere, and keeps the wire test's exact-order pin valid.
    """
    items = sorted(items, key=lambda item: item[0])
    self_handled = settled if settled is not None else set()

    # Items that lost their sop_class / stored_ts cannot be proposed over any
    # negotiated context. They used to be silently dropped from `pairs` while
    # staying unsent: never delivered, never failed, so the caller requeued
    # the whole batch forever and one broken item blocked every valid one
    # behind it. Fail them HERE (before the association) and proceed with the
    # rest.
    sendable = []
    pairs = set()
    for uid, sop_class, stored_ts, blob_path in items:
        if sop_class and stored_ts:
            sendable.append((uid, sop_class, stored_ts, blob_path))
            pairs.add((sop_class, stored_ts))
        else:
            logging.warning(
                "[FORWARD] SOP %s missing sop_class/stored_ts - mark_failed",
                uid,
            )
            forward_failed_total.inc()
            # Same rule as the context-rejection path: settled only on a
            # successful transition, so a failed one is left to recovery.
            try:
                forward_outbox.mark_failed(uid, "missing sop_class/stored_ts")
            except Exception as exc:
                logging.error(
                    "[FORWARD] SOP %s: cannot record the failure (%s) - "
                    "leaving it for recovery",
                    uid,
                    exc,
                )
                continue
            self_handled.add(uid)
    if not sendable:
        # Nothing sendable remained; every item was already failed above, so
        # the batch is terminal (not retryable).
        return True
    pairs = sorted(pairs)
    assoc = _forward_open_assoc(
        calling_ae,
        dest_ae,
        host,
        port,
        pairs,
        network_timeout,
        dimse_timeout,
        acse_timeout,
    )
    if assoc is None and _LAST_OPEN_REFUSED:
        # The peer answered and rejected every context: a capability verdict.
        # Charging the batch against its retry budget is what stops an
        # incompatible SOP class from being re-proposed forever; the items
        # reach undelivered/ and the operator sees them.
        logging.warning(
            "[FORWARD] %s at %s:%s rejected every proposed context - "
            "charging the retry budget for %d item(s)",
            dest_ae,
            host,
            port,
            len(sendable),
        )
        for uid, _sop_class, _stored_ts, _blob_path in sendable:
            forward_failed_total.inc()
            # Settled only when the transition actually happened. Recording the
            # UID unconditionally let a raising `mark_failed` count as handled,
            # so the caller never requeued the item and it stayed in
            # in_progress/ with no retry and no verdict.
            try:
                forward_outbox.mark_failed(uid, "all presentation contexts rejected")
            except Exception as exc:
                logging.error(
                    "[FORWARD] SOP %s: cannot record the context rejection "
                    "(%s) - leaving it for recovery",
                    uid,
                    exc,
                )
                continue
            self_handled.add(uid)
        return True
    if assoc is None:
        logging.warning(
            "[FORWARD] Cannot associate with %s at %s:%s - batch %d requeued, "
            "pause %.0fs (no retry burn)",
            dest_ae,
            host,
            port,
            len(items),
            _FORWARD_PAUSE_S,
        )
        return False

    try:
        # accepted = {sop_class: {ts,...}} from the negotiated contexts.
        accepted = {}
        for ctx in assoc.accepted_contexts:
            ts_list = [str(t) for t in (ctx.transfer_syntax or [])]
            accepted.setdefault(str(ctx.abstract_syntax), set()).update(ts_list)

        delivered_any = False
        for uid, sop_class, stored_ts, blob_path in sendable:
            # Only send when the negotiated context actually covers this
            # sop_class and stored TS; sending stored bytes as-is over a
            # foreign/absent TS would corrupt them. A peer that cannot accept
            # this SOP class / TS is a PEER CAPABILITY RESULT, so it burns a
            # retry (mark_failed -> at max retries -> undelivered), exactly like
            # a non-zero RSP. It is NOT a transient transport condition, so it
            # must NOT requeue-no-burn (which would otherwise spin forever).
            negotiated_ts = accepted.get(sop_class, set())
            if not sop_class or stored_ts not in negotiated_ts:
                logging.warning(
                    "[FORWARD] SOP %s %s@%s context not negotiated - "
                    "mark_failed (capability verdict, retry budget applied "
                    "then undelivered)",
                    uid,
                    sop_class,
                    stored_ts,
                )
                forward_failed_total.inc()
                try:
                    forward_outbox.mark_failed(uid, "context not covered")
                except Exception as exc:
                    logging.error(
                        "[FORWARD] SOP %s: cannot record the context verdict "
                        "(%s) - leaving it for recovery",
                        uid,
                        exc,
                    )
                    continue
                self_handled.add(uid)
                continue

            # Size is read BEFORE the send: mark_delivered removes the blob,
            # so measuring afterwards always yields 0.
            _blob_size = _forward_blob_size(blob_path)
            # Ship the audit trail WITH the instance. `enqueue_from_blob`
            # copies the primary `.mods` sidecar alongside the blob, but the
            # forward channel used to send the raw file and drop the sidecar -
            # so the second archive stored an instance whose Modified
            # Attributes Sequence was missing, i.e. a different record from
            # the one this bridge keeps. When a sidecar exists the instance is
            # re-serialized with the same `record_modification` entries the
            # primary drain applies, and THAT byte stream is what goes on the
            # wire.
            _send_path = blob_path
            _mods_extra = None
            # The temp file this re-serialization creates, recorded at CREATION.
            # `_mods_extra` is only assigned after `save_as` succeeds, so a
            # `save_as` that raised part-way left a file holding patient data,
            # in the outbox directory, with nothing referencing it - neither
            # the failure branch below nor the `finally` could find it.
            _tmp_send_path = None
            try:
                _mods_json = forward_outbox.read_mods_sidecar(blob_path)
            except Exception:
                _mods_json = None
            if _mods_json:
                try:
                    from pydicom import dcmread as _fwd_dcmread

                    _fds = _fwd_dcmread(blob_path)
                    for entry in _mods_json:
                        record_modification(
                            _fds,
                            tuple(entry["tag"]),
                            entry["old"],
                            modifying_operator="DIMSE",
                            modifying_system=calling_ae,
                        )
                    import os as _os_fwd
                    import tempfile as _tf_fwd

                    _fh = _tf_fwd.NamedTemporaryFile(
                        suffix=".dcm", delete=False, dir=_os_fwd.path.dirname(blob_path)
                    )
                    _fh.close()
                    _tmp_send_path = _fh.name
                    _fds.save_as(_fh.name, enforce_file_format=True)
                    _send_path = _fh.name
                    _mods_extra = _fh.name
                    _blob_size = _forward_blob_size(_send_path)
                except Exception as mods_err:
                    logging.warning(
                        "[FORWARD] SOP %s: audit sidecar could not be applied "
                        "(%s) - sending the stored blob unchanged",
                        uid,
                        mods_err,
                    )
                    # A partial file from the failed write holds patient data.
                    if _tmp_send_path:
                        try:
                            import os as _os_fwd_part

                            _os_fwd_part.unlink(_tmp_send_path)
                        except OSError:
                            pass
                        _tmp_send_path = None
                    _send_path = blob_path
                    _mods_extra = None
                    _blob_size = _forward_blob_size(blob_path)
            try:
                _t0 = time.perf_counter()
                status = assoc.send_c_store(_send_path)
                try:
                    cstore_outbound_duration.labels(peer=ae_label(dest_ae)).observe(
                        time.perf_counter() - _t0
                    )
                except Exception:
                    pass
            except Exception as fwd_err:
                logging.warning(
                    "[FORWARD] SOP %s C-STORE raised %s - requeued (no burn)",
                    uid,
                    type(fwd_err).__name__,
                )
                if _mods_extra:
                    try:
                        import os as _os_fwd2

                        _os_fwd2.unlink(_mods_extra)
                    except OSError:
                        pass
                try:
                    forward_outbox.requeue(
                        uid, f"send exception: {type(fwd_err).__name__}"
                    )
                except Exception:
                    pass
                # The association is the batch's transport. Once it is gone,
                # every remaining send raises the same way: the loop used to
                # requeue each item in turn and then return True, so the worker
                # treated the batch as settled and retried WITHOUT the
                # association-failure pause - hammering a peer that had already
                # closed on us. Returning False hands the whole unsettled batch
                # back for requeue-and-pause, while the items already settled
                # above stay settled because they are in `self_handled`.
                try:
                    still_up = bool(assoc.is_established)
                except Exception:
                    still_up = False
                if not still_up:
                    logging.warning(
                        "[FORWARD] association closed during the batch - "
                        "abandoning the rest for a paused retry"
                    )
                    return False
                self_handled.add(uid)
                continue
            finally:
                if _mods_extra:
                    try:
                        import os as _os_fwd3

                        _os_fwd3.unlink(_mods_extra)
                    except OSError:
                        pass

            # READ every C-STORE-RSP. `send_c_store` also RETURNS an EMPTY
            # Dataset when the peer times out, aborts or sends an invalid
            # response, so `status is not None` is not "a status arrived":
            # reading `Status` off that empty set used to raise AttributeError,
            # which escaped this function and killed the batch with no cost
            # recorded for the instance that caused it.
            try:
                rsp_status = getattr(status, "Status", None)
            except Exception as stat_err:
                # A malformed Status element (wrong VR, unexpected type) is a
                # per-instance verdict, not a batch-level crash: cost it like a
                # rejection and keep draining the rest of the batch.
                forward_failed_total.inc()
                logging.warning(
                    "[FORWARD] SOP %s: malformed C-STORE-RSP Status (%s) - "
                    "counted as rejected",
                    uid,
                    stat_err,
                )
                try:
                    forward_outbox.mark_failed(uid, f"malformed RSP: {stat_err}")
                except Exception:
                    pass
                continue
            # PS3.7 Annex C: a WARNING is a SUCCESS class status - the instance
            # WAS stored. Treating 0xB000/0xB006/0xB007 as a failure marked a
            # delivered instance failed, retried it, and eventually parked it in
            # undelivered/ while the destination held it all along.
            #
            # The set is ENUMERATED, not the whole 0xB000..0xBFFF range: PS3.4
            # Table B.2-1 defines exactly 0xB000 (coercion), 0xB006 (element
            # discarded) and 0xB007 (data set does not match SOP class) as
            # C-STORE warnings - and 0xB007 in particular means the instance was
            # NOT stored as sent. Treating an undefined status in that range as
            # delivered told the modality (and the forward channel) that an
            # instance was archived on the strength of a code the standard does
            # not define, so anything unrecognised stays on the failure path.
            if rsp_status == 0x0000 or rsp_status in _CSTORE_WARNING_STATUSES:
                # Settled only when the transition actually happened: recording
                # the UID unconditionally let a raising mark_delivered count as
                # handled, so the caller never requeued the item and it stayed
                # in in_progress/ with no retry and no verdict.
                try:
                    forward_outbox.mark_delivered(uid)
                except Exception as exc:
                    logging.error(
                        "[FORWARD] SOP %s: cannot record the delivery (%s) - "
                        "leaving it for recovery",
                        uid,
                        exc,
                    )
                    continue
                self_handled.add(uid)
                forward_delivered_total.inc()
                try:
                    bytes_total.labels(direction="tx", peer=ae_label(dest_ae)).inc(
                        _blob_size
                    )
                except Exception:
                    pass
                delivered_any = True
                logging.debug("[FORWARD] SOP %s delivered (0x%04X)", uid, rsp_status)
            elif rsp_status is None:
                # No C-STORE-RSP at all: the peer dropped the association, or
                # returned an EMPTY Dataset. When the association is GONE the
                # remaining items in this batch were never attempted on the
                # wire at all - charging each of them a retry burned the whole
                # batch's budget (20 items x MAX_RETRIES) on one transport
                # failure and parked a healthy queue in undelivered/. Hand the
                # rest back unclaimed and let the caller pause and retry the
                # batch on a fresh association.
                if not getattr(assoc, "is_established", False):
                    logging.warning(
                        "[FORWARD] association lost before SOP %s - handing "
                        "back the rest of the batch uncharged, %s included",
                        uid,
                        uid,
                    )
                    # This SOP's C-STORE-RSP never arrived and its claim is
                    # still open: it must go back to pending/ with the unsent
                    # items, NOT be reported as settled. Settling it left the
                    # claimed blob in in_progress/ for the 300 s reaper, so a
                    # SOP that only needed a re-send waited out the stuck
                    # sweep - and if the destination was reachable again by
                    # then, the reaper's requeue was the only thing that saved
                    # it. Earlier UIDs are legitimately settled and stay so.
                    return False
                # Association still up: this one instance produced no answer.
                # Requeueing it for free let a single instance that always
                # loses its response hot-loop the channel forever: every drain
                # picked it first again. It costs a retry exactly like a
                # rejection, so at MAX_RETRIES the item leaves the channel and
                # the rest of the queue drains.
                forward_failed_total.inc()
                logging.warning(
                    "[FORWARD] SOP %s: no C-STORE-RSP read - requeued with "
                    "a retry burn",
                    uid,
                )
                try:
                    forward_outbox.mark_failed(uid, "no RSP")
                except Exception:
                    pass
                self_handled.add(uid)
            else:
                # A real FAILURE RSP (0xA7xx/0xC000/0x0122...). mark_failed
                # bumps the retry counter and, at MAX_RETRIES, calls
                # move_to_undelivered internally (outbox.py semantics).
                msg = str(rsp_status)
                forward_failed_total.inc()
                # Same rule as every other transition in this loop: a failed
                # mark_failed is left for recovery rather than counted as
                # settled.
                try:
                    forward_outbox.mark_failed(uid, f"C-STORE {msg}")
                except Exception as exc:
                    logging.error(
                        "[FORWARD] SOP %s: cannot record the rejection (%s) - "
                        "leaving it for recovery",
                        uid,
                        exc,
                    )
                    continue
                self_handled.add(uid)
                logging.warning("[FORWARD] SOP %s rejected: %s", uid, msg)
        if delivered_any:
            try:
                forward_last_success_timestamp.set(time.time())
            except Exception:
                pass
        return True
    finally:
        # `settled` is the caller's set (see the docstring): whether this call
        # returns True, gives up on a lost association or raises, the UIDs it
        # already transitioned are visible to the recovery path.
        try:
            assoc.release()
        except Exception:
            pass

def _forward_worker(
    forward_outbox,
    dest_ae,
    calling_ae,
    host,
    port,
    network_timeout=30,
    dimse_timeout=30,
    acse_timeout=15,
):
    """Background thread loop: drain forward/pending into the second DIMSE
    server. Runs independently of _outbox_worker; the two queues/threads are
    isolated, so a slow/dead second server CANNOT stall the primary drain."""
    _last_stuck = 0.0
    while not _shutdown_requested.is_set():
        # Periodic stuck recovery (restart replay / crash recovery) - same
        # recover_stuck semantics as the primary outbox (outbox.py).
        now = time.time()
        if now - _last_stuck >= 60.0:
            _last_stuck = now
            try:
                forward_outbox.recover_stuck()
            except Exception:
                pass
        try:
            forward_pending_files.set(forward_outbox.pending_count())
        except Exception:
            pass

        # Drain one batch (up to _FORWARD_BATCH_MAX_SOP within a small window).
        items = []
        window_end = time.time() + _FORWARD_BATCH_WINDOW_S
        while not _shutdown_requested.is_set() and len(items) < _FORWARD_BATCH_MAX_SOP:
            try:
                res = forward_outbox.dequeue()
            except Exception:
                res = (None, None, None, None)
            uid, _ds, blob_path, raw_bytes = res
            if uid is None:
                break
            sop_class, stored_ts = _forward_blob_pair(raw_bytes)
            items.append((uid, sop_class, stored_ts, blob_path))
            if time.time() >= window_end:
                break

        if not items:
            # Empty / nothing ready - sleep until the next retry is due.
            try:
                wait = forward_outbox.next_retry_wait_sec()
            except Exception:
                wait = 1.0
            _shutdown_requested.wait(timeout=max(0.1, wait))
            continue

        # A batch that raises must not kill this loop: the thread is the only
        # thing draining the forward queue, so losing it leaves claimed items
        # in forward/in_progress and forwarding silently stops until restart.
        # Treat an escape as an association-level failure (requeue, no burn).
        #
        # The settlement set is created HERE, per batch, and handed in: it must
        # describe this call only. Reading it off the function (`handled`) meant
        # an exception before the `finally` re-published it left the PREVIOUS
        # batch's UIDs in place, and recovery then skipped a SOP that was due
        # for retry.
        handled = set()
        try:
            assoc_ok = _forward_process_batch(
                forward_outbox,
                items,
                dest_ae,
                calling_ae,
                host,
                port,
                network_timeout,
                dimse_timeout,
                acse_timeout,
                settled=handled,
            )
        except Exception as e:
            logging.error(
                "[FORWARD] batch processing raised %s: %s - requeueing %d item(s)",
                type(e).__name__,
                e,
                len(items),
            )
            assoc_ok = False
        if not assoc_ok:
            # Association-level failure: requeue the items that were never
            # settled, without burning retries, then pause (destination probe).
            # Items already delivered or failed are skipped - requeueing them
            # moved a DELIVERED blob back into pending/.
            for uid, _sop, _ts, _bp in items:
                if uid in handled:
                    continue
                try:
                    forward_outbox.requeue(uid, "association failed")
                except Exception:
                    pass
            _shutdown_requested.wait(timeout=_FORWARD_PAUSE_S)
        try:
            forward_pending_files.set(forward_outbox.pending_count())
        except Exception:
            pass

# ---------------------------------------------------------------------------
# _register_handlers - DIMSE event handler registration
# ---------------------------------------------------------------------------
def _register_handlers(
    args,
    sop_index,
    move_jobs,
    sop_registry,
    outbox,
    health_checker,
    commit_tracker=None,
    forward_outbox=None,
    expose_rejected=False,
    allowlist_titles=(),
):
    """Register DIMSE event handlers. Returns list of (event, handler) tuples.

    `expose_rejected` is bound to the AE this set is registered on: the Expose
    Rejected Instances AE builds its own set with the flag on, every other AE
    uses the default. It only affects the QIDO/WADO query the C-FIND and
    C-MOVE handlers issue - the DIMSE behaviour is identical.

    `allowlist_titles` is the calling-AE allowlist the owning AE was armed
    with (empty when the filter is off); it only feeds the warning handler,
    because the refusal itself happens in the AE's negotiation.
    """
    # Bridge: verbose HTTP logging when DEBUG level is active
    verbose = args.log_level == "DEBUG"

    # Storage Commitment presence, read here rather than threaded in as a
    # parameter: it is consumed by on_n_action below, and the same one-line
    # formula already appears in _start_background_services (which selects the
    # readiness-gate mode). A parameter would add an argument for a single
    # read of a single config flag.
    stc_presence = bool(getattr(args, "storage_commitment_presence", False))

    # P1-3: C-STORE, C-FIND, C-MOVE share the httpx.Client for connection reuse.
    # C-MOVE uses HTTP WADO-RS via httpx.Client for instance retrieval.

    # C-STORE wrapper with pynetdicom error isolation.
    # 0xC001 (CannotUnderstand) is generated by pynetdicom BEFORE our handler
    # when it fails to decode the dataset or negotiate the presentation context.
    # This wrapper catches any Exception that manages to reach our handler,
    # logging the Transfer Syntax and SOP Class UID for root cause analysis.
    def on_c_store(event):
        try:
            return handle_c_store(
                event,
                args.clarus_url,
                verbose,
                sop_index,
                max_store_bytes=(
                    args.max_store_mb * 1024 * 1024 if args.max_store_mb > 0 else 0
                ),
                http_timeout=args.http_timeout,
                sop_registry=sop_registry,
                outbox=outbox,
                health_checker=health_checker,
                store_forward=args.outbox_store_forward,
                fix_empty_patient_id=args.fix_empty_patient_id,
                fix_empty_patient_name=args.fix_empty_patient_name,
                bridge_id_prefix=args.bridge_id_prefix,
                bridge_name_prefix=args.bridge_name_prefix,
                tls=args.tls_pair,
                forward_outbox=forward_outbox,
                bridge_ae_title=args.ae_title,
            )
        except Exception:
            # Catch ALL exceptions to prevent pynetdicom association abort.
            # Log enough context to identify root cause (Transfer Syntax, SOP Class,
            # presentation context) without relying on event.dataset (may be None).
            ctx_uid = "?"
            ts_uid = "?"
            sop_uid = "?"
            try:
                ctx_uid = str(event.context.abstract_syntax) if event.context else "?"
            except Exception:
                pass
            try:
                ts_uid = str(event.context.transfer_syntax) if event.context else "?"
            except Exception:
                pass
            try:
                sop_uid = str(getattr(event.dataset, "SOPInstanceUID", "?"))
            except Exception:
                pass
            logging.error(
                "[BUG-005] C-STORE handler crashed - "
                "AbstractSyntax=%s TransferSyntax=%s SOP=%s",
                ctx_uid,
                ts_uid,
                sop_uid,
            )
            logging.debug(
                "[BUG-005] Full traceback follows:",
                exc_info=True,
            )
            return 0xC000  # Processing Failure - association survives

    def on_c_echo(event):
        return handle_c_echo(event)

    def on_c_find(event):
        yield from handle_c_find(
            event,
            args.clarus_url,
            verbose,
            args.c_find_max_responses,
            http_timeout=args.http_timeout,
            tls=args.tls_pair,
            expose_rejected=expose_rejected,
            qa_url=args.qa_url,
        )

    def on_c_move(event):
        yield from handle_c_move(
            event,
            move_jobs,
            args.peers_file,
            args.clarus_url,
            bridge_ae_title=args.ae_title,
            http_timeout=args.http_timeout,
            sop_registry=sop_registry,
            storage_commit_after_move=not args.no_storage_commit,
            sop_index=sop_index,
            outbound_network_timeout=args.outbound_network_timeout,
            outbound_dimse_timeout=args.outbound_dimse_timeout,
            outbound_acse_timeout=args.outbound_acse_timeout,
            bridge_dimse_host=args.bridge_host,
            bridge_dimse_port=args.bridge_port,
            move_poll_timeout=args.move_poll_timeout,
            tls=args.tls_pair,
            expose_rejected=expose_rejected,
            qa_url=args.qa_url,
        )

    def on_n_action(event):
        # pynetdicom 3.0.4 unpacks the EVT_N_ACTION handler's return value as a
        # `(status, dataset)` pair:
        #     usr_status, ds = cast(UserReturnType, user_response)
        # (service_class.py, _n_action_scp). `handle_n_action` is a plain
        # function that RETURNS that pair, so `yield from` here turned this
        # adapter into a GENERATOR and handed pynetdicom a generator object to
        # unpack - a Storage Commitment request could never complete. The
        # contract is a pair, so the adapter returns a pair.
        return handle_n_action(
            event,
            args.clarus_url,
            verbose,
            sop_index,
            http_timeout=args.http_timeout,
            commit_tracker=commit_tracker,
            resolve_scp=lambda ae_title, client_ip: move_jobs.lookup_scp(
                ae_title, client_ip=client_ip
            ),
            tls=args.tls_pair,
            stc_presence=stc_presence,
        )

    # MPPS (PS3.18 section 15): the two DIMSE operations that write a performed
    # procedure step are translated into the two DICOMweb transactions. Nothing
    # is answered from local state - the origin server owns the record - so the
    # handlers only need the DICOMweb base URL, the timeout and the mTLS pair.
    def on_n_create(event):
        return handle_n_create(
            event,
            args.clarus_url,
            http_timeout=args.http_timeout,
            tls=args.tls_pair,
        )

    def on_n_set(event):
        return handle_n_set(
            event,
            args.clarus_url,
            http_timeout=args.http_timeout,
            tls=args.tls_pair,
        )

    # DIMSE association lifecycle handlers.
    # Log association open/close at INFO - admin sees who connected and what they sent.
    def on_assoc_accepted(event):
        # Use id(event.assoc) as unique key - same as C-STORE handler.
        # Python object ID is unique per DICOM connection, available before negotiation.
        ae_title = "?"
        address = "?"
        assoc_id = 0
        try:
            assoc = event.assoc
            assoc_id = id(assoc)
            req = getattr(assoc, "requestor", None)
            if req is not None:
                ae = getattr(req, "ae_title", None)
                if ae and str(ae).strip():
                    ae_title = str(ae).strip()
                addr = getattr(req, "address", None)
                if addr and str(addr).strip():
                    address = str(addr).strip()
        except Exception as e:
            logging.debug("[DIMSE] Failed to extract AE/address: %s", e)
        register_assoc_accepted(assoc_id, ae_title, address)
        return 0x0000  # Always accept

    def on_assoc_released(event):
        assoc_id = 0
        try:
            assoc_id = id(event.assoc)
        except Exception:
            pass
        register_assoc_released(assoc_id)

    # T1 (21.11): PS3.8 9.3.2.2 negotiated maximum PDU length.
    #
    # The REAL bound is `GuardedDUL` (inbound_guard.py), installed at
    # EVT_CONN_OPEN: it reads the six-byte header and refuses before reading
    # the body, so an oversized P-DATA-TF never enters memory and never
    # reaches DIMSE. The EVT_PDU_RECV handler is the dispatch-level backstop
    # for a PDU that arrives by a path where no guarded provider was
    # installed.
    #
    # T3 (21.11): the calling-AE allowlist is decided in ONE place
    # (`make_calling_ae_guard`) and BOTH the warning and the A-ASSOCIATE-RJ
    # come from it. pynetdicom's own require_calling_aet is deliberately not
    # used: it compares case-sensitively, so it would refuse a peer the
    # warning reports as known.
    #
    # All three handlers come from clean_code.inbound_guard so the wire tests
    # drive the same code the bridge runs.
    handlers = [
        (evt.EVT_CONN_OPEN, install_guarded_dul),
        (
            evt.EVT_REQUESTED,
            make_calling_ae_guard(allowlist_titles),
        ),
        (evt.EVT_PDU_RECV, make_pdu_ceiling_handler()),
        (evt.EVT_C_STORE, on_c_store),
        (evt.EVT_C_ECHO, on_c_echo),
        (evt.EVT_C_FIND, on_c_find),
        (evt.EVT_C_MOVE, on_c_move),
        (evt.EVT_N_ACTION, on_n_action),
        (evt.EVT_N_CREATE, on_n_create),
        (evt.EVT_N_SET, on_n_set),
        (evt.EVT_ACCEPTED, on_assoc_accepted),
        (evt.EVT_RELEASED, on_assoc_released),
        (evt.EVT_ABORTED, on_assoc_released),  # Same cleanup as release
    ]

    return handlers

# ---------------------------------------------------------------------------
# T3: inbound calling-AE allowlist from peers.conf
# ---------------------------------------------------------------------------
def _load_calling_ae_allowlist(peers_file, enabled):
    """Distinct AE titles named in peers.conf, or [] when the knob is off.

    Read at START-UP only, and read through the same parser the C-MOVE
    destination uses (`parse_peers_conf`), so a peer is written once and both
    directions agree on what an entry means. A CIDR row names the same AE as an
    exact row, so the titles are de-duplicated.

    Start-up is deliberate: the guard is consulted while the A-ASSOCIATE-RQ is
    being negotiated, when the peer is not yet allowed to do anything, and it
    reads from a plain tuple bound into the handler. Teaching the lazyloaded
    peer table to feed it would mean mutating that tuple from the reload
    thread mid-negotiation. A peer added to peers.conf therefore takes effect
    on restart, which is the same contract the C-MOVE destination list already
    has for a NEW peer.

    No file, or a file that names nobody, yields [] - "no filter". The ARMED
    case is handled by the caller, which refuses to start: `require_known_peers`
    with an empty allowlist is a configuration hole, and pynetdicom only
    restricts Calling AE Titles when the list is non-empty, so leaving the knob
    on would read as "filtered" while nothing was filtered.
    """
    if not enabled or not peers_file:
        return []

    titles = []
    seen = set()
    for ae_title, _host, _port in parse_peers_conf(peers_file):
        key = normalise_ae_title(ae_title)
        if key and key not in seen:
            seen.add(key)
            titles.append(key)
    return titles

def _apply_calling_ae_allowlist(target_ae, args):
    """Bind the inbound calling-AE allowlist onto `target_ae`.

    Extracted from `_init_dimse_ae` so the fail-closed rule is reachable from a
    test without building a whole SCP AE.

    An armed filter (`require_known_peers=true`) with an empty allowlist is a
    startup error, not a warning: pynetdicom only restricts Calling AE Titles
    when the list is non-empty, so starting would produce an OPEN listener
    while the config and the log both read as "filtered". The explicit opt-out
    is `require_known_peers=false`.

    Returns the titles bound onto `target_ae` (empty when no filter is armed), so
    the caller can reuse them for the QA AE and the handler wiring.
    """
    _peers_file = getattr(args, "peers_file", None)
    _required = bool(getattr(args, "require_known_peers", False))
    _allowed_calling_aets = _load_calling_ae_allowlist(_peers_file, _required)
    if _allowed_calling_aets:
        target_ae.require_calling_aet = list(_allowed_calling_aets)
        logging.info(
            "[PEER] Inbound calling-AE allowlist active: %d title(s) from %s",
            len(_allowed_calling_aets),
            _peers_file,
        )
    elif _required:
        raise RuntimeError(
            f"require_known_peers is on but {_peers_file or '(no peers_file)'} "
            "lists no AE titles - refuse to start an unfiltered listener"
        )
    return _allowed_calling_aets

# ---------------------------------------------------------------------------
# SCP AE construction: contexts + handlers + shutdown monitor
# ---------------------------------------------------------------------------
def _is_addr_in_use(exc):
    """True when `exc` is a bind conflict rather than a generic start failure.

    A port already held is an OPERATOR problem (another instance, a stray
    listener) and deserves its own message; anything else is a bridge fault.
    """
    import errno

    if isinstance(exc, OSError) and getattr(exc, "errno", None) in (
        errno.EADDRINUSE,
        10048,  # WSAEADDRINUSE on Windows
    ):
        return True
    return "address already in use" in str(exc).lower()

def _init_dimse_ae(
    args,
    sop_index,
    move_jobs,
    sop_registry,
    outbox,
    health_checker,
    commit_tracker,
    forward_outbox,
):
    """Build the SCP AE(s), register contexts and handlers, start the
    shutdown monitor and the (optional) QA AE listener.

    Returns (ae, expose_ae, handlers). Kept out of main() so the caller can
    wrap it in a shutdown guard: an exception here must not leave the already
    started background threads holding the interpreter.
    """
    ae = AE(ae_title=args.ae_title)
    # P1 (2608): answer associations ONLY for our own AE title. pynetdicom
    # default is False - any Called AE Title would be accepted, which let a
    # misconfigured peers.conf loop C-MOVE back into the bridge's own SCP.
    ae.require_called_aet = True
    # T3 (21.11): calling-AE allowlist.
    #
    # The REFUSAL is pynetdicom's (`ae.require_calling_aet`): it answers with a
    # real A-ASSOCIATE-RJ through its own state machine, which is the one path
    # that actually puts the PDU on the wire.
    #
    # The COMPARISON is ours: pynetdicom compares case-sensitively
    # (acse.py:330-334), so a peer announcing `ct_room` against `CT_ROOM`
    # would be refused while a case-insensitive warning called it known.
    # `make_calling_ae_guard` folds the received title in place on
    # EVT_REQUESTED, before negotiation compares it, so one rule decides both
    # the warning and the rejection. Titles here are already folded by
    # `_load_calling_ae_allowlist`.
    #
    # The list comes from peers.conf, the SAME file the C-MOVE destination and
    # the N-EVENT requestor already resolve through, so a peer is configured in
    # one place. An armed knob with no titles is a startup error - see
    # `_apply_calling_ae_allowlist`.
    #
    # Both values are read defensively: _init_dimse_ae is also called with a
    # hand-built args object, where a missing knob must mean "no filter"
    # rather than an AttributeError that leaves the bridge unable to build its
    # AE at all.
    _allowed_calling_aets = _apply_calling_ae_allowlist(ae, args)
    # DIMSE timeouts - from config [dimse] (inbound - outbound).
    # Inbound: bridge as SCP - C-STORE from modality, C-FIND from viewer.
    # inbound_network_timeout: 0 = disabled (SCP should wait for client, ).
    # None tells pynetdicom "never kill idle associations" - viewers hold
    # associations open during C-MOVE (PS3.4 C.4.2.2), sometimes for minutes.
    ae.network_timeout = (
        args.inbound_network_timeout if args.inbound_network_timeout > 0 else None
    )
    ae.acse_timeout = args.inbound_acse_timeout
    ae.dimse_timeout = args.inbound_dimse_timeout
    # [dimse] max_associations: explicit inbound association cap.
    ae.maximum_associations = args.max_associations
    nw = ae.network_timeout
    logging.debug(
        "[DIMSE] Inbound: network=%s acse=%ds dimse=%ds",
        nw if nw is not None else "off",
        ae.acse_timeout,
        ae.dimse_timeout,
    )
    # Bridge: register supported SOP classes from YAML registry
    accepted_uids = _get_sop_registry_uids(sop_registry)

    def _register_contexts(target_ae):
        """Add every SOP class and query/retrieve context to `target_ae`.

        Shared by the ordinary AE and the Expose Rejected Instances AE: the
        second AE exposes the SAME objects with a different QIDO view, so a
        differing context set would make it answer a strictly narrower set
        of requests for no reason.
        """
        # EVRLE is proposed FIRST for image SOP classes (see the module-level
        # IMAGE_TS constant in clean_code.protocol): a native-only viewer
        # accepts the (DX, 4.70) fallback association only with EVRLE first.
        # Negotiation is acceptor-driven, so a 4.80-capable viewer still
        # negotiates 4.80 and a stored 4.80 instance sends as-is. JPEG
        # Lossless 4.57 and Baseline 4.50 are dropped from the proposal -
        # never stored, never produced, and no viewer ever selected them.
        # Non-image SOPs (SR, PR, RTSTRUCT) get uncompressed-only lists.
        _NON_IMAGE_PFX = (
            "1.2.840.10008.5.1.4.1.1.88.",
            "1.2.840.10008.5.1.4.1.1.11.",
            "1.2.840.10008.5.1.4.1.1.104.",
            "1.2.840.10008.5.1.4.1.1.66.",
        )
        _NON_IMAGE_EXACT = {
            "1.2.840.10008.5.1.4.1.1.481.3",
            "1.2.840.10008.5.1.4.1.1.481.4",
            "1.2.840.10008.5.1.4.1.1.481.5",
            "1.2.840.10008.5.1.4.1.1.481.6",
            "1.2.840.10008.5.1.4.1.1.481.7",
            "1.2.840.10008.5.1.4.1.1.481.8",
            "1.2.840.10008.5.1.4.1.1.481.9",
        }
        for sop_uid in accepted_uids:
            entry = (
                sop_registry.get(sop_uid, {}) if isinstance(sop_registry, dict) else {}
            )
            non_image = (
                bool(entry.get("non_image")) if isinstance(entry, dict) else False
            )
            if (
                non_image
                or sop_uid in _NON_IMAGE_EXACT
                or sop_uid.startswith(_NON_IMAGE_PFX)
            ):
                ts_list = NON_IMAGE_TS
            else:
                ts_list = IMAGE_TS
            # The SCP side (incoming C-STORE from viewers and modalities)
            # accepts the broad IMAGE_TS_INCOMING set - local files arrive in
            # their original TS, and a sender whose context is rejected
            # reports a failed export. The SCU proposal keeps IMAGE_TS.
            #
            # Only supported (SCP) contexts are registered here: this AE is
            # a pure SCP and never initiates an outgoing association (the
            # C-MOVE / N-EVENT / forward channels build their own AEs).
            # add_requested_context on every registry UID both lied about the
            # role and blew the 128-context UL limit for large registries,
            # killing AE construction outright.
            target_ae.add_supported_context(
                sop_uid, IMAGE_TS_INCOMING if ts_list is IMAGE_TS else NON_IMAGE_TS
            )
        target_ae.add_supported_context(
            PatientRootQueryRetrieveInformationModelFind, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            StudyRootQueryRetrieveInformationModelFind, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            ModalityWorklistInformationFind, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            StorageCommitmentPushModel, ImplicitVRLittleEndian
        )
        # PS3.4 F.7: the MPPS SOP Class is proposed with Implicit VR Little
        # Endian, the transfer syntax its data set is defined over. Without a
        # supported context an A-ASSOCIATE requesting MPPS alone is rejected
        # outright, so a modality cannot open its association at all.
        target_ae.add_supported_context(
            ModalityPerformedProcedureStep, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            StudyRootQueryRetrieveInformationModelMove, ImplicitVRLittleEndian
        )
        target_ae.add_supported_context(
            PatientRootQueryRetrieveInformationModelMove, ImplicitVRLittleEndian
        )

    _register_contexts(ae)
    logging.info(
        "Registered %d SOP classes for C-STORE (from registry)", len(accepted_uids)
    )

    # register handlers
    handlers = _register_handlers(
        args,
        sop_index,
        move_jobs,
        sop_registry,
        outbox,
        health_checker,
        commit_tracker=commit_tracker,
        forward_outbox=forward_outbox,
        allowlist_titles=_allowed_calling_aets,
    )

    # QA AE (AIRA 57.2.1 Expose Rejected Instances). A DIMSE association has
    # no per-query "show rejected" flag, so a designated AE Title is the
    # standard mechanism, and its queries go to a separately configured QA
    # webservice endpoint. It runs on its OWN port with its OWN handler set:
    # the endpoint choice is a property of the AE that accepted the
    # association, so the ordinary AE cannot inherit it.
    #
    # BOTH keys are required. A port without a URL would accept associations
    # and then query the ordinary endpoint, silently returning the hidden
    # view to a QA user; a URL without a port is dead config. Either half
    # alone is a configuration mistake, so it is reported and the second AE
    # is not started.
    expose_ae = None
    expose_handlers = None
    if args.expose_port and args.qa_url:
        expose_ae = AE(ae_title=args.expose_ae_title)
        expose_ae.require_called_aet = True
        expose_ae.network_timeout = ae.network_timeout
        expose_ae.acse_timeout = ae.acse_timeout
        expose_ae.dimse_timeout = ae.dimse_timeout
        expose_ae.maximum_associations = args.max_associations
        # The QA AE is a second inbound listener: it owes the same PDU ceiling
        # and the same calling-AE allowlist as the ordinary one, for the same
        # reasons and against the same peers.conf. Both come from the shared
        # handler list below; the allowlist titles are canonical, so the
        # EVT_REQUESTED folding applies here unchanged.
        expose_ae.require_calling_aet = list(_allowed_calling_aets)
        _register_contexts(expose_ae)
        expose_handlers = _register_handlers(
            args,
            sop_index,
            move_jobs,
            sop_registry,
            outbox,
            health_checker,
            commit_tracker=commit_tracker,
            forward_outbox=forward_outbox,
            expose_rejected=True,
            allowlist_titles=_allowed_calling_aets,
        )
    elif args.expose_port:
        logging.warning(
            "[DIMSE] [server] expose_port is set but [dicomweb] qa_url is "
            "empty - the QA AE is NOT started; the bridge stays single-AE. "
            "Set qa_url to the backend QA webservice endpoint."
        )
    elif args.qa_url:
        logging.warning(
            "[DIMSE] [dicomweb] qa_url is set but [server] expose_port is "
            "empty - the QA AE is NOT started; the bridge stays single-AE. "
            "Set expose_port to the port the QA workstation will connect to."
        )

    # - Shutdown Monitor Thread -
    # Bridges the async-signal-safe shutdown flag to pynetdicom's event loop.
    # On Windows, select() does NOT wake up on signals (no EINTR).
    # The monitor waits for _shutdown_requested in a regular thread and calls
    # ae.shutdown() - which closes the listening socket - select() wakes up
    # - start_server() returns - main thread proceeds with graceful shutdown.
    shutdown_monitor = threading.Thread(
        target=lambda: (_shutdown_requested.wait(), ae.shutdown()),
        name="shutdown-monitor",
        daemon=True,
    )
    shutdown_monitor.start()

    if expose_ae is not None:
        # Both AEs answer from their own listener thread. The expose server is
        # non-blocking so the main thread can keep serving the ordinary AE;
        # the shutdown monitor above still governs the process.
        logging.info(
            "[DIMSE] Expose Rejected Instances AE '%s' on %s:%d",
            args.expose_ae_title,
            args.bridge_host,
            args.expose_port,
        )

        # BIND the QA listener HERE, synchronously, and report the result.
        #
        # A thread that binds on its own schedule can lose the port after the
        # preflight probe and set the shutdown flag while the ordinary AE has
        # no server yet: the monitor then calls `ae.shutdown()` against an
        # empty server list, and the normal listener starts afterwards - after
        # its workers have already begun to exit. Binding in the caller makes
        # the outcome part of the return value instead of a race.
        try:
            expose_server = expose_ae.start_server(
                (args.bridge_host, args.expose_port),
                block=False,
                evt_handlers=expose_handlers,
            )
        except Exception as exc:
            # A QA listener that cannot bind is a startup failure for THAT AE.
            # It must not be silently degraded: the QA workstation would
            # connect to nothing, and the operator would read a single log line.
            if _is_addr_in_use(exc):
                logging.error(
                    "[FATAL] Expose AE cannot bind %s:%d: %s",
                    args.bridge_host,
                    args.expose_port,
                    exc,
                )
                raise RuntimeError(
                    f"Expose AE cannot bind {args.bridge_host}:{args.expose_port}"
                ) from exc
            logging.error("[DIMSE] Expose AE stopped: %s", exc)
            _shutdown_requested.set()
            raise RuntimeError("Expose AE failed to start") from exc
        if expose_server is None:
            logging.error(
                "[FATAL] Expose AE did not start on %s:%d",
                args.bridge_host,
                args.expose_port,
            )
            raise RuntimeError("Expose AE failed to start")
        logging.info("[DIMSE] Expose AE listening (bound synchronously)")

    # Bridge: register signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)
    # Windows: Ctrl+Break - graceful shutdown (SIGBREAK)
    if hasattr(signal, "SIGBREAK"):
        signal.signal(signal.SIGBREAK, _signal_handler)

    return ae, expose_ae, handlers

def _start_main_listener(ae, host, port, handlers):
    """Start the blocking DIMSE listener unless shutdown has already begun.

    Returns True when the listener was started, False when it was skipped.

    A signal that arrives after handler registration but before this point has
    already fired the shutdown monitor: it called `ae.shutdown()` while no
    server was registered, so it shut down nothing and the monitor thread is
    gone. pynetdicom 3.0.4 only stops servers that exist when `shutdown()` runs
    (ae.py), so starting a blocking listener now would serve connections with
    every worker already exiting and nothing left to stop it.
    """
    if _shutdown_requested.is_set():
        logging.warning(
            "[DIMSE] Shutdown requested before the listener started - not "
            "starting the blocking server"
        )
        return False
    ae.start_server((host, port), block=True, evt_handlers=handlers)
    return True

# ---------------------------------------------------------------------------
# Main entry point
# ---------------------------------------------------------------------------
def main():
    # - Windows: disable Quick Edit mode (console Mark mode) -
    # On Windows, clicking in a console window pauses ALL output
    # (ENABLE_QUICK_EDIT_MODE). PyInstaller .exe has no Properties dialog
    # to disable it manually, so we do it programmatically at startup.
    # Without this, a single accidental click freezes the bridge.
    if sys.platform == "win32" and sys.stdout is not None:
        try:
            kernel32 = ctypes.windll.kernel32
            ENABLE_QUICK_EDIT_MODE = 0x0040
            ENABLE_EXTENDED_FLAGS = 0x0080
            STD_INPUT_HANDLE = -10
            handle = kernel32.GetStdHandle(STD_INPUT_HANDLE)
            mode = ctypes.c_uint32()
            if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                new_mode = (
                    mode.value & ~ENABLE_QUICK_EDIT_MODE
                ) | ENABLE_EXTENDED_FLAGS
                kernel32.SetConsoleMode(handle, new_mode)
        except Exception:
            pass  # Not a console (redirected output, no-pty, etc.)

    cli = _parse_args()

    # CONFIG-DISCIPLINE: config file is the sole source of settings.
    if not os.path.exists(cli.config):
        logging.basicConfig(level=logging.INFO)
        logging.error("Config file not found: %s", cli.config)
        sys.exit(1)

    cfg = ConfParser(cli.config)

    # Validate before populating - fail fast on bad config.
    try:
        _validate_config(cfg)
    except ValueError as e:
        logging.basicConfig(level=logging.INFO)
        logging.error("%s", e)
        logging.debug("Config validation traceback:", exc_info=True)
        sys.exit(1)

    args = _populate_args(cfg)

    # - Resolve relative paths against config file directory -
    # Same as nginx: all relative paths in config are relative to the
    # config file, NOT the CWD. Makes the entire folder portable.
    _config_dir = os.path.dirname(os.path.abspath(cli.config))
    # peers_file and printers_yaml are read by the C-MOVE peer lookup and the
    # print registry; resolved from the CWD they point nowhere under a service
    # manager, and both lookups then silently return nothing.
    _path_keys = [
        "log_file",
        "sop_registry",
        "sop_index_dir",
        "outbox_dir",
        "peers_file",
        "printers_yaml",
    ]
    for key in _path_keys:
        val = getattr(args, key, None)
        if val and not os.path.isabs(val):
            setattr(args, key, os.path.join(_config_dir, val))

    # The patient-id masking key lives beside the outbox: the same directory
    # the data it labels is written to, so moving the outbox moves the
    # correlation with it. Set before the first log line that masks an id.
    set_mask_key_dir(os.path.join(args.outbox_dir, "forward"))

    # Bridge: initialize logging before any output
    _setup_logging(args.log_level, args.log_file)

    # Startup WARN: if worst-case association retry time (attempts x
    # outbound_acse_timeout) reaches into the C-MOVE poll budget, the reactor
    # could hit 0xB000 before a job finishes its association attempts. The
    # standard (PS3.8 9.1.4 Note 2) gives no retry-count guidance, so surface
    # the risk at config load - not at 0xB000 time.
    _retry_total = args.outbound_assoc_attempts * args.outbound_acse_timeout
    if args.move_poll_timeout and _retry_total >= args.move_poll_timeout:
        logging.warning(
            "[CONFIG-WARN] dimse.outbound_assoc_attempts=%d x "
            "outbound_acse_timeout=%d = %ds reaches into "
            "move_poll_timeout=%ds - a wedged target could exhaust the "
            "C-MOVE poll budget across association retries (0xB000 before "
            "delivery). Tune the attempts/timeouts down if this bites.",
            args.outbound_assoc_attempts,
            args.outbound_acse_timeout,
            _retry_total,
            args.move_poll_timeout,
        )

    # Bridge: load SOP class registry. A registry file that exists but yields
    # no usable entry is a configuration error, not a reason to fall back to
    # the built-ins (which would re-enable a class the file disables), so it
    # stops startup - with the operator-facing reason, not a traceback.
    try:
        sop_registry = _load_sop_registry(args.sop_registry)
    except RegistryConfigError as exc:
        logging.error("[STARTUP] %s", exc)
        sys.exit(1)

    # - Duplicate-instance and port checks BEFORE any component starts -
    # `_init_components` calls `move_jobs.recover_in_progress_jobs()`, which
    # resets every in-progress C-MOVE job in the shared database back to
    # pending. A second instance would therefore steal the live first
    # instance's running jobs and only afterwards discover that the ports are
    # taken - the first instance's workers then re-claim the same jobs and
    # both C-STORE them. Refusing before that write is what keeps the guard
    # free of side effects.
    _check_port_available(args.http_port, args.http_print_bind, "metrics HTTP")
    _check_port_available(args.bridge_port, args.bridge_host, "DIMSE")
    # The QA (expose) listener is a third bind of the same shape. Without this
    # a second instance sharing expose_port passed every pre-check, reset the
    # live instance's in-progress C-MOVE jobs in _init_components, and only
    # then lost its QA-AE thread - the same ordering hazard the two checks
    # above exist to prevent.
    #
    # The probe mirrors the START condition: with `qa_url` empty the QA AE is
    # never constructed and never binds the port, so a port held by an
    # unrelated process must not abort startup for a listener that is not
    # going to exist.
    if _qa_port_will_bind(args):
        _check_port_available(args.expose_port, args.bridge_host, "DIMSE QA")
    _check_dimse_unique(args.bridge_host, args.bridge_port, args.ae_title)

    # PID file: `/var/run/clbridge-{port}.pid` on Linux, next to the script
    # elsewhere, falling back to the script directory when the system
    # location is not writable. Never fatal on a write error - see
    # `_acquire_pid_file`. Named by DIMSE port so multiple bridge instances
    # on the same machine don't clash.
    _pid_path = _acquire_pid_file(args.bridge_port)
    if _pid_path:
        set_pid_path(_pid_path)

    # Exclusive STARTUP ownership, taken before any component touches the
    # database and held for the life of the process. The PID file above only
    # records; this is what makes two concurrent starts impossible.
    if not _acquire_startup_lock(args.bridge_port):
        sys.exit(1)

    # Ownership of the STATE DIRECTORY, which is a different question from
    # ownership of the DIMSE port: two instances may take different ports and
    # still share `sop_index_dir`, and `_init_components` below resets
    # in-progress C-MOVE jobs in the shared database. Taken before that call,
    # for the same reason the port lock is.
    if not _acquire_state_lock(os.path.dirname(args.sop_index_dir) or "."):
        sys.exit(1)

    # initialize components
    sop_index, move_jobs, printer_registry, driver_registry = _init_components(args)

    # - Startup summary (INFO: key params; DEBUG: tuning) -
    logging.info("clbridge v%s", VERSION)
    logging.info("[CONFIG] file: %s", cli.config)
    logging.info(
        "[DIMSE] %s:%d AE=%s", args.bridge_host, args.bridge_port, args.ae_title
    )
    logging.info("[DICOMWEB] %s", args.clarus_url)
    logging.info("[OUTBOX] dir=%s cleanup=%s", args.outbox_dir, args.outbox_cleanup)
    # The patient-id masking key is a SECRET that lives on this host's file
    # system: an operator who does not know it exists cannot back it up, and
    # restoring an outbox without it silently breaks the correlation between
    # old and new log tokens. Named here, at startup, next to the directory
    # it sits in.
    logging.info(
        "[MASK] patient-id key: %s",
        os.path.join(args.outbox_dir, "forward", ".patient_id_mask.key"),
    )
    logging.info("[SOP-INDEX] dir=%s", args.sop_index_dir)
    logging.info("[METRICS] %s:%d", args.http_print_bind, args.http_port)
    logging.info(
        "[COERCION] fix_patient_id=%s fix_patient_name=%s id_prefix=%s",
        args.fix_empty_patient_id,
        args.fix_empty_patient_name,
        args.bridge_id_prefix,
    )
    # - Tuning params (DEBUG only) -
    logging.debug(
        "[TUNING] c_find_max=%d c_move_workers=%d http_timeout=%ds "
        "stow_queue_size=%d max_assoc=%d",
        args.c_find_max_responses,
        args.c_move_workers,
        args.http_timeout,
        args.stow_queue_size,
        args.max_associations,
    )
    mx_cstore = getattr(args, "max_concurrent_cstore", None)
    logging.debug(
        "[TUNING] max_concurrent_cstore=%s",
        str(mx_cstore) if mx_cstore else "unlimited",
    )
    # - SOP registry info (DEBUG) -
    logging.debug("SOP registry: %s (%d classes)", args.sop_registry, len(sop_registry))
    mx_store = f"{args.max_store_mb} MB" if args.max_store_mb > 0 else "unlimited"
    logging.debug("C-STORE size limit: %s", mx_store)

    # start background services (HTTP server, workers, cleanup)
    #
    # This call starts NON-daemon threads - the HTTP server, the health
    # checker, the outbox and C-MOVE workers - and later steps can still raise
    # (opening commit_jobs.db, creating the forward queue). If one does, main()
    # exits with the exception while those threads keep the interpreter alive:
    # DIMSE never listens but /health keeps answering OK, so a liveness probe
    # never restarts the process. A failure here therefore exits HARD.
    try:
        (
            http_server,
            http_thread,
            cmove_thread,
            cleanup_thread,
            sop_cleanup_thread,
            outbox,
            outbox_workers,
            health_checker,
            commit_tracker,
            commit_thread,
            forward_outbox,
            forward_worker_thread,
        ) = _start_background_services(
            args,
            driver_registry,
            printer_registry,
            move_jobs,
            sop_index,
            sop_registry,
        )
    except Exception as e:
        logging.error("[FATAL] background services failed to start: %s", e)
        _shutdown_requested.set()
        os._exit(1)

    try:
        ae, expose_ae, handlers = _init_dimse_ae(
            args,
            sop_index,
            move_jobs,
            sop_registry,
            outbox,
            health_checker,
            commit_tracker,
            forward_outbox,
        )
    except BaseException:
        # A failure constructing the SCP AE / registering its handlers would
        # otherwise leave the already-started non-daemon background threads
        # (outbox / forward / commit workers) holding the interpreter: the
        # process hangs "alive but dead". Set the shutdown flag so the workers
        # drain and the HTTP server closes, then re-raise.
        _shutdown_requested.set()
        http_server.shutdown()
        raise

    logging.info("Waiting for DICOM connections...")

    try:
        # Bridge: start_server blocks, but signal handlers will trigger shutdown
        _start_main_listener(ae, args.bridge_host, args.bridge_port, handlers)
    except KeyboardInterrupt:
        # Bridge: Ctrl+C in terminal
        logging.info("KeyboardInterrupt received")
        _shutdown_requested.set()
    finally:
        # Bridge: graceful shutdown sequence
        logging.info("Shutting down DICOM server...")
        if not _shutdown_requested.is_set():
            _shutdown_requested.set()

        # Bridge: allow in-flight operations to complete (30s grace period)
        logging.info("Waiting up to 30s for in-flight operations to complete...")
        ae.shutdown()  # Idempotent - monitor may have already called it
        if expose_ae is not None:
            # The QA listener was bound synchronously in `_init_dimse_ae`; a
            # non-blocking server is closed through its own shutdown.
            try:
                expose_ae.shutdown()
            except Exception:
                pass
        logging.info("DICOM server stopped")

        # Bridge: stop HTTP server - before joining threads
        http_server.shutdown()
        logging.info("[HTTP] Bridge server stopped")

        # - stop the producers before draining their queues -
        # The outbox workers exit on `_shutdown_requested`, so joining them
        # FIRST lets each one push its tail batch. Draining and then closing
        # the queue while a worker was still alive made `mark_delivered` /
        # `mark_failed` run against a closed queue, which turned a delivered
        # instance into a logged error.
        _fwd = [forward_worker_thread] if forward_worker_thread is not None else []
        for t in list(outbox_workers) + _fwd:
            if t.is_alive():
                logging.info("[SHUTDOWN] Waiting for thread %s (up to 30s)...", t.name)
                t.join(timeout=30.0)
                if t.is_alive():
                    logging.warning("[SHUTDOWN] Thread %s did not stop in time", t.name)

        # Bridge: drain outbox (graceful shutdown), then close the queues.
        # The forward queue exists only with `[forward] enabled=true`; the
        # default leaves it None and an unguarded close aborts the whole
        # shutdown sequence on the way out.
        _drain_outbox(outbox)
        if forward_outbox is not None:
            forward_outbox.close()

        # Stop the async Storage Commitment resolver.
        commit_tracker.close()

        # - join the remaining background threads -
        # Join C-MOVE workers FIRST - they use move_jobs DB which must stay open.
        _all_threads = [
            cmove_thread,
            cleanup_thread,
            sop_cleanup_thread,
            http_thread,
            commit_thread,
        ]
        for t in _all_threads:
            if t.is_alive():
                logging.info("[SHUTDOWN] Waiting for thread %s (up to 30s)...", t.name)
                t.join(timeout=30.0)
                if t.is_alive():
                    logging.warning("[SHUTDOWN] Thread %s did not stop in time", t.name)

        # Bridge: cleanup resources AFTER threads are done
        sop_index.close()
        move_jobs.close()

        # clean up PID file in normal shutdown sequence
        # (NOT in signal handler - unsafe on Windows)
        if _pid_path and os.path.exists(_pid_path):
            try:
                os.unlink(_pid_path)
                logging.info("Removed PID file %s", _pid_path)
            except OSError:
                pass

        logging.info("Bridge shutdown complete")

if __name__ == "__main__":
    main()

